  last_login_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  created_by_org_id uuid,
  invited_by uuid,
  profile_confirmed_at timestamp with time zone
);
ALTER TABLE public.supplier_portal_users ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.supplier_portal_users IS 'Portal do fornecedor F3.1: utilizador do portal (conta Auth sem anew_users). owner = primeiro convidado da conta; só o owner escreve no catálogo.';
COMMENT ON COLUMN public.supplier_portal_users.profile_confirmed_at IS 'Portal do fornecedor: quando o utilizador (owner) confirmou os dados da empresa no primeiro acesso. NULL = por confirmar.';

CREATE TABLE IF NOT EXISTS public.supplier_price_change_requests (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  organization_id uuid NOT NULL,
  link_id uuid NOT NULL,
  supplier_id uuid NOT NULL,
  catalog_item_id uuid NOT NULL,
  item_supplier_id uuid NOT NULL,
  product_id uuid,
  uom_id uuid,
  old_price numeric(12,2),
  old_currency text,
  new_price numeric(12,2) NOT NULL,
  currency text NOT NULL,
  catalog_old_price numeric(14,4),
  catalog_new_price numeric(14,4) NOT NULL,
  old_unit_label text,
  unit_label text,
  old_units_per_pack numeric(14,4),
  units_per_pack numeric(14,4),
  unit_changed boolean DEFAULT false NOT NULL,
  status text DEFAULT 'pending'::text NOT NULL,
  batch_id uuid NOT NULL,
  requested_at timestamp with time zone DEFAULT now() NOT NULL,
  requested_by_portal_user uuid,
  superseded_at timestamp with time zone,
  superseded_batch_id uuid,
  superseded_by uuid,
  decided_at timestamp with time zone,
  decided_by uuid,
  decision_note text,
  result jsonb,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE public.supplier_price_change_requests ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.supplier_price_change_requests IS 'Portal do fornecedor F3.4b: pedido de alteração de preço nascido de uma mudança no catálogo do fornecedor num artigo ligado (item_suppliers.catalog_item_id). Aceitar atualiza item_suppliers.purchase_price e, se a ligação é a preferencial, o custo do produto (product_prices purchase). Escrita só pelo gatilho e por rpc_price_changes_decide.';

