ALTER TABLE public.warehouses ADD COLUMN IF NOT EXISTS is_vehicle boolean DEFAULT false NOT NULL;
COMMENT ON COLUMN public.warehouses.is_vehicle IS 'Armazém móvel (carrinha da Frota, fleet_vehicles.warehouse_id). Nunca serve clientes (CHECK warehouses_vehicle_not_serving): fica fora da reserva FIFO e das saídas das encomendas de cliente. O stock conta no valor do inventário.';

