CASE
    WHEN (tipo IS NULL) THEN ((resposta IS NOT NULL) AND (pergunta_texto IS NULL) AND (seccao_titulo IS NULL) AND (bloco IS NULL) AND (ordem IS NULL) AND (escolhas IS NULL) AND (escolhas_texto IS NULL) AND (valor_texto IS NULL) AND (valor_numero IS NULL))
    WHEN ((pergunta_texto IS NULL) OR (seccao_titulo IS NULL) OR (ordem IS NULL)) THEN false
    WHEN (tipo = 'escolha_unica'::text) THEN ((escolhas IS NOT NULL) AND (escolhas_texto IS NOT NULL) AND (array_ndims(escolhas) = 1) AND (cardinality(escolhas) = 1) AND (array_ndims(escolhas_texto) = 1) AND (cardinality(escolhas_texto) = 1) AND (escolhas[1] IS NOT NULL) AND (escolhas_texto[1] IS NOT NULL) AND (resposta IS NOT NULL) AND (resposta = escolhas[1]) AND (valor_texto IS NULL) AND (valor_numero IS NULL))
    WHEN (tipo = 'escolha_multipla'::text) THEN ((escolhas IS NOT NULL) AND (escolhas_texto IS NOT NULL) AND (array_ndims(escolhas) = 1) AND ((cardinality(escolhas) >= 1) AND (cardinality(escolhas) <= 30)) AND (array_ndims(escolhas_texto) = 1) AND (cardinality(escolhas_texto) = cardinality(escolhas)) AND (array_position(escolhas, NULL::text) IS NULL) AND (array_position(escolhas_texto, NULL::text) IS NULL) AND (resposta IS NULL) AND (valor_texto IS NULL) AND (valor_numero IS NULL))
    WHEN (tipo = 'texto'::text) THEN ((valor_texto IS NOT NULL) AND (resposta IS NULL) AND (escolhas IS NULL) AND (escolhas_texto IS NULL) AND (valor_numero IS NULL))
    WHEN (tipo = 'numero'::text) THEN ((valor_numero IS NOT NULL) AND (resposta IS NULL) AND (escolhas IS NULL) AND (escolhas_texto IS NULL) AND (valor_texto IS NULL))
    ELSE false
END, false));
  END IF;
