-- 5. Funcoes novas ---------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_anew_memberships_block_supplier_internal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_auth uuid;
BEGIN
  -- Cliente: permitido. Calculado aqui (não depende da ordem do gatilho que
  -- preenche role_is_client). Papel inexistente/NULL conta como interno.
  IF COALESCE((SELECT r.code = 'client' FROM public.anew_roles r WHERE r.id = NEW.role_id), false) THEN
    RETURN NEW;
  END IF;
  SELECT u.auth_user_id INTO v_auth FROM public.anew_users u WHERE u.id = NEW.user_id;
  IF v_auth IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sp_internal:' || v_auth::text, 0));
  IF EXISTS (SELECT 1 FROM public.supplier_portal_users s WHERE s.auth_user_id = v_auth) THEN
    RAISE EXCEPTION 'Esta conta é do portal do fornecedor e não pode ser usada no CRM'
      USING ERRCODE = 'check_violation', HINT = 'supplier_account';
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_anew_memberships_block_supplier_internal() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_anew_memberships_block_supplier_internal() TO service_role;
COMMENT ON FUNCTION public.fn_anew_memberships_block_supplier_internal() IS 'Portal do Fornecedor: uma conta Auth com supplier_portal_users não pode ter membership ativa não-cliente (pode ser cliente).';

CREATE OR REPLACE FUNCTION public.fn_anew_users_block_supplier_accounts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.auth_user_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('sp_internal:' || NEW.auth_user_id::text, 0));
    IF EXISTS (SELECT 1 FROM public.supplier_portal_users s WHERE s.auth_user_id = NEW.auth_user_id)
       AND EXISTS (SELECT 1 FROM public.anew_memberships m
                   WHERE m.user_id = NEW.id AND m.status = 'active' AND m.role_is_client IS NOT TRUE) THEN
      RAISE EXCEPTION 'Esta conta é do portal do fornecedor e não pode ser usada no CRM'
        USING ERRCODE = 'check_violation', HINT = 'supplier_account';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_anew_users_block_supplier_accounts() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_anew_users_block_supplier_accounts() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_apply_product_cost_from_supplier(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_plan    jsonb := public.fn_price_change_cost_plan(p_item_supplier_id, p_organization_id, p_new_price, p_currency);
  v_product uuid;
  v_unit    numeric;
  v_rows    integer := 0;
  v_upd     boolean := false;
BEGIN
  IF (v_plan ->> 'will_update')::boolean THEN
    SELECT product_id INTO v_product FROM public.item_suppliers WHERE id = p_item_supplier_id;
    v_unit := (v_plan ->> 'new_unit_cost')::numeric;
    UPDATE public.product_prices
       SET price = v_unit, created_by = p_actor
     WHERE product_id = v_product AND price_type = 'purchase'
       AND currency::text = p_currency AND price IS DISTINCT FROM v_unit;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF NOT EXISTS (SELECT 1 FROM public.product_prices
                   WHERE product_id = v_product AND price_type = 'purchase') THEN
      INSERT INTO public.product_prices (product_id, price_type, price, currency, vat_rate, created_by)
      VALUES (v_product, 'purchase', v_unit, p_currency::public.currency_code,
              COALESCE((SELECT pp.vat_rate FROM public.product_prices pp
                        WHERE pp.product_id = v_product AND pp.vat_rate IS NOT NULL
                        ORDER BY pp.updated_at DESC LIMIT 1), 23),
              p_actor);
      v_rows := 1;
    END IF;
    v_upd := true;
  END IF;

  RETURN jsonb_build_object(
    'product_cost_updated', v_upd,
    'product_cost_rows', v_rows,
    'product_cost_reason', v_plan ->> 'reason',
    'product_cost_message', v_plan ->> 'message',
    'new_unit_cost', CASE WHEN v_upd THEN v_unit END,
    'units_per_purchase_uom', (v_plan ->> 'units_per_purchase_uom')::integer);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_apply_product_cost_from_supplier(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text, p_actor uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_apply_product_cost_from_supplier(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text, p_actor uuid) TO service_role;
COMMENT ON FUNCTION public.fn_apply_product_cost_from_supplier(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text, p_actor uuid) IS 'Portal do fornecedor F3.4b: aplica ao custo do produto (product_prices purchase) o preço de uma ligação item_suppliers, se fn_price_change_cost_plan o permitir. Usada por rpc_price_changes_decide e rpc_catalog_link.';

CREATE OR REPLACE FUNCTION public.fn_can_manage_form(_form_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.forms f
     WHERE f.id = _form_id
       AND (
         public.is_system_admin_user(auth.uid())
         OR (
           f.organization_id IN (SELECT public.get_user_visible_org_ids(auth.uid()))
           AND (
                public.has_anew_permission(auth.uid(), 'forms.create')
             OR public.has_anew_permission(auth.uid(), 'forms.edit')
             OR public.has_anew_permission(auth.uid(), 'forms.delete')
             OR public.has_anew_permission(auth.uid(), 'campaigns.create')
             OR public.has_anew_permission(auth.uid(), 'campaigns.edit')
             OR public.has_anew_permission(auth.uid(), 'campaigns.delete')
           )
         )
       )
  )
$function$;
REVOKE ALL ON FUNCTION public.fn_can_manage_form(_form_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_form(_form_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_form(_form_id uuid) TO service_role;
COMMENT ON FUNCTION public.fn_can_manage_form(_form_id uuid) IS 'Portal do fornecedor F3.0: escrita em form_steps/form_fields/form_districts. System admin, ou org do formulário visível + forms.* ou campaigns.* (create/edit/delete).';

CREATE OR REPLACE FUNCTION public.fn_can_manage_user_template(_template_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    SELECT public.fn_can_manage_user_template_org(t.organization_id)
      FROM public.user_creation_templates t
     WHERE t.id = _template_id
  ), false)
$function$;
REVOKE ALL ON FUNCTION public.fn_can_manage_user_template(_template_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_user_template(_template_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_user_template(_template_id uuid) TO service_role;
COMMENT ON FUNCTION public.fn_can_manage_user_template(_template_id uuid) IS 'Portal do fornecedor F3.0: escrita em user_template_fields/_attributes/_organizations, pela regra do modelo.';

CREATE OR REPLACE FUNCTION public.fn_can_manage_user_template_org(_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.is_system_admin_user(auth.uid())
    OR (
      (
        (_org_id IS NULL AND public.fn_is_internal_crm_user())
        OR _org_id IN (SELECT public.get_user_visible_org_ids(auth.uid()))
      )
      AND (
           public.has_anew_permission(auth.uid(), 'users.create')
        OR public.has_anew_permission(auth.uid(), 'users.edit')
      )
    )
$function$;
REVOKE ALL ON FUNCTION public.fn_can_manage_user_template_org(_org_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_user_template_org(_org_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_can_manage_user_template_org(_org_id uuid) TO service_role;
COMMENT ON FUNCTION public.fn_can_manage_user_template_org(_org_id uuid) IS 'Portal do fornecedor F3.0: escrita em user_creation_templates. System admin, ou membro interno (org visível; NULL = global) com users.create/users.edit.';

CREATE OR REPLACE FUNCTION public.fn_catalog_parse_number(p_value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  s text := regexp_replace(COALESCE(p_value, ''), '[\s€' || chr(160) || ']', '', 'g');
BEGIN
  IF s = '' THEN
    RETURN NULL;
  END IF;
  IF s ~ '^[+-]?[0-9]+$' THEN
    RETURN s::numeric;
  ELSIF s ~ '^[+-]?[0-9]*[\.,][0-9]+$' THEN
    RETURN replace(s, ',', '.')::numeric;
  ELSIF s ~ '^[+-]?[0-9]{1,3}(\.[0-9]{3})+(,[0-9]+)?$' THEN
    RETURN replace(replace(s, '.', ''), ',', '.')::numeric;
  ELSIF s ~ '^[+-]?[0-9]{1,3}(,[0-9]{3})+(\.[0-9]+)?$' THEN
    RETURN replace(s, ',', '')::numeric;
  ELSIF s ~ '^[+-]?[0-9]+(\.[0-9]+)?[eE][+-]?[0-9]{1,3}$' THEN
    RETURN s::numeric;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_catalog_parse_number(p_value text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_catalog_parse_number(p_value text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_catalog_parse_number(p_value text) TO service_role;
COMMENT ON FUNCTION public.fn_catalog_parse_number(p_value text) IS 'Portal do fornecedor F3.1: lê um número de uma célula de Excel/CSV (vírgula ou ponto decimal, separador de milhares, €). Inválido → NULL.';

CREATE OR REPLACE FUNCTION public.fn_delivery_note_scope(p_delivery_note_id uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT array_agg(o.purchase_order_id ORDER BY o.purchase_order_id)
  FROM public.supplier_delivery_note_orders o
  WHERE o.delivery_note_id = p_delivery_note_id;
$function$;
REVOKE ALL ON FUNCTION public.fn_delivery_note_scope(p_delivery_note_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_delivery_note_scope(p_delivery_note_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_delivery_note_summary(p_delivery_note_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_note      public.supplier_delivery_notes%ROWTYPE;
  v_scope     uuid[];
  v_has_lines boolean;
  v_products  jsonb;
  v_receipts  jsonb;
BEGIN
  SELECT * INTO v_note FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_scope := public.fn_delivery_note_scope(p_delivery_note_id);
  v_has_lines := EXISTS (SELECT 1 FROM public.supplier_delivery_note_lines WHERE delivery_note_id = p_delivery_note_id);

  WITH ann AS (
    SELECT l.product_id, sum(l.quantity * l.units_per_uom) AS units
    FROM public.supplier_delivery_note_lines l
    WHERE l.delivery_note_id = p_delivery_note_id
    GROUP BY l.product_id
  ), rcv AS (
    SELECT COALESCE(pr.product_id, poi.product_id) AS product_id,
           sum(pr.quantity * pr.units_per_uom) AS units
    FROM public.purchase_order_receipts pr
    LEFT JOIN public.purchase_order_items poi ON poi.id = pr.purchase_order_item_id
    WHERE pr.delivery_note_id = p_delivery_note_id
      AND pr.kind = 'receipt'
      AND pr.reverted_at IS NULL
    GROUP BY 1
  ), ordered AS (
    -- Produtos com alguma linha nas POs do âmbito (qualquer estado).
    SELECT DISTINCT poi.product_id
    FROM public.purchase_order_items poi
    JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    WHERE po.organization_id = v_note.organization_id
      AND po.deleted_at IS NULL
      AND poi.item_type = 'product'
      AND poi.product_id IS NOT NULL
      AND (CASE WHEN v_scope IS NULL THEN po.supplier_id = v_note.supplier_id
                ELSE po.id = ANY (v_scope) END)
  ), x AS (
    SELECT COALESCE(a.product_id, r.product_id) AS product_id,
           COALESCE(a.units, 0) AS announced,
           COALESCE(r.units, 0) AS received,
           (o.product_id IS NOT NULL) AS on_order
    FROM ann a
    FULL JOIN rcv r ON r.product_id = a.product_id
    LEFT JOIN ordered o ON o.product_id = COALESCE(a.product_id, r.product_id)
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'product_id',       x.product_id,
           'name',             p.name,
           'sku',              p.sku,
           'announced_units',  trim_scale(x.announced),
           'received_units',   trim_scale(x.received),
           'missing_units',    trim_scale(GREATEST(0, x.announced - x.received)),
           'excess_units',     trim_scale(CASE WHEN x.announced > 0 THEN GREATEST(0, x.received - x.announced) ELSE 0 END),
           'on_order',         x.on_order,
           'status',           s.status,
           'divergent',        (v_has_lines AND s.status <> 'ok')
         ) ORDER BY p.name, x.product_id), '[]'::jsonb)
  INTO v_products
  FROM x
  LEFT JOIN public.products p ON p.id = x.product_id
  CROSS JOIN LATERAL (
    SELECT CASE
      WHEN NOT v_has_lines                                  THEN 'recebido'
      WHEN x.announced = 0                                  THEN 'nao_anunciado'
      WHEN x.received = 0 AND NOT x.on_order                THEN 'nao_encomendado'
      WHEN x.received < x.announced                         THEN 'falta'
      WHEN x.received > x.announced                         THEN 'excesso'
      ELSE 'ok'
    END AS status
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id',                     pr.id,
           'purchase_order_id',      pr.purchase_order_id,
           'order_number',           po.order_number,
           'purchase_order_item_id', pr.purchase_order_item_id,
           'product_id',             COALESCE(pr.product_id, poi.product_id),
           'product_name',           p.name,
           'quantity',               pr.quantity,
           'units_per_uom',          pr.units_per_uom,
           'units',                  pr.quantity * pr.units_per_uom,
           'units_to_order',         pr.units_to_order,
           'units_to_stock',         pr.units_to_stock,
           'contract_id',            pr.contract_id,
           'warehouse_id',           pr.warehouse_id,
           'receiving_scan_id',      pr.receiving_scan_id,
           'received_at',            pr.received_at,
           'received_by',            pr.received_by,
           'reverted',               pr.reverted_at IS NOT NULL,
           'reverted_at',            pr.reverted_at,
           'revert_reason',          pr.revert_reason
         ) ORDER BY pr.received_at, pr.id), '[]'::jsonb)
  INTO v_receipts
  FROM public.purchase_order_receipts pr
  JOIN public.purchase_orders po ON po.id = pr.purchase_order_id
  LEFT JOIN public.purchase_order_items poi ON poi.id = pr.purchase_order_item_id
  LEFT JOIN public.products p ON p.id = COALESCE(pr.product_id, poi.product_id)
  WHERE pr.delivery_note_id = p_delivery_note_id
    AND pr.kind = 'receipt';

  RETURN jsonb_build_object(
    'has_lines',       v_has_lines,
    'products',        v_products,
    'receipts',        v_receipts,
    'totals', jsonb_build_object(
      'announced_units',   (SELECT COALESCE(sum((e ->> 'announced_units')::numeric), 0) FROM jsonb_array_elements(v_products) e),
      'received_units',    (SELECT COALESCE(sum((e ->> 'received_units')::numeric), 0) FROM jsonb_array_elements(v_products) e),
      'missing_units',     (SELECT COALESCE(sum((e ->> 'missing_units')::numeric), 0) FROM jsonb_array_elements(v_products) e),
      'excess_units',      (SELECT COALESCE(sum((e ->> 'excess_units')::numeric), 0) FROM jsonb_array_elements(v_products) e),
      'products',          jsonb_array_length(v_products),
      'divergences',       (SELECT count(*) FROM jsonb_array_elements(v_products) e WHERE (e ->> 'divergent')::boolean),
      'active_receipts',   (SELECT count(*) FROM jsonb_array_elements(v_receipts) e WHERE NOT (e ->> 'reverted')::boolean),
      'reverted_receipts', (SELECT count(*) FROM jsonb_array_elements(v_receipts) e WHERE (e ->> 'reverted')::boolean)
    ),
    'has_divergences', EXISTS (SELECT 1 FROM jsonb_array_elements(v_products) e WHERE (e ->> 'divergent')::boolean)
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_delivery_note_summary(p_delivery_note_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_delivery_note_summary(p_delivery_note_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_add_working_days(p_organization_id uuid, p_from date, p_days integer)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d date := p_from;
  n integer := 0;
BEGIN
  WHILE n < GREATEST(p_days, 0) LOOP
    d := d + 1;
    IF extract(isodow FROM d) < 6 AND NOT EXISTS (
         SELECT 1 FROM public.schedule_holidays h
         WHERE h.organization_id = p_organization_id
           AND (h.holiday_date = d
                OR (COALESCE(h.is_recurring, false) AND to_char(h.holiday_date, 'MM-DD') = to_char(d, 'MM-DD')))) THEN
      n := n + 1;
    END IF;
  END LOOP;
  RETURN d;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_add_working_days(p_organization_id uuid, p_from date, p_days integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_add_working_days(p_organization_id uuid, p_from date, p_days integer) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_assert(p_organization_id uuid, p_permissions text[], p_self_vehicle_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF public.current_business_user_id() IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_permissions) AS p(code) WHERE public.fn_fleet_can(p_organization_id, p.code)) THEN
    RETURN;
  END IF;
  IF p_self_vehicle_id IS NOT NULL
     AND public.fn_fleet_can(p_organization_id, 'fleet.self')
     AND public.fn_fleet_is_my_vehicle(p_self_vehicle_id) THEN
    RETURN;
  END IF;
  RAISE EXCEPTION 'Sem permissão para esta ação na Frota.' USING ERRCODE = 'insufficient_privilege';
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_assert(p_organization_id uuid, p_permissions text[], p_self_vehicle_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_assert(p_organization_id uuid, p_permissions text[], p_self_vehicle_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_assert(p_organization_id uuid, p_permissions text[], p_self_vehicle_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_assignment_at(p_vehicle_id uuid, p_on date)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT a.id
  FROM public.fleet_assignments a
  WHERE a.vehicle_id = p_vehicle_id
    AND a.cancelled_at IS NULL
    AND a.starts_on <= p_on
    AND (a.ends_on IS NULL OR a.ends_on > p_on OR (a.ends_on = p_on AND a.returned_on IS NULL))
  ORDER BY a.starts_on DESC
  LIMIT 1
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_assignment_at(p_vehicle_id uuid, p_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_assignment_at(p_vehicle_id uuid, p_on date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_assignment_at(p_vehicle_id uuid, p_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_board(p_organization_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('fleet_board:' || p_organization_id::text));
  SELECT b.id INTO v_id
  FROM public.schedule_boards b
  WHERE b.organization_id = p_organization_id AND b.board_type = 'fleet'
  ORDER BY b.created_at
  LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO public.schedule_boards (organization_id, name, name_key, description, board_type, is_system_board, is_active, color, created_by)
    VALUES (p_organization_id, 'Frota', 'fleet.boardName', 'Reservas e manutenções das viaturas (geridas na Frota).',
            'fleet', true, true, '#64748b', public.current_business_user_id())
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_board(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_board(p_organization_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_can(p_organization_id uuid, p_permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT (SELECT auth.uid()) IS NOT NULL
     AND p_organization_id IS NOT NULL
     AND p_organization_id IN (SELECT public.get_user_visible_org_ids((SELECT auth.uid())))
     AND public.has_anew_permission((SELECT auth.uid()), p_permission)
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_can(p_organization_id uuid, p_permission text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_can(p_organization_id uuid, p_permission text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_can(p_organization_id uuid, p_permission text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_cost_per_km(p_organization_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_from date := COALESCE(p_from, current_date - 90);
  v_to   date := COALESCE(p_to, current_date);
  v_km   numeric;
  v_cost numeric;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.get_user_visible_org_ids((SELECT auth.uid()))) THEN
    RAISE EXCEPTION 'Sem acesso a esta organização.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  WITH km AS (
    SELECT r.vehicle_id, max(r.km) - min(r.km) AS km
    FROM public.fleet_odometer_readings r
    JOIN public.fleet_vehicles v ON v.id = r.vehicle_id
    WHERE r.organization_id = p_organization_id
      AND r.read_on BETWEEN v_from AND v_to
      AND NOT r.is_flagged
      AND v.deleted_at IS NULL AND v.status NOT IN ('inactive', 'sold')
      AND (p_vehicle_id IS NULL OR r.vehicle_id = p_vehicle_id)
    GROUP BY r.vehicle_id
  ), cost AS (
    -- Decisão 9: só custos variáveis com o uso. Ficam de fora os fixos
    -- (seguro, IUC, renda, inspeção) e as multas.
    SELECT e.vehicle_id, sum(e.amount) AS amount
    FROM public.fleet_expenses e
    WHERE e.organization_id = p_organization_id
      AND e.spent_on BETWEEN v_from AND v_to
      AND NOT e.needs_review
      AND e.category IN ('fuel', 'charging', 'tolls', 'parking', 'washing', 'workshop', 'other')
      AND e.vehicle_id IN (SELECT km.vehicle_id FROM km)
    GROUP BY e.vehicle_id
  )
  SELECT sum(km.km), sum(COALESCE(cost.amount, 0)) INTO v_km, v_cost
  FROM km LEFT JOIN cost ON cost.vehicle_id = km.vehicle_id;

  IF p_vehicle_id IS NOT NULL AND (v_km IS NULL OR v_km <= 0) THEN
    RETURN public.fn_fleet_cost_per_km(p_organization_id, NULL, p_from, p_to);  -- média da frota
  END IF;
  IF v_km IS NULL OR v_km <= 0 OR v_cost IS NULL OR v_cost <= 0 THEN
    RETURN 0.40;  -- os 0,40 €/km de sempre (sugestaoFichaLocal.ts, km_eur)
  END IF;
  RETURN round(v_cost / v_km, 4);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_cost_per_km(p_organization_id uuid, p_vehicle_id uuid, p_from date, p_to date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_cost_per_km(p_organization_id uuid, p_vehicle_id uuid, p_from date, p_to date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_cost_per_km(p_organization_id uuid, p_vehicle_id uuid, p_from date, p_to date) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_daily_alerts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_n    integer := 0;
  v_rows integer;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _fleet_alerts (
    organization_id uuid, type text, entity_type text, entity_id uuid, priority text,
    title text, message text, link text, data jsonb, driver_user uuid
  ) ON COMMIT DROP;
  TRUNCATE _fleet_alerts;

  WITH orgs AS (
    SELECT DISTINCT organization_id FROM public.fleet_vehicles WHERE deleted_at IS NULL
  ), cfg AS (
    SELECT o.organization_id,
           COALESCE(s_doc.is_active, true) AS doc_on,  COALESCE(s_doc.days_threshold, 30) AS doc_days,
           COALESCE(s_srv.is_active, true) AS srv_on,  COALESCE(s_srv.days_threshold, 30) AS srv_days,
           COALESCE(s_fin.is_active, true) AS fin_on,  COALESCE(s_fin.days_threshold, 5)  AS fin_days,
           COALESCE(s_lic.is_active, true) AS lic_on,  COALESCE(s_lic.days_threshold, 60) AS lic_days
    FROM orgs o
    LEFT JOIN public.alert_settings s_doc ON s_doc.organization_id = o.organization_id AND s_doc.alert_type = 'fleet_document_due' AND s_doc.kind = 'alert'
    LEFT JOIN public.alert_settings s_srv ON s_srv.organization_id = o.organization_id AND s_srv.alert_type = 'fleet_service_due' AND s_srv.kind = 'alert'
    LEFT JOIN public.alert_settings s_fin ON s_fin.organization_id = o.organization_id AND s_fin.alert_type = 'fleet_fine_deadline' AND s_fin.kind = 'alert'
    LEFT JOIN public.alert_settings s_lic ON s_lic.organization_id = o.organization_id AND s_lic.alert_type = 'fleet_licence_expiring' AND s_lic.kind = 'alert'
  )
  INSERT INTO _fleet_alerts
  -- vencimentos
  SELECT c.organization_id, 'fleet_document_due', 'fleet_compliance', c.id,
         CASE WHEN c.valid_until < current_date THEN 'high' ELSE 'medium' END,
         'Documento da viatura a vencer',
         format('%s da %s: %s %s.',
                CASE c.kind WHEN 'insurance' THEN 'Seguro' WHEN 'inspection' THEN 'Inspeção (IPO)' WHEN 'road_tax' THEN 'IUC'
                            WHEN 'lease_contract' THEN 'Fim do contrato' ELSE 'Documento' END,
                v.plate, CASE WHEN c.valid_until < current_date THEN 'venceu a' ELSE 'vence a' END, to_char(c.valid_until, 'DD/MM/YYYY')),
         '/frota/documentos', jsonb_build_object('vehicle_id', v.id, 'kind', c.kind, 'valid_until', c.valid_until), NULL::uuid
  FROM public.fleet_compliance c
  JOIN public.fleet_vehicles v ON v.id = c.vehicle_id
  JOIN cfg ON cfg.organization_id = c.organization_id
  WHERE cfg.doc_on AND c.is_current AND NOT c.is_exempt
    AND v.deleted_at IS NULL AND v.status NOT IN ('inactive', 'sold')
    AND c.valid_until <= current_date + cfg.doc_days
  UNION ALL
  -- revisões (km ou data, o que chegar primeiro), sem revisão já marcada
  SELECT p.organization_id, 'fleet_service_due', 'fleet_vehicle', v.id, 'medium',
         'Revisão a fazer',
         format('A %s precisa de revisão (próxima aos %s km ou a %s).', v.plate, p.last_km + p.every_km,
                to_char((p.last_done_on + make_interval(months => p.every_months))::date, 'DD/MM/YYYY')),
         '/frota/manutencao', jsonb_build_object('vehicle_id', v.id), NULL::uuid
  FROM public.fleet_maintenance_plans p
  JOIN public.fleet_vehicles v ON v.id = p.vehicle_id
  JOIN cfg ON cfg.organization_id = p.organization_id
  WHERE cfg.srv_on AND p.is_active AND p.kind = 'service'
    AND v.deleted_at IS NULL AND v.status NOT IN ('inactive', 'sold')
    AND ((p.every_km IS NOT NULL AND p.last_km IS NOT NULL AND v.odometer_km >= p.last_km + p.every_km - 3000)
      OR (p.every_months IS NOT NULL AND p.last_done_on IS NOT NULL
          AND (p.last_done_on + make_interval(months => p.every_months))::date <= current_date + cfg.srv_days))
    AND NOT EXISTS (SELECT 1 FROM public.fleet_maintenance_events m
                    WHERE m.vehicle_id = v.id AND m.kind = 'service' AND m.status IN ('scheduled', 'in_progress'))
  UNION ALL
  -- multas por identificar perto do prazo
  SELECT i.organization_id, 'fleet_fine_deadline', 'fleet_incident', i.id,
         CASE WHEN i.identify_by <= current_date + 2 THEN 'high' ELSE 'medium' END,
         'Multa por identificar',
         format('Multa da %s: identifica o condutor até %s.', v.plate, to_char(i.identify_by, 'DD/MM/YYYY')),
         '/frota/ocorrencias', jsonb_build_object('vehicle_id', v.id, 'identify_by', i.identify_by), NULL::uuid
  FROM public.fleet_incidents i
  JOIN public.fleet_vehicles v ON v.id = i.vehicle_id
  JOIN cfg ON cfg.organization_id = i.organization_id
  WHERE cfg.fin_on AND i.kind = 'fine' AND i.status = 'to_identify' AND i.identify_by <= current_date + cfg.fin_days
  UNION ALL
  -- cartas a caducar
  SELECT d.organization_id, 'fleet_licence_expiring', 'fleet_driver', d.id,
         CASE WHEN d.licence_expires_on < current_date THEN 'high' ELSE 'medium' END,
         'Carta de condução a caducar',
         format('A carta de %s %s a %s.', d.full_name,
                CASE WHEN d.licence_expires_on < current_date THEN 'caducou' ELSE 'caduca' END, to_char(d.licence_expires_on, 'DD/MM/YYYY')),
         '/frota/condutores', jsonb_build_object('driver_id', d.id), au.auth_user_id
  FROM public.fleet_drivers d
  JOIN cfg ON cfg.organization_id = d.organization_id
  LEFT JOIN public.anew_users au ON au.id = d.user_id AND au.deleted_at IS NULL
  WHERE cfg.lic_on AND d.is_active AND d.deleted_at IS NULL
    AND d.licence_expires_on IS NOT NULL AND d.licence_expires_on <= current_date + cfg.lic_days;

  WITH recipients AS (
    SELECT DISTINCT am.organization_id, au.auth_user_id
    FROM public.anew_memberships am
    JOIN public.anew_users au ON au.id = am.user_id
    JOIN public.anew_role_permissions rp ON rp.role_id = am.role_id AND rp.permission_code = 'fleet.manage'
    WHERE am.status = 'active' AND am.role_is_client IS NOT TRUE
      AND au.auth_user_id IS NOT NULL AND au.deleted_at IS NULL
  ), targets AS (
    SELECT r.auth_user_id AS user_id, a.* FROM _fleet_alerts a JOIN recipients r ON r.organization_id = a.organization_id
    UNION
    SELECT a.driver_user, a.* FROM _fleet_alerts a WHERE a.driver_user IS NOT NULL
  )
  INSERT INTO public.notifications (user_id, organization_id, kind, type, entity_type, entity_id, title, message, priority, link, data)
  SELECT t.user_id, t.organization_id, 'alert', t.type, t.entity_type, t.entity_id, t.title, t.message, t.priority, t.link, t.data
  FROM targets t
  WHERE NOT EXISTS (
    SELECT 1 FROM public.notifications n
    WHERE n.user_id = t.user_id AND n.type = t.type AND n.entity_id = t.entity_id
      AND n.is_resolved = false AND n.is_dismissed = false
      AND n.created_at > now() - interval '7 days');
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_n := v_rows;
  RETURN v_n;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_daily_alerts() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_daily_alerts() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_is_my_vehicle(p_vehicle_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.fleet_assignments a
    WHERE a.id = public.fn_fleet_assignment_at(p_vehicle_id, current_date)
      AND a.driver_id IN (SELECT public.fn_fleet_my_driver_ids())
  )
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_is_my_vehicle(p_vehicle_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_is_my_vehicle(p_vehicle_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_is_my_vehicle(p_vehicle_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_licence_problem(p_driver_id uuid, p_required text, p_on date)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN d.id IS NULL THEN 'Condutor desconhecido.'
    WHEN COALESCE(cardinality(d.licence_categories), 0) = 0
      THEN format('%s não tem carta de condução registada.', d.full_name)
    WHEN d.licence_expires_on IS NOT NULL AND d.licence_expires_on < p_on
      THEN format('A carta de %s caducou a %s.', d.full_name, to_char(d.licence_expires_on, 'DD/MM/YYYY'))
    WHEN NOT (p_required = ANY (d.licence_categories))
      THEN format('%s não tem a categoria %s.', d.full_name, p_required)
  END
  FROM (SELECT 1) AS x
  LEFT JOIN public.fleet_drivers d ON d.id = p_driver_id AND d.deleted_at IS NULL
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_licence_problem(p_driver_id uuid, p_required text, p_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_licence_problem(p_driver_id uuid, p_required text, p_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_log(p_organization_id uuid, p_vehicle_id uuid, p_action text, p_summary text, p_detail text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  INSERT INTO public.fleet_activity_log (organization_id, vehicle_id, action, summary, detail, entity_type, entity_id, actor_id, actor_name)
  SELECT p_organization_id, p_vehicle_id, p_action, p_summary, p_detail, p_entity_type, p_entity_id, u.id, u.name
  FROM (SELECT public.current_business_user_id() AS bid) b
  LEFT JOIN public.anew_users u ON u.id = b.bid
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_log(p_organization_id uuid, p_vehicle_id uuid, p_action text, p_summary text, p_detail text, p_entity_type text, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_log(p_organization_id uuid, p_vehicle_id uuid, p_action text, p_summary text, p_detail text, p_entity_type text, p_entity_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_my_driver_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT d.id
  FROM public.fleet_drivers d
  WHERE d.user_id = public.current_business_user_id()
    AND d.deleted_at IS NULL
    AND d.is_active
    AND d.organization_id IN (SELECT public.get_user_visible_org_ids((SELECT auth.uid())))
    AND public.has_anew_permission((SELECT auth.uid()), 'fleet.self')
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_my_driver_ids() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_my_driver_ids() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_my_driver_ids() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_my_vehicle_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT DISTINCT a.vehicle_id
  FROM public.fleet_assignments a
  WHERE a.driver_id IN (SELECT public.fn_fleet_my_driver_ids())
    AND a.cancelled_at IS NULL
    AND a.returned_on IS NULL
    AND (a.ends_on IS NULL OR a.ends_on >= current_date)
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_my_vehicle_ids() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_my_vehicle_ids() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_my_vehicle_ids() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_next_inspection(p_category text, p_first_registration_on date, p_done_on date)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_years integer;
  v_due   date;
BEGIN
  IF p_done_on IS NULL THEN
    RETURN NULL;
  END IF;
  IF p_first_registration_on IS NULL OR p_category IS NULL OR p_category NOT IN ('light_passenger', 'light_goods') THEN
    RETURN (p_done_on + interval '12 months')::date;
  END IF;
  v_years := CASE WHEN p_category = 'light_passenger' THEN 4 ELSE 2 END;
  LOOP
    v_due := (p_first_registration_on + make_interval(years => v_years))::date;
    EXIT WHEN v_due > (p_done_on + interval '3 months')::date;
    v_years := v_years + CASE WHEN p_category = 'light_passenger' AND v_years < 8 THEN 2 ELSE 1 END;
  END LOOP;
  RETURN v_due;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_next_inspection(p_category text, p_first_registration_on date, p_done_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_next_inspection(p_category text, p_first_registration_on date, p_done_on date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_fleet_next_inspection(p_category text, p_first_registration_on date, p_done_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_sync_schedule_item(p_vehicle_id uuid, p_item_id uuid, p_title text, p_from date, p_to date, p_status schedule_item_status, p_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_res   uuid;
  v_org   uuid;
  v_item  uuid := p_item_id;
  v_start timestamptz := (p_from::timestamp AT TIME ZONE 'Europe/Lisbon');
  -- Fim dentro do proprio ultimo dia (23:59 local), como a Agenda guarda os
  -- itens de dia inteiro. Terminar as 00:00 do dia seguinte fazia o gatilho
  -- de feriados contar esse dia e recusar a vespera de um feriado.
  v_end   timestamptz := ((COALESCE(p_to, p_from) + time '23:59') AT TIME ZONE 'Europe/Lisbon');
BEGIN
  SELECT v.schedule_resource_id, v.organization_id INTO v_res, v_org
  FROM public.fleet_vehicles v WHERE v.id = p_vehicle_id;

  IF v_item IS NULL THEN
    IF v_res IS NULL THEN
      RETURN NULL;
    END IF;
    INSERT INTO public.schedule_items (board_id, title, status, origin, start_datetime, end_datetime, all_day,
                                       organization_id, created_by, user_id, metadata)
    VALUES (public.fn_fleet_board(v_org), p_title, p_status, 'manual', v_start, v_end, true,
            v_org, public.current_business_user_id(), p_user_id,
            COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('source', 'fleet', 'fleet_vehicle_id', p_vehicle_id))
    RETURNING id INTO v_item;
    INSERT INTO public.schedule_item_assignees (item_id, resource_id, role)
    VALUES (v_item, v_res, 'vehicle')
    ON CONFLICT (item_id, resource_id) DO NOTHING;
  ELSE
    UPDATE public.schedule_items
       SET title = COALESCE(p_title, title),
           status = p_status,
           start_datetime = v_start,
           end_datetime = v_end,
           metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('source', 'fleet', 'fleet_vehicle_id', p_vehicle_id)
     WHERE id = v_item;
  END IF;
  RETURN v_item;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_sync_schedule_item(p_vehicle_id uuid, p_item_id uuid, p_title text, p_from date, p_to date, p_status schedule_item_status, p_user_id uuid, p_metadata jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_sync_schedule_item(p_vehicle_id uuid, p_item_id uuid, p_title text, p_from date, p_to date, p_status schedule_item_status, p_user_id uuid, p_metadata jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_fleet_vehicle_blockers(p_vehicle_id uuid, p_from date, p_to date, p_exclude_assignment_id uuid DEFAULT NULL::uuid, p_exclude_event_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(kind text, ref_id uuid, label text, from_on date, to_on date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT 'temporary', a.id, d.full_name, a.starts_on, a.ends_on
  FROM public.fleet_assignments a
  JOIN public.fleet_drivers d ON d.id = a.driver_id
  WHERE a.vehicle_id = p_vehicle_id AND a.kind = 'temporary'
    AND a.cancelled_at IS NULL AND a.returned_on IS NULL
    AND a.starts_on <= p_to AND a.ends_on >= p_from
    AND (p_exclude_assignment_id IS NULL OR a.id <> p_exclude_assignment_id)
  UNION ALL
  SELECT 'maintenance', m.id, m.title, m.scheduled_on, COALESCE(m.expected_end_on, m.scheduled_on)
  FROM public.fleet_maintenance_events m
  WHERE m.vehicle_id = p_vehicle_id AND m.status IN ('scheduled', 'in_progress')
    AND m.scheduled_on <= p_to AND COALESCE(m.expected_end_on, m.scheduled_on) >= p_from
    AND (p_exclude_event_id IS NULL OR m.id <> p_exclude_event_id)
  UNION ALL
  SELECT 'workshop', v.id, COALESCE(v.status_reason, 'Oficina'), GREATEST(p_from, current_date), p_to
  FROM public.fleet_vehicles v
  WHERE v.id = p_vehicle_id AND v.status = 'workshop' AND p_to >= current_date
  UNION ALL
  SELECT 'agenda', si.id, si.title, (si.start_datetime AT TIME ZONE 'Europe/Lisbon')::date,
         ((si.end_datetime - interval '1 microsecond') AT TIME ZONE 'Europe/Lisbon')::date
  FROM public.fleet_vehicles v
  JOIN public.schedule_item_assignees sia ON sia.resource_id = v.schedule_resource_id
  JOIN public.schedule_items si ON si.id = sia.item_id
  WHERE v.id = p_vehicle_id
    AND si.status <> 'cancelled'
    AND COALESCE(si.metadata ->> 'source', '') <> 'fleet'
    AND si.start_datetime < ((p_to + 1)::timestamp AT TIME ZONE 'Europe/Lisbon')
    AND si.end_datetime > (p_from::timestamp AT TIME ZONE 'Europe/Lisbon')
$function$;
REVOKE ALL ON FUNCTION public.fn_fleet_vehicle_blockers(p_vehicle_id uuid, p_from date, p_to date, p_exclude_assignment_id uuid, p_exclude_event_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_fleet_vehicle_blockers(p_vehicle_id uuid, p_from date, p_to date, p_exclude_assignment_id uuid, p_exclude_event_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_gravar_ficha_edificio(p_address_id uuid, p_actor uuid, p_gravar_exterior boolean, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_gravar_interior boolean, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ext   boolean := COALESCE(p_gravar_exterior, false);
  v_int   boolean := COALESCE(p_gravar_interior, false);
  v_notas text    := nullif(btrim(COALESCE(p_notas_interior, '')), '');
BEGIN
  IF NOT v_ext AND NOT v_int THEN
    RETURN;
  END IF;

  INSERT INTO public.anew_address_building AS b (
    address_id,
    acesso, impacto_percent, estacionamento, zona_estacionamento,
    tem_elevador, n_elevadores, n_andares, n_fracoes_por_andar,
    tipologia, area_util_m2, n_divisoes, n_casas_banho, ano_construcao, pavimento,
    eletrica, quadro_diferencial, canalizacao, gas, amianto, habitada_durante_obra,
    animais, notas_interior,
    created_by, updated_by
  ) VALUES (
    p_address_id,
    CASE WHEN v_ext THEN p_acesso END,
    CASE WHEN v_ext THEN p_impacto_percent END,
    CASE WHEN v_ext THEN p_estacionamento END,
    CASE WHEN v_ext THEN p_zona_estacionamento END,
    CASE WHEN v_ext THEN p_tem_elevador END,
    CASE WHEN v_ext THEN p_n_elevadores END,
    CASE WHEN v_ext THEN p_n_andares END,
    CASE WHEN v_ext THEN p_n_fracoes_por_andar END,
    CASE WHEN v_int THEN p_tipologia END,
    CASE WHEN v_int THEN p_area_util_m2 END,
    CASE WHEN v_int THEN p_n_divisoes END,
    CASE WHEN v_int THEN p_n_casas_banho END,
    CASE WHEN v_int THEN p_ano_construcao END,
    CASE WHEN v_int THEN p_pavimento END,
    CASE WHEN v_int THEN p_eletrica END,
    CASE WHEN v_int THEN p_quadro_diferencial END,
    CASE WHEN v_int THEN p_canalizacao END,
    CASE WHEN v_int THEN p_gas END,
    CASE WHEN v_int THEN p_amianto END,
    CASE WHEN v_int THEN p_habitada_durante_obra END,
    CASE WHEN v_int THEN p_animais END,
    CASE WHEN v_int THEN v_notas END,
    p_actor, p_actor
  )
  ON CONFLICT (address_id) DO UPDATE SET
    acesso                = CASE WHEN v_ext THEN EXCLUDED.acesso                ELSE b.acesso END,
    impacto_percent       = CASE WHEN v_ext THEN EXCLUDED.impacto_percent       ELSE b.impacto_percent END,
    estacionamento        = CASE WHEN v_ext THEN EXCLUDED.estacionamento        ELSE b.estacionamento END,
    zona_estacionamento   = CASE WHEN v_ext THEN EXCLUDED.zona_estacionamento   ELSE b.zona_estacionamento END,
    tem_elevador          = CASE WHEN v_ext THEN EXCLUDED.tem_elevador          ELSE b.tem_elevador END,
    n_elevadores          = CASE WHEN v_ext THEN EXCLUDED.n_elevadores          ELSE b.n_elevadores END,
    n_andares             = CASE WHEN v_ext THEN EXCLUDED.n_andares             ELSE b.n_andares END,
    n_fracoes_por_andar   = CASE WHEN v_ext THEN EXCLUDED.n_fracoes_por_andar   ELSE b.n_fracoes_por_andar END,
    tipologia             = CASE WHEN v_int THEN EXCLUDED.tipologia             ELSE b.tipologia END,
    area_util_m2          = CASE WHEN v_int THEN EXCLUDED.area_util_m2          ELSE b.area_util_m2 END,
    n_divisoes            = CASE WHEN v_int THEN EXCLUDED.n_divisoes            ELSE b.n_divisoes END,
    n_casas_banho         = CASE WHEN v_int THEN EXCLUDED.n_casas_banho         ELSE b.n_casas_banho END,
    ano_construcao        = CASE WHEN v_int THEN EXCLUDED.ano_construcao        ELSE b.ano_construcao END,
    pavimento             = CASE WHEN v_int THEN EXCLUDED.pavimento             ELSE b.pavimento END,
    eletrica              = CASE WHEN v_int THEN EXCLUDED.eletrica              ELSE b.eletrica END,
    quadro_diferencial    = CASE WHEN v_int THEN EXCLUDED.quadro_diferencial    ELSE b.quadro_diferencial END,
    canalizacao           = CASE WHEN v_int THEN EXCLUDED.canalizacao           ELSE b.canalizacao END,
    gas                   = CASE WHEN v_int THEN EXCLUDED.gas                   ELSE b.gas END,
    amianto               = CASE WHEN v_int THEN EXCLUDED.amianto               ELSE b.amianto END,
    habitada_durante_obra = CASE WHEN v_int THEN EXCLUDED.habitada_durante_obra ELSE b.habitada_durante_obra END,
    animais               = CASE WHEN v_int THEN EXCLUDED.animais               ELSE b.animais END,
    notas_interior        = CASE WHEN v_int THEN EXCLUDED.notas_interior        ELSE b.notas_interior END,
    updated_at            = now(),
    updated_by            = EXCLUDED.updated_by;

  -- Ficha toda vazia => sem linha (como antes: tudo NULL = apagar).
  DELETE FROM public.anew_address_building b
  WHERE b.address_id = p_address_id
    AND b.acesso IS NULL AND b.impacto_percent IS NULL AND b.estacionamento IS NULL
    AND b.zona_estacionamento IS NULL AND b.tem_elevador IS NULL AND b.n_elevadores IS NULL
    AND b.n_andares IS NULL AND b.n_fracoes_por_andar IS NULL
    AND b.tipologia IS NULL AND b.area_util_m2 IS NULL AND b.n_divisoes IS NULL
    AND b.n_casas_banho IS NULL AND b.ano_construcao IS NULL AND b.pavimento IS NULL
    AND b.eletrica IS NULL AND b.quadro_diferencial IS NULL AND b.canalizacao IS NULL
    AND b.gas IS NULL AND b.amianto IS NULL AND b.habitada_durante_obra IS NULL
    AND b.animais IS NULL AND b.notas_interior IS NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_gravar_ficha_edificio(p_address_id uuid, p_actor uuid, p_gravar_exterior boolean, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_gravar_interior boolean, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_gravar_ficha_edificio(p_address_id uuid, p_actor uuid, p_gravar_exterior boolean, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_gravar_interior boolean, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_is_internal_crm_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.anew_users u
      JOIN public.anew_memberships m ON m.user_id = u.id
     WHERE u.auth_user_id = auth.uid()
       AND m.status = 'active'
       AND m.role_is_client IS NOT TRUE
  )
$function$;
REVOKE ALL ON FUNCTION public.fn_is_internal_crm_user() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_is_internal_crm_user() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_is_internal_crm_user() TO service_role;
COMMENT ON FUNCTION public.fn_is_internal_crm_user() IS 'Portal do fornecedor F3.0: true se quem chama tem um vínculo ativo que não é de cliente (equivalente a get_user_visible_org_ids não vazio).';

CREATE OR REPLACE FUNCTION public.fn_item_suppliers_catalog_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
     AND NEW.catalog_item_id IS NOT NULL AND NEW.catalog_item_id IS NOT DISTINCT FROM OLD.catalog_item_id THEN
    NEW.catalog_item_id := NULL;
  END IF;

  IF current_user IN ('authenticated', 'anon') THEN
    IF (TG_OP = 'INSERT' AND NEW.catalog_item_id IS NOT NULL)
       OR (TG_OP = 'UPDATE' AND NEW.catalog_item_id IS DISTINCT FROM OLD.catalog_item_id
           AND NEW.catalog_item_id IS NOT NULL) THEN
      RAISE EXCEPTION 'A ligação ao catálogo do fornecedor só pode ser feita pelo painel do catálogo'
        USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_item_suppliers_catalog_guard() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_item_suppliers_catalog_guard() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamento_config_guardar()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_n jsonb := to_jsonb(NEW);
  v_o jsonb := to_jsonb(OLD);
BEGIN
  IF (v_n ->> 'organization_id') IS DISTINCT FROM (v_o ->> 'organization_id')
     OR (v_n ->> 'id') IS DISTINCT FROM (v_o ->> 'id')
     OR (v_n ->> 'chave') IS DISTINCT FROM (v_o ->> 'chave')
     OR (v_n ->> 'aba') IS DISTINCT FROM (v_o ->> 'aba')
     OR (v_n ->> 'especial') IS DISTINCT FROM (v_o ->> 'especial')
     OR (v_n ->> 'pergunta_id') IS DISTINCT FROM (v_o ->> 'pergunta_id') THEN
    RAISE EXCEPTION 'Não é possível mudar a organização, o identificador, a chave, a aba ou a pergunta de um elemento do questionário.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (v_o ->> 'apagada_em') IS NOT NULL
     AND (v_n ->> 'apagada_em') IS DISTINCT FROM (v_o ->> 'apagada_em') THEN
    RAISE EXCEPTION 'Um elemento apagado do questionário não volta; crie outro.'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.created_at := OLD.created_at;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamento_config_guardar() FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamento_filhos_pai(p_levantamento_id uuid, p_apagar boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org     uuid;
  v_negocio uuid;
  v_lixo    timestamptz;
BEGIN
  -- 1. Organização do pai, SEM bloquear, só para a guarda.
  SELECT l.organization_id INTO v_org
  FROM public.levantamentos l
  WHERE l.id = p_levantamento_id;

  IF NOT FOUND THEN
    -- DELETE em cascata: o pai já foi apagado; deixa passar.
    IF p_apagar THEN
      RETURN NULL;
    END IF;
    RAISE EXCEPTION 'Levantamento indisponível.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. Guarda de organização (mesma mensagem que "não existe").
  PERFORM public.fn_levantamentos_exigir_organizacao(v_org);

  -- 3. Só agora o FOR SHARE (nunca sobre linhas de outra organização).
  SELECT l.organization_id, l.negocio_id, l.deleted_at
    INTO v_org, v_negocio, v_lixo
  FROM public.levantamentos l
  WHERE l.id = p_levantamento_id
  FOR SHARE;

  IF NOT FOUND THEN
    IF p_apagar THEN
      RETURN NULL;
    END IF;
    RAISE EXCEPTION 'Levantamento indisponível.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_negocio IS NOT NULL THEN
    RAISE EXCEPTION 'Este levantamento já está ligado a um negócio e não se altera; registe um novo.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_lixo IS NOT NULL THEN
    RAISE EXCEPTION 'Este levantamento está no lixo: tem de ser restaurado antes de ser alterado.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN v_org;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamento_filhos_pai(p_levantamento_id uuid, p_apagar boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamento_filhos_pai(p_levantamento_id uuid, p_apagar boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamento_linhas_guardar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_levantamento_filhos_pai(OLD.levantamento_id, true);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Primeiro o pai (guarda de organização, ligado, lixo).
    PERFORM public.fn_levantamento_filhos_pai(OLD.levantamento_id, false);
    IF NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'Não é possível mudar o identificador de uma linha do levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.levantamento_id IS DISTINCT FROM OLD.levantamento_id THEN
      RAISE EXCEPTION 'Não é possível passar uma linha para outro levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'Não é possível mudar a organização de uma linha do levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := OLD.created_at;
    RETURN NEW;
  END IF;

  -- INSERT: a organização é a do pai, ignorando o que o cliente mande.
  NEW.organization_id := public.fn_levantamento_filhos_pai(NEW.levantamento_id, false);
  NEW.created_at := now();
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamento_linhas_guardar() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamento_linhas_guardar() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamento_respostas_guardar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_levantamento_filhos_pai(OLD.levantamento_id, true);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Primeiro o pai (guarda de organização, ligado, lixo).
    PERFORM public.fn_levantamento_filhos_pai(OLD.levantamento_id, false);
    IF NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'Não é possível mudar o identificador de uma resposta do levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.levantamento_id IS DISTINCT FROM OLD.levantamento_id THEN
      RAISE EXCEPTION 'Não é possível passar uma resposta para outro levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'Não é possível mudar a organização de uma resposta do levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.pergunta IS DISTINCT FROM OLD.pergunta THEN
      RAISE EXCEPTION 'Não é possível mudar a pergunta de uma resposta; apague-a e registe outra.'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := OLD.created_at;
    RETURN NEW;
  END IF;

  -- INSERT: a organização é a do pai, ignorando o que o cliente mande.
  NEW.organization_id := public.fn_levantamento_filhos_pai(NEW.levantamento_id, false);
  NEW.created_at := now();
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamento_respostas_guardar() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamento_respostas_guardar() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_exigir_organizacao(p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_role     text := coalesce(current_setting('role', true), '');
  v_jwt_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
BEGIN
  IF v_uid IS NULL THEN
    IF v_role IN ('authenticated', 'anon') OR v_jwt_role IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Levantamento indisponível.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN;
  END IF;

  IF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.get_user_crm_org_ids(v_uid)) THEN
    RAISE EXCEPTION 'Levantamento indisponível.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_exigir_organizacao(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_exigir_organizacao(p_organization_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_exigir_permissao_lixo(p_organization_id uuid, p_feito_por uuid, p_created_by uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_role     text := coalesce(current_setting('role', true), '');
  v_jwt_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
BEGIN
  IF v_uid IS NULL THEN
    IF v_role IN ('authenticated', 'anon') OR v_jwt_role IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Sessão sem utilizador: não é possível enviar este levantamento para o lixo nem restaurá-lo.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN;
  END IF;

  IF NOT (
    public.has_anew_permission(v_uid, 'pessoas.delete')
    AND EXISTS (
      SELECT 1
      FROM unnest(public.crm_scope_keys('pessoas.delete')) AS k(scope_key)
      WHERE k.scope_key = p_organization_id::text || ':*'
         OR k.scope_key = p_organization_id::text || ':' || p_feito_por::text
         OR k.scope_key = p_organization_id::text || ':' || p_created_by::text
    )
  ) THEN
    RAISE EXCEPTION 'Sem permissão para enviar este levantamento para o lixo ou para o restaurar (pessoas.delete).'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_exigir_permissao_lixo(p_organization_id uuid, p_feito_por uuid, p_created_by uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_exigir_permissao_lixo(p_organization_id uuid, p_feito_por uuid, p_created_by uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_guardar_alteracao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_limpa_visita   boolean := public.fn_levantamentos_ref_desaparecida('schedule_items', OLD.visita_id, NEW.visita_id);
  v_limpa_negocio  boolean := public.fn_levantamentos_ref_desaparecida('negocios', OLD.negocio_id, NEW.negocio_id);
  v_limpa_criador  boolean := public.fn_negocios_ref_utilizador_apagado(OLD.created_by, NEW.created_by);
  v_limpa_autor    boolean := public.fn_negocios_ref_utilizador_apagado(OLD.feito_por, NEW.feito_por);
  v_limpa_apagador boolean := public.fn_negocios_ref_utilizador_apagado(OLD.deleted_by, NEW.deleted_by);
  v_ignorar        text[]  := ARRAY['updated_at'];
BEGIN
  -- 1. Imutáveis (created_by só pode ir a NULL se o utilizador foi apagado)
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'Não é possível mudar o identificador de um levantamento.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'Não é possível mudar a organização de um levantamento.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.entity_id IS DISTINCT FROM OLD.entity_id THEN
    RAISE EXCEPTION 'Não é possível mudar a pessoa de um levantamento.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by AND NOT v_limpa_criador THEN
    RAISE EXCEPTION 'Não é possível mudar quem criou um levantamento.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 2. UPDATE interno das chaves estrangeiras ON DELETE SET NULL: passa
  --    sempre (ligado ou no lixo), desde que nada mais mude.
  IF v_limpa_visita   THEN v_ignorar := v_ignorar || 'visita_id'::text;  END IF;
  IF v_limpa_negocio  THEN v_ignorar := v_ignorar || 'negocio_id'::text; END IF;
  IF v_limpa_criador  THEN v_ignorar := v_ignorar || 'created_by'::text; END IF;
  IF v_limpa_autor    THEN v_ignorar := v_ignorar || 'feito_por'::text;  END IF;
  IF v_limpa_apagador THEN v_ignorar := v_ignorar || 'deleted_by'::text; END IF;

  IF cardinality(v_ignorar) > 1
     AND (to_jsonb(NEW) - v_ignorar) = (to_jsonb(OLD) - v_ignorar) THEN
    RETURN NEW;
  END IF;

  -- 3. Ligado a um negócio: congelado (D3). Inclui desligar e trocar.
  IF OLD.negocio_id IS NOT NULL
     AND (to_jsonb(NEW) - 'updated_at'::text) IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at'::text) THEN
    RAISE EXCEPTION 'Este levantamento já está ligado a um negócio e não se altera; registe um novo.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 4. No lixo: só o restauro (deleted_at volta a NULL).
  IF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NOT NULL
     AND (to_jsonb(NEW) - 'updated_at'::text) IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at'::text) THEN
    RAISE EXCEPTION 'Este levantamento está no lixo: tem de ser restaurado antes de ser alterado.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 5. Ligações que mudaram para um valor (negocio_id aqui só de NULL para
  --    valor: o ligado já foi recusado no passo 3). É aqui que se liga a um
  --    negócio (CRIAR, PREENCHER, LIGAR), com a guarda de organização, o
  --    acesso de pessoas.edit ao negócio e a serialização por negócio.
  PERFORM public.fn_levantamentos_validar_ligacoes(
    NEW.organization_id, NEW.entity_id,
    CASE WHEN NEW.feito_por  IS DISTINCT FROM OLD.feito_por  THEN NEW.feito_por  END,
    CASE WHEN NEW.visita_id  IS DISTINCT FROM OLD.visita_id  THEN NEW.visita_id  END,
    CASE WHEN NEW.negocio_id IS DISTINCT FROM OLD.negocio_id THEN NEW.negocio_id END);

  -- 6. Fixos
  NEW.root_organization_id := OLD.root_organization_id;
  NEW.created_at := OLD.created_at;

  -- 7. Lixo: só a passagem vivo <-> lixo conta; o valor é sempre da base.
  IF (OLD.deleted_at IS NULL) IS DISTINCT FROM (NEW.deleted_at IS NULL) THEN
    PERFORM public.fn_levantamentos_exigir_permissao_lixo(
      OLD.organization_id, OLD.feito_por, OLD.created_by);

    IF NEW.deleted_at IS NOT NULL THEN
      NEW.deleted_at := now();
      NEW.deleted_by := public.fn_negocios_actor();
    ELSE
      NEW.deleted_by := NULL;
    END IF;
  ELSE
    NEW.deleted_at := OLD.deleted_at;
    NEW.deleted_by := CASE WHEN v_limpa_apagador THEN NULL ELSE OLD.deleted_by END;
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_guardar_alteracao() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_guardar_alteracao() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_preparar_insercao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_feito_por_dado uuid := NEW.feito_por;
BEGIN
  -- Guarda de organização antes de qualquer leitura (mensagem genérica).
  PERFORM public.fn_levantamentos_exigir_organizacao(NEW.organization_id);

  -- CRIAR, PREENCHER, LIGAR: nasce sempre por ligar. Um INSERT já ligado
  -- ficaria congelado e vazio (os filhos são recusados) e ocuparia o lugar
  -- único do negócio.
  IF NEW.negocio_id IS NOT NULL THEN
    RAISE EXCEPTION 'Um levantamento não se cria já ligado a um negócio: grave-o primeiro (com as medidas e respostas) e ligue-o depois.'
      USING ERRCODE = 'check_violation';
  END IF;

  NEW.root_organization_id := public.resolve_root_organization_id(NEW.organization_id);

  IF NEW.created_by IS NULL THEN
    NEW.created_by := public.fn_negocios_actor();
  END IF;
  IF NEW.feito_por IS NULL THEN
    NEW.feito_por := NEW.created_by;
  END IF;

  NEW.created_at := now();
  NEW.updated_at := now();
  NEW.deleted_at := NULL;
  NEW.deleted_by := NULL;

  -- feito_por só é validado aqui se veio do cliente (o derivado de
  -- created_by é validado pela política de INSERT).
  PERFORM public.fn_levantamentos_validar_ligacoes(
    NEW.organization_id, NEW.entity_id,
    v_feito_por_dado, NEW.visita_id, NULL::uuid);

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_preparar_insercao() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_preparar_insercao() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_ref_desaparecida(p_tabela text, p_antigo uuid, p_novo uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_antigo IS NULL OR p_novo IS NOT NULL THEN
    RETURN false;
  END IF;

  CASE p_tabela
    WHEN 'schedule_items' THEN
      RETURN NOT EXISTS (SELECT 1 FROM public.schedule_items s WHERE s.id = p_antigo);
    WHEN 'negocios' THEN
      RETURN NOT EXISTS (SELECT 1 FROM public.negocios n WHERE n.id = p_antigo);
    ELSE
      RAISE EXCEPTION 'fn_levantamentos_ref_desaparecida: tabela não suportada (%)', p_tabela;
  END CASE;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_ref_desaparecida(p_tabela text, p_antigo uuid, p_novo uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_ref_desaparecida(p_tabela text, p_antigo uuid, p_novo uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_levantamentos_validar_ligacoes(p_organization_id uuid, p_entity_id uuid, p_feito_por uuid, p_visita_id uuid, p_negocio_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_visita record;
BEGIN
  -- Guarda de organização antes de qualquer leitura (mensagem genérica).
  PERFORM public.fn_levantamentos_exigir_organizacao(p_organization_id);

  IF p_feito_por IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.anew_memberships m
    WHERE m.user_id = p_feito_por
      AND m.organization_id = p_organization_id
      AND m.status = 'active'
      AND m.role_is_client IS NOT TRUE
  ) THEN
    RAISE EXCEPTION 'Quem fez o levantamento tem de ser membro activo da organização.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_visita_id IS NOT NULL THEN
    SELECT s.organization_id, s.lead_id, s.contact_id, s.deal_id, s.client_id,
           s.time_off_type, s.vacation_id
      INTO v_visita
    FROM public.schedule_items s
    WHERE s.id = p_visita_id;

    IF NOT FOUND OR v_visita.organization_id IS DISTINCT FROM p_organization_id THEN
      RAISE EXCEPTION 'A visita indicada não existe nesta organização.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF v_visita.lead_id IS NOT NULL THEN
      -- Com lead, o lead tem de ser da pessoa do levantamento.
      IF NOT EXISTS (
        SELECT 1 FROM public.anew_leads l
        WHERE l.id = v_visita.lead_id
          AND l.entity_id = p_entity_id
      ) THEN
        RAISE EXCEPTION 'A visita indicada é de outra pessoa.'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSIF v_visita.client_id IS NOT NULL
          AND v_visita.time_off_type IS NULL
          AND v_visita.vacation_id IS NULL
          AND EXISTS (
            SELECT 1 FROM public.anew_clients c
            WHERE c.id = v_visita.client_id
              AND c.entity_id = p_entity_id
              AND c.organization_id = p_organization_id
          ) THEN
      -- Visita sem lead de um cliente que é esta pessoa: aceite.
      NULL;
    ELSIF v_visita.contact_id IS NOT NULL
       OR v_visita.deal_id IS NOT NULL
       OR v_visita.client_id IS NOT NULL
       OR v_visita.time_off_type IS NOT NULL
       OR v_visita.vacation_id IS NOT NULL THEN
      -- D5: sem lead só se aceita uma visita "solta" (sem contacto, negócio,
      -- cliente, ausência nem férias): nunca uma folga, umas férias ou uma
      -- reunião de outra pessoa.
      RAISE EXCEPTION 'A visita indicada é de outra pessoa ou não é uma visita.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF p_negocio_id IS NOT NULL THEN
    -- Negócio vivo, da mesma organização e pessoa e, com sessão, com
    -- pessoas.edit de quem liga sobre esse negócio (espelha negocios_update:
    -- chave org:*, org:assigned_to ou org:created_by). Uma só mensagem para
    -- "não existe", "é de outra pessoa", "está no lixo" e "sem acesso".
    IF NOT EXISTS (
      SELECT 1 FROM public.negocios n
      WHERE n.id = p_negocio_id
        AND n.organization_id = p_organization_id
        AND n.entity_id = p_entity_id
        AND n.deleted_at IS NULL
        AND (
          v_uid IS NULL
          OR (
            public.has_anew_permission(v_uid, 'pessoas.edit')
            AND EXISTS (
              SELECT 1
              FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
              WHERE k.scope_key = n.organization_id::text || ':*'
                 OR k.scope_key = n.organization_id::text || ':' || n.assigned_to::text
                 OR k.scope_key = n.organization_id::text || ':' || n.created_by::text
            )
          )
        )
    ) THEN
      RAISE EXCEPTION 'O negócio indicado não está disponível para ligar a este levantamento.'
        USING ERRCODE = 'check_violation';
    END IF;

    -- Serializa as ligações ao mesmo negócio: a segunda espera pelo fim da
    -- primeira e, com um snapshot novo, vê-a. Assim "já tem levantamento"
    -- dá esta mensagem e não o erro 23505 do UNIQUE (que mostraria o uuid).
    PERFORM pg_advisory_xact_lock(
      hashtextextended('levantamentos.negocio_id:' || p_negocio_id::text, 0));
    IF EXISTS (
      SELECT 1 FROM public.levantamentos l
      WHERE l.negocio_id = p_negocio_id
    ) THEN
      RAISE EXCEPTION 'Este negócio já tem um levantamento ligado.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_levantamentos_validar_ligacoes(p_organization_id uuid, p_entity_id uuid, p_feito_por uuid, p_visita_id uuid, p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_levantamentos_validar_ligacoes(p_organization_id uuid, p_entity_id uuid, p_feito_por uuid, p_visita_id uuid, p_negocio_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_actor()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (SELECT au.id FROM public.anew_users au WHERE au.auth_user_id = auth.uid() LIMIT 1),
    public.current_business_user_id());
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_actor() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_actor() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_actor() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_ambito_pessoas(p_organization_id uuid, OUT chaves_lead text[], OUT chaves_cliente text[], OUT admin boolean)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_chaves text[];
  v_cod    text;
  v_scope  text;
  v_user   uuid;
  v_auth   uuid;
  v_team   uuid[];
BEGIN
  chaves_lead := ARRAY[]::text[];
  chaves_cliente := ARRAY[]::text[];
  admin := false;
  IF v_uid IS NULL OR p_organization_id IS NULL
     OR NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                    WHERE c.organization_id = p_organization_id) THEN
    RETURN;
  END IF;

  FOREACH v_cod IN ARRAY ARRAY['pessoas.view', 'leads.view', 'clients.view'] LOOP
    v_chaves := ARRAY[]::text[];
    v_scope := NULL;
    v_user := NULL;
    v_auth := NULL;
    v_team := NULL;
    IF public.has_anew_permission(v_uid, v_cod) THEN
      BEGIN
        SELECT r.applied_scope, r.anew_user_id, r.auth_user_id, r.team_user_ids
          INTO v_scope, v_user, v_auth, v_team
        FROM public.resolve_lead_access_context(p_organization_id, 'ORG', v_cod) r;
        IF v_scope = 'ORG' THEN
          v_chaves := ARRAY[p_organization_id::text || ':*'];
        ELSE
          v_chaves := ARRAY(
            SELECT DISTINCT p_organization_id::text || ':' || o.dono::text
            FROM unnest(CASE WHEN v_scope = 'TEAM' THEN COALESCE(v_team, ARRAY[]::uuid[])
                             ELSE ARRAY[]::uuid[] END || ARRAY[v_user, v_auth]) AS o(dono)
            WHERE o.dono IS NOT NULL);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        -- Como crm_scope_keys: sem a permissão nesta organização, sem chaves.
        v_chaves := ARRAY[]::text[];
      END;
    END IF;
    IF v_cod = 'pessoas.view' THEN
      IF cardinality(v_chaves) = 0 THEN
        RETURN;
      END IF;
    ELSIF v_cod = 'leads.view' THEN
      chaves_lead := v_chaves;
    ELSE
      chaves_cliente := v_chaves;
    END IF;
  END LOOP;
  admin := public.is_system_admin(v_uid);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_ambito_pessoas(p_organization_id uuid, OUT chaves_lead text[], OUT chaves_cliente text[], OUT admin boolean) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_anotar(p_negocio_id uuid, p_tipo text, p_alerta text, p_detalhe text, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_tipo NOT IN ('acompanhamento', 'alerta') THEN
    RAISE EXCEPTION 'fn_neg_anotar: tipo inválido.' USING ERRCODE = 'NG009';
  END IF;

  INSERT INTO public.negocio_eventos
    (negocio_id, organization_id, root_organization_id, tipo, created_by, detalhe,
     origem_tipo, origem_id, origem_estado, canal, prova, conteudo_hash)
  SELECT n.id, n.organization_id, n.root_organization_id, p_tipo, public.fn_negocios_actor(),
         left(p_detalhe, 1000),
         CASE WHEN p_origem_id IS NOT NULL THEN p_origem_tipo END, p_origem_id,
         CASE WHEN p_origem_id IS NOT NULL THEN left(p_origem_estado, 60) END,
         p_canal,
         CASE WHEN p_origem_id IS NOT NULL THEN p_prova END,
         CASE WHEN p_origem_id IS NOT NULL THEN p_hash END
  FROM public.negocios n
  WHERE n.id = p_negocio_id;

  IF p_alerta IS NOT NULL THEN
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.negocios n SET alerta_codigo = p_alerta
    WHERE n.id = p_negocio_id AND n.alerta_codigo IS DISTINCT FROM p_alerta;
    PERFORM set_config('app.neg_via_funcao', 'off', true);
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_anotar(p_negocio_id uuid, p_tipo text, p_alerta text, p_detalhe text, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_canal(p_actor uuid, p_prova text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
           WHEN p_actor IS NOT NULL THEN 'crm'
           WHEN p_prova = 'P1' THEN 'portal'
           WHEN p_prova = 'P2' THEN 'assinatura'
           WHEN current_setting('app.audit_source', true) = 'portal' THEN 'portal'
           WHEN current_setting('app.audit_source', true) = 'signature' THEN 'assinatura'
           ELSE 'sistema'
         END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_canal(p_actor uuid, p_prova text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_conteudo_hash(p_tipo text, p_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE p_tipo
           WHEN 'proposta' THEN public.compute_proposal_business_hash(p_id)
           WHEN 'contrato' THEN public.fn_neg_contrato_hash(p_id)
         END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_conteudo_hash(p_tipo text, p_id uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_contrato_hash(p_contract_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT md5(jsonb_build_object(
           'contract_body_html', cc.contract_body_html,
           'total_value', cc.total_value,
           'payment_terms', cc.payment_terms,
           'start_date', cc.start_date,
           'end_date', cc.end_date,
           'prompt_values', cc.prompt_values,
           'contract_template_id', cc.contract_template_id,
           'template_id', cc.template_id,
           'currency', cc.currency)::text)
  FROM public.client_contracts cc
  WHERE cc.id = p_contract_id;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_contrato_hash(p_contract_id uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_converter_pessoa(p_negocio_id uuid, p_doc_tipo text, p_doc_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg                public.negocios;
  v_root_org_id        uuid;
  v_client_id          uuid;
  v_client_status      text;
  v_actor              uuid;
  v_origin_source      text;
  v_origin_source_id   uuid;
  v_origin_campaign_id uuid;
  v_leads_closed       integer := 0;
  v_doc_criador        uuid;
BEGIN
  SELECT n.* INTO v_neg FROM public.negocios n WHERE n.id = p_negocio_id AND n.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
  END IF;

  -- Uma conversão de cada vez por pessoa (o mesmo bloqueio de neg_ganhar_negocio).
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'neg_pessoa:' || v_neg.organization_id::text || ':' || v_neg.entity_id::text, 0));

  v_root_org_id := COALESCE(v_neg.root_organization_id, v_neg.organization_id);

  SELECT o.origin_source, o.origin_source_id, o.origin_campaign_id
    INTO v_origin_source, v_origin_source_id, v_origin_campaign_id
  FROM public.fn_resolve_client_marketing_origin(v_neg.entity_id, v_neg.organization_id) AS o
  LIMIT 1;

  SELECT c.id, c.status INTO v_client_id, v_client_status
  FROM public.anew_clients c
  WHERE c.entity_id = v_neg.entity_id AND c.organization_id = v_neg.organization_id
  ORDER BY c.created_at ASC
  LIMIT 1;

  IF v_client_id IS NOT NULL THEN
    IF v_client_status IS DISTINCT FROM 'active' THEN
      UPDATE public.anew_clients SET status = 'active' WHERE id = v_client_id;
    END IF;
    UPDATE public.anew_clients
    SET origin_source = COALESCE(origin_source, v_origin_source),
        origin_source_id = COALESCE(origin_source_id, v_origin_source_id),
        origin_campaign_id = COALESCE(origin_campaign_id, v_origin_campaign_id)
    WHERE id = v_client_id
      AND (origin_source IS NULL OR origin_source_id IS NULL OR origin_campaign_id IS NULL);
  ELSE
    -- Cliente de uma organização irmã da mesma raiz: reutiliza, não muda de sítio.
    SELECT c.id INTO v_client_id
    FROM public.anew_clients c
    WHERE c.entity_id = v_neg.entity_id AND c.root_organization_id = v_root_org_id
    ORDER BY c.created_at ASC
    LIMIT 1;

    IF v_client_id IS NULL THEN
      IF p_doc_tipo = 'contrato' THEN
        SELECT cc.created_by INTO v_doc_criador FROM public.client_contracts cc WHERE cc.id = p_doc_id;
      ELSIF p_doc_tipo = 'proposta' THEN
        SELECT pr.created_by INTO v_doc_criador FROM public.proposals pr WHERE pr.id = p_doc_id;
      END IF;
      v_actor := NULL;
      BEGIN
        v_actor := NULLIF(current_setting('app.audit_user_id', true), '')::uuid;
      EXCEPTION WHEN OTHERS THEN
        v_actor := NULL;
      END;
      v_actor := COALESCE(v_actor, public.current_business_user_id(), v_doc_criador, v_neg.created_by);
      IF v_actor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.anew_users u WHERE u.id = v_actor) THEN
        v_actor := NULL;
      END IF;

      INSERT INTO public.anew_clients (
        entity_id, organization_id, root_organization_id,
        status, source_type, source_id, created_by,
        origin_source, origin_source_id, origin_campaign_id
      ) VALUES (
        v_neg.entity_id, v_neg.organization_id, v_root_org_id,
        'active', CASE WHEN p_doc_tipo = 'contrato' THEN 'contract' ELSE 'direct_sale' END,
        p_doc_id, v_actor,
        v_origin_source, v_origin_source_id, v_origin_campaign_id
      )
      RETURNING id INTO v_client_id;
    END IF;
  END IF;

  -- Fechar as leads abertas da pessoa nesta organização (nunca as perdidas
  -- nem as apagadas; só preenche o que estiver vazio).
  v_actor := NULL;
  BEGIN
    v_actor := NULLIF(current_setting('app.audit_user_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;
  v_actor := COALESCE(v_actor, public.current_business_user_id());
  IF v_actor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.anew_users u WHERE u.id = v_actor) THEN
    v_actor := NULL;
  END IF;

  UPDATE public.anew_leads AS l
  SET status = 'converted',
      converted_to_client_id = COALESCE(l.converted_to_client_id, v_client_id),
      converted_at = COALESCE(l.converted_at, now()),
      converted_by = COALESCE(l.converted_by, v_actor),
      updated_at = now()
  WHERE l.entity_id = v_neg.entity_id
    AND l.organization_id = v_neg.organization_id
    AND l.deleted_at IS NULL
    AND lower(COALESCE(l.status::text, '')) <> 'lost'
    AND (lower(COALESCE(l.status::text, '')) IS DISTINCT FROM 'converted'
         OR l.converted_to_client_id IS NULL
         OR l.converted_at IS NULL);
  GET DIAGNOSTICS v_leads_closed = ROW_COUNT;

  INSERT INTO public.workflow_execution_log (
    source_entity, source_record_id, target_entity, target_record_id,
    action_type, status, execution_data
  ) VALUES (
    'negocio', v_neg.id, 'client', v_client_id,
    'trigger:negocio_conversao', 'success',
    jsonb_build_object('leads_closed', v_leads_closed, 'documento', p_doc_tipo, 'documento_id', p_doc_id)
  );

  RETURN v_client_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_converter_pessoa(p_negocio_id uuid, p_doc_tipo text, p_doc_id uuid) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_converter_pessoa(p_negocio_id uuid, p_doc_tipo text, p_doc_id uuid) IS 'Pessoas, Fase N: converte a pessoa do negócio em cliente (cópia conservadora de fn_contract_signed_convert_to_client): reutiliza o cliente da organização ou de uma irmã da mesma raiz, ou cria-o; fecha as leads abertas. Interna, sem sessão, idempotente. 20261226140000.';

CREATE OR REPLACE FUNCTION public.fn_neg_decidir_negocio(p_tipo text, p_doc_id uuid, p_status_antes text, p_status_depois text, p_negocio_antes uuid, p_negocio_depois uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_pos_pr  CONSTANT text[] := ARRAY['accepted'];
  c_neg_pr  CONSTANT text[] := ARRAY['rejected'];
  c_pos_cc  CONSTANT text[] := ARRAY['signed', 'assinado', 'active'];
  c_neg_cc  CONSTANT text[] := ARRAY['cancelled', 'cancelado', 'rejected', 'recusado'];
  -- 20261226210000: orçamentos. Recusado (decide) e documentos que já não contam.
  c_neg_qt   CONSTANT text[] := ARRAY['perdido', 'rejeitado', 'rejeitada', 'recusado', 'recusada',
                                     'rejected', 'declined', 'lost'];
  c_recusa_pr CONSTANT text[] := ARRAY['rejeitado', 'rejeitada', 'recusado', 'recusada',
                                      'rejected', 'declined', 'lost'];
  c_morto_qt CONSTANT text[] := ARRAY['perdido', 'rejeitado', 'rejeitada', 'recusado', 'recusada',
                                     'rejected', 'declined', 'lost', 'cancelado', 'cancelada', 'cancelled'];
  c_morto_pr CONSTANT text[] := ARRAY['rejeitado', 'rejeitada', 'recusado', 'recusada', 'rejected',
                                     'declined', 'lost', 'cancelado', 'cancelada', 'cancelled'];
  c_morto_cc CONSTANT text[] := ARRAY['cancelled', 'cancelado', 'cancelada', 'rejected', 'recusado',
                                     'recusada', 'rejeitado', 'rejeitada'];
  v_actor     uuid := public.fn_negocios_actor();
  v_neg       public.negocios;
  v_cfg       public.negocio_workflow_config;
  v_org       uuid;
  v_entity    uuid;
  v_status    text;
  v_neg_doc   uuid;
  v_apagado   boolean;
  v_subst     boolean := false;
  v_motivo_cl text;
  v_cls_antes text;
  v_cls_dep   text;
  v_ligacao   boolean := p_negocio_antes IS DISTINCT FROM p_negocio_depois;
  v_decisivo  boolean;
  v_origem    boolean;
  v_classe    text;
  v_prova     text;
  v_hash      text;
  v_canal     text;
  v_nome      text := CASE WHEN p_tipo = 'proposta' THEN 'Proposta'
                           WHEN p_tipo = 'orcamento' THEN 'Orçamento' ELSE 'Contrato' END;
  v_momento   timestamptz;
  v_prop_qt   uuid;
BEGIN
  IF p_tipo NOT IN ('proposta', 'contrato', 'orcamento') OR p_doc_id IS NULL OR p_negocio_depois IS NULL THEN
    RETURN;
  END IF;

  -- 1. Reler o documento. Idempotente: só age se o documento ainda está no
  --    estado e no negócio deste evento (um evento posterior trata o resto).
  IF p_tipo = 'proposta' THEN
    SELECT pr.organization_id, pr.entity_id, pr.status, pr.negocio_id,
           (pr.deleted_at IS NOT NULL OR pr.is_deleted IS TRUE),
           COALESCE(NULLIF(btrim(pr.rejection_notes), ''), NULLIF(btrim(pr.rejection_reason), ''))
      INTO v_org, v_entity, v_status, v_neg_doc, v_apagado, v_motivo_cl
    FROM public.proposals pr WHERE pr.id = p_doc_id;
  ELSIF p_tipo = 'orcamento' THEN
    SELECT q.organization_id, q.entity_id, q.estado, q.negocio_id,
           (q.deleted_at IS NOT NULL OR q.is_internal IS TRUE),
           NULLIF(btrim(q.lost_reason), ''), q.proposal_id
      INTO v_org, v_entity, v_status, v_neg_doc, v_apagado, v_motivo_cl, v_prop_qt
    FROM public.quotes q WHERE q.id = p_doc_id;
  ELSE
    SELECT cc.organization_id, cc.entity_id, cc.status, cc.negocio_id,
           (cc.deleted_at IS NOT NULL), (cc.replaced_by_contract_id IS NOT NULL),
           NULLIF(btrim(cc.cancellation_reason), '')
      INTO v_org, v_entity, v_status, v_neg_doc, v_apagado, v_subst, v_motivo_cl
    FROM public.client_contracts cc WHERE cc.id = p_doc_id;
  END IF;
  IF NOT FOUND OR v_neg_doc IS DISTINCT FROM p_negocio_depois
     OR v_status IS DISTINCT FROM p_status_depois THEN
    RETURN;
  END IF;

  -- 2. Sai sem fazer nada nos casos da secção 9.
  SELECT n.* INTO v_neg FROM public.negocios n
  WHERE n.id = p_negocio_depois AND n.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT c.* INTO v_cfg FROM public.negocio_workflow_config c
  WHERE c.organization_id = v_neg.organization_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF v_org IS DISTINCT FROM v_neg.organization_id OR v_entity IS DISTINCT FROM v_neg.entity_id
     OR v_apagado THEN
    RETURN;
  END IF;
  IF p_tipo = 'contrato' AND v_neg.fecho = 'proposta' THEN
    RETURN;
  END IF;

  -- 2b. Orçamento (20261226210000). Só a ENTRADA em recusado decide; uma
  --     ligação, um aceite ou outra mudança de estado não fazem nada aqui.
  --     Perde o negócio aberto se este era o último documento vivo e não
  --     recusado nem cancelado do negócio (orçamento, proposta ou contrato),
  --     salvo recusa_orcamento = 'manter_aberto'. Se o orçamento pertence a
  --     uma proposta já recusada (a cascata de Proposals.tsx), quem decidiu
  --     foi a recusa da proposta, segundo recusa_proposta: aqui só se anota.
  IF p_tipo = 'orcamento' THEN
    IF v_ligacao
       OR NOT COALESCE(lower(btrim(p_status_depois)) = ANY (c_neg_qt), false)
       OR COALESCE(lower(btrim(p_status_antes)) = ANY (c_neg_qt), false) THEN
      RETURN;
    END IF;
    v_canal := public.fn_neg_canal(v_actor, NULL);
    IF v_neg.estado = 'aberto' THEN
      IF v_prop_qt IS NOT NULL
         AND EXISTS (SELECT 1 FROM public.proposals pr
                     WHERE pr.id = v_prop_qt
                       AND lower(btrim(COALESCE(pr.status::text, ''))) = ANY (c_recusa_pr)) THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
          'Orçamento recusado com a proposta: a recusa da proposta é que decide.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
      ELSIF v_cfg.recusa_orcamento = 'manter_aberto'
         OR EXISTS (SELECT 1 FROM public.quotes q
                    WHERE q.negocio_id = v_neg.id AND q.id <> p_doc_id
                      AND q.deleted_at IS NULL AND q.is_internal IS NOT TRUE
                      AND NOT (lower(btrim(COALESCE(q.estado, ''))) = ANY (c_morto_qt)))
         OR EXISTS (SELECT 1 FROM public.proposals pr
                    WHERE pr.negocio_id = v_neg.id
                      AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
                      AND NOT (lower(btrim(COALESCE(pr.status::text, ''))) = ANY (c_morto_pr)))
         OR EXISTS (SELECT 1 FROM public.client_contracts cc
                    WHERE cc.negocio_id = v_neg.id
                      AND cc.deleted_at IS NULL AND cc.replaced_by_contract_id IS NULL
                      AND NOT (lower(btrim(COALESCE(cc.status::text, ''))) = ANY (c_morto_cc))) THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Orçamento recusado.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
      ELSE
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'orcamento',
          'Automático: orçamento recusado' || COALESCE(': ' || v_motivo_cl, ''), NULL,
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL,
          'Orçamento recusado (era o último documento vivo do negócio)');
      END IF;
    ELSIF v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Orçamento recusado num negócio ganho.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
    END IF;
    RETURN;
  END IF;

  -- 3. Classes de estado.
  v_cls_antes := CASE
    WHEN p_tipo = 'proposta' AND p_status_antes = ANY (c_pos_pr) THEN 'positivo'
    WHEN p_tipo = 'proposta' AND p_status_antes = ANY (c_neg_pr) THEN 'negativo'
    WHEN p_tipo = 'contrato' AND p_status_antes = ANY (c_pos_cc) THEN 'positivo'
    WHEN p_tipo = 'contrato' AND p_status_antes = ANY (c_neg_cc) THEN 'negativo'
    ELSE 'neutro' END;
  v_cls_dep := CASE
    WHEN p_tipo = 'proposta' AND p_status_depois = ANY (c_pos_pr) THEN 'positivo'
    WHEN p_tipo = 'proposta' AND p_status_depois = ANY (c_neg_pr) THEN 'negativo'
    WHEN p_tipo = 'contrato' AND p_status_depois = ANY (c_pos_cc) THEN 'positivo'
    WHEN p_tipo = 'contrato' AND p_status_depois = ANY (c_neg_cc) THEN 'negativo'
    ELSE 'neutro' END;
  v_decisivo := (p_tipo = v_neg.fecho);
  v_origem := (v_neg.decisao_origem_id IS NOT DISTINCT FROM p_doc_id);

  -- 4. Classe da transição (9.1).
  IF v_ligacao THEN
    -- T11: uma ligação só conta se o documento já for positivo. A prova é a
    -- das colunas: quem liga não é quem aceitou (decisão 1 da v3, adiada).
    IF v_cls_dep <> 'positivo' THEN
      RETURN;
    END IF;
    v_prova := CASE WHEN p_tipo = 'proposta' THEN public.fn_neg_prova_proposta(p_doc_id, NULL)
                    ELSE public.fn_neg_prova_contrato(p_doc_id) END;
    v_classe := CASE WHEN v_prova IS NOT NULL THEN 'positivo' ELSE 'positivo_sem_prova' END;
  ELSIF v_cls_dep = 'positivo' AND v_cls_antes <> 'positivo' THEN
    v_prova := CASE WHEN p_tipo = 'proposta' THEN public.fn_neg_prova_proposta(p_doc_id, v_actor)
                    ELSE public.fn_neg_prova_contrato(p_doc_id) END;
    v_classe := CASE WHEN v_prova IS NOT NULL THEN 'positivo' ELSE 'positivo_sem_prova' END;
  ELSIF v_cls_dep = 'positivo' THEN
    RETURN;                                               -- T2
  ELSIF v_cls_dep = 'negativo' AND v_cls_antes <> 'negativo' THEN
    IF p_tipo = 'proposta' THEN
      v_classe := CASE WHEN v_cls_antes = 'positivo' THEN 'recusa_depois_aceite' ELSE 'recusa_proposta' END;
    ELSIF v_subst THEN
      v_classe := 'substituicao';
    ELSIF v_cls_antes = 'positivo' THEN
      v_classe := 'cancelamento_assinado';
    ELSE
      v_classe := 'recusa_contrato';
    END IF;
  ELSIF v_cls_antes = 'positivo' AND v_cls_dep = 'neutro' THEN
    v_classe := CASE WHEN v_actor IS NOT NULL AND public.fn_neg_houve_alteracoes(v_neg.id, p_tipo, p_doc_id)
                     THEN 'reabertura' ELSE 'sem_efeito' END;
  ELSIF v_cls_antes = 'negativo' AND v_cls_dep = 'neutro' THEN
    v_classe := CASE WHEN v_actor IS NOT NULL AND public.fn_neg_houve_alteracoes(v_neg.id, p_tipo, p_doc_id)
                     THEN 'reenviado' ELSE 'reenviado_sem_alteracoes' END;
  ELSE
    RETURN;
  END IF;

  -- Retrato do conteúdo nas decisões positivas e negativas (10.4).
  IF v_classe IN ('positivo', 'positivo_sem_prova', 'recusa_proposta', 'recusa_contrato',
                  'recusa_depois_aceite', 'cancelamento_assinado') THEN
    v_hash := public.fn_neg_conteudo_hash(p_tipo, p_doc_id);
  END IF;
  v_canal := public.fn_neg_canal(v_actor, v_prova);

  -- 5. Efeito no negócio (9.2).
  IF v_classe = 'positivo' THEN
    IF NOT v_decisivo THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
        'Proposta aceite; o negócio fecha no contrato.',
        p_tipo, p_doc_id, v_status, v_canal, v_prova, v_hash);
    ELSIF v_neg.estado = 'aberto' THEN
      PERFORM public.fn_neg_ganhar_interno(v_neg.id, p_tipo, p_doc_id, v_status, v_canal, v_prova, v_hash,
        CASE WHEN p_tipo = 'proposta' THEN 'Proposta aceite' ELSE 'Contrato assinado' END);
    ELSIF v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
        v_nome || ' positivo num negócio já ganho.',
        p_tipo, p_doc_id, v_status, v_canal, v_prova, v_hash);
    ELSE
      PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'positivo_depois_perda',
        v_nome || ' aceite ou assinado depois da perda.',
        p_tipo, p_doc_id, v_status, v_canal, v_prova, v_hash);
    END IF;

  ELSIF v_classe = 'positivo_sem_prova' THEN
    IF NOT v_decisivo OR v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
        v_nome || ' aceite ou assinado sem prova.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
    ELSE
      PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'sem_prova',
        'Assinado ou aceite sem prova.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
    END IF;

  ELSIF v_classe = 'recusa_proposta' THEN
    -- A recusa só perde se não houver outro documento positivo ativo (proposta
    -- aceite, ou contrato assinado no fecho no contrato). Outra proposta em
    -- rascunho ou enviada não trava a perda (decisão do utilizador).
    IF v_neg.estado = 'aberto' THEN
      IF public.fn_neg_tem_positivo_activo(v_neg, p_doc_id) OR v_cfg.recusa_proposta = 'manter_aberto' THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Proposta recusada.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      ELSE
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'proposta',
          'Automático: proposta recusada' || COALESCE(': ' || v_motivo_cl, ''), NULL,
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash, 'Proposta recusada');
      END IF;
    ELSIF v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Proposta recusada num negócio ganho.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
    END IF;

  ELSIF v_classe = 'recusa_contrato' THEN
    IF v_neg.estado = 'aberto' THEN
      IF v_cfg.recusa_contrato = 'manter_aberto' THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Contrato recusado ou cancelado antes de assinado.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      ELSE
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'contrato',
          CASE WHEN v_status IN ('cancelled', 'cancelado')
               THEN 'Automático: contrato cancelado antes de assinado'
               ELSE 'Automático: contrato recusado' END || COALESCE(': ' || v_motivo_cl, ''), NULL,
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash, 'Contrato recusado ou cancelado');
      END IF;
    ELSIF v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Contrato recusado ou cancelado num negócio ganho.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
    END IF;

  ELSIF v_classe = 'substituicao' THEN
    IF v_neg.estado = 'ganho' AND v_origem THEN
      PERFORM public.fn_neg_mudar_estado(v_neg.id, 'aberto', NULL, NULL,
        'Contrato substituído: aguarda assinatura da nova versão',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL, 'Contrato substituído');
    ELSE
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Contrato substituído por uma nova versão.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
    END IF;

  ELSIF v_classe = 'cancelamento_assinado' THEN
    IF v_neg.estado = 'ganho' AND v_origem THEN
      v_momento := public.fn_neg_momento_assinatura(p_doc_id, v_neg.ganho_em);
      IF v_cfg.reflexao_dias IS NULL THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'prazo_por_configurar',
          'Contrato cancelado depois de assinado; o prazo de reflexão não está configurado: o negócio continua ganho.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      ELSIF v_momento IS NOT NULL AND now() <= v_momento + make_interval(days => v_cfg.reflexao_dias) THEN
        IF v_cfg.cancelamento_no_prazo = 'perder' THEN
          PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'contrato',
            'Desistência dentro do prazo' || COALESCE(': ' || v_motivo_cl, ''), NULL,
            p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash, 'Desistência dentro do prazo');
        ELSE
          PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
            'Contrato cancelado dentro do prazo; a configuração mantém o ganho.',
            p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
        END IF;
      ELSE
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Cancelado depois do prazo.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      END IF;
    ELSIF v_neg.estado <> 'perdido' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Contrato cancelado depois de assinado.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
    END IF;

  ELSIF v_classe = 'reabertura' THEN
    IF v_neg.estado = 'ganho' AND v_origem THEN
      PERFORM public.fn_neg_mudar_estado(v_neg.id, 'aberto', NULL, NULL,
        v_nome || ' reaberto com alterações',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL, v_nome || ' reaberto com alterações');
    END IF;

  ELSIF v_classe = 'sem_efeito' THEN
    IF v_neg.estado = 'ganho' THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'mudanca_sem_efeito',
        v_nome || ' saiu de aceite ou assinado sem alterações: o negócio continua ganho.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
    END IF;

  ELSIF v_classe = 'recusa_depois_aceite' THEN
    IF v_neg.estado = 'aberto' THEN
      IF public.fn_neg_tem_positivo_activo(v_neg, p_doc_id) OR v_cfg.recusa_proposta = 'manter_aberto' THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL, 'Proposta recusada depois de aceite.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      ELSE
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'proposta',
          'Automático: proposta recusada depois de aceite' || COALESCE(': ' || v_motivo_cl, ''), NULL,
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash, 'Proposta recusada depois de aceite');
      END IF;
    ELSIF v_neg.estado = 'ganho' THEN
      IF v_origem AND v_actor IS NOT NULL THEN
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'aberto', NULL, NULL,
          'Proposta recusada depois de aceite',
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL, 'Proposta recusada depois de aceite');
        SELECT n.* INTO v_neg FROM public.negocios n WHERE n.id = v_neg.id;
        IF v_cfg.recusa_proposta = 'perder' AND NOT public.fn_neg_tem_positivo_activo(v_neg, p_doc_id) THEN
          PERFORM public.fn_neg_mudar_estado(v_neg.id, 'perdido', 'proposta',
            'Automático: proposta recusada depois de aceite' || COALESCE(': ' || v_motivo_cl, ''), NULL,
            p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash, 'Proposta recusada depois de aceite');
        END IF;
      ELSE
        PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'recusa_depois_aceite',
          'Proposta recusada depois de aceite: o negócio continua ganho.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, v_hash);
      END IF;
    END IF;

  ELSIF v_classe = 'reenviado' THEN
    IF v_neg.estado = 'perdido' THEN
      IF v_origem THEN
        PERFORM public.fn_neg_mudar_estado(v_neg.id, 'aberto', NULL, NULL,
          v_nome || ' reenviado com alterações',
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL, v_nome || ' reenviado com alterações');
      ELSE
        PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', 'reenvio_sem_reabrir',
          v_nome || ' reenviado com alterações, mas a perda não veio dele (ou foi manual): o negócio continua perdido.',
          p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
      END IF;
    END IF;

  ELSIF v_classe = 'reenviado_sem_alteracoes' THEN
    IF v_neg.estado = 'perdido' AND v_origem THEN
      PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
        v_nome || ' reenviado sem alterações: não reabre o negócio.',
        p_tipo, p_doc_id, v_status, v_canal, NULL, NULL);
    END IF;
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_decidir_negocio(p_tipo text, p_doc_id uuid, p_status_antes text, p_status_depois text, p_negocio_antes uuid, p_negocio_depois uuid) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_decidir_negocio(p_tipo text, p_doc_id uuid, p_status_antes text, p_status_depois text, p_negocio_antes uuid, p_negocio_depois uuid) IS 'Pessoas, Fase N: decide o negócio a partir de uma proposta, de um contrato ou (20261226210000) de um orçamento recusado. Chamada só pelos gatilhos adiados trg_negocios_fecho_*. 20261226140000, 20261226210000.';

CREATE OR REPLACE FUNCTION public.fn_neg_detalhes_visita(p_detalhes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_morada jsonb;
BEGIN
  IF p_detalhes IS NULL OR p_detalhes = 'null'::jsonb THEN
    RETURN NULL;
  END IF;
  IF jsonb_typeof(p_detalhes) <> 'object' THEN
    RAISE EXCEPTION 'Valor inválido: detalhes da visita.' USING ERRCODE = 'NG009';
  END IF;
  IF octet_length(p_detalhes::text) > 2000
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_detalhes) AS k(chave)
                WHERE k.chave NOT IN ('morada', 'igual_a_lead', 'presentes'))
     OR jsonb_typeof(COALESCE(p_detalhes -> 'igual_a_lead', 'null'::jsonb)) NOT IN ('boolean', 'null')
     OR jsonb_typeof(COALESCE(p_detalhes -> 'presentes', 'null'::jsonb)) NOT IN ('string', 'null')
     OR (p_detalhes ->> 'presentes') NOT IN ('cliente', 'casal', 'familia', 'outra') THEN
    RAISE EXCEPTION 'Valor inválido: detalhes da visita.' USING ERRCODE = 'NG009';
  END IF;

  v_morada := p_detalhes -> 'morada';
  IF v_morada IS NOT NULL AND v_morada <> 'null'::jsonb THEN
    IF jsonb_typeof(v_morada) <> 'object' THEN
      RAISE EXCEPTION 'Valor inválido: morada da visita.' USING ERRCODE = 'NG009';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(v_morada) AS m(chave, valor)
                  WHERE m.chave NOT IN ('rua', 'codigo_postal', 'localidade', 'andar')
                     OR jsonb_typeof(m.valor) NOT IN ('string', 'null'))
       OR char_length(v_morada ->> 'rua') > 300
       OR char_length(v_morada ->> 'localidade') > 120
       OR char_length(v_morada ->> 'andar') > 60
       OR (v_morada ->> 'codigo_postal') !~ '^[0-9]{4}-[0-9]{3}$' THEN
      RAISE EXCEPTION 'Valor inválido: morada da visita.' USING ERRCODE = 'NG009';
    END IF;
  END IF;

  RETURN p_detalhes;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_detalhes_visita(p_detalhes jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_detalhes_visita(p_detalhes jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_escolher_lead(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_preferir text)
 RETURNS anew_leads
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lead public.anew_leads;
BEGIN
  IF p_lead_id IS NOT NULL THEN
    SELECT l.* INTO v_lead
    FROM public.anew_leads l
    WHERE l.id = p_lead_id AND l.organization_id = p_organization_id
      AND l.entity_id = p_entity_id AND l.deleted_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Valor inválido: a lead indicada não é desta pessoa.' USING ERRCODE = 'NG009';
    END IF;
    RETURN v_lead;
  END IF;

  SELECT l.* INTO v_lead
  FROM public.anew_leads l
  WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
    AND l.deleted_at IS NULL
    AND (p_preferir IS DISTINCT FROM 'aberta' OR public.fn_neg_lead_aberta(l.status::text))
  ORDER BY
    CASE WHEN p_preferir = 'fechada' THEN l.closure_result IS NOT NULL ELSE true END DESC,
    l.created_at DESC
  LIMIT 1;

  RETURN v_lead;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_escolher_lead(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_preferir text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_escolher_lead(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_preferir text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_escolher_lead(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_preferir text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_exigir_config(p_organization_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_momento text;
BEGIN
  SELECT c.momento_ganho INTO v_momento
  FROM public.negocio_workflow_config c
  WHERE c.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  RETURN v_momento;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_exigir_config(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_exigir_config(p_organization_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_exigir_config(p_organization_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_exigir_pessoa(p_organization_id uuid, p_entity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_organization_id IS NULL OR p_entity_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.anew_entity_org_links lk
       WHERE lk.entity_id = p_entity_id AND lk.organization_id = p_organization_id)
     OR NOT (
       EXISTS (SELECT 1 FROM public.anew_leads l
               WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                 AND l.deleted_at IS NULL)
       OR EXISTS (SELECT 1 FROM public.anew_clients c
                  WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                    AND c.deleted_at IS NULL)) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_exigir_pessoa(p_organization_id uuid, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_exigir_pessoa(p_organization_id uuid, p_entity_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_exigir_pessoa(p_organization_id uuid, p_entity_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_fecho_contrato_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '2s'
AS $function$
BEGIN
  BEGIN
    PERFORM public.fn_neg_decidir_negocio('contrato', NEW.id, OLD.status, NEW.status,
                                          OLD.negocio_id, NEW.negocio_id);
  EXCEPTION WHEN OTHERS THEN
    -- Nunca faz falhar o COMMIT do documento: regista e segue.
    BEGIN
      INSERT INTO public.workflow_execution_log (
        source_entity, source_record_id, target_entity, target_record_id,
        action_type, status, error_message, execution_data
      ) VALUES (
        'contract', NEW.id, 'negocio', NEW.negocio_id,
        'trigger:negocio_fecho', 'error', SQLERRM,
        jsonb_build_object('sqlstate', SQLSTATE, 'status_antes', OLD.status,
                           'status_depois', NEW.status, 'negocio_antes', OLD.negocio_id)
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_fecho_contrato_trg() FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_fecho_contrato_trg() IS 'Pessoas, Fase N: gatilho adiado de client_contracts; chama fn_neg_decidir_negocio. Um erro vai para workflow_execution_log (trigger:negocio_fecho) e nunca faz falhar o COMMIT. 20261226160000.';

