CREATE OR REPLACE FUNCTION public.fn_neg_ficha_seccao(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer, p_depois jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_lim    int;
  v_ts     timestamptz;
  v_dt     date;
  v_id     uuid;
  v_leads  uuid[];
  v_clis   uuid[];
  v_total  bigint;
  v_itens  jsonb;
  v_mais   boolean;
  v_ult_ts timestamptz;
  v_ult_dt date;
  v_ult_id uuid;
BEGIN
  IF p_tipo IS NULL OR p_tipo NOT IN ('contactos', 'visitas', 'levantamentos', 'atividade')
     OR p_limite IS NULL OR p_limite < 1 OR p_limite > 100
     OR (p_depois IS NOT NULL AND jsonb_typeof(p_depois) NOT IN ('object', 'null')) THEN
    RAISE EXCEPTION 'Valor inválido: secção, limite (1 a 100) ou página.' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_typeof(p_depois) = 'object' THEN
    BEGIN
      v_id := (p_depois ->> 'id')::uuid;
      IF p_tipo = 'levantamentos' THEN
        v_dt := (p_depois ->> 'em')::date;
      ELSE
        v_ts := (p_depois ->> 'em')::timestamptz;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- qualquer erro de conversão (uuid, data, fuso): página inválida
      RAISE EXCEPTION 'Valor inválido: página.' USING ERRCODE = 'NG009';
    END;
    IF v_id IS NULL OR (v_ts IS NULL AND v_dt IS NULL) THEN
      RAISE EXCEPTION 'Valor inválido: página.' USING ERRCODE = 'NG009';
    END IF;
  END IF;

  -- Guardas: saltadas só se neg_ficha_pessoa já as passou nesta transacção
  -- para esta organização e pessoa (variável local que a API não escreve).
  IF COALESCE(current_setting('app.neg_ficha_verificada', true), '')
     IS DISTINCT FROM p_organization_id::text || ':' || p_entity_id::text THEN
    PERFORM public.fn_neg_exigir_config(p_organization_id);
    PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);
  END IF;

  -- 20261226060000: os levantamentos paginam como as outras secções, com
  -- p_limite por página (antes, no máximo 10).
  v_lim := p_limite;

  IF p_tipo IN ('contactos', 'atividade') THEN
    SELECT count(*) INTO v_total
    FROM public.entity_interactions i
    WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id
      AND (p_tipo = 'atividade' OR i.interaction_type = 'call');

    SELECT COALESCE(jsonb_agg(z.item ORDER BY z.rn) FILTER (WHERE z.rn <= v_lim), '[]'::jsonb),
           count(*) > v_lim,
           (array_agg(z.em ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1],
           (array_agg(z.id ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1]
      INTO v_itens, v_mais, v_ult_ts, v_ult_id
    FROM (
      SELECT i.id, i.interaction_at AS em,
             row_number() OVER (ORDER BY i.interaction_at DESC, i.id DESC) AS rn,
             CASE WHEN p_tipo = 'contactos' THEN
               jsonb_build_object('id', i.id, 'resultado', i.result, 'notas', i.notes,
                                  'em', i.interaction_at, 'proxima_acao_em', i.next_action_date,
                                  'negocio_id', i.negocio_id, 'criado_por_nome', cu.name)
             ELSE
               jsonb_build_object('id', i.id, 'tipo', i.interaction_type, 'assunto', i.subject,
                                  'resultado', i.result, 'notas', i.notes, 'em', i.interaction_at,
                                  'negocio_id', i.negocio_id, 'criado_por_nome', cu.name)
             END AS item
      FROM (
        SELECT ei.*
        FROM public.entity_interactions ei
        WHERE ei.entity_id = p_entity_id AND ei.organization_id = p_organization_id
          AND (p_tipo = 'atividade' OR ei.interaction_type = 'call')
          AND (v_ts IS NULL OR (ei.interaction_at, ei.id) < (v_ts, v_id))
        ORDER BY ei.interaction_at DESC, ei.id DESC
        LIMIT v_lim + 1
      ) i
      LEFT JOIN LATERAL (
        SELECT u.name FROM public.anew_users u
        WHERE u.id = CASE WHEN i.created_by ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN i.created_by::uuid END
        LIMIT 1
      ) cu ON true
    ) z;

  ELSIF p_tipo = 'visitas' THEN
    -- Dois ramos por índice (leads e clientes da pessoa); sem ausências,
    -- férias nem quadros de ausências ou de frota. 20261226060000: as
    -- canceladas passam a vir (antes eram escondidas), marcadas com
    -- 'cancelada' = true; o total e a paginação contam-nas.
    v_leads := ARRAY(SELECT l.id FROM public.anew_leads l
                     WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                       AND l.deleted_at IS NULL);
    v_clis  := ARRAY(SELECT c.id FROM public.anew_clients c
                     WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                       AND c.deleted_at IS NULL);

    SELECT count(*) INTO v_total
    FROM (SELECT si.id FROM public.schedule_items si
          WHERE si.lead_id = ANY (v_leads) AND si.organization_id = p_organization_id
          UNION
          SELECT si.id FROM public.schedule_items si
          WHERE si.client_id = ANY (v_clis) AND si.organization_id = p_organization_id) ids
    JOIN public.schedule_items s ON s.id = ids.id
    LEFT JOIN public.schedule_boards b ON b.id = s.board_id
    WHERE s.time_off_type IS NULL AND s.vacation_id IS NULL
      AND (b.board_type IS NULL OR b.board_type NOT IN ('time_off', 'fleet'));

    -- 20261226100000: a página primeiro (com a RLS de quem chama, como antes) e
    -- os responsáveis dessas visitas por fn_neg_ficha_visitas_recursos, que não
    -- passa pela política de schedule_item_assignees (essa voltava a ler toda a
    -- agenda da organização com a RLS de quem chama: cerca de 1,5 s por ficha).
    -- Os recursos continuam a vir de schedule_resources com a RLS de quem chama.
    WITH pagina AS MATERIALIZED (
      SELECT si.*, b.name AS board_nome
      FROM (SELECT x.id FROM public.schedule_items x
            WHERE x.lead_id = ANY (v_leads) AND x.organization_id = p_organization_id
            UNION
            SELECT x.id FROM public.schedule_items x
            WHERE x.client_id = ANY (v_clis) AND x.organization_id = p_organization_id) ids
      JOIN public.schedule_items si ON si.id = ids.id
      LEFT JOIN public.schedule_boards b ON b.id = si.board_id
      WHERE si.time_off_type IS NULL AND si.vacation_id IS NULL
        AND (b.board_type IS NULL OR b.board_type NOT IN ('time_off', 'fleet'))
        AND (v_ts IS NULL OR (si.start_datetime, si.id) < (v_ts, v_id))
      ORDER BY si.start_datetime DESC, si.id DESC
      LIMIT v_lim + 1
    ),
    atrib AS MATERIALIZED (
      SELECT h.visita_id, h.recurso_id
      FROM public.fn_neg_ficha_visitas_recursos(p_organization_id,
                                                ARRAY(SELECT pg.id FROM pagina pg)) AS h
    )
    SELECT COALESCE(jsonb_agg(z.item ORDER BY z.rn) FILTER (WHERE z.rn <= v_lim), '[]'::jsonb),
           count(*) > v_lim,
           (array_agg(z.em ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1],
           (array_agg(z.id ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1]
      INTO v_itens, v_mais, v_ult_ts, v_ult_id
    FROM (
      SELECT s.id, s.start_datetime AS em,
             row_number() OVER (ORDER BY s.start_datetime DESC, s.id DESC) AS rn,
             jsonb_build_object(
               'id', s.id, 'inicio', s.start_datetime, 'fim', s.end_datetime, 'status', s.status,
               'resultado', s.visit_outcome, 'tipo', s.visit_kind, 'titulo', s.title,
               'notas', s.description, 'local', s.location, 'negocio_id', s.negocio_id,
               'feito_por_nome', fp.name, 'board_id', s.board_id, 'board_nome', s.board_nome,
               'recursos', rc.lista, 'detalhes', s.metadata -> 'pessoas',
               'cancelada', s.status = 'cancelled'::public.schedule_item_status) AS item
      FROM pagina s
      LEFT JOIN LATERAL (
        SELECT u.name FROM public.anew_users u
        WHERE u.id = s.created_by OR u.auth_user_id = s.created_by
        LIMIT 1
      ) fp ON true
      LEFT JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('id', r.id, 'nome', r.name,
                                                     'user_id', r.user_id, 'ativo', r.is_active)
                                  ORDER BY r.name, r.id), '[]'::jsonb) AS lista
        FROM atrib a
        JOIN public.schedule_resources r ON r.id = a.recurso_id
        WHERE a.visita_id = s.id
      ) rc ON true
    ) z;

  ELSE -- levantamentos
    SELECT count(*) INTO v_total
    FROM public.levantamentos lt
    WHERE lt.entity_id = p_entity_id AND lt.organization_id = p_organization_id
      AND lt.deleted_at IS NULL;

    SELECT COALESCE(jsonb_agg(z.item ORDER BY z.rn) FILTER (WHERE z.rn <= v_lim), '[]'::jsonb),
           count(*) > v_lim,
           (array_agg(z.em ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1],
           (array_agg(z.id ORDER BY z.rn) FILTER (WHERE z.rn = v_lim))[1]
      INTO v_itens, v_mais, v_ult_dt, v_ult_id
    FROM (
      SELECT lt.id, lt.data_levantamento AS em,
             row_number() OVER (ORDER BY lt.data_levantamento DESC, lt.id DESC) AS rn,
             jsonb_build_object(
               'id', lt.id, 'visita_id', lt.visita_id, 'negocio_id', lt.negocio_id,
               'data', lt.data_levantamento, 'estado', lt.estado, 'notas', lt.notas,
               'feito_por_id', lt.feito_por, 'feito_por_nome', fp.name,
               'morada', jsonb_build_object('rua', lt.morada_rua, 'codigo_postal', lt.morada_codigo_postal,
                                            'localidade', lt.morada_localidade, 'andar', lt.morada_andar),
               'n_linhas', ln.n, 'n_respostas', rs.n,
               'linhas', ln.lista, 'respostas', rs.lista) AS item
      FROM (
        SELECT l2.*
        FROM public.levantamentos l2
        WHERE l2.entity_id = p_entity_id AND l2.organization_id = p_organization_id
          AND l2.deleted_at IS NULL
          AND (v_dt IS NULL OR (l2.data_levantamento, l2.id) < (v_dt, v_id))
        ORDER BY l2.data_levantamento DESC, l2.id DESC
        LIMIT v_lim + 1
      ) lt
      LEFT JOIN LATERAL (
        SELECT u.name FROM public.anew_users u WHERE u.id = lt.feito_por LIMIT 1
      ) fp ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n,
               COALESCE(jsonb_agg(jsonb_build_object(
                 'divisao', ll.divisao, 'trabalho', ll.trabalho, 'trabalho_outro', ll.trabalho_outro,
                 'medida', ll.medida, 'unidade', ll.unidade, 'observacoes', ll.observacoes,
                 'ordem', ll.ordem) ORDER BY ll.ordem, ll.id), '[]'::jsonb) AS lista
        FROM public.levantamento_linhas ll
        WHERE ll.levantamento_id = lt.id
      ) ln ON true
      LEFT JOIN LATERAL (
        -- 20261226090000: cada resposta traz o snapshot (o que a pessoa viu e
        -- respondeu); tipo NULL = resposta antiga, só com a chave em 'resposta'.
        SELECT count(*) AS n,
               COALESCE(jsonb_agg(jsonb_build_object(
                 'seccao', lr.seccao, 'pergunta', lr.pergunta, 'resposta', lr.resposta,
                 'tipo', lr.tipo, 'pergunta_texto', lr.pergunta_texto, 'seccao_titulo', lr.seccao_titulo,
                 'bloco', lr.bloco, 'ordem', lr.ordem, 'escolhas', lr.escolhas,
                 'escolhas_texto', lr.escolhas_texto, 'valor_texto', lr.valor_texto,
                 'valor_numero', lr.valor_numero)
                 ORDER BY lr.ordem NULLS LAST, lr.seccao, lr.pergunta), '[]'::jsonb) AS lista
        FROM public.levantamento_respostas lr
        WHERE lr.levantamento_id = lt.id
      ) rs ON true
    ) z;
  END IF;

  RETURN jsonb_build_object(
    'total', v_total,
    'tem_mais', v_mais,
    'proximo', CASE WHEN v_mais THEN jsonb_build_object(
                 'em', CASE WHEN p_tipo = 'levantamentos' THEN to_char(v_ult_dt, 'YYYY-MM-DD')
                            ELSE to_char(v_ult_ts AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
                 'id', v_ult_id) END,
    'itens', v_itens);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_ficha_seccao(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer, p_depois jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_ficha_seccao(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer, p_depois jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_ficha_visitas_recursos(p_organization_id uuid, p_visitas uuid[])
 RETURNS TABLE(visita_id uuid, recurso_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- A ficha pede no máximo uma página (100) mais uma.
  IF p_organization_id IS NULL OR p_visitas IS NULL OR cardinality(p_visitas) > 101 THEN
    RAISE EXCEPTION 'Valor inválido: visitas.' USING ERRCODE = 'NG009';
  END IF;

  -- Só as visitas que quem chama vê: as três políticas de leitura de
  -- schedule_items, copiadas à letra (a migration confere o md5 delas), com
  -- auth.uid() de quem chama; as funções que usam são todas SECURITY DEFINER,
  -- por isso dão aqui o mesmo que na RLS. Dada a visita visível, as políticas
  -- de leitura de schedule_item_assignees ficam todas satisfeitas: quem vê a
  -- visita vê os seus responsáveis, como hoje. Só os ids; os recursos lêem-se
  -- fora daqui, com a RLS de schedule_resources de quem chama.
  RETURN QUERY
  SELECT a.item_id, a.resource_id
  FROM public.schedule_items si
  JOIN public.schedule_item_assignees a ON a.item_id = si.id
  WHERE si.id = ANY (p_visitas)
    AND si.organization_id = p_organization_id
    AND ((public.is_system_admin(auth.uid())
          AND si.organization_id IN (SELECT public.get_user_visible_org_ids(auth.uid())))
         OR (public.is_system_admin(auth.uid())
             AND public.has_active_support_access(si.organization_id))
         OR (public.has_scheduling_permission(auth.uid(), 'scheduling.items.view'::text)
             AND si.organization_id IN (SELECT public.get_user_visible_org_ids(auth.uid()))
             AND EXISTS (SELECT 1
                         FROM public.get_schedule_item_scope_context(si.organization_id,
                                                                     'scheduling.items.view'::text)
                                AS ctx(applied_scope, owner_ids)
                         WHERE ctx.applied_scope = 'ORG'::text
                            OR si.created_by = ANY (ctx.owner_ids)
                            OR si.user_id = ANY (ctx.owner_ids)
                            OR public.schedule_item_assigned_to_owners(si.id, ctx.owner_ids))));
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_ficha_visitas_recursos(p_organization_id uuid, p_visitas uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_ficha_visitas_recursos(p_organization_id uuid, p_visitas uuid[]) TO authenticated;
COMMENT ON FUNCTION public.fn_neg_ficha_visitas_recursos(p_organization_id uuid, p_visitas uuid[]) IS 'Pessoas, ficha: pares (visita_id, recurso_id) dos responsáveis das visitas dadas que quem chama vê (as políticas de leitura de schedule_items, copiadas). Só leitura. Usada por fn_neg_ficha_seccao para não passar pela política de schedule_item_assignees. 20261226100000.';

CREATE OR REPLACE FUNCTION public.fn_neg_filtro_pessoas(p_organization_id uuid, p_atribuido_a uuid, p_formulario_id uuid, p_ultimo_resultado text, p_voltou boolean)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_keys_lead text[];
  v_keys_cli  text[];
  v_admin     boolean;
  v_visiveis  uuid[];
BEGIN
  IF v_uid IS NULL OR p_organization_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT a.chaves_lead, a.chaves_cliente, a.admin
    INTO v_keys_lead, v_keys_cli, v_admin
  FROM public.fn_neg_ambito_pessoas(p_organization_id) a;
  IF v_admin IS NOT FALSE OR cardinality(v_keys_lead) + cardinality(v_keys_cli) = 0 THEN
    RETURN NULL;
  END IF;
  v_visiveis := ARRAY(SELECT public.get_user_visible_org_ids(v_uid));
  IF NOT (p_organization_id = ANY (v_visiveis)) THEN
    RETURN NULL;
  END IF;

  RETURN ARRAY(
    SELECT b.ent
    FROM (
      SELECT COALESCE(ld.ent, cl.ent) AS ent, ld.lassigned, ld.lcamp, ld.lativ, ld.lcontacto, ld.lresultado,
             cl.cassigned
      FROM (
        SELECT DISTINCT ON (l.entity_id)
               l.entity_id AS ent, l.assigned_to AS lassigned, l.campaign_id AS lcamp,
               l.last_activity_at AS lativ, l.last_contact_at AS lcontacto, l.last_contact_result AS lresultado
        FROM public.anew_leads l
        WHERE l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
          AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
               OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
               OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead))
        ORDER BY l.entity_id, l.created_at DESC, l.id DESC
      ) ld
      FULL JOIN (
        SELECT DISTINCT ON (c.entity_id)
               c.entity_id AS ent, c.assigned_to AS cassigned
        FROM public.anew_clients c
        WHERE c.organization_id = p_organization_id AND c.deleted_at IS NULL AND c.entity_id IS NOT NULL
          AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
               OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
               OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli))
        ORDER BY c.entity_id, c.created_at ASC, c.id ASC
      ) cl ON cl.ent = ld.ent
    ) b
    LEFT JOIN (
      SELECT i.entity_id AS ent, max(i.interaction_at) AS ultimo,
             (array_agg(i.result ORDER BY i.interaction_at DESC, i.id DESC))[1] AS resultado
      FROM public.entity_interactions i
      WHERE (p_ultimo_resultado IS NOT NULL OR p_voltou IS NOT NULL)
        AND i.organization_id = p_organization_id AND i.interaction_type = 'call'
      GROUP BY i.entity_id
    ) ct ON ct.ent = b.ent
    LEFT JOIN LATERAL (
      SELECT f.id AS fid
      FROM public.campaigns ca
      JOIN public.forms f ON f.id = ca.form_id
      WHERE p_formulario_id IS NOT NULL AND ca.id = b.lcamp
        AND ca.organization_id = ANY (v_visiveis) AND f.organization_id = ANY (v_visiveis)
    ) fm ON true
    WHERE (p_atribuido_a IS NULL OR COALESCE(b.cassigned, b.lassigned) = p_atribuido_a)
      AND (p_formulario_id IS NULL OR fm.fid = p_formulario_id)
      AND (p_ultimo_resultado IS NULL
           OR (CASE WHEN ct.ultimo IS NULL AND b.lcontacto IS NULL THEN 'semContacto'
                    WHEN b.lcontacto IS NULL OR ct.ultimo >= b.lcontacto THEN ct.resultado
                    ELSE b.lresultado::text END) = p_ultimo_resultado)
      AND (p_voltou IS NULL
           OR (b.lativ IS NOT NULL
               AND (GREATEST(b.lcontacto, ct.ultimo) IS NULL
                    OR b.lativ > GREATEST(b.lcontacto, ct.ultimo))) = p_voltou));
EXCEPTION WHEN OTHERS THEN
  -- falha fechada no caminho rápido: a Lista usa o caminho normal, pela RLS
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_filtro_pessoas(p_organization_id uuid, p_atribuido_a uuid, p_formulario_id uuid, p_ultimo_resultado text, p_voltou boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_filtro_pessoas(p_organization_id uuid, p_atribuido_a uuid, p_formulario_id uuid, p_ultimo_resultado text, p_voltou boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_ganhar_interno(p_negocio_id uuid, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text, p_detalhe text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org      uuid;
  v_conv     text;
  v_sqlstate text;
  v_sqlerrm  text;
BEGIN
  SELECT n.organization_id INTO v_org FROM public.negocios n WHERE n.id = p_negocio_id;
  SELECT c.conversao_ao_ganhar INTO v_conv
  FROM public.negocio_workflow_config c WHERE c.organization_id = v_org;

  PERFORM public.fn_neg_mudar_estado(p_negocio_id, 'ganho', NULL, NULL, NULL,
    p_origem_tipo, p_origem_id, p_origem_estado, p_canal, p_prova, p_hash, p_detalhe);

  IF v_conv IS DISTINCT FROM 'automatica' THEN
    RETURN COALESCE(v_conv, 'nao_alterar');
  END IF;

  BEGIN
    PERFORM public.fn_neg_converter_pessoa(p_negocio_id, p_origem_tipo, p_origem_id);
    RETURN 'feita';
  EXCEPTION WHEN OTHERS THEN
    -- O negócio fica ganho na mesma; a ficha oferece «Converter em cliente».
    -- O evento (visível a quem lê o histórico) leva só o SQLSTATE e um texto fixo: a mensagem do Postgres pode trazer nomes de
    -- constraints, colunas ou valores. O detalhe técnico fica em workflow_execution_log.
    v_sqlstate := SQLSTATE;
    v_sqlerrm := SQLERRM;
    BEGIN
      INSERT INTO public.workflow_execution_log (
        source_entity, source_record_id, target_entity, target_record_id,
        action_type, status, error_message, execution_data
      ) VALUES (
        'negocio', p_negocio_id, 'negocio', p_negocio_id,
        'trigger:negocio_conversao', 'error', v_sqlerrm,
        jsonb_build_object('sqlstate', v_sqlstate, 'documento', p_origem_tipo, 'documento_id', p_origem_id)
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    PERFORM public.fn_neg_anotar(p_negocio_id, 'alerta', 'conversao_falhou',
      'A conversão em cliente falhou (código ' || v_sqlstate || '). Use «Converter em cliente» para repetir.',
      p_origem_tipo, p_origem_id, p_origem_estado, p_canal, NULL, NULL);
    RETURN 'falhou';
  END;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_ganhar_interno(p_negocio_id uuid, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text, p_detalhe text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_gravar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assunto text, p_texto text, p_proxima_acao_em timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_texto text := NULLIF(btrim(p_texto, E' \t\r\n'), '');
  v_ex    public.entity_interactions;
  v_n     int;
BEGIN
  IF p_id IS NULL OR p_assunto IS NULL OR p_assunto NOT IN ('Nota', 'Contacto adiado') THEN
    RAISE EXCEPTION 'Valor inválido: identificador ou assunto da nota.' USING ERRCODE = 'NG009';
  END IF;
  IF p_assunto = 'Nota'
     AND (v_texto IS NULL OR char_length(v_texto) > 2000 OR p_proxima_acao_em IS NOT NULL) THEN
    RAISE EXCEPTION 'Valor inválido: texto da nota (1 a 2000 caracteres).' USING ERRCODE = 'NG009';
  END IF;
  IF p_assunto = 'Contacto adiado' AND (v_texto IS NOT NULL OR p_proxima_acao_em IS NULL) THEN
    RAISE EXCEPTION 'Valor inválido: data da próxima acção.' USING ERRCODE = 'NG009';
  END IF;

  PERFORM public.fn_neg_exigir_config(p_organization_id);

  IF NOT (public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.create')
          OR public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit')) THEN
    RAISE EXCEPTION 'Sem permissão para registar notas nesta organização.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  -- Reenvio de um pedido já gravado: devolve-o antes da janela de datas (um
  -- adiamento reenviado mais tarde não dá um "data inválida" enganador).
  SELECT i.* INTO v_ex FROM public.entity_interactions i WHERE i.id = p_id;
  IF FOUND THEN
    IF v_ex.organization_id IS DISTINCT FROM p_organization_id
       OR v_ex.entity_id <> p_entity_id OR v_ex.interaction_type <> 'note'
       OR v_ex.subject IS DISTINCT FROM p_assunto THEN
      RAISE EXCEPTION 'Registo indisponível.' USING ERRCODE = 'NG004';
    END IF;
    RETURN false;
  END IF;

  IF p_assunto = 'Contacto adiado'
     AND (p_proxima_acao_em < now() - interval '1 day'
          OR p_proxima_acao_em > now() + interval '5 years') THEN
    RAISE EXCEPTION 'Valor inválido: data da próxima acção.' USING ERRCODE = 'NG009';
  END IF;

  INSERT INTO public.entity_interactions
    (id, entity_id, organization_id, root_organization_id, interaction_type, subject,
     notes, interaction_at, next_action_type, next_action_date, created_by)
  VALUES
    (p_id, p_entity_id, p_organization_id, public.resolve_root_organization_id(p_organization_id),
     'note', p_assunto, v_texto, now(),
     CASE WHEN p_proxima_acao_em IS NOT NULL THEN 'callback' END, p_proxima_acao_em,
     public.fn_neg_actor()::text)
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 0 THEN
    -- Corrida com outro envio do mesmo id: só vale se for desta pessoa e
    -- organização com o mesmo assunto.
    SELECT i.* INTO v_ex FROM public.entity_interactions i WHERE i.id = p_id;
    IF NOT FOUND OR v_ex.organization_id IS DISTINCT FROM p_organization_id
       OR v_ex.entity_id <> p_entity_id OR v_ex.interaction_type <> 'note'
       OR v_ex.subject IS DISTINCT FROM p_assunto THEN
      RAISE EXCEPTION 'Registo indisponível.' USING ERRCODE = 'NG004';
    END IF;
    RETURN false;
  END IF;
  RETURN true;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_gravar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assunto text, p_texto text, p_proxima_acao_em timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_gravar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assunto text, p_texto text, p_proxima_acao_em timestamp with time zone) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_heranca_permitida(p_neg negocios, p_estados text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Sem sessão (portal, assinatura, sistema): a herança do desenho.
  -- Com sessão: negócio num dos estados indicados e pessoas.edit com âmbito.
  SELECT p_neg.id IS NOT NULL
     AND (auth.uid() IS NULL
          OR (p_neg.estado = ANY (p_estados) AND public.fn_neg_pode_editar(p_neg)));
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_heranca_permitida(p_neg negocios, p_estados text[]) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_herdar_contrato()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_var  text;
  v_cand uuid;
  v_pr   uuid;
  v_qt   uuid;
  v_neg  public.negocios;
BEGIN
  IF NEW.negocio_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 1. Criado a partir do negócio (neg_criar_contrato): a variável é consumida.
  v_var := NULLIF(current_setting('app.neg_criar_contrato', true), '');
  IF v_var IS NOT NULL THEN
    PERFORM set_config('app.neg_criar_contrato', '', true);
    NEW.negocio_id := v_var::uuid;
    RETURN NEW;
  END IF;

  -- 2. Substituto: herda do contrato que substitui. Sem sessão, em qualquer
  --    estado; com sessão, pessoas.edit e negócio aberto ou ganho (o INSERT do
  --    substituto vem antes de a substituição reabrir o negócio).
  IF NEW.replaces_contract_id IS NOT NULL THEN
    SELECT o.negocio_id INTO v_cand FROM public.client_contracts o WHERE o.id = NEW.replaces_contract_id;
    IF v_cand IS NOT NULL THEN
      v_neg := public.fn_neg_negocio_para_heranca(v_cand, NEW.organization_id, NEW.entity_id);
      IF v_neg.id IS NOT NULL AND v_neg.fecho = 'contrato'
         AND public.fn_neg_heranca_permitida(v_neg, ARRAY['aberto', 'ganho']) THEN
        NEW.negocio_id := v_neg.id;
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  -- 3 e 4. Proposta e orçamento de origem.
  IF NEW.proposal_id IS NOT NULL THEN
    SELECT o.negocio_id INTO v_pr FROM public.proposals o WHERE o.id = NEW.proposal_id;
  END IF;
  IF NEW.quote_id IS NOT NULL THEN
    SELECT o.negocio_id INTO v_qt FROM public.quotes o WHERE o.id = NEW.quote_id;
  END IF;
  IF v_pr IS NULL AND v_qt IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_pr IS NOT NULL AND v_qt IS NOT NULL AND v_pr <> v_qt THEN
    -- Proposta e orçamento em negócios diferentes: não herda; alerta nos dois.
    FOREACH v_cand IN ARRAY ARRAY[v_pr, v_qt] LOOP
      v_neg := public.fn_neg_negocio_para_heranca(v_cand, NEW.organization_id, NEW.entity_id);
      IF v_neg.id IS NOT NULL THEN
        PERFORM public.fn_neg_anotar(v_neg.id, 'alerta', NULL,
          'Contrato criado de uma proposta e de um orçamento de negócios diferentes: ficou sem negócio.',
          'contrato', NEW.id, NEW.status, public.fn_neg_canal(public.fn_negocios_actor(), NULL), NULL, NULL);
      END IF;
    END LOOP;
    RETURN NEW;
  END IF;

  -- Com sessão: só num negócio aberto e com pessoas.edit; senão o contrato
  -- cria-se sem negócio.
  v_neg := public.fn_neg_negocio_para_heranca(COALESCE(v_pr, v_qt), NEW.organization_id, NEW.entity_id);
  IF v_neg.id IS NOT NULL AND v_neg.fecho = 'contrato'
     AND public.fn_neg_heranca_permitida(v_neg, ARRAY['aberto']) THEN
    NEW.negocio_id := v_neg.id;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_herdar_contrato() FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_herdar_orcamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_var  text;
  v_cand uuid;
  v_neg  public.negocios;
BEGIN
  IF NEW.negocio_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 1. Criado a partir do negócio (neg_criar_orcamento): a variável é
  --    consumida pelo primeiro INSERT (o orçamento principal de rpc_save_quote).
  v_var := NULLIF(current_setting('app.neg_criar_orcamento', true), '');
  IF v_var IS NOT NULL THEN
    PERFORM set_config('app.neg_criar_orcamento', '', true);
    NEW.negocio_id := v_var::uuid;
    RETURN NEW;
  END IF;

  -- 2. Proposta de origem (com sessão: negócio aberto e pessoas.edit; senão
  --    o orçamento cria-se sem negócio).
  IF NEW.proposal_id IS NOT NULL THEN
    SELECT o.negocio_id INTO v_cand FROM public.proposals o WHERE o.id = NEW.proposal_id;
    IF v_cand IS NOT NULL THEN
      v_neg := public.fn_neg_negocio_para_heranca(v_cand, NEW.organization_id, NEW.entity_id);
      IF v_neg.id IS NOT NULL AND public.fn_neg_heranca_permitida(v_neg, ARRAY['aberto']) THEN
        NEW.negocio_id := v_neg.id;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_herdar_orcamento() FROM PUBLIC, anon, authenticated, service_role;

