$function$;
REVOKE ALL ON FUNCTION public.fn_neg_herdar_proposta() FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_herdar_proposta_ligacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg_id uuid;
  v_org    uuid;
  v_ent    uuid;
  v_prop   uuid := NEW.proposal_id;
  v_neg    public.negocios;
BEGIN
  IF TG_TABLE_NAME = 'quotes' THEN
    IF NEW.deleted_at IS NOT NULL THEN
      RETURN NULL;
    END IF;
    v_neg_id := NEW.negocio_id;
    v_org := NEW.organization_id;
    v_ent := NEW.entity_id;
  ELSE
    IF NEW.status IS DISTINCT FROM 'active' THEN
      RETURN NULL;
    END IF;
    SELECT q.negocio_id, q.organization_id, q.entity_id INTO v_neg_id, v_org, v_ent
    FROM public.quotes q
    WHERE q.id = NEW.quote_id AND q.deleted_at IS NULL;
    -- Saída barata primeiro (caminho quente da Mudelar: nenhum orçamento tem
    -- negócio): só uma leitura por chave primária, SEM get_user_crm_org_ids.
    IF v_neg_id IS NULL OR v_prop IS NULL THEN
      RETURN NULL;
    END IF;
    -- A ligação tem de ser da organização do orçamento e, com sessão, de uma
    -- das organizações do utilizador.
    IF NEW.organization_id IS DISTINCT FROM v_org
       OR (auth.uid() IS NOT NULL
           AND (NEW.organization_id IN (SELECT public.get_user_crm_org_ids(auth.uid()))) IS NOT TRUE) THEN
      RETURN NULL;
    END IF;
  END IF;
  IF v_neg_id IS NULL OR v_prop IS NULL THEN
    RETURN NULL;
  END IF;

  -- Com sessão: só num negócio aberto e com pessoas.edit; senão a proposta
  -- fica por ligar.
  v_neg := public.fn_neg_negocio_para_heranca(v_neg_id, v_org, v_ent);
  IF v_neg.id IS NULL OR NOT public.fn_neg_heranca_permitida(v_neg, ARRAY['aberto']) THEN
    RETURN NULL;
  END IF;

  -- Nunca aborta quem chamou (o aceite do cliente no portal, em particular):
  -- um erro deixa a proposta por ligar e fica registado.
  BEGIN
    PERFORM set_config('app.neg_herdar_proposta', v_neg.id::text, true);
    UPDATE public.proposals p
    SET negocio_id = v_neg.id
    WHERE p.id = v_prop
      AND p.negocio_id IS NULL
      AND p.organization_id = v_neg.organization_id
      AND p.entity_id = v_neg.entity_id
      AND p.deleted_at IS NULL
      AND p.is_deleted IS NOT TRUE;
    PERFORM set_config('app.neg_herdar_proposta', '', true);
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.workflow_execution_log (
        source_entity, source_record_id, target_entity, target_record_id,
        action_type, status, error_message, execution_data
      ) VALUES (
        'proposal', v_prop, 'negocio', v_neg.id,
        'trigger:negocio_heranca', 'error', SQLERRM,
        jsonb_build_object('sqlstate', SQLSTATE, 'origem', TG_TABLE_NAME, 'origem_id', NEW.id)
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;
  PERFORM set_config('app.neg_herdar_proposta', '', true);

  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_herdar_proposta_ligacao() FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_houve_alteracoes(p_negocio_id uuid, p_tipo text, p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_antes text;
  v_agora text;
BEGIN
  SELECT e.conteudo_hash INTO v_antes
  FROM public.negocio_eventos e
  WHERE e.negocio_id = p_negocio_id AND e.origem_id = p_id AND e.conteudo_hash IS NOT NULL
  ORDER BY e.created_at DESC, e.id DESC
  LIMIT 1;

  IF v_antes IS NULL AND p_tipo = 'proposta' THEN
    SELECT pr.decided_snapshot_hash INTO v_antes FROM public.proposals pr WHERE pr.id = p_id;
  END IF;

  -- Sem retrato da decisão: conta como sem alterações (o lado seguro).
  IF v_antes IS NULL THEN
    RETURN false;
  END IF;

  v_agora := public.fn_neg_conteudo_hash(p_tipo, p_id);
  RETURN v_agora IS NOT NULL AND v_agora <> v_antes;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_houve_alteracoes(p_negocio_id uuid, p_tipo text, p_id uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_lead_aberta(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(p_status, '') NOT IN ('converted', 'rejected', 'lost', 'cancelled');
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_lead_aberta(p_status text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_lead_aberta(p_status text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_lead_aberta(p_status text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_momento_assinatura(p_contract_id uuid, p_ganho_em timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    cc.signature_date,
    (SELECT max(pp.signed_at) FROM public.client_contract_parties pp
     WHERE pp.contract_id = cc.id AND pp.is_signatory = true AND pp.status = 'signed'),
    cc.company_signature_date,
    cc.accepted_at,
    p_ganho_em)
  FROM public.client_contracts cc
  WHERE cc.id = p_contract_id;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_momento_assinatura(p_contract_id uuid, p_ganho_em timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_mudar_abordagem(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_resultado text, p_nota_resultado text, p_nota_texto text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lead public.anew_leads;
  v_n    int;
BEGIN
  IF p_resultado IS NOT NULL AND p_resultado NOT IN ('semInteresse', 'obraInviavel') THEN
    RAISE EXCEPTION 'Valor inválido: resultado do encerramento.' USING ERRCODE = 'NG009';
  END IF;
  IF char_length(p_nota_resultado) > 300 OR char_length(p_nota_texto) > 1000 THEN
    RAISE EXCEPTION 'Valor inválido: motivo até 300 e texto até 1000 caracteres.' USING ERRCODE = 'NG009';
  END IF;

  PERFORM public.fn_neg_exigir_config(p_organization_id);
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit') THEN
    RAISE EXCEPTION 'Sem permissão para alterar a abordagem desta pessoa.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  IF p_resultado IS NOT NULL
     AND public.fn_neg_tem_negocio_aberto(p_organization_id, p_entity_id) THEN
    RAISE EXCEPTION 'A pessoa tem negócios abertos.' USING ERRCODE = 'NG011';
  END IF;

  SELECT * INTO v_lead FROM public.fn_neg_escolher_lead(
    p_organization_id, p_entity_id, p_lead_id,
    CASE WHEN p_resultado IS NULL THEN 'fechada' ELSE 'qualquer' END);
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'Valor inválido: só as leads se encerram.' USING ERRCODE = 'NG009';
  END IF;

  IF v_lead.closure_result IS NOT DISTINCT FROM p_resultado THEN
    RETURN jsonb_build_object('mudou', false, 'lead_id', v_lead.id);
  END IF;

  UPDATE public.anew_leads l
  SET closure_result = p_resultado
  WHERE l.id = v_lead.id AND l.closure_result IS DISTINCT FROM p_resultado;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'Sem permissão para alterar a lead.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO public.entity_interactions
    (entity_id, organization_id, root_organization_id, interaction_type, subject,
     result, notes, interaction_at, created_by)
  VALUES
    (p_entity_id, p_organization_id, public.resolve_root_organization_id(p_organization_id),
     'note',
     CASE WHEN p_resultado IS NULL THEN 'Abordagem reaberta' ELSE 'Abordagem encerrada' END,
     p_nota_resultado, p_nota_texto, now(), public.fn_neg_actor()::text);

  RETURN jsonb_build_object('mudou', true, 'lead_id', v_lead.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_mudar_abordagem(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_resultado text, p_nota_resultado text, p_nota_texto text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_mudar_abordagem(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_resultado text, p_nota_resultado text, p_nota_texto text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_mudar_abordagem(p_organization_id uuid, p_entity_id uuid, p_lead_id uuid, p_resultado text, p_nota_resultado text, p_nota_texto text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_mudar_estado(p_negocio_id uuid, p_estado text, p_fase text, p_motivo text, p_motivo_reabertura text, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text, p_detalhe text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM set_config('app.neg_origem_tipo', COALESCE(p_origem_tipo, ''), true);
  PERFORM set_config('app.neg_origem_id', COALESCE(p_origem_id::text, ''), true);
  PERFORM set_config('app.neg_ev_origem_estado', COALESCE(left(p_origem_estado, 60), ''), true);
  PERFORM set_config('app.neg_ev_canal', COALESCE(p_canal, ''), true);
  PERFORM set_config('app.neg_ev_prova', COALESCE(p_prova, ''), true);
  PERFORM set_config('app.neg_ev_hash', COALESCE(p_hash, ''), true);
  PERFORM set_config('app.neg_ev_detalhe', COALESCE(left(p_detalhe, 1000), ''), true);
  IF p_motivo_reabertura IS NOT NULL THEN
    PERFORM set_config('app.negocio_motivo_reabertura', left(p_motivo_reabertura, 1000), true);
  END IF;

  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n
  SET estado = p_estado,
      fase_perda = CASE WHEN p_estado = 'perdido' THEN p_fase END,
      motivo_perda = CASE WHEN p_estado = 'perdido' THEN left(p_motivo, 1000) END
  WHERE n.id = p_negocio_id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);

  PERFORM set_config('app.neg_origem_tipo', '', true);
  PERFORM set_config('app.neg_origem_id', '', true);
  PERFORM set_config('app.neg_ev_origem_estado', '', true);
  PERFORM set_config('app.neg_ev_canal', '', true);
  PERFORM set_config('app.neg_ev_prova', '', true);
  PERFORM set_config('app.neg_ev_hash', '', true);
  PERFORM set_config('app.neg_ev_detalhe', '', true);
  PERFORM set_config('app.negocio_motivo_reabertura', '', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_mudar_estado(p_negocio_id uuid, p_estado text, p_fase text, p_motivo text, p_motivo_reabertura text, p_origem_tipo text, p_origem_id uuid, p_origem_estado text, p_canal text, p_prova text, p_hash text, p_detalhe text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_negocio_editavel(p_negocio_id uuid, p_estados text[])
 RETURNS negocios
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg public.negocios;
BEGIN
  SELECT n.* INTO v_neg
  FROM public.negocios n
  WHERE n.id = p_negocio_id AND n.deleted_at IS NULL
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
  END IF;

  PERFORM public.fn_neg_exigir_config(v_neg.organization_id);

  IF NOT (v_neg.estado = ANY (p_estados)) THEN
    RAISE EXCEPTION 'O negócio está %: esta acção não é possível.', v_neg.estado
      USING ERRCODE = 'NG002';
  END IF;
  RETURN v_neg;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_negocio_editavel(p_negocio_id uuid, p_estados text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_negocio_editavel(p_negocio_id uuid, p_estados text[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_negocio_editavel(p_negocio_id uuid, p_estados text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_negocio_para_heranca(p_negocio_id uuid, p_organization_id uuid, p_entity_id uuid)
 RETURNS negocios
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT n
  FROM public.negocios n
  WHERE n.id = p_negocio_id
    AND n.deleted_at IS NULL
    AND n.organization_id = p_organization_id
    AND n.entity_id = p_entity_id
    AND EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                WHERE c.organization_id = n.organization_id);
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_negocio_para_heranca(p_negocio_id uuid, p_organization_id uuid, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_parado_desde(p_negocio_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.client_contracts cc
                 WHERE cc.negocio_id = p_negocio_id AND cc.deleted_at IS NULL) THEN NULL
    ELSE COALESCE(
      (SELECT max(pr.created_at) FROM public.proposals pr
       WHERE pr.negocio_id = p_negocio_id AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE),
      (SELECT max(q.created_at) FROM public.quotes q
       WHERE q.negocio_id = p_negocio_id AND q.deleted_at IS NULL))
  END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_parado_desde(p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_parado_desde(p_negocio_id uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_pesquisa_pessoas(p_organization_id uuid, p_pesquisa text)
 RETURNS TABLE(entity_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid       uuid := auth.uid();
  v_q         text := NULLIF(btrim(p_pesquisa), '');
  v_padrao    text;
  v_digitos   text;
  v_keys_lead text[];
  v_keys_cli  text[];
  v_admin     boolean;
BEGIN
  IF char_length(v_q) < 2 OR char_length(v_q) > 200 THEN
    RAISE EXCEPTION 'Valor inválido: pesquisa (2 a 200 caracteres).' USING ERRCODE = 'NG009';
  END IF;
  IF v_q IS NULL THEN
    RETURN;
  END IF;
  SELECT a.chaves_lead, a.chaves_cliente, a.admin
    INTO v_keys_lead, v_keys_cli, v_admin
  FROM public.fn_neg_ambito_pessoas(p_organization_id) a;
  IF cardinality(v_keys_lead) + cardinality(v_keys_cli) = 0 THEN
    RETURN;
  END IF;

  v_padrao := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  IF v_q ~ '^[0-9 +().-]+$' THEN
    v_digitos := regexp_replace(v_q, '\D', '', 'g');
    IF char_length(v_digitos) < 7 THEN
      v_digitos := NULL;
    END IF;
  END IF;

  RETURN QUERY
  SELECT p.ent
  FROM (
    SELECT l.entity_id AS ent
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
      AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
           OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
           OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead))
    UNION
    SELECT c.entity_id
    FROM public.anew_clients c
    WHERE c.organization_id = p_organization_id AND c.deleted_at IS NULL
      AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
           OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
           OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli))
  ) p
  WHERE (NOT v_admin
         OR EXISTS (SELECT 1 FROM public.anew_entity_roles er
                    WHERE er.entity_id = p.ent AND er.deleted_at IS NULL
                      AND er.organization_id IN (SELECT public.get_user_visible_org_ids(v_uid))))
    AND (EXISTS (SELECT 1 FROM public.anew_entities e
                 WHERE e.id = p.ent AND e.display_name ILIKE v_padrao ESCAPE '\')
         OR EXISTS (SELECT 1 FROM public.anew_entity_emails em
                    WHERE em.entity_id = p.ent AND em.email ILIKE v_padrao ESCAPE '\')
         OR (v_digitos IS NOT NULL AND EXISTS (
               SELECT 1
               FROM public.anew_entity_phones ph
               CROSS JOIN LATERAL (SELECT regexp_replace(ph.phone_number, '\D', '', 'g') AS d) x
               WHERE ph.entity_id = p.ent AND char_length(x.d) >= 7
                 AND (x.d LIKE '%' || v_digitos OR v_digitos LIKE '%' || x.d))));
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_pesquisa_pessoas(p_organization_id uuid, p_pesquisa text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_pesquisa_pessoas(p_organization_id uuid, p_pesquisa text) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_pode_editar(p_neg negocios)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT auth.uid() IS NOT NULL
     AND p_neg.id IS NOT NULL
     AND p_neg.organization_id IN (SELECT public.get_user_crm_org_ids(auth.uid()))
     AND public.has_anew_permission(auth.uid(), 'pessoas.edit')
     AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
                 WHERE k.scope_key = p_neg.organization_id::text || ':*'
                    OR k.scope_key = p_neg.organization_id::text || ':' || p_neg.assigned_to::text
                    OR k.scope_key = p_neg.organization_id::text || ':' || p_neg.created_by::text);
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_pode_editar(p_neg negocios) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_pode_mudar_dono_lead(p_visita_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_org    uuid;
  v_lead   uuid;
  v_meta   text;
  v_criou  uuid;
  v_user   uuid;
  v_leads  uuid[];
  v_keys   text[];
BEGIN
  SELECT s.organization_id, s.lead_id, s.metadata ->> 'lead_id', s.created_by, s.user_id
    INTO v_org, v_lead, v_meta, v_criou, v_user
  FROM public.schedule_items s
  WHERE s.id = p_visita_id;
  IF v_uid IS NULL OR v_org IS NULL
     OR NOT (v_org IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c WHERE c.organization_id = v_org) THEN
    RETURN false;
  END IF;

  -- Sem pessoas.edit com âmbito sobre a visita (o mesmo teste de
  -- fn_neg_visita_editavel), false sem olhar para leads: não é oráculo.
  IF NOT (public.has_anew_permission(v_uid, 'pessoas.edit')
          AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
                      WHERE k.scope_key = v_org::text || ':*'
                         OR k.scope_key = v_org::text || ':' || v_criou::text
                         OR k.scope_key = v_org::text || ':' || v_user::text)) THEN
    RETURN false;
  END IF;

  IF v_lead IS NOT NULL THEN
    v_leads := ARRAY[v_lead];
  ELSIF v_meta ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_leads := ARRAY[v_meta::uuid];
  ELSE
    v_leads := ARRAY(SELECT l.id FROM public.anew_leads l WHERE l.scheduled_visit_id = p_visita_id);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.anew_leads l
                 WHERE l.id = ANY (v_leads) AND l.organization_id = v_org AND l.deleted_at IS NULL) THEN
    RETURN true;
  END IF;

  IF NOT public.has_anew_permission(v_uid, 'leads.edit') THEN
    RETURN false;
  END IF;
  v_keys := public.crm_scope_keys('leads.edit');
  RETURN NOT EXISTS (
    SELECT 1 FROM public.anew_leads l
    WHERE l.id = ANY (v_leads) AND l.organization_id = v_org AND l.deleted_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM unnest(v_keys) AS k(scope_key)
                      WHERE k.scope_key = l.organization_id::text || ':*'
                         OR k.scope_key = l.organization_id::text || ':' || l.assigned_to::text
                         OR k.scope_key = l.organization_id::text || ':' || l.created_by::text));
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_pode_mudar_dono_lead(p_visita_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_pode_mudar_dono_lead(p_visita_id uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_positivo_decisivo(p_neg negocios)
 RETURNS TABLE(tipo text, id uuid, estado text, prova text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_neg.fecho = 'proposta' THEN
    RETURN QUERY
    SELECT 'proposta'::text, pr.id, pr.status,
           COALESCE(public.fn_neg_prova_proposta(pr.id, NULL),
                    (SELECT e.prova FROM public.negocio_eventos e
                     WHERE e.negocio_id = p_neg.id AND e.origem_id = pr.id
                       AND e.origem_estado = 'accepted' AND e.prova IS NOT NULL
                     ORDER BY e.created_at DESC, e.id DESC LIMIT 1))
    FROM public.proposals pr
    WHERE pr.negocio_id = p_neg.id AND pr.status = 'accepted'
      AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
      AND COALESCE(public.fn_neg_prova_proposta(pr.id, NULL),
                   (SELECT e.prova FROM public.negocio_eventos e
                    WHERE e.negocio_id = p_neg.id AND e.origem_id = pr.id
                      AND e.origem_estado = 'accepted' AND e.prova IS NOT NULL
                    ORDER BY e.created_at DESC, e.id DESC LIMIT 1)) IS NOT NULL
    ORDER BY pr.accepted_at DESC NULLS LAST, pr.id
    LIMIT 1;
  ELSE
    RETURN QUERY
    SELECT 'contrato'::text, cc.id, cc.status, public.fn_neg_prova_contrato(cc.id)
    FROM public.client_contracts cc
    WHERE cc.negocio_id = p_neg.id AND cc.status IN ('signed', 'assinado', 'active')
      AND cc.deleted_at IS NULL AND cc.replaced_by_contract_id IS NULL
      AND public.fn_neg_prova_contrato(cc.id) IS NOT NULL
    ORDER BY public.fn_neg_momento_assinatura(cc.id, NULL) DESC NULLS LAST, cc.id
    LIMIT 1;
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_positivo_decisivo(p_neg negocios) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_prova_contrato(p_contract_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cc public.client_contracts;
BEGIN
  SELECT cc.* INTO v_cc FROM public.client_contracts cc WHERE cc.id = p_contract_id;
  IF NOT FOUND OR v_cc.status IS NULL OR v_cc.status NOT IN ('signed', 'assinado', 'active') THEN
    RETURN NULL;
  END IF;
  -- P1: assinatura do cliente no portal.
  IF v_cc.signature_date IS NOT NULL
     AND NULLIF(btrim(v_cc.signed_by_name), '') IS NOT NULL
     AND NULLIF(btrim(v_cc.signature_image), '') IS NOT NULL THEN
    RETURN 'P1';
  END IF;
  -- P2: todas as partes signatárias assinaram (validate-contract-signature).
  IF EXISTS (SELECT 1 FROM public.client_contract_parties pp
             WHERE pp.contract_id = v_cc.id AND pp.is_signatory = true)
     AND NOT EXISTS (SELECT 1 FROM public.client_contract_parties pp
                     WHERE pp.contract_id = v_cc.id AND pp.is_signatory = true
                       AND (pp.status IS DISTINCT FROM 'signed' OR pp.signed_at IS NULL)) THEN
    RETURN 'P2';
  END IF;
  -- P3: «Marcar como Assinado» (assinatura da empresa).
  IF v_cc.company_signature_date IS NOT NULL AND v_cc.company_signed_by_id IS NOT NULL THEN
    RETURN 'P3';
  END IF;
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_prova_contrato(p_contract_id uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_prova_proposta(p_proposal_id uuid, p_actor uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_status text;
  v_assin  text;
  v_aceite timestamptz;
BEGIN
  SELECT pr.status, pr.signature_image, pr.accepted_at
    INTO v_status, v_assin, v_aceite
  FROM public.proposals pr WHERE pr.id = p_proposal_id;
  IF NOT FOUND OR v_status IS DISTINCT FROM 'accepted' THEN
    RETURN NULL;
  END IF;
  IF NULLIF(btrim(v_assin), '') IS NOT NULL AND v_aceite IS NOT NULL THEN
    RETURN 'P1';
  END IF;
  IF p_actor IS NOT NULL THEN
    RETURN 'utilizador';
  END IF;
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_prova_proposta(p_proposal_id uuid, p_actor uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_proximo_contacto(p_organization_id uuid, p_entity_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT i.next_action_date
  FROM public.entity_interactions i
  WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id
    AND (i.interaction_type = 'call'
         OR (i.interaction_type = 'note' AND i.next_action_type = 'callback'))
  ORDER BY i.interaction_at DESC, i.id DESC
  LIMIT 1;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_proximo_contacto(p_organization_id uuid, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_proximo_contacto(p_organization_id uuid, p_entity_id uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_booleano(p_valor jsonb, p_omissao boolean, p_campo text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_valor IS NULL OR jsonb_typeof(p_valor) = 'null' THEN
    RETURN p_omissao;
  END IF;
  IF jsonb_typeof(p_valor) <> 'boolean' THEN
    RAISE EXCEPTION 'Questionário inválido: % tem de ser verdadeiro ou falso.', p_campo USING ERRCODE = 'NG009';
  END IF;
  RETURN (p_valor #>> '{}')::boolean;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_booleano(p_valor jsonb, p_omissao boolean, p_campo text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_ident(p_valor jsonb, p_formato text, p_campo text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_re_uuid CONSTANT text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  c_re_ref  CONSTANT text := '^[A-Za-z0-9_]{1,40}$';
  v text;
BEGIN
  IF p_valor IS NULL OR jsonb_typeof(p_valor) = 'null' THEN
    RETURN NULL;
  END IF;
  IF jsonb_typeof(p_valor) <> 'string' THEN
    RAISE EXCEPTION 'Questionário inválido: % tem de ser texto.', p_campo USING ERRCODE = 'NG009';
  END IF;
  v := p_valor #>> '{}';
  IF v ~ c_re_uuid AND p_formato IN ('id', 'id_ou_ref') THEN
    RETURN lower(v);
  END IF;
  IF v ~ c_re_ref AND p_formato IN ('ref', 'id_ou_ref') THEN
    RETURN v;
  END IF;
  RAISE EXCEPTION 'Questionário inválido: % com formato errado.', p_campo USING ERRCODE = 'NG009';
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_ident(p_valor jsonb, p_formato text, p_campo text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_normalizar(p_seccoes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_max_bytes     CONSTANT integer := 262144;
  c_max_seccoes   CONSTANT integer := 20;
  c_max_perguntas CONSTANT integer := 150;
  c_max_opcoes    CONSTANT integer := 30;
  c_max_numero    CONSTANT numeric := 99999999999.999;
  c_tipos     CONSTANT text[] := ARRAY['escolha_unica', 'escolha_multipla', 'texto', 'numero'];
  c_chaves_s  CONSTANT text[] := ARRAY['id', 'ref', 'titulo', 'aba', 'especial', 'activa', 'perguntas'];
  c_chaves_p  CONSTANT text[] := ARRAY['id', 'ref', 'texto', 'tipo', 'bloco', 'activa', 'numero',
                                       'texto_max', 'depende', 'opcoes'];
  c_chaves_o  CONSTANT text[] := ARRAY['id', 'ref', 'texto', 'activa'];
  c_chaves_n  CONSTANT text[] := ARRAY['min', 'max', 'casas', 'unidade'];
  c_chaves_d  CONSTANT text[] := ARRAY['pergunta', 'opcoes', 'sem_resposta'];
  v_s     jsonb;
  v_q     jsonb;
  v_o     jsonb;
  v_x     jsonb;
  v_dep   jsonb;
  v_out   jsonb := '[]'::jsonb;
  v_qs    jsonb;
  v_os    jsonb;
  v_ids   text[] := ARRAY[]::text[];
  v_refs  text[] := ARRAY[]::text[];
  v_sid   text;
  v_sref  text;
  v_pid   text;
  v_pref  text;
  v_oid   text;
  v_oref  text;
  v_tipo  text;
  v_aba   text;
  v_esp   text;
  v_min   numeric;
  v_max   numeric;
  v_casas numeric;
  v_tmax  numeric;
  v_unid  text;
  v_np    integer := 0;
BEGIN
  IF p_seccoes IS NULL OR jsonb_typeof(p_seccoes) <> 'array'
     OR octet_length(p_seccoes::text) > c_max_bytes THEN
    RAISE EXCEPTION 'Questionário inválido: lista de secções (até 256 KB).' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_array_length(p_seccoes) < 1 OR jsonb_array_length(p_seccoes) > c_max_seccoes THEN
    RAISE EXCEPTION 'Questionário inválido: de 1 a 20 secções.' USING ERRCODE = 'NG009';
  END IF;

  FOR v_s IN SELECT e.value FROM jsonb_array_elements(p_seccoes) WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
  LOOP
    PERFORM public.fn_neg_questionario_objecto(v_s, c_chaves_s, 'secção');
    v_sid  := public.fn_neg_questionario_ident(v_s -> 'id', 'id', 'id da secção');
    v_sref := public.fn_neg_questionario_ident(v_s -> 'ref', 'ref', 'ref da secção');
    IF v_sid = ANY (v_ids) OR v_sref = ANY (v_refs) THEN
      RAISE EXCEPTION 'Questionário inválido: id ou ref repetido.' USING ERRCODE = 'NG009';
    END IF;
    IF v_sid IS NOT NULL THEN v_ids := v_ids || v_sid; END IF;
    IF v_sref IS NOT NULL THEN v_refs := v_refs || v_sref; END IF;

    v_aba := public.fn_neg_questionario_texto(v_s -> 'aba', 20, true, 'aba');
    v_esp := public.fn_neg_questionario_texto(v_s -> 'especial', 20, true, 'tipo especial');
    IF v_aba IS NOT NULL AND v_aba NOT IN ('visita', 'qualificacao') THEN
      RAISE EXCEPTION 'Questionário inválido: aba desconhecida.' USING ERRCODE = 'NG009';
    END IF;
    IF v_esp IS NOT NULL AND v_esp NOT IN ('visitas', 'medidas') THEN
      RAISE EXCEPTION 'Questionário inválido: tipo especial desconhecido.' USING ERRCODE = 'NG009';
    END IF;

    v_x := v_s -> 'perguntas';
    IF v_x IS NULL OR jsonb_typeof(v_x) = 'null' THEN
      v_x := '[]'::jsonb;
    END IF;
    IF jsonb_typeof(v_x) <> 'array' THEN
      RAISE EXCEPTION 'Questionário inválido: as perguntas de uma secção são uma lista.' USING ERRCODE = 'NG009';
    END IF;

    v_qs := '[]'::jsonb;
    FOR v_q IN SELECT e.value FROM jsonb_array_elements(v_x) WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
    LOOP
      v_np := v_np + 1;
      IF v_np > c_max_perguntas THEN
        RAISE EXCEPTION 'Questionário inválido: até 150 perguntas.' USING ERRCODE = 'NG009';
      END IF;
      PERFORM public.fn_neg_questionario_objecto(v_q, c_chaves_p, 'pergunta');
      v_pid  := public.fn_neg_questionario_ident(v_q -> 'id', 'id', 'id da pergunta');
      v_pref := public.fn_neg_questionario_ident(v_q -> 'ref', 'ref', 'ref da pergunta');
      IF v_pid = ANY (v_ids) OR v_pref = ANY (v_refs) THEN
        RAISE EXCEPTION 'Questionário inválido: id ou ref repetido.' USING ERRCODE = 'NG009';
      END IF;
      IF v_pid IS NOT NULL THEN v_ids := v_ids || v_pid; END IF;
      IF v_pref IS NOT NULL THEN v_refs := v_refs || v_pref; END IF;

      v_tipo := public.fn_neg_questionario_texto(v_q -> 'tipo', 20, false, 'tipo da pergunta');
      IF v_tipo <> ALL (c_tipos) THEN
        RAISE EXCEPTION 'Questionário inválido: tipo de pergunta desconhecido.' USING ERRCODE = 'NG009';
      END IF;

      -- Número: limites, casas decimais e unidade (só em perguntas de número).
      v_min := NULL; v_max := NULL; v_casas := NULL; v_unid := NULL;
      v_x := v_q -> 'numero';
      IF v_x IS NOT NULL AND jsonb_typeof(v_x) <> 'null' THEN
        IF v_tipo <> 'numero' THEN
          RAISE EXCEPTION 'Questionário inválido: só as perguntas de número têm limites.' USING ERRCODE = 'NG009';
        END IF;
        PERFORM public.fn_neg_questionario_objecto(v_x, c_chaves_n, 'limites do número');
        v_min   := public.fn_neg_questionario_numero(v_x -> 'min', 'mínimo');
        v_max   := public.fn_neg_questionario_numero(v_x -> 'max', 'máximo');
        v_casas := public.fn_neg_questionario_numero(v_x -> 'casas', 'casas decimais');
        v_unid  := public.fn_neg_questionario_texto(v_x -> 'unidade', 12, true, 'unidade');
        IF abs(v_min) > c_max_numero OR v_min <> round(v_min, 3)
           OR abs(v_max) > c_max_numero OR v_max <> round(v_max, 3)
           OR v_min > v_max
           OR v_casas <> trunc(v_casas) OR v_casas < 0 OR v_casas > 3 THEN
          RAISE EXCEPTION 'Questionário inválido: limites do número (mínimo até máximo, até 3 casas decimais).'
            USING ERRCODE = 'NG009';
        END IF;
      END IF;

      v_tmax := public.fn_neg_questionario_numero(v_q -> 'texto_max', 'tamanho do texto');
      IF v_tmax IS NOT NULL
         AND (v_tipo <> 'texto' OR v_tmax <> trunc(v_tmax) OR v_tmax < 1 OR v_tmax > 2000) THEN
        RAISE EXCEPTION 'Questionário inválido: tamanho do texto (1 a 2000, só em perguntas de texto).'
          USING ERRCODE = 'NG009';
      END IF;

      -- Opções: 2 a 30 nas perguntas de escolha; nenhuma nas outras.
      v_x := v_q -> 'opcoes';
      IF v_x IS NULL OR jsonb_typeof(v_x) = 'null' THEN
        v_x := '[]'::jsonb;
      END IF;
      IF jsonb_typeof(v_x) <> 'array' THEN
        RAISE EXCEPTION 'Questionário inválido: as opções são uma lista.' USING ERRCODE = 'NG009';
      END IF;
      IF v_tipo IN ('escolha_unica', 'escolha_multipla') THEN
        IF jsonb_array_length(v_x) < 2 OR jsonb_array_length(v_x) > c_max_opcoes THEN
          RAISE EXCEPTION 'Questionário inválido: uma pergunta de escolha tem de 2 a 30 opções.' USING ERRCODE = 'NG009';
        END IF;
      ELSIF jsonb_array_length(v_x) > 0 THEN
        RAISE EXCEPTION 'Questionário inválido: só as perguntas de escolha têm opções.' USING ERRCODE = 'NG009';
      END IF;

      v_os := '[]'::jsonb;
      FOR v_o IN SELECT e.value FROM jsonb_array_elements(v_x) WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
      LOOP
        PERFORM public.fn_neg_questionario_objecto(v_o, c_chaves_o, 'opção');
        v_oid  := public.fn_neg_questionario_ident(v_o -> 'id', 'id', 'id da opção');
        v_oref := public.fn_neg_questionario_ident(v_o -> 'ref', 'ref', 'ref da opção');
        IF v_oid = ANY (v_ids) OR v_oref = ANY (v_refs) THEN
          RAISE EXCEPTION 'Questionário inválido: id ou ref repetido.' USING ERRCODE = 'NG009';
        END IF;
        IF v_oid IS NOT NULL THEN v_ids := v_ids || v_oid; END IF;
        IF v_oref IS NOT NULL THEN v_refs := v_refs || v_oref; END IF;
        v_os := v_os || jsonb_build_array(jsonb_build_object(
          'id', v_oid, 'ref', v_oref,
          'texto', public.fn_neg_questionario_texto(v_o -> 'texto', 80, false, 'texto da opção'),
          'activa', public.fn_neg_questionario_booleano(v_o -> 'activa', true, 'activa')));
      END LOOP;

      -- Condição (um nível; resolvida e conferida na gravação).
      v_dep := NULL;
      v_x := v_q -> 'depende';
      IF v_x IS NOT NULL AND jsonb_typeof(v_x) <> 'null' THEN
        PERFORM public.fn_neg_questionario_objecto(v_x, c_chaves_d, 'condição');
        IF jsonb_typeof(v_x -> 'opcoes') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'Questionário inválido: as opções da condição são uma lista.' USING ERRCODE = 'NG009';
        END IF;
        IF jsonb_array_length(v_x -> 'opcoes') < 1 OR jsonb_array_length(v_x -> 'opcoes') > c_max_opcoes THEN
          RAISE EXCEPTION 'Questionário inválido: a condição tem de 1 a 30 opções.' USING ERRCODE = 'NG009';
        END IF;
        v_dep := jsonb_build_object(
          'pergunta', public.fn_neg_questionario_ident(v_x -> 'pergunta', 'id_ou_ref', 'pergunta da condição'),
          'opcoes', (SELECT jsonb_agg(public.fn_neg_questionario_ident(e.value, 'id_ou_ref', 'opção da condição')
                                      ORDER BY e.ord)
                     FROM jsonb_array_elements(v_x -> 'opcoes') WITH ORDINALITY AS e(value, ord)),
          'sem_resposta', public.fn_neg_questionario_booleano(v_x -> 'sem_resposta', false, 'sem resposta'));
        IF v_dep ->> 'pergunta' IS NULL OR (v_dep -> 'opcoes') @> '[null]'::jsonb THEN
          RAISE EXCEPTION 'Questionário inválido: condição sem pergunta ou com opção vazia.' USING ERRCODE = 'NG009';
        END IF;
      END IF;

      v_qs := v_qs || jsonb_build_array(jsonb_build_object(
        'id', v_pid, 'ref', v_pref,
        'texto', public.fn_neg_questionario_texto(v_q -> 'texto', 200, false, 'texto da pergunta'),
        'tipo', v_tipo,
        'bloco', public.fn_neg_questionario_texto(v_q -> 'bloco', 80, true, 'subtítulo'),
        'activa', public.fn_neg_questionario_booleano(v_q -> 'activa', true, 'activa'),
        'numero_min', v_min, 'numero_max', v_max, 'numero_casas', v_casas::integer, 'unidade', v_unid,
        'texto_max', v_tmax::integer, 'depende', v_dep, 'opcoes', v_os));
    END LOOP;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'id', v_sid, 'ref', v_sref,
      'titulo', public.fn_neg_questionario_texto(v_s -> 'titulo', 80, false, 'título da secção'),
      'aba', v_aba, 'especial', v_esp,
      'activa', public.fn_neg_questionario_booleano(v_s -> 'activa', true, 'activa'),
      'perguntas', v_qs));
  END LOOP;

  RETURN v_out;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_normalizar(p_seccoes jsonb) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_questionario_normalizar(p_seccoes jsonb) IS 'Pessoas, levantamento configurável: valida a forma de p_seccoes de neg_guardar_questionario (NG009) e devolve-a normalizada. Uso interno. 20261226090000.';

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_numero(p_valor jsonb, p_campo text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_valor IS NULL OR jsonb_typeof(p_valor) = 'null' THEN
    RETURN NULL;
  END IF;
  IF jsonb_typeof(p_valor) <> 'number' THEN
    RAISE EXCEPTION 'Questionário inválido: % tem de ser um número.', p_campo USING ERRCODE = 'NG009';
  END IF;
  RETURN (p_valor #>> '{}')::numeric;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_numero(p_valor jsonb, p_campo text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_objecto(p_valor jsonb, p_chaves text[], p_campo text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_valor IS NULL OR jsonb_typeof(p_valor) <> 'object' THEN
    RAISE EXCEPTION 'Questionário inválido: % tem de ser um objecto.', p_campo USING ERRCODE = 'NG009';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_valor) AS k(chave) WHERE k.chave <> ALL (p_chaves)) THEN
    RAISE EXCEPTION 'Questionário inválido: % com campos desconhecidos.', p_campo USING ERRCODE = 'NG009';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_objecto(p_valor jsonb, p_chaves text[], p_campo text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_questionario_texto(p_valor jsonb, p_max integer, p_nulo boolean, p_campo text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v text;
BEGIN
  IF p_valor IS NULL OR jsonb_typeof(p_valor) = 'null' THEN
    IF p_nulo THEN
      RETURN NULL;
    END IF;
    RAISE EXCEPTION 'Questionário inválido: falta %.', p_campo USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_typeof(p_valor) <> 'string' THEN
    RAISE EXCEPTION 'Questionário inválido: % tem de ser texto.', p_campo USING ERRCODE = 'NG009';
  END IF;
  v := btrim(p_valor #>> '{}');
  IF v = '' THEN
    IF p_nulo THEN
      RETURN NULL;
    END IF;
    RAISE EXCEPTION 'Questionário inválido: falta %.', p_campo USING ERRCODE = 'NG009';
  END IF;
  IF char_length(v) > p_max OR v ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Questionário inválido: % com mais de % caracteres ou com caracteres de controlo.', p_campo, p_max
      USING ERRCODE = 'NG009';
  END IF;
  RETURN v;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_questionario_texto(p_valor jsonb, p_max integer, p_nulo boolean, p_campo text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_regra_qualificacao(p_regra jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  -- Os tipos que o separador «Qualificação» de Leads grava hoje
  -- (QUALIFICATION_LEGACY_KEYS), todos no CASE de evaluate_condition.
  c_tipos CONSTANT text[] := ARRAY[
    'has_assignee', 'has_source', 'has_contact_logged', 'has_scheduled_visit',
    'has_active_deal', 'has_active_quote', 'has_active_proposal',
    'has_signed_contract', 'qualification_is', 'last_contact_is_negative',
    'last_contact_is_positive'];
  c_max_condicoes CONSTANT integer := 50;
  v_chave text;
  v_elem  jsonb;
BEGIN
  IF p_regra IS NULL OR jsonb_typeof(p_regra) = 'null' THEN
    RETURN NULL;
  END IF;

  -- Duas verificações separadas: jsonb_object_keys sobre um escalar dá erro,
  -- e um OR não garante a ordem de avaliação.
  IF jsonb_typeof(p_regra) <> 'object' THEN
    RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_regra) AS k(chave)
             WHERE k.chave NOT IN ('all', 'any')) THEN
    RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
  END IF;

  FOREACH v_chave IN ARRAY ARRAY['all', 'any']
  LOOP
    CONTINUE WHEN NOT (p_regra ? v_chave);

    IF jsonb_typeof(p_regra -> v_chave) <> 'array'
       OR jsonb_array_length(p_regra -> v_chave) > c_max_condicoes THEN
      RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
    END IF;

    FOR v_elem IN SELECT e.elem FROM jsonb_array_elements(p_regra -> v_chave) AS e(elem)
    LOOP
      IF jsonb_typeof(v_elem) <> 'object' THEN
        RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
      END IF;
      IF jsonb_typeof(v_elem -> 'type') IS DISTINCT FROM 'string'
         OR NOT ((v_elem ->> 'type') = ANY (c_tipos))
         OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_elem) AS k(chave)
                    WHERE k.chave NOT IN ('type', 'value'))
         OR ((v_elem ->> 'type') = 'qualification_is'
             AND (jsonb_typeof(v_elem -> 'value') IS DISTINCT FROM 'string'
                  OR NOT ((v_elem ->> 'value') IN ('mql', 'sql'))))
         OR ((v_elem ->> 'type') <> 'qualification_is' AND v_elem ? 'value') THEN
        RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
      END IF;
    END LOOP;
  END LOOP;

  -- Só objectos válidos chegam aqui: a normalização apenas remove duplicados,
  -- põe as duas chaves e devolve NULL quando não sobra nenhuma condição.
  RETURN public.fn_normalize_lead_rule(p_regra);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_regra_qualificacao(p_regra jsonb) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_regra_qualificacao(p_regra jsonb) IS 'Pessoas, Workflow, Qualificação: valida uma regra MQL/SQL (só objectos {type} dos 12 tipos do separador de Leads; qualification_is com value mql/sql; até 50 por lista) e devolve a forma de fn_normalize_lead_rule. NG009 se inválida. Uso interno de neg_guardar_regras_qualificacao. 20261226030000.';

