      {"chave": "decisor", "texto": "Quem decide", "bloco": null, "opcoes": [{"chave": "proprio", "texto": "O próprio"}, {"chave": "familia", "texto": "Com a família"}, {"chave": "administracao", "texto": "Administração"}], "se": null},
      {"chave": "orcCliente", "texto": "Orçamento do cliente", "bloco": null, "opcoes": [{"chave": "ate3000", "texto": "Até 3.000 €"}, {"chave": "de3000a6000", "texto": "3.000 a 6.000 €"}, {"chave": "de6000a10000", "texto": "6.000 a 10.000 €"}, {"chave": "mais10000", "texto": "Mais de 10.000 €"}, {"chave": "naoSabe", "texto": "Não sabe"}], "se": null},
      {"chave": "prazo", "texto": "Para quando", "bloco": null, "opcoes": [{"chave": "urgente", "texto": "Urgente (1 mês)"}, {"chave": "de1a3", "texto": "1 a 3 meses"}, {"chave": "de3a6", "texto": "3 a 6 meses"}, {"chave": "semPressa", "texto": "Sem pressa"}], "se": null},
      {"chave": "outrosOrc", "texto": "Pediu outros orçamentos", "bloco": null, "opcoes": [{"chave": "sim", "texto": "Sim"}, {"chave": "nao", "texto": "Não"}], "se": null}
    ]}
  ]$catalogo$::jsonb;
  v_s integer;
  v_p integer;
  v_o integer;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Sementeira do questionário: falta a organização.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c WHERE c.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Sementeira do questionário: a organização não tem a página Pessoas activa.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.levantamento_questionario q WHERE q.organization_id = p_organization_id) THEN
    RETURN jsonb_build_object('semeado', false);
  END IF;

  INSERT INTO public.levantamento_questionario (organization_id, versao) VALUES (p_organization_id, 1);

  INSERT INTO public.levantamento_seccoes (organization_id, chave, titulo, aba, especial, ordem)
  SELECT p_organization_id, s.value ->> 'chave', s.value ->> 'titulo', s.value ->> 'aba',
         s.value ->> 'especial', (s.ord - 1)::integer
  FROM jsonb_array_elements(c_catalogo) WITH ORDINALITY AS s(value, ord);
  GET DIAGNOSTICS v_s = ROW_COUNT;

  INSERT INTO public.levantamento_perguntas (organization_id, seccao_id, chave, texto, bloco, tipo, ordem)
  SELECT p_organization_id, ls.id, q.value ->> 'chave', q.value ->> 'texto', q.value ->> 'bloco',
         'escolha_unica', (q.ord - 1)::integer
  FROM jsonb_array_elements(c_catalogo) AS s(value)
  JOIN public.levantamento_seccoes ls
    ON ls.organization_id = p_organization_id AND ls.chave = s.value ->> 'chave'
  CROSS JOIN LATERAL jsonb_array_elements(s.value -> 'perguntas') WITH ORDINALITY AS q(value, ord);
  GET DIAGNOSTICS v_p = ROW_COUNT;

  INSERT INTO public.levantamento_opcoes (organization_id, pergunta_id, chave, texto, ordem)
  SELECT p_organization_id, lp.id, o.value ->> 'chave', o.value ->> 'texto', (o.ord - 1)::integer
  FROM jsonb_array_elements(c_catalogo) AS s(value)
  CROSS JOIN LATERAL jsonb_array_elements(s.value -> 'perguntas') AS q(value)
  JOIN public.levantamento_perguntas lp
    ON lp.organization_id = p_organization_id AND lp.chave = q.value ->> 'chave'
  CROSS JOIN LATERAL jsonb_array_elements(q.value -> 'opcoes') WITH ORDINALITY AS o(value, ord);
  GET DIAGNOSTICS v_o = ROW_COUNT;

  -- As condições (um nível): a pergunta aparece se a outra tiver uma destas opções
  -- (e também sem resposta, quando o código tinha a chave vazia "").
  UPDATE public.levantamento_perguntas lp
  SET depende_de = alvo.id,
      depende_opcoes = ARRAY(SELECT jsonb_array_elements_text(q.value -> 'se' -> 'opcoes')),
      depende_sem_resposta = (q.value -> 'se' ->> 'sem_resposta')::boolean
  FROM jsonb_array_elements(c_catalogo) AS s(value)
  CROSS JOIN LATERAL jsonb_array_elements(s.value -> 'perguntas') AS q(value)
  JOIN public.levantamento_perguntas alvo
    ON alvo.organization_id = p_organization_id AND alvo.chave = q.value -> 'se' ->> 'pergunta'
  WHERE jsonb_typeof(q.value -> 'se') = 'object'
    AND lp.organization_id = p_organization_id AND lp.chave = q.value ->> 'chave';

  RETURN jsonb_build_object('semeado', true, 'seccoes', v_s, 'perguntas', v_p, 'opcoes', v_o);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_semear_questionario(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_semear_questionario(p_organization_id uuid) IS 'Pessoas, levantamento configurável: copia o catálogo de hoje (8 secções, 36 perguntas de escolha única, 109 opções, 3 condições; textos pt) para uma organização com negocio_workflow_config e sem questionário; devolve {semeado}. Só para migrations (sem EXECUTE para ninguém além do dono). 20261226070000.';

CREATE OR REPLACE FUNCTION public.fn_neg_tem_lead_aberta(p_organization_id uuid, p_entity_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Não é um oráculo: só para quem tem leads.create nesta organização e só
  -- em organizações com a página Pessoas activa (mesma mensagem para tudo).
  IF v_uid IS NULL OR p_organization_id IS NULL
     OR NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.fn_neg_tem_permissao_org(p_organization_id, 'leads.create')
     OR NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                    WHERE c.organization_id = p_organization_id)
     OR p_entity_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.anew_entity_org_links lk
                    WHERE lk.entity_id = p_entity_id AND lk.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
      AND l.deleted_at IS NULL AND public.fn_neg_lead_aberta(l.status::text));
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_tem_lead_aberta(p_organization_id uuid, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_tem_lead_aberta(p_organization_id uuid, p_entity_id uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_neg_tem_negocio_aberto(p_organization_id uuid, p_entity_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Não é um oráculo: só para quem tem pessoas.edit nesta organização e só
  -- em organizações com a página Pessoas activa (mesma mensagem para tudo).
  IF v_uid IS NULL OR p_organization_id IS NULL
     OR NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit')
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                    WHERE c.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.negocios n
    WHERE n.organization_id = p_organization_id AND n.entity_id = p_entity_id
      AND n.estado = 'aberto' AND n.deleted_at IS NULL);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_tem_negocio_aberto(p_organization_id uuid, p_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_tem_negocio_aberto(p_organization_id uuid, p_entity_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_tem_negocio_aberto(p_organization_id uuid, p_entity_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_tem_permissao_org(p_organization_id uuid, p_codigo text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_organization_id IS NOT NULL
     AND public.has_anew_permission(auth.uid(), p_codigo)
     AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys(p_codigo)) AS k(scope_key)
                 WHERE starts_with(k.scope_key, p_organization_id::text || ':'));
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_tem_permissao_org(p_organization_id uuid, p_codigo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_tem_permissao_org(p_organization_id uuid, p_codigo text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_tem_permissao_org(p_organization_id uuid, p_codigo text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_tem_positivo_activo(p_neg negocios, p_excluir uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.proposals pr
                 WHERE pr.negocio_id = p_neg.id AND pr.id IS DISTINCT FROM p_excluir
                   AND pr.status = 'accepted'
                   AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE)
      OR (p_neg.fecho = 'contrato'
          AND EXISTS (SELECT 1 FROM public.client_contracts cc
                      WHERE cc.negocio_id = p_neg.id AND cc.id IS DISTINCT FROM p_excluir
                        AND cc.status IN ('signed', 'assinado', 'active')
                        AND cc.deleted_at IS NULL AND cc.replaced_by_contract_id IS NULL));
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_tem_positivo_activo(p_neg negocios, p_excluir uuid) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_validar_documento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg     public.negocios;
  v_herdado boolean := false;
  v_subst   boolean := false;
  v_sessao  boolean := auth.uid() IS NOT NULL;
BEGIN
  -- Desligar (valor -> nulo): só por neg_desligar_registo, que põe
  -- app.neg_via_funcao; o negócio de antes tem de estar aberto e editável.
  IF NEW.negocio_id IS NULL THEN
    IF TG_OP <> 'UPDATE' THEN
      RETURN NEW;
    END IF;
    IF OLD.negocio_id IS NULL THEN
      RETURN NEW;
    END IF;
    IF COALESCE(current_setting('app.neg_via_funcao', true), '') <> 'on' THEN
      RAISE EXCEPTION 'Um documento só se desliga do negócio pela acção da página Pessoas.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    SELECT n.* INTO v_neg FROM public.negocios n
    WHERE n.id = OLD.negocio_id AND n.deleted_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
    END IF;
    IF v_neg.estado <> 'aberto' THEN
      RAISE EXCEPTION 'O negócio está %: esta acção não é possível.', v_neg.estado
        USING ERRCODE = 'NG002';
    END IF;
    IF NOT public.fn_neg_pode_editar(v_neg) THEN
      RAISE EXCEPTION 'Sem permissão para desligar documentos deste negócio.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;

  SELECT n.* INTO v_neg FROM public.negocios n
  WHERE n.id = NEW.negocio_id AND n.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                 WHERE c.organization_id = v_neg.organization_id) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_neg.organization_id
     OR NEW.entity_id IS DISTINCT FROM v_neg.entity_id THEN
    RAISE EXCEPTION 'O documento tem de ser da mesma organização e da mesma pessoa do negócio.'
      USING ERRCODE = 'NG004';
  END IF;
  IF TG_TABLE_NAME = 'client_contracts' AND v_neg.fecho <> 'contrato' THEN
    RAISE EXCEPTION 'Este negócio fecha na proposta (venda directa): não leva contratos.'
      USING ERRCODE = 'NG023';
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- Herança: o valor é o negocio_id do documento de origem.
    IF TG_TABLE_NAME = 'client_contracts' THEN
      v_subst := NEW.replaces_contract_id IS NOT NULL AND EXISTS (
                   SELECT 1 FROM public.client_contracts o
                   WHERE o.id = NEW.replaces_contract_id AND o.negocio_id = NEW.negocio_id);
      v_herdado := v_subst
                OR (NEW.proposal_id IS NOT NULL AND EXISTS (
                      SELECT 1 FROM public.proposals o
                      WHERE o.id = NEW.proposal_id AND o.negocio_id = NEW.negocio_id))
                OR (NEW.quote_id IS NOT NULL AND EXISTS (
                      SELECT 1 FROM public.quotes o
                      WHERE o.id = NEW.quote_id AND o.negocio_id = NEW.negocio_id));
    ELSIF TG_TABLE_NAME = 'quotes' THEN
      v_herdado := NEW.proposal_id IS NOT NULL AND EXISTS (
                     SELECT 1 FROM public.proposals o
                     WHERE o.id = NEW.proposal_id AND o.negocio_id = NEW.negocio_id);
    END IF;
    -- Sem sessão (portal, assinatura): a herança não exige mais nada.
    IF v_herdado AND NOT v_sessao THEN
      RETURN NEW;
    END IF;
    -- Com sessão, herdado ou não, e criação a partir do negócio: aberto (o
    -- substituto de um contrato também ganho) e pessoas.edit com âmbito.
    IF v_subst AND v_sessao AND v_neg.estado = 'ganho' THEN
      NULL;
    ELSIF v_neg.estado <> 'aberto' THEN
      RAISE EXCEPTION 'O negócio está %: esta acção não é possível.', v_neg.estado
        USING ERRCODE = 'NG002';
    END IF;
    IF NOT public.fn_neg_pode_editar(v_neg) THEN
      RAISE EXCEPTION 'Sem permissão para criar documentos neste negócio.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE de negocio_id para um valor não nulo e diferente.
  IF TG_TABLE_NAME = 'proposals' AND OLD.negocio_id IS NULL
     AND COALESCE(current_setting('app.neg_herdar_proposta', true), '') = NEW.negocio_id::text THEN
    IF v_sessao AND NOT public.fn_neg_heranca_permitida(v_neg, ARRAY['aberto']) THEN
      RAISE EXCEPTION 'Sem permissão para ligar documentos a este negócio.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;
  IF COALESCE(current_setting('app.neg_via_funcao', true), '') = 'on' AND OLD.negocio_id IS NULL THEN
    IF v_neg.estado <> 'aberto' THEN
      RAISE EXCEPTION 'O negócio está %: esta acção não é possível.', v_neg.estado
        USING ERRCODE = 'NG002';
    END IF;
    IF NOT public.fn_neg_pode_editar(v_neg) THEN
      RAISE EXCEPTION 'Sem permissão para ligar documentos a este negócio.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'O negócio de um documento só muda pelas acções da página Pessoas.'
    USING ERRCODE = 'insufficient_privilege';
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_validar_documento() FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_neg_validar_documento() IS 'Pessoas, D10: valida negocio_id em quotes, proposals e client_contracts (INSERT e qualquer UPDATE que o mude): negócio vivo, organização com Pessoas, mesma organização e pessoa, contratos só com fecho no contrato. Com sessão, tudo (herdado ou não) exige negócio aberto (o substituto de um contrato também ganho) e pessoas.edit; sem sessão, só a herança passa. Desligar (para nulo) só por neg_desligar_registo, com o negócio aberto e pessoas.edit. Outros UPDATE recusados. 20261226150000.';

CREATE OR REPLACE FUNCTION public.fn_neg_valor_negocio(p_negocio_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (SELECT pr.value::numeric
     FROM public.proposals pr
     WHERE pr.negocio_id = p_negocio_id AND pr.status IS DISTINCT FROM 'rejected'
       AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
     ORDER BY pr.created_at DESC
     LIMIT 1),
    (SELECT q.total::numeric
     FROM public.quotes q
     WHERE q.negocio_id = p_negocio_id AND q.estado = 'aceite' AND q.deleted_at IS NULL
     ORDER BY q.accepted_at DESC NULLS LAST, q.created_at DESC
     LIMIT 1),
    (SELECT max(q.total)::numeric
     FROM public.quotes q
     WHERE q.negocio_id = p_negocio_id AND q.deleted_at IS NULL
       AND q.estado IS DISTINCT FROM 'rejeitado' AND q.estado IS DISTINCT FROM 'perdido'));
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_valor_negocio(p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_valor_negocio(p_negocio_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_neg_valor_negocio(p_negocio_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_neg_visita_editavel(p_visita_id uuid, p_aceitar_cancelada boolean)
 RETURNS schedule_items
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_vis  public.schedule_items;
  v_org  uuid;
  v_tipo text;
BEGIN
  SELECT s.organization_id INTO v_org
  FROM public.schedule_items s
  WHERE s.id = p_visita_id;
  IF v_org IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c WHERE c.organization_id = v_org) THEN
    RAISE EXCEPTION 'Visita indisponível.' USING ERRCODE = 'NG017';
  END IF;

  SELECT s.* INTO v_vis
  FROM public.schedule_items s
  WHERE s.id = p_visita_id AND s.organization_id = v_org
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Visita indisponível.' USING ERRCODE = 'NG017';
  END IF;

  SELECT b.board_type INTO v_tipo FROM public.schedule_boards b WHERE b.id = v_vis.board_id;
  IF v_vis.time_off_type IS NOT NULL OR v_vis.vacation_id IS NOT NULL
     OR v_tipo IN ('time_off', 'fleet')
     OR (v_vis.lead_id IS NULL AND v_vis.client_id IS NULL) THEN
    RAISE EXCEPTION 'Visita indisponível.' USING ERRCODE = 'NG017';
  END IF;

  IF NOT (public.has_anew_permission(auth.uid(), 'pessoas.edit')
          AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
                      WHERE k.scope_key = v_vis.organization_id::text || ':*'
                         OR k.scope_key = v_vis.organization_id::text || ':' || v_vis.created_by::text
                         OR k.scope_key = v_vis.organization_id::text || ':' || v_vis.user_id::text)) THEN
    RAISE EXCEPTION 'Sem permissão para alterar a visita.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_aceitar_cancelada AND v_vis.status = 'cancelled'::public.schedule_item_status THEN
    RETURN v_vis;
  END IF;

  IF v_vis.status IN ('completed'::public.schedule_item_status, 'cancelled'::public.schedule_item_status)
     OR v_vis.visit_outcome IS NOT NULL
     OR (v_vis.negocio_id IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM public.negocios n
                         WHERE n.id = v_vis.negocio_id AND n.estado = 'aberto' AND n.deleted_at IS NULL)) THEN
    RAISE EXCEPTION 'A visita já foi feita, cancelada ou tem resultado, ou o negócio dela está fechado: não se altera.'
      USING ERRCODE = 'NG018';
  END IF;

  RETURN v_vis;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_neg_visita_editavel(p_visita_id uuid, p_aceitar_cancelada boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_neg_visita_editavel(p_visita_id uuid, p_aceitar_cancelada boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_negocio_workflow_config_preparar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := public.fn_negocios_actor();
    NEW.created_at := now();
  ELSE
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'Não é possível mudar a organização de uma configuração.'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_by := CASE
      WHEN public.fn_negocios_ref_utilizador_apagado(OLD.created_by, NEW.created_by) THEN NULL
      ELSE OLD.created_by END;
    NEW.created_at := OLD.created_at;
  END IF;
  -- Quem executa (nulo sem sessão: migrations, service_role).
  NEW.updated_by := public.fn_negocios_actor();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocio_workflow_config_preparar() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocio_workflow_config_preparar() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
BEGIN
  SELECT au.id INTO v_actor
  FROM public.anew_users au
  WHERE au.auth_user_id = auth.uid()
  LIMIT 1;

  IF v_actor IS NULL THEN
    v_actor := public.current_business_user_id();
    IF v_actor IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.anew_users u WHERE u.id = v_actor) THEN
      v_actor := NULL;
    END IF;
  END IF;

  RETURN v_actor;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_actor() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_actor() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_exigir_permissao_lixo(p_organization_id uuid, p_assigned_to uuid, p_created_by uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_role     text := coalesce(current_setting('role', true), '');
  v_jwt_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
BEGIN
  IF v_uid IS NULL THEN
    IF v_role IN ('authenticated', 'anon') OR v_jwt_role IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Sessão sem utilizador: não é possível enviar este negócio para o lixo nem restaurá-lo.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN;
  END IF;

  IF NOT (
    public.has_anew_permission(v_uid, 'pessoas.delete')
    AND EXISTS (
      SELECT 1
      FROM unnest(public.crm_scope_keys('pessoas.delete')) AS k(scope_key)
      WHERE k.scope_key = p_organization_id::text || ':*'
         OR k.scope_key = p_organization_id::text || ':' || p_assigned_to::text
         OR k.scope_key = p_organization_id::text || ':' || p_created_by::text
    )
  ) THEN
    RAISE EXCEPTION 'Sem permissão para enviar este negócio para o lixo ou para o restaurar (pessoas.delete).'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_exigir_permissao_lixo(p_organization_id uuid, p_assigned_to uuid, p_created_by uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_exigir_permissao_lixo(p_organization_id uuid, p_assigned_to uuid, p_created_by uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_fechado_so_leitura()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- As funções neg_* e os gatilhos de decisão do fecho escrevem com a variável.
  IF COALESCE(current_setting('app.neg_via_funcao', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  -- Só a limpeza do comercial de um utilizador apagado passa (ON DELETE SET NULL).
  IF NEW.titulo IS NOT DISTINCT FROM OLD.titulo
     AND NEW.notas IS NOT DISTINCT FROM OLD.notas
     AND (NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to
          OR public.fn_negocios_ref_utilizador_apagado(OLD.assigned_to, NEW.assigned_to)) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Este negócio está %: o título, as notas e o comercial já não se alteram. Reabra-o primeiro.',
    OLD.estado
    USING ERRCODE = 'NG028';
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_fechado_so_leitura() FROM PUBLIC, anon, authenticated, service_role;
COMMENT ON FUNCTION public.fn_negocios_fechado_so_leitura() IS 'Pessoas: gatilho que recusa (NG028) mudar titulo, notas ou assigned_to de um negócio ganho ou perdido, salvo com app.neg_via_funcao = on (funções neg_* e gatilhos do fecho) ou a limpeza do comercial de um utilizador apagado. 20261226230000.';

CREATE OR REPLACE FUNCTION public.fn_negocios_guardar_alteracao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_limpa_criador   boolean := public.fn_negocios_ref_utilizador_apagado(OLD.created_by, NEW.created_by);
  v_limpa_comercial boolean := public.fn_negocios_ref_utilizador_apagado(OLD.assigned_to, NEW.assigned_to);
  v_limpa_apagador  boolean := public.fn_negocios_ref_utilizador_apagado(OLD.deleted_by, NEW.deleted_by);
  v_ignorar         text[]  := ARRAY['created_by', 'assigned_to', 'deleted_by', 'updated_at'];
BEGIN
  -- 1. Imutáveis (created_by só pode ir a NULL se o utilizador foi apagado)
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'Não é possível mudar o identificador de um negócio.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'Não é possível mudar a organização de um negócio.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.entity_id IS DISTINCT FROM OLD.entity_id THEN
    RAISE EXCEPTION 'Não é possível mudar a pessoa de um negócio.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by AND NOT v_limpa_criador THEN
    RAISE EXCEPTION 'Não é possível mudar quem criou um negócio.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 1b. O estado, o tipo de fecho e o alerta só mudam pelas funções da
  --     página Pessoas (e pelos gatilhos de decisão, que usam o mesmo caminho).
  IF (NEW.estado IS DISTINCT FROM OLD.estado
      OR NEW.fase_perda IS DISTINCT FROM OLD.fase_perda
      OR NEW.motivo_perda IS DISTINCT FROM OLD.motivo_perda
      OR NEW.fecho IS DISTINCT FROM OLD.fecho
      OR NEW.alerta_codigo IS DISTINCT FROM OLD.alerta_codigo)
     AND COALESCE(current_setting('app.neg_via_funcao', true), '') <> 'on' THEN
    RAISE EXCEPTION 'O estado do negócio só muda pelas acções da página Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 2. No lixo: só o restauro, ou a limpeza de um utilizador apagado
  IF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NOT NULL
     AND ((to_jsonb(NEW) - v_ignorar) IS DISTINCT FROM (to_jsonb(OLD) - v_ignorar)
          OR (NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NOT v_limpa_comercial)
          OR (NEW.deleted_by IS DISTINCT FROM OLD.deleted_by AND NOT v_limpa_apagador)) THEN
    RAISE EXCEPTION 'Este negócio está no lixo: tem de ser restaurado antes de ser alterado.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 3. Comercial novo tem de ser membro activo (só quando muda para alguém)
  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to
     AND NEW.assigned_to IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.anew_memberships m
       WHERE m.user_id = NEW.assigned_to
         AND m.organization_id = NEW.organization_id
         AND m.status = 'active'
     ) THEN
    RAISE EXCEPTION 'O comercial tem de ser membro activo da organização do negócio.'
      USING ERRCODE = 'check_violation';
  END IF;

  NEW.root_organization_id := OLD.root_organization_id;
  NEW.created_at := OLD.created_at;

  -- 4. Datas de estado: now() ao entrar no estado, mantidas enquanto lá
  --    fica, limpas ao sair.
  NEW.perdido_em := CASE
    WHEN NEW.estado <> 'perdido' THEN NULL
    WHEN OLD.estado = 'perdido'  THEN OLD.perdido_em
    ELSE now() END;
  NEW.ganho_em := CASE
    WHEN NEW.estado <> 'ganho' THEN NULL
    WHEN OLD.estado = 'ganho'  THEN OLD.ganho_em
    ELSE now() END;

  -- 4b. Origem da decisão e alerta (Fase N).
  --     A origem só muda com o estado: vem das variáveis locais postas pela
  --     função que decide (nulas numa decisão manual) e só vale para ganho e
  --     perdido. Ao mudar de estado o alerta limpa-se, salvo se a mesma
  --     escrita o mudar. alerta_em é sempre da base.
  IF NEW.estado IS DISTINCT FROM OLD.estado THEN
    IF NEW.estado IN ('ganho', 'perdido') THEN
      NEW.decisao_origem_tipo := NULLIF(current_setting('app.neg_origem_tipo', true), '');
      NEW.decisao_origem_id   := NULLIF(current_setting('app.neg_origem_id', true), '')::uuid;
      IF (NEW.decisao_origem_tipo IS NULL) <> (NEW.decisao_origem_id IS NULL) THEN
        NEW.decisao_origem_tipo := NULL;
        NEW.decisao_origem_id   := NULL;
      END IF;
    ELSE
      NEW.decisao_origem_tipo := NULL;
      NEW.decisao_origem_id   := NULL;
    END IF;
    IF NEW.alerta_codigo IS NOT DISTINCT FROM OLD.alerta_codigo THEN
      NEW.alerta_codigo := NULL;
    END IF;
  ELSE
    NEW.decisao_origem_tipo := OLD.decisao_origem_tipo;
    NEW.decisao_origem_id   := OLD.decisao_origem_id;
  END IF;
  NEW.alerta_em := CASE
    WHEN NEW.alerta_codigo IS NULL THEN NULL
    WHEN NEW.alerta_codigo IS DISTINCT FROM OLD.alerta_codigo THEN now()
    ELSE OLD.alerta_em END;

  -- 5. Lixo: só a passagem vivo <-> lixo conta; o valor é sempre da base.
  IF (OLD.deleted_at IS NULL) IS DISTINCT FROM (NEW.deleted_at IS NULL) THEN
    PERFORM public.fn_negocios_exigir_permissao_lixo(
      OLD.organization_id, OLD.assigned_to, OLD.created_by);

    IF NEW.deleted_at IS NOT NULL THEN
      NEW.deleted_at := now();
      NEW.deleted_by := public.fn_negocios_actor();
    ELSE
      NEW.deleted_by := NULL;
    END IF;
  ELSE
    NEW.deleted_at := OLD.deleted_at;
    NEW.deleted_by := CASE WHEN v_limpa_apagador THEN NULL ELSE OLD.deleted_by END;
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_guardar_alteracao() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_guardar_alteracao() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_preparar_insercao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.estado IS DISTINCT FROM 'aberto'
     AND COALESCE(current_setting('app.neg_via_funcao', true), '') <> 'on' THEN
    RAISE EXCEPTION 'Um negócio é criado aberto; o estado só muda pelas acções da página Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  NEW.root_organization_id := public.resolve_root_organization_id(NEW.organization_id);

  IF NEW.created_by IS NULL THEN
    NEW.created_by := public.fn_negocios_actor();
  END IF;

  NEW.created_at := now();
  NEW.updated_at := now();
  NEW.deleted_at := NULL;
  NEW.deleted_by := NULL;
  NEW.perdido_em := CASE WHEN NEW.estado = 'perdido' THEN now() END;
  NEW.ganho_em   := CASE WHEN NEW.estado = 'ganho'   THEN now() END;

  -- Fase N: a origem e o alerta só aparecem por decisão posterior.
  NEW.decisao_origem_tipo := NULL;
  NEW.decisao_origem_id   := NULL;
  NEW.alerta_codigo       := NULL;
  NEW.alerta_em           := NULL;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_preparar_insercao() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_preparar_insercao() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_ref_utilizador_apagado(p_antigo uuid, p_novo uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN p_antigo IS NOT NULL
     AND p_novo IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.anew_users u WHERE u.id = p_antigo);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_ref_utilizador_apagado(p_antigo uuid, p_novo uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_ref_utilizador_apagado(p_antigo uuid, p_novo uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_negocios_registar_evento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tipo        text;
  v_fase        text;
  v_motivo      text;
  v_motivo_reab text;
  v_lixo        text;
  v_actor       uuid := public.fn_negocios_actor();
  v_or_tipo     text := NULLIF(current_setting('app.neg_origem_tipo', true), '');
  v_or_id       uuid := NULLIF(current_setting('app.neg_origem_id', true), '')::uuid;
  v_or_estado   text := NULLIF(current_setting('app.neg_ev_origem_estado', true), '');
  v_canal       text := NULLIF(current_setting('app.neg_ev_canal', true), '');
  v_prova       text := NULLIF(current_setting('app.neg_ev_prova', true), '');
  v_hash        text := NULLIF(current_setting('app.neg_ev_hash', true), '');
  v_detalhe     text := NULLIF(current_setting('app.neg_ev_detalhe', true), '');
BEGIN
  IF (v_or_tipo IS NULL) <> (v_or_id IS NULL) THEN
    v_or_tipo := NULL;
    v_or_id := NULL;
  END IF;
  v_canal := COALESCE(v_canal, CASE WHEN v_actor IS NOT NULL THEN 'crm' ELSE 'sistema' END);

  IF TG_OP = 'INSERT' THEN
    IF NEW.estado = 'perdido' THEN
      v_tipo := 'perdeu';  v_fase := NEW.fase_perda;  v_motivo := NEW.motivo_perda;
    ELSIF NEW.estado = 'ganho' THEN
      v_tipo := 'ganhou';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.estado IS DISTINCT FROM OLD.estado THEN
      IF NEW.estado = 'perdido' THEN
        v_tipo := 'perdeu';  v_fase := NEW.fase_perda;  v_motivo := NEW.motivo_perda;
      ELSIF NEW.estado = 'ganho' THEN
        v_tipo := 'ganhou';
      ELSE
        -- Reabrir: guarda a perda desfeita (nula se vinha de ganho) e a
        -- razão, se a função de reabrir a deixou na variável local.
        v_tipo := 'reabriu'; v_fase := OLD.fase_perda; v_motivo := OLD.motivo_perda;
        v_motivo_reab := NULLIF(btrim(current_setting('app.negocio_motivo_reabertura', true)), '');
        PERFORM set_config('app.negocio_motivo_reabertura', '', true);
      END IF;
    ELSIF NEW.estado = 'perdido'
          AND (NEW.fase_perda IS DISTINCT FROM OLD.fase_perda
               OR NEW.motivo_perda IS DISTINCT FROM OLD.motivo_perda) THEN
      -- Correcção da fase ou do motivo de uma perda já registada.
      v_tipo := 'perdeu';  v_fase := NEW.fase_perda;  v_motivo := NEW.motivo_perda;
    END IF;

    -- Lixo: só a passagem vivo <-> lixo (o valor é escrito pela base).
    IF (OLD.deleted_at IS NULL) IS DISTINCT FROM (NEW.deleted_at IS NULL) THEN
      v_lixo := CASE WHEN NEW.deleted_at IS NOT NULL THEN 'apagado' ELSE 'restaurado' END;
    END IF;
  END IF;

  -- Estado primeiro, depois o tipo de fecho, depois o lixo.
  -- Não engole erros: sem evento, sem alteração.
  IF v_tipo IS NOT NULL THEN
    INSERT INTO public.negocio_eventos
      (negocio_id, organization_id, root_organization_id, tipo, fase, motivo,
       motivo_reabertura, created_by, detalhe, origem_tipo, origem_id, origem_estado,
       canal, prova, conteudo_hash)
    VALUES
      (NEW.id, NEW.organization_id, NEW.root_organization_id, v_tipo, v_fase, v_motivo,
       v_motivo_reab, v_actor, v_detalhe, v_or_tipo, v_or_id,
       CASE WHEN v_or_id IS NOT NULL THEN v_or_estado END,
       v_canal,
       CASE WHEN v_or_id IS NOT NULL THEN v_prova END,
       CASE WHEN v_or_id IS NOT NULL THEN v_hash END);
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.fecho IS DISTINCT FROM OLD.fecho THEN
    INSERT INTO public.negocio_eventos
      (negocio_id, organization_id, root_organization_id, tipo, created_by, detalhe, canal)
    VALUES
      (NEW.id, NEW.organization_id, NEW.root_organization_id, 'fecho_mudou', v_actor,
       'Fecho: de ' || OLD.fecho || ' para ' || NEW.fecho, v_canal);
  END IF;

  IF v_lixo IS NOT NULL THEN
    INSERT INTO public.negocio_eventos
      (negocio_id, organization_id, root_organization_id, tipo, created_by, canal)
    VALUES
      (NEW.id, NEW.organization_id, NEW.root_organization_id, v_lixo, v_actor, v_canal);
  END IF;

  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_negocios_registar_evento() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_negocios_registar_evento() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_nif_key(p_nif text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  s    text;
  cc   text;
  body text;
  i    integer;
  tot  integer := 0;
  r    integer;
  chk  integer;
BEGIN
  s := upper(regexp_replace(COALESCE(p_nif, ''), '[\s\.\-/' || chr(160) || ']', '', 'g'));
  IF s = '' THEN
    RETURN NULL;
  END IF;

  IF s ~ '^[0-9]{9}$' THEN
    cc := 'PT'; body := s;
  ELSIF s ~ '^[A-Z]{2}[0-9A-Z]{2,13}$' THEN
    cc := left(s, 2); body := substr(s, 3);
    IF cc = 'GR' THEN cc := 'EL'; END IF;
    IF cc NOT IN ('AT','BE','BG','CY','CZ','DE','DK','EE','EL','ES','FI','FR','HR','HU','IE',
                  'IT','LT','LU','LV','MT','NL','PL','PT','RO','SE','SI','SK','XI') THEN
      RETURN NULL;
    END IF;
  ELSE
    RETURN NULL;
  END IF;

  IF cc = 'PT' THEN
    IF body !~ '^[1-9][0-9]{8}$' THEN
      RETURN NULL;
    END IF;
    FOR i IN 1..8 LOOP
      tot := tot + substr(body, i, 1)::integer * (10 - i);
    END LOOP;
    r := tot % 11;
    chk := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
    IF chk <> substr(body, 9, 1)::integer THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN cc || body;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_nif_key(p_nif text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_nif_key(p_nif text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_nif_key(p_nif text) TO service_role;
COMMENT ON FUNCTION public.fn_nif_key(p_nif text) IS 'Portal do fornecedor F3.1: chave global do NIF (PT + 9 dígitos com dígito de controlo válido, ou prefixo de país da UE + identificador). NULL = inválido.';

CREATE OR REPLACE FUNCTION public.fn_piso_numerico(p_floor text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_floor IS NULL OR btrim(p_floor) = '' THEN NULL
    WHEN regexp_replace(lower(btrim(p_floor)), '[[:space:].]', '', 'g') ~ '^(r/?c|r[eé]s-?do-?ch[aã]o)' THEN 0
    WHEN btrim(p_floor) ~ '^-?[0-9]{1,4}(?![0-9])' THEN substring(btrim(p_floor) from '^-?[0-9]{1,4}')::integer
    ELSE NULL
  END
$function$;
REVOKE ALL ON FUNCTION public.fn_piso_numerico(p_floor text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_piso_numerico(p_floor text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_piso_numerico(p_floor text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_po_crm_load(p_po_id uuid, p_permission text, p_lock boolean)
 RETURNS purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_po  public.purchase_orders;
BEGIN
  IF v_uid IS NULL OR public.current_business_user_id() IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF p_lock THEN
    SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_po_id AND deleted_at IS NULL FOR UPDATE;
  ELSE
    SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_po_id AND deleted_at IS NULL;
  END IF;
  IF v_po.id IS NULL OR NOT public.fn_deal_org_in_scope(v_po.organization_id) THEN
    RAISE EXCEPTION 'Encomenda não encontrada' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  IF NOT public.has_anew_permission(v_uid, p_permission) THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (%)', p_permission
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  RETURN v_po;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_po_crm_load(p_po_id uuid, p_permission text, p_lock boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_po_crm_load(p_po_id uuid, p_permission text, p_lock boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_po_has_active_publication(p_po_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.supplier_po_publications
    WHERE purchase_order_id = p_po_id AND status <> 'withdrawn'
  );
$function$;
REVOKE ALL ON FUNCTION public.fn_po_has_active_publication(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_po_has_active_publication(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_po_has_active_publication(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_po_notify_supplier_confirmed(p_po purchase_orders, p_pub supplier_po_publications)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_supplier text;
  v_msg      text;
  v_n        integer := 0;
BEGIN
  SELECT name INTO v_supplier FROM public.suppliers WHERE id = p_po.supplier_id;
  v_msg := format('%s confirmou a encomenda %s', COALESCE(v_supplier, 'O fornecedor'), p_po.order_number)
           || CASE WHEN p_pub.promised_date IS NOT NULL
                   THEN ' · entrega prevista ' || to_char(p_pub.promised_date, 'DD/MM/YYYY') ELSE '' END;

  INSERT INTO public.notifications
    (user_id, organization_id, kind, type, title, message, link, entity_type, entity_id, priority, data)
  SELECT r.auth_user_id, p_po.organization_id, 'notification', 'supplier_po_confirmed',
         'Encomenda confirmada pelo fornecedor', v_msg,
         '/purchase-orders?open=' || p_po.id::text, 'purchase_order', p_po.id, 'medium',
         jsonb_build_object('modulo', 'compras', 'purchase_order_id', p_po.id, 'revision', p_pub.revision,
                            'promised_date', p_pub.promised_date, 'supplier_comment', p_pub.supplier_comment)
  FROM (
    SELECT DISTINCT u.auth_user_id
    FROM public.anew_users u
    WHERE u.deleted_at IS NULL
      AND u.auth_user_id IS NOT NULL
      AND (
        (u.id = p_po.created_by
         AND p_po.organization_id IN (SELECT public.get_user_visible_org_ids(u.auth_user_id)))
        OR EXISTS (
          SELECT 1
          FROM public.anew_memberships m
          JOIN public.anew_role_permissions rp ON rp.role_id = m.role_id AND rp.permission_code = 'purchase_orders.approve'
          WHERE m.user_id = u.id AND m.organization_id = p_po.organization_id
            AND m.status = 'active' AND m.role_is_client IS NOT TRUE
        )
      )
  ) r
  WHERE NOT EXISTS (
    SELECT 1 FROM public.notifications n
    WHERE n.user_id = r.auth_user_id AND n.type = 'supplier_po_confirmed' AND n.entity_id = p_po.id
      AND n.is_read = false AND n.is_dismissed = false AND n.is_resolved = false
  );
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Aviso de confirmação não enviado: %', SQLERRM;
  RETURN 0;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_po_notify_supplier_confirmed(p_po purchase_orders, p_pub supplier_po_publications) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_po_notify_supplier_confirmed(p_po purchase_orders, p_pub supplier_po_publications) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_po_published_direct_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_TABLE_NAME = 'purchase_order_items' THEN
    IF (TG_OP <> 'INSERT' AND public.fn_po_has_active_publication(OLD.purchase_order_id))
       OR (TG_OP <> 'DELETE' AND public.fn_po_has_active_publication(NEW.purchase_order_id)) THEN
      RAISE EXCEPTION 'Esta encomenda está no portal do fornecedor: as linhas não podem ser alteradas'
        USING ERRCODE = 'check_violation', HINT = 'po_published';
    END IF;
  ELSIF TG_TABLE_NAME = 'purchase_orders' THEN
    IF TG_OP = 'DELETE' THEN
      IF public.fn_po_has_active_publication(OLD.id) THEN
        RAISE EXCEPTION 'Esta encomenda está no portal do fornecedor: retire-a do portal antes de a apagar'
          USING ERRCODE = 'check_violation', HINT = 'po_published';
      END IF;
    ELSIF (NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR NEW.order_date IS DISTINCT FROM OLD.order_date)
          AND public.fn_po_has_active_publication(OLD.id) THEN
      RAISE EXCEPTION 'Esta encomenda está no portal do fornecedor: o fornecedor e a data da encomenda não podem ser alterados'
        USING ERRCODE = 'check_violation', HINT = 'po_published';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_po_published_direct_guard() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_po_published_direct_guard() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_price_change_cost_plan(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  isup       public.item_suppliers;
  p          record;
  v_factor   integer;
  v_unit     numeric;
  v_cur      numeric;
  v_cur_ccy  text;
  v_sale     numeric;
  v_reason   text;
  v_msg      text;
  v_pref     text;
  v_same_ccy boolean;
  v_any_rows boolean;
BEGIN
  SELECT * INTO isup FROM public.item_suppliers WHERE id = p_item_supplier_id;
  IF isup.id IS NULL OR isup.product_id IS NULL THEN
    RETURN jsonb_build_object('will_update', false, 'reason', 'not_product',
                              'message', 'Esta ligação não é de um produto: o custo não muda');
  END IF;

  SELECT pr.id, pr.organization_id, pr.deleted_at, pr.is_deleted INTO p
  FROM public.products pr WHERE pr.id = isup.product_id;

  SELECT pp.price, pp.currency::text INTO v_cur, v_cur_ccy
  FROM public.product_prices pp
  WHERE pp.product_id = isup.product_id AND pp.price_type = 'purchase'
  ORDER BY (pp.currency::text = p_currency) DESC, pp.updated_at DESC, pp.created_at DESC
  LIMIT 1;

  SELECT pp.price INTO v_sale
  FROM public.product_prices pp
  WHERE pp.product_id = isup.product_id AND pp.price_type = 'retail' AND pp.currency::text = p_currency
  ORDER BY pp.updated_at DESC, pp.created_at DESC
  LIMIT 1;

  BEGIN
    v_factor := public.fn_uom_units_per(isup.uom_id, isup.product_id);
  EXCEPTION WHEN OTHERS THEN
    v_factor := NULL;
  END;
  IF v_factor IS NOT NULL AND v_factor > 0 AND p_new_price IS NOT NULL THEN
    v_unit := round(p_new_price / v_factor, 2);
  END IF;

  v_same_ccy := EXISTS (SELECT 1 FROM public.product_prices
                        WHERE product_id = isup.product_id AND price_type = 'purchase' AND currency::text = p_currency);
  v_any_rows := EXISTS (SELECT 1 FROM public.product_prices
                        WHERE product_id = isup.product_id AND price_type = 'purchase');

  IF p.id IS NULL OR p.deleted_at IS NOT NULL OR p.is_deleted THEN
    v_reason := 'product_deleted';
    v_msg := 'O produto foi apagado: só o preço do fornecedor foi atualizado';
  ELSIF p.organization_id IS DISTINCT FROM p_organization_id THEN
    v_reason := 'other_primary_company';
    v_msg := 'O custo do produto só muda na empresa principal do produto: só o preço deste fornecedor foi atualizado';
  ELSIF NOT (isup.is_preferred AND isup.is_active AND isup.deleted_at IS NULL) THEN
    SELECT s.name INTO v_pref
    FROM public.item_suppliers i JOIN public.suppliers s ON s.id = i.supplier_id
    WHERE i.product_id = isup.product_id AND i.is_preferred AND i.deleted_at IS NULL
    LIMIT 1;
    v_reason := 'not_preferred';
    v_msg := CASE WHEN v_pref IS NULL
                  THEN 'Este fornecedor não é o preferencial do produto: só o preço deste fornecedor foi atualizado'
                  ELSE format('O custo do produto vem do fornecedor preferencial (%s): só o preço deste fornecedor foi atualizado', v_pref) END;
  ELSIF v_factor IS NULL THEN
    v_reason := 'uom_incompatible';
    v_msg := 'A unidade de compra desta ligação não é compatível com a unidade do produto: o custo do produto não mudou';
  ELSIF p_new_price IS NULL OR v_unit <= 0 THEN
    v_reason := 'zero_price';
    v_msg := 'O custo unitário daria 0: o custo do produto não mudou';
  ELSIF v_unit >= 100000000 THEN
    v_reason := 'out_of_range';
    v_msg := 'O custo unitário é demasiado alto para a ficha do produto: o custo do produto não mudou';
  ELSIF v_any_rows AND NOT v_same_ccy THEN
    v_reason := 'currency_mismatch';
    v_msg := format('O custo do produto está noutra moeda (%s): o custo do produto não mudou', v_cur_ccy);
  ELSIF NOT v_any_rows AND NOT EXISTS (SELECT 1 FROM pg_enum
                                       WHERE enumtypid = 'public.currency_code'::regtype AND enumlabel = p_currency) THEN
    v_reason := 'currency_unsupported';
    v_msg := format('A moeda %s não é suportada no custo do produto: o custo do produto não mudou', p_currency);
  END IF;

  RETURN jsonb_build_object(
    'will_update', v_reason IS NULL,
    'reason', v_reason,
    'message', v_msg,
    'is_preferred', (isup.is_preferred AND isup.is_active AND isup.deleted_at IS NULL),
    'preferred_supplier_name', v_pref,
    'units_per_purchase_uom', v_factor,
    'new_unit_cost', v_unit,
    'current_unit_cost', v_cur,
    'current_cost_currency', v_cur_ccy,
    'sale_price', v_sale,
    'margin_current_pct', CASE WHEN v_sale > 0 AND v_cur IS NOT NULL AND v_cur_ccy = p_currency
                               THEN round((v_sale - v_cur) / v_sale * 100, 2) END,
    'margin_new_pct', CASE WHEN v_sale > 0 AND v_unit IS NOT NULL
                           THEN round((v_sale - v_unit) / v_sale * 100, 2) END
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_price_change_cost_plan(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_price_change_cost_plan(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text) TO service_role;
COMMENT ON FUNCTION public.fn_price_change_cost_plan(p_item_supplier_id uuid, p_organization_id uuid, p_new_price numeric, p_currency text) IS 'Portal do fornecedor F3.4b: o que aceitar um preço faz ao custo do produto (product_prices purchase). will_update + reason/message; custo unitário = round(preço / fn_uom_units_per(ligação.uom_id), 2); margens sobre o preço de venda (retail).';

CREATE OR REPLACE FUNCTION public.fn_product_code_json(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_r      record;
  v_factor integer;
BEGIN
  SELECT pc.*, p.name AS product_name, p.sku AS product_sku, p.uom_id AS product_uom_id,
         u.code AS uom_code, s.name AS supplier_name
  INTO v_r
  FROM public.product_codes pc
  JOIN public.products p ON p.id = pc.product_id
  LEFT JOIN public.uom u ON u.id = COALESCE(pc.uom_id, p.uom_id)
  LEFT JOIN public.suppliers s ON s.id = pc.supplier_id
  WHERE pc.id = p_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  BEGIN
    v_factor := public.fn_uom_units_per(v_r.uom_id, v_r.product_id);
  EXCEPTION WHEN OTHERS THEN
    v_factor := NULL;  -- unidade deixou de ser compatível com o produto
  END;
  RETURN jsonb_build_object(
    'id', v_r.id, 'code', v_r.code, 'code_key', v_r.code_key, 'kind', v_r.kind,
    'product_id', v_r.product_id, 'product_name', v_r.product_name, 'sku', v_r.product_sku,
    'uom_id', COALESCE(v_r.uom_id, v_r.product_uom_id), 'uom_code', v_r.uom_code,
    'is_pack', v_r.uom_id IS NOT NULL, 'units_per_uom', v_factor,
    'supplier_id', v_r.supplier_id, 'supplier_name', v_r.supplier_name,
    'source', v_r.source, 'context', v_r.context,
    'created_by', v_r.created_by, 'created_at', v_r.created_at,
    'deleted_at', v_r.deleted_at, 'deleted_by', v_r.deleted_by, 'delete_reason', v_r.delete_reason);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_product_code_json(p_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_product_code_json(p_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_product_codes_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key   text := public.fn_product_code_key(NEW.code);  -- code_key (gerada) ainda não está calculada num BEFORE
  v_org   uuid;
  v_other record;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL
     AND v_key IS NOT DISTINCT FROM OLD.code_key AND NEW.kind = OLD.kind
     AND NEW.product_id = OLD.product_id AND NEW.organization_id = OLD.organization_id THEN
    RETURN NEW;
  END IF;

  SELECT organization_id INTO v_org FROM public.products WHERE id = NEW.product_id;
  IF v_org IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'O produto do código não pertence à organização do código' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.kind = 'barcode' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('product_code:' || NEW.organization_id::text || ':' || v_key, 0));
    SELECT p.id, p.name, p.sku INTO v_other
    FROM public.products p
    WHERE p.organization_id = NEW.organization_id AND p.id <> NEW.product_id
      AND p.deleted_at IS NULL AND NOT p.is_deleted
      AND public.fn_product_code_key(p.barcode) = v_key
    ORDER BY p.id
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'O código de barras «%» já é o código do produto «%» (%)', btrim(NEW.code), v_other.name, v_other.sku
        USING ERRCODE = 'unique_violation', DETAIL = v_other.id::text,
              HINT = 'Um código de barras só pode estar num produto ativo da organização (id do produto em DETAIL).';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_product_codes_guard() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_product_codes_guard() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_products_barcode_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_own   text;
  v_keys  text[];
  v_k     text;
  v_other record;
  v_found boolean;
  v_upsert uuid;  -- INSERT: produto já existente com a mesma (organization_id, sku)
BEGIN
  IF NEW.organization_id IS NULL OR NEW.deleted_at IS NOT NULL OR NEW.is_deleted THEN
    RETURN NEW;  -- produto apagado (ou sem organização) não bloqueia
  END IF;

  v_own := public.fn_product_code_key(NEW.barcode);

  -- INSERT … ON CONFLICT (sku, organization_id) DO UPDATE (rpc_bulk_import_products):
  -- o BEFORE INSERT corre antes de o conflito ser resolvido, por isso o produto
  -- com a mesma (organization_id, sku) — igualdade exata, como o índice
  -- products_sku_organization_id_key — é o próprio produto, não "outro". Se a
  -- linha for mesmo inserida, esse produto não existe (o índice impede); se
  -- houver conflito, o BEFORE UPDATE OF barcode/... verifica com o id real.
  IF TG_OP = 'INSERT' AND NEW.sku IS NOT NULL THEN
    SELECT p.id INTO v_upsert
    FROM public.products p
    WHERE p.organization_id = NEW.organization_id AND p.sku = NEW.sku;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL AND NOT OLD.is_deleted
     AND OLD.organization_id IS NOT DISTINCT FROM NEW.organization_id THEN
    -- Continua ativo na mesma organização: só o código principal pode mudar.
    IF v_own IS NULL OR v_own IS NOT DISTINCT FROM public.fn_product_code_key(OLD.barcode) THEN
      RETURN NEW;
    END IF;
    v_keys := ARRAY[v_own];
  ELSE
    -- Novo, restaurado da lixeira ou noutra organização: o código principal
    -- e os códigos aprendidos ativos do produto.
    SELECT array_agg(DISTINCT z.k ORDER BY z.k) INTO v_keys
    FROM (
      SELECT v_own AS k WHERE v_own IS NOT NULL
      UNION
      SELECT pc.code_key FROM public.product_codes pc
      WHERE pc.product_id = NEW.id AND pc.kind = 'barcode' AND pc.deleted_at IS NULL
    ) z;
    IF v_keys IS NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Locks por ordem (chaves ordenadas) antes de qualquer verificação.
  FOREACH v_k IN ARRAY v_keys LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('product_code:' || NEW.organization_id::text || ':' || v_k, 0));
  END LOOP;

  FOREACH v_k IN ARRAY v_keys LOOP
    SELECT p.id, p.name, p.sku, btrim(p.barcode) AS code INTO v_other
    FROM public.products p
    WHERE p.organization_id = NEW.organization_id AND p.id <> NEW.id
      AND p.id IS DISTINCT FROM v_upsert
      AND p.deleted_at IS NULL AND NOT p.is_deleted
      AND public.fn_product_code_key(p.barcode) = v_k
    ORDER BY p.id
    LIMIT 1;
    v_found := FOUND;
    IF NOT v_found THEN
      SELECT p.id, p.name, p.sku, btrim(pc.code) AS code INTO v_other
      FROM public.product_codes pc
      JOIN public.products p ON p.id = pc.product_id
      WHERE pc.organization_id = NEW.organization_id AND pc.kind = 'barcode'
        AND pc.deleted_at IS NULL AND pc.code_key = v_k AND pc.product_id <> NEW.id
        AND pc.product_id IS DISTINCT FROM v_upsert
        AND p.deleted_at IS NULL AND NOT p.is_deleted
      ORDER BY pc.id
      LIMIT 1;
      v_found := FOUND;
    END IF;
    IF v_found THEN
      RAISE EXCEPTION 'O código de barras «%» já é o código do produto «%» (%)', v_other.code, v_other.name, v_other.sku
        USING ERRCODE = 'unique_violation', DETAIL = v_other.id::text,
              HINT = 'Um código de barras só pode estar num produto ativo da organização (id do produto em DETAIL).';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_products_barcode_guard() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_products_barcode_guard() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_purchase_orders_guard_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Só pedidos diretos do PostgREST. Dentro de uma RPC SECURITY DEFINER o
  -- current_user é o dono da RPC (postgres) e passa.
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' AND NEW.status IS DISTINCT FROM 'pending' THEN
      RAISE EXCEPTION 'Uma encomenda a fornecedor nasce sempre pendente; o estado só muda pelas funções do sistema'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
      RAISE EXCEPTION 'O estado da encomenda a fornecedor só pode ser alterado pelas funções do sistema (Encomendar, Receber, Anular, Reverter)'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_purchase_orders_guard_status() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_purchase_orders_guard_status() TO service_role;
COMMENT ON FUNCTION public.fn_purchase_orders_guard_status() IS 'Portal do fornecedor F3.0: recusa INSERT com estado diferente de pending e qualquer mudança de status feitos diretamente por authenticated/anon. As RPCs SECURITY DEFINER passam.';

CREATE OR REPLACE FUNCTION public.fn_quote_morada_texto(p_address_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT nullif(concat_ws(', ',
           nullif(btrim(a.street), ''),
           nullif(btrim(a.number), ''),
           nullif(concat_ws(' ', nullif(btrim(a.floor), ''), nullif(btrim(a.unit), '')), ''),
           nullif(concat_ws(' ', nullif(btrim(a.postal_code), ''), nullif(btrim(a.city), '')), '')
         ), '')
  FROM public.anew_addresses a
  WHERE a.id = p_address_id;
$function$;
REVOKE ALL ON FUNCTION public.fn_quote_morada_texto(p_address_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_quote_morada_texto(p_address_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_receiving_open_lines(p_organization_id uuid, p_product_ids uuid[], p_supplier_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(purchase_order_id uuid, order_number text, po_status text, confirmed boolean, supplier_id uuid, supplier_name text, expected_delivery date, order_date date, purchase_order_item_id uuid, product_id uuid, description text, quantity numeric, received_quantity numeric, open_quantity numeric, uom_id uuid, units_per_uom integer, supplier_sku text, sku text, contract_id uuid, contract_order_number text, contract_active boolean, contract_sort_ts timestamp with time zone, allocation_rank bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    x.po_id, x.order_number, x.status, x.status <> 'pending', x.supplier_id, x.supplier_name,
    x.expected_delivery, x.order_date, x.poi_id, x.product_id, x.description, x.quantity,
    x.received_quantity, x.quantity - x.received_quantity, x.uom_id, x.units_per_uom,
    x.supplier_sku, x.sku, x.contract_id, x.contract_order_number, x.contract_active,
    x.contract_sort_ts,
    row_number() OVER (
      PARTITION BY x.product_id
      ORDER BY x.contract_active DESC,
               CASE WHEN x.contract_active THEN x.contract_sort_ts END NULLS LAST,
               CASE WHEN x.contract_active THEN x.contract_id END NULLS LAST,
               x.expected_delivery NULLS LAST,
               x.order_date,
               x.order_number,
               x.poi_created_at,
               x.poi_id
    )
  FROM (
    SELECT
      po.id                AS po_id,
      po.order_number,
      po.status,
      po.supplier_id,
      s.name               AS supplier_name,
      po.expected_delivery,
      po.order_date,
      poi.id               AS poi_id,
      poi.product_id,
      poi.description,
      poi.quantity,
      poi.received_quantity,
      poi.uom_id,
      COALESCE(poi.units_per_uom, 1) AS units_per_uom,
      poi.supplier_sku,
      poi.sku,
      poi.created_at       AS poi_created_at,
      CASE WHEN po.source_type = 'contract' THEN po.source_id END AS contract_id,
      CASE WHEN po.source_type = 'contract' THEN COALESCE(cc.order_number, cc.contract_number) END AS contract_order_number,
      -- Mesma definição de EC ativa de fn_po_receipt_allocation.
      COALESCE(po.source_type = 'contract' AND cc.id IS NOT NULL
               AND cc.deleted_at IS NULL AND cc.status IN ('signed', 'assinado'), false) AS contract_active,
      COALESCE(cc.signature_date, cc.status_changed_at, cc.created_at) AS contract_sort_ts
    FROM public.purchase_orders po
    JOIN public.purchase_order_items poi ON poi.purchase_order_id = po.id
    LEFT JOIN public.suppliers s ON s.id = po.supplier_id
    LEFT JOIN public.client_contracts cc
      ON po.source_type = 'contract'
     AND cc.id = po.source_id
     AND cc.organization_id = po.organization_id
    WHERE po.organization_id = p_organization_id
      AND po.deleted_at IS NULL
      AND po.status IN ('pending', 'ordered', 'partially_received')
      AND poi.item_type = 'product'
      AND poi.product_id = ANY (p_product_ids)
      AND poi.quantity > poi.received_quantity
      AND (p_supplier_id IS NULL OR po.supplier_id = p_supplier_id)
  ) x;
$function$;
REVOKE ALL ON FUNCTION public.fn_receiving_open_lines(p_organization_id uuid, p_product_ids uuid[], p_supplier_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_receiving_open_lines(p_organization_id uuid, p_product_ids uuid[], p_supplier_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_receiving_scan_replay(p_request_id uuid, p_organization_id uuid, p_actor uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_scan public.receiving_scans%ROWTYPE;
BEGIN
  SELECT * INTO v_scan FROM public.receiving_scans WHERE id = p_request_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_scan.organization_id IS DISTINCT FROM p_organization_id
     OR v_scan.created_by IS DISTINCT FROM p_actor THEN
    RAISE EXCEPTION 'Este pedido de receção pertence a outro utilizador ou organização'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_scan.warehouse_id IS DISTINCT FROM p_warehouse_id
     OR v_scan.product_id IS DISTINCT FROM p_product_id
     OR v_scan.quantity IS DISTINCT FROM p_quantity
     OR v_scan.uom_id IS DISTINCT FROM p_uom_id THEN
    RAISE EXCEPTION 'O identificador do pedido de receção já foi usado noutra leitura (outro produto, quantidade, unidade ou armazém)'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN v_scan.result || jsonb_build_object('replayed', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_receiving_scan_replay(p_request_id uuid, p_organization_id uuid, p_actor uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_receiving_scan_replay(p_request_id uuid, p_organization_id uuid, p_actor uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_actor()
 RETURNS supplier_portal_users
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.supplier_portal_users;
BEGIN
  SELECT u.* INTO v
  FROM public.supplier_portal_users u
  JOIN public.supplier_accounts a ON a.id = u.supplier_account_id
  WHERE u.auth_user_id = auth.uid()
    AND u.status = 'active'
    AND a.status = 'active'
    AND EXISTS (
      SELECT 1
      FROM public.supplier_portal_user_access x
      JOIN public.supplier_account_links l ON l.id = x.link_id
      JOIN public.suppliers s ON s.id = l.supplier_id
      WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL
        AND l.status = 'active' AND s.deleted_at IS NULL
    );
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'Sem acesso ao portal do fornecedor'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_supplier_access';
  END IF;
  RETURN v;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_actor() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_actor() TO service_role;
COMMENT ON FUNCTION public.fn_sp_actor() IS 'Portal do fornecedor F3.1: resolve auth.uid() para um utilizador do portal ativo, numa conta ativa, com pelo menos um acesso ativo; senão erro 42501 (HINT no_supplier_access). Chamada no início de cada sp_*.';

CREATE OR REPLACE FUNCTION public.fn_sp_catalog_clean(p_row jsonb, OUT data jsonb, OUT errors text[])
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  k     text;
  raw   text;
  v     text;
  n     numeric;
  ctrl  text := '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]';
  lim   integer;
  labels jsonb := '{"supplier_ref":"Referência","name":"Nome","description":"Descrição","brand":"Marca","unit_label":"Unidade","barcode":"Código de barras","currency":"Moeda","base_price":"Preço","units_per_pack":"Unidades por embalagem","moq":"Quantidade mínima","lead_time_days":"Prazo de entrega (dias)","is_active":"Ativo"}';
BEGIN
  data := '{}'::jsonb;
  errors := ARRAY[]::text[];

  IF p_row IS NULL OR jsonb_typeof(p_row) <> 'object' THEN
    errors := errors || 'Linha inválida'::text;
    RETURN;
  END IF;

  -- Texto
  FOR k, lim IN SELECT * FROM (VALUES ('supplier_ref', 100), ('name', 300), ('description', 2000),
                                      ('brand', 100), ('unit_label', 30)) t(k, lim) LOOP
    IF p_row ? k THEN
      raw := CASE WHEN jsonb_typeof(p_row -> k) = 'null' THEN NULL ELSE p_row ->> k END;
      v := NULLIF(btrim(regexp_replace(COALESCE(raw, ''), ctrl, '', 'g')), '');
      IF v IS NOT NULL AND char_length(v) > lim THEN
        errors := errors || format('%s demasiado longo (máx. %s caracteres)', labels ->> k, lim);
      ELSIF v IS NULL AND k IN ('supplier_ref', 'name') THEN
        errors := errors || format('%s obrigatório', labels ->> k);
      ELSE
        data := data || jsonb_build_object(k, v);
      END IF;
    END IF;
  END LOOP;
  IF NOT (p_row ? 'supplier_ref') THEN
    errors := errors || 'Referência obrigatória'::text;
  END IF;

  -- Código de barras: 8 a 14 dígitos
  IF p_row ? 'barcode' THEN
    raw := CASE WHEN jsonb_typeof(p_row -> 'barcode') = 'null' THEN NULL ELSE p_row ->> 'barcode' END;
    v := NULLIF(regexp_replace(COALESCE(raw, ''), '[\s' || chr(160) || ']', '', 'g'), '');
    IF v IS NOT NULL AND v !~ '^[0-9]{8,14}$' THEN
      errors := errors || 'Código de barras inválido (8 a 14 dígitos)'::text;
    ELSE
      data := data || jsonb_build_object('barcode', v);
    END IF;
  END IF;

  -- Moeda
  IF p_row ? 'currency' THEN
    v := upper(NULLIF(btrim(COALESCE(p_row ->> 'currency', '')), ''));
    IF v IS NULL THEN
      data := data || jsonb_build_object('currency', 'EUR');
    ELSIF v !~ '^[A-Z]{3}$' THEN
      errors := errors || 'Moeda inválida (código de 3 letras, ex.: EUR)'::text;
    ELSE
      data := data || jsonb_build_object('currency', v);
    END IF;
  END IF;

  -- Números
  FOR k IN SELECT unnest(ARRAY['base_price', 'units_per_pack', 'moq', 'lead_time_days']) LOOP
    IF p_row ? k THEN
      raw := CASE WHEN jsonb_typeof(p_row -> k) = 'null' THEN NULL ELSE btrim(p_row ->> k) END;
      IF raw IS NULL OR raw = '' THEN
        data := data || jsonb_build_object(k, NULL);
        CONTINUE;
      END IF;
      n := public.fn_catalog_parse_number(raw);
      IF n IS NULL THEN
        errors := errors || format('%s inválido: «%s»', labels ->> k, left(raw, 40));
      ELSIF k = 'base_price' AND (n < 0 OR n > 1000000000) THEN
        errors := errors || 'Preço fora do intervalo (0 a 1 000 000 000)'::text;
      ELSIF k IN ('units_per_pack', 'moq') AND (n <= 0 OR n > 1000000000) THEN
        errors := errors || format('%s tem de ser maior que zero', labels ->> k);
      ELSIF k = 'lead_time_days' AND (n < 0 OR n > 3650 OR n <> trunc(n)) THEN
        errors := errors || 'Prazo de entrega inválido (dias inteiros, 0 a 3650)'::text;
      ELSE
        data := data || jsonb_build_object(k, CASE WHEN k = 'lead_time_days' THEN to_jsonb(n::integer)
                                                  ELSE to_jsonb(trim_scale(round(n, 4))) END);
      END IF;
    END IF;
  END LOOP;

  -- Ativo
  IF p_row ? 'is_active' THEN
    v := lower(btrim(COALESCE(p_row ->> 'is_active', '')));
    IF v IN ('', 'true', 'sim', 's', 'yes', 'y', '1', 'ativo', 'activo', 'x') THEN
      data := data || jsonb_build_object('is_active', true);
    ELSIF v IN ('false', 'não', 'nao', 'n', 'no', '0', 'inativo', 'inactivo') THEN
      data := data || jsonb_build_object('is_active', false);
    ELSE
      errors := errors || format('Ativo inválido: «%s» (use sim/não)', left(v, 20));
    END IF;
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_catalog_clean(p_row jsonb, OUT data jsonb, OUT errors text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_catalog_clean(p_row jsonb, OUT data jsonb, OUT errors text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_catalog_diff(p_item supplier_catalog_items, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  cur jsonb := to_jsonb(p_item);
  out jsonb := '{}'::jsonb;
  k   text;
BEGIN
  FOR k IN SELECT jsonb_object_keys(p_data) LOOP
    IF k IN ('base_price', 'units_per_pack', 'moq', 'lead_time_days') THEN
      IF (cur ->> k)::numeric IS DISTINCT FROM (p_data ->> k)::numeric THEN
        out := out || jsonb_build_object(k, jsonb_build_object('old', cur -> k, 'new', p_data -> k));
      END IF;
    ELSIF k = 'is_active' THEN
      IF (cur ->> k)::boolean IS DISTINCT FROM (p_data ->> k)::boolean THEN
        out := out || jsonb_build_object(k, jsonb_build_object('old', cur -> k, 'new', p_data -> k));
      END IF;
    ELSIF k IN ('supplier_ref', 'name', 'description', 'brand', 'unit_label', 'barcode', 'currency') THEN
      IF (cur ->> k) IS DISTINCT FROM (p_data ->> k) THEN
        out := out || jsonb_build_object(k, jsonb_build_object('old', cur -> k, 'new', p_data -> k));
      END IF;
    END IF;
  END LOOP;
  RETURN out;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_catalog_diff(p_item supplier_catalog_items, p_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_catalog_diff(p_item supplier_catalog_items, p_data jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_catalog_item_json(p_item supplier_catalog_items, p_with_price boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'id', p_item.id,
    'supplier_ref', p_item.supplier_ref,
    'barcode', p_item.barcode,
    'name', p_item.name,
    'description', p_item.description,
    'brand', p_item.brand,
    'unit_label', p_item.unit_label,
    'units_per_pack', p_item.units_per_pack,
    'base_price', CASE WHEN p_with_price THEN p_item.base_price END,
    'currency', p_item.currency,
    'moq', p_item.moq,
    'lead_time_days', p_item.lead_time_days,
    'is_active', p_item.is_active,
    'updated_at', p_item.updated_at
  )
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_catalog_item_json(p_item supplier_catalog_items, p_with_price boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_catalog_item_json(p_item supplier_catalog_items, p_with_price boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_crm_supplier_org(p_supplier_id uuid, p_permission text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_uid IS NULL OR public.current_business_user_id() IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  SELECT s.organization_id INTO v_org
  FROM public.suppliers s
  WHERE s.id = p_supplier_id AND s.deleted_at IS NULL;
  IF v_org IS NULL OR v_org NOT IN (SELECT public.get_user_visible_org_ids(v_uid)) THEN
    RAISE EXCEPTION 'Fornecedor não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  IF NOT public.has_anew_permission(v_uid, p_permission) THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (%)', p_permission
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  RETURN v_org;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_crm_supplier_org(p_supplier_id uuid, p_permission text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_crm_supplier_org(p_supplier_id uuid, p_permission text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_html_escape(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT replace(replace(replace(replace(replace(
           COALESCE(p_text, ''),
           '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;');
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_html_escape(p_text text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_html_escape(p_text text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_orders_visible(p_portal_user_id uuid, p_org_id uuid, p_like text)
 RETURNS TABLE(purchase_order_id uuid, organization_id uuid, org_name text, org_logo text, order_number text, order_date date, expected_delivery date, order_status text, pub_status text, revision integer, sent_at timestamp with time zone, viewed_at timestamp with time zone, confirmed_at timestamp with time zone, promised_date date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT po.id, po.organization_id, o.name, o.logo_url, po.order_number, po.order_date, po.expected_delivery,
         po.status, p.status, p.revision, p.sent_at, p.viewed_at, p.confirmed_at, p.promised_date
  FROM public.supplier_po_publications p
  JOIN public.purchase_orders po ON po.id = p.purchase_order_id
  JOIN public.supplier_account_links l ON l.id = p.link_id
  JOIN public.suppliers s ON s.id = l.supplier_id
  JOIN public.supplier_portal_user_access x ON x.link_id = l.id
  JOIN public.anew_organizations o ON o.id = po.organization_id
  WHERE x.portal_user_id = p_portal_user_id
    AND x.revoked_at IS NULL
    AND l.status = 'active'
    AND s.deleted_at IS NULL
    AND p.status <> 'withdrawn'
    AND po.deleted_at IS NULL
    AND po.status <> 'pending'
    AND po.supplier_id = l.supplier_id
    AND po.organization_id = p.organization_id
    AND l.organization_id = p.organization_id
    AND (p_org_id IS NULL OR po.organization_id = p_org_id)
    AND (p_like IS NULL OR po.order_number ILIKE p_like OR o.name ILIKE p_like);
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_orders_visible(p_portal_user_id uuid, p_org_id uuid, p_like text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_orders_visible(p_portal_user_id uuid, p_org_id uuid, p_like text) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_po_lines_json(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', i.id,
           'item_type', i.item_type,
           'description', i.description,
           'sku', i.sku,
           'supplier_sku', i.supplier_sku,
           'uom_code', lu.code,
           'base_uom_code', bu.code,
           'units_per_uom', i.units_per_uom,
           'quantity', i.quantity,
           'unit_price', i.unit_price,
           'vat_rate', i.vat_rate,
           'vat_amount', COALESCE(i.vat_amount, 0),
           'subtotal', round(i.unit_price * i.quantity, 2),
           'total', round(i.unit_price * i.quantity + COALESCE(i.vat_amount, 0), 2),
           'received_quantity', i.received_quantity,
           'selected_attributes', COALESCE(i.selected_attributes, '{}'::jsonb)
         ) ORDER BY i.created_at, i.id), '[]'::jsonb)
  FROM public.purchase_order_items i
  LEFT JOIN public.uom lu ON lu.id = i.uom_id
  LEFT JOIN public.products pr ON pr.id = i.product_id
  LEFT JOIN public.uom bu ON bu.id = pr.uom_id
  WHERE i.purchase_order_id = p_po_id;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_po_lines_json(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_po_lines_json(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_po_publication(p_po_id uuid, p_portal_user_id uuid)
 RETURNS supplier_po_publications
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p.*
  FROM public.supplier_po_publications p
  JOIN public.purchase_orders po ON po.id = p.purchase_order_id
  JOIN public.supplier_account_links l ON l.id = p.link_id
  JOIN public.suppliers s ON s.id = l.supplier_id
  JOIN public.supplier_portal_user_access x ON x.link_id = l.id
  WHERE p.purchase_order_id = p_po_id
    AND p.status <> 'withdrawn'
    AND po.deleted_at IS NULL
    AND po.status <> 'pending'
    AND po.supplier_id = l.supplier_id
    AND po.organization_id = p.organization_id
    AND l.organization_id = p.organization_id
    AND l.status = 'active'
    AND s.deleted_at IS NULL
    AND x.portal_user_id = p_portal_user_id
    AND x.revoked_at IS NULL
  LIMIT 1;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_po_publication(p_po_id uuid, p_portal_user_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_po_publication(p_po_id uuid, p_portal_user_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_sp_po_queue_email(p_po purchase_orders, p_pub supplier_po_publications)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org     text;
  v_subject text;
  v_link    text := 'https://www.olyvia-ai.com/supplier-portal/orders/' || p_po.id::text;
  v_html    text;
  v_n       integer := 0;
  v_sender  uuid := auth.uid();
BEGIN
  IF v_sender IS NULL THEN
    RETURN 0;
  END IF;
  SELECT name INTO v_org FROM public.anew_organizations WHERE id = p_po.organization_id;
  v_org := COALESCE(NULLIF(btrim(v_org), ''), 'A empresa');

  v_subject := CASE WHEN p_pub.revision > 1
                    THEN format('Encomenda %s atualizada — %s', p_po.order_number, v_org)
                    ELSE format('Nova encomenda %s — %s', p_po.order_number, v_org) END;
  v_html := format(
    '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #222;">'
    || '<h2 style="color: #333;">%s</h2>'
    || '<p><strong>%s</strong> %s a encomenda <strong>%s</strong> no Portal do Fornecedor.</p>'
    || '<p>Entre no portal para ver o detalhe, descarregar o PDF e confirmar a encomenda com a data de entrega prevista.</p>'
    || '<p style="margin: 24px 0;"><a href="%s" style="background: #2563eb; color: #fff; padding: 12px 20px; border-radius: 6px; text-decoration: none; display: inline-block;">Ver encomenda</a></p>'
    || '<hr style="border: none; border-top: 1px solid #eee; margin: 24px 0;">'
    || '<p style="color: #999; font-size: 13px;">Enviado por %s através da Olyvia. Se não esperava este email, pode ignorá-lo.</p></div>',
    CASE WHEN p_pub.revision > 1 THEN 'Encomenda atualizada' ELSE 'Nova encomenda' END,
    public.fn_sp_html_escape(v_org),
    CASE WHEN p_pub.revision > 1 THEN 'atualizou' ELSE 'enviou-lhe' END,
    public.fn_sp_html_escape(p_po.order_number),
    public.fn_sp_html_escape(v_link),
    public.fn_sp_html_escape(v_org));

  INSERT INTO public.scheduled_emails
    (entity_type, entity_id, to_email, subject, body_html, user_id, organization_id, scheduled_for, status)
  SELECT 'purchase_orders', p_po.id, u.email, v_subject, v_html, v_sender, p_po.organization_id, now(), 'pending'
  FROM public.supplier_portal_user_access x
  JOIN public.supplier_portal_users u ON u.id = x.portal_user_id
  JOIN public.supplier_accounts a ON a.id = u.supplier_account_id
  WHERE x.link_id = p_pub.link_id
    AND x.revoked_at IS NULL
    AND u.status = 'active'
    AND a.status = 'active';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Email ao fornecedor não posto na fila: %', SQLERRM;
  RETURN 0;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_sp_po_queue_email(p_po purchase_orders, p_pub supplier_po_publications) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_sp_po_queue_email(p_po purchase_orders, p_pub supplier_po_publications) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_supplier_catalog_price_change_requests()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch uuid := gen_random_uuid();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM sci_new n JOIN sci_old o ON o.id = n.id
    WHERE n.base_price IS DISTINCT FROM o.base_price
       OR n.currency IS DISTINCT FROM o.currency
       OR n.unit_label IS DISTINCT FROM o.unit_label
       OR n.units_per_pack IS DISTINCT FROM o.units_per_pack
  ) THEN
    RETURN NULL;
  END IF;

  IF COALESCE(current_setting('app.audit_source', true), '') = '' THEN
    PERFORM set_config('app.audit_source', 'supplier_portal', true);
  END IF;

  -- 1. O estado novo do artigo substitui qualquer pedido pendente dele.
  UPDATE public.supplier_price_change_requests r
     SET status = 'superseded', superseded_at = now(), superseded_batch_id = v_batch
    FROM sci_new n
    JOIN sci_old o ON o.id = n.id
   WHERE r.catalog_item_id = n.id
     AND r.status = 'pending'
     AND (n.base_price IS DISTINCT FROM o.base_price
          OR n.currency IS DISTINCT FROM o.currency
          OR n.unit_label IS DISTINCT FROM o.unit_label
          OR n.units_per_pack IS DISTINCT FROM o.units_per_pack);

  -- 2. Um pedido por ligação ativa (empresa) cujo preço/unidade difere.
  INSERT INTO public.supplier_price_change_requests (
    organization_id, link_id, supplier_id, catalog_item_id, item_supplier_id, product_id, uom_id,
    old_price, old_currency, new_price, currency, catalog_old_price, catalog_new_price,
    old_unit_label, unit_label, old_units_per_pack, units_per_pack, unit_changed,
    status, batch_id, requested_by_portal_user
  )
  SELECT isup.organization_id, l.id, isup.supplier_id, n.id, isup.id, isup.product_id, isup.uom_id,
         isup.purchase_price, isup.currency, x.np, n.currency, o.base_price, n.base_price,
         x.old_unit, n.unit_label, x.old_upp, n.units_per_pack, x.unit_chg,
         'pending', v_batch, n.updated_by_portal_user
  FROM sci_new n
  JOIN sci_old o ON o.id = n.id
  JOIN public.item_suppliers isup ON isup.catalog_item_id = n.id AND isup.deleted_at IS NULL
  JOIN public.supplier_account_links l
    ON l.supplier_id = isup.supplier_id AND l.supplier_account_id = n.supplier_account_id AND l.status = 'active'
  LEFT JOIN LATERAL (
    SELECT pv.unit_changed, pv.old_unit_label, pv.old_units_per_pack
    FROM public.supplier_price_change_requests pv
    WHERE pv.item_supplier_id = isup.id AND pv.superseded_batch_id = v_batch
    ORDER BY pv.requested_at DESC, pv.id
    LIMIT 1
  ) prev ON true
  CROSS JOIN LATERAL (
    SELECT round(n.base_price, 2) AS np,
           CASE WHEN prev.unit_changed THEN prev.old_unit_label ELSE o.unit_label END AS old_unit,
           CASE WHEN prev.unit_changed THEN prev.old_units_per_pack ELSE o.units_per_pack END AS old_upp
  ) x0
  CROSS JOIN LATERAL (
    SELECT x0.np, x0.old_unit, x0.old_upp,
           (x0.old_unit IS DISTINCT FROM n.unit_label OR x0.old_upp IS DISTINCT FROM n.units_per_pack) AS unit_chg
  ) x
  WHERE n.base_price IS NOT NULL
    AND (n.base_price IS DISTINCT FROM o.base_price
         OR n.currency IS DISTINCT FROM o.currency
         OR n.unit_label IS DISTINCT FROM o.unit_label
         OR n.units_per_pack IS DISTINCT FROM o.units_per_pack)
    AND (x.unit_chg
         OR x.np IS DISTINCT FROM isup.purchase_price
         OR n.currency IS DISTINCT FROM isup.currency);

  -- 3. Encadear os substituídos ao novo pedido da mesma ligação.
  UPDATE public.supplier_price_change_requests s
     SET superseded_by = nw.id
    FROM public.supplier_price_change_requests nw
   WHERE s.superseded_batch_id = v_batch
     AND nw.batch_id = v_batch
     AND nw.item_supplier_id = s.item_supplier_id;

  -- 4. Sino: um aviso por pessoa e fornecedor (atualizado a cada lote).
  BEGIN
    INSERT INTO public.notifications
      (user_id, organization_id, kind, type, title, message, link, entity_type, entity_id, priority, data)
    SELECT u.auth_user_id, g.organization_id, 'notification', 'supplier_price_pending',
           'Preços do fornecedor por aprovar',
           format('%s alterou o preço de %s %s no portal. Por aprovar: %s.',
                  COALESCE(s.name, 'O fornecedor'), g.n_batch,
                  CASE WHEN g.n_batch = 1 THEN 'artigo' ELSE 'artigos' END, pc.n_pending),
           '/suppliers?open=' || g.supplier_id::text || '&tab=portal&prices=pending',
           'supplier', g.supplier_id, 'medium',
           jsonb_build_object('modulo', 'compras', 'supplier_id', g.supplier_id, 'batch_id', v_batch,
                              'batch_count', g.n_batch, 'pending_count', pc.n_pending)
    FROM (
      SELECT organization_id, supplier_id, count(*) AS n_batch
      FROM public.supplier_price_change_requests
      WHERE batch_id = v_batch
      GROUP BY organization_id, supplier_id
    ) g
    JOIN public.suppliers s ON s.id = g.supplier_id
    CROSS JOIN LATERAL (
      SELECT count(*) AS n_pending
      FROM public.supplier_price_change_requests q
      WHERE q.organization_id = g.organization_id AND q.supplier_id = g.supplier_id AND q.status = 'pending'
    ) pc
    JOIN LATERAL (
      SELECT DISTINCT au.auth_user_id
      FROM public.anew_memberships m
      JOIN public.anew_users au ON au.id = m.user_id
      WHERE m.organization_id = g.organization_id
        AND m.status = 'active' AND m.role_is_client IS NOT TRUE
        AND au.deleted_at IS NULL AND au.auth_user_id IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.anew_role_permissions rp
                    WHERE rp.role_id = m.role_id AND rp.permission_code = 'products.manage_prices')
        AND EXISTS (SELECT 1 FROM public.anew_role_permissions rp
                    WHERE rp.role_id = m.role_id AND rp.permission_code = 'products.edit')
    ) u ON true
    ON CONFLICT (type, entity_id, user_id) WHERE is_resolved = false DO UPDATE SET
      organization_id = EXCLUDED.organization_id,
      title = EXCLUDED.title,
      message = EXCLUDED.message,
      link = EXCLUDED.link,
      data = EXCLUDED.data,
      priority = EXCLUDED.priority,
      is_read = false,
      read_at = NULL,
      is_dismissed = false,
      created_at = now();
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Aviso de preços por aprovar não enviado: %', SQLERRM;
  END;

  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_supplier_catalog_price_change_requests() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_supplier_catalog_price_change_requests() TO service_role;
COMMENT ON FUNCTION public.fn_supplier_catalog_price_change_requests() IS 'Portal do fornecedor F3.4b: gatilho por instrução em supplier_catalog_items. Cria pedidos de alteração de preço (um por ligação ativa com o artigo ligado), substitui pendentes e avisa no sino (um aviso por pessoa e fornecedor).';

CREATE OR REPLACE FUNCTION public.fn_supplier_portal_users_block_internal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.auth_user_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('sp_internal:' || NEW.auth_user_id::text, 0));
    IF EXISTS (SELECT 1 FROM public.anew_users u
               JOIN public.anew_memberships m ON m.user_id = u.id
               WHERE u.auth_user_id = NEW.auth_user_id AND m.status = 'active' AND m.role_is_client IS NOT TRUE) THEN
      RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
        USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_supplier_portal_users_block_internal() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_supplier_portal_users_block_internal() TO service_role;
COMMENT ON FUNCTION public.fn_supplier_portal_users_block_internal() IS 'Portal do Fornecedor: recusa utilizador do portal para conta Auth com membership ativa não-cliente.';

CREATE OR REPLACE FUNCTION public.fn_suppliers_portal_nif_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key text;
BEGIN
  IF NEW.tax_id IS NOT DISTINCT FROM OLD.tax_id
     AND NEW.vat_number IS NOT DISTINCT FROM OLD.vat_number
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN
    RETURN NEW;
  END IF;

  SELECT a.nif_key INTO v_key
  FROM public.supplier_account_links l
  JOIN public.supplier_accounts a ON a.id = l.supplier_account_id
  WHERE l.supplier_id = NEW.id AND l.status = 'active'
  LIMIT 1;

  IF v_key IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'Este fornecedor tem acesso ao portal ativo: desligue o portal antes de o mudar de empresa'
      USING ERRCODE = 'check_violation', HINT = 'portal_link_active';
  END IF;

  IF (NULLIF(btrim(NEW.tax_id), '') IS NOT NULL AND public.fn_nif_key(NEW.tax_id) IS DISTINCT FROM v_key)
     OR (NULLIF(btrim(NEW.vat_number), '') IS NOT NULL AND public.fn_nif_key(NEW.vat_number) IS DISTINCT FROM v_key)
     OR (NULLIF(btrim(NEW.tax_id), '') IS NULL AND NULLIF(btrim(NEW.vat_number), '') IS NULL) THEN
    RAISE EXCEPTION 'Este fornecedor tem acesso ao portal ativo: desligue o portal antes de mudar o NIF'
      USING ERRCODE = 'check_violation', HINT = 'portal_link_active';
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_suppliers_portal_nif_guard() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_suppliers_portal_nif_guard() TO service_role;

CREATE OR REPLACE FUNCTION public.fn_validar_ficha_edificio(p_floor text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_canalizacao text, p_gas text, p_amianto text, p_notas_interior text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_piso integer;
BEGIN
  -- ─── Exterior (igual a 20261206160000) ───
  IF p_acesso IS NOT NULL AND p_acesso NOT IN ('facil', 'dificil') THEN
    RAISE EXCEPTION 'Acesso inválido (fácil ou difícil)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_impacto_percent IS NOT NULL AND p_impacto_percent NOT BETWEEN 0 AND 100 THEN
    RAISE EXCEPTION 'O impacto tem de ser um número inteiro entre 0 e 100' USING ERRCODE = 'check_violation';
  END IF;
  IF p_impacto_percent IS NOT NULL AND p_acesso IS DISTINCT FROM 'dificil' THEN
    RAISE EXCEPTION 'O impacto só se indica com acesso difícil' USING ERRCODE = 'check_violation';
  END IF;
  IF p_estacionamento IS NOT NULL AND p_estacionamento NOT IN ('pago', 'nao_pago', 'sem_estacionamento') THEN
    RAISE EXCEPTION 'Estacionamento inválido' USING ERRCODE = 'check_violation';
  END IF;
  IF p_zona_estacionamento IS NOT NULL AND p_zona_estacionamento NOT IN ('verde', 'amarela', 'vermelha') THEN
    RAISE EXCEPTION 'Zona de estacionamento inválida' USING ERRCODE = 'check_violation';
  END IF;
  IF p_zona_estacionamento IS NOT NULL AND p_estacionamento IS DISTINCT FROM 'pago' AND p_estacionamento IS DISTINCT FROM 'nao_pago' THEN
    RAISE EXCEPTION 'A zona só se indica quando há estacionamento' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_elevadores IS NOT NULL AND p_n_elevadores NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'O número de elevadores tem de ser um número inteiro entre 1 e 50' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_elevadores IS NOT NULL AND p_tem_elevador IS NOT TRUE THEN
    RAISE EXCEPTION 'O número de elevadores só se indica quando há elevador' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_andares IS NOT NULL AND p_n_andares NOT BETWEEN 0 AND 200 THEN
    RAISE EXCEPTION 'O número de andares tem de ser um número inteiro entre 0 e 200' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_fracoes_por_andar IS NOT NULL AND p_n_fracoes_por_andar NOT BETWEEN 0 AND 200 THEN
    RAISE EXCEPTION 'O número de frações por andar tem de ser um número inteiro entre 0 e 200' USING ERRCODE = 'check_violation';
  END IF;
  v_piso := public.fn_piso_numerico(p_floor);
  IF v_piso IS NOT NULL AND p_n_andares IS NOT NULL AND v_piso > p_n_andares THEN
    RAISE EXCEPTION 'O piso não pode ser acima do número de andares do edifício' USING ERRCODE = 'check_violation';
  END IF;

  -- ─── Interior ───
  IF p_tipologia IS NOT NULL AND p_tipologia NOT IN ('T0', 'T1', 'T2', 'T3', 'T4', 'T5+') THEN
    RAISE EXCEPTION 'Tipologia inválida (T0 a T5+)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_area_util_m2 IS NOT NULL
     AND (p_area_util_m2 <= 0 OR p_area_util_m2 > 10000 OR p_area_util_m2 <> round(p_area_util_m2, 2)) THEN
    RAISE EXCEPTION 'A área útil tem de ser maior que 0 e até 10000 m² (no máximo 2 casas decimais)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_divisoes IS NOT NULL AND p_n_divisoes NOT BETWEEN 0 AND 100 THEN
    RAISE EXCEPTION 'O número de divisões tem de ser um número inteiro entre 0 e 100' USING ERRCODE = 'check_violation';
  END IF;
  IF p_n_casas_banho IS NOT NULL AND p_n_casas_banho NOT BETWEEN 0 AND 50 THEN
    RAISE EXCEPTION 'O número de casas de banho tem de ser um número inteiro entre 0 e 50' USING ERRCODE = 'check_violation';
  END IF;
  IF p_ano_construcao IS NOT NULL
     AND p_ano_construcao NOT BETWEEN 1800 AND extract(year FROM current_date)::integer THEN
    RAISE EXCEPTION 'O ano de construção tem de ser um ano entre 1800 e o ano atual' USING ERRCODE = 'check_violation';
  END IF;
  IF p_pavimento IS NOT NULL AND p_pavimento NOT IN ('ceramico', 'madeira', 'flutuante', 'vinilico', 'outro') THEN
    RAISE EXCEPTION 'Pavimento inválido' USING ERRCODE = 'check_violation';
  END IF;
  IF p_eletrica IS NOT NULL AND p_eletrica NOT IN ('antiga', 'renovada') THEN
    RAISE EXCEPTION 'Instalação elétrica inválida (antiga ou renovada)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_canalizacao IS NOT NULL AND p_canalizacao NOT IN ('ferro', 'pvc', 'multicamada', 'cobre', 'misto', 'nao_sei') THEN
    RAISE EXCEPTION 'Canalização inválida' USING ERRCODE = 'check_violation';
  END IF;
  IF p_gas IS NOT NULL AND p_gas NOT IN ('canalizado', 'garrafa', 'sem') THEN
    RAISE EXCEPTION 'Gás inválido (canalizado, garrafa ou sem gás)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_amianto IS NOT NULL AND p_amianto NOT IN ('sim', 'nao', 'nao_sei') THEN
    RAISE EXCEPTION 'Amianto inválido (sim, não ou não sei)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_notas_interior IS NOT NULL AND char_length(btrim(p_notas_interior)) > 2000 THEN
    RAISE EXCEPTION 'As notas do interior têm no máximo 2000 caracteres' USING ERRCODE = 'check_violation';
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.fn_validar_ficha_edificio(p_floor text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_canalizacao text, p_gas text, p_amianto text, p_notas_interior text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_validar_ficha_edificio(p_floor text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_canalizacao text, p_gas text, p_amianto text, p_notas_interior text) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_adiar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_proxima_acao_em timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'nota_id', p_id,
    'mudou', public.fn_neg_gravar_nota(
      p_id, p_organization_id, p_entity_id, 'Contacto adiado', NULL, p_proxima_acao_em));
$function$;
REVOKE ALL ON FUNCTION public.neg_adiar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_proxima_acao_em timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_adiar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_proxima_acao_em timestamp with time zone) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_alterar_visita(p_visita_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_local text DEFAULT NULL::text, p_recursos uuid[] DEFAULT NULL::uuid[], p_visit_kind text DEFAULT NULL::text, p_detalhes jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_vis        public.schedule_items;
  v_titulo     text := NULLIF(btrim(p_titulo), '');
  v_notas      text := NULLIF(btrim(p_notas), '');
  v_local      text := NULLIF(btrim(p_local), '');
  v_tipo       text;
  v_ativo      boolean;
  v_det        jsonb;
  v_meta       jsonb;
  v_atuais     uuid[];
  v_recursos   uuid[];
  v_r          uuid;
  v_m_quadro   boolean;
  v_m_titulo   boolean;
  v_m_notas    boolean;
  v_m_local    boolean;
  v_m_horas    boolean;
  v_m_meta     boolean;
  v_m_tipo     boolean;
  v_m_recursos boolean;
  v_dono       jsonb;
  v_n          int;
BEGIN
  -- 1. Visita: configuração, existência, permissão, estado.
  v_vis := public.fn_neg_visita_editavel(p_visita_id, false);

  -- 2. Quadro e recursos da organização e activos (NG008); quadro de
  --    ausências ou de frota não serve (NG009).
  SELECT b.board_type, b.is_active INTO v_tipo, v_ativo
  FROM public.schedule_boards b
  WHERE b.id = p_board_id AND b.organization_id = v_vis.organization_id;
  IF NOT FOUND OR v_ativo IS FALSE THEN
    RAISE EXCEPTION 'Quadro ou recurso indisponível.' USING ERRCODE = 'NG008';
  END IF;
  IF v_tipo IN ('time_off', 'fleet') THEN
    RAISE EXCEPTION 'Valor inválido: este quadro não serve para visitas.' USING ERRCODE = 'NG009';
  END IF;

  v_atuais := (SELECT COALESCE(array_agg(a.resource_id ORDER BY a.resource_id), ARRAY[]::uuid[])
               FROM public.schedule_item_assignees a WHERE a.item_id = v_vis.id);
  IF p_recursos IS NULL THEN
    v_recursos := v_atuais;
  ELSE
    IF cardinality(p_recursos) = 0 OR cardinality(p_recursos) > 20
       OR array_position(p_recursos, NULL) IS NOT NULL THEN
      RAISE EXCEPTION 'Valor inválido: recursos (1 a 20, sem vazios).' USING ERRCODE = 'NG009';
    END IF;
    v_recursos := (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(p_recursos) AS u(x));
    IF (SELECT count(*) FROM public.schedule_resources r
        WHERE r.id = ANY (v_recursos) AND r.organization_id = v_vis.organization_id
          AND r.is_active = true) <> cardinality(v_recursos) THEN
      RAISE EXCEPTION 'Quadro ou recurso indisponível.' USING ERRCODE = 'NG008';
    END IF;
  END IF;

  -- 3. Valores.
  IF p_inicio IS NULL OR p_fim IS NULL OR p_fim <= p_inicio OR p_fim - p_inicio > interval '1 day' THEN
    RAISE EXCEPTION 'Valor inválido: horário da visita (fim depois do início, até 1 dia).' USING ERRCODE = 'NG009';
  END IF;
  IF (p_visit_kind IS NOT NULL AND p_visit_kind NOT IN ('levantamento', 'medicao', 'materiais', 'revisita'))
     OR char_length(v_titulo) > 200 OR char_length(v_notas) > 5000 OR char_length(v_local) > 500 THEN
    RAISE EXCEPTION 'Valor inválido: tipo, título, notas ou local da visita.' USING ERRCODE = 'NG009';
  END IF;
  v_det := public.fn_neg_detalhes_visita(p_detalhes);

  -- O que muda. Título NULL mantém o actual; notas, local, tipo e detalhes
  -- NULL limpam. O metadata vai inteiro, com a chave 'pessoas' trocada.
  v_titulo := COALESCE(v_titulo, v_vis.title);
  v_meta := (COALESCE(v_vis.metadata, '{}'::jsonb) - 'pessoas')
            || CASE WHEN v_det IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('pessoas', v_det) END;
  v_m_quadro   := p_board_id IS DISTINCT FROM v_vis.board_id;
  v_m_titulo   := v_titulo IS DISTINCT FROM v_vis.title;
  v_m_notas    := v_notas IS DISTINCT FROM v_vis.description;
  v_m_local    := v_local IS DISTINCT FROM v_vis.location;
  v_m_horas    := p_inicio IS DISTINCT FROM v_vis.start_datetime OR p_fim IS DISTINCT FROM v_vis.end_datetime;
  v_m_meta     := v_meta IS DISTINCT FROM COALESCE(v_vis.metadata, '{}'::jsonb);
  v_m_tipo     := p_visit_kind IS DISTINCT FROM v_vis.visit_kind;
  v_m_recursos := p_recursos IS NOT NULL AND v_recursos IS DISTINCT FROM v_atuais;

  IF NOT (v_m_quadro OR v_m_titulo OR v_m_notas OR v_m_local OR v_m_horas OR v_m_meta
          OR v_m_tipo OR v_m_recursos) THEN
    RETURN jsonb_build_object('visita_id', v_vis.id, 'mudou', false, 'recursos_mudaram', false,
                              'dono_alterado', false, 'novo_dono', NULL, 'outras_visitas', '[]'::jsonb,
                              'desconfirmada', false);
  END IF;

  -- 3b. Trocar os recursos de uma visita futura pode mudar o dono da lead ou
  --     do cliente (fn_owner_sync_entity_from_visit, DEFINER). Exige poder
  --     editar essa lead (leads.edit, pelo auxiliar DEFINER) e esse cliente
  --     (clients.edit: a leitura FOR NO KEY UPDATE aplica a política de UPDATE).
  IF v_m_recursos AND p_inicio > now() THEN
    -- A lead é resolvida como fn_owner_sync_entity_from_visit a resolve
    -- (lead_id, metadata.lead_id, scheduled_visit_id), também a que o
    -- chamador não vê: auxiliar DEFINER que só devolve boolean. Falha
    -- fechada, mensagem genérica.
    IF NOT public.fn_neg_pode_mudar_dono_lead(v_vis.id) THEN
      RAISE EXCEPTION 'Sem permissão para alterar os recursos desta visita.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_vis.client_id IS NOT NULL THEN
      PERFORM 1 FROM public.anew_clients c
      WHERE c.id = v_vis.client_id AND c.organization_id = v_vis.organization_id AND c.deleted_at IS NULL
      FOR NO KEY UPDATE;
      IF NOT FOUND AND NOT EXISTS (
           SELECT 1 FROM public.anew_clients c
           WHERE c.id = v_vis.client_id
             AND (c.deleted_at IS NOT NULL OR c.organization_id <> v_vis.organization_id)) THEN
        RAISE EXCEPTION 'Sem permissão para mudar o responsável do cliente desta visita.'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;
  END IF;

  -- 4. Conflitos, por ordem de uuid, com bloqueio consultivo por recurso
  --    (exclui a própria visita).
  IF v_m_horas OR v_m_recursos THEN
    FOREACH v_r IN ARRAY v_recursos LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended('agenda:' || v_r::text, 0));
      IF public.check_schedule_conflict(v_r, p_inicio, p_fim, v_vis.id) THEN
        RAISE EXCEPTION 'O recurso já tem outra marcação nesse horário.'
          USING ERRCODE = 'NG010', DETAIL = v_r::text;
      END IF;
    END LOOP;
  END IF;

  -- 5. Escritas: a visita pelo rpc do calendário (horas antes dos recursos,
  --    porque a troca de dono olha para a data já gravada).
  IF v_m_quadro OR v_m_titulo OR v_m_notas OR v_m_local OR v_m_horas OR v_m_meta THEN
    PERFORM public.rpc_update_schedule_item(
      p_id                 => v_vis.id,
      p_board_id           => p_board_id,     p_set_board_id       => v_m_quadro,
      p_title              => v_titulo,       p_set_title          => v_m_titulo,
      p_description        => v_notas,        p_set_description    => v_m_notas,
      p_location           => v_local,        p_set_location       => v_m_local,
      p_start_datetime     => p_inicio,       p_set_start_datetime => v_m_horas,
      p_end_datetime       => p_fim,          p_set_end_datetime   => v_m_horas,
      p_metadata           => v_meta,         p_set_metadata       => v_m_meta);
  END IF;

  IF v_m_recursos THEN
    v_dono := public.rpc_update_schedule_item_assignees(v_vis.id, v_recursos);
  END IF;

  -- Os rpc deixam a auditoria genérica desligada: volta a ligar antes da escrita própria.
  PERFORM set_config('app.audit_bypass', 'off', true);

  IF v_m_tipo THEN
    UPDATE public.schedule_items s SET visit_kind = p_visit_kind WHERE s.id = v_vis.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
      RAISE EXCEPTION 'Sem permissão para alterar a visita.' USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'visita_id', v_vis.id,
    'mudou', true,
    'recursos_mudaram', v_m_recursos,
    'dono_alterado', v_dono IS NOT NULL,
    'novo_dono', v_dono -> 'new_owner',
    'outras_visitas', COALESCE(v_dono -> 'other_visit_ids', '[]'::jsonb),
    -- Mudar as horas de uma visita confirmada passa-a a 'scheduled' (trigger existente).
    'desconfirmada', v_m_horas AND v_vis.status = 'confirmed'::public.schedule_item_status);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_alterar_visita(p_visita_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text, p_notas text, p_local text, p_recursos uuid[], p_visit_kind text, p_detalhes jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_alterar_visita(p_visita_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text, p_notas text, p_local text, p_recursos uuid[], p_visit_kind text, p_detalhes jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_anular_perda(p_negocio_id uuid, p_motivo_reabertura text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_motivo text := btrim(p_motivo_reabertura);
BEGIN
  IF v_motivo IS NULL OR v_motivo = '' OR char_length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'Valor inválido: razão da reabertura (1 a 1000 caracteres).' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto', 'perdido']);

  IF v_neg.estado = 'aberto' THEN
    RETURN jsonb_build_object('mudou', false, 'estado', 'aberto');
  END IF;

  PERFORM set_config('app.negocio_motivo_reabertura', v_motivo, true);
  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n
  SET estado = 'aberto', fase_perda = NULL, motivo_perda = NULL
  WHERE n.id = v_neg.id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);
  PERFORM set_config('app.negocio_motivo_reabertura', '', true);

  RETURN jsonb_build_object('mudou', true, 'estado', 'aberto');
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_anular_perda(p_negocio_id uuid, p_motivo_reabertura text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_anular_perda(p_negocio_id uuid, p_motivo_reabertura text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_anular_perda(p_negocio_id uuid, p_motivo_reabertura text) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_cancelar_visita(p_visita_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_vis public.schedule_items;
BEGIN
  v_vis := public.fn_neg_visita_editavel(p_visita_id, true);

  IF v_vis.status = 'cancelled'::public.schedule_item_status THEN
    RETURN jsonb_build_object('visita_id', v_vis.id, 'mudou', false);
  END IF;

  -- Nunca DELETE; o levantamento que aponte para esta visita fica como está.
  -- Não repõe anew_leads.status nem anew_leads.scheduled_visit_id.
  PERFORM public.rpc_update_schedule_item(
    p_id         => v_vis.id,
    p_status     => 'cancelled'::public.schedule_item_status,
    p_set_status => true);
  PERFORM set_config('app.audit_bypass', 'off', true);

  RETURN jsonb_build_object('visita_id', v_vis.id, 'mudou', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_cancelar_visita(p_visita_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_cancelar_visita(p_visita_id uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_classificar_lead(p_organization_id uuid, p_lead_id uuid, p_tipo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid;
  v_antes  public.anew_leads;
  v_lead   public.anew_leads;
  v_bypass text;
BEGIN
  IF p_organization_id IS NULL OR p_lead_id IS NULL
     OR (p_tipo IS NOT NULL AND p_tipo NOT IN ('mql', 'sql')) THEN
    RAISE EXCEPTION 'Valor inválido: organização, lead ou classificação (mql, sql ou nula).'
      USING ERRCODE = 'NG009';
  END IF;

  v_actor := public.current_business_user_id();
  IF auth.uid() IS NULL OR v_actor IS NULL THEN
    RAISE EXCEPTION 'Sem sessão ou sem perfil de utilizador: não é possível classificar a lead.' USING ERRCODE = '42501';
  END IF;

  -- 1. A lead, como quem chama a vê (política anew_leads_select: leads.view
  --    com âmbito), presa à organização pedida.
  PERFORM 1 FROM public.anew_leads l
  WHERE l.id = p_lead_id AND l.organization_id = p_organization_id AND l.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 2. Tranca a linha. Com RLS, FOR UPDATE só devolve a linha se a política
  --    anew_leads_update (leads.edit com âmbito: organização inteira, comercial
  --    ou quem criou) também a deixar: vista mas não editável dá 42501.
  SELECT l.* INTO v_antes
  FROM public.anew_leads l
  WHERE l.id = p_lead_id AND l.organization_id = p_organization_id AND l.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sem permissão para classificar esta lead (leads.edit).' USING ERRCODE = '42501';
  END IF;

  -- 3. Já está assim: não se escreve nada.
  IF v_antes.qualification_type IS NOT DISTINCT FROM p_tipo THEN
    RETURN jsonb_build_object('mudou', false,
                              'qualificacao_tipo', v_antes.qualification_type,
                              'qualificado_em', v_antes.qualified_at);
  END IF;

  -- 4. Só as colunas da classificação, com as regras de rpc_update_lead
  --    (p_qualification_changed = true): qualified_at fica a primeira vez que
  --    a lead foi classificada (não muda ao trocar nem ao limpar);
  --    qualification_set_by é quem mudou. O gatilho de auditoria genérico fica
  --    calado (app.audit_bypass), como em rpc_update_lead, porque a linha de
  --    auditoria é escrita à mão a seguir; o valor anterior repõe-se logo.
  v_bypass := current_setting('app.audit_bypass', true);
  PERFORM set_config('app.audit_bypass', 'on', true);
  UPDATE public.anew_leads l
     SET qualification_type   = p_tipo,
         qualified_at         = CASE WHEN p_tipo IS NOT NULL AND l.qualified_at IS NULL
                                     THEN now() ELSE l.qualified_at END,
         qualification_set_by = v_actor,
         updated_at           = now()
   WHERE l.id = v_antes.id
  RETURNING l.* INTO v_lead;
  PERFORM set_config('app.audit_bypass', COALESCE(v_bypass, ''), true);
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'Sem permissão para classificar esta lead (leads.edit).' USING ERRCODE = '42501';
  END IF;

  -- 5. Uma linha de auditoria, no formato de rpc_update_lead (só a
  --    qualificação, a única coluna com significado que mudou).
  PERFORM public.fn_manual_audit_log(
    'anew_leads',
    COALESCE(v_lead.entity_id, v_lead.id),
    v_lead.organization_id,
    'UPDATE',
    jsonb_build_object('anew_leads', jsonb_build_object('qualification_type',
      jsonb_build_object('old', to_jsonb(v_antes.qualification_type),
                         'new', to_jsonb(v_lead.qualification_type)))),
    'web_app');

  -- 6. O histórico de qualificação (anew_entity_history), como em
  --    rpc_update_lead, mas só com entidade e sem engolir erros: a função é
  --    INVOKER e a política de inserção pede a entidade no âmbito de quem
  --    chama; se falhar, nada fica gravado (a classificação inteira volta
  --    atrás) em vez de ficar sem histórico em silêncio. A recusa da RLS aqui
  --    é uma regra diferente da de leads.edit (a pessoa fora do âmbito), por
  --    isso sai com código próprio, NG027, e não como o 42501 do passo 2.
  IF v_lead.entity_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.anew_entity_history
        (entity_id, change_type, field_name, old_value, new_value, changed_by, metadata)
      VALUES
        (v_lead.entity_id, 'qualification_changed', 'qualification_type',
         v_antes.qualification_type, v_lead.qualification_type, v_actor,
         jsonb_build_object('organization_id', v_lead.organization_id, 'lead_id', v_lead.id));
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE EXCEPTION 'Sem permissão sobre a pessoa desta lead: não é possível classificá-la.'
        USING ERRCODE = 'NG027';
    END;
  END IF;

  RETURN jsonb_build_object('mudou', true,
                            'qualificacao_tipo', v_lead.qualification_type,
                            'qualificado_em', v_lead.qualified_at);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_classificar_lead(p_organization_id uuid, p_lead_id uuid, p_tipo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_classificar_lead(p_organization_id uuid, p_lead_id uuid, p_tipo text) TO authenticated;
COMMENT ON FUNCTION public.neg_classificar_lead(p_organization_id uuid, p_lead_id uuid, p_tipo text) IS 'Pessoas: classifica a lead (MQL, SQL ou limpar) gravando só a classificação: qualification_type, qualified_at (a primeira), qualification_set_by e updated_at, uma linha de auditoria e o histórico (anew_entity_history), com as regras de rpc_update_lead, que não é tocada. INVOKER: exige leads.edit com âmbito (política anew_leads_update). NG003, NG009, NG027, 42501. 20261226200000.';

CREATE OR REPLACE FUNCTION public.neg_criar_contrato(p_negocio_id uuid, p_client_id uuid, p_entity_id uuid, p_organization_id uuid, p_root_organization_id uuid, p_proposal_id uuid, p_contract_template_id uuid, p_total_value numeric, p_currency text, p_start_date date, p_end_date date, p_notes text, p_payment_terms text, p_contract_body_html text, p_final_body_html text, p_prompt_values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_id     uuid;
  v_ligado uuid;
BEGIN
  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);

  IF v_neg.fecho <> 'contrato' THEN
    RAISE EXCEPTION 'Este negócio fecha na proposta (venda directa): não leva contratos.'
      USING ERRCODE = 'NG023';
  END IF;
  IF p_organization_id IS DISTINCT FROM v_neg.organization_id
     OR p_entity_id IS DISTINCT FROM v_neg.entity_id THEN
    RAISE EXCEPTION 'O contrato tem de ser da mesma organização e da mesma pessoa do negócio.'
      USING ERRCODE = 'NG004';
  END IF;

  PERFORM set_config('app.neg_criar_contrato', v_neg.id::text, true);
  v_id := public.rpc_create_client_contract(
    p_client_id, p_entity_id, p_organization_id, p_root_organization_id, p_proposal_id,
    p_contract_template_id, p_total_value, p_currency, p_start_date, p_end_date, p_notes,
    p_payment_terms, p_contract_body_html, p_final_body_html, p_prompt_values);
  PERFORM set_config('app.neg_criar_contrato', '', true);

  SELECT cc.negocio_id INTO v_ligado FROM public.client_contracts cc WHERE cc.id = v_id;
  IF FOUND AND v_ligado IS DISTINCT FROM v_neg.id THEN
    RAISE EXCEPTION 'O contrato não ficou ligado ao negócio.' USING ERRCODE = 'NG004';
  END IF;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_criar_contrato(p_negocio_id uuid, p_client_id uuid, p_entity_id uuid, p_organization_id uuid, p_root_organization_id uuid, p_proposal_id uuid, p_contract_template_id uuid, p_total_value numeric, p_currency text, p_start_date date, p_end_date date, p_notes text, p_payment_terms text, p_contract_body_html text, p_final_body_html text, p_prompt_values jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_criar_contrato(p_negocio_id uuid, p_client_id uuid, p_entity_id uuid, p_organization_id uuid, p_root_organization_id uuid, p_proposal_id uuid, p_contract_template_id uuid, p_total_value numeric, p_currency text, p_start_date date, p_end_date date, p_notes text, p_payment_terms text, p_contract_body_html text, p_final_body_html text, p_prompt_values jsonb) TO authenticated;
COMMENT ON FUNCTION public.neg_criar_contrato(p_negocio_id uuid, p_client_id uuid, p_entity_id uuid, p_organization_id uuid, p_root_organization_id uuid, p_proposal_id uuid, p_contract_template_id uuid, p_total_value numeric, p_currency text, p_start_date date, p_end_date date, p_notes text, p_payment_terms text, p_contract_body_html text, p_final_body_html text, p_prompt_values jsonb) IS 'Pessoas: cria um contrato já ligado ao negócio (aberto, com fecho no contrato), envolvendo rpc_create_client_contract sem a alterar. NG001, NG002, NG004, NG008, NG023. Se rpc_create_client_contract mudar de argumentos, esta função tem de acompanhar. 20261226150000.';

CREATE OR REPLACE FUNCTION public.neg_criar_lead(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_source   text := btrim(COALESCE(p_source, 'manual'));
  v_comercial uuid;
  v_lead     public.anew_leads;
BEGIN
  -- 1. Valores
  IF p_id IS NULL OR v_source = '' OR char_length(v_source) > 50 THEN
    RAISE EXCEPTION 'Valor inválido: identificador ou origem (1 a 50 caracteres).' USING ERRCODE = 'NG009';
  END IF;

  -- 2. Configuração (D1), permissão, pessoa visível
  PERFORM public.fn_neg_exigir_config(p_organization_id);
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'leads.create') THEN
    RAISE EXCEPTION 'Sem permissão para criar leads nesta organização.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  -- 3. Comercial: o indicado ou quem cria; membro activo e não cliente.
  v_comercial := COALESCE(p_assigned_to, public.fn_neg_actor());
  IF v_comercial IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.anew_memberships m
       WHERE m.user_id = v_comercial AND m.organization_id = p_organization_id
         AND m.status = 'active' AND m.role_is_client IS NOT TRUE) THEN
    RAISE EXCEPTION 'Valor inválido: o comercial tem de ser membro activo da organização.'
      USING ERRCODE = 'NG009';
  END IF;

  -- 4. Uma pessoa de cada vez (mesma chave de neg_ganhar_negocio).
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'neg_pessoa:' || p_organization_id::text || ':' || p_entity_id::text, 0));

  -- 5. Lead aberta visível (em curso ou encerrada reabrível): não se duplica;
  --    devolve-a (a em curso primeiro). Convertidas e mortas não contam.
  SELECT l.* INTO v_lead
  FROM public.anew_leads l
  WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
    AND l.deleted_at IS NULL AND public.fn_neg_lead_aberta(l.status::text)
  ORDER BY (l.closure_result IS NULL) DESC, l.created_at DESC
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'criada', false, 'ja_existia', true, 'mudou', false, 'lead_id', v_lead.id,
      'encerrada', v_lead.closure_result IS NOT NULL);
  END IF;

  -- 6. Lead aberta que o chamador não vê: recusa sem dizer qual.
  IF public.fn_neg_tem_lead_aberta(p_organization_id, p_entity_id) THEN
    RAISE EXCEPTION 'A pessoa já tem uma lead.' USING ERRCODE = 'NG016';
  END IF;

  -- 7. Criar pela função existente (sem e-mail nem telefone: a pessoa já os tem).
  SELECT r.* INTO v_lead
  FROM public.rpc_create_lead_manual(
    p_organization_id,
    public.resolve_root_organization_id(p_organization_id),
    p_entity_id,
    false,
    '{}'::jsonb,
    NULL::text,
    NULL::text,
    v_source,
    NULL::uuid,
    NULL::uuid,
    v_comercial) AS r;

  -- O rpc deixa a auditoria genérica desligada até ao fim da transacção.
  PERFORM set_config('app.audit_bypass', 'off', true);

  RETURN jsonb_build_object(
    'criada', true, 'ja_existia', false, 'mudou', true, 'lead_id', v_lead.id,
    'encerrada', false);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_criar_lead(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assigned_to uuid, p_source text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_criar_lead(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_assigned_to uuid, p_source text) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_criar_negocio(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_titulo text, p_notas text DEFAULT NULL::text, p_assigned_to uuid DEFAULT NULL::uuid, p_registos jsonb DEFAULT '[]'::jsonb, p_levantamento_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_reabrir_abordagem boolean DEFAULT false, p_fecho text DEFAULT 'contrato'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_titulo     text := btrim(p_titulo);
  v_notas      text := NULLIF(btrim(p_notas), '');
  v_registos   jsonb := COALESCE(p_registos, '[]'::jsonb);
  v_lead       public.anew_leads;
  v_existente  public.negocios;
  v_reg        record;
  v_ligados    jsonb := '[]'::jsonb;
  v_recusados  jsonb := '[]'::jsonb;
  v_n          int;
BEGIN
  IF p_id IS NULL OR v_titulo IS NULL OR v_titulo = '' OR char_length(v_titulo) > 200
     OR char_length(v_notas) > 5000 THEN
    RAISE EXCEPTION 'Valor inválido: identificador, título (1 a 200) ou notas (até 5000).' USING ERRCODE = 'NG009';
  END IF;
  IF p_fecho IS NULL OR p_fecho NOT IN ('proposta', 'contrato') THEN
    RAISE EXCEPTION 'Valor inválido: tipo de fecho (proposta ou contrato).' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_typeof(v_registos) <> 'array' THEN
    RAISE EXCEPTION 'Valor inválido: registos.' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_array_length(v_registos) > 100 OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_registos) AS e(valor)
       WHERE jsonb_typeof(e.valor) <> 'object'
          OR (e.valor ->> 'tipo') IS NULL
          OR (e.valor ->> 'tipo') NOT IN ('contacto', 'visita', 'orcamento', 'proposta', 'contrato')
          OR (e.valor ->> 'id') IS NULL
          OR (e.valor ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') THEN
    RAISE EXCEPTION 'Valor inválido: registos (até 100; tipo contacto, visita, orcamento, proposta ou contrato; id uuid).'
      USING ERRCODE = 'NG009';
  END IF;

  PERFORM public.fn_neg_exigir_config(p_organization_id);
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  -- Reenvio do mesmo id: devolve-o como está, antes de qualquer outra regra.
  SELECT n.* INTO v_existente FROM public.negocios n WHERE n.id = p_id;
  IF FOUND THEN
    IF v_existente.organization_id <> p_organization_id OR v_existente.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
    END IF;
    RETURN jsonb_build_object('negocio_id', p_id, 'mudou', false, 'ligados', '[]'::jsonb,
                              'recusados', '[]'::jsonb, 'lead_escolhida', NULL);
  END IF;

  -- A lead aberta a que o negócio corresponde (só informação; não se altera).
  SELECT * INTO v_lead FROM public.fn_neg_escolher_lead(p_organization_id, p_entity_id, p_lead_id, 'aberta');
  IF v_lead.id IS NOT NULL AND v_lead.closure_result IS NOT NULL
     AND NOT COALESCE(p_reabrir_abordagem, false) THEN
    RAISE EXCEPTION 'A abordagem desta pessoa está encerrada.' USING ERRCODE = 'NG002';
  END IF;

  -- Criar (RLS negocios_insert: pessoas.create na organização, pessoa ligada,
  -- comercial membro activo). Corrida com outro reenvio: devolve-o como está.
  INSERT INTO public.negocios (id, organization_id, entity_id, titulo, notas, assigned_to, fecho)
  VALUES (p_id, p_organization_id, p_entity_id, v_titulo, v_notas, p_assigned_to, p_fecho)
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 0 THEN
    SELECT n.* INTO v_existente FROM public.negocios n WHERE n.id = p_id;
    IF NOT FOUND OR v_existente.organization_id <> p_organization_id
       OR v_existente.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
    END IF;
    RETURN jsonb_build_object('negocio_id', p_id, 'mudou', false, 'ligados', '[]'::jsonb,
                              'recusados', '[]'::jsonb, 'lead_escolhida', NULL);
  END IF;

  -- Ligações (exigem pessoas.edit: NG001 aborta tudo; NG004, NG014, NG023 e
  -- NG024 vão para recusados).
  FOR v_reg IN
    SELECT e.valor ->> 'tipo' AS tipo, (e.valor ->> 'id')::uuid AS id
    FROM jsonb_array_elements(v_registos) AS e(valor)
    UNION ALL
    SELECT 'levantamento', p_levantamento_id WHERE p_levantamento_id IS NOT NULL
  LOOP
    BEGIN
      PERFORM public.neg_ligar_registo(p_id, v_reg.tipo, v_reg.id);
      v_ligados := v_ligados || jsonb_build_object('tipo', v_reg.tipo, 'id', v_reg.id);
    EXCEPTION WHEN SQLSTATE 'NG004' OR SQLSTATE 'NG014' OR SQLSTATE 'NG023' OR SQLSTATE 'NG024' THEN
      v_recusados := v_recusados || jsonb_build_object('tipo', v_reg.tipo, 'id', v_reg.id);
    END;
  END LOOP;

  IF v_lead.id IS NOT NULL AND v_lead.closure_result IS NOT NULL THEN
    PERFORM public.fn_neg_mudar_abordagem(
      p_organization_id, p_entity_id, v_lead.id, NULL, NULL, 'Reaberta ao criar um negócio');
  END IF;

  RETURN jsonb_build_object('negocio_id', p_id, 'mudou', true, 'ligados', v_ligados,
                            'recusados', v_recusados,
                            'lead_escolhida', CASE WHEN public.fn_neg_lead_aberta(v_lead.status::text)
                                                   THEN v_lead.id END);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_criar_negocio(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_titulo text, p_notas text, p_assigned_to uuid, p_registos jsonb, p_levantamento_id uuid, p_lead_id uuid, p_reabrir_abordagem boolean, p_fecho text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_criar_negocio(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_titulo text, p_notas text, p_assigned_to uuid, p_registos jsonb, p_levantamento_id uuid, p_lead_id uuid, p_reabrir_abordagem boolean, p_fecho text) TO authenticated;
COMMENT ON FUNCTION public.neg_criar_negocio(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_titulo text, p_notas text, p_assigned_to uuid, p_registos jsonb, p_levantamento_id uuid, p_lead_id uuid, p_reabrir_abordagem boolean, p_fecho text) IS 'Pessoas: cria um negócio aberto com o tipo de fecho (p_fecho proposta ou contrato; omissão contrato) e liga os registos indicados. NG009 valores; NG008 sem Pessoas; NG003 pessoa; NG002 abordagem encerrada; NG004/NG014/NG023/NG024 vão para recusados. 20261226110000.';

CREATE OR REPLACE FUNCTION public.neg_criar_orcamento(p_negocio_id uuid, p_quote_data jsonb, p_lines jsonb, p_fees jsonb, p_totals jsonb, p_inline_quotes jsonb DEFAULT '[]'::jsonb, p_diagnostic_suggestions jsonb DEFAULT '[]'::jsonb)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg public.negocios;
  v_q   public.quotes;
BEGIN
  IF p_quote_data IS NULL OR jsonb_typeof(p_quote_data) <> 'object' THEN
    RAISE EXCEPTION 'Valor inválido: dados do orçamento.' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);

  IF NULLIF(p_quote_data ->> 'organization_id', '')::uuid IS DISTINCT FROM v_neg.organization_id
     OR NULLIF(p_quote_data ->> 'entity_id', '')::uuid IS DISTINCT FROM v_neg.entity_id THEN
    RAISE EXCEPTION 'O orçamento tem de ser da mesma organização e da mesma pessoa do negócio.'
      USING ERRCODE = 'NG004';
  END IF;

  PERFORM set_config('app.neg_criar_orcamento', v_neg.id::text, true);
  v_q := public.rpc_save_quote(NULL::uuid, p_quote_data, p_lines, p_fees, p_totals,
                               p_inline_quotes, p_diagnostic_suggestions);
  PERFORM set_config('app.neg_criar_orcamento', '', true);

  IF v_q.negocio_id IS DISTINCT FROM v_neg.id THEN
    RAISE EXCEPTION 'O orçamento não ficou ligado ao negócio.' USING ERRCODE = 'NG004';
  END IF;
  RETURN v_q;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_criar_orcamento(p_negocio_id uuid, p_quote_data jsonb, p_lines jsonb, p_fees jsonb, p_totals jsonb, p_inline_quotes jsonb, p_diagnostic_suggestions jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_criar_orcamento(p_negocio_id uuid, p_quote_data jsonb, p_lines jsonb, p_fees jsonb, p_totals jsonb, p_inline_quotes jsonb, p_diagnostic_suggestions jsonb) TO authenticated;
COMMENT ON FUNCTION public.neg_criar_orcamento(p_negocio_id uuid, p_quote_data jsonb, p_lines jsonb, p_fees jsonb, p_totals jsonb, p_inline_quotes jsonb, p_diagnostic_suggestions jsonb) IS 'Pessoas: cria um orçamento já ligado ao negócio (aberto), envolvendo rpc_save_quote (criação) sem a alterar. NG001, NG002, NG004, NG008, NG009. Se rpc_save_quote mudar de argumentos, esta função tem de acompanhar. 20261226150000.';

CREATE OR REPLACE FUNCTION public.neg_criar_proposta(p_negocio_id uuid, p_proposal_data jsonb, p_selected_quote_ids uuid[] DEFAULT ARRAY[]::uuid[], p_inline_quotes jsonb DEFAULT '[]'::jsonb, p_proposal_items jsonb DEFAULT '[]'::jsonb, p_quote_entity_id uuid DEFAULT NULL::uuid)
 RETURNS proposals
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg public.negocios;
  v_p   public.proposals;
BEGIN
  IF p_proposal_data IS NULL OR jsonb_typeof(p_proposal_data) <> 'object' THEN
    RAISE EXCEPTION 'Valor inválido: dados da proposta.' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);

  IF NULLIF(p_proposal_data ->> 'organization_id', '')::uuid IS DISTINCT FROM v_neg.organization_id
     OR NULLIF(p_proposal_data ->> 'entity_id', '')::uuid IS DISTINCT FROM v_neg.entity_id THEN
    RAISE EXCEPTION 'A proposta tem de ser da mesma organização e da mesma pessoa do negócio.'
      USING ERRCODE = 'NG004';
  END IF;

  -- 20261226180000: a regra do ecrã (temPropostaEnviadaOuAceite, em
  -- src/hooks/pessoas/documentosDoNegocio.ts, com propostaRecusada e
  -- estadoPropostaDeDb), sobre as mesmas propostas que a ficha mostra no
  -- negócio. Uma proposta conta se o cliente não a recusou e já saiu de
  -- rascunho: estado de aceite ou de enviada, ou, com um estado desconhecido,
  -- accepted_at ou sent_at preenchidos. O negócio está trancado (FOR NO KEY
  -- UPDATE em fn_neg_negocio_editavel): duas criações ao mesmo tempo não passam
  -- as duas.
  IF EXISTS (
    SELECT 1
    FROM public.proposals pr
    CROSS JOIN LATERAL (SELECT lower(btrim(COALESCE(pr.status::text, ''))) AS s) e
    WHERE pr.negocio_id = v_neg.id
      AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
      AND e.s NOT IN ('rejeitado', 'rejeitada', 'recusado', 'recusada', 'rejected', 'declined', 'lost')
      AND e.s NOT IN ('draft', 'rascunho')
      AND (e.s IN ('accepted', 'aceite', 'aceita', 'approved',
                   'sent', 'viewed', 'enviada', 'enviado', 'expired')
           OR pr.accepted_at IS NOT NULL OR pr.sent_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'Este negócio já tem uma proposta enviada ou aceite: não se cria outra.'
      USING ERRCODE = 'NG025';
  END IF;

  PERFORM set_config('app.neg_criar_proposta', v_neg.id::text, true);
  v_p := public.rpc_create_proposal(p_proposal_data, p_selected_quote_ids, p_inline_quotes,
                                    p_proposal_items, p_quote_entity_id);
  PERFORM set_config('app.neg_criar_proposta', '', true);

  IF v_p.negocio_id IS DISTINCT FROM v_neg.id THEN
    RAISE EXCEPTION 'A proposta não ficou ligada ao negócio.' USING ERRCODE = 'NG004';
  END IF;
  RETURN v_p;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_criar_proposta(p_negocio_id uuid, p_proposal_data jsonb, p_selected_quote_ids uuid[], p_inline_quotes jsonb, p_proposal_items jsonb, p_quote_entity_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_criar_proposta(p_negocio_id uuid, p_proposal_data jsonb, p_selected_quote_ids uuid[], p_inline_quotes jsonb, p_proposal_items jsonb, p_quote_entity_id uuid) TO authenticated;
COMMENT ON FUNCTION public.neg_criar_proposta(p_negocio_id uuid, p_proposal_data jsonb, p_selected_quote_ids uuid[], p_inline_quotes jsonb, p_proposal_items jsonb, p_quote_entity_id uuid) IS 'Pessoas: cria uma proposta já ligada ao negócio (aberto), envolvendo rpc_create_proposal sem a alterar. Recusa uma segunda proposta enviada ou aceite (não recusada) no mesmo negócio, com a regra do ecrã (NG025). NG001, NG002, NG004, NG008, NG009, NG025. Se rpc_create_proposal mudar de argumentos, esta função tem de acompanhar. 20261226150000, 20261226180000.';

CREATE OR REPLACE FUNCTION public.neg_desligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_existe boolean;
  v_atual  uuid;
  v_n      int;
BEGIN
  IF p_registo_id IS NULL OR p_tipo IS NULL
     OR p_tipo NOT IN ('contacto', 'visita', 'levantamento', 'orcamento', 'proposta', 'contrato') THEN
    RAISE EXCEPTION 'Valor inválido: tipo ou registo.' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);

  IF p_tipo = 'levantamento' THEN
    RAISE EXCEPTION 'Este registo não se desliga.' USING ERRCODE = 'NG005';
  END IF;

  IF p_tipo = 'contacto' THEN
    SELECT true, i.negocio_id INTO v_existe, v_atual
    FROM public.entity_interactions i
    WHERE i.id = p_registo_id AND i.organization_id = v_neg.organization_id
      AND i.entity_id = v_neg.entity_id;
    IF v_existe AND v_atual IS NULL THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    UPDATE public.entity_interactions i SET negocio_id = NULL
    WHERE i.id = p_registo_id AND i.organization_id = v_neg.organization_id
      AND i.entity_id = v_neg.entity_id AND i.negocio_id = v_neg.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;

  ELSIF p_tipo = 'visita' THEN
    SELECT true, s.negocio_id INTO v_existe, v_atual
    FROM public.schedule_items s
    WHERE s.id = p_registo_id AND s.organization_id = v_neg.organization_id;
    IF v_existe AND v_atual IS NULL THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    UPDATE public.schedule_items s SET negocio_id = NULL
    WHERE s.id = p_registo_id AND s.organization_id = v_neg.organization_id
      AND s.negocio_id = v_neg.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;

  ELSIF p_tipo = 'orcamento' THEN
    SELECT true, q.negocio_id INTO v_existe, v_atual
    FROM public.quotes q
    WHERE q.id = p_registo_id AND q.organization_id = v_neg.organization_id
      AND q.entity_id = v_neg.entity_id;
    IF v_existe AND v_atual IS NULL THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.quotes q SET negocio_id = NULL
    WHERE q.id = p_registo_id AND q.organization_id = v_neg.organization_id
      AND q.entity_id = v_neg.entity_id AND q.negocio_id = v_neg.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);

  ELSIF p_tipo = 'proposta' THEN
    SELECT true, pr.negocio_id INTO v_existe, v_atual
    FROM public.proposals pr
    WHERE pr.id = p_registo_id AND pr.organization_id = v_neg.organization_id
      AND pr.entity_id = v_neg.entity_id;
    IF v_existe AND v_atual IS NULL THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.proposals pr SET negocio_id = NULL
    WHERE pr.id = p_registo_id AND pr.organization_id = v_neg.organization_id
      AND pr.entity_id = v_neg.entity_id AND pr.negocio_id = v_neg.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);

  ELSE -- contrato
    SELECT true, cc.negocio_id INTO v_existe, v_atual
    FROM public.client_contracts cc
    WHERE cc.id = p_registo_id AND cc.organization_id = v_neg.organization_id
      AND cc.entity_id = v_neg.entity_id;
    IF v_existe AND v_atual IS NULL THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.client_contracts cc SET negocio_id = NULL
    WHERE cc.id = p_registo_id AND cc.organization_id = v_neg.organization_id
      AND cc.entity_id = v_neg.entity_id AND cc.negocio_id = v_neg.id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);
  END IF;

  IF v_n = 0 THEN
    RAISE EXCEPTION 'Registo indisponível para desligar.' USING ERRCODE = 'NG004';
  END IF;
  RETURN jsonb_build_object('mudou', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_desligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_desligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_desligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_dispensar_alerta(p_negocio_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg public.negocios;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT n.* INTO v_neg FROM public.negocios n
  WHERE n.id = p_negocio_id AND n.deleted_at IS NULL
  FOR NO KEY UPDATE;
  IF NOT FOUND OR NOT public.fn_neg_pode_editar(v_neg) THEN
    RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
  END IF;
  PERFORM public.fn_neg_exigir_config(v_neg.organization_id);

  IF v_neg.alerta_codigo IS NULL THEN
    RETURN jsonb_build_object('mudou', false, 'estado', v_neg.estado);
  END IF;

  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n SET alerta_codigo = NULL WHERE n.id = v_neg.id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);

  PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
    'Alerta dispensado: ' || v_neg.alerta_codigo, NULL, NULL, NULL, 'crm', NULL, NULL);

  RETURN jsonb_build_object('mudou', true, 'estado', v_neg.estado, 'alerta', v_neg.alerta_codigo);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_dispensar_alerta(p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_dispensar_alerta(p_negocio_id uuid) TO authenticated;
COMMENT ON FUNCTION public.neg_dispensar_alerta(p_negocio_id uuid) IS 'Pessoas: limpa o alerta em aberto do negócio («Manter perdido» e afins), com pessoas.edit, e regista acompanhamento. 20261226140000.';

CREATE OR REPLACE FUNCTION public.neg_encerrar_abordagem(p_organization_id uuid, p_entity_id uuid, p_resultado text, p_motivo text, p_motivo_outro text DEFAULT NULL::text, p_lead_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_outro text := NULLIF(btrim(p_motivo_outro), '');
BEGIN
  IF p_resultado IS NULL OR p_resultado NOT IN ('semInteresse', 'obraInviavel')
     OR p_motivo IS NULL OR p_motivo NOT IN
        ('preco', 'adiou', 'outraEmpresa', 'semResposta', 'naoProcurava', 'outro') THEN
    RAISE EXCEPTION 'Valor inválido: resultado ou motivo do encerramento.' USING ERRCODE = 'NG009';
  END IF;
  IF (p_motivo = 'outro') <> (v_outro IS NOT NULL) OR char_length(v_outro) > 300 THEN
    RAISE EXCEPTION 'Valor inválido: o motivo "outro" exige um texto até 300 caracteres (e só ele).'
      USING ERRCODE = 'NG009';
  END IF;

  RETURN public.fn_neg_mudar_abordagem(
    p_organization_id, p_entity_id, p_lead_id, p_resultado, p_motivo, v_outro);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_encerrar_abordagem(p_organization_id uuid, p_entity_id uuid, p_resultado text, p_motivo text, p_motivo_outro text, p_lead_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_encerrar_abordagem(p_organization_id uuid, p_entity_id uuid, p_resultado text, p_motivo text, p_motivo_outro text, p_lead_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_encerrar_abordagem(p_organization_id uuid, p_entity_id uuid, p_resultado text, p_motivo text, p_motivo_outro text, p_lead_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_ficha_pessoa(p_organization_id uuid, p_entity_id uuid, p_limite integer DEFAULT 30, p_depois jsonb DEFAULT NULL::jsonb, p_partes text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_momento   text;
  v_conv      text;
  v_base      boolean;
  v_lead      public.anew_leads;
  v_cli       public.anew_clients;
  v_lds       uuid[];
  v_pessoa    jsonb;
  v_lead_j    jsonb;
  v_abertas   jsonb;
  v_agreg     jsonb;
  v_perm      jsonb;
  v_negocios  jsonb;
  v_docs      jsonb;
  v_ng        record;
  v_ct        record;
  v_vs        record;
  v_lv_por    bigint;
  v_etapa     text;
  v_res       jsonb;
  v_uid       uuid;
  v_ch_editar text[];
  v_ch_apagar text[];
BEGIN
  -- 1. Valores
  IF p_limite IS NULL OR p_limite < 1 OR p_limite > 100
     OR (p_partes IS NOT NULL AND (cardinality(p_partes) = 0 OR EXISTS (
           SELECT 1 FROM unnest(p_partes) AS x(parte)
           WHERE x.parte IS NULL
              OR x.parte NOT IN ('base', 'contactos', 'visitas', 'levantamentos', 'atividade'))))
     OR (p_depois IS NOT NULL AND jsonb_typeof(p_depois) NOT IN ('object', 'null')) THEN
    RAISE EXCEPTION 'Valor inválido: limite (1 a 100), partes ou páginas.' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_typeof(p_depois) = 'object' THEN
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_depois) AS k(chave)
               WHERE k.chave NOT IN ('contactos', 'visitas', 'levantamentos', 'atividade')) THEN
      RAISE EXCEPTION 'Valor inválido: páginas.' USING ERRCODE = 'NG009';
    END IF;
  END IF;

  -- 2. Guardas, antes de qualquer leitura de registos; as secções não as
  --    repetem para esta organização e pessoa nesta transacção.
  v_momento := public.fn_neg_exigir_config(p_organization_id);
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);
  PERFORM set_config('app.neg_ficha_verificada',
                     p_organization_id::text || ':' || p_entity_id::text, true);

  v_base := p_partes IS NULL OR 'base' = ANY (p_partes);

  IF v_base THEN
    -- A lead (a mais recente viva) e o cliente (o mais antigo vivo), como no resumo.
    SELECT l.* INTO v_lead
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id AND l.deleted_at IS NULL
    ORDER BY l.created_at DESC, l.id DESC
    LIMIT 1;
    SELECT c.* INTO v_cli
    FROM public.anew_clients c
    WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id AND c.deleted_at IS NULL
    ORDER BY c.created_at ASC, c.id ASC
    LIMIT 1;
    v_lds := ARRAY(SELECT l.id FROM public.anew_leads l
                   WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                     AND l.deleted_at IS NULL);

    -- Agregados: os mesmos predicados de neg_resumo_pessoas.
    SELECT count(*) FILTER (WHERE n.estado = 'aberto')  AS abertos,
           count(*) FILTER (WHERE n.estado = 'ganho')   AS ganhos,
           count(*) FILTER (WHERE n.estado = 'perdido') AS perdidos,
           count(*) AS total,
           max(n.created_at) AS ultimo_em
      INTO v_ng
    FROM public.negocios n
    WHERE n.organization_id = p_organization_id AND n.entity_id = p_entity_id AND n.deleted_at IS NULL;

    SELECT max(i.interaction_at) AS ultimo,
           count(*) FILTER (WHERE i.negocio_id IS NULL
                              AND i.interaction_at > COALESCE(v_ng.ultimo_em, '-infinity'::timestamptz)) AS por_ligar,
           count(*) AS total
      INTO v_ct
    FROM public.entity_interactions i
    WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id AND i.interaction_type = 'call';

    SELECT min(s.start_datetime) FILTER (
             WHERE s.start_datetime >= now()
               AND s.status NOT IN ('cancelled'::public.schedule_item_status, 'completed'::public.schedule_item_status)) AS proxima,
           max(s.start_datetime) FILTER (WHERE s.status = 'completed'::public.schedule_item_status) AS ultima_feita,
           count(*) FILTER (WHERE s.lead_id IS NOT NULL
                              AND s.status <> 'cancelled'::public.schedule_item_status) AS visitas_lead,
           count(*) FILTER (WHERE s.negocio_id IS NULL
                              AND s.status <> 'cancelled'::public.schedule_item_status
                              AND s.start_datetime > COALESCE(v_ng.ultimo_em, '-infinity'::timestamptz)) AS por_ligar
      INTO v_vs
    FROM (
      SELECT si.start_datetime, si.status, si.lead_id, si.negocio_id
      FROM public.schedule_items si
      WHERE si.lead_id = ANY (v_lds)
        AND si.organization_id = p_organization_id
        AND si.time_off_type IS NULL AND si.vacation_id IS NULL
      UNION ALL
      SELECT si.start_datetime, si.status, si.lead_id, si.negocio_id
      FROM public.schedule_items si
      WHERE v_cli.id IS NOT NULL AND si.client_id = v_cli.id
        AND (si.lead_id IS NULL OR si.lead_id <> ALL (v_lds))
        AND si.organization_id = p_organization_id
        AND si.time_off_type IS NULL AND si.vacation_id IS NULL
    ) s;

    SELECT count(*) INTO v_lv_por
    FROM public.levantamentos lt
    WHERE lt.organization_id = p_organization_id AND lt.entity_id = p_entity_id
      AND lt.negocio_id IS NULL AND lt.deleted_at IS NULL
      AND lt.created_at > COALESCE(v_ng.ultimo_em, '-infinity'::timestamptz);

    v_etapa := CASE
      WHEN v_cli.id IS NOT NULL THEN 'cliente'
      WHEN v_ng.abertos > 0 THEN 'qualificada'
      WHEN v_vs.visitas_lead > 0 THEN 'visitaMarcada'
      WHEN v_ct.ultimo IS NOT NULL THEN 'emContacto'
      ELSE 'nova'
    END;

    v_agreg := jsonb_build_object(
      'ultimo_contacto_em', v_ct.ultimo,
      'ultimo_resultado', (SELECT i.result FROM public.entity_interactions i
                           WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id
                             AND i.interaction_type = 'call'
                           ORDER BY i.interaction_at DESC, i.id DESC LIMIT 1),
      'proximo_contacto_em', public.fn_neg_proximo_contacto(p_organization_id, p_entity_id),
      -- 20261225150000: o contacto EFECTIVO, a regra da Lista (ultimo_resultado):
      -- o mais recente entre a última chamada (acima) e o último contacto
      -- guardado na lead mostrada pela página de Leads (last_contact_at e
      -- last_contact_result); em empate ganha a chamada. É o que a UI deve usar.
      'ultimo_contacto_efetivo_em', GREATEST(v_ct.ultimo, v_lead.last_contact_at),
      'ultimo_resultado_efetivo', CASE
         WHEN v_ct.ultimo IS NULL AND v_lead.last_contact_at IS NULL THEN NULL
         WHEN v_lead.last_contact_at IS NULL OR v_ct.ultimo >= v_lead.last_contact_at THEN
           (SELECT i.result FROM public.entity_interactions i
            WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id
              AND i.interaction_type = 'call'
            ORDER BY i.interaction_at DESC, i.id DESC LIMIT 1)
         ELSE v_lead.last_contact_result::text END,
      'ultima_visita_feita_em', v_vs.ultima_feita,
      'proxima_visita_em', v_vs.proxima,
      'por_ligar', jsonb_build_object('contactos', v_ct.por_ligar, 'visitas', v_vs.por_ligar,
                                      'levantamentos', v_lv_por),
      'negocios', jsonb_build_object('abertos', v_ng.abertos, 'ganhos', v_ng.ganhos,
                                     'perdidos', v_ng.perdidos),
      'total_contactos', v_ct.total,
      'total_visitas', (SELECT count(*)
                        FROM (SELECT si.id FROM public.schedule_items si
                              WHERE si.lead_id = ANY (v_lds) AND si.organization_id = p_organization_id
                              UNION
                              SELECT si.id FROM public.schedule_items si
                              WHERE si.organization_id = p_organization_id
                                AND si.client_id IN (SELECT c.id FROM public.anew_clients c
                                                     WHERE c.organization_id = p_organization_id
                                                       AND c.entity_id = p_entity_id
                                                       AND c.deleted_at IS NULL)) ids
                        JOIN public.schedule_items s ON s.id = ids.id
                        LEFT JOIN public.schedule_boards b ON b.id = s.board_id
                        WHERE s.time_off_type IS NULL AND s.vacation_id IS NULL
                          AND s.status <> 'cancelled'::public.schedule_item_status
                          AND (b.board_type IS NULL OR b.board_type NOT IN ('time_off', 'fleet'))),
      'total_levantamentos', (SELECT count(*) FROM public.levantamentos lt
                              WHERE lt.entity_id = p_entity_id AND lt.organization_id = p_organization_id
                                AND lt.deleted_at IS NULL),
      'total_atividade', (SELECT count(*) FROM public.entity_interactions i
                          WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id));

    -- Pessoa
    SELECT jsonb_build_object(
      'id', p_entity_id,
      'nome', e.display_name,
      -- 20261226100000: o nome em partes (anew_entities), para o ecrã não ter de
      -- partir display_name; NULL quando a entidade não as tem.
      'first_name', e.first_name,
      'last_name', e.last_name,
      'papel', CASE WHEN v_cli.id IS NOT NULL THEN 'cliente' ELSE 'lead' END,
      'lead_id', v_lead.id,
      'client_id', v_cli.id,
      'responsavel_id', COALESCE(v_cli.assigned_to, v_lead.assigned_to),
      'responsavel_nome', (SELECT u.name FROM public.anew_users u
                           WHERE u.id = COALESCE(v_cli.assigned_to, v_lead.assigned_to)),
      'etapa', v_etapa,
      'desde', LEAST((SELECT min(l.created_at) FROM public.anew_leads l
                      WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                        AND l.deleted_at IS NULL),
                     v_cli.created_at),
      'contacto', jsonb_build_object(
        'telefone', (SELECT ph.phone_number FROM public.anew_entity_phones ph
                     WHERE ph.entity_id = p_entity_id
                     ORDER BY ph.is_primary IS TRUE DESC, ph.created_at DESC, ph.id DESC LIMIT 1),
        'email', (SELECT em.email FROM public.anew_entity_emails em
                  WHERE em.entity_id = p_entity_id
                  ORDER BY em.is_primary IS TRUE DESC, em.created_at DESC, em.id DESC LIMIT 1)),
      'morada', (SELECT jsonb_build_object(
                          'rua', NULLIF(btrim(concat_ws(' ', a.street, a.number)), ''),
                          'codigo_postal', a.postal_code, 'localidade', a.city,
                          'andar', a.floor, 'distrito', a.district)
                 FROM public.anew_entity_addresses ea
                 JOIN public.anew_addresses a ON a.id = ea.address_id
                 WHERE ea.entity_id = p_entity_id
                   AND (ea.valid_to IS NULL OR ea.valid_to > now())
                 ORDER BY ea.is_primary IS TRUE DESC, ea.created_at DESC, ea.id DESC
                 LIMIT 1),
      -- As respostas da aba Qualificação do levantamento vivo mais recente que as tenha
      -- (ql, abaixo). 20261226090000: 'qualificacao' fica {pergunta: chave} só com as de
      -- escolha única (hoje são todas); 'qualificacao_respostas' traz as mesmas com o
      -- snapshot (textos, tipo, escolhas, valores), do mesmo levantamento.
      'qualificacao', (SELECT jsonb_object_agg(lr.pergunta, lr.resposta) FILTER (WHERE lr.resposta IS NOT NULL)
                       FROM public.levantamento_respostas lr
                       WHERE lr.seccao = 'qualificacao'
                         AND lr.levantamento_id = ql.id),
      'qualificacao_respostas', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                   'seccao', lr.seccao, 'pergunta', lr.pergunta, 'resposta', lr.resposta,
                                   'tipo', lr.tipo, 'pergunta_texto', lr.pergunta_texto,
                                   'seccao_titulo', lr.seccao_titulo, 'bloco', lr.bloco, 'ordem', lr.ordem,
                                   'escolhas', lr.escolhas, 'escolhas_texto', lr.escolhas_texto,
                                   'valor_texto', lr.valor_texto, 'valor_numero', lr.valor_numero)
                                   ORDER BY lr.ordem NULLS LAST, lr.pergunta), '[]'::jsonb)
                                 FROM public.levantamento_respostas lr
                                 WHERE lr.seccao = 'qualificacao'
                                   AND lr.levantamento_id = ql.id),
      'origem', CASE WHEN v_lead.id IS NULL THEN NULL ELSE jsonb_build_object(
                  'origin', v_lead.origin,
                  'source', v_lead.source,
                  'campanha_id', v_lead.campaign_id,
                  'campanha', (SELECT ca.name FROM public.campaigns ca WHERE ca.id = v_lead.campaign_id),
                  'formulario_id', (SELECT f.id FROM public.campaigns ca
                                    JOIN public.forms f ON f.id = ca.form_id
                                    WHERE ca.id = v_lead.campaign_id),
                  'formulario', (SELECT f.name FROM public.campaigns ca
                                 JOIN public.forms f ON f.id = ca.form_id
                                 WHERE ca.id = v_lead.campaign_id)) END,
      'nif', NULL,
      'empresa', NULL,
      -- 20261225150000: MQL/SQL da lead mostrada (v_lead); as respostas da aba
      -- Qualificação continuam na chave 'qualificacao', acima.
      'qualificacao_tipo', v_lead.qualification_type,
      -- «Voltou a contactar»: a regra da página de Leads, contando também as
      -- chamadas registadas (entity_interactions 'call', onde escreve
      -- neg_registar_contacto).
      'ultima_atividade_em', v_lead.last_activity_at,
      'ultimo_contacto_lead_em', v_lead.last_contact_at,
      'voltou_a_contactar', (v_lead.last_activity_at IS NOT NULL
                             AND (GREATEST(v_lead.last_contact_at, v_ct.ultimo) IS NULL
                                  OR v_lead.last_activity_at > GREATEST(v_lead.last_contact_at, v_ct.ultimo))),
      -- Identidade: tipo da entidade, nome da empresa (organização) e se há
      -- NIF, só em leitura. O NIF nunca sai daqui, nem o id da entidade
      -- fiscal: só se há uma ligação fiscal PRINCIPAL em vigor.
      'tipo', e.type,
      'empresa_nome', CASE WHEN e.type = 'organization' THEN e.display_name END,
      'tem_nif', fe.fid IS NOT NULL)
      INTO v_pessoa
    FROM (SELECT 1) AS um
    LEFT JOIN public.anew_entities e ON e.id = p_entity_id
    LEFT JOIN LATERAL (
      SELECT aef.fiscal_entity_id AS fid
      FROM public.anew_entity_fiscal_entities aef
      WHERE aef.entity_id = p_entity_id AND aef.is_primary IS TRUE
        AND (aef.valid_to IS NULL OR aef.valid_to > now())
      ORDER BY aef.created_at DESC, aef.id DESC
      LIMIT 1
    ) fe ON true
    LEFT JOIN LATERAL (
      SELECT lt.id FROM public.levantamentos lt
      WHERE lt.entity_id = p_entity_id AND lt.organization_id = p_organization_id
        AND lt.deleted_at IS NULL
        AND EXISTS (SELECT 1 FROM public.levantamento_respostas q
                    WHERE q.levantamento_id = lt.id AND q.seccao = 'qualificacao')
      ORDER BY lt.data_levantamento DESC, lt.created_at DESC, lt.id DESC
      LIMIT 1
    ) ql ON true;

    -- Lead e encerramento (a nota 'Abordagem encerrada' mais recente).
    IF v_lead.id IS NOT NULL THEN
      SELECT jsonb_build_object(
        'id', v_lead.id,
        'estado', v_lead.status,
        'aberta', public.fn_neg_lead_aberta(v_lead.status::text) AND v_lead.closure_result IS NULL,
        'encerramento', CASE WHEN v_lead.closure_result IS NULL THEN NULL ELSE jsonb_build_object(
          'resultado', v_lead.closure_result,
          'motivo', nt.result,
          'motivo_outro', CASE WHEN nt.result = 'outro' THEN nt.notes END,
          'em', nt.interaction_at) END)
        INTO v_lead_j
      FROM (SELECT 1) AS um
      LEFT JOIN LATERAL (
        SELECT i.result, i.notes, i.interaction_at
        FROM public.entity_interactions i
        WHERE i.entity_id = p_entity_id AND i.organization_id = p_organization_id
          AND i.interaction_type = 'note' AND i.subject = 'Abordagem encerrada'
        ORDER BY i.interaction_at DESC, i.id DESC
        LIMIT 1
      ) nt ON true;
    END IF;

    v_abertas := (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                           'id', l.id, 'status', l.status, 'created_at', l.created_at,
                           'closure_result', l.closure_result) ORDER BY l.created_at DESC, l.id DESC), '[]'::jsonb)
                  FROM (SELECT l1.* FROM public.anew_leads l1
                        WHERE l1.organization_id = p_organization_id AND l1.entity_id = p_entity_id
                          AND l1.deleted_at IS NULL AND public.fn_neg_lead_aberta(l1.status::text)
                        ORDER BY l1.created_at DESC, l1.id DESC
                        LIMIT 20) l);

    -- 20261226170000: a conversão ao ganhar (uma leitura por chave), para
    -- dizer se um ganho tem a conversão em cliente por fazer.
    v_conv := (SELECT c.conversao_ao_ganhar FROM public.negocio_workflow_config c
               WHERE c.organization_id = p_organization_id);

    v_perm := jsonb_build_object(
      'editar', public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit'),
      'criar',  public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.create'));

    -- 20261226190000: as chaves de âmbito de quem chama, lidas UMA vez (não
    -- por negócio). Editar: a regra de fn_neg_pode_editar e da política
    -- negocios_update (sessão, organização CRM do utilizador, pessoas.edit e
    -- a chave da organização inteira, do comercial ou de quem criou; a
    -- equipa entra pelas chaves de crm_scope_keys). Apagar e restaurar: a
    -- regra de fn_negocios_exigir_permissao_lixo (pessoas.delete com o mesmo
    -- tipo de chave).
    v_uid := auth.uid();
    v_ch_editar := CASE WHEN v_uid IS NOT NULL
                          AND p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid))
                          AND public.has_anew_permission(v_uid, 'pessoas.edit')
                        THEN public.crm_scope_keys('pessoas.edit')
                        ELSE ARRAY[]::text[] END;
    v_ch_apagar := CASE WHEN v_uid IS NOT NULL
                          AND public.has_anew_permission(v_uid, 'pessoas.delete')
                        THEN public.crm_scope_keys('pessoas.delete')
                        ELSE ARRAY[]::text[] END;

    -- Negócios (até 50, recentes primeiro), com documentos e os últimos 30 eventos.
    -- 20261226170000: o fecho v4 (tipo de fecho, alerta em aberto com o texto,
    -- origem da decisão com prova e canal, perda automática, conversão por
    -- fazer) e os eventos com detalhe, origem, canal e prova.
    v_negocios := jsonb_build_object(
      'total', v_ng.total,
      'itens', (SELECT COALESCE(jsonb_agg(x.item ORDER BY x.created_at DESC, x.id DESC), '[]'::jsonb)
                FROM (
                  SELECT n.id, n.created_at,
                    jsonb_build_object(
                      'id', n.id, 'titulo', n.titulo, 'notas', n.notas, 'estado', n.estado,
                      'criado_em', n.created_at, 'ganho_em', n.ganho_em, 'perdido_em', n.perdido_em,
                      'fase_perda', n.fase_perda, 'motivo_perda', n.motivo_perda,
                      'responsavel_id', n.assigned_to,
                      'responsavel_nome', (SELECT u.name FROM public.anew_users u WHERE u.id = n.assigned_to),
                      'valor', public.fn_neg_valor_negocio(n.id),
                      'pronto_a_ganhar', n.estado = 'aberto' AND CASE
                        WHEN v_momento = 'proposta_aceite' THEN EXISTS (
                          SELECT 1 FROM public.proposals pr
                          WHERE pr.negocio_id = n.id AND pr.status = 'accepted'
                            AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE)
                        WHEN v_momento = 'contrato_assinado' THEN EXISTS (
                          SELECT 1 FROM public.client_contracts cc
                          WHERE cc.negocio_id = n.id AND cc.status IN ('signed', 'assinado')
                            AND cc.deleted_at IS NULL)
                        ELSE false END,
                      'parado_desde', CASE WHEN n.estado = 'aberto'
                                           THEN public.fn_neg_parado_desde(n.id) END,
                      'levantamento_id', (SELECT lt.id FROM public.levantamentos lt
                                          WHERE lt.negocio_id = n.id AND lt.deleted_at IS NULL LIMIT 1),
                      'fecho', n.fecho,
                      -- 20261226190000: o que quem chama pode fazer a ESTE negócio.
                      -- pode_editar: a política negocios_update (só a permissão e o
                      -- âmbito; o estado do negócio é à parte, em 'estado').
                      -- pode_apagar e pode_restaurar: o lixo é um UPDATE de deleted_at,
                      -- por isso exige a política de edição E a permissão própria do
                      -- lixo (pessoas.delete com âmbito), que o gatilho verifica.
                      'pode_editar', pm.editar,
                      'pode_apagar', pm.editar AND pm.apagar,
                      'pode_restaurar', pm.editar AND pm.apagar,
                      'alerta_codigo', n.alerta_codigo,
                      'alerta_em', n.alerta_em,
                      -- O texto do alerta em aberto: o detalhe do evento 'alerta' mais
                      -- recente desde que o código ficou (mesma transacção, mesmo instante).
                      'alerta_texto', CASE WHEN n.alerta_codigo IS NOT NULL THEN (
                                        SELECT ea.detalhe FROM public.negocio_eventos ea
                                        WHERE ea.negocio_id = n.id AND ea.tipo = 'alerta'
                                          AND ea.created_at >= n.alerta_em
                                        ORDER BY ea.created_at DESC, ea.id DESC LIMIT 1) END,
                      -- A origem da decisão (nula numa decisão manual): o documento, o
                      -- número dele, o instante do ganho ou da perda, e a prova e o canal
                      -- do evento que a registou.
                      'decisao_origem_tipo', n.decisao_origem_tipo,
                      'decisao_origem_id', n.decisao_origem_id,
                      'decisao_origem_numero', CASE n.decisao_origem_tipo
                        WHEN 'proposta' THEN (SELECT po.proposal_number FROM public.proposals po
                                              WHERE po.id = n.decisao_origem_id)
                        WHEN 'contrato' THEN (SELECT co.contract_number FROM public.client_contracts co
                                              WHERE co.id = n.decisao_origem_id) END,
                      'decisao_origem_em', CASE WHEN n.decisao_origem_id IS NOT NULL THEN
                        CASE n.estado WHEN 'ganho' THEN n.ganho_em WHEN 'perdido' THEN n.perdido_em END END,
                      'decisao_origem_prova', dv.prova,
                      'decisao_origem_canal', dv.canal,
                      'perda_automatica', CASE WHEN n.estado = 'perdido' THEN n.decisao_origem_id IS NOT NULL END,
                      -- Ganho com a conversão em cliente por fazer: a pessoa não é cliente
                      -- desta organização, tem lead aberta e a configuração converte.
                      'conversao_pendente', CASE WHEN n.estado = 'ganho' THEN
                        v_cli.id IS NULL AND COALESCE(v_conv, 'nao_alterar') IS DISTINCT FROM 'nao_alterar'
                        AND jsonb_array_length(v_abertas) > 0 END,
                      'orcamentos', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                       'id', q.id, 'numero', q.quote_number, 'estado', q.estado,
                                       'total', q.total, 'criado_em', q.created_at)
                                       ORDER BY q.created_at DESC, q.id DESC), '[]'::jsonb)
                                     FROM public.quotes q
                                     WHERE q.negocio_id = n.id AND q.deleted_at IS NULL),
                      'propostas', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                      'id', pr.id, 'numero', pr.proposal_number, 'titulo', pr.title,
                                      'status', pr.status, 'valor', pr.value, 'valid_until', pr.valid_until,
                                      'terms', pr.terms, 'enviada_em', pr.sent_at, 'aceite_em', pr.accepted_at,
                                      'criado_em', pr.created_at)
                                      ORDER BY pr.created_at DESC, pr.id DESC), '[]'::jsonb)
                                    FROM public.proposals pr
                                    WHERE pr.negocio_id = n.id AND pr.deleted_at IS NULL
                                      AND pr.is_deleted IS NOT TRUE),
                      'contratos', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                      'id', cc.id, 'numero', cc.contract_number, 'status', cc.status,
                                      'valor', cc.total_value, 'assinado_em', cc.signature_date,
                                      'criado_em', cc.created_at,
                                      'tem_base', cc.quote_id IS NOT NULL OR cc.proposal_id IS NOT NULL)
                                      ORDER BY cc.created_at DESC, cc.id DESC), '[]'::jsonb)
                                    FROM public.client_contracts cc
                                    WHERE cc.negocio_id = n.id AND cc.deleted_at IS NULL),
                      'eventos', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                    'id', ev.id, 'tipo', ev.tipo, 'fase', ev.fase, 'motivo', ev.motivo,
                                    'motivo_reabertura', ev.motivo_reabertura, 'criado_em', ev.created_at,
                                    'criado_por_nome', (SELECT u.name FROM public.anew_users u
                                                        WHERE u.id = ev.created_by),
                                    'detalhe', ev.detalhe, 'origem_tipo', ev.origem_tipo,
                                    'origem_id', ev.origem_id, 'origem_estado', ev.origem_estado,
                                    'canal', ev.canal, 'prova', ev.prova)
                                    ORDER BY ev.created_at DESC, ev.id DESC), '[]'::jsonb)
                                  FROM (SELECT e1.* FROM public.negocio_eventos e1
                                        WHERE e1.negocio_id = n.id
                                        ORDER BY e1.created_at DESC, e1.id DESC
                                        LIMIT 30) ev),
                      -- Há mais de 30 eventos (a ficha mostra os 30 mais recentes).
                      'eventos_tem_mais', EXISTS (SELECT 1 FROM public.negocio_eventos e2
                                                  WHERE e2.negocio_id = n.id
                                                  ORDER BY e2.created_at DESC, e2.id DESC
                                                  OFFSET 30 LIMIT 1)
                    ) AS item
                  FROM (SELECT n1.* FROM public.negocios n1
                        WHERE n1.organization_id = p_organization_id AND n1.entity_id = p_entity_id
                          AND n1.deleted_at IS NULL
                        ORDER BY n1.created_at DESC, n1.id DESC
                        LIMIT 50) n
                  -- 20261226170000: o evento que registou a decisão (índice
                  -- idx_negocio_eventos_origem), para a prova e o canal.
                  LEFT JOIN LATERAL (
                    SELECT ed.prova, ed.canal FROM public.negocio_eventos ed
                    WHERE n.decisao_origem_id IS NOT NULL
                      AND ed.negocio_id = n.id AND ed.origem_id = n.decisao_origem_id
                      AND ed.tipo = CASE n.estado WHEN 'ganho' THEN 'ganhou' WHEN 'perdido' THEN 'perdeu' END
                    ORDER BY ed.created_at DESC, ed.id DESC
                    LIMIT 1
                  ) dv ON true
                  -- 20261226190000: as permissões deste negócio, contra as chaves
                  -- lidas acima (só memória; nenhuma leitura de tabela por negócio).
                  CROSS JOIN LATERAL (
                    SELECT EXISTS (SELECT 1 FROM unnest(v_ch_editar) AS k(chave)
                                   WHERE k.chave = n.organization_id::text || ':*'
                                      OR k.chave = n.organization_id::text || ':' || n.assigned_to::text
                                      OR k.chave = n.organization_id::text || ':' || n.created_by::text) AS editar,
                           EXISTS (SELECT 1 FROM unnest(v_ch_apagar) AS k(chave)
                                   WHERE k.chave = n.organization_id::text || ':*'
                                      OR k.chave = n.organization_id::text || ':' || n.assigned_to::text
                                      OR k.chave = n.organization_id::text || ':' || n.created_by::text) AS apagar
                  ) pm
                ) x));

    -- Documentos da pessoa ainda sem negócio (até 50 de cada).
    v_docs := jsonb_build_object(
      'orcamentos', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                       'id', q.id, 'numero', q.quote_number, 'estado', q.estado,
                       'total', q.total, 'criado_em', q.created_at)
                       ORDER BY q.created_at DESC, q.id DESC), '[]'::jsonb)
                     FROM (SELECT q1.* FROM public.quotes q1
                           WHERE q1.entity_id = p_entity_id AND q1.organization_id = p_organization_id
                             AND q1.deleted_at IS NULL AND q1.negocio_id IS NULL
                           ORDER BY q1.created_at DESC, q1.id DESC LIMIT 50) q),
      'propostas', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                      'id', pr.id, 'numero', pr.proposal_number, 'titulo', pr.title,
                      'status', pr.status, 'valor', pr.value, 'valid_until', pr.valid_until,
                      'terms', pr.terms, 'enviada_em', pr.sent_at, 'aceite_em', pr.accepted_at,
                      'criado_em', pr.created_at)
                      ORDER BY pr.created_at DESC, pr.id DESC), '[]'::jsonb)
                    FROM (SELECT p1.* FROM public.proposals p1
                          WHERE p1.entity_id = p_entity_id AND p1.organization_id = p_organization_id
                            AND p1.deleted_at IS NULL AND p1.is_deleted IS NOT TRUE AND p1.negocio_id IS NULL
                          ORDER BY p1.created_at DESC, p1.id DESC LIMIT 50) pr),
      'contratos', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                      'id', cc.id, 'numero', cc.contract_number, 'status', cc.status,
                      'valor', cc.total_value, 'assinado_em', cc.signature_date,
                      'criado_em', cc.created_at,
                      'tem_base', cc.quote_id IS NOT NULL OR cc.proposal_id IS NOT NULL)
                      ORDER BY cc.created_at DESC, cc.id DESC), '[]'::jsonb)
                    FROM (SELECT c1.* FROM public.client_contracts c1
                          WHERE c1.entity_id = p_entity_id AND c1.organization_id = p_organization_id
                            AND c1.deleted_at IS NULL AND c1.negocio_id IS NULL
                          ORDER BY c1.created_at DESC, c1.id DESC LIMIT 50) cc));
  END IF;

  v_res := jsonb_build_object(
    'pessoa', v_pessoa,
    'lead', v_lead_j,
    'leads_abertas', v_abertas,
    'agregados', v_agreg,
    'permissoes', v_perm,
    'negocios', v_negocios,
    'documentos_por_ligar', v_docs,
    'contactos', CASE WHEN p_partes IS NULL OR 'contactos' = ANY (p_partes) THEN
                   public.fn_neg_ficha_seccao(p_organization_id, p_entity_id, 'contactos', p_limite,
                                              p_depois -> 'contactos') END,
    'visitas', CASE WHEN p_partes IS NULL OR 'visitas' = ANY (p_partes) THEN
                 public.fn_neg_ficha_seccao(p_organization_id, p_entity_id, 'visitas', p_limite,
                                            p_depois -> 'visitas') END,
    'levantamentos', CASE WHEN p_partes IS NULL OR 'levantamentos' = ANY (p_partes) THEN
                       public.fn_neg_ficha_seccao(p_organization_id, p_entity_id, 'levantamentos', p_limite,
                                                  p_depois -> 'levantamentos') END,
    'atividade', CASE WHEN p_partes IS NULL OR 'atividade' = ANY (p_partes) THEN
                   public.fn_neg_ficha_seccao(p_organization_id, p_entity_id, 'atividade', p_limite,
                                              p_depois -> 'atividade') END);

  -- Repõe a marca: as guardas só ficam dispensadas durante esta chamada.
  PERFORM set_config('app.neg_ficha_verificada', '', true);
  RETURN v_res;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_ficha_pessoa(p_organization_id uuid, p_entity_id uuid, p_limite integer, p_depois jsonb, p_partes text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_ficha_pessoa(p_organization_id uuid, p_entity_id uuid, p_limite integer, p_depois jsonb, p_partes text[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_ganhar_negocio(p_negocio_id uuid, p_lead_id uuid DEFAULT NULL::uuid, p_client_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg        public.negocios;
  v_mudou      boolean := false;
  v_lead       public.anew_leads;
  v_client_id  uuid;
  v_client_org uuid;
  v_conversao  text;
  v_outras     int;
BEGIN
  IF p_client_data IS NOT NULL AND jsonb_typeof(p_client_data) <> 'object' THEN
    RAISE EXCEPTION 'Valor inválido: dados do cliente.' USING ERRCODE = 'NG009';
  END IF;

  -- 1. Negócio editável e JÁ ganho (o ganho vem dos documentos; aberto ou
  --    perdido: NG002). Fase N: deixa de dar o ganho e de ler o momento do ganho.
  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['ganho']);

  -- 2. Conversão de UMA lead aberta, serializada por pessoa.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'neg_pessoa:' || v_neg.organization_id::text || ':' || v_neg.entity_id::text, 0));

  SELECT * INTO v_lead FROM public.fn_neg_escolher_lead(
    v_neg.organization_id, v_neg.entity_id, p_lead_id, 'aberta');

  IF v_lead.id IS NOT NULL
     AND (v_lead.status = 'converted' OR v_lead.converted_to_client_id IS NOT NULL) THEN
    -- Lead indicada já convertida: não se chama o rpc.
    v_conversao := 'ja_convertida';
    v_client_id := v_lead.converted_to_client_id;

  ELSIF v_lead.id IS NOT NULL AND public.fn_neg_lead_aberta(v_lead.status::text) THEN
    -- D5: leads.convert com âmbito sobre esta lead (como as políticas).
    IF NOT (public.has_anew_permission(auth.uid(), 'leads.convert')
            AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('leads.convert')) AS k(scope_key)
                        WHERE k.scope_key = v_lead.organization_id::text || ':*'
                           OR k.scope_key = v_lead.organization_id::text || ':' || v_lead.assigned_to::text
                           OR k.scope_key = v_lead.organization_id::text || ':' || v_lead.created_by::text)) THEN
      RAISE EXCEPTION 'Sem permissão para converter a lead.' USING ERRCODE = 'NG007';
    END IF;

    SELECT c.id, c.organization_id INTO v_client_id, v_client_org
    FROM public.rpc_convert_lead_to_client(
      v_lead.id, COALESCE(p_client_data, '{}'::jsonb), NULL::uuid, NULL::uuid, NULL::uuid) AS c;
    IF v_client_org IS DISTINCT FROM v_neg.organization_id THEN
      RAISE EXCEPTION 'A conversão desta lead não é possível nesta organização.' USING ERRCODE = 'NG012';
    END IF;
    v_conversao := 'feita';
    v_mudou := true;

  ELSE
    -- Sem lead aberta, ou a indicada está fechada (rejeitada, perdida,
    -- cancelada): não converte; só se a pessoa já for cliente desta organização.
    SELECT c.id INTO v_client_id
    FROM public.anew_clients c
    WHERE c.organization_id = v_neg.organization_id AND c.entity_id = v_neg.entity_id
      AND c.deleted_at IS NULL
    ORDER BY c.created_at ASC
    LIMIT 1;
    IF v_client_id IS NOT NULL THEN
      v_conversao := 'ja_cliente';
    ELSE
      SELECT l.* INTO v_lead
      FROM public.anew_leads l
      WHERE l.organization_id = v_neg.organization_id AND l.entity_id = v_neg.entity_id
        AND l.deleted_at IS NULL AND l.converted_to_client_id IS NOT NULL
      ORDER BY l.converted_at DESC NULLS LAST, l.created_at DESC
      LIMIT 1;
      IF v_lead.id IS NULL THEN
        RAISE EXCEPTION 'A pessoa não tem lead aberta para converter.' USING ERRCODE = 'NG015';
      END IF;
      v_conversao := 'ja_convertida';
      v_client_id := v_lead.converted_to_client_id;
    END IF;
  END IF;

  -- Cliente já existente tem de ser desta organização (lido sob RLS).
  IF v_conversao = 'ja_convertida' THEN
    SELECT c.organization_id INTO v_client_org
    FROM public.anew_clients c
    WHERE c.id = v_client_id;
    IF v_client_org IS DISTINCT FROM v_neg.organization_id THEN
      RAISE EXCEPTION 'A conversão desta lead não é possível nesta organização.' USING ERRCODE = 'NG012';
    END IF;
  END IF;

  SELECT count(*)::int INTO v_outras
  FROM public.anew_leads l
  WHERE l.organization_id = v_neg.organization_id AND l.entity_id = v_neg.entity_id
    AND l.deleted_at IS NULL
    AND l.id IS DISTINCT FROM v_lead.id
    AND public.fn_neg_lead_aberta(l.status::text);

  -- 3. A conversão que falhou deixa de estar em alerta.
  IF v_neg.alerta_codigo = 'conversao_falhou' THEN
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.negocios n SET alerta_codigo = NULL
    WHERE n.id = v_neg.id AND n.alerta_codigo = 'conversao_falhou';
    PERFORM set_config('app.neg_via_funcao', 'off', true);
  END IF;

  -- 4. O rpc de conversão deixa a auditoria genérica desligada até ao fim da transacção.
  PERFORM set_config('app.audit_bypass', 'off', true);

  RETURN jsonb_build_object('mudou', v_mudou, 'estado', 'ganho', 'conversao', v_conversao,
                            'lead_id', v_lead.id, 'client_id', v_client_id,
                            'outras_leads_abertas', v_outras);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_ganhar_negocio(p_negocio_id uuid, p_lead_id uuid, p_client_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_ganhar_negocio(p_negocio_id uuid, p_lead_id uuid, p_client_data jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_ganhar_negocio(p_negocio_id uuid, p_lead_id uuid, p_client_data jsonb) TO service_role;
COMMENT ON FUNCTION public.neg_ganhar_negocio(p_negocio_id uuid, p_lead_id uuid, p_client_data jsonb) IS 'Pessoas: «Converter em cliente» num negócio JÁ ganho (o ganho vem dos documentos). Aberto ou perdido: NG002. Limpa o alerta conversao_falhou. 20261226140000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_cadeia(p_orcamento_cria_proposta boolean, p_proposta_cria_contrato boolean, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_orgs      uuid[];
  v_keys      text[];
  v_org       uuid;
  v_fase_orc  uuid;
  v_fase_pr   uuid;
  v_n         integer;
  v_actor     uuid;
  v_orc_antes boolean;
  v_pr_antes  boolean;
  v_cc_nada   boolean;
  v_tem_org   boolean;
  v_mudou     boolean := false;
BEGIN
  -- 1. Valores
  IF p_orcamento_cria_proposta IS NULL OR p_proposta_cria_contrato IS NULL THEN
    RAISE EXCEPTION 'Cadeia de documentos inválida.' USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organizações elegíveis do utilizador: as organizações CRM activas
  --    dele com a página Pessoas (configuração) e pessoas.view.
  IF NOT public.has_anew_permission(v_uid, 'pessoas.view') THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  v_keys := public.crm_scope_keys('pessoas.view');
  SELECT array_agg(DISTINCT c.organization_id) INTO v_orgs
  FROM public.negocio_workflow_config c
  WHERE c.organization_id IN (SELECT public.get_user_crm_org_ids(v_uid))
    AND EXISTS (SELECT 1 FROM unnest(v_keys) AS k(scope_key)
                WHERE starts_with(k.scope_key, c.organization_id::text || ':'));
  IF v_orgs IS NULL THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  -- 4. Permissão própria do Workflow de Pessoas, nessa organização.
  IF NOT public.has_anew_permission(v_uid, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_keys := public.crm_scope_keys('pessoas.config');
  SELECT array_agg(o.id) INTO v_orgs
  FROM unnest(v_orgs) AS o(id)
  WHERE EXISTS (SELECT 1 FROM unnest(v_keys) AS k(scope_key)
                WHERE starts_with(k.scope_key, o.id::text || ':'));
  IF v_orgs IS NULL THEN
    RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- O parâmetro só escolhe entre as elegíveis; nunca alarga a lista.
  IF p_organization_id IS NOT NULL THEN
    IF NOT (p_organization_id = ANY (v_orgs)) THEN
      RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    v_org := p_organization_id;
  ELSIF cardinality(v_orgs) > 1 THEN
    RAISE EXCEPTION 'Pertence a mais do que uma organização com a página Pessoas: não se sabe qual configurar.'
      USING ERRCODE = 'NG026';
  ELSE
    v_org := v_orgs[1];
  END IF;

  -- 5. Em exclusivo por organização até ao fim da transacção.
  PERFORM pg_advisory_xact_lock(hashtextextended('neg_guardar_cadeia:' || v_org::text, 0));

  -- 6. Fases globais (as que o motor usa).
  SELECT (array_agg(s.id))[1], count(*) INTO v_fase_orc, v_n
  FROM public.quote_workflow_stages s
  WHERE s.organization_id IS NULL AND s.name = 'aceite';
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'A fase aceite dos orçamentos não é única.' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT (array_agg(s.id))[1], count(*) INTO v_fase_pr, v_n
  FROM public.proposal_workflow_stages s
  WHERE s.organization_id IS NULL AND s.name::text = 'accepted';
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'A fase aceite das propostas não é única.' USING ERRCODE = 'no_data_found';
  END IF;

  -- 7. Antes: o valor EFECTIVO, como o motor execute-workflow o lê.
  --    Orçamentos: linhas activas da organização nessa fase (não há globais:
  --    organization_id é NOT NULL).
  v_orc_antes := EXISTS (SELECT 1 FROM public.quote_stage_actions a
                         WHERE a.organization_id = v_org AND a.stage_id = v_fase_orc
                           AND a.action_type = 'create_proposal' AND a.is_active IS TRUE);
  --    Propostas: com alguma linha da organização (qualquer fase), só essas;
  --    senão as globais.
  v_tem_org := EXISTS (SELECT 1 FROM public.proposal_stage_actions a WHERE a.organization_id = v_org);
  v_pr_antes := EXISTS (SELECT 1 FROM public.proposal_stage_actions a
                        WHERE a.organization_id IS NOT DISTINCT FROM CASE WHEN v_tem_org THEN v_org END
                          AND a.stage_id = v_fase_pr
                          AND a.action_type = 'create_contract' AND a.is_active IS TRUE);
  --    Contratos (só leitura): linhas activas da organização em signed ou
  --    assinado; sem nenhuma, as globais. Nada criado = nenhuma acção que crie
  --    um documento (pedido, orçamento, proposta, contrato).
  v_tem_org := EXISTS (SELECT 1 FROM public.contract_stage_actions a
                       WHERE a.organization_id = v_org AND a.stage_id IN ('signed', 'assinado')
                         AND a.is_active IS TRUE);
  v_cc_nada := NOT EXISTS (SELECT 1 FROM public.contract_stage_actions a
                           WHERE a.organization_id IS NOT DISTINCT FROM CASE WHEN v_tem_org THEN v_org END
                             AND a.stage_id IN ('signed', 'assinado') AND a.is_active IS TRUE
                             AND a.action_type IN ('create_deal', 'create_quote', 'create_proposal',
                                                   'create_contract'));

  -- 8. Escrita, só nas linhas da organização validada acima. Nunca DELETE.
  v_actor := public.fn_neg_actor();

  UPDATE public.quote_stage_actions a
  SET is_active = p_orcamento_cria_proposta, updated_at = now()
  WHERE a.organization_id = v_org AND a.stage_id = v_fase_orc
    AND a.action_type = 'create_proposal'
    AND a.is_active IS DISTINCT FROM p_orcamento_cria_proposta;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_mudou := v_mudou OR v_n > 0;
  IF NOT EXISTS (SELECT 1 FROM public.quote_stage_actions a
                 WHERE a.organization_id = v_org AND a.stage_id = v_fase_orc
                   AND a.action_type = 'create_proposal')
     AND v_orc_antes IS DISTINCT FROM p_orcamento_cria_proposta THEN
    INSERT INTO public.quote_stage_actions
      (organization_id, stage_id, action_type, action_config, is_active, execution_order, created_by)
    VALUES (v_org, v_fase_orc, 'create_proposal', '{}'::jsonb, p_orcamento_cria_proposta, 0, v_actor);
    v_mudou := true;
  END IF;

  UPDATE public.proposal_stage_actions a
  SET is_active = p_proposta_cria_contrato
  WHERE a.organization_id = v_org AND a.stage_id = v_fase_pr
    AND a.action_type = 'create_contract'
    AND a.is_active IS DISTINCT FROM p_proposta_cria_contrato;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_mudou := v_mudou OR v_n > 0;
  IF NOT EXISTS (SELECT 1 FROM public.proposal_stage_actions a
                 WHERE a.organization_id = v_org AND a.stage_id = v_fase_pr
                   AND a.action_type = 'create_contract')
     AND v_pr_antes IS DISTINCT FROM p_proposta_cria_contrato THEN
    INSERT INTO public.proposal_stage_actions
      (organization_id, stage_id, action_type, action_config, is_active, execution_order, created_by)
    VALUES (v_org, v_fase_pr, 'create_contract', '{}'::jsonb, p_proposta_cria_contrato, 0, v_actor);
    v_mudou := true;
  END IF;

  RETURN jsonb_build_object(
    'organizacao', v_org,
    'antes',  jsonb_build_object('orcamento_cria_proposta', v_orc_antes,
                                 'proposta_cria_contrato', v_pr_antes,
                                 'contrato_assinado_cria_nada', v_cc_nada),
    'depois', jsonb_build_object('orcamento_cria_proposta', p_orcamento_cria_proposta,
                                 'proposta_cria_contrato', p_proposta_cria_contrato,
                                 'contrato_assinado_cria_nada', v_cc_nada),
    'mudou',  v_mudou);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_cadeia(p_orcamento_cria_proposta boolean, p_proposta_cria_contrato boolean, p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_cadeia(p_orcamento_cria_proposta boolean, p_proposta_cria_contrato boolean, p_organization_id uuid) TO authenticated;
COMMENT ON FUNCTION public.neg_guardar_cadeia(p_orcamento_cria_proposta boolean, p_proposta_cria_contrato boolean, p_organization_id uuid) IS 'Pessoas: grava a cadeia de documentos de uma organização elegível de quem chama (p_organization_id só escolhe entre as elegíveis; nulo = a única): orçamento aceite cria a proposta (quote_stage_actions, fase global aceite, create_proposal) e proposta aceite cria o contrato (proposal_stage_actions, fase global accepted, create_contract). UPSERT de is_active, nunca apaga; contract_stage_actions só é lida. NG008, NG009, NG026, 42501. 20261226210000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_config_negocios(p_organization_id uuid, p_conversao_ao_ganhar text, p_recusa_proposta text, p_recusa_contrato text, p_cancelamento_no_prazo text, p_reflexao_dias integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_keys_pes text[];
  v_antes    public.negocio_workflow_config;
  v_depois   jsonb;
  v_antes_j  jsonb;
  v_conv     boolean;
  v_aviso    boolean;
BEGIN
  -- 1. Valores
  IF p_organization_id IS NULL
     OR p_conversao_ao_ganhar IS NULL OR p_conversao_ao_ganhar NOT IN ('nao_alterar', 'automatica', 'manual')
     OR p_recusa_proposta IS NULL OR p_recusa_proposta NOT IN ('perder', 'manter_aberto')
     OR p_recusa_contrato IS NULL OR p_recusa_contrato NOT IN ('perder', 'manter_aberto')
     OR p_cancelamento_no_prazo IS NULL OR p_cancelamento_no_prazo NOT IN ('perder', 'manter_ganho')
     OR (p_reflexao_dias IS NOT NULL AND (p_reflexao_dias < 1 OR p_reflexao_dias > 365)) THEN
    RAISE EXCEPTION 'Configuração de negócios inválida.' USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view e com configuração.
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 4. Permissão própria do Workflow de Pessoas, nesta organização.
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5. Linha da organização, em exclusivo até ao fim da transacção.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('neg_guardar_config_negocios:' || p_organization_id::text, 0));

  SELECT c.* INTO v_antes
  FROM public.negocio_workflow_config c
  WHERE c.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  v_antes_j := jsonb_build_object(
    'conversao_ao_ganhar', v_antes.conversao_ao_ganhar,
    'recusa_proposta', v_antes.recusa_proposta,
    'recusa_contrato', v_antes.recusa_contrato,
    'cancelamento_no_prazo', v_antes.cancelamento_no_prazo,
    'reflexao_dias', v_antes.reflexao_dias);
  v_depois := jsonb_build_object(
    'conversao_ao_ganhar', p_conversao_ao_ganhar,
    'recusa_proposta', p_recusa_proposta,
    'recusa_contrato', p_recusa_contrato,
    'cancelamento_no_prazo', p_cancelamento_no_prazo,
    'reflexao_dias', p_reflexao_dias);

  -- Aviso: Contratos converte ao assinar e aqui a conversão não é automática.
  IF EXISTS (SELECT 1 FROM public.contract_stage_actions a
             WHERE a.organization_id = p_organization_id
               AND a.stage_id IN ('signed', 'assinado') AND a.is_active = true) THEN
    v_conv := EXISTS (SELECT 1 FROM public.contract_stage_actions a
                      WHERE a.organization_id = p_organization_id
                        AND a.stage_id IN ('signed', 'assinado') AND a.is_active = true
                        AND a.action_type = 'convert_to_client');
  ELSE
    v_conv := EXISTS (SELECT 1 FROM public.contract_stage_actions a
                      WHERE a.organization_id IS NULL
                        AND a.stage_id IN ('signed', 'assinado') AND a.is_active = true
                        AND a.action_type = 'convert_to_client');
  END IF;
  v_aviso := v_conv AND p_conversao_ao_ganhar IN ('manual', 'nao_alterar');

  IF v_antes_j = v_depois THEN
    RETURN jsonb_build_object('antes', v_antes_j, 'depois', v_antes_j, 'mudou', false,
                              'aviso_conversao_contratos', v_aviso);
  END IF;

  -- 6. Escrita, só na linha da organização validada acima (nunca INSERT).
  UPDATE public.negocio_workflow_config c
  SET conversao_ao_ganhar   = p_conversao_ao_ganhar,
      recusa_proposta       = p_recusa_proposta,
      recusa_contrato       = p_recusa_contrato,
      cancelamento_no_prazo = p_cancelamento_no_prazo,
      reflexao_dias         = p_reflexao_dias
  WHERE c.organization_id = p_organization_id;

  RETURN jsonb_build_object('antes', v_antes_j, 'depois', v_depois, 'mudou', true,
                            'aviso_conversao_contratos', v_aviso);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_config_negocios(p_organization_id uuid, p_conversao_ao_ganhar text, p_recusa_proposta text, p_recusa_contrato text, p_cancelamento_no_prazo text, p_reflexao_dias integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_config_negocios(p_organization_id uuid, p_conversao_ao_ganhar text, p_recusa_proposta text, p_recusa_contrato text, p_cancelamento_no_prazo text, p_reflexao_dias integer) TO authenticated;
COMMENT ON FUNCTION public.neg_guardar_config_negocios(p_organization_id uuid, p_conversao_ao_ganhar text, p_recusa_proposta text, p_recusa_contrato text, p_cancelamento_no_prazo text, p_reflexao_dias integer) IS 'Pessoas, Workflow, Negócios: grava a configuração do fecho da organização (conversão ao ganhar, recusa da proposta e do contrato, cancelamento no prazo, prazo de reflexão) e devolve {antes, depois, mudou, aviso_conversao_contratos}. Só UPDATE da linha existente. NG009 valores; 42501 sem sessão ou sem pessoas.config; NG008 sem Pessoas. 20261226120000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_identidade_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text DEFAULT NULL::text, p_nome_empresa text DEFAULT NULL::text, p_nome_proprio text DEFAULT NULL::text, p_apelido text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid        uuid := auth.uid();
  v_nome       text := NULLIF(btrim(p_nome_empresa), '');
  v_keys_pes   text[];
  v_keys_lead  text[];
  v_keys_cli   text[];
  v_ent        public.anew_entities;
  v_tipo       text;
  v_mudou      boolean := false;
  -- como .trim().replace(/\s+/g, " ") do ecrã: primeiro junta todo o espaço
  -- (tabulações, quebras de linha e o espaço inseparável U+00A0, que o \s do
  -- Postgres também apanha), depois apara.
  v_f          text := NULLIF(btrim(regexp_replace(p_nome_proprio, '\s+', ' ', 'g')), '');
  v_l          text := NULLIF(btrim(regexp_replace(p_apelido, '\s+', ' ', 'g')), '');
  v_disp       text;
  v_first      text;
  v_last       text;
BEGIN
  -- 1. Valores
  IF p_organization_id IS NULL OR p_entity_id IS NULL
     OR (p_tipo IS NOT NULL AND p_tipo NOT IN ('person', 'organization'))
     OR char_length(v_nome) > 200
     OR v_nome ~ '[[:cntrl:]]'
     OR char_length(v_f) > 100 OR char_length(v_l) > 100
     OR v_f ~ '[[:cntrl:]]' OR v_l ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Valor inválido: organização, pessoa, tipo, nome da empresa (até 200 caracteres) ou nome e apelido (até 100).'
      USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view e com configuração (D1).
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 4. Pessoa ligada, com lead ou cliente vivo, visível no âmbito de leitura,
  --    e que não é a ficha de uma organização do sistema.
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);
  v_keys_lead := CASE WHEN public.has_anew_permission(v_uid, 'leads.view')
                      THEN public.crm_scope_keys('leads.view') ELSE ARRAY[]::text[] END;
  v_keys_cli  := CASE WHEN public.has_anew_permission(v_uid, 'clients.view')
                      THEN public.crm_scope_keys('clients.view') ELSE ARRAY[]::text[] END;
  IF NOT (EXISTS (SELECT 1 FROM public.anew_leads l
                  WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                    AND l.deleted_at IS NULL
                    AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
                         OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
                         OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead)))
          OR EXISTS (SELECT 1 FROM public.anew_clients c
                     WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                       AND c.deleted_at IS NULL
                       AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
                            OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
                            OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli))))
     OR EXISTS (SELECT 1 FROM public.anew_organizations o WHERE o.entity_id = p_entity_id) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 5. Editar: pessoas.edit na organização e âmbito de edição sobre a lead ou o cliente.
  v_keys_lead := CASE WHEN public.has_anew_permission(v_uid, 'leads.edit')
                      THEN public.crm_scope_keys('leads.edit') ELSE ARRAY[]::text[] END;
  v_keys_cli  := CASE WHEN public.has_anew_permission(v_uid, 'clients.edit')
                      THEN public.crm_scope_keys('clients.edit') ELSE ARRAY[]::text[] END;
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit')
     OR NOT (EXISTS (SELECT 1 FROM public.anew_leads l
                     WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                       AND l.deleted_at IS NULL
                       AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
                            OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
                            OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead)))
             OR EXISTS (SELECT 1 FROM public.anew_clients c
                        WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                          AND c.deleted_at IS NULL
                          AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
                               OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
                               OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli)))) THEN
    RAISE EXCEPTION 'Sem permissão para editar esta pessoa.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5b. Não muda o tipo nem o nome de uma entidade que aparece noutra organização
  --     (ligação, lead viva, cliente vivo, papel vivo, ou linha viva de uma tabela
  --     com chave estrangeira para anew_entities; ver PARTILHADA).
  IF EXISTS (SELECT 1 FROM public.anew_entity_org_links lk
             WHERE lk.entity_id = p_entity_id AND lk.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.anew_leads l
                WHERE l.entity_id = p_entity_id AND l.organization_id <> p_organization_id
                  AND l.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_clients c
                WHERE c.entity_id = p_entity_id AND c.organization_id <> p_organization_id
                  AND c.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_entity_roles er
                WHERE er.entity_id = p_entity_id AND er.organization_id <> p_organization_id
                  AND er.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_contacts t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.client_contracts t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.client_portal_users t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.contact_tags t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.data_erasure_requests t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.deals t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.direct_sales t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.entity_interactions t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.form_submissions t
                WHERE (t.entity_id = p_entity_id OR t.conflicting_entity_id = p_entity_id)
                  AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.levantamentos t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.negocios t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.organization_counted_entities t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.proposals t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.quotes t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     -- a ficha de um utilizador do sistema não é uma pessoa da página
     OR EXISTS (SELECT 1 FROM public.anew_users u
                WHERE u.entity_id = p_entity_id AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 6. Bloqueio: uma alteração de cada vez por pessoa.
  SELECT e.* INTO v_ent FROM public.anew_entities e WHERE e.id = p_entity_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 7. Tipo e nome (só escreve se alguma coisa muda).
  v_tipo := COALESCE(p_tipo, v_ent.type);
  IF v_tipo = 'organization' THEN
    -- Empresa: o nome visível é o da empresa; nome próprio e apelido a NULL.
    IF v_f IS NOT NULL OR v_l IS NOT NULL
       OR (v_ent.type IS DISTINCT FROM 'organization' AND v_nome IS NULL) THEN
      RAISE EXCEPTION 'Valor inválido: uma empresa tem só o nome da empresa (obrigatório ao mudar para empresa).'
        USING ERRCODE = 'NG009';
    END IF;
    v_disp  := COALESCE(v_nome, v_ent.display_name);
    v_first := NULL;
    v_last  := NULL;
  ELSE
    -- Pessoa: nome próprio e apelido (os dois, ou nenhum se já era pessoa).
    IF v_nome IS NOT NULL
       OR ((v_f IS NULL) <> (v_l IS NULL))
       OR (v_ent.type IS DISTINCT FROM 'person' AND (v_f IS NULL OR v_l IS NULL)) THEN
      RAISE EXCEPTION 'Valor inválido: uma pessoa tem nome próprio e apelido (obrigatórios ao mudar para pessoa).'
        USING ERRCODE = 'NG009';
    END IF;
    IF v_f IS NULL THEN
      v_disp  := v_ent.display_name;
      v_first := v_ent.first_name;
      v_last  := v_ent.last_name;
    ELSE
      -- normalizeFirstLast (src/utils/composeDisplayName.ts:19-30)
      IF lower(v_f) = lower(v_l) AND position(' ' IN v_f) > 0 THEN
        v_first := split_part(v_f, ' ', 1);
        v_last  := substr(v_f, position(' ' IN v_f) + 1);
      ELSE
        v_first := v_f;
        v_last  := v_l;
      END IF;
      -- composeDisplayName (src/utils/composeDisplayName.ts:8-17)
      v_disp := CASE
        WHEN v_first IS NULL THEN COALESCE(v_last, '')
        WHEN v_last IS NULL THEN v_first
        WHEN lower(v_first) = lower(v_last) THEN v_first
        WHEN starts_with(lower(v_last), lower(v_first) || ' ') THEN v_last
        WHEN right(lower(v_first), char_length(v_last) + 1) = ' ' || lower(v_last) THEN v_first
        ELSE v_first || ' ' || v_last
      END;
    END IF;
  END IF;
  IF v_tipo IS DISTINCT FROM v_ent.type
     OR v_disp IS DISTINCT FROM v_ent.display_name
     OR v_first IS DISTINCT FROM v_ent.first_name
     OR v_last IS DISTINCT FROM v_ent.last_name THEN
    UPDATE public.anew_entities e
    SET type         = v_tipo,
        display_name = v_disp,
        first_name   = v_first,
        last_name    = v_last,
        updated_at   = now()
    WHERE e.id = p_entity_id;
    v_mudou := true;
  END IF;

  RETURN jsonb_build_object(
    'tipo', v_tipo,
    'nome', v_disp,
    'empresa_nome', CASE WHEN v_tipo = 'organization' THEN v_disp END,
    'mudou', v_mudou);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_identidade_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_nome_empresa text, p_nome_proprio text, p_apelido text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_identidade_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_nome_empresa text, p_nome_proprio text, p_apelido text) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_guardar_levantamento(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_dados jsonb, p_linhas jsonb, p_respostas jsonb, p_negocio_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg       public.negocios;
  v_lev       public.levantamentos;
  v_dados     jsonb := COALESCE(p_dados, '{}'::jsonb);
  v_linhas    jsonb := COALESCE(p_linhas, '[]'::jsonb);
  v_respostas jsonb := COALESCE(p_respostas, '{}'::jsonb);
  v_data      date;
  v_visita    uuid;
  v_feito_por uuid;
  v_criado    boolean;
  v_ligado    uuid;
  v_n         int;
  -- 20261226090000: questionário configurável.
  v_norm      jsonb;
  v_versao    integer;
  v_versao_cl integer;
  v_res       jsonb;
  v_erro      text;
BEGIN
  IF p_id IS NULL
     OR jsonb_typeof(v_dados) <> 'object'
     OR jsonb_typeof(v_linhas) <> 'array'
     OR jsonb_typeof(v_respostas) <> 'object' THEN
    RAISE EXCEPTION 'Valor inválido: identificador, dados, linhas ou respostas.' USING ERRCODE = 'NG009';
  END IF;
  IF jsonb_array_length(v_linhas) > 200
     OR (SELECT count(*) FROM jsonb_object_keys(v_respostas)) > 200 THEN
    RAISE EXCEPTION 'Valor inválido: até 200 linhas e 200 respostas.' USING ERRCODE = 'NG009';
  END IF;
  BEGIN
    v_data      := (v_dados ->> 'data_levantamento')::date;
    v_visita    := (v_dados ->> 'visita_id')::uuid;
    v_feito_por := (v_dados ->> 'feito_por')::uuid;
    v_versao_cl := (v_dados ->> 'versao_questionario')::integer;
  EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow
              OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'Valor inválido: data, visita, autor ou versão do questionário.' USING ERRCODE = 'NG009';
  END;
  IF v_data IS NULL THEN
    RAISE EXCEPTION 'Valor inválido: falta a data do levantamento.' USING ERRCODE = 'NG009';
  END IF;

  -- 20261226090000: cada resposta é {"escolhas": [chaves]}, {"texto": "..."} ou
  -- {"numero": n}. A forma antiga da Fase V, {"seccao": "...", "resposta": "chave"},
  -- vale como {"escolhas": [chave]}; a secção enviada é ignorada (vem da
  -- configuração da organização).
  v_erro := (SELECT r.pergunta
             FROM jsonb_each(v_respostas) AS r(pergunta, valor)
             WHERE CASE
               WHEN r.pergunta !~ '^[a-z][A-Za-z0-9]{0,39}$' THEN true
               WHEN jsonb_typeof(r.valor) <> 'object' THEN true
               WHEN EXISTS (SELECT 1 FROM jsonb_object_keys(r.valor) AS k(chave)
                            WHERE k.chave NOT IN ('escolhas', 'texto', 'numero', 'resposta', 'seccao')) THEN true
               WHEN (r.valor ? 'escolhas')::integer + (r.valor ? 'texto')::integer
                    + (r.valor ? 'numero')::integer + (r.valor ? 'resposta')::integer <> 1 THEN true
               WHEN r.valor ? 'seccao' AND NOT (r.valor ? 'resposta') THEN true
               WHEN r.valor ? 'escolhas' THEN
                 CASE WHEN jsonb_typeof(r.valor -> 'escolhas') <> 'array' THEN true
                      WHEN jsonb_array_length(r.valor -> 'escolhas') NOT BETWEEN 1 AND 30 THEN true
                      ELSE EXISTS (SELECT 1 FROM jsonb_array_elements(r.valor -> 'escolhas') AS x(v)
                                   WHERE jsonb_typeof(x.v) <> 'string')
                 END
               WHEN r.valor ? 'texto' THEN jsonb_typeof(r.valor -> 'texto') <> 'string'
               WHEN r.valor ? 'numero' THEN jsonb_typeof(r.valor -> 'numero') <> 'number'
               ELSE jsonb_typeof(r.valor -> 'resposta') <> 'string'
                    OR COALESCE(jsonb_typeof(r.valor -> 'seccao'), 'null') NOT IN ('string', 'null')
             END
             ORDER BY r.pergunta
             LIMIT 1);
  IF v_erro IS NOT NULL THEN
    RAISE EXCEPTION 'Valor inválido: resposta à pergunta %.', left(v_erro, 40) USING ERRCODE = 'NG009';
  END IF;
  v_norm := (SELECT COALESCE(jsonb_object_agg(r.pergunta,
                       CASE WHEN r.valor ? 'resposta'
                            THEN jsonb_build_object('escolhas', jsonb_build_array(r.valor -> 'resposta'))
                            ELSE r.valor END), '{}'::jsonb)
             FROM jsonb_each(v_respostas) AS r(pergunta, valor));

  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 20261226090000: o questionário da organização. Bloqueio PARTILHADO, o mesmo
  -- que neg_guardar_questionario toma em exclusivo: as respostas validam-se e
  -- gravam-se contra uma configuração que não muda a meio (e o tipo de uma
  -- pergunta não muda enquanto se grava uma resposta a ela).
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('levantamento_questionario:' || p_organization_id::text, 0));
  SELECT q.versao INTO v_versao
  FROM public.levantamento_questionario q
  WHERE q.organization_id = p_organization_id;
  IF v_versao IS NULL AND v_norm <> '{}'::jsonb THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  -- Validação das respostas contra o questionário (sob RLS), ANTES de
  -- escrever: pergunta desconhecida nesta organização, tipo do valor, opções
  -- da pergunta, limites -> NG009. Perguntas e opções inactivas ou apagadas
  -- aceitam-se (D5): existem e têm texto para o snapshot.
  v_res := (
    SELECT jsonb_agg(jsonb_build_object(
             'pergunta', z.pergunta, 'valido', z.valido, 'seccao', z.seccao, 'tipo', z.tipo,
             'pergunta_texto', z.texto, 'seccao_titulo', z.s_titulo, 'bloco', z.bloco,
             'ordem', z.s_ordem * 1000 + z.p_ordem,
             'escolhas', CASE WHEN z.tipo IN ('escolha_unica', 'escolha_multipla') THEN to_jsonb(z.esc) END,
             'escolhas_texto', CASE WHEN z.tipo IN ('escolha_unica', 'escolha_multipla') THEN to_jsonb(z.esc_txt) END,
             'resposta', CASE WHEN z.tipo = 'escolha_unica' THEN z.esc[1] END,
             'valor_texto', CASE WHEN z.tipo = 'texto' THEN z.txt END,
             'valor_numero', CASE WHEN z.tipo = 'numero' THEN z.num END))
    FROM (
      SELECT y.*,
             CASE
               WHEN y.pid IS NULL THEN false
               WHEN y.valor ? 'escolhas' THEN
                 y.tipo IN ('escolha_unica', 'escolha_multipla')
                 AND y.n_ok = y.n_env AND y.n_dist = y.n_env
                 AND (y.tipo = 'escolha_multipla' OR y.n_env = 1)
               WHEN y.valor ? 'texto' THEN
                 y.tipo = 'texto' AND char_length(y.txt) BETWEEN 1 AND COALESCE(y.texto_max, 2000)
               WHEN y.valor ? 'numero' THEN
                 y.tipo = 'numero' AND abs(y.num) <= 99999999999.999
                 AND y.num = round(y.num, COALESCE(y.numero_casas, 3))
                 AND (y.numero_min IS NULL OR y.num >= y.numero_min)
                 AND (y.numero_max IS NULL OR y.num <= y.numero_max)
               ELSE false
             END AS valido
      FROM (
        SELECT n.pergunta, n.valor, p.id AS pid, p.tipo, p.texto, p.bloco, p.ordem AS p_ordem,
               p.texto_max, p.numero_min, p.numero_max, p.numero_casas,
               s.chave AS seccao, s.titulo AS s_titulo, s.ordem AS s_ordem,
               CASE WHEN n.valor ? 'texto' THEN btrim(n.valor ->> 'texto') END AS txt,
               CASE WHEN n.valor ? 'numero' THEN (n.valor ->> 'numero')::numeric END AS num,
               x.n_env, x.n_dist, x.n_ok, x.esc, x.esc_txt
        FROM jsonb_each(v_norm) AS n(pergunta, valor)
        LEFT JOIN public.levantamento_perguntas p
          ON p.organization_id = p_organization_id AND p.chave = n.pergunta
        LEFT JOIN public.levantamento_seccoes s ON s.id = p.seccao_id
        LEFT JOIN LATERAL (
          SELECT count(*)::integer AS n_env, count(DISTINCT c.chave)::integer AS n_dist,
                 count(o.id)::integer AS n_ok,
                 array_agg(c.chave ORDER BY o.ordem, c.chave) FILTER (WHERE o.id IS NOT NULL) AS esc,
                 array_agg(o.texto ORDER BY o.ordem, c.chave) FILTER (WHERE o.id IS NOT NULL) AS esc_txt
          FROM jsonb_array_elements_text(CASE WHEN n.valor ? 'escolhas' THEN n.valor -> 'escolhas'
                                              ELSE '[]'::jsonb END) AS c(chave)
          LEFT JOIN public.levantamento_opcoes o ON o.pergunta_id = p.id AND o.chave = c.chave
        ) x ON true
      ) y
    ) z);
  v_erro := (SELECT x.e ->> 'pergunta'
             FROM jsonb_array_elements(v_res) AS x(e)
             WHERE NOT (x.e ->> 'valido')::boolean
             ORDER BY 1
             LIMIT 1);
  IF v_erro IS NOT NULL THEN
    RAISE EXCEPTION 'Valor inválido: resposta à pergunta %.', left(v_erro, 40) USING ERRCODE = 'NG009';
  END IF;

  -- Ordem de bloqueio: negócio primeiro (ligação feita no fim).
  IF p_negocio_id IS NOT NULL THEN
    SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);
    IF v_neg.organization_id <> p_organization_id OR v_neg.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Registo indisponível para ligar.' USING ERRCODE = 'NG004';
    END IF;
    IF EXISTS (SELECT 1 FROM public.levantamentos o
               WHERE o.negocio_id = p_negocio_id AND o.id <> p_id) THEN
      RAISE EXCEPTION 'Este negócio já tem um levantamento ligado.' USING ERRCODE = 'NG013';
    END IF;
  END IF;

  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  -- 1. CRIAR (sem negocio_id) ou alterar o existente.
  INSERT INTO public.levantamentos
    (id, organization_id, entity_id, visita_id, feito_por, data_levantamento, estado, notas,
     morada_rua, morada_codigo_postal, morada_localidade, morada_andar)
  VALUES
    (p_id, p_organization_id, p_entity_id, v_visita, v_feito_por, v_data,
     COALESCE(NULLIF(v_dados ->> 'estado', ''), 'por_fazer'),
     NULLIF(btrim(v_dados ->> 'notas'), ''),
     NULLIF(btrim(v_dados ->> 'morada_rua'), ''),
     NULLIF(btrim(v_dados ->> 'morada_codigo_postal'), ''),
     NULLIF(btrim(v_dados ->> 'morada_localidade'), ''),
     NULLIF(btrim(v_dados ->> 'morada_andar'), ''))
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_criado := v_n > 0;

  IF NOT v_criado THEN
    SELECT lv.* INTO v_lev FROM public.levantamentos lv WHERE lv.id = p_id;
    IF NOT FOUND OR v_lev.organization_id <> p_organization_id OR v_lev.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Registo indisponível para ligar.' USING ERRCODE = 'NG004';
    END IF;
    IF v_lev.negocio_id IS NOT NULL THEN
      IF v_lev.negocio_id = p_negocio_id THEN
        RETURN jsonb_build_object('levantamento_id', p_id, 'criado', false, 'mudou', false,
                                  'ligado_a', v_lev.negocio_id,
                                  'versao_questionario', v_versao,
                                  'questionario_mudou', v_versao_cl IS NOT NULL
                                                        AND v_versao_cl IS DISTINCT FROM v_versao);
      END IF;
      RAISE EXCEPTION 'Este levantamento já está ligado a um negócio e não se altera; registe um novo.'
        USING ERRCODE = 'NG005';
    END IF;

    UPDATE public.levantamentos lv
    SET visita_id            = v_visita,
        feito_por            = COALESCE(v_feito_por, lv.feito_por),
        data_levantamento    = v_data,
        estado               = COALESCE(NULLIF(v_dados ->> 'estado', ''), lv.estado),
        notas                = NULLIF(btrim(v_dados ->> 'notas'), ''),
        morada_rua           = NULLIF(btrim(v_dados ->> 'morada_rua'), ''),
        morada_codigo_postal = NULLIF(btrim(v_dados ->> 'morada_codigo_postal'), ''),
        morada_localidade    = NULLIF(btrim(v_dados ->> 'morada_localidade'), ''),
        morada_andar         = NULLIF(btrim(v_dados ->> 'morada_andar'), '')
    WHERE lv.id = p_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
      RAISE EXCEPTION 'Sem permissão para alterar o levantamento.' USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  -- 2. PREENCHER: linhas por substituição completa, na ordem recebida.
  DELETE FROM public.levantamento_linhas ll WHERE ll.levantamento_id = p_id;
  BEGIN
    INSERT INTO public.levantamento_linhas
      (levantamento_id, organization_id, divisao, trabalho, trabalho_outro, medida, unidade,
       observacoes, ordem)
    SELECT p_id, p_organization_id,
           e.valor ->> 'divisao',
           e.valor ->> 'trabalho',
           NULLIF(btrim(e.valor ->> 'trabalho_outro'), ''),
           (e.valor ->> 'medida')::numeric,
           COALESCE(NULLIF(e.valor ->> 'unidade', ''), 'm2'),
           NULLIF(btrim(e.valor ->> 'observacoes'), ''),
           (e.posicao - 1)::int
    FROM jsonb_array_elements(v_linhas) WITH ORDINALITY AS e(valor, posicao);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'Valor inválido: medida de uma linha do levantamento.' USING ERRCODE = 'NG009';
  END;

  -- Respostas: as enviadas (upsert, sem id no payload) e apagar as que deixaram de vir.
  -- 20261226090000: validadas acima; o snapshot (tipo, textos, secção, ordem) só
  -- se escreve quando a resposta é nova ou o valor mudou, para que mudar a
  -- configuração não altere o que já foi respondido.
  INSERT INTO public.levantamento_respostas AS lr
    (levantamento_id, organization_id, seccao, pergunta, resposta, tipo, pergunta_texto,
     seccao_titulo, bloco, ordem, escolhas, escolhas_texto, valor_texto, valor_numero)
  SELECT p_id, p_organization_id, x.seccao, x.pergunta, x.resposta, x.tipo, x.pergunta_texto,
         x.seccao_titulo, x.bloco, x.ordem, x.escolhas, x.escolhas_texto, x.valor_texto, x.valor_numero
  FROM jsonb_to_recordset(v_res) AS x(pergunta text, seccao text, resposta text, tipo text,
         pergunta_texto text, seccao_titulo text, bloco text, ordem integer, escolhas text[],
         escolhas_texto text[], valor_texto text, valor_numero numeric)
  LEFT JOIN public.levantamento_respostas a
    ON a.levantamento_id = p_id AND a.pergunta = x.pergunta
  WHERE a.id IS NULL
     OR a.tipo IS DISTINCT FROM x.tipo
     OR a.resposta IS DISTINCT FROM x.resposta
     OR a.valor_texto IS DISTINCT FROM x.valor_texto
     OR a.valor_numero IS DISTINCT FROM x.valor_numero
     OR ARRAY(SELECT u.c FROM unnest(a.escolhas) AS u(c) ORDER BY u.c)
        IS DISTINCT FROM ARRAY(SELECT u.c FROM unnest(x.escolhas) AS u(c) ORDER BY u.c)
  ON CONFLICT (levantamento_id, pergunta)
  DO UPDATE SET seccao = EXCLUDED.seccao, resposta = EXCLUDED.resposta, tipo = EXCLUDED.tipo,
                pergunta_texto = EXCLUDED.pergunta_texto, seccao_titulo = EXCLUDED.seccao_titulo,
                bloco = EXCLUDED.bloco, ordem = EXCLUDED.ordem, escolhas = EXCLUDED.escolhas,
                escolhas_texto = EXCLUDED.escolhas_texto, valor_texto = EXCLUDED.valor_texto,
                valor_numero = EXCLUDED.valor_numero;

  DELETE FROM public.levantamento_respostas lr
  WHERE lr.levantamento_id = p_id
    AND NOT (v_respostas ? lr.pergunta);

  -- 3. LIGAR (o trigger valida um por negócio e a permissão).
  IF p_negocio_id IS NOT NULL THEN
    UPDATE public.levantamentos lv SET negocio_id = p_negocio_id WHERE lv.id = p_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 1 THEN
      v_ligado := p_negocio_id;
    END IF;
  END IF;

  RETURN jsonb_build_object('levantamento_id', p_id, 'criado', v_criado, 'mudou', true,
                            'ligado_a', v_ligado,
                            'versao_questionario', v_versao,
                            'questionario_mudou', v_versao_cl IS NOT NULL
                                                  AND v_versao_cl IS DISTINCT FROM v_versao);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_levantamento(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_dados jsonb, p_linhas jsonb, p_respostas jsonb, p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_levantamento(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_dados jsonb, p_linhas jsonb, p_respostas jsonb, p_negocio_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_guardar_levantamento(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_dados jsonb, p_linhas jsonb, p_respostas jsonb, p_negocio_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_guardar_questionario(p_organization_id uuid, p_versao integer, p_seccoes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_escolha  CONSTANT text[] := ARRAY['escolha_unica', 'escolha_multipla'];
  c_re_uuid  CONSTANT text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_uid      uuid := auth.uid();
  v_norm     jsonb;
  v_keys_pes text[];
  v_versao   integer;
  v_actor    uuid;
  v_s        jsonb;
  v_q        jsonb;
  v_o        jsonb;
  v_si       integer;
  v_qi       integer;
  v_oi       integer;
  v_sid      uuid;
  v_pid      uuid;
  v_oid      uuid;
  v_sec      public.levantamento_seccoes;
  v_per      public.levantamento_perguntas;
  v_chave    text;
  v_n        integer;
  v_k        integer;
  v_refs     jsonb := '{}'::jsonb;
  v_vs       uuid[] := ARRAY[]::uuid[];
  v_vp       uuid[] := ARRAY[]::uuid[];
  v_vo       uuid[] := ARRAY[]::uuid[];
  v_novas_p  uuid[] := ARRAY[]::uuid[];
  v_alt_s    uuid[] := ARRAY[]::uuid[];
  v_alt_p    uuid[] := ARRAY[]::uuid[];
  v_alt_o    uuid[] := ARRAY[]::uuid[];
  v_cri_s    integer := 0;
  v_cri_p    integer := 0;
  v_cri_o    integer := 0;
  v_apa_s    integer := 0;
  v_apa_p    integer := 0;
  v_apa_o    integer := 0;
  v_alvo     uuid;
  v_alvo_txt text;
  v_dep_ops  text[];
  v_dep_sem  boolean;
  v_n_env    integer;
  v_n_ok     integer;
  v_n_dist   integer;
  v_mudou    boolean;
BEGIN
  -- 1. Valores (NG009), antes de tudo.
  IF p_organization_id IS NULL OR p_versao IS NULL OR p_versao < 1 THEN
    RAISE EXCEPTION 'Questionário inválido: organização ou versão.' USING ERRCODE = 'NG009';
  END IF;
  v_norm := public.fn_neg_questionario_normalizar(p_seccoes);

  -- 2. Sessão
  IF v_uid IS NULL OR public.current_business_user_id() IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view, Pessoas activa e questionário
  --    (a mesma mensagem nos quatro casos).
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':'))
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c WHERE c.organization_id = p_organization_id)
     OR NOT EXISTS (SELECT 1 FROM public.levantamento_questionario q WHERE q.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  -- 4. Permissão própria do Workflow de Pessoas, nesta organização.
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o levantamento.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5. Exclusivo por organização (as gravações de levantamentos tomam o
  --    mesmo bloqueio partilhado) e versão.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('levantamento_questionario:' || p_organization_id::text, 0));
  SELECT q.versao INTO v_versao
  FROM public.levantamento_questionario q
  WHERE q.organization_id = p_organization_id
  FOR UPDATE;
  IF v_versao <> p_versao THEN
    RAISE EXCEPTION 'A configuração do levantamento foi alterada entretanto; volte a abrir.' USING ERRCODE = 'NG021';
  END IF;

  -- 6 e 7. Secções, perguntas e opções, pela ordem do pedido.
  FOR v_s, v_si IN SELECT e.value, (e.ord - 1)::integer
                   FROM jsonb_array_elements(v_norm) WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
  LOOP
    v_sid := (v_s ->> 'id')::uuid;
    IF v_sid IS NOT NULL THEN
      SELECT ls.* INTO v_sec
      FROM public.levantamento_seccoes ls
      WHERE ls.id = v_sid AND ls.organization_id = p_organization_id AND ls.apagada_em IS NULL
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Questionário inválido: secção desconhecida.' USING ERRCODE = 'NG009';
      END IF;
      IF ((v_s ->> 'aba') IS NOT NULL AND (v_s ->> 'aba') <> v_sec.aba)
         OR ((v_s ->> 'especial') IS NOT NULL AND (v_s ->> 'especial') IS DISTINCT FROM v_sec.especial) THEN
        RAISE EXCEPTION 'Questionário inválido: a aba e o tipo de uma secção não mudam.' USING ERRCODE = 'NG009';
      END IF;
      IF v_sec.especial IS NOT NULL AND NOT (v_s ->> 'activa')::boolean THEN
        RAISE EXCEPTION 'Questionário inválido: as secções Visitas e Medidas só se reordenam.' USING ERRCODE = 'NG009';
      END IF;
      UPDATE public.levantamento_seccoes ls
      SET titulo = v_s ->> 'titulo', ordem = v_si, activa = (v_s ->> 'activa')::boolean
      WHERE ls.id = v_sid
        AND (ls.titulo, ls.ordem, ls.activa)
            IS DISTINCT FROM (v_s ->> 'titulo', v_si, (v_s ->> 'activa')::boolean);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN
        v_alt_s := v_alt_s || v_sid;
      END IF;
    ELSE
      IF (v_s ->> 'especial') IS NOT NULL OR COALESCE(v_s ->> 'aba', 'visita') <> 'visita' THEN
        RAISE EXCEPTION 'Questionário inválido: só se criam secções da aba Visita, sem tipo especial.'
          USING ERRCODE = 'NG009';
      END IF;
      LOOP
        v_chave := 's' || substr(md5(gen_random_uuid()::text), 1, 10);
        EXIT WHEN NOT EXISTS (SELECT 1 FROM public.levantamento_seccoes x
                              WHERE x.organization_id = p_organization_id AND x.chave = v_chave);
      END LOOP;
      INSERT INTO public.levantamento_seccoes (organization_id, chave, titulo, aba, especial, ordem, activa)
      VALUES (p_organization_id, v_chave, v_s ->> 'titulo', 'visita', NULL, v_si, (v_s ->> 'activa')::boolean)
      RETURNING * INTO v_sec;
      v_sid := v_sec.id;
      v_cri_s := v_cri_s + 1;
    END IF;
    IF v_sid = ANY (v_vs) THEN
      RAISE EXCEPTION 'Questionário inválido: secção repetida.' USING ERRCODE = 'NG009';
    END IF;
    v_vs := v_vs || v_sid;
    IF (v_s ->> 'ref') IS NOT NULL THEN
      v_refs := v_refs || jsonb_build_object(v_s ->> 'ref', v_sid);
    END IF;

    IF v_sec.especial IS NOT NULL AND jsonb_array_length(v_s -> 'perguntas') > 0 THEN
      RAISE EXCEPTION 'Questionário inválido: as secções Visitas e Medidas não têm perguntas.' USING ERRCODE = 'NG009';
    END IF;

    FOR v_q, v_qi IN SELECT e.value, (e.ord - 1)::integer
                     FROM jsonb_array_elements(v_s -> 'perguntas') WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
    LOOP
      v_pid := (v_q ->> 'id')::uuid;
      IF v_pid IS NOT NULL THEN
        SELECT lp.* INTO v_per
        FROM public.levantamento_perguntas lp
        WHERE lp.id = v_pid AND lp.organization_id = p_organization_id AND lp.apagada_em IS NULL
        FOR UPDATE;
        IF NOT FOUND OR v_pid = ANY (v_vp) THEN
          RAISE EXCEPTION 'Questionário inválido: pergunta desconhecida.' USING ERRCODE = 'NG009';
        END IF;
        -- D4 (20/10): o tipo só muda enquanto a pergunta não tiver respostas.
        IF v_per.tipo <> (v_q ->> 'tipo')
           AND EXISTS (SELECT 1 FROM public.levantamento_respostas lr
                       WHERE lr.organization_id = p_organization_id AND lr.pergunta = v_per.chave) THEN
          RAISE EXCEPTION 'Questionário inválido: a pergunta «%» já tem respostas e não muda de tipo; crie uma pergunta nova.',
            v_per.texto USING ERRCODE = 'NG009';
        END IF;
        UPDATE public.levantamento_perguntas lp
        SET seccao_id    = v_sid,
            texto        = v_q ->> 'texto',
            bloco        = v_q ->> 'bloco',
            tipo         = v_q ->> 'tipo',
            numero_min   = (v_q ->> 'numero_min')::numeric,
            numero_max   = (v_q ->> 'numero_max')::numeric,
            numero_casas = (v_q ->> 'numero_casas')::smallint,
            unidade      = v_q ->> 'unidade',
            texto_max    = (v_q ->> 'texto_max')::smallint,
            ordem        = v_qi,
            activa       = (v_q ->> 'activa')::boolean
        WHERE lp.id = v_pid
          AND (lp.seccao_id, lp.texto, lp.bloco, lp.tipo, lp.numero_min, lp.numero_max, lp.numero_casas,
               lp.unidade, lp.texto_max, lp.ordem, lp.activa)
              IS DISTINCT FROM
              (v_sid, v_q ->> 'texto', v_q ->> 'bloco', v_q ->> 'tipo', (v_q ->> 'numero_min')::numeric,
               (v_q ->> 'numero_max')::numeric, (v_q ->> 'numero_casas')::smallint, v_q ->> 'unidade',
               (v_q ->> 'texto_max')::smallint, v_qi, (v_q ->> 'activa')::boolean);
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n > 0 THEN
          v_alt_p := v_alt_p || v_pid;
        END IF;
      ELSE
        LOOP
          v_chave := 'p' || substr(md5(gen_random_uuid()::text), 1, 10);
          EXIT WHEN NOT EXISTS (SELECT 1 FROM public.levantamento_perguntas x
                                WHERE x.organization_id = p_organization_id AND x.chave = v_chave);
        END LOOP;
        INSERT INTO public.levantamento_perguntas
          (organization_id, seccao_id, chave, texto, bloco, tipo, numero_min, numero_max, numero_casas,
           unidade, texto_max, ordem, activa)
        VALUES
          (p_organization_id, v_sid, v_chave, v_q ->> 'texto', v_q ->> 'bloco', v_q ->> 'tipo',
           (v_q ->> 'numero_min')::numeric, (v_q ->> 'numero_max')::numeric, (v_q ->> 'numero_casas')::smallint,
           v_q ->> 'unidade', (v_q ->> 'texto_max')::smallint, v_qi, (v_q ->> 'activa')::boolean)
        RETURNING id INTO v_pid;
        v_novas_p := v_novas_p || v_pid;
        v_cri_p := v_cri_p + 1;
      END IF;
      v_vp := v_vp || v_pid;
      IF (v_q ->> 'ref') IS NOT NULL THEN
        v_refs := v_refs || jsonb_build_object(v_q ->> 'ref', v_pid);
      END IF;

      FOR v_o, v_oi IN SELECT e.value, (e.ord - 1)::integer
                       FROM jsonb_array_elements(v_q -> 'opcoes') WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
      LOOP
        v_oid := (v_o ->> 'id')::uuid;
        IF v_oid IS NOT NULL THEN
          PERFORM 1 FROM public.levantamento_opcoes lo
          WHERE lo.id = v_oid AND lo.pergunta_id = v_pid AND lo.organization_id = p_organization_id
            AND lo.apagada_em IS NULL
          FOR UPDATE;
          IF NOT FOUND OR v_oid = ANY (v_vo) THEN
            RAISE EXCEPTION 'Questionário inválido: opção desconhecida.' USING ERRCODE = 'NG009';
          END IF;
          UPDATE public.levantamento_opcoes lo
          SET texto = v_o ->> 'texto', ordem = v_oi, activa = (v_o ->> 'activa')::boolean
          WHERE lo.id = v_oid
            AND (lo.texto, lo.ordem, lo.activa)
                IS DISTINCT FROM (v_o ->> 'texto', v_oi, (v_o ->> 'activa')::boolean);
          GET DIAGNOSTICS v_n = ROW_COUNT;
          IF v_n > 0 THEN
            v_alt_o := v_alt_o || v_oid;
          END IF;
        ELSE
          LOOP
            v_chave := 'o' || substr(md5(gen_random_uuid()::text), 1, 8);
            EXIT WHEN NOT EXISTS (SELECT 1 FROM public.levantamento_opcoes x
                                  WHERE x.pergunta_id = v_pid AND x.chave = v_chave);
          END LOOP;
          INSERT INTO public.levantamento_opcoes (organization_id, pergunta_id, chave, texto, ordem, activa)
          VALUES (p_organization_id, v_pid, v_chave, v_o ->> 'texto', v_oi, (v_o ->> 'activa')::boolean)
          RETURNING id INTO v_oid;
          v_cri_o := v_cri_o + 1;
        END IF;
        v_vo := v_vo || v_oid;
        IF (v_o ->> 'ref') IS NOT NULL THEN
          v_refs := v_refs || jsonb_build_object(v_o ->> 'ref', v_oid);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;

  -- Apagar o que não veio (nunca DELETE). Visitas, Medidas e Qualificação ficam.
  IF EXISTS (SELECT 1 FROM public.levantamento_seccoes ls
             WHERE ls.organization_id = p_organization_id AND ls.apagada_em IS NULL
               AND ls.id <> ALL (v_vs) AND (ls.especial IS NOT NULL OR ls.chave = 'qualificacao')) THEN
    RAISE EXCEPTION 'Questionário inválido: as secções Visitas, Medidas e Qualificação não se apagam.'
      USING ERRCODE = 'NG009';
  END IF;
  UPDATE public.levantamento_opcoes lo
  SET apagada_em = now()
  WHERE lo.organization_id = p_organization_id AND lo.apagada_em IS NULL
    AND lo.pergunta_id = ANY (v_vp) AND lo.id <> ALL (v_vo);
  GET DIAGNOSTICS v_apa_o = ROW_COUNT;
  UPDATE public.levantamento_perguntas lp
  SET apagada_em = now()
  WHERE lp.organization_id = p_organization_id AND lp.apagada_em IS NULL AND lp.id <> ALL (v_vp);
  GET DIAGNOSTICS v_apa_p = ROW_COUNT;
  UPDATE public.levantamento_seccoes ls
  SET apagada_em = now()
  WHERE ls.organization_id = p_organization_id AND ls.apagada_em IS NULL AND ls.id <> ALL (v_vs);
  GET DIAGNOSTICS v_apa_s = ROW_COUNT;

  -- Condições: resolvidas depois de todas as perguntas e opções terem id
  -- (podem apontar para uma criada nesta mesma gravação, por ref).
  v_k := 0;
  FOR v_q IN SELECT q.value
             FROM jsonb_array_elements(v_norm) WITH ORDINALITY AS s(value, ord)
             CROSS JOIN LATERAL jsonb_array_elements(s.value -> 'perguntas') WITH ORDINALITY AS q(value, ord)
             ORDER BY s.ord, q.ord
  LOOP
    v_k := v_k + 1;
    v_pid := v_vp[v_k];
    v_alvo := NULL;
    v_dep_ops := NULL;
    v_dep_sem := false;
    IF jsonb_typeof(v_q -> 'depende') = 'object' THEN
      v_alvo_txt := v_q -> 'depende' ->> 'pergunta';
      v_alvo := CASE WHEN v_alvo_txt ~ c_re_uuid THEN v_alvo_txt::uuid
                     ELSE (v_refs ->> v_alvo_txt)::uuid END;
      IF v_alvo IS NULL OR NOT (v_alvo = ANY (v_vp)) OR v_alvo = v_pid THEN
        RAISE EXCEPTION 'Questionário inválido: condição de uma pergunta desconhecida.' USING ERRCODE = 'NG009';
      END IF;
      SELECT count(*), count(lo.id), count(DISTINCT lo.id), array_agg(lo.chave ORDER BY d.ord)
        INTO v_n_env, v_n_ok, v_n_dist, v_dep_ops
      FROM jsonb_array_elements_text(v_q -> 'depende' -> 'opcoes') WITH ORDINALITY AS d(ref, ord)
      LEFT JOIN public.levantamento_opcoes lo
        ON lo.id = CASE WHEN d.ref ~ c_re_uuid THEN d.ref::uuid ELSE (v_refs ->> d.ref)::uuid END
       AND lo.pergunta_id = v_alvo AND lo.apagada_em IS NULL;
      IF v_n_ok <> v_n_env OR v_n_dist <> v_n_env THEN
        RAISE EXCEPTION 'Questionário inválido: a condição tem opções desconhecidas ou repetidas.' USING ERRCODE = 'NG009';
      END IF;
      v_dep_sem := (v_q -> 'depende' ->> 'sem_resposta')::boolean;
    END IF;
    UPDATE public.levantamento_perguntas lp
    SET depende_de = v_alvo, depende_opcoes = v_dep_ops, depende_sem_resposta = v_dep_sem
    WHERE lp.id = v_pid
      AND (lp.depende_de, lp.depende_opcoes, lp.depende_sem_resposta)
          IS DISTINCT FROM (v_alvo, v_dep_ops, v_dep_sem);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 AND NOT (v_pid = ANY (v_novas_p)) AND NOT (v_pid = ANY (v_alt_p)) THEN
      v_alt_p := v_alt_p || v_pid;
    END IF;
  END LOOP;

  -- Invariantes do resultado (falha: NG009 e tudo se desfaz).
  IF EXISTS (SELECT 1
             FROM public.levantamento_perguntas lp
             JOIN public.levantamento_perguntas alvo ON alvo.id = lp.depende_de
             WHERE lp.organization_id = p_organization_id AND lp.apagada_em IS NULL
               AND (alvo.apagada_em IS NOT NULL
                    OR alvo.tipo <> ALL (c_escolha)
                    OR alvo.depende_de IS NOT NULL
                    OR EXISTS (SELECT 1 FROM unnest(lp.depende_opcoes) AS d(chave)
                               WHERE NOT EXISTS (SELECT 1 FROM public.levantamento_opcoes lo
                                                 WHERE lo.pergunta_id = alvo.id AND lo.chave = d.chave
                                                   AND lo.apagada_em IS NULL)))) THEN
    RAISE EXCEPTION 'Questionário inválido: cada condição aponta para uma pergunta de escolha viva, sem condição própria, e para opções dela.'
      USING ERRCODE = 'NG009';
  END IF;
  IF EXISTS (SELECT 1 FROM public.levantamento_perguntas lp
             WHERE lp.organization_id = p_organization_id AND lp.apagada_em IS NULL
               AND ((lp.tipo = ANY (c_escolha)
                     AND (SELECT count(*) FROM public.levantamento_opcoes lo
                          WHERE lo.pergunta_id = lp.id AND lo.apagada_em IS NULL) < 2)
                    OR (lp.tipo <> ALL (c_escolha)
                        AND EXISTS (SELECT 1 FROM public.levantamento_opcoes lo
                                    WHERE lo.pergunta_id = lp.id AND lo.apagada_em IS NULL)))) THEN
    RAISE EXCEPTION 'Questionário inválido: perguntas de escolha com 2 a 30 opções; as outras sem opções.'
      USING ERRCODE = 'NG009';
  END IF;
  IF (SELECT string_agg(ls.chave, ',' ORDER BY ls.chave) FROM public.levantamento_seccoes ls
      WHERE ls.organization_id = p_organization_id AND ls.apagada_em IS NULL
        AND (ls.especial IS NOT NULL OR ls.chave = 'qualificacao'))
     IS DISTINCT FROM 'medidas,qualificacao,visitas' THEN
    RAISE EXCEPTION 'Questionário inválido: faltam as secções Visitas, Medidas ou Qualificação.' USING ERRCODE = 'NG009';
  END IF;

  -- 8. Versão e auditoria, só se alguma coisa mudou.
  v_mudou := v_cri_s + v_cri_p + v_cri_o + v_apa_s + v_apa_p + v_apa_o
             + cardinality(v_alt_s) + cardinality(v_alt_p) + cardinality(v_alt_o) > 0;
  IF v_mudou THEN
    v_actor := public.fn_neg_actor();
    UPDATE public.levantamento_questionario q
    SET versao = q.versao + 1, updated_by = v_actor
    WHERE q.organization_id = p_organization_id
    RETURNING q.versao INTO v_versao;
    PERFORM public.fn_manual_audit_log(
      'levantamento_questionario', NULL, p_organization_id, 'UPDATE',
      jsonb_build_object('levantamento_questionario', jsonb_build_object(
        'versao', jsonb_build_object('old', v_versao - 1, 'new', v_versao),
        'criadas', jsonb_build_object('seccoes', v_cri_s, 'perguntas', v_cri_p, 'opcoes', v_cri_o),
        'alteradas', jsonb_build_object('seccoes', cardinality(v_alt_s), 'perguntas', cardinality(v_alt_p),
                                        'opcoes', cardinality(v_alt_o)),
        'apagadas', jsonb_build_object('seccoes', v_apa_s, 'perguntas', v_apa_p, 'opcoes', v_apa_o))),
      'web_app', p_organization_id);
  END IF;

  RETURN jsonb_build_object(
    'versao', v_versao,
    'mudou', v_mudou,
    'criadas', jsonb_build_object('seccoes', v_cri_s, 'perguntas', v_cri_p, 'opcoes', v_cri_o),
    'alteradas', jsonb_build_object('seccoes', cardinality(v_alt_s), 'perguntas', cardinality(v_alt_p),
                                    'opcoes', cardinality(v_alt_o)),
    'apagadas', jsonb_build_object('seccoes', v_apa_s, 'perguntas', v_apa_p, 'opcoes', v_apa_o),
    'refs', v_refs);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_questionario(p_organization_id uuid, p_versao integer, p_seccoes jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_questionario(p_organization_id uuid, p_versao integer, p_seccoes jsonb) TO authenticated;
COMMENT ON FUNCTION public.neg_guardar_questionario(p_organization_id uuid, p_versao integer, p_seccoes jsonb) IS 'Pessoas, Workflow, Levantamento: grava o questionário inteiro da organização (secções, perguntas, opções, condições). Forma inválida NG009; sem sessão 42501; sem Pessoas, sem questionário ou sem pessoas.view NG008; sem pessoas.config 42501; versão desactualizada NG021. Tipo só muda sem respostas. Devolve {versao, mudou, criadas, alteradas, apagadas, refs}. 20261226090000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_recusa_orcamento(p_organization_id uuid, p_valor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_keys_pes text[];
  v_antes    text;
BEGIN
  -- 1. Valores
  IF p_organization_id IS NULL
     OR p_valor IS NULL OR p_valor NOT IN ('perder_se_ultimo', 'manter_aberto') THEN
    RAISE EXCEPTION 'Configuração de negócios inválida.' USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view nessa organização.
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  -- 4. Permissão própria do Workflow de Pessoas, nesta organização.
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5. A mesma chave de neg_guardar_config_negocios: as duas não se cruzam.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('neg_guardar_config_negocios:' || p_organization_id::text, 0));

  -- 6. A linha da organização, em exclusivo até ao fim da transacção.
  SELECT c.recusa_orcamento INTO v_antes
  FROM public.negocio_workflow_config c
  WHERE c.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  IF v_antes = p_valor THEN
    RETURN jsonb_build_object('antes', jsonb_build_object('recusa_orcamento', v_antes),
                              'depois', jsonb_build_object('recusa_orcamento', v_antes),
                              'mudou', false);
  END IF;

  -- 7. Escrita, só na linha da organização validada acima (nunca INSERT).
  UPDATE public.negocio_workflow_config c
  SET recusa_orcamento = p_valor
  WHERE c.organization_id = p_organization_id;

  RETURN jsonb_build_object('antes', jsonb_build_object('recusa_orcamento', v_antes),
                            'depois', jsonb_build_object('recusa_orcamento', p_valor),
                            'mudou', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_recusa_orcamento(p_organization_id uuid, p_valor text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_recusa_orcamento(p_organization_id uuid, p_valor text) TO authenticated;
COMMENT ON FUNCTION public.neg_guardar_recusa_orcamento(p_organization_id uuid, p_valor text) IS 'Pessoas: grava só negocio_workflow_config.recusa_orcamento (perder_se_ultimo ou manter_aberto) da organização de quem chama, com pessoas.view e pessoas.config nessa organização; as mesmas regras e o mesmo bloqueio de neg_guardar_config_negocios, que não muda. NG008, NG009, 42501. 20261226240000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_regras_qualificacao(p_organization_id uuid, p_mql_when jsonb, p_sql_when jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_max_bytes CONSTANT integer := 32768;
  v_uid       uuid := auth.uid();
  v_mql       jsonb;
  v_sql       jsonb;
  v_keys_pes  text[];
  v_existe    boolean;
  v_antes_mql jsonb;
  v_antes_sql jsonb;
  v_actor     uuid;
BEGIN
  -- 1. Valores
  IF p_organization_id IS NULL
     OR COALESCE(octet_length(p_mql_when::text), 0)
        + COALESCE(octet_length(p_sql_when::text), 0) > c_max_bytes THEN
    RAISE EXCEPTION 'Regra de qualificação inválida.' USING ERRCODE = 'NG009';
  END IF;
  v_mql := public.fn_neg_regra_qualificacao(p_mql_when);
  v_sql := public.fn_neg_regra_qualificacao(p_sql_when);

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view e com configuração.
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 4. Permissão própria do Workflow de Pessoas, nesta organização.
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o workflow de Pessoas.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5. Linha da organização, em exclusivo até ao fim da transacção.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('neg_guardar_regras_qualificacao:' || p_organization_id::text, 0));

  SELECT r.mql_when, r.sql_when
    INTO v_antes_mql, v_antes_sql
  FROM public.lead_qualification_rules r
  WHERE r.organization_id = p_organization_id
  FOR UPDATE;
  v_existe := FOUND;

  IF (NOT v_existe AND v_mql IS NULL AND v_sql IS NULL)
     OR (v_existe
         AND v_antes_mql IS NOT DISTINCT FROM v_mql
         AND v_antes_sql IS NOT DISTINCT FROM v_sql) THEN
    RETURN jsonb_build_object(
      'antes',  jsonb_build_object('mql_when', v_antes_mql, 'sql_when', v_antes_sql),
      'depois', jsonb_build_object('mql_when', v_antes_mql, 'sql_when', v_antes_sql),
      'mudou',  false);
  END IF;

  -- 6. Escrita, só na linha da organização validada acima.
  v_actor := public.fn_neg_actor();

  IF v_existe THEN
    UPDATE public.lead_qualification_rules r
    SET mql_when   = v_mql,
        sql_when   = v_sql,
        updated_by = v_actor
    WHERE r.organization_id = p_organization_id;
  ELSE
    INSERT INTO public.lead_qualification_rules AS r
      (organization_id, mql_when, sql_when, created_by, updated_by)
    VALUES (p_organization_id, v_mql, v_sql, v_actor, v_actor)
    ON CONFLICT (organization_id) DO UPDATE
      SET mql_when   = EXCLUDED.mql_when,
          sql_when   = EXCLUDED.sql_when,
          updated_by = EXCLUDED.updated_by;
  END IF;

  RETURN jsonb_build_object(
    'antes',  jsonb_build_object('mql_when', v_antes_mql, 'sql_when', v_antes_sql),
    'depois', jsonb_build_object('mql_when', v_mql, 'sql_when', v_sql),
    'mudou',  true);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_regras_qualificacao(p_organization_id uuid, p_mql_when jsonb, p_sql_when jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_regras_qualificacao(p_organization_id uuid, p_mql_when jsonb, p_sql_when jsonb) TO authenticated;
COMMENT ON FUNCTION public.neg_guardar_regras_qualificacao(p_organization_id uuid, p_mql_when jsonb, p_sql_when jsonb) IS 'Pessoas, Workflow, Qualificação: grava as regras MQL/SQL da organização em lead_qualification_rules (só a linha dessa organização) e devolve {antes, depois, mudou}. Regra inválida NG009; sem sessão 42501; organização sem Pessoas ou sem pessoas.view NG008; sem pessoas.config 42501. Nunca cria regras por omissão. 20261226030000.';

CREATE OR REPLACE FUNCTION public.neg_guardar_visita(p_organization_id uuid, p_entity_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_local text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_recursos uuid[] DEFAULT NULL::uuid[], p_visit_kind text DEFAULT NULL::text, p_negocio_id uuid DEFAULT NULL::uuid, p_detalhes jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid        uuid := auth.uid();
  v_actor      uuid;
  v_titulo     text := NULLIF(btrim(p_titulo), '');
  v_notas      text := NULLIF(btrim(p_notas), '');
  v_local      text := NULLIF(btrim(p_local), '');
  v_det        jsonb;
  v_keys_lead  text[];
  v_keys_cli   text[];
  v_keys_pes   text[];
  v_lead_id    uuid;
  v_client_id  uuid;
  v_neg_id     uuid;
  v_tipo_quadro text;
  v_recursos   uuid[];
  v_conflito   uuid[];
  v_r          uuid;
  v_item       public.schedule_items;
BEGIN
  -- 1. Sessão e actor
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  -- Parâmetros
  IF p_board_id IS NULL OR p_inicio IS NULL OR p_fim IS NULL
     OR p_fim <= p_inicio OR p_fim - p_inicio > interval '1 day' THEN
    RAISE EXCEPTION 'Valor inválido: quadro ou horário da visita (fim depois do início, até 1 dia).'
      USING ERRCODE = 'NG009';
  END IF;
  IF (p_visit_kind IS NOT NULL AND p_visit_kind NOT IN ('levantamento', 'medicao', 'materiais', 'revisita'))
     OR char_length(v_titulo) > 200 OR char_length(v_notas) > 5000 OR char_length(v_local) > 500
     OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180
     OR COALESCE(cardinality(p_recursos), 0) > 20 THEN
    RAISE EXCEPTION 'Valor inválido: tipo, título, notas, local, coordenadas ou recursos da visita.'
      USING ERRCODE = 'NG009';
  END IF;
  v_det := public.fn_neg_detalhes_visita(p_detalhes);

  -- 2. Organização do utilizador, com pessoas.view e com configuração (D1).
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF p_organization_id IS NULL
     OR NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':'))
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                    WHERE c.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;

  -- 3 e 4. Pessoa ligada e visível; a visita fica na lead viva mais recente
  --    visível, senão no cliente visível.
  IF p_entity_id IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.anew_entity_org_links lk
       WHERE lk.entity_id = p_entity_id AND lk.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  IF public.has_anew_permission(v_uid, 'leads.view') THEN
    v_keys_lead := public.crm_scope_keys('leads.view');
    SELECT l.id INTO v_lead_id
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
      AND l.deleted_at IS NULL
      AND EXISTS (SELECT 1 FROM unnest(v_keys_lead) AS k(scope_key)
                  WHERE k.scope_key = l.organization_id::text || ':*'
                     OR k.scope_key = l.organization_id::text || ':' || l.assigned_to::text
                     OR k.scope_key = l.organization_id::text || ':' || l.created_by::text)
    ORDER BY l.created_at DESC
    LIMIT 1;
  END IF;

  IF v_lead_id IS NULL AND public.has_anew_permission(v_uid, 'clients.view') THEN
    v_keys_cli := public.crm_scope_keys('clients.view');
    SELECT c.id INTO v_client_id
    FROM public.anew_clients c
    WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
      AND c.deleted_at IS NULL
      AND EXISTS (SELECT 1 FROM unnest(v_keys_cli) AS k(scope_key)
                  WHERE k.scope_key = c.organization_id::text || ':*'
                     OR k.scope_key = c.organization_id::text || ':' || c.assigned_to::text
                     OR k.scope_key = c.organization_id::text || ':' || c.created_by::text)
    ORDER BY c.created_at ASC
    LIMIT 1;
  END IF;

  IF v_lead_id IS NULL AND v_client_id IS NULL THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 5. Quadro e recursos DESTA organização, antes de bloquear o negócio ou
  --    de ler ocupação. Quadro: existe nesta organização e não é de ausências.
  --    "Não existe" e "é de outra organização" dão a mesma mensagem.
  SELECT b.board_type INTO v_tipo_quadro
  FROM public.schedule_boards b
  WHERE b.id = p_board_id AND b.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quadro ou recurso indisponível.' USING ERRCODE = 'NG008';
  END IF;
  IF v_tipo_quadro = 'time_off' THEN
    RAISE EXCEPTION 'Valor inválido: o quadro de ausências não serve para visitas.' USING ERRCODE = 'NG009';
  END IF;

  --    Recursos: sem recursos, o rpc usa o recurso activo do criador nesta
  --    organização; verifica-se esse (se ainda não existir, o rpc cria-o e não
  --    há conflito).
  v_recursos := (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(p_recursos) AS u(x) WHERE x IS NOT NULL);
  IF v_recursos IS NULL THEN
    v_conflito := ARRAY(
      SELECT r.id FROM public.schedule_resources r
      WHERE r.user_id = v_actor AND r.organization_id = p_organization_id AND r.is_active = true
      ORDER BY r.created_at ASC
      LIMIT 1);
  ELSE
    -- Cada recurso pedido existe, está activo e é desta organização (antes
    -- de qualquer bloqueio ou leitura de ocupação: sem oráculo de recursos
    -- alheios).
    IF (SELECT count(*) FROM public.schedule_resources r
        WHERE r.id = ANY (v_recursos) AND r.organization_id = p_organization_id
          AND r.is_active = true) <> cardinality(v_recursos) THEN
      RAISE EXCEPTION 'Quadro ou recurso indisponível.' USING ERRCODE = 'NG008';
    END IF;
    v_conflito := v_recursos;
  END IF;

  -- 6. Negócio: aberto, da mesma organização e pessoa, com pessoas.edit e
  --    âmbito (cópia do teste de negocios_update). Só se bloqueia a linha
  --    que passa em tudo.
  IF p_negocio_id IS NOT NULL THEN
    IF public.has_anew_permission(v_uid, 'pessoas.edit') THEN
      SELECT n.id INTO v_neg_id
      FROM public.negocios n
      WHERE n.id = p_negocio_id
        AND n.organization_id = p_organization_id
        AND n.entity_id = p_entity_id
        AND n.estado = 'aberto'
        AND n.deleted_at IS NULL
        AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
                    WHERE k.scope_key = n.organization_id::text || ':*'
                       OR k.scope_key = n.organization_id::text || ':' || n.assigned_to::text
                       OR k.scope_key = n.organization_id::text || ':' || n.created_by::text)
      FOR NO KEY UPDATE;
    END IF;
    IF v_neg_id IS NULL THEN
      RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
    END IF;
  END IF;

  -- 7. Conflitos, por ordem de uuid, com bloqueio consultivo por recurso.
  FOREACH v_r IN ARRAY COALESCE(v_conflito, ARRAY[]::uuid[]) LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('agenda:' || v_r::text, 0));
    IF public.check_schedule_conflict(v_r, p_inicio, p_fim, NULL::uuid) THEN
      RAISE EXCEPTION 'O recurso já tem outra marcação nesse horário.'
        USING ERRCODE = 'NG010', DETAIL = v_r::text;
    END IF;
  END LOOP;

  -- 8. Criar pela função do calendário (verificações dela com o auth.uid() real).
  SELECT si.* INTO v_item
  FROM public.rpc_create_schedule_item(
    p_organization_id      => p_organization_id,
    p_board_id             => p_board_id,
    p_title                => COALESCE(v_titulo, 'Visita'),
    p_description          => v_notas,
    p_status               => 'scheduled'::public.schedule_item_status,
    p_origin               => 'manual'::public.schedule_item_origin,
    p_start_datetime       => p_inicio,
    p_end_datetime         => p_fim,
    p_all_day              => false,
    p_client_id            => v_client_id,
    p_location             => v_local,
    p_location_lat         => p_lat,
    p_location_lng         => p_lng,
    p_metadata             => CASE WHEN v_det IS NULL THEN NULL
                                   ELSE jsonb_build_object('pessoas', v_det) END,
    p_assignee_resource_ids => v_recursos,
    p_lead_id              => v_lead_id) AS si;

  -- 9. O resto do INSERT, auditado (o rpc deixou a auditoria genérica desligada).
  PERFORM set_config('app.audit_bypass', 'off', true);
  IF p_visit_kind IS NOT NULL OR v_neg_id IS NOT NULL THEN
    UPDATE public.schedule_items s
    SET visit_kind = p_visit_kind, negocio_id = v_neg_id
    WHERE s.id = v_item.id;
  END IF;

  RETURN jsonb_build_object('visita_id', v_item.id, 'mudou', true, 'ligado_a', v_neg_id);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_guardar_visita(p_organization_id uuid, p_entity_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text, p_notas text, p_local text, p_lat numeric, p_lng numeric, p_recursos uuid[], p_visit_kind text, p_negocio_id uuid, p_detalhes jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_guardar_visita(p_organization_id uuid, p_entity_id uuid, p_board_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_titulo text, p_notas text, p_local text, p_lat numeric, p_lng numeric, p_recursos uuid[], p_visit_kind text, p_negocio_id uuid, p_detalhes jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_ligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg      public.negocios;
  v_existe   boolean;
  v_atual    uuid;
  v_n        int;
  v_sem_base boolean;
  v_criado   timestamptz;
  v_activado timestamptz;
BEGIN
  IF p_registo_id IS NULL OR p_tipo IS NULL
     OR p_tipo NOT IN ('contacto', 'visita', 'levantamento', 'orcamento', 'proposta', 'contrato') THEN
    RAISE EXCEPTION 'Valor inválido: tipo ou registo.' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);

  IF p_tipo = 'contrato' AND v_neg.fecho = 'proposta' THEN
    RAISE EXCEPTION 'Este negócio fecha na proposta (venda directa): não se ligam contratos.'
      USING ERRCODE = 'NG023';
  END IF;

  -- Documentos: só os criados antes da activação de Pessoas na organização.
  SELECT c.created_at INTO v_activado
  FROM public.negocio_workflow_config c WHERE c.organization_id = v_neg.organization_id;

  IF p_tipo = 'contacto' THEN
    SELECT true, i.negocio_id INTO v_existe, v_atual
    FROM public.entity_interactions i
    WHERE i.id = p_registo_id AND i.organization_id = v_neg.organization_id
      AND i.entity_id = v_neg.entity_id;
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    UPDATE public.entity_interactions i SET negocio_id = v_neg.id
    WHERE i.id = p_registo_id AND i.organization_id = v_neg.organization_id
      AND i.entity_id = v_neg.entity_id AND i.negocio_id IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;

  ELSIF p_tipo = 'visita' THEN
    SELECT true, s.negocio_id INTO v_existe, v_atual
    FROM public.schedule_items s
    WHERE s.id = p_registo_id AND s.organization_id = v_neg.organization_id
      AND s.time_off_type IS NULL AND s.vacation_id IS NULL
      AND (EXISTS (SELECT 1 FROM public.anew_leads l WHERE l.id = s.lead_id AND l.entity_id = v_neg.entity_id)
           OR EXISTS (SELECT 1 FROM public.anew_clients c WHERE c.id = s.client_id AND c.entity_id = v_neg.entity_id));
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    UPDATE public.schedule_items s SET negocio_id = v_neg.id
    WHERE s.id = p_registo_id AND s.organization_id = v_neg.organization_id
      AND s.time_off_type IS NULL AND s.vacation_id IS NULL AND s.negocio_id IS NULL
      AND (EXISTS (SELECT 1 FROM public.anew_leads l WHERE l.id = s.lead_id AND l.entity_id = v_neg.entity_id)
           OR EXISTS (SELECT 1 FROM public.anew_clients c WHERE c.id = s.client_id AND c.entity_id = v_neg.entity_id));
    GET DIAGNOSTICS v_n = ROW_COUNT;

  ELSIF p_tipo = 'levantamento' THEN
    -- O trigger do levantamento valida o resto (um por negócio, permissão).
    SELECT true, lv.negocio_id INTO v_existe, v_atual
    FROM public.levantamentos lv
    WHERE lv.id = p_registo_id AND lv.organization_id = v_neg.organization_id
      AND lv.entity_id = v_neg.entity_id AND lv.deleted_at IS NULL;
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    IF EXISTS (SELECT 1 FROM public.levantamentos o
               WHERE o.negocio_id = v_neg.id AND o.id <> p_registo_id) THEN
      RAISE EXCEPTION 'Este negócio já tem um levantamento ligado.' USING ERRCODE = 'NG013';
    END IF;
    UPDATE public.levantamentos lv SET negocio_id = v_neg.id
    WHERE lv.id = p_registo_id AND lv.organization_id = v_neg.organization_id
      AND lv.entity_id = v_neg.entity_id AND lv.deleted_at IS NULL AND lv.negocio_id IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;

  ELSIF p_tipo = 'orcamento' THEN
    SELECT true, q.negocio_id, q.created_at INTO v_existe, v_atual, v_criado
    FROM public.quotes q
    WHERE q.id = p_registo_id AND q.organization_id = v_neg.organization_id
      AND q.entity_id = v_neg.entity_id AND q.deleted_at IS NULL;
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    IF v_existe AND v_criado >= v_activado THEN
      RAISE EXCEPTION 'Só os documentos anteriores à activação se ligam à mão.' USING ERRCODE = 'NG024';
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.quotes q SET negocio_id = v_neg.id
    WHERE q.id = p_registo_id AND q.organization_id = v_neg.organization_id
      AND q.entity_id = v_neg.entity_id AND q.deleted_at IS NULL AND q.negocio_id IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);

  ELSIF p_tipo = 'proposta' THEN
    SELECT true, pr.negocio_id, pr.created_at INTO v_existe, v_atual, v_criado
    FROM public.proposals pr
    WHERE pr.id = p_registo_id AND pr.organization_id = v_neg.organization_id
      AND pr.entity_id = v_neg.entity_id AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE;
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    IF v_existe AND v_criado >= v_activado THEN
      RAISE EXCEPTION 'Só os documentos anteriores à activação se ligam à mão.' USING ERRCODE = 'NG024';
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.proposals pr SET negocio_id = v_neg.id
    WHERE pr.id = p_registo_id AND pr.organization_id = v_neg.organization_id
      AND pr.entity_id = v_neg.entity_id AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
      AND pr.negocio_id IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);

  ELSE -- contrato
    SELECT true, cc.negocio_id,
           (cc.status NOT IN ('signed', 'assinado') AND cc.quote_id IS NULL AND cc.proposal_id IS NULL),
           cc.created_at
      INTO v_existe, v_atual, v_sem_base, v_criado
    FROM public.client_contracts cc
    WHERE cc.id = p_registo_id AND cc.organization_id = v_neg.organization_id
      AND cc.entity_id = v_neg.entity_id AND cc.deleted_at IS NULL;
    IF v_existe AND v_atual IS NOT DISTINCT FROM v_neg.id THEN
      RETURN jsonb_build_object('mudou', false);
    END IF;
    IF v_existe AND v_criado >= v_activado THEN
      RAISE EXCEPTION 'Só os documentos anteriores à activação se ligam à mão.' USING ERRCODE = 'NG024';
    END IF;
    -- Contrato por assinar sem orçamento nem proposta: o trigger existente
    -- set_client_contract_total_value_sem_iva poria o valor a NULL.
    IF v_existe AND v_sem_base THEN
      RAISE EXCEPTION 'Este contrato não tem orçamento nem proposta: não se liga antes de ser assinado.'
        USING ERRCODE = 'NG014';
    END IF;
    PERFORM set_config('app.neg_via_funcao', 'on', true);
    UPDATE public.client_contracts cc SET negocio_id = v_neg.id
    WHERE cc.id = p_registo_id AND cc.organization_id = v_neg.organization_id
      AND cc.entity_id = v_neg.entity_id AND cc.deleted_at IS NULL AND cc.negocio_id IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM set_config('app.neg_via_funcao', 'off', true);
  END IF;

  IF v_n = 0 THEN
    RAISE EXCEPTION 'Registo indisponível para ligar.' USING ERRCODE = 'NG004';
  END IF;
  RETURN jsonb_build_object('mudou', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_ligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_ligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_ligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) TO service_role;
COMMENT ON FUNCTION public.neg_ligar_registo(p_negocio_id uuid, p_tipo text, p_registo_id uuid) IS 'Pessoas: liga um registo a um negócio aberto. Só para a migração dos dados actuais: os documentos (orçamento, proposta, contrato) só se ligam se criados antes da activação de Pessoas (NG024); contrato num negócio com fecho na proposta NG023. 20261226140000.';

CREATE OR REPLACE FUNCTION public.neg_mudar_fecho(p_negocio_id uuid, p_fecho text, p_confirmar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg      public.negocios;
  v_ganharia boolean := false;
  v_reav     jsonb;
BEGIN
  IF p_fecho IS NULL OR p_fecho NOT IN ('proposta', 'contrato') THEN
    RAISE EXCEPTION 'Valor inválido: tipo de fecho (proposta ou contrato).' USING ERRCODE = 'NG009';
  END IF;

  -- Existe, não está no lixo, organização com Pessoas e pessoas.edit com
  -- âmbito (RLS de negocios no FOR NO KEY UPDATE).
  SELECT * INTO v_neg
  FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto', 'ganho', 'perdido']);

  IF v_neg.estado <> 'aberto' THEN
    RAISE EXCEPTION 'O tipo de fecho só muda num negócio aberto: reabra o negócio ou anule a perda primeiro.'
      USING ERRCODE = 'NG022';
  END IF;

  IF v_neg.fecho = p_fecho THEN
    RETURN jsonb_build_object('mudou', false, 'fecho', v_neg.fecho, 'precisa_confirmar', false);
  END IF;

  IF p_fecho = 'proposta' THEN
    IF EXISTS (SELECT 1 FROM public.client_contracts cc
               WHERE cc.negocio_id = v_neg.id AND cc.deleted_at IS NULL
                 AND cc.replaced_by_contract_id IS NULL
                 AND cc.status IN ('pending_signature', 'signed', 'assinado', 'active')) THEN
      RAISE EXCEPTION 'Há um contrato assinado ou enviado para assinatura: o negócio não pode passar a fechar na proposta.'
        USING ERRCODE = 'NG022';
    END IF;
    v_ganharia := EXISTS (SELECT 1 FROM public.proposals pr
                          WHERE pr.negocio_id = v_neg.id AND pr.status = 'accepted'
                            AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE);
  ELSE
    IF EXISTS (SELECT 1 FROM public.proposals pr
               WHERE pr.negocio_id = v_neg.id AND pr.status = 'accepted'
                 AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE) THEN
      RAISE EXCEPTION 'Há uma proposta aceite: o negócio não pode passar a fechar no contrato.'
        USING ERRCODE = 'NG022';
    END IF;
    v_ganharia := EXISTS (SELECT 1 FROM public.client_contracts cc
                          WHERE cc.negocio_id = v_neg.id AND cc.deleted_at IS NULL
                            AND cc.replaced_by_contract_id IS NULL
                            AND cc.status IN ('signed', 'assinado', 'active'));
  END IF;

  IF v_ganharia AND NOT COALESCE(p_confirmar, false) THEN
    RETURN jsonb_build_object('mudou', false, 'fecho', v_neg.fecho, 'precisa_confirmar', true);
  END IF;

  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n SET fecho = p_fecho WHERE n.id = v_neg.id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);

  -- Fase N, D: um positivo decisivo com prova dá o ganho (nunca sem prova).
  IF v_ganharia THEN
    v_reav := public.neg_reavaliar_negocio(v_neg.id);
  END IF;

  RETURN jsonb_build_object('mudou', true, 'fecho', p_fecho, 'precisa_confirmar', false,
                            'reavaliacao', v_reav);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_mudar_fecho(p_negocio_id uuid, p_fecho text, p_confirmar boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_mudar_fecho(p_negocio_id uuid, p_fecho text, p_confirmar boolean) TO authenticated;
COMMENT ON FUNCTION public.neg_mudar_fecho(p_negocio_id uuid, p_fecho text, p_confirmar boolean) IS 'Pessoas: muda o tipo de fecho de um negócio aberto (secção 3 do desenho v4). NG022 se ganho/perdido, se há contrato activo assinado ou em pending_signature (para proposta) ou proposta aceite (para contrato). Com um positivo que passaria a decidir, devolve precisa_confirmar e só muda com p_confirmar. NG009 valores. 20261226110000.';

CREATE OR REPLACE FUNCTION public.neg_perder_negocio(p_negocio_id uuid, p_fase text, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_motivo text := btrim(p_motivo);
BEGIN
  IF p_fase IS NULL OR p_fase NOT IN
     ('lead', 'contacto', 'visita', 'levantamento', 'orcamento', 'proposta', 'contrato') THEN
    RAISE EXCEPTION 'Valor inválido: fase da perda.' USING ERRCODE = 'NG009';
  END IF;
  IF v_motivo IS NULL OR v_motivo = '' OR char_length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'Valor inválido: motivo da perda (1 a 1000 caracteres).' USING ERRCODE = 'NG009';
  END IF;

  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto', 'perdido']);

  IF v_neg.estado = 'perdido' AND v_neg.fase_perda = p_fase AND v_neg.motivo_perda = v_motivo THEN
    RETURN jsonb_build_object('mudou', false, 'estado', 'perdido');
  END IF;

  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n
  SET estado = 'perdido', fase_perda = p_fase, motivo_perda = v_motivo
  WHERE n.id = v_neg.id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);

  RETURN jsonb_build_object('mudou', true, 'estado', 'perdido');
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_perder_negocio(p_negocio_id uuid, p_fase text, p_motivo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_perder_negocio(p_negocio_id uuid, p_fase text, p_motivo text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_perder_negocio(p_negocio_id uuid, p_fase text, p_motivo text) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_procurar_duplicados(p_organization_id uuid, p_email text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_nif_hash text DEFAULT NULL::text, p_pais text DEFAULT 'PT'::text)
 RETURNS TABLE(pessoa integer, campo text, ambito text, entity_id uuid, nome text, visivel boolean, organizacao_id uuid, organizacao_nome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  c_bucket_utilizador   CONSTANT text    := 'neg_procurar_duplicados:utilizador';
  c_bucket_organizacao  CONSTANT text    := 'neg_procurar_duplicados:organizacao';
  c_max_utilizador_5min CONSTANT integer := 30;
  c_max_utilizador_hora CONSTANT integer := 200;
  c_max_organizacao_hora CONSTANT integer := 2000;
  v_uid       uuid := auth.uid();
  v_email     text := lower(NULLIF(btrim(p_email), ''));
  v_tel       text := NULLIF(btrim(p_telefone), '');
  v_dig       text;
  v_nif       text := lower(NULLIF(btrim(p_nif_hash), ''));
  v_pais      text := upper(COALESCE(NULLIF(btrim(p_pais), ''), 'PT'));
  v_orgs      uuid[];
  v_keys_pes  text[];
  v_keys_lead text[];
  v_keys_cli  text[];
  v_n_5min    integer;
  v_n_hora    integer;
  v_n_org     integer;
  v_linhas    integer;
BEGIN
  -- 1. Valores
  v_dig := regexp_replace(COALESCE(v_tel, ''), '[^0-9]', '', 'g');
  IF p_organization_id IS NULL
     OR (v_email IS NULL AND v_tel IS NULL AND v_nif IS NULL)
     OR (v_email IS NOT NULL AND (char_length(v_email) > 254
                                  OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'))
     OR (v_tel IS NOT NULL AND (char_length(v_tel) > 30
                                OR v_tel !~ '^\+?[0-9 ().-]+$'
                                OR char_length(v_dig) NOT BETWEEN 7 AND 15))
     OR (v_nif IS NOT NULL AND v_nif !~ '^[0-9a-f]{64}$')
     OR v_pais !~ '^[A-Z]{2}$' THEN
    RAISE EXCEPTION 'Valor inválido: organização, email, telefone (7 a 15 dígitos) ou NIF.'
      USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view e com configuração.
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 4. Quem procura duplicados é quem pode criar a lead nesta organização.
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'leads.create') THEN
    RAISE EXCEPTION 'Sem permissão para criar leads nesta organização.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5. Limite de pedidos (por utilizador e por organização).
  PERFORM pg_advisory_xact_lock(hashtextextended(c_bucket_utilizador || ':' || v_uid::text, 0));

  SELECT count(*) FILTER (WHERE r.created_at > now() - interval '5 minutes'),
         count(*)
    INTO v_n_5min, v_n_hora
  FROM public.rate_limit_attempts r
  WHERE r.bucket = c_bucket_utilizador
    AND r.identifier = v_uid::text
    AND r.created_at > now() - interval '1 hour';

  SELECT count(*) INTO v_n_org
  FROM public.rate_limit_attempts r
  WHERE r.bucket = c_bucket_organizacao
    AND r.identifier = p_organization_id::text
    AND r.created_at > now() - interval '1 hour';

  IF v_n_5min >= c_max_utilizador_5min
     OR v_n_hora >= c_max_utilizador_hora
     OR v_n_org >= c_max_organizacao_hora THEN
    RAISE EXCEPTION 'Demasiadas verificações seguidas. Tente de novo mais tarde.'
      USING ERRCODE = 'NG020';
  END IF;

  -- 6. Organizações onde se procura: esta e as do grupo que quem chama vê.
  v_orgs := ARRAY[p_organization_id]
         || ARRAY(SELECT g.id
                  FROM public.get_org_group_ids(p_organization_id) AS g(id)
                  WHERE g.id <> p_organization_id
                    AND g.id IN (SELECT public.get_user_visible_org_ids(v_uid)));

  -- 7. Âmbito de leitura de quem chama (para entity_id e nome).
  v_keys_lead := CASE WHEN public.has_anew_permission(v_uid, 'leads.view')
                      THEN public.crm_scope_keys('leads.view') ELSE ARRAY[]::text[] END;
  v_keys_cli  := CASE WHEN public.has_anew_permission(v_uid, 'clients.view')
                      THEN public.crm_scope_keys('clients.view') ELSE ARRAY[]::text[] END;

  -- 8. Procura.
  RETURN QUERY
  WITH universo AS (
    SELECT lk.entity_id AS ent, lk.organization_id AS org
    FROM public.anew_entity_org_links lk
    WHERE lk.organization_id = ANY (v_orgs)
    UNION
    SELECT l.entity_id, l.organization_id
    FROM public.anew_leads l
    WHERE l.organization_id = ANY (v_orgs) AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
    UNION
    SELECT c.entity_id, c.organization_id
    FROM public.anew_clients c
    WHERE c.organization_id = ANY (v_orgs) AND c.deleted_at IS NULL AND c.entity_id IS NOT NULL
    UNION
    SELECT er.entity_id, er.organization_id
    FROM public.anew_entity_roles er
    WHERE er.organization_id = ANY (v_orgs) AND er.deleted_at IS NULL AND er.entity_id IS NOT NULL
  ),
  entidades AS (
    SELECT DISTINCT u.ent FROM universo u
  ),
  coincide AS (
    SELECT em.entity_id AS ent, 'email'::text AS cmp
    FROM entidades e
    JOIN public.anew_entity_emails em ON em.entity_id = e.ent
    WHERE v_email IS NOT NULL
      AND lower(btrim(em.email)) = v_email
    UNION
    SELECT ph.entity_id, 'telefone'::text
    FROM entidades e
    JOIN public.anew_entity_phones ph ON ph.entity_id = e.ent
    WHERE v_tel IS NOT NULL
      AND char_length(regexp_replace(COALESCE(ph.phone_number, ''), '[^0-9]', '', 'g')) >= 7
      AND (regexp_replace(COALESCE(ph.phone_number, ''), '[^0-9]', '', 'g') LIKE '%' || v_dig
           OR v_dig LIKE '%' || regexp_replace(COALESCE(ph.phone_number, ''), '[^0-9]', '', 'g'))
    UNION
    SELECT aef.entity_id, 'nif'::text
    FROM entidades e
    JOIN public.anew_entity_fiscal_entities aef ON aef.entity_id = e.ent
    JOIN public.fiscal_entities fe ON fe.id = aef.fiscal_entity_id
    WHERE v_nif IS NOT NULL
      AND fe.nif_hash = v_nif
      AND fe.country_code = v_pais
  ),
  nesta AS (
    SELECT c.ent, c.cmp
    FROM coincide c
    WHERE EXISTS (SELECT 1 FROM universo u WHERE u.ent = c.ent AND u.org = p_organization_id)
  ),
  nesta_vista AS (
    SELECT n.ent,
           n.cmp,
           dense_rank() OVER (ORDER BY n.ent)::integer AS num,
           (EXISTS (SELECT 1 FROM public.anew_leads l
                    WHERE l.organization_id = p_organization_id AND l.entity_id = n.ent
                      AND l.deleted_at IS NULL
                      AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
                           OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
                           OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead)))
            OR EXISTS (SELECT 1 FROM public.anew_clients c
                       WHERE c.organization_id = p_organization_id AND c.entity_id = n.ent
                         AND c.deleted_at IS NULL
                         AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
                              OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
                              OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli))))
             AS ve
    FROM nesta n
  ),
  no_grupo AS (
    SELECT DISTINCT c.cmp, u.org
    FROM coincide c
    JOIN universo u ON u.ent = c.ent AND u.org <> p_organization_id
    WHERE NOT EXISTS (SELECT 1 FROM nesta n WHERE n.ent = c.ent)
  ),
  linhas AS (
    SELECT 1 AS ordem,
           nv.num AS r_pessoa,
           nv.cmp AS r_campo,
           'organizacao'::text AS r_ambito,
           CASE WHEN nv.ve THEN nv.ent END AS r_entity_id,
           CASE WHEN nv.ve THEN ent.display_name END AS r_nome,
           nv.ve AS r_visivel,
           p_organization_id AS r_org,
           NULL::text AS r_org_nome
    FROM nesta_vista nv
    LEFT JOIN public.anew_entities ent ON ent.id = nv.ent
    UNION ALL
    SELECT 2,
           NULL::integer,
           g.cmp,
           'grupo'::text,
           NULL::uuid,
           NULL::text,
           NULL::boolean,
           g.org,
           o.name::text
    FROM no_grupo g
    LEFT JOIN public.anew_organizations o ON o.id = g.org
  )
  SELECT x.r_pessoa, x.r_campo, x.r_ambito, x.r_entity_id, x.r_nome, x.r_visivel, x.r_org, x.r_org_nome
  FROM linhas x
  ORDER BY x.ordem, x.r_pessoa, x.r_campo, x.r_org_nome
  LIMIT 50;

  GET DIAGNOSTICS v_linhas = ROW_COUNT;

  -- 9. Registo da tentativa (sem o valor procurado).
  INSERT INTO public.rate_limit_attempts (bucket, identifier, success)
  VALUES (c_bucket_utilizador,  v_uid::text,               v_linhas = 0),
         (c_bucket_organizacao, p_organization_id::text,   v_linhas = 0);

  RETURN;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_procurar_duplicados(p_organization_id uuid, p_email text, p_telefone text, p_nif_hash text, p_pais text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_procurar_duplicados(p_organization_id uuid, p_email text, p_telefone text, p_nif_hash text, p_pais text) TO authenticated;
COMMENT ON FUNCTION public.neg_procurar_duplicados(p_organization_id uuid, p_email text, p_telefone text, p_nif_hash text, p_pais text) IS 'Pessoas, «Nova lead»: procura email, telefone e NIF (hash) nas pessoas desta organização e, como informação, nas do grupo visível. Uma linha por pessoa e campo; entity_id e nome só no âmbito de leitura de quem chama. pessoas.view + configuração (NG008), leads.create (42501), limite por utilizador e organização (NG020). 20261225200000.';

CREATE OR REPLACE FUNCTION public.neg_questionario_levantamento(p_organization_id uuid, p_incluir_inactivas boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_versao integer;
BEGIN
  IF p_organization_id IS NULL OR p_incluir_inactivas IS NULL THEN
    RAISE EXCEPTION 'Valor inválido: organização.' USING ERRCODE = 'NG009';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);
  SELECT q.versao INTO v_versao
  FROM public.levantamento_questionario q
  WHERE q.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  IF p_incluir_inactivas AND NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.config') THEN
    RAISE EXCEPTION 'Sem permissão para configurar o levantamento.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'versao', v_versao,
      'seccoes', COALESCE(jsonb_agg(jsonb_build_object(
        'id', s.id, 'chave', s.chave, 'titulo', s.titulo, 'aba', s.aba, 'especial', s.especial,
        'ordem', s.ordem, 'activa', s.activa,
        'perguntas', (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
                   'id', p.id, 'chave', p.chave, 'texto', p.texto, 'tipo', p.tipo, 'bloco', p.bloco,
                   'ordem', p.ordem, 'activa', p.activa,
                   'numero', CASE WHEN p.tipo = 'numero' THEN jsonb_build_object(
                               'min', p.numero_min, 'max', p.numero_max,
                               'casas', p.numero_casas, 'unidade', p.unidade) END,
                   'texto_max', CASE WHEN p.tipo = 'texto' THEN COALESCE(p.texto_max, 2000) END,
                   'depende', CASE WHEN p.depende_de IS NOT NULL THEN jsonb_build_object(
                                'pergunta_id', p.depende_de, 'pergunta_chave', alvo.chave,
                                'opcoes', to_jsonb(p.depende_opcoes),
                                'sem_resposta', p.depende_sem_resposta) END,
                   'opcoes', (
                     SELECT COALESCE(jsonb_agg(jsonb_build_object(
                              'id', o.id, 'chave', o.chave, 'texto', o.texto,
                              'ordem', o.ordem, 'activa', o.activa)
                              ORDER BY o.ordem, o.chave), '[]'::jsonb)
                     FROM public.levantamento_opcoes o
                     WHERE o.pergunta_id = p.id AND o.apagada_em IS NULL
                       AND (p_incluir_inactivas OR o.activa)))
                   ORDER BY p.ordem, p.chave), '[]'::jsonb)
          FROM public.levantamento_perguntas p
          LEFT JOIN public.levantamento_perguntas alvo ON alvo.id = p.depende_de
          WHERE p.seccao_id = s.id AND p.apagada_em IS NULL
            AND (p_incluir_inactivas OR p.activa)))
        ORDER BY s.ordem, s.chave), '[]'::jsonb))
    FROM public.levantamento_seccoes s
    WHERE s.organization_id = p_organization_id AND s.apagada_em IS NULL
      AND (p_incluir_inactivas OR s.activa));
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_questionario_levantamento(p_organization_id uuid, p_incluir_inactivas boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_questionario_levantamento(p_organization_id uuid, p_incluir_inactivas boolean) TO authenticated;
COMMENT ON FUNCTION public.neg_questionario_levantamento(p_organization_id uuid, p_incluir_inactivas boolean) IS 'Pessoas, Levantamento: o questionário da organização {versao, seccoes[perguntas[opcoes]]}, pela ordem. Sem inactivas (formulário) ou com inactivas (separador do Workflow, exige pessoas.config, 42501). Apagadas nunca. NG009, NG008. INVOKER (RLS). 20261226090000.';

CREATE OR REPLACE FUNCTION public.neg_reabrir_abordagem(p_organization_id uuid, p_entity_id uuid, p_motivo text DEFAULT NULL::text, p_lead_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_motivo text := NULLIF(btrim(p_motivo), '');
BEGIN
  IF char_length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'Valor inválido: motivo com mais de 1000 caracteres.' USING ERRCODE = 'NG009';
  END IF;

  RETURN public.fn_neg_mudar_abordagem(
    p_organization_id, p_entity_id, p_lead_id, NULL, NULL, v_motivo);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_reabrir_abordagem(p_organization_id uuid, p_entity_id uuid, p_motivo text, p_lead_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_reabrir_abordagem(p_organization_id uuid, p_entity_id uuid, p_motivo text, p_lead_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_reabrir_abordagem(p_organization_id uuid, p_entity_id uuid, p_motivo text, p_lead_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_reabrir_ganho(p_negocio_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_motivo text := btrim(p_motivo);
BEGIN
  IF v_motivo IS NULL OR v_motivo = '' OR char_length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'Valor inválido: razão da reabertura (1 a 1000 caracteres).' USING ERRCODE = 'NG009';
  END IF;

  -- Existe, não está no lixo, pessoas.edit com âmbito (RLS), configuração
  -- (NG008) e estado ganho (NG002).
  SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['ganho']);

  IF NOT public.fn_neg_tem_permissao_org(v_neg.organization_id, 'pessoas.reopen') THEN
    RAISE EXCEPTION 'Sem permissão para reabrir negócios ganhos.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM set_config('app.neg_origem_tipo', '', true);
  PERFORM set_config('app.neg_origem_id', '', true);
  PERFORM set_config('app.negocio_motivo_reabertura', v_motivo, true);
  PERFORM set_config('app.neg_via_funcao', 'on', true);
  UPDATE public.negocios n SET estado = 'aberto', fase_perda = NULL, motivo_perda = NULL
  WHERE n.id = v_neg.id;
  PERFORM set_config('app.neg_via_funcao', 'off', true);
  PERFORM set_config('app.negocio_motivo_reabertura', '', true);

  RETURN jsonb_build_object('mudou', true, 'estado', 'aberto');
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_reabrir_ganho(p_negocio_id uuid, p_motivo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_reabrir_ganho(p_negocio_id uuid, p_motivo text) TO authenticated;
COMMENT ON FUNCTION public.neg_reabrir_ganho(p_negocio_id uuid, p_motivo text) IS 'Pessoas: «Reabrir negócio» ganho -> aberto, com motivo e pessoas.reopen. Não mexe nos documentos nem desfaz a conversão. NG009; NG001; NG008; NG002; 42501. 20261226140000.';

CREATE OR REPLACE FUNCTION public.neg_reavaliar_negocio(p_negocio_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg      public.negocios;
  v_pos      record;
  v_conv     text;
  v_hash     text;
  v_chaves   text[];
  v_converte boolean := true;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT n.* INTO v_neg FROM public.negocios n
  WHERE n.id = p_negocio_id AND n.deleted_at IS NULL
  FOR NO KEY UPDATE;
  IF NOT FOUND OR NOT public.fn_neg_pode_editar(v_neg) THEN
    RAISE EXCEPTION 'Negócio indisponível.' USING ERRCODE = 'NG001';
  END IF;
  PERFORM public.fn_neg_exigir_config(v_neg.organization_id);
  IF v_neg.estado <> 'aberto' THEN
    RAISE EXCEPTION 'O negócio está %: esta acção não é possível.', v_neg.estado
      USING ERRCODE = 'NG002';
  END IF;

  SELECT d.tipo, d.id, d.estado, d.prova INTO v_pos FROM public.fn_neg_positivo_decisivo(v_neg) AS d;
  IF NOT FOUND OR v_pos.id IS NULL THEN
    RETURN jsonb_build_object('mudou', false, 'estado', 'aberto', 'motivo', 'sem_positivo_com_prova');
  END IF;

  v_hash := public.fn_neg_conteudo_hash(v_pos.tipo, v_pos.id);

  -- Conversão automática pela configuração: quem carrega no botão tem de poder
  -- converter (leads.convert com âmbito sobre as leads que a conversão fecha,
  -- como neg_ganhar_negocio). Sem isso dá o ganho, não converte e deixa a
  -- conversão por fazer («Converter em cliente»). Esta função exige sessão;
  -- sem sessão (portal) a conversão vem dos gatilhos, por fn_neg_ganhar_interno.
  SELECT c.conversao_ao_ganhar INTO v_conv
  FROM public.negocio_workflow_config c WHERE c.organization_id = v_neg.organization_id;
  IF v_conv = 'automatica' THEN
    v_chaves := public.crm_scope_keys('leads.convert');
    v_converte := public.fn_neg_tem_permissao_org(v_neg.organization_id, 'leads.convert')
      AND NOT EXISTS (
        SELECT 1 FROM public.anew_leads l
        WHERE l.entity_id = v_neg.entity_id
          AND l.organization_id = v_neg.organization_id
          AND l.deleted_at IS NULL
          AND lower(COALESCE(l.status::text, '')) <> 'lost'
          AND (lower(COALESCE(l.status::text, '')) IS DISTINCT FROM 'converted'
               OR l.converted_to_client_id IS NULL
               OR l.converted_at IS NULL)
          AND (l.organization_id::text || ':*' = ANY (v_chaves)
               OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_chaves)
               OR l.organization_id::text || ':' || l.created_by::text = ANY (v_chaves)) IS NOT TRUE);
  END IF;

  IF v_conv = 'automatica' AND NOT v_converte THEN
    PERFORM public.fn_neg_mudar_estado(v_neg.id, 'ganho', NULL, NULL, NULL,
      v_pos.tipo, v_pos.id, v_pos.estado, 'crm', v_pos.prova, v_hash, 'Fechar agora (reparação)');
    PERFORM public.fn_neg_anotar(v_neg.id, 'acompanhamento', NULL,
      'Conversão em cliente por fazer: quem fechou não tem a permissão de converter leads. Use «Converter em cliente».',
      v_pos.tipo, v_pos.id, v_pos.estado, 'crm', NULL, NULL);
    v_conv := 'por_fazer';
  ELSE
    v_conv := public.fn_neg_ganhar_interno(v_neg.id, v_pos.tipo, v_pos.id, v_pos.estado, 'crm',
                                            v_pos.prova, v_hash, 'Fechar agora (reparação)');
  END IF;

  RETURN jsonb_build_object('mudou', true, 'estado', 'ganho', 'origem_tipo', v_pos.tipo,
                            'origem_id', v_pos.id, 'prova', v_pos.prova, 'conversao', v_conv);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_reavaliar_negocio(p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_reavaliar_negocio(p_negocio_id uuid) TO authenticated;
COMMENT ON FUNCTION public.neg_reavaliar_negocio(p_negocio_id uuid) IS 'Pessoas: «Fechar agora» (reparação de ganhos). Num negócio aberto com um positivo decisivo COM prova, dá o ganho e converte pela configuração; a conversão automática exige leads.convert com âmbito sobre as leads da pessoa, e sem ela fica por fazer (conversao: por_fazer). Nunca dá ganho sem prova; não repara perdas. 42501 sem sessão; NG001; NG008; NG002. 20261226140000.';

CREATE OR REPLACE FUNCTION public.neg_registar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_resultado text, p_nota text DEFAULT NULL::text, p_quando timestamp with time zone DEFAULT now(), p_proxima_acao_em timestamp with time zone DEFAULT NULL::timestamp with time zone, p_negocio_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_neg    public.negocios;
  v_quando timestamptz := COALESCE(p_quando, now());
  v_nota   text := NULLIF(btrim(p_nota), '');
  v_ex     public.entity_interactions;
  v_n      int;
BEGIN
  IF p_id IS NULL OR p_resultado IS NULL OR p_resultado NOT IN
     ('atendeuInteressado', 'atendeuMaisTarde', 'naoAtendeu', 'semInteresse', 'numeroErrado') THEN
    RAISE EXCEPTION 'Valor inválido: identificador ou resultado do contacto.' USING ERRCODE = 'NG009';
  END IF;
  IF char_length(v_nota) > 2000 THEN
    RAISE EXCEPTION 'Valor inválido: nota com mais de 2000 caracteres.' USING ERRCODE = 'NG009';
  END IF;
  IF v_quando > now() + interval '5 minutes' OR v_quando < timestamptz '2000-01-01 00:00:00+00' THEN
    RAISE EXCEPTION 'Valor inválido: data do contacto.' USING ERRCODE = 'NG009';
  END IF;
  IF p_proxima_acao_em < v_quando - interval '1 day' OR p_proxima_acao_em > now() + interval '5 years' THEN
    RAISE EXCEPTION 'Valor inválido: data da próxima acção.' USING ERRCODE = 'NG009';
  END IF;

  PERFORM public.fn_neg_exigir_config(p_organization_id);

  IF NOT (public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.create')
          OR public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit')) THEN
    RAISE EXCEPTION 'Sem permissão para registar contactos nesta organização.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Ordem de bloqueio: negócio primeiro.
  IF p_negocio_id IS NOT NULL THEN
    SELECT * INTO v_neg FROM public.fn_neg_negocio_editavel(p_negocio_id, ARRAY['aberto']);
    IF v_neg.organization_id <> p_organization_id OR v_neg.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Registo indisponível para ligar.' USING ERRCODE = 'NG004';
    END IF;
  END IF;

  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);

  INSERT INTO public.entity_interactions
    (id, entity_id, organization_id, root_organization_id, interaction_type, result,
     subject, notes, interaction_at, next_action_type, next_action_date, created_by, negocio_id)
  VALUES
    (p_id, p_entity_id, p_organization_id, public.resolve_root_organization_id(p_organization_id),
     'call', p_resultado, 'Contacto', v_nota, v_quando,
     CASE WHEN p_proxima_acao_em IS NOT NULL THEN 'callback' END, p_proxima_acao_em,
     public.fn_neg_actor()::text, p_negocio_id)
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 0 THEN
    -- Reenvio: devolve o que existe, se for desta pessoa e organização.
    SELECT i.* INTO v_ex FROM public.entity_interactions i WHERE i.id = p_id;
    IF NOT FOUND OR v_ex.organization_id IS DISTINCT FROM p_organization_id
       OR v_ex.entity_id <> p_entity_id THEN
      RAISE EXCEPTION 'Registo indisponível para ligar.' USING ERRCODE = 'NG004';
    END IF;
    RETURN jsonb_build_object('contacto_id', p_id, 'mudou', false, 'ligado_a', v_ex.negocio_id);
  END IF;

  RETURN jsonb_build_object('contacto_id', p_id, 'mudou', true, 'ligado_a', p_negocio_id);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_registar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_resultado text, p_nota text, p_quando timestamp with time zone, p_proxima_acao_em timestamp with time zone, p_negocio_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_registar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_resultado text, p_nota text, p_quando timestamp with time zone, p_proxima_acao_em timestamp with time zone, p_negocio_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_registar_contacto(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_resultado text, p_nota text, p_quando timestamp with time zone, p_proxima_acao_em timestamp with time zone, p_negocio_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_registar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_texto text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'nota_id', p_id,
    'mudou', public.fn_neg_gravar_nota(p_id, p_organization_id, p_entity_id, 'Nota', p_texto, NULL));
$function$;
REVOKE ALL ON FUNCTION public.neg_registar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_texto text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_registar_nota(p_id uuid, p_organization_id uuid, p_entity_id uuid, p_texto text) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_registos_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer DEFAULT 30, p_depois jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
  SELECT public.fn_neg_ficha_seccao(p_organization_id, p_entity_id, p_tipo, p_limite, p_depois);
$function$;
REVOKE ALL ON FUNCTION public.neg_registos_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer, p_depois jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_registos_pessoa(p_organization_id uuid, p_entity_id uuid, p_tipo text, p_limite integer, p_depois jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_resultado_visita(p_visita_id uuid, p_resultado text, p_feita boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_vis      record;
  v_entity   uuid;
  v_lead     uuid;
  v_feita    boolean := COALESCE(p_feita, false);
  v_concluir boolean;
  v_mudou    boolean := false;
  v_motivo   text;
  v_n        int;
BEGIN
  IF p_visita_id IS NULL
     OR (p_resultado IS NULL AND NOT v_feita)
     OR p_resultado NOT IN ('interessado', 'aPensar', 'semInteresse', 'obraInviavel') THEN
    RAISE EXCEPTION 'Valor inválido: resultado da visita.' USING ERRCODE = 'NG009';
  END IF;

  SELECT s.organization_id, s.negocio_id, s.lead_id, s.client_id, s.visit_outcome, s.status,
         s.start_datetime, s.created_by, s.user_id
    INTO v_vis
  FROM public.schedule_items s
  WHERE s.id = p_visita_id AND s.time_off_type IS NULL AND s.vacation_id IS NULL;
  -- "Não existe", "não se vê" e "organização sem a página Pessoas": a mesma resposta.
  IF NOT FOUND
     OR NOT EXISTS (SELECT 1 FROM public.negocio_workflow_config c
                    WHERE c.organization_id = v_vis.organization_id) THEN
    RAISE EXCEPTION 'Visita indisponível.' USING ERRCODE = 'NG004';
  END IF;

  -- pessoas.edit com âmbito sobre a visita (org:*, criador ou utilizador).
  IF NOT (public.has_anew_permission(auth.uid(), 'pessoas.edit')
          AND EXISTS (SELECT 1 FROM unnest(public.crm_scope_keys('pessoas.edit')) AS k(scope_key)
                      WHERE k.scope_key = v_vis.organization_id::text || ':*'
                         OR k.scope_key = v_vis.organization_id::text || ':' || v_vis.created_by::text
                         OR k.scope_key = v_vis.organization_id::text || ':' || v_vis.user_id::text)) THEN
    RAISE EXCEPTION 'Sem permissão para alterar a visita.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Uma visita cancelada não se dá como feita nem recebe resultado (com e sem resultado).
  IF v_vis.status = 'cancelled'::public.schedule_item_status THEN
    RAISE EXCEPTION 'A visita foi cancelada: não recebe resultado.' USING ERRCODE = 'NG018';
  END IF;

  IF v_feita AND v_vis.start_datetime > now() THEN
    RAISE EXCEPTION 'Valor inválido: uma visita no futuro não pode ser dada como feita.' USING ERRCODE = 'NG009';
  END IF;

  -- status só entra no UPDATE quando muda (o trigger dos feriados corre em UPDATE OF status).
  v_concluir := v_feita AND v_vis.status <> 'completed'::public.schedule_item_status;

  IF p_resultado IS NULL THEN
    -- Só "feita": não toca no resultado nem na abordagem.
    IF v_concluir THEN
      UPDATE public.schedule_items s
      SET status = 'completed'::public.schedule_item_status
      WHERE s.id = p_visita_id;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n = 0 THEN
        RAISE EXCEPTION 'Sem permissão para alterar a visita.' USING ERRCODE = 'insufficient_privilege';
      END IF;
      v_mudou := true;
    END IF;
    RETURN jsonb_build_object('mudou', v_mudou, 'abordagem_encerrada', false,
                              'motivo_nao_encerrada', NULL);
  END IF;

  IF v_concluir THEN
    UPDATE public.schedule_items s
    SET visit_outcome = p_resultado, status = 'completed'::public.schedule_item_status
    WHERE s.id = p_visita_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  ELSIF v_vis.visit_outcome IS DISTINCT FROM p_resultado THEN
    UPDATE public.schedule_items s
    SET visit_outcome = p_resultado
    WHERE s.id = p_visita_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  ELSE
    v_n := -1;
  END IF;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'Sem permissão para alterar a visita.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_mudou := v_n = 1;

  IF p_resultado NOT IN ('semInteresse', 'obraInviavel') THEN
    RETURN jsonb_build_object('mudou', v_mudou, 'abordagem_encerrada', false,
                              'motivo_nao_encerrada', NULL);
  END IF;

  SELECT l.entity_id, l.id INTO v_entity, v_lead
  FROM public.anew_leads l
  WHERE l.id = v_vis.lead_id AND l.organization_id = v_vis.organization_id;
  IF v_entity IS NULL THEN
    SELECT c.entity_id INTO v_entity
    FROM public.anew_clients c
    WHERE c.id = v_vis.client_id AND c.organization_id = v_vis.organization_id;
  END IF;

  IF v_vis.negocio_id IS NOT NULL THEN
    v_motivo := 'visita_de_negocio';
  ELSIF v_entity IS NULL THEN
    v_motivo := 'sem_pessoa';
  ELSIF public.fn_neg_tem_negocio_aberto(v_vis.organization_id, v_entity) THEN
    v_motivo := 'negocios_abertos';
  ELSIF NOT EXISTS (SELECT 1 FROM public.anew_leads l
                    WHERE l.organization_id = v_vis.organization_id AND l.entity_id = v_entity
                      AND l.deleted_at IS NULL) THEN
    v_motivo := 'sem_lead';
  END IF;

  IF v_motivo IS NOT NULL THEN
    RETURN jsonb_build_object('mudou', v_mudou, 'abordagem_encerrada', false,
                              'motivo_nao_encerrada', v_motivo);
  END IF;

  -- A lead da visita, se ainda viva; senão a mais recente da pessoa.
  IF NOT EXISTS (SELECT 1 FROM public.anew_leads l WHERE l.id = v_lead AND l.deleted_at IS NULL) THEN
    v_lead := NULL;
  END IF;
  v_mudou := (public.fn_neg_mudar_abordagem(
    v_vis.organization_id, v_entity, v_lead, p_resultado, NULL, 'Resultado da visita')
    ->> 'mudou')::boolean OR v_mudou;

  RETURN jsonb_build_object('mudou', v_mudou, 'abordagem_encerrada', true,
                            'motivo_nao_encerrada', NULL);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_resultado_visita(p_visita_id uuid, p_resultado text, p_feita boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_resultado_visita(p_visita_id uuid, p_resultado text, p_feita boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.neg_resultado_visita(p_visita_id uuid, p_resultado text, p_feita boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.neg_resumo_pessoas(p_organization_id uuid, p_papel text DEFAULT NULL::text, p_etapa text DEFAULT NULL::text, p_pesquisa text DEFAULT NULL::text, p_ordem text DEFAULT 'recentes'::text, p_depois_de_chave text DEFAULT NULL::text, p_depois_de_id uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 50, p_atribuido_a uuid DEFAULT NULL::uuid, p_formulario_id uuid DEFAULT NULL::uuid, p_ultimo_resultado text DEFAULT NULL::text, p_voltou boolean DEFAULT NULL::boolean, p_atrasada boolean DEFAULT NULL::boolean)
 RETURNS TABLE(entity_id uuid, nome text, papel text, lead_id uuid, client_id uuid, assigned_to uuid, lead_status text, closure_result text, etapa text, negocios_abertos integer, negocios_ganhos integer, negocios_perdidos integer, fase_mais_avancada text, pronto_a_ganhar boolean, valor_em_jogo numeric, ultimo_contacto_em timestamp with time zone, proxima_visita_em timestamp with time zone, ultima_visita_feita_em timestamp with time zone, ultimo_negocio_em timestamp with time zone, por_ligar_contactos integer, por_ligar_visitas integer, por_ligar_levantamentos integer, chave_ordem text, ha_mais boolean, criado_em timestamp with time zone, qualificacao_tipo text, ultima_atividade_em timestamp with time zone, ultimo_contacto_lead_em timestamp with time zone, voltou_a_contactar boolean, origem text, origem_detalhe text, campanha_id uuid, campanha text, formulario_id uuid, formulario text, ultimo_resultado text, atrasada boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
#variable_conflict use_column
DECLARE
  v_ordem    text := COALESCE(p_ordem, 'recentes');
  v_pesquisa text := NULLIF(btrim(p_pesquisa), '');
  v_padrao   text;
  v_depois   timestamptz;
  v_momento  text;
  v_ents     uuid[];
  v_pesq     uuid[];
  v_filtro   uuid[];
  v_filtrar  boolean;
  v_conjunto boolean;
  v_pequeno  boolean;
  -- «hoje» da regra de atraso: o dia civil de Lisboa
  v_hoje     date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  IF p_organization_id IS NULL
     OR v_ordem NOT IN ('recentes', 'nome')
     OR (p_papel IS NOT NULL AND p_papel NOT IN ('lead', 'cliente'))
     OR (p_etapa IS NOT NULL AND p_etapa NOT IN ('nova', 'emContacto', 'visitaMarcada', 'qualificada', 'cliente'))
     OR p_limite IS NULL OR p_limite < 1 OR p_limite > 100
     OR (p_depois_de_chave IS NULL) <> (p_depois_de_id IS NULL)
     OR char_length(v_pesquisa) < 2 OR char_length(v_pesquisa) > 200
     OR (p_ultimo_resultado IS NOT NULL AND p_ultimo_resultado NOT IN
           ('atendeuInteressado', 'atendeuMaisTarde', 'naoAtendeu', 'semInteresse', 'numeroErrado', 'semContacto')) THEN
    RAISE EXCEPTION 'Valor inválido: organização, ordem, papel, etapa, limite (1 a 100), página, pesquisa (2 a 200 caracteres) ou resultado.'
      USING ERRCODE = 'NG009';
  END IF;

  -- D1: sem linha de configuração visível, lista vazia.
  SELECT c.momento_ganho INTO v_momento
  FROM public.negocio_workflow_config c
  WHERE c.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_pesquisa IS NOT NULL THEN
    v_padrao := '%' || replace(replace(replace(v_pesquisa, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    -- nome, email e telefone: uma vez, pela auxiliar
    -- (fn_neg_pesquisa_pessoas explica porque o nome também vai para lá)
    v_pesq := ARRAY(SELECT x.entity_id FROM public.fn_neg_pesquisa_pessoas(p_organization_id, v_pesquisa) x);
  END IF;
  IF v_ordem = 'recentes' AND p_depois_de_chave IS NOT NULL THEN
    BEGIN
      v_depois := p_depois_de_chave::timestamptz;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Valor inválido: chave da página.' USING ERRCODE = 'NG009';
    END;
  END IF;

  -- Filtro de etapa: uma vez, por conjunto, para a organização.
  IF p_etapa IS NOT NULL THEN
    v_ents := ARRAY(
      SELECT b.ent
      FROM (
        SELECT x.ent, bool_or(x.cliente) AS cliente
        FROM (
          SELECT l.entity_id AS ent, false AS cliente
          FROM public.anew_leads l
          WHERE l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
          UNION ALL
          SELECT c.entity_id, true
          FROM public.anew_clients c
          WHERE c.organization_id = p_organization_id AND c.deleted_at IS NULL
        ) x
        GROUP BY x.ent
      ) b
      LEFT JOIN (
        SELECT DISTINCT n.entity_id AS ent
        FROM public.negocios n
        WHERE n.organization_id = p_organization_id AND n.estado = 'aberto' AND n.deleted_at IS NULL
      ) na ON na.ent = b.ent
      LEFT JOIN (
        SELECT DISTINCT l.entity_id AS ent
        FROM public.schedule_items s
        JOIN public.anew_leads l ON l.id = s.lead_id
        WHERE l.organization_id = p_organization_id AND s.organization_id = p_organization_id
          AND s.status <> 'cancelled'::public.schedule_item_status
          AND s.time_off_type IS NULL AND s.vacation_id IS NULL
      ) vi ON vi.ent = b.ent
      LEFT JOIN (
        SELECT DISTINCT i.entity_id AS ent
        FROM public.entity_interactions i
        WHERE i.organization_id = p_organization_id AND i.interaction_type = 'call'
      ) co ON co.ent = b.ent
      WHERE CASE
              WHEN b.cliente THEN 'cliente'
              WHEN na.ent IS NOT NULL THEN 'qualificada'
              WHEN vi.ent IS NOT NULL THEN 'visitaMarcada'
              WHEN co.ent IS NOT NULL THEN 'emContacto'
              ELSE 'nova'
            END = p_etapa);
  END IF;

  -- Filtros novos (20261225150000): um conjunto, calculado uma vez para a
  -- organização, com a MESMA lead e o MESMO cliente que a linha mostra e as
  -- MESMAS expressões das colunas assigned_to, formulario_id,
  -- ultimo_resultado, voltou_a_contactar e atrasada (abaixo). Cada parte só
  -- corre se o seu filtro vier preenchido.
  v_filtrar := p_atribuido_a IS NOT NULL OR p_formulario_id IS NOT NULL OR p_ultimo_resultado IS NOT NULL
               OR p_voltou IS NOT NULL OR p_atrasada IS NOT NULL;
  IF v_filtrar THEN
    -- A: sem «atrasada», o conjunto vem da auxiliar, sem a RLS por linha e com
    -- as mesmas regras de acesso (fn_neg_filtro_pessoas explica). NULL: a
    -- auxiliar não se aplica e o conjunto calcula-se aqui, pela RLS, como antes.
    IF p_atrasada IS NULL THEN
      v_filtro := public.fn_neg_filtro_pessoas(p_organization_id, p_atribuido_a, p_formulario_id,
                                               p_ultimo_resultado, p_voltou);
    END IF;
    IF v_filtro IS NULL THEN
    v_filtro := ARRAY(
      SELECT b.ent
      FROM (
        -- uma só passagem pelas leads e pelos clientes da organização: por
        -- pessoa, a lead mostrada (a viva mais recente por created_at, desempate
        -- por id) e o cliente mostrado (o vivo mais antigo, desempate por id)
        SELECT COALESCE(ld.ent, cl.ent) AS ent, ld.lid, ld.lassigned, ld.lcamp, ld.lclosure, ld.lativ,
               ld.lcontacto, ld.lresultado, cl.cid, cl.cassigned
        FROM (
          SELECT DISTINCT ON (l.entity_id)
                 l.entity_id AS ent, l.id AS lid, l.assigned_to AS lassigned, l.campaign_id AS lcamp,
                 l.closure_result AS lclosure, l.last_activity_at AS lativ, l.last_contact_at AS lcontacto,
                 l.last_contact_result AS lresultado
          FROM public.anew_leads l
          WHERE l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
          ORDER BY l.entity_id, l.created_at DESC, l.id DESC
        ) ld
        FULL JOIN (
          SELECT DISTINCT ON (c.entity_id)
                 c.entity_id AS ent, c.id AS cid, c.assigned_to AS cassigned
          FROM public.anew_clients c
          WHERE c.organization_id = p_organization_id AND c.deleted_at IS NULL AND c.entity_id IS NOT NULL
          ORDER BY c.entity_id, c.created_at ASC, c.id ASC
        ) cl ON cl.ent = ld.ent
      ) b
      LEFT JOIN (
        -- chamadas: uma passagem agrupada pelas da organização
        SELECT i.entity_id AS ent, max(i.interaction_at) AS ultimo,
               (array_agg(i.result ORDER BY i.interaction_at DESC, i.id DESC))[1] AS resultado
        FROM public.entity_interactions i
        WHERE (p_ultimo_resultado IS NOT NULL OR p_voltou IS NOT NULL)
          AND i.organization_id = p_organization_id AND i.interaction_type = 'call'
        GROUP BY i.entity_id
      ) ct ON ct.ent = b.ent
      LEFT JOIN LATERAL (
        SELECT f.id AS fid
        FROM public.campaigns ca
        JOIN public.forms f ON f.id = ca.form_id
        WHERE p_formulario_id IS NOT NULL AND ca.id = b.lcamp
      ) fm ON true
      LEFT JOIN (
        -- a visita por fazer mais antiga ainda por ligar a um negócio, por
        -- pessoa: as mesmas visitas que a coluna atrasada lê em vs (pelas
        -- leads da pessoa nesta organização, todas), numa passagem agrupada
        SELECT l.entity_id AS ent, min(si.start_datetime) AS por_fazer_desde
        FROM public.schedule_items si
        JOIN public.anew_leads l ON l.id = si.lead_id
        LEFT JOIN (
          SELECT n.entity_id AS ent, max(n.created_at) AS ultimo_em
          FROM public.negocios n
          WHERE p_atrasada IS NOT NULL AND n.organization_id = p_organization_id AND n.deleted_at IS NULL
          GROUP BY n.entity_id
        ) un ON un.ent = l.entity_id
        WHERE p_atrasada IS NOT NULL
          AND l.organization_id = p_organization_id AND si.organization_id = p_organization_id
          AND si.time_off_type IS NULL AND si.vacation_id IS NULL
          AND si.negocio_id IS NULL
          AND si.status NOT IN ('cancelled'::public.schedule_item_status, 'completed'::public.schedule_item_status)
          AND si.start_datetime > COALESCE(un.ultimo_em, '-infinity'::timestamptz)
        GROUP BY l.entity_id
      ) vf ON vf.ent = b.ent
      WHERE (p_atribuido_a IS NULL OR COALESCE(b.cassigned, b.lassigned) = p_atribuido_a)
        AND (p_formulario_id IS NULL OR fm.fid = p_formulario_id)
        AND (p_ultimo_resultado IS NULL
             OR (CASE WHEN ct.ultimo IS NULL AND b.lcontacto IS NULL THEN 'semContacto'
                      WHEN b.lcontacto IS NULL OR ct.ultimo >= b.lcontacto THEN ct.resultado
                      ELSE b.lresultado::text END) = p_ultimo_resultado)
        AND (p_voltou IS NULL
             OR (b.lativ IS NOT NULL
                 AND (GREATEST(b.lcontacto, ct.ultimo) IS NULL
                      OR b.lativ > GREATEST(b.lcontacto, ct.ultimo))) = p_voltou)
        AND (p_atrasada IS NULL
             OR COALESCE(CASE WHEN b.cid IS NULL AND b.lid IS NOT NULL AND b.lclosure IS NULL THEN
                           (LEAST(public.fn_neg_proximo_contacto(p_organization_id, b.ent), vf.por_fazer_desde)
                            AT TIME ZONE 'Europe/Lisbon')::date < v_hoje END, false) = p_atrasada));
    END IF;
    v_ents := CASE WHEN p_etapa IS NULL THEN v_filtro
                   ELSE ARRAY(SELECT unnest(v_ents) INTERSECT SELECT unnest(v_filtro)) END;
  END IF;
  v_conjunto := p_etapa IS NOT NULL OR v_filtrar;
  -- B: com um conjunto pequeno, a Lista parte dele (uma sonda por pessoa, pelo
  -- índice de entity_id) em vez de percorrer as leads e os clientes da
  -- organização; as mesmas condições, a mesma ordem e a mesma chave de página.
  -- Limiar de 200 pessoas: ver DESEMPENHO no cabeçalho.
  v_pequeno := v_conjunto AND cardinality(v_ents) <= 200;

  RETURN QUERY
  WITH cand_leads_org AS (
    -- recentes: a lead mais recente de cada pessoa (a chave da pessoa), pelo
    -- índice (organization_id, list_sort_at DESC), com LIMIT antes de juntar.
    SELECT l.entity_id AS ent, l.list_sort_at AS k
    FROM public.anew_leads l
    WHERE v_ordem = 'recentes'
      AND l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.anew_leads l2
                      WHERE l2.entity_id = l.entity_id AND l2.organization_id = p_organization_id
                        AND l2.deleted_at IS NULL
                        AND (l2.list_sort_at, l2.id) > (l.list_sort_at, l.id))
      AND NOT EXISTS (SELECT 1 FROM public.anew_clients c2
                      WHERE c2.entity_id = l.entity_id AND c2.organization_id = p_organization_id
                        AND c2.deleted_at IS NULL
                        AND COALESCE(c2.updated_at, c2.created_at) > l.list_sort_at)
      AND (p_papel IS NULL
           OR (p_papel = 'cliente') = EXISTS (SELECT 1 FROM public.anew_clients c3
                                             WHERE c3.entity_id = l.entity_id
                                               AND c3.organization_id = p_organization_id
                                               AND c3.deleted_at IS NULL))
      AND NOT v_pequeno AND (NOT v_conjunto OR l.entity_id IN (SELECT unnest(v_ents)))
      AND (v_padrao IS NULL OR l.entity_id IN (SELECT unnest(v_pesq)))
      AND (p_depois_de_id IS NULL OR (l.list_sort_at, l.entity_id) < (v_depois, p_depois_de_id))
    ORDER BY l.list_sort_at DESC, l.entity_id DESC
    LIMIT p_limite + 1
  ), cand_leads_conj AS (
    -- B: o mesmo, a partir do conjunto pequeno.
    SELECT l.entity_id AS ent, l.list_sort_at AS k
    FROM (SELECT DISTINCT u.ent FROM unnest(v_ents) AS u(ent)) s
    JOIN public.anew_leads l ON l.entity_id = s.ent
    WHERE v_pequeno AND v_ordem = 'recentes'
      AND l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.anew_leads l2
                      WHERE l2.entity_id = l.entity_id AND l2.organization_id = p_organization_id
                        AND l2.deleted_at IS NULL
                        AND (l2.list_sort_at, l2.id) > (l.list_sort_at, l.id))
      AND NOT EXISTS (SELECT 1 FROM public.anew_clients c2
                      WHERE c2.entity_id = l.entity_id AND c2.organization_id = p_organization_id
                        AND c2.deleted_at IS NULL
                        AND COALESCE(c2.updated_at, c2.created_at) > l.list_sort_at)
      AND (p_papel IS NULL
           OR (p_papel = 'cliente') = EXISTS (SELECT 1 FROM public.anew_clients c3
                                             WHERE c3.entity_id = l.entity_id
                                               AND c3.organization_id = p_organization_id
                                               AND c3.deleted_at IS NULL))
      AND (v_padrao IS NULL OR l.entity_id IN (SELECT unnest(v_pesq)))
      AND (p_depois_de_id IS NULL OR (l.list_sort_at, l.entity_id) < (v_depois, p_depois_de_id))
    ORDER BY l.list_sort_at DESC, l.entity_id DESC
    LIMIT p_limite + 1
  ), cand_leads AS (
    SELECT * FROM cand_leads_org UNION ALL SELECT * FROM cand_leads_conj
  ), cand_clientes_org AS (
    -- recentes: pessoas cuja chave vem do cliente (mais recente do que todas as leads).
    SELECT c.entity_id AS ent, COALESCE(c.updated_at, c.created_at) AS k
    FROM public.anew_clients c
    WHERE v_ordem = 'recentes' AND p_papel IS DISTINCT FROM 'lead'
      AND c.organization_id = p_organization_id AND c.deleted_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM public.anew_clients c2
                      WHERE c2.entity_id = c.entity_id AND c2.organization_id = p_organization_id
                        AND c2.deleted_at IS NULL
                        AND (COALESCE(c2.updated_at, c2.created_at), c2.id)
                            > (COALESCE(c.updated_at, c.created_at), c.id))
      AND NOT EXISTS (SELECT 1 FROM public.anew_leads l2
                      WHERE l2.entity_id = c.entity_id AND l2.organization_id = p_organization_id
                        AND l2.deleted_at IS NULL
                        AND l2.list_sort_at >= COALESCE(c.updated_at, c.created_at))
      AND NOT v_pequeno AND (NOT v_conjunto OR c.entity_id IN (SELECT unnest(v_ents)))
      AND (v_padrao IS NULL OR c.entity_id IN (SELECT unnest(v_pesq)))
      AND (p_depois_de_id IS NULL
           OR (COALESCE(c.updated_at, c.created_at), c.entity_id) < (v_depois, p_depois_de_id))
    ORDER BY COALESCE(c.updated_at, c.created_at) DESC, c.entity_id DESC
    LIMIT p_limite + 1
  ), cand_clientes_conj AS (
    -- B: o mesmo, a partir do conjunto pequeno.
    SELECT c.entity_id AS ent, COALESCE(c.updated_at, c.created_at) AS k
    FROM (SELECT DISTINCT u.ent FROM unnest(v_ents) AS u(ent)) s
    JOIN public.anew_clients c ON c.entity_id = s.ent
    WHERE v_pequeno AND v_ordem = 'recentes' AND p_papel IS DISTINCT FROM 'lead'
      AND c.organization_id = p_organization_id AND c.deleted_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM public.anew_clients c2
                      WHERE c2.entity_id = c.entity_id AND c2.organization_id = p_organization_id
                        AND c2.deleted_at IS NULL
                        AND (COALESCE(c2.updated_at, c2.created_at), c2.id)
                            > (COALESCE(c.updated_at, c.created_at), c.id))
      AND NOT EXISTS (SELECT 1 FROM public.anew_leads l2
                      WHERE l2.entity_id = c.entity_id AND l2.organization_id = p_organization_id
                        AND l2.deleted_at IS NULL
                        AND l2.list_sort_at >= COALESCE(c.updated_at, c.created_at))
      AND (v_padrao IS NULL OR c.entity_id IN (SELECT unnest(v_pesq)))
      AND (p_depois_de_id IS NULL
           OR (COALESCE(c.updated_at, c.created_at), c.entity_id) < (v_depois, p_depois_de_id))
    ORDER BY COALESCE(c.updated_at, c.created_at) DESC, c.entity_id DESC
    LIMIT p_limite + 1
  ), cand_clientes AS (
    SELECT * FROM cand_clientes_org UNION ALL SELECT * FROM cand_clientes_conj
  ), cand_nome AS (
    -- nome: pessoas (leads e clientes vivos) pelo nome, com LIMIT antes dos agregados.
    SELECT x.ent, COALESCE(lower(e.display_name), '') AS nm
    FROM (
      SELECT l.entity_id AS ent
      FROM public.anew_leads l
      WHERE v_ordem = 'nome' AND p_papel IS DISTINCT FROM 'cliente' AND NOT v_pequeno
        AND l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
        AND (p_papel IS NULL OR NOT EXISTS (SELECT 1 FROM public.anew_clients c3
                                            WHERE c3.entity_id = l.entity_id
                                              AND c3.organization_id = p_organization_id
                                              AND c3.deleted_at IS NULL))
      UNION
      SELECT c.entity_id
      FROM public.anew_clients c
      WHERE v_ordem = 'nome' AND p_papel IS DISTINCT FROM 'lead' AND NOT v_pequeno
        AND c.organization_id = p_organization_id AND c.deleted_at IS NULL
      UNION
      -- B: as mesmas leads, a partir do conjunto pequeno
      SELECT l.entity_id
      FROM (SELECT DISTINCT u.ent FROM unnest(v_ents) AS u(ent)) s
      JOIN public.anew_leads l ON l.entity_id = s.ent
      WHERE v_pequeno AND v_ordem = 'nome' AND p_papel IS DISTINCT FROM 'cliente'
        AND l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
        AND (p_papel IS NULL OR NOT EXISTS (SELECT 1 FROM public.anew_clients c3
                                            WHERE c3.entity_id = l.entity_id
                                              AND c3.organization_id = p_organization_id
                                              AND c3.deleted_at IS NULL))
      UNION
      -- B: os mesmos clientes, a partir do conjunto pequeno
      SELECT c.entity_id
      FROM (SELECT DISTINCT u.ent FROM unnest(v_ents) AS u(ent)) s
      JOIN public.anew_clients c ON c.entity_id = s.ent
      WHERE v_pequeno AND v_ordem = 'nome' AND p_papel IS DISTINCT FROM 'lead'
        AND c.organization_id = p_organization_id AND c.deleted_at IS NULL
    ) x
    LEFT JOIN public.anew_entities e ON e.id = x.ent
    WHERE (NOT v_conjunto OR x.ent IN (SELECT unnest(v_ents)))
      AND (v_padrao IS NULL OR x.ent IN (SELECT unnest(v_pesq)))
      AND (p_depois_de_id IS NULL
           OR (COALESCE(lower(e.display_name), ''), x.ent) > (p_depois_de_chave, p_depois_de_id))
    ORDER BY COALESCE(lower(e.display_name), ''), x.ent
    LIMIT p_limite + 1
  ), candidatos AS (
    SELECT u.ent, u.k, NULL::text AS nm
    FROM (SELECT * FROM cand_leads UNION ALL SELECT * FROM cand_clientes) u
    UNION ALL
    SELECT n.ent, NULL::timestamptz, n.nm FROM cand_nome n
  ), pagina AS (
    SELECT cd.ent, cd.k, cd.nm,
           row_number() OVER (ORDER BY
             CASE WHEN v_ordem = 'recentes' THEN cd.k END DESC,
             CASE WHEN v_ordem = 'recentes' THEN cd.ent END DESC,
             CASE WHEN v_ordem = 'nome' THEN cd.nm END ASC,
             CASE WHEN v_ordem = 'nome' THEN cd.ent END ASC) AS rn,
           count(*) OVER () AS lidas
    FROM candidatos cd
  )
  SELECT
    pg.ent::uuid,
    e2.display_name::text,
    (CASE WHEN cl.cid IS NOT NULL THEN 'cliente' ELSE 'lead' END)::text,
    ld.lid::uuid,
    cl.cid::uuid,
    COALESCE(cl.cassigned, ld.lassigned)::uuid,
    ld.lstatus::text,
    ld.lclosure::text,
    (CASE
       WHEN cl.cid IS NOT NULL THEN 'cliente'
       WHEN COALESCE(ng.abertos, 0) > 0 THEN 'qualificada'
       WHEN COALESCE(vs.visitas_lead, 0) > 0 THEN 'visitaMarcada'
       WHEN ct.ultimo IS NOT NULL THEN 'emContacto'
       ELSE 'nova'
     END)::text,
    COALESCE(ng.abertos, 0)::integer,
    COALESCE(ng.ganhos, 0)::integer,
    COALESCE(ng.perdidos, 0)::integer,
    fs.fase::text,
    COALESCE(vl.pronto, false)::boolean,
    vl.valor::numeric,
    ct.ultimo::timestamptz,
    vs.proxima::timestamptz,
    vs.ultima_feita::timestamptz,
    ng.ultimo_em::timestamptz,
    COALESCE(ct.por_ligar, 0)::integer,
    COALESCE(vs.por_ligar, 0)::integer,
    COALESCE(lv.por_ligar, 0)::integer,
    (CASE WHEN v_ordem = 'nome' THEN COALESCE(pg.nm, '')
          ELSE to_char(pg.k AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END)::text,
    (pg.lidas > p_limite)::boolean,
    -- 20261225150000: campos novos (todos da lead mostrada, ld, salvo criado_em)
    LEAST(lds.criado_min, cl.ccriado)::timestamptz,
    ld.lqualif::text,
    ld.lativ::timestamptz,
    ld.lcontacto::timestamptz,
    (ld.lativ IS NOT NULL
     AND (GREATEST(ld.lcontacto, ct.ultimo) IS NULL
          OR ld.lativ > GREATEST(ld.lcontacto, ct.ultimo)))::boolean,
    ld.lsource::text,
    ld.lorigin::text,
    ld.lcamp::uuid,
    cp.cnome::text,
    cp.fid::uuid,
    cp.fnome::text,
    -- resultado do contacto mais recente entre as DUAS fontes: a última chamada
    -- registada (entity_interactions 'call', funções neg_*) e o último contacto
    -- guardado na lead mostrada pela página de Leads (last_contact_at e
    -- last_contact_result); em empate ganha a chamada. Nulo sem contacto em
    -- nenhuma das duas (a UI diz «Sem contacto» quando ultimo_contacto_em e
    -- ultimo_contacto_lead_em são ambos nulos) ou com um contacto sem resultado.
    (CASE WHEN ct.ultimo IS NULL AND ld.lcontacto IS NULL THEN NULL
          WHEN ld.lcontacto IS NULL OR ct.ultimo >= ld.lcontacto THEN ct.resultado
          ELSE ld.lresultado::text END)::text,
    -- atrasada: a regra do protótipo (etapaPessoa.ts, estaAtrasadaRegistos):
    -- lead não encerrada cujo próximo contacto (a chamada agendada,
    -- fn_neg_proximo_contacto, ou a visita por fazer mais antiga ainda por
    -- ligar) é anterior a hoje em Lisboa. Cliente: nunca, até haver prazo de
    -- negócio (D20).
    COALESCE(CASE WHEN cl.cid IS NULL AND ld.lid IS NOT NULL AND ld.lclosure IS NULL THEN
               (LEAST(public.fn_neg_proximo_contacto(p_organization_id, pg.ent), vs.por_fazer_desde)
                AT TIME ZONE 'Europe/Lisbon')::date < v_hoje END, false)::boolean
  FROM pagina pg
  LEFT JOIN public.anew_entities e2 ON e2.id = pg.ent
  LEFT JOIN LATERAL (
    SELECT l.id AS lid, l.status::text AS lstatus, l.closure_result AS lclosure, l.assigned_to AS lassigned,
           l.qualification_type AS lqualif, l.last_activity_at AS lativ, l.last_contact_at AS lcontacto,
           l.last_contact_result AS lresultado,
           l.source AS lsource, l.origin AS lorigin, l.campaign_id AS lcamp
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.entity_id = pg.ent AND l.deleted_at IS NULL
    ORDER BY l.created_at DESC, l.id DESC
    LIMIT 1
  ) ld ON true
  LEFT JOIN LATERAL (
    SELECT c.id AS cid, c.assigned_to AS cassigned, c.created_at AS ccriado
    FROM public.anew_clients c
    WHERE c.organization_id = p_organization_id AND c.entity_id = pg.ent AND c.deleted_at IS NULL
    ORDER BY c.created_at ASC, c.id ASC
    LIMIT 1
  ) cl ON true
  LEFT JOIN LATERAL (
    -- ids de todas as leads da pessoa (sondas por índice nas visitas)
    SELECT COALESCE(array_agg(l.id), ARRAY[]::uuid[]) AS ids,
           min(l.created_at) FILTER (WHERE l.deleted_at IS NULL) AS criado_min
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.entity_id = pg.ent
  ) lds ON true
  LEFT JOIN LATERAL (
    SELECT count(*) FILTER (WHERE n.estado = 'aberto')  AS abertos,
           count(*) FILTER (WHERE n.estado = 'ganho')   AS ganhos,
           count(*) FILTER (WHERE n.estado = 'perdido') AS perdidos,
           max(n.created_at) AS ultimo_em
    FROM public.negocios n
    WHERE n.organization_id = p_organization_id AND n.entity_id = pg.ent AND n.deleted_at IS NULL
  ) ng ON true
  LEFT JOIN LATERAL (
    SELECT CASE
      WHEN EXISTS (SELECT 1 FROM public.client_contracts cc JOIN public.negocios n ON n.id = cc.negocio_id
                   WHERE n.organization_id = p_organization_id AND n.entity_id = pg.ent
                     AND n.estado = 'aberto' AND n.deleted_at IS NULL AND cc.deleted_at IS NULL) THEN 'contrato'
      WHEN EXISTS (SELECT 1 FROM public.proposals pr JOIN public.negocios n ON n.id = pr.negocio_id
                   WHERE n.organization_id = p_organization_id AND n.entity_id = pg.ent
                     AND n.estado = 'aberto' AND n.deleted_at IS NULL
                     AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE) THEN 'proposta'
      WHEN EXISTS (SELECT 1 FROM public.quotes q JOIN public.negocios n ON n.id = q.negocio_id
                   WHERE n.organization_id = p_organization_id AND n.entity_id = pg.ent
                     AND n.estado = 'aberto' AND n.deleted_at IS NULL AND q.deleted_at IS NULL) THEN 'orcamento'
    END AS fase
  ) fs ON true
  LEFT JOIN LATERAL (
    SELECT sum(public.fn_neg_valor_negocio(n.id)) AS valor,
           bool_or(CASE
             WHEN v_momento = 'proposta_aceite' THEN EXISTS (
               SELECT 1 FROM public.proposals pr
               WHERE pr.negocio_id = n.id AND pr.status = 'accepted'
                 AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE)
             WHEN v_momento = 'contrato_assinado' THEN EXISTS (
               SELECT 1 FROM public.client_contracts cc
               WHERE cc.negocio_id = n.id AND cc.status IN ('signed', 'assinado') AND cc.deleted_at IS NULL)
             ELSE false
           END) AS pronto
    FROM public.negocios n
    WHERE n.organization_id = p_organization_id AND n.entity_id = pg.ent
      AND n.estado = 'aberto' AND n.deleted_at IS NULL
  ) vl ON true
  LEFT JOIN LATERAL (
    SELECT max(i.interaction_at) AS ultimo,
           count(*) FILTER (WHERE i.negocio_id IS NULL
                              AND i.interaction_at > COALESCE(ng.ultimo_em, '-infinity'::timestamptz)) AS por_ligar,
           (array_agg(i.result ORDER BY i.interaction_at DESC, i.id DESC))[1] AS resultado
    FROM public.entity_interactions i
    WHERE i.entity_id = pg.ent AND i.organization_id = p_organization_id AND i.interaction_type = 'call'
  ) ct ON true
  LEFT JOIN LATERAL (
    SELECT min(s.start_datetime) FILTER (
             WHERE s.start_datetime >= now()
               AND s.status NOT IN ('cancelled'::public.schedule_item_status, 'completed'::public.schedule_item_status)) AS proxima,
           max(s.start_datetime) FILTER (WHERE s.status = 'completed'::public.schedule_item_status) AS ultima_feita,
           count(*) FILTER (WHERE s.lead_id IS NOT NULL
                              AND s.status <> 'cancelled'::public.schedule_item_status) AS visitas_lead,
           count(*) FILTER (WHERE s.negocio_id IS NULL
                              AND s.status <> 'cancelled'::public.schedule_item_status
                              AND s.start_datetime > COALESCE(ng.ultimo_em, '-infinity'::timestamptz)) AS por_ligar,
           min(s.start_datetime) FILTER (
             WHERE s.negocio_id IS NULL
               AND s.status NOT IN ('cancelled'::public.schedule_item_status, 'completed'::public.schedule_item_status)
               AND s.start_datetime > COALESCE(ng.ultimo_em, '-infinity'::timestamptz)) AS por_fazer_desde
    FROM (
      -- dois ramos por índice, sem OR sobre subconsulta: pelas leads e pelo cliente
      SELECT si.start_datetime, si.status, si.lead_id, si.negocio_id
      FROM public.schedule_items si
      WHERE si.lead_id = ANY (lds.ids)
        AND si.organization_id = p_organization_id
        AND si.time_off_type IS NULL AND si.vacation_id IS NULL
      UNION ALL
      SELECT si.start_datetime, si.status, si.lead_id, si.negocio_id
      FROM public.schedule_items si
      WHERE cl.cid IS NOT NULL AND si.client_id = cl.cid
        AND (si.lead_id IS NULL OR si.lead_id <> ALL (lds.ids))
        AND si.organization_id = p_organization_id
        AND si.time_off_type IS NULL AND si.vacation_id IS NULL
    ) s
  ) vs ON true
  LEFT JOIN LATERAL (
    SELECT count(*) AS por_ligar
    FROM public.levantamentos lt
    WHERE lt.organization_id = p_organization_id AND lt.entity_id = pg.ent
      AND lt.negocio_id IS NULL AND lt.deleted_at IS NULL
      AND lt.created_at > COALESCE(ng.ultimo_em, '-infinity'::timestamptz)
  ) lv ON true
  LEFT JOIN LATERAL (
    -- origem da lead mostrada: campanha e formulário, como na ficha
    SELECT ca.name AS cnome, f.id AS fid, f.name AS fnome
    FROM public.campaigns ca
    LEFT JOIN public.forms f ON f.id = ca.form_id
    WHERE ca.id = ld.lcamp
  ) cp ON true
  WHERE pg.rn <= p_limite
  ORDER BY pg.rn;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_resumo_pessoas(p_organization_id uuid, p_papel text, p_etapa text, p_pesquisa text, p_ordem text, p_depois_de_chave text, p_depois_de_id uuid, p_limite integer, p_atribuido_a uuid, p_formulario_id uuid, p_ultimo_resultado text, p_voltou boolean, p_atrasada boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_resumo_pessoas(p_organization_id uuid, p_papel text, p_etapa text, p_pesquisa text, p_ordem text, p_depois_de_chave text, p_depois_de_id uuid, p_limite integer, p_atribuido_a uuid, p_formulario_id uuid, p_ultimo_resultado text, p_voltou boolean, p_atrasada boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_resumo_quadro(p_organization_id uuid, p_colunas text[] DEFAULT NULL::text[], p_papel text DEFAULT NULL::text, p_pesquisa text DEFAULT NULL::text, p_ordem text DEFAULT 'recentes'::text, p_depois_de_chave text DEFAULT NULL::text, p_depois_de_id uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 25)
 RETURNS TABLE(coluna text, tipo text, cartao_id uuid, entity_id uuid, nome text, papel text, lead_id uuid, client_id uuid, assigned_to uuid, negocio_id uuid, titulo text, valor numeric, pronto_a_ganhar boolean, n_orcamentos integer, proposta_status text, parado_desde timestamp with time zone, proximo_prazo_em timestamp with time zone, por_ligar_contactos integer, por_ligar_visitas integer, por_ligar_visitas_feitas integer, por_ligar_levantamentos integer, chave_ordem text, ha_mais boolean, total_coluna bigint, valor_coluna numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '5s'
AS $function$
#variable_conflict use_column
DECLARE
  k_todas    constant text[] := ARRAY['porContactar', 'contactado', 'visita', 'levantamento',
                                      'orcamento', 'proposta', 'contrato'];
  v_cols     text[];
  v_ordem    text := COALESCE(p_ordem, 'recentes');
  v_pesquisa text := NULLIF(btrim(p_pesquisa), '');
  v_padrao   text;
  v_depois   timestamptz;
  v_momento  text;
  v_quer_pes boolean;
  v_quer_neg boolean;
  v_nome_cedo boolean;
BEGIN
  IF p_organization_id IS NULL
     OR (p_colunas IS NOT NULL AND (cardinality(p_colunas) = 0 OR EXISTS (
           SELECT 1 FROM unnest(p_colunas) AS x(c) WHERE x.c IS NULL OR NOT (x.c = ANY (k_todas)))))
     OR (p_papel IS NOT NULL AND p_papel NOT IN ('lead', 'cliente'))
     OR v_ordem NOT IN ('recentes', 'nome')
     OR char_length(v_pesquisa) < 2 OR char_length(v_pesquisa) > 200
     OR p_limite IS NULL OR p_limite < 1 OR p_limite > 100
     OR (p_depois_de_chave IS NULL) <> (p_depois_de_id IS NULL) THEN
    RAISE EXCEPTION 'Valor inválido: organização, colunas, papel, ordem, pesquisa (2 a 200), limite (1 a 100) ou página.'
      USING ERRCODE = 'NG009';
  END IF;

  v_cols := ARRAY(SELECT DISTINCT x.c FROM unnest(COALESCE(p_colunas, k_todas)) AS x(c));
  IF p_depois_de_id IS NOT NULL AND (p_colunas IS NULL OR cardinality(v_cols) <> 1) THEN
    RAISE EXCEPTION 'Valor inválido: a página seguinte pede-se para uma só coluna.' USING ERRCODE = 'NG009';
  END IF;
  IF v_ordem = 'recentes' AND p_depois_de_chave IS NOT NULL THEN
    BEGIN
      v_depois := p_depois_de_chave::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      -- qualquer erro de conversão (data, fuso): página inválida
      RAISE EXCEPTION 'Valor inválido: chave da página.' USING ERRCODE = 'NG009';
    END;
  END IF;

  -- D1: sem linha de configuração visível, Quadro vazio.
  SELECT c.momento_ganho INTO v_momento
  FROM public.negocio_workflow_config c
  WHERE c.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_pesquisa IS NOT NULL THEN
    v_padrao := '%' || replace(replace(replace(v_pesquisa, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;
  v_quer_pes := v_cols && ARRAY['porContactar', 'contactado', 'visita'];
  v_quer_neg := v_cols && ARRAY['levantamento', 'orcamento', 'proposta', 'contrato'];
  v_nome_cedo := v_padrao IS NOT NULL OR v_ordem = 'nome';

  RETURN QUERY
  WITH lds AS (
    -- um só scan das leads vivas: a mais recente de cada pessoa, a chave de
    -- ordem (a maior) e todas as leads vivas da pessoa (para as visitas)
    SELECT DISTINCT ON (l.entity_id)
           l.entity_id AS ent, l.id AS lid, l.status::text AS lstatus, l.closure_result AS lclosure,
           l.assigned_to AS lassigned,
           max(COALESCE(l.list_sort_at, l.created_at)) OVER w AS k,
           array_agg(l.id) OVER w AS lids
    FROM public.anew_leads l
    WHERE l.organization_id = p_organization_id AND l.deleted_at IS NULL AND l.entity_id IS NOT NULL
    WINDOW w AS (PARTITION BY l.entity_id)
    ORDER BY l.entity_id, l.created_at DESC, l.id DESC
  ), cls AS (
    -- um só scan dos clientes vivos: o mais antigo (como o resumo) e a chave
    SELECT DISTINCT ON (c.entity_id)
           c.entity_id AS ent, c.id AS cid, c.assigned_to AS cassigned,
           max(COALESCE(c.updated_at, c.created_at)) OVER w AS k
    FROM public.anew_clients c
    WHERE c.organization_id = p_organization_id AND c.deleted_at IS NULL
    WINDOW w AS (PARTITION BY c.entity_id)
    ORDER BY c.entity_id, c.created_at ASC, c.id ASC
  ), pes AS (
    SELECT b.*
    FROM (
      SELECT e.ent,
             -- o nome só se lê aqui com pesquisa ou ordem por nome; senão só
             -- para as linhas devolvidas
             CASE WHEN v_nome_cedo THEN (SELECT en.display_name FROM public.anew_entities en
                                         WHERE en.id = e.ent) END AS nome,
             ld.lid, ld.lstatus, ld.lclosure, ld.lids, cl.cid,
             COALESCE(cl.cassigned, ld.lassigned) AS assigned,
             GREATEST(ld.k, cl.k) AS k
      FROM (SELECT x.ent FROM lds x UNION SELECT y.ent FROM cls y) e
      LEFT JOIN lds ld ON ld.ent = e.ent
      LEFT JOIN cls cl ON cl.ent = e.ent
      WHERE p_papel IS NULL OR (p_papel = 'cliente') = (cl.cid IS NOT NULL)
    ) b
    WHERE v_padrao IS NULL OR b.nome ILIKE v_padrao ESCAPE '\'
  ), ng AS (
    SELECT n.entity_id AS ent,
           count(*) FILTER (WHERE n.estado = 'aberto') AS abertos,
           count(*) AS total,
           max(n.created_at) AS ultimo_em
    FROM public.negocios n
    WHERE n.organization_id = p_organization_id AND n.deleted_at IS NULL
    GROUP BY n.entity_id
  ), cart_neg AS (
    -- um cartão por negócio aberto
    SELECT CASE
             WHEN d.tem_contrato THEN 'contrato'
             WHEN d.tem_proposta THEN 'proposta'
             WHEN d.n_orc > 0 OR d.tem_lev THEN 'orcamento'
             ELSE 'levantamento'
           END AS col,
           'negocio'::text AS tp, n.id AS cid_cartao, p.ent, p.nome, p.lid, p.cid,
           n.assigned_to AS assigned, n.id AS neg_id, n.titulo AS tit,
           d.pronto, d.n_orc::integer AS n_orc, d.prop_status,
           NULL::timestamptz AS primeira_visita,
           NULL::integer AS plc, NULL::integer AS plv, NULL::integer AS plvf, NULL::integer AS pll,
           n.created_at AS k,
           d.valor AS val
    FROM public.negocios n
    JOIN pes p ON p.ent = n.entity_id
    LEFT JOIN LATERAL (
      SELECT EXISTS (SELECT 1 FROM public.client_contracts cc
                     WHERE cc.negocio_id = n.id AND cc.deleted_at IS NULL) AS tem_contrato,
             EXISTS (SELECT 1 FROM public.proposals pr
                     WHERE pr.negocio_id = n.id AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE) AS tem_proposta,
             (SELECT count(*) FROM public.quotes q
              WHERE q.negocio_id = n.id AND q.deleted_at IS NULL) AS n_orc,
             EXISTS (SELECT 1 FROM public.levantamentos lt
                     WHERE lt.negocio_id = n.id AND lt.deleted_at IS NULL) AS tem_lev,
             (SELECT pr.status FROM public.proposals pr
              WHERE pr.negocio_id = n.id AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
              ORDER BY pr.created_at DESC, pr.id DESC LIMIT 1) AS prop_status,
             -- valor com a precedência de fn_neg_valor_negocio: a proposta mais
             -- recente não rejeitada, senão o orçamento aceite, senão o maior
             -- orçamento vivo que não esteja rejeitado nem perdido
             COALESCE(
               (SELECT pr.value::numeric FROM public.proposals pr
                WHERE pr.negocio_id = n.id AND pr.status IS DISTINCT FROM 'rejected'
                  AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE
                ORDER BY pr.created_at DESC LIMIT 1),
               (SELECT q.total::numeric FROM public.quotes q
                WHERE q.negocio_id = n.id AND q.estado = 'aceite' AND q.deleted_at IS NULL
                ORDER BY q.accepted_at DESC NULLS LAST, q.created_at DESC LIMIT 1),
               (SELECT max(q.total)::numeric FROM public.quotes q
                WHERE q.negocio_id = n.id AND q.deleted_at IS NULL
                  AND q.estado IS DISTINCT FROM 'rejeitado' AND q.estado IS DISTINCT FROM 'perdido')) AS valor,
             CASE
               WHEN v_momento = 'proposta_aceite' THEN EXISTS (
                 SELECT 1 FROM public.proposals pr
                 WHERE pr.negocio_id = n.id AND pr.status = 'accepted'
                   AND pr.deleted_at IS NULL AND pr.is_deleted IS NOT TRUE)
               WHEN v_momento = 'contrato_assinado' THEN EXISTS (
                 SELECT 1 FROM public.client_contracts cc
                 WHERE cc.negocio_id = n.id AND cc.status IN ('signed', 'assinado') AND cc.deleted_at IS NULL)
               ELSE false
             END AS pronto
    ) d ON true
    WHERE v_quer_neg
      AND n.organization_id = p_organization_id AND n.estado = 'aberto' AND n.deleted_at IS NULL
  ), cand AS (
    -- pessoas sem negócio aberto e sem abordagem encerrada
    SELECT p.*, COALESCE(g.total, 0) AS total_neg, g.ultimo_em
    FROM pes p
    LEFT JOIN ng g ON g.ent = p.ent
    WHERE v_quer_pes AND COALESCE(g.abertos, 0) = 0 AND p.lclosure IS NULL
  ), cand_l AS (
    SELECT c.ent, u.lid, c.ultimo_em FROM cand c CROSS JOIN LATERAL unnest(c.lids) AS u(lid)
  ), cand_c AS (
    -- visitas por ligar pelo cliente: só o cliente vivo mais antigo (regra do
    -- resumo e da ficha)
    SELECT c.ent, c.cid, c.ultimo_em FROM cand c WHERE c.cid IS NOT NULL
  ), ct AS (
    SELECT i.entity_id AS ent, count(*) AS n
    FROM public.entity_interactions i
    JOIN cand c ON c.ent = i.entity_id
    WHERE i.organization_id = p_organization_id AND i.interaction_type = 'call'
      AND i.negocio_id IS NULL
      AND i.interaction_at > COALESCE(c.ultimo_em, '-infinity'::timestamptz)
    GROUP BY i.entity_id
  ), vis AS (
    -- dois ramos por índice (lead_id e client_id), como neg_resumo_pessoas
    SELECT v.ent,
           count(*) FILTER (WHERE v.st <> 'cancelled'::public.schedule_item_status) AS n,
           count(*) FILTER (WHERE v.st = 'completed'::public.schedule_item_status) AS feitas,
           min(v.inicio) FILTER (WHERE v.st NOT IN ('cancelled'::public.schedule_item_status,
                                                    'completed'::public.schedule_item_status)) AS primeira
    FROM (
      SELECT x.ent, s.id, s.status AS st, s.start_datetime AS inicio
      FROM public.schedule_items s
      JOIN cand_l x ON x.lid = s.lead_id
      WHERE s.lead_id = ANY (ARRAY(SELECT y.lid FROM cand_l y))
        AND s.organization_id = p_organization_id
        AND s.time_off_type IS NULL AND s.vacation_id IS NULL AND s.negocio_id IS NULL
        AND s.start_datetime > COALESCE(x.ultimo_em, '-infinity'::timestamptz)
      UNION
      SELECT x.ent, s.id, s.status, s.start_datetime
      FROM public.schedule_items s
      JOIN cand_c x ON x.cid = s.client_id
      WHERE s.client_id = ANY (ARRAY(SELECT y.cid FROM cand_c y))
        AND s.organization_id = p_organization_id
        AND s.time_off_type IS NULL AND s.vacation_id IS NULL AND s.negocio_id IS NULL
        AND s.start_datetime > COALESCE(x.ultimo_em, '-infinity'::timestamptz)
    ) v
    GROUP BY v.ent
  ), lvs AS (
    SELECT lt.entity_id AS ent, count(*) AS n
    FROM public.levantamentos lt
    JOIN cand c ON c.ent = lt.entity_id
    WHERE lt.organization_id = p_organization_id AND lt.negocio_id IS NULL AND lt.deleted_at IS NULL
      AND lt.created_at > COALESCE(c.ultimo_em, '-infinity'::timestamptz)
    GROUP BY lt.entity_id
  ), pes_pl AS (
    SELECT c.*,
           COALESCE(ct.n, 0)::integer AS plc, COALESCE(vis.n, 0)::integer AS plv,
           COALESCE(vis.feitas, 0)::integer AS plvf, COALESCE(lvs.n, 0)::integer AS pll,
           vis.primeira,
           (c.lid IS NOT NULL AND public.fn_neg_lead_aberta(c.lstatus)) AS lead_aberta
    FROM cand c
    LEFT JOIN ct ON ct.ent = c.ent
    LEFT JOIN vis ON vis.ent = c.ent
    LEFT JOIN lvs ON lvs.ent = c.ent
  ), cart_pes AS (
    -- regra R-A
    SELECT CASE WHEN x.plv > 0 THEN 'visita' WHEN x.plc > 0 THEN 'contactado' ELSE 'porContactar' END AS col,
           'pessoa'::text AS tp, x.ent AS cid_cartao, x.ent, x.nome, x.lid, x.cid,
           x.assigned, NULL::uuid AS neg_id, NULL::text AS tit,
           NULL::boolean AS pronto, NULL::integer AS n_orc, NULL::text AS prop_status,
           x.primeira AS primeira_visita,
           x.plc, x.plv, x.plvf, x.pll,
           x.k,
           NULL::numeric AS val
    FROM pes_pl x
    WHERE (x.lead_aberta AND (x.total_neg = 0 OR x.plc + x.plv + x.pll > 0))
       OR (NOT x.lead_aberta AND x.total_neg > 0 AND x.plc + x.plv + x.pll > 0)
  ), cartoes AS (
    SELECT u.col, u.tp, u.cid_cartao, u.ent, u.nome, u.lid, u.cid, u.assigned, u.neg_id, u.tit,
           u.pronto, u.n_orc, u.prop_status, u.primeira_visita, u.plc, u.plv, u.plvf, u.pll,
           COALESCE(u.k, '1970-01-01 00:00:00+00'::timestamptz) AS k,
           CASE WHEN u.tp = 'negocio' AND u.col <> 'levantamento' THEN u.val END AS val,
           COALESCE(lower(u.nome), '') AS nm
    FROM (SELECT * FROM cart_neg UNION ALL SELECT * FROM cart_pes) u
    WHERE u.col = ANY (v_cols)
  ), totais AS (
    SELECT t.*,
           count(*) OVER (PARTITION BY t.col) AS tot_col,
           sum(t.val) OVER (PARTITION BY t.col) AS val_col
    FROM cartoes t
  ), pos AS (
    SELECT t.*,
           row_number() OVER (PARTITION BY t.col ORDER BY
             CASE WHEN v_ordem = 'recentes' THEN t.k END DESC,
             CASE WHEN v_ordem = 'recentes' THEN t.cid_cartao END DESC,
             CASE WHEN v_ordem = 'nome' THEN t.nm END ASC,
             CASE WHEN v_ordem = 'nome' THEN t.cid_cartao END ASC) AS rn,
           count(*) OVER (PARTITION BY t.col) AS restantes
    FROM totais t
    WHERE p_depois_de_id IS NULL
       OR (v_ordem = 'recentes' AND (t.k, t.cid_cartao) < (v_depois, p_depois_de_id))
       OR (v_ordem = 'nome' AND (t.nm, t.cid_cartao) > (p_depois_de_chave, p_depois_de_id))
  ), pag AS (
    SELECT q.* FROM pos q WHERE q.rn <= p_limite
  ), pc AS (
    -- próximo contacto, por conjunto, só para as pessoas da página (a mesma
    -- regra de fn_neg_proximo_contacto, usada pela ficha)
    SELECT DISTINCT ON (i.entity_id) i.entity_id AS ent, i.next_action_date
    FROM public.entity_interactions i
    WHERE i.organization_id = p_organization_id
      AND i.entity_id = ANY (ARRAY(SELECT g.ent FROM pag g WHERE g.tp = 'pessoa'))
      AND (i.interaction_type = 'call'
           OR (i.interaction_type = 'note' AND i.next_action_type = 'callback'))
    ORDER BY i.entity_id, i.interaction_at DESC, i.id DESC
  )
  SELECT
    q.col::text,
    q.tp::text,
    q.cid_cartao::uuid,
    q.ent::uuid,
    COALESCE(q.nome, (SELECT en.display_name FROM public.anew_entities en WHERE en.id = q.ent))::text,
    (CASE WHEN q.cid IS NOT NULL THEN 'cliente' ELSE 'lead' END)::text,
    q.lid::uuid,
    q.cid::uuid,
    q.assigned::uuid,
    q.neg_id::uuid,
    q.tit::text,
    q.val::numeric,
    q.pronto::boolean,
    q.n_orc::integer,
    q.prop_status::text,
    (CASE WHEN q.tp = 'negocio' AND q.col IN ('orcamento', 'proposta')
          THEN public.fn_neg_parado_desde(q.neg_id) END)::timestamptz,
    (CASE WHEN q.tp = 'pessoa' THEN LEAST(q.primeira_visita, pc.next_action_date) END)::timestamptz,
    q.plc::integer,
    q.plv::integer,
    q.plvf::integer,
    q.pll::integer,
    COALESCE(CASE WHEN v_ordem = 'nome' THEN q.nm
                  ELSE to_char(q.k AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
             '1970-01-01T00:00:00.000000Z')::text,
    (q.restantes > p_limite)::boolean,
    q.tot_col::bigint,
    q.val_col::numeric
  FROM pag q
  LEFT JOIN pc ON pc.ent = q.ent AND q.tp = 'pessoa'
  ORDER BY array_position(k_todas, q.col), q.rn;
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_resumo_quadro(p_organization_id uuid, p_colunas text[], p_papel text, p_pesquisa text, p_ordem text, p_depois_de_chave text, p_depois_de_id uuid, p_limite integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_resumo_quadro(p_organization_id uuid, p_colunas text[], p_papel text, p_pesquisa text, p_ordem text, p_depois_de_chave text, p_depois_de_id uuid, p_limite integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.neg_substituir_contacto(p_organization_id uuid, p_entity_id uuid, p_email text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid         uuid := auth.uid();
  v_actor       uuid;
  v_email       text := lower(NULLIF(btrim(p_email), ''));
  v_tel         text := NULLIF(btrim(p_telefone), '');
  v_dig         text;
  v_keys_pes    text[];
  v_keys_lead   text[];
  v_keys_cli    text[];
  v_email_antes text;
  v_tel_antes   text;
  v_tel_cc      text;
  v_email_ja    boolean := false;
  v_tel_ja      boolean := false;
  v_email_mudou boolean := false;
  v_tel_mudou   boolean := false;
  v_manter      uuid;
  v_n_prim      int;
  v_n_iguais    int;
  v_n           int;
BEGIN
  -- 1. Valores
  v_dig := regexp_replace(COALESCE(v_tel, ''), '\D', '', 'g');
  IF p_organization_id IS NULL OR p_entity_id IS NULL
     OR (v_email IS NULL AND v_tel IS NULL)
     OR (v_email IS NOT NULL AND (char_length(v_email) > 254
                                  OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'))
     OR (v_tel IS NOT NULL AND (char_length(v_tel) > 30
                                OR v_tel !~ '^\+?[0-9 ().-]+$'
                                OR char_length(v_dig) NOT BETWEEN 7 AND 15)) THEN
    RAISE EXCEPTION 'Valor inválido: organização, pessoa, email ou telefone (7 a 15 dígitos).'
      USING ERRCODE = 'NG009';
  END IF;

  -- 2. Sessão
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  -- 3. Organização do utilizador, com pessoas.view e com configuração (D1).
  v_keys_pes := public.crm_scope_keys('pessoas.view');
  IF NOT (p_organization_id IN (SELECT public.get_user_crm_org_ids(v_uid)))
     OR NOT public.has_anew_permission(v_uid, 'pessoas.view')
     OR NOT EXISTS (SELECT 1 FROM unnest(v_keys_pes) AS k(scope_key)
                    WHERE starts_with(k.scope_key, p_organization_id::text || ':')) THEN
    RAISE EXCEPTION 'Organização sem a página Pessoas activa.' USING ERRCODE = 'NG008';
  END IF;
  PERFORM public.fn_neg_exigir_config(p_organization_id);

  -- 4. Pessoa ligada, com lead ou cliente vivo, visível no âmbito de leitura,
  --    e que não é a ficha de uma organização do sistema.
  PERFORM public.fn_neg_exigir_pessoa(p_organization_id, p_entity_id);
  v_keys_lead := CASE WHEN public.has_anew_permission(v_uid, 'leads.view')
                      THEN public.crm_scope_keys('leads.view') ELSE ARRAY[]::text[] END;
  v_keys_cli  := CASE WHEN public.has_anew_permission(v_uid, 'clients.view')
                      THEN public.crm_scope_keys('clients.view') ELSE ARRAY[]::text[] END;
  IF NOT (EXISTS (SELECT 1 FROM public.anew_leads l
                  WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                    AND l.deleted_at IS NULL
                    AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
                         OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
                         OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead)))
          OR EXISTS (SELECT 1 FROM public.anew_clients c
                     WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                       AND c.deleted_at IS NULL
                       AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
                            OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
                            OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli))))
     OR EXISTS (SELECT 1 FROM public.anew_organizations o WHERE o.entity_id = p_entity_id) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 5. Editar: pessoas.edit na organização e âmbito de edição sobre a lead ou o cliente.
  v_keys_lead := CASE WHEN public.has_anew_permission(v_uid, 'leads.edit')
                      THEN public.crm_scope_keys('leads.edit') ELSE ARRAY[]::text[] END;
  v_keys_cli  := CASE WHEN public.has_anew_permission(v_uid, 'clients.edit')
                      THEN public.crm_scope_keys('clients.edit') ELSE ARRAY[]::text[] END;
  IF NOT public.fn_neg_tem_permissao_org(p_organization_id, 'pessoas.edit')
     OR NOT (EXISTS (SELECT 1 FROM public.anew_leads l
                     WHERE l.organization_id = p_organization_id AND l.entity_id = p_entity_id
                       AND l.deleted_at IS NULL
                       AND (l.organization_id::text || ':*' = ANY (v_keys_lead)
                            OR l.organization_id::text || ':' || l.assigned_to::text = ANY (v_keys_lead)
                            OR l.organization_id::text || ':' || l.created_by::text = ANY (v_keys_lead)))
             OR EXISTS (SELECT 1 FROM public.anew_clients c
                        WHERE c.organization_id = p_organization_id AND c.entity_id = p_entity_id
                          AND c.deleted_at IS NULL
                          AND (c.organization_id::text || ':*' = ANY (v_keys_cli)
                               OR c.organization_id::text || ':' || c.assigned_to::text = ANY (v_keys_cli)
                               OR c.organization_id::text || ':' || c.created_by::text = ANY (v_keys_cli)))) THEN
    RAISE EXCEPTION 'Sem permissão para editar esta pessoa.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 5b. Não escreve em contactos de uma entidade que aparece noutra organização
  --     (ligação, lead viva, cliente vivo, papel vivo, ou linha viva de uma tabela
  --     com chave estrangeira para anew_entities; ver PARTILHADA).
  IF EXISTS (SELECT 1 FROM public.anew_entity_org_links lk
             WHERE lk.entity_id = p_entity_id AND lk.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.anew_leads l
                WHERE l.entity_id = p_entity_id AND l.organization_id <> p_organization_id
                  AND l.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_clients c
                WHERE c.entity_id = p_entity_id AND c.organization_id <> p_organization_id
                  AND c.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_entity_roles er
                WHERE er.entity_id = p_entity_id AND er.organization_id <> p_organization_id
                  AND er.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.anew_contacts t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.client_contracts t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.client_portal_users t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.contact_tags t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.data_erasure_requests t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.deals t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.direct_sales t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.entity_interactions t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.form_submissions t
                WHERE (t.entity_id = p_entity_id OR t.conflicting_entity_id = p_entity_id)
                  AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.levantamentos t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.negocios t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.organization_counted_entities t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id)
     OR EXISTS (SELECT 1 FROM public.proposals t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.quotes t
                WHERE t.entity_id = p_entity_id AND t.organization_id <> p_organization_id
                  AND t.deleted_at IS NULL)
     -- a ficha de um utilizador do sistema não é uma pessoa da página
     OR EXISTS (SELECT 1 FROM public.anew_users u
                WHERE u.entity_id = p_entity_id AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;

  -- 6. Bloqueios: a pessoa, depois cada valor (sempre email antes de telefone).
  PERFORM 1 FROM public.anew_entities e WHERE e.id = p_entity_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pessoa indisponível.' USING ERRCODE = 'NG003';
  END IF;
  IF v_email IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('neg_contacto_email:' || p_organization_id::text || ':' || v_email, 0));
  END IF;
  IF v_tel IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('neg_contacto_tel:' || p_organization_id::text || ':' || right(v_dig, 7), 0));
  END IF;

  -- 7. Valor de outra pessoa da organização: recusa sem dizer de quem. Um valor
  --    que a pessoa já tem não se verifica (era dela; um duplicado antigo de
  --    outra pessoa não a impede de o manter).
  IF v_email IS NOT NULL THEN
    v_email_ja := EXISTS (SELECT 1 FROM public.anew_entity_emails em
                          WHERE em.entity_id = p_entity_id AND lower(btrim(em.email)) = v_email);
  END IF;
  IF v_tel IS NOT NULL THEN
    v_tel_ja := EXISTS (SELECT 1 FROM public.anew_entity_phones ph
                        WHERE ph.entity_id = p_entity_id
                          AND regexp_replace(ph.phone_number, '\D', '', 'g') = v_dig);
  END IF;
  IF v_email IS NOT NULL AND NOT v_email_ja AND EXISTS (
       SELECT 1 FROM public.anew_entity_emails em
       JOIN public.anew_entity_org_links lk ON lk.entity_id = em.entity_id
       WHERE lk.organization_id = p_organization_id
         AND em.entity_id <> p_entity_id
         AND lower(btrim(em.email)) = v_email) THEN
    RAISE EXCEPTION 'Contacto indisponível: pertence a outra pessoa.' USING ERRCODE = 'NG019';
  END IF;
  IF v_tel IS NOT NULL AND NOT v_tel_ja AND EXISTS (
       SELECT 1 FROM public.anew_entity_phones ph
       JOIN public.anew_entity_org_links lk ON lk.entity_id = ph.entity_id
       WHERE lk.organization_id = p_organization_id
         AND ph.entity_id <> p_entity_id
         AND char_length(regexp_replace(ph.phone_number, '\D', '', 'g')) >= 7
         AND (regexp_replace(ph.phone_number, '\D', '', 'g') LIKE '%' || v_dig
              OR v_dig LIKE '%' || regexp_replace(ph.phone_number, '\D', '', 'g'))) THEN
    RAISE EXCEPTION 'Contacto indisponível: pertence a outra pessoa.' USING ERRCODE = 'NG019';
  END IF;

  -- 8. Email: uma só linha principal, nenhuma repetida.
  SELECT em.email INTO v_email_antes
  FROM public.anew_entity_emails em
  WHERE em.entity_id = p_entity_id AND em.is_primary IS TRUE
  ORDER BY em.created_at DESC, em.id DESC
  LIMIT 1;
  IF v_email IS NOT NULL THEN
    SELECT count(*) FILTER (WHERE em.is_primary IS TRUE),
           count(*) FILTER (WHERE lower(btrim(em.email)) = v_email)
      INTO v_n_prim, v_n_iguais
    FROM public.anew_entity_emails em
    WHERE em.entity_id = p_entity_id;
    SELECT em.id INTO v_manter
    FROM public.anew_entity_emails em
    WHERE em.entity_id = p_entity_id AND lower(btrim(em.email)) = v_email
    ORDER BY em.is_primary IS TRUE DESC, em.created_at DESC, em.id DESC
    LIMIT 1;

    IF NOT (v_n_prim = 1 AND v_n_iguais = 1 AND EXISTS (
              SELECT 1 FROM public.anew_entity_emails em
              WHERE em.id = v_manter AND em.is_primary IS TRUE)) THEN
      BEGIN
        DELETE FROM public.anew_entity_emails em
        WHERE em.entity_id = p_entity_id
          AND em.id IS DISTINCT FROM v_manter
          AND (em.is_primary IS TRUE OR lower(btrim(em.email)) = v_email);
        IF v_manter IS NOT NULL THEN
          -- sem reescrever o texto: o trigger de unicidade só dispara se o email mudar
          UPDATE public.anew_entity_emails em
          SET is_primary = true
          WHERE em.id = v_manter AND em.is_primary IS NOT TRUE;
        ELSE
          INSERT INTO public.anew_entity_emails (entity_id, email, email_type, is_primary, created_by)
          VALUES (p_entity_id, v_email, 'personal', true, v_actor);
        END IF;
      EXCEPTION WHEN unique_violation THEN
        -- o trigger de unicidade (também nas outras organizações da pessoa)
        RAISE EXCEPTION 'Contacto indisponível: pertence a outra pessoa.' USING ERRCODE = 'NG019';
      END;
      v_email_mudou := true;
    END IF;
  END IF;

  -- 9. Telefone: uma só linha principal, nenhuma repetida (pelos dígitos).
  v_manter := NULL;
  SELECT ph.phone_number, ph.country_code INTO v_tel_antes, v_tel_cc
  FROM public.anew_entity_phones ph
  WHERE ph.entity_id = p_entity_id AND ph.is_primary IS TRUE
  ORDER BY ph.created_at DESC, ph.id DESC
  LIMIT 1;
  IF v_tel IS NOT NULL THEN
    SELECT count(*) FILTER (WHERE ph.is_primary IS TRUE),
           count(*) FILTER (WHERE regexp_replace(ph.phone_number, '\D', '', 'g') = v_dig)
      INTO v_n_prim, v_n_iguais
    FROM public.anew_entity_phones ph
    WHERE ph.entity_id = p_entity_id;
    SELECT ph.id INTO v_manter
    FROM public.anew_entity_phones ph
    WHERE ph.entity_id = p_entity_id
      AND regexp_replace(ph.phone_number, '\D', '', 'g') = v_dig
    ORDER BY ph.is_primary IS TRUE DESC, ph.created_at DESC, ph.id DESC
    LIMIT 1;

    IF NOT (v_n_prim = 1 AND v_n_iguais = 1 AND EXISTS (
              SELECT 1 FROM public.anew_entity_phones ph
              WHERE ph.id = v_manter AND ph.is_primary IS TRUE)) THEN
      DELETE FROM public.anew_entity_phones ph
      WHERE ph.entity_id = p_entity_id
        AND ph.id IS DISTINCT FROM v_manter
        AND (ph.is_primary IS TRUE
             OR regexp_replace(ph.phone_number, '\D', '', 'g') = v_dig);
      IF v_manter IS NOT NULL THEN
        UPDATE public.anew_entity_phones ph
        SET is_primary = true
        WHERE ph.id = v_manter AND ph.is_primary IS NOT TRUE;
      ELSE
        INSERT INTO public.anew_entity_phones
          (entity_id, phone_number, country_code, phone_type, is_primary, created_by)
        VALUES (p_entity_id, v_tel, v_tel_cc, 'mobile', true, v_actor);
      END IF;
      v_tel_mudou := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'email_antes', v_email_antes,
    'email_depois', (SELECT em.email FROM public.anew_entity_emails em
                     WHERE em.entity_id = p_entity_id AND em.is_primary IS TRUE
                     ORDER BY em.created_at DESC, em.id DESC LIMIT 1),
    'telefone_antes', v_tel_antes,
    'telefone_depois', (SELECT ph.phone_number FROM public.anew_entity_phones ph
                        WHERE ph.entity_id = p_entity_id AND ph.is_primary IS TRUE
                        ORDER BY ph.created_at DESC, ph.id DESC LIMIT 1),
    'email_mudou', v_email_mudou,
    'telefone_mudou', v_tel_mudou,
    'mudou', v_email_mudou OR v_tel_mudou);
END;
$function$;
REVOKE ALL ON FUNCTION public.neg_substituir_contacto(p_organization_id uuid, p_entity_id uuid, p_email text, p_telefone text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.neg_substituir_contacto(p_organization_id uuid, p_entity_id uuid, p_email text, p_telefone text) TO authenticated;

CREATE OR REPLACE FUNCTION public.ops_contrato_orcamento(_contrato_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote    uuid;
  v_proposta uuid;
BEGIN
  IF _contrato_id IS NULL OR to_regclass('public.client_contracts') IS NULL THEN
    RETURN NULL;
  END IF;

  EXECUTE 'SELECT quote_id, ' ||
          CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns
                             WHERE table_schema = 'public' AND table_name = 'client_contracts'
                               AND column_name = 'proposal_id')
               THEN 'proposal_id' ELSE 'NULL::uuid' END ||
          ' FROM public.client_contracts WHERE id = $1'
     INTO v_quote, v_proposta USING _contrato_id;

  IF v_quote IS NOT NULL OR v_proposta IS NULL THEN
    RETURN v_quote;
  END IF;

  IF to_regclass('public.proposal_quote_selections') IS NOT NULL THEN
    EXECUTE 'SELECT quote_id FROM public.proposal_quote_selections
              WHERE proposal_id = $1 AND selected AND quote_id IS NOT NULL LIMIT 1'
       INTO v_quote USING v_proposta;
    IF v_quote IS NOT NULL THEN RETURN v_quote; END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
              WHERE table_schema = 'public' AND table_name = 'quotes' AND column_name = 'proposal_id') THEN
    EXECUTE 'SELECT id FROM public.quotes WHERE proposal_id = $1
              ORDER BY accepted_at DESC NULLS LAST, created_at DESC LIMIT 1'
       INTO v_quote USING v_proposta;
    IF v_quote IS NOT NULL THEN RETURN v_quote; END IF;
  END IF;

  IF to_regclass('public.pipeline_links') IS NOT NULL THEN
    EXECUTE 'SELECT q.id FROM public.pipeline_links pl JOIN public.quotes q ON q.id = pl.quote_id
              WHERE pl.proposal_id = $1 ORDER BY q.created_at DESC LIMIT 1'
       INTO v_quote USING v_proposta;
  END IF;

  RETURN v_quote;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_contrato_orcamento(_contrato_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_contrato_orcamento(_contrato_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_contrato_orcamento(_contrato_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_entrar_como_verificar(p_org uuid, p_alvo uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eu       uuid;
  v_funcao   text;
  v_alvo     record;
  v_falta    text;
BEGIN
  SELECT q.utilizador_id, q.funcao INTO v_eu, v_funcao FROM public.ops_quem_sou(p_org) q;

  IF v_funcao IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Só o admin de Operações pode entrar como outra pessoa.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_alvo = v_eu THEN
    RAISE EXCEPTION 'Já estás na tua conta.';
  END IF;

  SELECT u.id, u.auth_user_id, u.email, u.name, p.funcao
    INTO v_alvo
    FROM public.anew_users u
    JOIN public.ops_utilizador_perfil p
      ON p.utilizador_id = u.id AND p.organization_id = p_org AND p.ativo
   WHERE u.id = p_alvo AND u.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Essa pessoa não tem perfil ativo de Operações nesta organização.';
  END IF;
  IF v_alvo.auth_user_id IS NULL OR coalesce(v_alvo.email, '') = '' THEN
    RAISE EXCEPTION 'Essa pessoa não tem conta de acesso (sem email/login).';
  END IF;
  IF public.ops_nivel_funcao(v_alvo.funcao) <= public.ops_nivel_funcao('admin') THEN
    RAISE EXCEPTION 'Não se entra como outro admin.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF public.is_system_admin_user(v_alvo.auth_user_id) THEN
    RAISE EXCEPTION 'Não se entra como um admin de sistema.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 4. Nada que eu não tenha. O admin de sistema tem tudo.
  IF NOT public.is_system_admin_user((SELECT auth.uid())) THEN
    SELECT string_agg(DISTINCT coalesce(o.name, ma.organization_id::text), ', ')
      INTO v_falta
      FROM public.anew_memberships ma
      LEFT JOIN public.anew_organizations o ON o.id = ma.organization_id
     WHERE ma.user_id = p_alvo AND ma.status = 'active'
       AND NOT EXISTS (
         SELECT 1 FROM public.anew_memberships me
          WHERE me.user_id = v_eu AND me.status = 'active'
            AND me.organization_id = ma.organization_id
            AND NOT EXISTS (
              SELECT 1 FROM public.anew_role_permissions rpa
               WHERE rpa.role_id = ma.role_id
                 AND NOT EXISTS (
                   SELECT 1 FROM public.anew_role_permissions rpe
                    WHERE rpe.role_id = me.role_id
                      AND rpe.permission_code = rpa.permission_code)));
    IF v_falta IS NOT NULL THEN
      RAISE EXCEPTION 'Essa pessoa tem acessos que tu não tens (em: %). Não podes entrar como ela.', v_falta
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'admin_id', v_eu,
    'alvo_id', v_alvo.id,
    'auth_user_id', v_alvo.auth_user_id,
    'email', v_alvo.email,
    'nome', v_alvo.name,
    'funcao', v_alvo.funcao);
END
$function$;
REVOKE ALL ON FUNCTION public.ops_entrar_como_verificar(p_org uuid, p_alvo uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_entrar_como_verificar(p_org uuid, p_alvo uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_entrar_como_verificar(p_org uuid, p_alvo uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_num(_t text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN replace(btrim(_t), ',', '.') ~ '^-?\d{1,12}(\.\d{1,6})?$'
              THEN replace(btrim(_t), ',', '.')::numeric END
$function$;
REVOKE ALL ON FUNCTION public.ops_num(_t text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_num(_t text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_num(_t text) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_alertas_lista(_org uuid, _obra uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tipo text, gravidade smallint, tarefa_id uuid, obra_id uuid, obra_codigo text, obra_titulo text, tarefa_nome text, pessoas uuid[], desde timestamp with time zone, minutos_atraso integer, detalhe text, atraso_id uuid, supervisor_id uuid)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH agora AS (
    SELECT (now() AT TIME ZONE 'Europe/Lisbon') AS ts,
           (now() AT TIME ZONE 'Europe/Lisbon')::date AS hoje
  ),
  ta AS (
    SELECT t.id, t.obra_id, t.nome, t.estado, t.inicio_planeado, t.fim_planeado,
           t.material_chega_em AS material, t.material_chega_nota AS material_nota,
           o.codigo, o.titulo, o.supervisor_id AS sup, COALESCE(o.hora_inicio_dia, time '08:00') AS hora,
           COALESCE((SELECT array_agg(tp.utilizador_id ORDER BY tp.atribuida_em, tp.utilizador_id)
                       FROM public.ops_obra_tarefa_pessoa tp WHERE tp.tarefa_id = t.id), '{}'::uuid[]) AS pessoas
      FROM public.ops_obra_tarefa t
      JOIN public.ops_obra o ON o.id = t.obra_id
     WHERE t.organization_id = _org
       AND (_obra IS NULL OR t.obra_id = _obra)
       AND o.estado IN ('planeada','em_curso')
       AND t.estado IN ('por_fazer','em_curso','rejeitada')
  )
  SELECT 'fim_ultrapassado'::text, 1::smallint, ta.id, ta.obra_id, ta.codigo, ta.titulo, ta.nome, ta.pessoas,
         ((ta.fim_planeado + 1)::timestamp AT TIME ZONE 'Europe/Lisbon'),
         GREATEST(0, floor(extract(epoch FROM (ag.ts - (ta.fim_planeado + 1)::timestamp)) / 60))::integer,
         'Devia ter acabado a ' || to_char(ta.fim_planeado, 'DD/MM') ||
           CASE ta.estado WHEN 'por_fazer' THEN ' e ainda nem começou'
                          WHEN 'rejeitada' THEN ' e voltou para refazer'
                          ELSE ' e ainda está em curso' END,
         NULL::uuid, ta.sup
    FROM ta CROSS JOIN agora ag
   WHERE ta.fim_planeado IS NOT NULL AND ta.fim_planeado < ag.hoje
  UNION ALL
  SELECT 'nao_iniciada'::text, 2::smallint, ta.id, ta.obra_id, ta.codigo, ta.titulo, ta.nome, ta.pessoas,
         ((ta.inicio_planeado + ta.hora) AT TIME ZONE 'Europe/Lisbon'),
         GREATEST(0, floor(extract(epoch FROM (ag.ts - (ta.inicio_planeado + ta.hora))) / 60))::integer,
         'Devia ter começado a ' || to_char(ta.inicio_planeado, 'DD/MM') || ' às ' || to_char(ta.hora, 'HH24:MI')
           || CASE WHEN cardinality(ta.pessoas) = 0 THEN ' · ninguém atribuído' ELSE '' END
           || COALESCE(' · à espera de "' || dep.nome || '"', ''),
         NULL::uuid, ta.sup
    FROM ta CROSS JOIN agora ag
    LEFT JOIN LATERAL (
      SELECT d.nome FROM public.ops_obra_tarefa_dependencia x
        JOIN public.ops_obra_tarefa d ON d.id = x.depende_de_id
       WHERE x.tarefa_id = ta.id AND d.estado NOT IN ('feita','validada')
       ORDER BY d.inicio_planeado NULLS LAST, d.nome LIMIT 1
    ) dep ON true
   WHERE public.ops_obra_atrasada_inicio(ta.estado, ta.inicio_planeado, ta.hora)
     AND NOT (ta.fim_planeado IS NOT NULL AND ta.fim_planeado < ag.hoje)
  UNION ALL
  SELECT 'material_tarde'::text, 2::smallint, ta.id, ta.obra_id, ta.codigo, ta.titulo, ta.nome, ta.pessoas,
         ((ta.inicio_planeado + ta.hora) AT TIME ZONE 'Europe/Lisbon'),
         (public.ops_obra_dias_uteis_entre_org(_org, ta.inicio_planeado, ta.material) * 480)::integer,
         'O material chega a ' || to_char(ta.material, 'DD/MM') || ', depois do início planeado ('
           || to_char(ta.inicio_planeado, 'DD/MM') || ')' || COALESCE(' · ' || ta.material_nota, ''),
         NULL::uuid, ta.sup
    FROM ta
   WHERE ta.estado = 'por_fazer' AND ta.material IS NOT NULL AND ta.inicio_planeado IS NOT NULL
     AND ta.material > ta.inicio_planeado
  UNION ALL
  SELECT 'cliente_por_avisar'::text, 3::smallint, a.tarefa_id, a.obra_id, o.codigo, o.titulo, t.nome,
         COALESCE((SELECT array_agg(tp.utilizador_id ORDER BY tp.atribuida_em, tp.utilizador_id)
                     FROM public.ops_obra_tarefa_pessoa tp WHERE tp.tarefa_id = a.tarefa_id), '{}'::uuid[]),
         a.registado_em,
         COALESCE(a.minutos_extra,
                  public.ops_obra_dias_uteis_entre_org(a.organization_id, a.fim_anterior, a.novo_fim) * o.minutos_por_dia)::integer,
         public.ops_obra_rotulo_atraso(a.motivo) || ': ' || a.contexto
           || COALESCE(' · novo fim ' || to_char(a.novo_fim, 'DD/MM'), ''),
         a.id, o.supervisor_id
    FROM public.ops_obra_tarefa_atraso a
    JOIN public.ops_obra o ON o.id = a.obra_id
    JOIN public.ops_obra_tarefa t ON t.id = a.tarefa_id
   WHERE a.organization_id = _org
     AND (_obra IS NULL OR a.obra_id = _obra)
     AND NOT a.cliente_avisado
     AND o.estado <> 'cancelada'
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_alertas_lista(_org uuid, _obra uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_alertas_lista(_org uuid, _obra uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_alertas_lista(_org uuid, _obra uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_atrasada_inicio(_estado text, _inicio date, _hora time without time zone, _agora timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    _estado = 'por_fazer' AND _inicio IS NOT NULL
    AND (_agora AT TIME ZONE 'Europe/Lisbon')
        >= (_inicio + COALESCE(_hora, time '08:00')) + interval '60 minutes',
    false)
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_atrasada_inicio(_estado text, _inicio date, _hora time without time zone, _agora timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_atrasada_inicio(_estado text, _inicio date, _hora time without time zone, _agora timestamp with time zone) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_atrasada_inicio(_estado text, _inicio date, _hora time without time zone, _agora timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_avisar_atribuicao(_obra uuid, _pessoas uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_o   record;
  v_p   uuid;
  v_eu  uuid;
  v_t   record;
  v_n   integer := 0;
BEGIN
  IF to_regclass('public.notifications') IS NULL THEN RETURN 0; END IF;
  SELECT id, organization_id, codigo, titulo, morada, estado INTO v_o FROM public.ops_obra WHERE id = _obra;
  IF NOT FOUND OR v_o.estado NOT IN ('planeada','em_curso') THEN RETURN 0; END IF;
  BEGIN
    SELECT id INTO v_eu FROM public.anew_users WHERE auth_user_id = auth.uid() LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_eu := NULL;
  END;

  FOREACH v_p IN ARRAY COALESCE(_pessoas, '{}') LOOP
    CONTINUE WHEN v_p IS NOT DISTINCT FROM v_eu;
    SELECT count(*)::int AS n,
           array_agg(t.id::text ORDER BY t.id) AS chaves,
           min(t.inicio_planeado) AS primeira,
           (array_agg(t.nome ORDER BY t.inicio_planeado NULLS LAST, t.ordem))[1:3] AS nomes
      INTO v_t
      FROM public.ops_obra_tarefa_pessoa tp
      JOIN public.ops_obra_tarefa t ON t.id = tp.tarefa_id
     WHERE tp.obra_id = _obra AND tp.utilizador_id = v_p AND t.estado IN ('por_fazer','rejeitada');
    CONTINUE WHEN COALESCE(v_t.n, 0) = 0;
    IF public.ops_obra_notificar(
         v_o.organization_id, v_p, 'operacoes_obra_tarefas', _obra,
         v_o.codigo || ': tens ' || v_t.n || CASE WHEN v_t.n = 1 THEN ' tarefa' ELSE ' tarefas' END,
         COALESCE(v_o.titulo, 'Obra')
           || COALESCE(' · ' || NULLIF(btrim(v_o.morada), ''), '')
           || COALESCE(' · a primeira a ' || to_char(v_t.primeira, 'DD/MM'), '')
           || '. ' || array_to_string(v_t.nomes, ', ')
           || CASE WHEN v_t.n > 3 THEN '…' ELSE '' END,
         '/operacao/minhas-tarefas', 'medium', v_t.chaves,
         jsonb_build_object('codigo', v_o.codigo)) IN ('novo','de_novo') THEN
      v_n := v_n + 1;
    END IF;
  END LOOP;
  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Aviso de atribuição não enviado: %', SQLERRM;
  RETURN v_n;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_avisar_atribuicao(_obra uuid, _pessoas uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_avisar_atribuicao(_obra uuid, _pessoas uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_avisar_bancada(_obra uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_o       record;
  v_skills  uuid[];
  v_t       record;
  v_chave   text;
  v_ficha   jsonb;
  v_local   text;
  v_para    uuid[];
  v_sem     boolean;
  v_med     text;
  v_msg     text;
  v_tit     text;
  v_p       uuid;
  v_ant     record;
BEGIN
  SELECT id, organization_id, codigo, titulo, morada, estado, supervisor_id INTO v_o
    FROM public.ops_obra WHERE id = _obra;
  IF NOT FOUND OR v_o.estado NOT IN ('planeada','em_curso') THEN
    RETURN '{}'::jsonb;
  END IF;

  SELECT COALESCE(array_agg(id), '{}') INTO v_skills
    FROM public.ops_skill WHERE organization_id = v_o.organization_id AND nome ILIKE 'marmor%';

  -- As tarefas de bancada que ainda vêm aí (medição, colocação…).
  SELECT count(*)::int AS n,
         min(t.inicio_planeado) AS primeira,
         max(COALESCE(t.fim_planeado, t.inicio_planeado)) AS ultima,
         string_agg(t.nome || ' a ' || to_char(t.inicio_planeado, 'DD/MM'), ', '
                    ORDER BY t.inicio_planeado, t.ordem) AS datas,
         string_agg(DISTINCT CASE WHEN t.medida IS NOT NULL AND t.medida_qt IS NOT NULL
                      THEN replace(t.medida, '_', ' ') || ' ' || trim(to_char(t.medida_qt, 'FM999990D0')) END, ', ') AS medidas,
         string_agg(t.id::text || '@' || t.inicio_planeado::text, ',' ORDER BY t.id) AS chave
    INTO v_t
    FROM public.ops_obra_tarefa t
   WHERE t.obra_id = _obra AND t.estado = 'por_fazer' AND t.inicio_planeado IS NOT NULL
     AND (t.skill_id = ANY (v_skills) OR t.nome ILIKE '%bancada%');

  IF COALESCE(v_t.n, 0) = 0 THEN
    -- Já não há bancada por fazer: o aviso deixa de fazer falta.
    PERFORM public.ops_obra_notificacoes_resolver(v_o.organization_id, 'operacoes_obra_bancada', '{}', _obra, 'sem_bancada');
    RETURN jsonb_build_object('bancada', false);
  END IF;

  v_chave := v_t.chave;
  SELECT COALESCE(array_agg(DISTINCT us.utilizador_id), '{}') INTO v_para
    FROM public.ops_utilizador_skill us
    JOIN public.ops_utilizador_perfil p ON p.utilizador_id = us.utilizador_id
                                       AND p.organization_id = v_o.organization_id AND p.ativo
   WHERE us.skill_id = ANY (v_skills);
  v_sem := cardinality(v_para) = 0;
  IF v_sem THEN
    v_para := public.ops_obra_coordenacao(_obra);
  ELSIF v_o.supervisor_id IS NOT NULL THEN
    v_para := v_para || v_o.supervisor_id;
  END IF;

  -- Já avisado com as mesmas datas e às mesmas pessoas → nada. Se há alguém
  -- novo (passou a ter a especialidade, mudou o supervisor…), avisa-se; quem
  -- já tinha o aviso aberto não o recebe duas vezes (ops_obra_notificar).
  SELECT * INTO v_ant FROM public.ops_obra_aviso WHERE obra_id = _obra AND tipo = 'bancada';
  IF FOUND AND v_ant.chave = v_chave AND v_para <@ COALESCE(v_ant.destinatarios, '{}') THEN
    RETURN jsonb_build_object('bancada', true, 'novo', false, 'enviado_em', v_ant.enviado_em);
  END IF;

  v_ficha := public.ops_obra_ficha_local_dados(_obra);
  v_local := public.ops_obra_local_resumo(v_ficha);
  v_med := v_t.medidas;

  v_tit := v_o.codigo || ': bancada ' || CASE WHEN v_t.primeira IS NOT NULL
             THEN 'a ' || to_char(v_t.primeira, 'DD/MM') ELSE 'por marcar' END;
  v_msg := COALESCE(v_o.titulo, 'Obra')
           || COALESCE(' · ' || NULLIF(btrim(v_o.morada), ''), '')
           || '. ' || v_t.datas || '.'
           || COALESCE(' Medidas: ' || v_med || '.', '')
           || COALESCE(' Local: ' || v_local || '.', '')
           || ' Preparar cortes e encomendar a pedra com antecedência.';

  IF v_sem THEN
    v_tit := v_tit || ' — ninguém com a especialidade Marmorista';
  END IF;

  FOREACH v_p IN ARRAY v_para LOOP
    PERFORM public.ops_obra_notificar(v_o.organization_id, v_p, 'operacoes_obra_bancada', _obra,
      v_tit, v_msg, '/operacao/obras/' || v_o.codigo, 'high', ARRAY[v_chave],
      jsonb_build_object('codigo', v_o.codigo, 'primeira', v_t.primeira, 'sem_especialidade', v_sem));
  END LOOP;

  INSERT INTO public.ops_obra_aviso (obra_id, tipo, organization_id, chave, enviado_em, destinatarios,
                                    sem_especialidade, detalhe)
  VALUES (_obra, 'bancada', v_o.organization_id, v_chave, now(), v_para, v_sem,
          jsonb_build_object('primeira', v_t.primeira, 'datas', v_t.datas, 'medidas', v_med, 'local', v_local))
  ON CONFLICT (obra_id, tipo) DO UPDATE
     SET chave = EXCLUDED.chave, enviado_em = EXCLUDED.enviado_em, destinatarios = EXCLUDED.destinatarios,
         sem_especialidade = EXCLUDED.sem_especialidade, detalhe = EXCLUDED.detalhe;

  RETURN jsonb_build_object('bancada', true, 'novo', true, 'para', cardinality(v_para), 'sem_especialidade', v_sem);
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Aviso da bancada não enviado: %', SQLERRM;
  RETURN jsonb_build_object('erro', SQLERRM);
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_avisar_bancada(_obra uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_avisar_bancada(_obra uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_coordenacao(_obra uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(array_agg(DISTINCT u), '{}')
    FROM (
      SELECT o.supervisor_id AS u FROM public.ops_obra o WHERE o.id = _obra AND o.supervisor_id IS NOT NULL
      UNION
      SELECT p.utilizador_id FROM public.ops_obra o
        JOIN public.ops_utilizador_perfil p ON p.organization_id = o.organization_id
       WHERE o.id = _obra AND p.ativo AND p.funcao IN ('admin','gestor')
    ) x
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_coordenacao(_obra uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_coordenacao(_obra uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_crm_tem(_tabela text, _colunas text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT to_regclass('public.' || _tabela) IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM unnest(_colunas) c(nome)
        WHERE NOT EXISTS (
          SELECT 1 FROM pg_attribute a
           WHERE a.attrelid = to_regclass('public.' || _tabela)
             AND a.attname = c.nome AND a.attnum > 0 AND NOT a.attisdropped))
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_crm_tem(_tabela text, _colunas text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_crm_tem(_tabela text, _colunas text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_dependencia_guarda()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_obra  uuid;
  v_org   uuid;
  v_obra2 uuid;
  v_nome  text;
  v_dnome text;
BEGIN
  SELECT obra_id, organization_id, nome INTO v_obra, v_org, v_nome
    FROM public.ops_obra_tarefa WHERE id = NEW.tarefa_id;
  SELECT obra_id, nome INTO v_obra2, v_dnome FROM public.ops_obra_tarefa WHERE id = NEW.depende_de_id;
  IF v_obra IS NULL OR v_obra2 IS DISTINCT FROM v_obra THEN
    RAISE EXCEPTION 'Uma tarefa só pode depender de outra da mesma obra.';
  END IF;
  NEW.obra_id := v_obra;
  NEW.organization_id := v_org;

  IF EXISTS (
    WITH RECURSIVE r(id) AS (
      SELECT NEW.depende_de_id
      UNION
      SELECT d.depende_de_id FROM public.ops_obra_tarefa_dependencia d JOIN r ON d.tarefa_id = r.id
    )
    SELECT 1 FROM r WHERE r.id = NEW.tarefa_id) THEN
    RAISE EXCEPTION '"%" depois de "%" fecharia um ciclo de dependências: nenhuma das duas poderia começar.',
      v_nome, v_dnome;
  END IF;
  RETURN NEW;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_dependencia_guarda() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_dependencia_guarda() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_dependencias_defeito_impl(_obra_id uuid, _inferir_servicos boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t       record;
  v_n     integer := 0;
  v_fase  smallint;
BEGIN
  FOR t IN
    SELECT ta.id, ta.organization_id, f.ordem AS fase, ta.orcamento_linha_id AS linha,
           ta.servico_id, ta.skill_id,
           (ta.orcamento_linha_id IS NULL AND ta.servico_id IS NULL) AS do_tipo
      FROM public.ops_obra_tarefa ta JOIN public.ops_obra_fase f ON f.id = ta.fase_id
     WHERE ta.obra_id = _obra_id
     ORDER BY f.ordem, ta.ordem, ta.criada_em
  LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia WHERE tarefa_id = t.id);

    IF t.do_tipo THEN
      -- 4. Tudo o que vem antes (as últimas de cada cadeia).
      INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
      SELECT t.id, a.id, t.organization_id, _obra_id
        FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
       WHERE a.obra_id = _obra_id AND fa.ordem < t.fase
         AND NOT EXISTS (
           SELECT 1 FROM public.ops_obra_tarefa_dependencia x
             JOIN public.ops_obra_tarefa b ON b.id = x.tarefa_id
             JOIN public.ops_obra_fase fb ON fb.id = b.fase_id
            WHERE x.depende_de_id = a.id AND b.obra_id = _obra_id AND fb.ordem < t.fase)
      ON CONFLICT DO NOTHING;
    ELSE
      IF _inferir_servicos THEN
        -- 2a. A mesma linha do orçamento, na fase anterior mais próxima.
        SELECT max(fa.ordem) INTO v_fase
          FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
         WHERE a.obra_id = _obra_id AND fa.ordem < t.fase
           AND t.linha IS NOT NULL AND a.orcamento_linha_id = t.linha;
        IF v_fase IS NOT NULL THEN
          INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
          SELECT t.id, a.id, t.organization_id, _obra_id
            FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
           WHERE a.obra_id = _obra_id AND fa.ordem = v_fase AND a.orcamento_linha_id = t.linha
             AND NOT EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia x
                               JOIN public.ops_obra_tarefa b ON b.id = x.tarefa_id
                              WHERE x.depende_de_id = a.id AND b.fase_id = a.fase_id
                                AND b.orcamento_linha_id = t.linha)
          ON CONFLICT DO NOTHING;
        ELSE
          -- 2b. A mesma especialidade ou o mesmo serviço, na fase anterior mais próxima.
          SELECT max(fa.ordem) INTO v_fase
            FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
           WHERE a.obra_id = _obra_id AND fa.ordem < t.fase
             AND ((t.skill_id IS NOT NULL AND a.skill_id = t.skill_id)
                  OR (t.servico_id IS NOT NULL AND a.servico_id = t.servico_id));
          IF v_fase IS NOT NULL THEN
            INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
            SELECT t.id, a.id, t.organization_id, _obra_id
              FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
             WHERE a.obra_id = _obra_id AND fa.ordem = v_fase
               AND ((t.skill_id IS NOT NULL AND a.skill_id = t.skill_id)
                    OR (t.servico_id IS NOT NULL AND a.servico_id = t.servico_id))
               AND NOT EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia x
                                 JOIN public.ops_obra_tarefa b ON b.id = x.tarefa_id
                                WHERE x.depende_de_id = a.id AND b.fase_id = a.fase_id
                                  AND ((t.skill_id IS NOT NULL AND b.skill_id = t.skill_id)
                                       OR (t.servico_id IS NOT NULL AND b.servico_id = t.servico_id)))
            ON CONFLICT DO NOTHING;
          END IF;
        END IF;
      END IF;

      -- 3. As tarefas do tipo de obra da fase anterior mais próxima.
      SELECT max(fa.ordem) INTO v_fase
        FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
       WHERE a.obra_id = _obra_id AND fa.ordem < t.fase
         AND a.orcamento_linha_id IS NULL AND a.servico_id IS NULL;
      IF v_fase IS NOT NULL THEN
        INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
        SELECT t.id, a.id, t.organization_id, _obra_id
          FROM public.ops_obra_tarefa a JOIN public.ops_obra_fase fa ON fa.id = a.fase_id
         WHERE a.obra_id = _obra_id AND fa.ordem = v_fase
           AND a.orcamento_linha_id IS NULL AND a.servico_id IS NULL
           AND NOT EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia x
                             JOIN public.ops_obra_tarefa b ON b.id = x.tarefa_id
                            WHERE x.depende_de_id = a.id AND b.fase_id = a.fase_id
                              AND b.orcamento_linha_id IS NULL AND b.servico_id IS NULL)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;

    IF EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia WHERE tarefa_id = t.id) THEN
      v_n := v_n + 1;
    END IF;
  END LOOP;

  -- A coluna antiga fica com a "primeira" (a que acaba mais tarde no modelo:
  -- a de fase/ordem maior), para quem ainda só lê depende_de.
  UPDATE public.ops_obra_tarefa ta
     SET depende_de = (SELECT x.depende_de_id
                         FROM public.ops_obra_tarefa_dependencia x
                         JOIN public.ops_obra_tarefa d ON d.id = x.depende_de_id
                         JOIN public.ops_obra_fase fd ON fd.id = d.fase_id
                        WHERE x.tarefa_id = ta.id
                        ORDER BY fd.ordem DESC, d.ordem DESC, d.id LIMIT 1)
   WHERE ta.obra_id = _obra_id AND ta.depende_de IS NULL
     AND EXISTS (SELECT 1 FROM public.ops_obra_tarefa_dependencia x WHERE x.tarefa_id = ta.id);

  RETURN v_n;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_dependencias_defeito_impl(_obra_id uuid, _inferir_servicos boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_dependencias_defeito_impl(_obra_id uuid, _inferir_servicos boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_dias_uteis_entre(_de date, _ate date)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN _de IS NULL OR _ate IS NULL OR _ate <= _de THEN 0
    ELSE (SELECT count(*)::integer
            FROM generate_series((_de + 1)::timestamp, _ate::timestamp, interval '1 day') d
           WHERE extract(isodow FROM d) <= 5) END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_dias_uteis_entre(_de date, _ate date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_dias_uteis_entre(_de date, _ate date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_dias_uteis_entre(_de date, _ate date) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_dias_uteis_entre_org(_org uuid, _de date, _ate date)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN _de IS NULL OR _ate IS NULL OR _ate <= _de THEN 0
    ELSE (SELECT count(*)::integer
            FROM unnest(public.ops_obra_dias_uteis_lista(_org, _de + 1, _ate - _de)) d
           WHERE d <= _ate) END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_dias_uteis_entre_org(_org uuid, _de date, _ate date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_dias_uteis_entre_org(_org uuid, _de date, _ate date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_dias_uteis_entre_org(_org uuid, _de date, _ate date) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_dias_uteis_lista(_org uuid, _d date, _n integer)
 RETURNS date[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v    date := _d;
  a    date[] := '{}';
  fer  date[] := '{}';
  rec  text[] := '{}';
  k    integer := 0;
BEGIN
  IF _org IS NOT NULL AND to_regclass('public.schedule_holidays') IS NOT NULL THEN
    EXECUTE 'SELECT COALESCE(array_agg(h.holiday_date) FILTER (WHERE NOT h.is_recurring), ''{}''),
                    COALESCE(array_agg(to_char(h.holiday_date, ''MM-DD'')) FILTER (WHERE h.is_recurring), ''{}'')
               FROM public.schedule_holidays h
              WHERE (h.organization_id = $1 OR (h.organization_id IS NULL AND upper(h.country_code) = ''PT''))
                AND (h.is_recurring OR h.holiday_date >= $2)'
       INTO fer, rec USING _org, _d;
  END IF;
  WHILE k < GREATEST(_n, 1) LOOP
    IF extract(isodow FROM v) <= 5 AND NOT (v = ANY (fer)) AND NOT (to_char(v, 'MM-DD') = ANY (rec)) THEN
      a := a || v;
      k := k + 1;
    END IF;
    v := v + 1;
  END LOOP;
  RETURN a;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_dias_uteis_lista(_org uuid, _d date, _n integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_dias_uteis_lista(_org uuid, _d date, _n integer) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_empurrar_dependentes_impl(_tarefa uuid, _fim_anterior date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org     uuid;
  v_fila    uuid[] := ARRAY[_tarefa];
  v_atual   uuid;
  v_cfim    date;
  v_cant    date;
  v_antes   jsonb := jsonb_build_object(_tarefa::text, _fim_anterior);
  v_mexidas jsonb := '{}'::jsonb;
  v_d       record;
  v_req     date;
  v_nf      date;
  v_passos  integer := 0;
BEGIN
  SELECT organization_id INTO v_org FROM public.ops_obra_tarefa WHERE id = _tarefa;
  WHILE COALESCE(array_length(v_fila, 1), 0) > 0 AND v_passos < 5000 LOOP
    v_passos := v_passos + 1;
    v_atual := v_fila[1];
    v_fila := v_fila[2:array_length(v_fila, 1)];
    SELECT COALESCE(fim_planeado, inicio_planeado) INTO v_cfim FROM public.ops_obra_tarefa WHERE id = v_atual;
    CONTINUE WHEN v_cfim IS NULL;
    v_cant := (v_antes ->> v_atual::text)::date;

    FOR v_d IN
      SELECT d.id, d.nome, d.inicio_planeado AS ini, COALESCE(d.fim_planeado, d.inicio_planeado) AS fim
        FROM public.ops_obra_tarefa_dependencia x
        JOIN public.ops_obra_tarefa d ON d.id = x.tarefa_id
       WHERE x.depende_de_id = v_atual
         AND d.estado = 'por_fazer' AND d.inicio_planeado IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM public.ops_obra_registo r WHERE r.tarefa_id = d.id)
       ORDER BY d.inicio_planeado, d.id
    LOOP
      -- Começava no dia seguinte ao fim da anterior → continua no dia
      -- seguinte ao novo fim; começava no próprio dia → no próprio dia.
      v_req := CASE WHEN v_cant IS NOT NULL AND v_d.ini > v_cant
                    THEN public.ops_obra_somar_dias_uteis_org(v_org, v_cfim, 1)
                    ELSE public.ops_obra_somar_dias_uteis_org(v_org, v_cfim, 0) END;
      CONTINUE WHEN v_d.ini >= v_req;
      v_nf := public.ops_obra_somar_dias_uteis_org(v_org, v_req,
                public.ops_obra_dias_uteis_entre_org(v_org, v_d.ini, v_d.fim));

      UPDATE public.ops_obra_tarefa
         SET inicio_original = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                    THEN inicio_planeado ELSE inicio_original END,
             fim_original    = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                    THEN fim_planeado ELSE fim_original END,
             inicio_planeado = v_req,
             fim_planeado    = v_nf,
             atualizada_em   = now()
       WHERE id = v_d.id;

      IF NOT (v_mexidas ? v_d.id::text) THEN
        v_mexidas := v_mexidas || jsonb_build_object(v_d.id::text, jsonb_build_object(
          'tarefa_id', v_d.id, 'nome', v_d.nome, 'inicio_anterior', v_d.ini, 'fim_anterior', v_d.fim));
        v_antes := v_antes || jsonb_build_object(v_d.id::text, v_d.fim);
      END IF;
      v_mexidas := jsonb_set(v_mexidas, ARRAY[v_d.id::text, 'novo_inicio'], to_jsonb(v_req));
      v_mexidas := jsonb_set(v_mexidas, ARRAY[v_d.id::text, 'novo_fim'], to_jsonb(v_nf));
      v_fila := v_fila || v_d.id;
    END LOOP;
  END LOOP;
  RETURN v_mexidas;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_empurrar_dependentes_impl(_tarefa uuid, _fim_anterior date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_empurrar_dependentes_impl(_tarefa uuid, _fim_anterior date) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_fatores(_area jsonb, _local jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'habitada',            CASE (_local->>'habitada_durante_obra') WHEN 'true' THEN 'sim' WHEN 'false' THEN 'nao' END,
    'acesso',              CASE WHEN _local->>'acesso' IN ('facil','dificil') THEN _local->>'acesso' END,
    'elevador',            CASE (_local->>'tem_elevador') WHEN 'true' THEN 'sim' WHEN 'false' THEN 'nao' END,
    'andar',               CASE WHEN public.ops_num(_local->>'piso') IS NULL THEN NULL
                                WHEN public.ops_num(_local->>'piso') <= 0 THEN 'rc'
                                WHEN public.ops_num(_local->>'piso') <= 2 THEN '1-2'
                                ELSE '3+' END,
    -- O caminho até à área (mobilada, distância) é da ÁREA (necessidade do
    -- negócio); a ficha do local só se usa se a área não disser.
    'mobilada',            CASE WHEN COALESCE(_area->>'diag_mobilada', _local->>'mobilada') IN ('pouco','medio','muito')
                                THEN COALESCE(_area->>'diag_mobilada', _local->>'mobilada') END,
    'distancia',           CASE WHEN COALESCE(_area->>'diag_distancia_entrada', _local->>'distancia_entrada') IN ('curta','media','longa')
                                THEN COALESCE(_area->>'diag_distancia_entrada', _local->>'distancia_entrada') END,
    'animais',             CASE (_local->>'animais') WHEN 'true' THEN 'sim' WHEN 'false' THEN 'nao' END,
    'janela',              CASE (_area->>'diag_janela') WHEN 'true' THEN 'sim' WHEN 'false' THEN 'nao' END,
    'local_cortes',        CASE WHEN _area->>'diag_local_cortes' IN ('na_area','varanda','fora') THEN _area->>'diag_local_cortes' END,
    'altura_revestimento', CASE WHEN _area->>'diag_altura_revestimento' IN ('20cm','60cm','120cm','teto')
                                THEN _area->>'diag_altura_revestimento' END))
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_fatores(_area jsonb, _local jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_fatores(_area jsonb, _local jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_fatores(_area jsonb, _local jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_fatores_chave(_fatores jsonb, _quais text[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(string_agg(k || '=' || (_fatores->>k), '|' ORDER BY k), '')
    FROM unnest(COALESCE(_quais, '{}')) k
   WHERE _fatores ? k
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_fatores_chave(_fatores jsonb, _quais text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_fatores_chave(_fatores jsonb, _quais text[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_fatores_chave(_fatores jsonb, _quais text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_ficha_local_dados(_obra uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_o   record;
  v_orc uuid;
  v_f   jsonb;
BEGIN
  SELECT orcamento_id, contrato_id INTO v_o FROM public.ops_obra WHERE id = _obra;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  v_orc := v_o.orcamento_id;
  IF v_orc IS NULL AND v_o.contrato_id IS NOT NULL THEN
    v_orc := public.ops_contrato_orcamento(v_o.contrato_id);
  END IF;
  IF v_orc IS NULL
     OR NOT public.ops_obra_crm_tem('anew_address_building', ARRAY['address_id'])
     OR NOT public.ops_obra_crm_tem('anew_addresses', ARRAY['id','floor'])
     OR NOT public.ops_obra_crm_tem('quotes', ARRAY['id','site_address_id']) THEN
    RETURN '{}'::jsonb;
  END IF;
  EXECUTE 'SELECT to_jsonb(b) || jsonb_build_object(''piso'', a.floor)
             FROM public.quotes q
             JOIN public.anew_address_building b ON b.address_id = q.site_address_id
             LEFT JOIN public.anew_addresses a ON a.id = q.site_address_id
            WHERE q.id = $1'
     INTO v_f USING v_orc;
  RETURN COALESCE(v_f, '{}'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN '{}'::jsonb;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_ficha_local_dados(_obra uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_ficha_local_dados(_obra uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_ids_de_servicos(_org uuid, _nomes jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v uuid[];
BEGIN
  IF to_regclass('public.services') IS NULL OR jsonb_typeof(_nomes) <> 'array' THEN
    RETURN '{}';
  END IF;
  EXECUTE 'SELECT COALESCE(array_agg(s.id), ''{}'') FROM public.services s
            WHERE btrim(s.name) IN (SELECT btrim(x) FROM jsonb_array_elements_text($2) x)
              AND NOT COALESCE(s.is_deleted, false) AND s.deleted_at IS NULL
              AND (s.organization_id = $1'
    || CASE WHEN to_regclass('public.service_organizations') IS NOT NULL
            THEN ' OR EXISTS (SELECT 1 FROM public.service_organizations so
                               WHERE so.service_id = s.id AND so.organization_id = $1)'
            ELSE '' END
    || ')'
    INTO v USING _org, _nomes;
  RETURN v;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_ids_de_servicos(_org uuid, _nomes jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_ids_de_servicos(_org uuid, _nomes jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_indisponiveis_impl(_org uuid, _ini date, _fim date)
 RETURNS TABLE(utilizador_id uuid, motivo text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ini date := COALESCE(_ini, current_date);
  v_fim date := GREATEST(COALESCE(_fim, _ini, current_date), COALESCE(_ini, current_date));
BEGIN
  IF to_regclass('public.resource_time_off') IS NOT NULL AND to_regclass('public.schedule_resources') IS NOT NULL THEN
    RETURN QUERY EXECUTE $q$
      SELECT DISTINCT sr.user_id,
             'ausência: ' || COALESCE(nullif(btrim(o.title), ''), nullif(btrim(o.reason), ''), 'indisponível')
        FROM public.resource_time_off o
        JOIN public.schedule_resources sr ON sr.id = o.resource_id
        JOIN public.ops_utilizador_perfil p ON p.utilizador_id = sr.user_id AND p.organization_id = $1
       WHERE sr.user_id IS NOT NULL
         AND COALESCE(o.approved, false)
         AND o.start_date <= $3 AND o.end_date >= $2
    $q$ USING _org, v_ini, v_fim;
  END IF;

  IF to_regclass('public.schedule_holidays') IS NOT NULL THEN
    RETURN QUERY EXECUTE $q$
      SELECT p.utilizador_id, 'feriado: ' || h.nome
        FROM (SELECT DISTINCT ON (h.name) h.name::text AS nome
                FROM public.schedule_holidays h
                JOIN generate_series($2, $3, interval '1 day') g(d) ON
                     (h.holiday_date = g.d::date
                      OR (h.is_recurring AND extract(month FROM h.holiday_date) = extract(month FROM g.d)
                                         AND extract(day FROM h.holiday_date) = extract(day FROM g.d)))
               WHERE h.organization_id = $1
                  OR (h.organization_id IS NULL AND upper(h.country_code) = 'PT')
               ORDER BY h.name) h
        CROSS JOIN public.ops_utilizador_perfil p
       WHERE p.organization_id = $1 AND p.ativo
    $q$ USING _org, v_ini, v_fim;
  END IF;

  IF to_regclass('public.pessoas_ausencias_dias') IS NOT NULL AND to_regclass('public.pessoas_contas') IS NOT NULL THEN
    RETURN QUERY EXECUTE format($q$
      SELECT DISTINCT pc.anew_user_id, 'ausência: ' || %s
        FROM public.pessoas_ausencias_dias d
        JOIN public.pessoas_contas pc
          ON pc.pessoa_id = d.pessoa_id AND pc.organization_id = d.organization_id AND pc.estado = 'activa'
        %s
       WHERE d.organization_id = $1 AND d.estado = 'aprovado'
         AND d.data BETWEEN $2 AND $3
    $q$,
      CASE WHEN to_regclass('public.hr_ausencias_tipos') IS NOT NULL THEN 'COALESCE(t.nome, ''RH'')' ELSE '''RH''' END,
      CASE WHEN to_regclass('public.hr_ausencias_tipos') IS NOT NULL
           THEN 'LEFT JOIN public.hr_ausencias_tipos t ON t.id = d.tipo_id' ELSE '' END)
    USING _org, v_ini, v_fim;
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_indisponiveis_impl(_org uuid, _ini date, _fim date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_indisponiveis_impl(_org uuid, _ini date, _fim date) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_local_resumo(_f jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT NULLIF(concat_ws(' · ',
    CASE WHEN NULLIF(btrim(_f->>'piso'), '') IS NOT NULL THEN 'piso ' || (_f->>'piso') END,
    CASE (_f->>'tem_elevador') WHEN 'true' THEN 'com elevador' WHEN 'false' THEN 'sem elevador' END,
    CASE WHEN NULLIF(_f->>'acesso', '') IS NOT NULL THEN 'acesso ' || (_f->>'acesso') END,
    CASE WHEN NULLIF(_f->>'estacionamento', '') IS NOT NULL THEN 'estacionamento ' || (_f->>'estacionamento') END,
    CASE (_f->>'habitada_durante_obra') WHEN 'true' THEN 'casa habitada' END), '')
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_local_resumo(_f jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_local_resumo(_f jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_local_resumo(_f jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_material_prazo(_org uuid, _materiais jsonb, _desde date)
 RETURNS TABLE(data date, nota text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prod uuid[];
  v_po   text := 'SELECT NULL::uuid AS product_id, NULL::date AS d WHERE false';
  v_lt   text := 'SELECT NULL::uuid AS product_id, NULL::integer AS dias WHERE false';
BEGIN
  IF jsonb_typeof(_materiais) IS DISTINCT FROM 'array' THEN
    RETURN;
  END IF;
  SELECT array_agg(DISTINCT (m->>'produto_id')::uuid) INTO v_prod
    FROM jsonb_array_elements(_materiais) m
   WHERE nullif(m->>'produto_id', '') IS NOT NULL
     AND (public.ops_num(m->>'disponivel') IS NULL
          OR public.ops_num(m->>'disponivel') < COALESCE(public.ops_num(m->>'quantidade'), 0));
  IF v_prod IS NULL THEN
    RETURN;
  END IF;

  IF public.ops_obra_crm_tem('purchase_orders', ARRAY['id','organization_id','status','deleted_at','expected_delivery'])
     AND public.ops_obra_crm_tem('purchase_order_items', ARRAY['purchase_order_id','product_id','quantity','received_quantity']) THEN
    v_po := 'SELECT poi.product_id, min(po.expected_delivery) AS d
               FROM public.purchase_orders po
               JOIN public.purchase_order_items poi ON poi.purchase_order_id = po.id
              WHERE po.organization_id = $1 AND po.deleted_at IS NULL
                AND po.status IN (''pending'', ''ordered'', ''partially_received'')
                AND po.expected_delivery IS NOT NULL AND po.expected_delivery >= $3
                AND COALESCE(poi.received_quantity, 0) < poi.quantity
                AND poi.product_id = ANY ($2)
              GROUP BY poi.product_id';
  END IF;
  IF public.ops_obra_crm_tem('item_suppliers',
       ARRAY['product_id','supplier_id','lead_time_days','is_preferred','is_active','deleted_at']) THEN
    v_lt := 'SELECT DISTINCT ON (s.product_id) s.product_id,
                    COALESCE(nullif(s.lead_time_days, 0), sp.delivery_sla_days) AS dias
               FROM public.item_suppliers s '
         || CASE WHEN public.ops_obra_crm_tem('suppliers', ARRAY['id','delivery_sla_days'])
                 THEN 'LEFT JOIN public.suppliers sp ON sp.id = s.supplier_id '
                 ELSE 'LEFT JOIN (SELECT NULL::uuid AS id, NULL::integer AS delivery_sla_days) sp ON false ' END
         || 'WHERE s.deleted_at IS NULL AND COALESCE(s.is_active, true)
                AND s.product_id = ANY ($2)
                AND COALESCE(nullif(s.lead_time_days, 0), sp.delivery_sla_days) > 0
              ORDER BY s.product_id, s.is_preferred DESC NULLS LAST,
                       COALESCE(nullif(s.lead_time_days, 0), sp.delivery_sla_days)';
  END IF;

  RETURN QUERY EXECUTE format($q$
    WITH m AS (
      SELECT DISTINCT ON ((e->>'produto_id')::uuid) (e->>'produto_id')::uuid AS pid,
             COALESCE(nullif(btrim(e->>'nome'), ''), 'Material') AS nome
        FROM jsonb_array_elements($4) e
       WHERE nullif(e->>'produto_id', '') IS NOT NULL AND (e->>'produto_id')::uuid = ANY ($2)
    ),
    po AS (%s),
    lt AS (%s),
    x AS (
      SELECT m.nome,
             COALESCE(po.d, $3 + lt.dias) AS d,
             CASE WHEN po.d IS NOT NULL THEN 'encomenda prevista para ' || to_char(po.d, 'DD/MM')
                  ELSE 'prazo do fornecedor de ' || lt.dias || ' dias' END AS porque
        FROM m LEFT JOIN po ON po.product_id = m.pid LEFT JOIN lt ON lt.product_id = m.pid
       WHERE po.d IS NOT NULL OR lt.dias IS NOT NULL
    )
    SELECT max(x.d), left(string_agg(x.nome || ': ' || x.porque, ' · ' ORDER BY x.d DESC, x.nome), 500)
      FROM x HAVING count(*) > 0 $q$, v_po, v_lt)
  USING _org, v_prod, _desde, _materiais;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_material_prazo(_org uuid, _materiais jsonb, _desde date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_material_prazo(_org uuid, _materiais jsonb, _desde date) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_medidas(_area jsonb, _ref jsonb, _mult numeric DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  a      jsonb := COALESCE(_area, '{}'::jsonb);
  r      jsonb := COALESCE(_ref, '{}'::jsonb);
  m      numeric := GREATEST(COALESCE(_mult, 1), 0);
  v      jsonb := '{}'::jsonb;
  pav    numeric;
  par    numeric;
  alt    numeric;
  per    numeric;
  k      text;
  num    numeric;
BEGIN
  pav := COALESCE(public.ops_num(a->>'diag_m2_pavimento'), public.ops_num(a->>'diag_area_m2'));
  per := public.ops_num(a->>'diag_perimetro_m');
  alt := CASE a->>'diag_altura_revestimento'
           WHEN '20cm' THEN 0.2 WHEN '60cm' THEN 0.6 WHEN '120cm' THEN 1.2
           WHEN 'teto' THEN COALESCE(public.ops_num(a->>'diag_pe_direito_m'), 2.5) END;
  IF per IS NOT NULL AND alt IS NOT NULL THEN
    par := round(per * alt, 2);
  END IF;

  IF pav IS NOT NULL THEN v := v || jsonb_build_object('m2_pavimento', pav); END IF;
  IF par IS NOT NULL THEN v := v || jsonb_build_object('m2_parede', par); END IF;
  IF public.ops_num(a->>'diag_pontos_agua') IS NOT NULL THEN
    v := v || jsonb_build_object('pontos_agua', public.ops_num(a->>'diag_pontos_agua'));
  END IF;
  IF public.ops_num(a->>'diag_pontos_eletricos') IS NOT NULL THEN
    v := v || jsonb_build_object('pontos_eletricos', public.ops_num(a->>'diag_pontos_eletricos'));
  END IF;

  -- O que faltar, da referência do pacote (× qt).
  FOR k IN SELECT unnest(ARRAY['m2_pavimento','m2_parede','pontos_agua','pontos_eletricos','pecas_sanitarias',
                               'acessorios','modulos','eletrodomesticos','ml_bancada']) LOOP
    num := public.ops_num(r->>k);
    IF NOT v ? k AND num IS NOT NULL THEN
      v := v || jsonb_build_object(k, round(num * m, 2));
    END IF;
  END LOOP;

  IF v ? 'm2_pavimento' OR v ? 'm2_parede' THEN
    v := v || jsonb_build_object('m2_total',
      COALESCE((v->>'m2_pavimento')::numeric, 0) + COALESCE((v->>'m2_parede')::numeric, 0));
  ELSIF public.ops_num(r->>'m2_total') IS NOT NULL THEN
    v := v || jsonb_build_object('m2_total', round(public.ops_num(r->>'m2_total') * m, 2));
  END IF;
  RETURN v;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_medidas(_area jsonb, _ref jsonb, _mult numeric) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_medidas(_area jsonb, _ref jsonb, _mult numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_medidas(_area jsonb, _ref jsonb, _mult numeric) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_minuto_apos_espera(_dias date[], _hora time without time zone, _mpd integer, _m bigint, _horas numeric)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  di   integer;
  off  integer;
  ts   timestamp;
  t    timestamp;
  dt   date;
  tod  interval;
  i    integer;
  n    integer := COALESCE(array_length(_dias, 1), 0);
BEGIN
  IF COALESCE(_horas, 0) <= 0 OR n = 0 THEN
    RETURN _m;
  END IF;
  IF _m <= 0 THEN
    ts := _dias[1] + _hora;
  ELSE
    di := ((_m - 1) / _mpd)::integer;
    off := (_m - di::bigint * _mpd)::integer;
    IF di + 1 > n THEN
      RETURN _m + ceil(_horas / 24.0)::bigint * _mpd;
    END IF;
    ts := _dias[di + 1] + _hora + make_interval(mins => off);
  END IF;
  t := ts + make_interval(secs => (_horas * 3600)::double precision);
  dt := t::date;

  i := NULL;
  FOR k IN 1 .. n LOOP
    IF _dias[k] >= dt THEN i := k; EXIT; END IF;
  END LOOP;
  IF i IS NULL THEN
    RETURN _m + ceil(_horas / 24.0)::bigint * _mpd;   -- para lá do horizonte: aproximação
  END IF;
  IF _dias[i] > dt THEN
    RETURN (i - 1)::bigint * _mpd;                     -- não é dia útil: o próximo, de manhã
  END IF;
  tod := t - dt::timestamp;
  IF tod <= _hora::interval THEN
    RETURN (i - 1)::bigint * _mpd;                     -- antes de o dia começar
  END IF;
  IF tod >= _hora::interval + make_interval(mins => _mpd) THEN
    RETURN i::bigint * _mpd;                           -- depois de o dia acabar: o dia útil seguinte
  END IF;
  RETURN (i - 1)::bigint * _mpd + ceil(extract(epoch FROM (tod - _hora::interval)) / 60.0)::bigint;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_minuto_apos_espera(_dias date[], _hora time without time zone, _mpd integer, _m bigint, _horas numeric) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_minuto_apos_espera(_dias date[], _hora time without time zone, _mpd integer, _m bigint, _horas numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_minuto_apos_espera(_dias date[], _hora time without time zone, _mpd integer, _m bigint, _horas numeric) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_notificacoes_resolver(_org uuid, _tipo text, _manter uuid[], _obra uuid DEFAULT NULL::uuid, _motivo text DEFAULT 'resolvido'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  n integer := 0;
BEGIN
  IF to_regclass('public.notifications') IS NULL THEN RETURN 0; END IF;
  UPDATE public.notifications
     SET is_resolved = true, resolved_at = now(), resolved_reason = _motivo
   WHERE organization_id = _org AND type = _tipo AND entity_type = 'ops_obra'
     AND NOT is_resolved AND data->>'modulo' = 'operacoes'
     AND (_obra IS NULL OR entity_id = _obra)
     AND NOT (entity_id = ANY (COALESCE(_manter, '{}')));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Avisos não resolvidos (%): %', _tipo, SQLERRM;
  RETURN 0;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_notificacoes_resolver(_org uuid, _tipo text, _manter uuid[], _obra uuid, _motivo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_notificacoes_resolver(_org uuid, _tipo text, _manter uuid[], _obra uuid, _motivo text) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_notificar(_org uuid, _utilizador uuid, _tipo text, _obra uuid, _titulo text, _mensagem text, _link text, _prioridade text, _chaves text[], _dados jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auth   uuid;
  v_ant    record;
  v_chaves text[] := COALESCE((SELECT array_agg(DISTINCT c ORDER BY c) FROM unnest(_chaves) c WHERE c IS NOT NULL), '{}');
  v_dados  jsonb;
  v_novas  boolean;
BEGIN
  IF to_regclass('public.notifications') IS NULL OR _utilizador IS NULL OR _obra IS NULL THEN
    RETURN 'sem_sino';
  END IF;
  SELECT auth_user_id INTO v_auth FROM public.anew_users WHERE id = _utilizador;
  IF v_auth IS NULL THEN
    RETURN 'sem_sino';   -- existe em Operações mas não entra na aplicação
  END IF;
  -- Só a equipa: nunca um cliente do CRM (membership role_is_client) nem
  -- quem não tem perfil ativo em Operações nesta organização.
  IF NOT EXISTS (SELECT 1 FROM public.ops_utilizador_perfil p
                  WHERE p.organization_id = _org AND p.utilizador_id = _utilizador AND p.ativo) THEN
    RETURN 'fora_da_equipa';
  END IF;
  IF public.ops_obra_crm_tem('anew_memberships', ARRAY['user_id','organization_id','role_is_client']) THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.anew_memberships m
                             WHERE m.user_id = $1 AND m.organization_id = $2 AND m.role_is_client)'
       INTO v_novas USING _utilizador, _org;
    IF v_novas THEN
      RETURN 'cliente';
    END IF;
  END IF;

  v_dados := COALESCE(_dados, '{}'::jsonb)
             || jsonb_build_object('modulo', 'operacoes', 'obra_id', _obra, 'chaves', to_jsonb(v_chaves));

  SELECT id, is_dismissed, title, message, data INTO v_ant
    FROM public.notifications
   WHERE user_id = v_auth AND type = _tipo AND entity_id = _obra AND NOT is_resolved
   ORDER BY created_at DESC
   LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.notifications
      (user_id, organization_id, kind, type, title, message, link, entity_type, entity_id, priority, data)
    VALUES
      (v_auth, _org, 'notification', _tipo, _titulo, _mensagem, _link, 'ops_obra', _obra,
       COALESCE(_prioridade, 'medium'), v_dados);
    RETURN 'novo';
  END IF;

  v_novas := EXISTS (
    SELECT 1 FROM unnest(v_chaves) c
     WHERE NOT (COALESCE(v_ant.data->'chaves', '[]'::jsonb) ? c));

  IF v_novas AND v_ant.is_dismissed THEN
    -- Fechou o anterior; isto é coisa nova → um aviso novo.
    UPDATE public.notifications
       SET is_resolved = true, resolved_at = now(), resolved_reason = 'substituido'
     WHERE id = v_ant.id;
    INSERT INTO public.notifications
      (user_id, organization_id, kind, type, title, message, link, entity_type, entity_id, priority, data)
    VALUES
      (v_auth, _org, 'notification', _tipo, _titulo, _mensagem, _link, 'ops_obra', _obra,
       COALESCE(_prioridade, 'medium'), v_dados);
    RETURN 'de_novo';
  ELSIF v_novas THEN
    UPDATE public.notifications
       SET title = _titulo, message = _mensagem, link = _link, priority = COALESCE(_prioridade, priority),
           data = v_dados, is_read = false, read_at = NULL, created_at = now()
     WHERE id = v_ant.id;
    RETURN 'de_novo';
  ELSIF v_ant.title IS DISTINCT FROM _titulo OR v_ant.message IS DISTINCT FROM _mensagem
        OR v_ant.data IS DISTINCT FROM v_dados THEN
    UPDATE public.notifications
       SET title = _titulo, message = _mensagem, link = _link, data = v_dados
     WHERE id = v_ant.id;
    RETURN 'atualizado';
  END IF;
  RETURN 'igual';
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Aviso não enviado (%): %', _tipo, SQLERRM;
  RETURN 'sem_sino';
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_notificar(_org uuid, _utilizador uuid, _tipo text, _obra uuid, _titulo text, _mensagem text, _link text, _prioridade text, _chaves text[], _dados jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_notificar(_org uuid, _utilizador uuid, _tipo text, _obra uuid, _titulo text, _mensagem text, _link text, _prioridade text, _chaves text[], _dados jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_passo_do_pacote(_obra uuid, _exp jsonb, _ctx text, _chave text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.id
    FROM jsonb_array_elements(COALESCE(_exp, '[]'::jsonb)) x
    JOIN public.ops_obra_tarefa t ON t.obra_id = _obra AND t.ordem = 1000 + (x->>'ordem')::integer
   WHERE COALESCE((x->>'pacote')::boolean, false)
     AND x->>'contexto' = _ctx AND x->>'chave' = _chave
   ORDER BY (x->>'ordem')::integer
   LIMIT 1
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_passo_do_pacote(_obra uuid, _exp jsonb, _ctx text, _chave text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_passo_do_pacote(_obra uuid, _exp jsonb, _ctx text, _chave text) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_pessoas_livres_impl(_org uuid, _ini date, _fim date, _excluir uuid DEFAULT NULL::uuid)
 RETURNS TABLE(utilizador_id uuid, nome text, funcao text, skills uuid[], zona text, minutos_ocupados integer, dias_cheios integer, ordens integer, livre boolean, motivo text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH lim AS (
    SELECT COALESCE(_ini, current_date) AS ini,
           GREATEST(COALESCE(_fim, _ini, current_date), COALESCE(_ini, current_date)) AS fim
  ),
  todos AS (
    SELECT g::date AS dia FROM lim, generate_series(lim.ini, lim.fim, interval '1 day') g
  ),
  dias AS (
    SELECT dia FROM todos
     WHERE extract(isodow FROM dia) <= 5
        OR NOT EXISTS (SELECT 1 FROM todos t2 WHERE extract(isodow FROM t2.dia) <= 5)
  ),
  carga AS (
    SELECT tp.utilizador_id, dd.dia,
           sum(t.minutos_previstos::numeric / GREATEST(t.pessoas_previstas, 1) / nd.n) AS minutos,
           string_agg(DISTINCT o.codigo, ', ') AS obras
      FROM public.ops_obra_tarefa t
      JOIN public.ops_obra o ON o.id = t.obra_id AND o.estado IN ('planeada','em_curso')
      JOIN public.ops_obra_tarefa_pessoa tp ON tp.tarefa_id = t.id
      CROSS JOIN LATERAL (
        SELECT GREATEST(1, count(*)) AS n
          FROM generate_series(t.inicio_planeado, COALESCE(t.fim_planeado, t.inicio_planeado), interval '1 day') g
         WHERE extract(isodow FROM g) <= 5) nd
      JOIN dias dd ON dd.dia BETWEEN t.inicio_planeado AND COALESCE(t.fim_planeado, t.inicio_planeado)
     WHERE t.organization_id = _org
       AND t.estado IN ('por_fazer','em_curso','rejeitada')
       AND t.inicio_planeado IS NOT NULL
       AND (_excluir IS NULL OR t.id <> _excluir)
     GROUP BY tp.utilizador_id, dd.dia
  ),
  ordens AS (
    SELECT x.u AS utilizador_id, count(DISTINCT od.id) AS n, min(od.codigo) AS codigo
      FROM public.ops_ordem od
      CROSS JOIN LATERAL (
        SELECT od.responsavel_id AS u WHERE od.responsavel_id IS NOT NULL
        UNION
        SELECT op.utilizador_id FROM public.ops_ordem_pessoa op WHERE op.ordem_id = od.id) x
     WHERE od.organization_id = _org
       AND od.estado IN ('agendada','em_curso','pausada')
       AND od.agendada_para IS NOT NULL
       AND (od.agendada_para AT TIME ZONE 'Europe/Lisbon')::date IN (SELECT dia FROM dias)
     GROUP BY x.u
  ),
  indisp AS (
    SELECT i.utilizador_id, min(i.motivo) AS motivo
      FROM lim, public.ops_obra_indisponiveis_impl(_org, lim.ini, lim.fim) i
     GROUP BY i.utilizador_id
  ),
  cheios AS (
    SELECT c.utilizador_id, count(*) AS n, string_agg(DISTINCT c.obras, ', ') AS obras
      FROM carga c WHERE c.minutos >= 479.5
     GROUP BY c.utilizador_id
  )
  SELECT p.utilizador_id,
         COALESCE(u.name, 'Sem nome')::text,
         p.funcao::text,
         COALESCE((SELECT array_agg(us.skill_id ORDER BY k.nome)
                     FROM public.ops_utilizador_skill us
                     JOIN public.ops_skill k ON k.id = us.skill_id AND k.organization_id = _org
                    WHERE us.utilizador_id = p.utilizador_id), '{}'::uuid[]),
         nullif(btrim(p.zona_base), ''),
         COALESCE(round((SELECT sum(c.minutos) FROM carga c WHERE c.utilizador_id = p.utilizador_id)), 0)::integer,
         COALESCE(ch.n, 0)::integer,
         COALESCE(od.n, 0)::integer,
         (ch.utilizador_id IS NULL AND od.utilizador_id IS NULL AND ix.utilizador_id IS NULL),
         COALESCE(ix.motivo,
                  'agenda cheia: ' || ch.obras,
                  CASE WHEN od.utilizador_id IS NOT NULL THEN 'ordem ' || od.codigo END)
    FROM public.ops_utilizador_perfil p
    LEFT JOIN public.anew_users u ON u.id = p.utilizador_id
    LEFT JOIN cheios ch ON ch.utilizador_id = p.utilizador_id
    LEFT JOIN ordens od ON od.utilizador_id = p.utilizador_id
    LEFT JOIN indisp ix ON ix.utilizador_id = p.utilizador_id
   WHERE p.organization_id = _org AND p.ativo
   ORDER BY 9 DESC, 6, 2
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_pessoas_livres_impl(_org uuid, _ini date, _fim date, _excluir uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_pessoas_livres_impl(_org uuid, _ini date, _fim date, _excluir uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_planear_auto_impl(_obra_id uuid, _desde date, _fixas uuid[] DEFAULT NULL::uuid[])
 RETURNS date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org   uuid := (SELECT o.organization_id FROM public.ops_obra o WHERE o.id = _obra_id);
  d       date := public.ops_obra_somar_dias_uteis_org(v_org, _desde, 0);
  v_best  date;
  v_min   integer;
  n       integer;
  i       integer := 0;
  v_fixas uuid[] := COALESCE(_fixas, '{}');
BEGIN
  LOOP
    DELETE FROM public.ops_obra_tarefa_pessoa tp
     USING public.ops_obra_tarefa t
     WHERE t.id = tp.tarefa_id AND t.obra_id = _obra_id
       AND t.estado IN ('por_fazer','rejeitada')
       AND NOT (t.id = ANY (v_fixas))
       AND NOT EXISTS (SELECT 1 FROM public.ops_obra_registo r WHERE r.tarefa_id = t.id);
    PERFORM public.ops_obra_replanear_impl(_obra_id, d);
    PERFORM public.ops_obra_distribuir_impl(_obra_id);

    SELECT count(*) INTO n FROM public.ops_obra_tarefa t
     WHERE t.obra_id = _obra_id AND public.ops_obra_conflitos_impl(t.id) <> '[]'::jsonb;
    IF n = 0 THEN
      RETURN d;
    END IF;
    IF v_min IS NULL OR n < v_min THEN
      v_min := n;
      v_best := d;
    END IF;

    i := i + 1;
    EXIT WHEN i >= 40;
    d := public.ops_obra_somar_dias_uteis_org(v_org, d, 1);
  END LOOP;

  -- Nenhum dia sem choques: o que tem menos.
  DELETE FROM public.ops_obra_tarefa_pessoa tp
   USING public.ops_obra_tarefa t
   WHERE t.id = tp.tarefa_id AND t.obra_id = _obra_id
     AND t.estado IN ('por_fazer','rejeitada')
     AND NOT (t.id = ANY (v_fixas))
     AND NOT EXISTS (SELECT 1 FROM public.ops_obra_registo r WHERE r.tarefa_id = t.id);
  PERFORM public.ops_obra_replanear_impl(_obra_id, v_best);
  PERFORM public.ops_obra_distribuir_impl(_obra_id);
  RETURN v_best;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_planear_auto_impl(_obra_id uuid, _desde date, _fixas uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_planear_auto_impl(_obra_id uuid, _desde date, _fixas uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_ritmo_aprender(_tarefa uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t       record;
  st      record;
  niv     text;
  v_reais numeric[];
  v_qts   numeric[];
  v_fix0  numeric;
  v_pu0   numeric;
  r       record;
  ant     record;
  g_fix   numeric;
  g_pu    numeric;
  v_mud   integer := 0;
BEGIN
  SELECT * INTO t FROM public.ops_obra_tarefa WHERE id = _tarefa;
  IF NOT FOUND OR t.servico_tarefa_id IS NULL THEN
    RETURN 0;
  END IF;
  SELECT * INTO st FROM public.ops_obra_servico_tarefa WHERE id = t.servico_tarefa_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  g_fix := st.minutos_fixos;
  g_pu := st.minutos_por_unidade;

  -- Primeiro o geral; depois a combinação de fatores desta tarefa, se tiver.
  FOREACH niv IN ARRAY CASE WHEN COALESCE(t.fatores_chave, '') <> '' THEN ARRAY['', t.fatores_chave]
                            ELSE ARRAY[''] END LOOP
    v_fix0 := CASE WHEN niv = '' THEN st.minutos_fixos ELSE g_fix END;
    v_pu0 := CASE WHEN niv = '' THEN st.minutos_por_unidade ELSE g_pu END;

    SELECT array_agg(x.real ORDER BY x.id), array_agg(x.q ORDER BY x.id) INTO v_reais, v_qts
      FROM (SELECT o.id,
                   public.ops_obra_minutos_reais(o.id)
                   * CASE WHEN o.minutos_juntos > 0 AND o.minutos_previstos > o.minutos_juntos
                          THEN (o.minutos_previstos - o.minutos_juntos)::numeric / o.minutos_previstos
                          ELSE 1 END AS real,
                   COALESCE(o.medida_real, o.medida_qt, 0) AS q
              FROM public.ops_obra_tarefa o
             WHERE o.organization_id = t.organization_id
               AND o.servico_tarefa_id = st.id
               AND o.estado = 'validada'
               AND COALESCE(o.motivo_desvio, '') NOT IN ('material_em_falta','acesso_cliente')
               AND NOT EXISTS (SELECT 1 FROM public.ops_obra_tarefa_atraso a
                                WHERE a.tarefa_id = o.id
                                  AND a.motivo IN ('material_em_falta','acesso_cliente','meteorologia'))
               AND (niv = '' OR o.fatores_chave = niv)) x;

    SELECT * INTO r FROM public.ops_obra_ritmo_calcular(v_fix0, v_pu0, st.medida, v_reais, v_qts);
    IF COALESCE(r.o_n, 0) > 0 THEN
      SELECT * INTO ant FROM public.ops_obra_ritmo WHERE servico_tarefa_id = st.id AND fatores_chave = niv;
      INSERT INTO public.ops_obra_ritmo (organization_id, servico_tarefa_id, fatores_chave, n,
                                         minutos_fixos, minutos_por_unidade, padrao_fixos, padrao_por_unidade, atualizado_em)
      VALUES (t.organization_id, st.id, niv, r.o_n, r.o_fix, r.o_pu, st.minutos_fixos, st.minutos_por_unidade, now())
      ON CONFLICT (servico_tarefa_id, fatores_chave) DO UPDATE
        SET n = EXCLUDED.n, minutos_fixos = EXCLUDED.minutos_fixos,
            minutos_por_unidade = EXCLUDED.minutos_por_unidade,
            padrao_fixos = EXCLUDED.padrao_fixos, padrao_por_unidade = EXCLUDED.padrao_por_unidade,
            atualizado_em = now();
      IF ant.servico_tarefa_id IS NULL OR ant.minutos_fixos <> r.o_fix OR ant.minutos_por_unidade <> r.o_pu THEN
        INSERT INTO public.ops_obra_ritmo_historico (organization_id, servico_tarefa_id, fatores_chave, tarefa_id, n,
                                                     antes_fixos, antes_por_unidade, depois_fixos, depois_por_unidade)
        VALUES (t.organization_id, st.id, niv, _tarefa, r.o_n, ant.minutos_fixos, ant.minutos_por_unidade, r.o_fix, r.o_pu);
        v_mud := v_mud + 1;
      END IF;
      IF niv = '' THEN
        g_fix := r.o_fix;
        g_pu := r.o_pu;
      END IF;
    END IF;
  END LOOP;
  RETURN v_mud;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_ritmo_aprender(_tarefa uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_ritmo_aprender(_tarefa uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_ritmo_calcular(_fix0 numeric, _pu0 numeric, _medida text, _reais numeric[], _qts numeric[], OUT o_fix numeric, OUT o_pu numeric, OUT o_n integer)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k      constant numeric := 3;
  n      integer := COALESCE(array_length(_reais, 1), 0);
  obs    numeric[] := '{}';
  qs     numeric[] := '{}';
  rs     numeric[] := '{}';
  med    numeric;
  i      integer;
  sq     numeric; sr numeric; sqq numeric; sqr numeric; mq numeric; mr numeric; b numeric; a numeric;
BEGIN
  o_fix := COALESCE(_fix0, 0);
  o_pu := COALESCE(_pu0, 0);
  o_n := 0;
  IF n = 0 THEN RETURN; END IF;

  IF _medida = 'fixo' OR o_pu = 0 THEN
    -- Só o fixo: cada tarefa é uma observação do tempo total.
    FOR i IN 1..n LOOP
      IF _reais[i] >= 5 THEN obs := obs || _reais[i]; END IF;
    END LOOP;
  ELSE
    FOR i IN 1..n LOOP
      IF _reais[i] >= 5 AND COALESCE(_qts[i], 0) > 0 THEN
        obs := obs || GREATEST(0, (_reais[i] - o_fix) / _qts[i]);
        qs := qs || _qts[i];
        rs := rs || _reais[i];
      END IF;
    END LOOP;
  END IF;
  n := COALESCE(array_length(obs, 1), 0);
  IF n = 0 THEN RETURN; END IF;

  -- Fora os absurdos (com 3+ observações).
  IF n >= 3 THEN
    SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY v) INTO med FROM unnest(obs) v;
    IF med > 0 THEN
      SELECT array_agg(o ORDER BY ord), array_agg(q ORDER BY ord), array_agg(r ORDER BY ord)
        INTO obs, qs, rs
        FROM unnest(obs, CASE WHEN cardinality(qs) = cardinality(obs) THEN qs ELSE array_fill(NULL::numeric, ARRAY[cardinality(obs)]) END,
                    CASE WHEN cardinality(rs) = cardinality(obs) THEN rs ELSE array_fill(NULL::numeric, ARRAY[cardinality(obs)]) END)
             WITH ORDINALITY AS u(o, q, r, ord)
       WHERE u.o <= 4 * med AND u.o >= med / 4;
      n := COALESCE(array_length(obs, 1), 0);
      IF n = 0 THEN RETURN; END IF;
    END IF;
  END IF;

  o_n := n;
  IF _medida = 'fixo' OR COALESCE(_pu0, 0) = 0 THEN
    o_fix := round((k * COALESCE(_fix0, 0) + (SELECT sum(v) FROM unnest(obs) v)) / (k + n), 2);
    RETURN;
  END IF;

  o_pu := round((k * COALESCE(_pu0, 0) + (SELECT sum(v) FROM unnest(obs) v)) / (k + n), 3);
  -- Tamanhos diferentes que cheguem: separar o fixo do variável.
  IF n >= 5 AND (SELECT max(v) FROM unnest(qs) v) >= 1.5 * (SELECT min(v) FROM unnest(qs) v) THEN
    SELECT avg(q), avg(r) INTO mq, mr FROM unnest(qs, rs) u(q, r);
    SELECT sum((q - mq) * (r - mr)), sum((q - mq) ^ 2) INTO sqr, sqq FROM unnest(qs, rs) u(q, r);
    IF sqq > 0 THEN
      b := GREATEST(0, sqr / sqq);
      a := GREATEST(0, mr - b * mq);
      o_fix := round((k * COALESCE(_fix0, 0) + n * a) / (k + n), 2);
      o_pu := round((k * COALESCE(_pu0, 0) + n * b) / (k + n), 3);
    END IF;
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_ritmo_calcular(_fix0 numeric, _pu0 numeric, _medida text, _reais numeric[], _qts numeric[], OUT o_fix numeric, OUT o_pu numeric, OUT o_n integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_ritmo_calcular(_fix0 numeric, _pu0 numeric, _medida text, _reais numeric[], _qts numeric[], OUT o_fix numeric, OUT o_pu numeric, OUT o_n integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_ritmo_calcular(_fix0 numeric, _pu0 numeric, _medida text, _reais numeric[], _qts numeric[], OUT o_fix numeric, OUT o_pu numeric, OUT o_n integer) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_rotulo_atraso(_motivo text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE _motivo
    WHEN 'secagem' THEN 'Secagem / cura'
    WHEN 'condicoes_edificio' THEN 'Condições do edifício'
    WHEN 'material_em_falta' THEN 'Material em falta'
    WHEN 'trabalho_imprevisto' THEN 'Trabalho imprevisto'
    WHEN 'acesso_cliente' THEN 'Acesso / cliente'
    WHEN 'meteorologia' THEN 'Meteorologia'
    WHEN 'equipa' THEN 'Equipa'
    ELSE 'Outro' END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_rotulo_atraso(_motivo text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_rotulo_atraso(_motivo text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_rotulo_atraso(_motivo text) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_semear_tempos_padrao_impl(_org uuid, _autor uuid, _substituir boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sem       jsonb := public.ops_obra_tempos_padrao();
  v_def       jsonb;
  v_nome      text;
  v_ids       uuid[];
  v_id        uuid;
  v_servicos  integer := 0;
  v_passos    integer := 0;
  v_saltados  text[] := '{}';
  v_faltam    text[] := '{}';
  p           jsonb;
  i           integer;
BEGIN
  IF to_regclass('public.services') IS NULL THEN
    RAISE EXCEPTION 'Esta base não tem o catálogo de serviços do CRM.';
  END IF;

  INSERT INTO public.ops_skill (organization_id, nome)
  SELECT _org, x FROM jsonb_array_elements_text(v_sem->'skills') x
  ON CONFLICT (organization_id, nome) DO NOTHING;

  -- Pacotes e extras: a mesma forma (passos), o pacote traz também o perfil.
  FOR v_def IN
    SELECT d || jsonb_build_object('_pacote', true) FROM jsonb_array_elements(v_sem->'pacotes') d
    UNION ALL
    SELECT d || jsonb_build_object('_pacote', false, 'servicos', jsonb_build_array(d->>'servico'))
      FROM jsonb_array_elements(v_sem->'extras') d
  LOOP
    FOR v_nome IN SELECT jsonb_array_elements_text(v_def->'servicos') LOOP
      EXECUTE 'SELECT COALESCE(array_agg(s.id), ''{}'') FROM public.services s
                WHERE btrim(s.name) = btrim($2)
                  AND NOT COALESCE(s.is_deleted, false) AND s.deleted_at IS NULL
                  AND (s.organization_id = $1'
        || CASE WHEN to_regclass('public.service_organizations') IS NOT NULL
                THEN ' OR EXISTS (SELECT 1 FROM public.service_organizations so
                                   WHERE so.service_id = s.id AND so.organization_id = $1)'
                ELSE '' END
        || ')'
        INTO v_ids USING _org, v_nome;
      IF cardinality(v_ids) = 0 THEN
        v_faltam := v_faltam || v_nome;
        CONTINUE;
      END IF;

      FOREACH v_id IN ARRAY v_ids LOOP
        IF NOT _substituir AND EXISTS (SELECT 1 FROM public.ops_obra_servico_tarefa
                                        WHERE organization_id = _org AND servico_id = v_id AND origem = 'manual') THEN
          v_saltados := v_saltados || v_nome;
          CONTINUE;
        END IF;

        INSERT INTO public.ops_obra_servico_perfil (organization_id, servico_id, tipo, medidas, planear, medida_para,
                                                    atualizado_em, atualizado_por)
        VALUES (_org, v_id,
                CASE WHEN (v_def->>'_pacote')::boolean THEN v_def->>'tipo' END,
                COALESCE(CASE WHEN (v_def->>'_pacote')::boolean THEN v_def->'medidas' END, '{}'::jsonb),
                true, NULL, now(), _autor)
        ON CONFLICT (organization_id, servico_id) DO UPDATE
          SET tipo = EXCLUDED.tipo, medidas = EXCLUDED.medidas, planear = true, medida_para = NULL,
              atualizado_em = now(), atualizado_por = _autor;

        DELETE FROM public.ops_obra_servico_tarefa WHERE organization_id = _org AND servico_id = v_id;
        i := 0;
        FOR p IN SELECT x FROM jsonb_array_elements(v_def->'passos') x LOOP
          i := i + 1;
          INSERT INTO public.ops_obra_servico_tarefa (
            organization_id, servico_id, ordem, nome, fase, minutos_por_unidade, minutos_fixos, pessoas,
            skill_id, depende_ordem, origem, atualizado_por,
            chave, depende_chaves, espera_antes_horas, medida, condicao, encaixe, fatores)
          VALUES (
            _org, v_id, i, p->>'nome', (p->>'fase')::smallint,
            (p->>'por_unidade')::numeric,
            (p->>'fixos')::integer,
            (p->>'pessoas')::smallint,
            (SELECT k.id FROM public.ops_skill k WHERE k.organization_id = _org AND k.nome = p->>'skill'),
            NULL, 'padrao', _autor,
            p->>'chave',
            ARRAY(SELECT jsonb_array_elements_text(p->'depende')),
            (p->>'espera')::numeric,
            CASE WHEN (p->>'medida') = 'fixo' OR ((p->>'por_unidade')::numeric = 0 AND (p->>'medida') <> 'qt')
                 THEN 'fixo' ELSE p->>'medida' END,
            -- Condição: os nomes dos serviços passam a ids desta organização.
            CASE WHEN jsonb_typeof(p->'condicao') = 'object' THEN
              jsonb_strip_nulls(jsonb_build_object(
                'servicos', public.ops_obra_ids_de_servicos(_org, p->'condicao'->'servicos'),
                'ficha', p->'condicao'->'ficha')) END,
            nullif(p->'encaixe', 'null'::jsonb),
            ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'fatores', '[]'::jsonb))));
          v_passos := v_passos + 1;
        END LOOP;
        v_servicos := v_servicos + 1;
      END LOOP;
    END LOOP;
  END LOOP;

  -- O que não é trabalho no local, e o que só dá medidas ao pacote.
  FOR v_def IN
    SELECT jsonb_build_object('servico', x, 'planear', false) FROM jsonb_array_elements_text(v_sem->'sem_planear') x
    UNION ALL
    SELECT jsonb_build_object('servico', x->>'servico', 'planear', true, 'medida_para', x->>'medida')
      FROM jsonb_array_elements(v_sem->'medida_para') x
  LOOP
    FOREACH v_id IN ARRAY public.ops_obra_ids_de_servicos(_org, jsonb_build_array(v_def->>'servico')) LOOP
      INSERT INTO public.ops_obra_servico_perfil (organization_id, servico_id, planear, medida_para, atualizado_em, atualizado_por)
      VALUES (_org, v_id, (v_def->>'planear')::boolean, v_def->>'medida_para', now(), _autor)
      ON CONFLICT (organization_id, servico_id) DO UPDATE
        SET planear = EXCLUDED.planear, medida_para = EXCLUDED.medida_para, tipo = NULL,
            atualizado_em = now(), atualizado_por = _autor;
      DELETE FROM public.ops_obra_servico_tarefa
       WHERE organization_id = _org AND servico_id = v_id AND origem <> 'manual';
      v_servicos := v_servicos + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'versao', v_sem->>'versao', 'servicos', v_servicos, 'passos', v_passos,
                            'saltados', to_jsonb(v_saltados), 'nao_encontrados', to_jsonb(v_faltam));
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_semear_tempos_padrao_impl(_org uuid, _autor uuid, _substituir boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_semear_tempos_padrao_impl(_org uuid, _autor uuid, _substituir boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_sincronizar_avisos(_org uuid DEFAULT NULL::uuid, _obra uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org    uuid;
  v_a      record;
  v_p      uuid;
  v_com    uuid[];
  v_novos  integer := 0;
  v_resolv integer := 0;
  v_banc   integer := 0;
  v_ob     uuid;
  v_r      text;
BEGIN
  FOR v_org IN
    SELECT DISTINCT o.organization_id FROM public.ops_obra o
     WHERE (_org IS NULL OR o.organization_id = _org)
       AND (_obra IS NULL OR o.id = _obra)
  LOOP
    v_com := '{}';
    IF to_regclass('public.notifications') IS NOT NULL THEN
      FOR v_a IN
        SELECT a.obra_id, max(a.obra_codigo) AS codigo, max(a.obra_titulo) AS titulo,
               min(a.gravidade) AS gravidade, count(*)::int AS n,
               array_agg(a.tipo || ':' || COALESCE(a.tarefa_id, a.atraso_id)::text) AS chaves,
               concat_ws(' · ',
                 NULLIF(count(*) FILTER (WHERE a.tipo = 'fim_ultrapassado'), 0)::text || ' fora do prazo',
                 NULLIF(count(*) FILTER (WHERE a.tipo = 'nao_iniciada'), 0)::text || ' por começar',
                 NULLIF(count(*) FILTER (WHERE a.tipo = 'material_tarde'), 0)::text || ' com material tarde',
                 NULLIF(count(*) FILTER (WHERE a.tipo = 'cliente_por_avisar'), 0)::text || ' cliente por avisar') AS resumo,
               (array_agg(a.tarefa_nome || ' — ' || a.detalhe ORDER BY a.gravidade, a.minutos_atraso DESC NULLS LAST))[1] AS pior
          FROM public.ops_obra_alertas_lista(v_org, _obra) a
         GROUP BY a.obra_id
      LOOP
        v_com := v_com || v_a.obra_id;
        FOREACH v_p IN ARRAY public.ops_obra_coordenacao(v_a.obra_id) LOOP
          v_r := public.ops_obra_notificar(v_org, v_p, 'operacoes_obra_alertas', v_a.obra_id,
            v_a.codigo || ': ' || v_a.n || CASE WHEN v_a.n = 1 THEN ' alerta' ELSE ' alertas' END,
            COALESCE(v_a.titulo, 'Obra') || '. ' || v_a.resumo || '. ' || v_a.pior,
            '/operacao/obras/' || v_a.codigo,
            CASE WHEN v_a.gravidade = 1 THEN 'high' ELSE 'medium' END,
            v_a.chaves, jsonb_build_object('codigo', v_a.codigo));
          IF v_r IN ('novo','de_novo') THEN v_novos := v_novos + 1; END IF;
        END LOOP;
      END LOOP;
      v_resolv := v_resolv + public.ops_obra_notificacoes_resolver(v_org, 'operacoes_obra_alertas', v_com, _obra, 'alertas_resolvidos');
    END IF;

    FOR v_ob IN
      SELECT o.id FROM public.ops_obra o
       WHERE o.organization_id = v_org AND (_obra IS NULL OR o.id = _obra)
         AND o.estado IN ('planeada','em_curso')
    LOOP
      IF (public.ops_obra_avisar_bancada(v_ob)->>'novo')::boolean THEN v_banc := v_banc + 1; END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('alertas_novos', v_novos, 'resolvidos', v_resolv, 'bancadas', v_banc);
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_sincronizar_avisos(_org uuid, _obra uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_sincronizar_avisos(_org uuid, _obra uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_somar_dias_uteis_org(_org uuid, _d date, _n integer)
 RETURNS date
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (public.ops_obra_dias_uteis_lista(_org, _d, GREATEST(_n, 0) + 1))[GREATEST(_n, 0) + 1]
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_somar_dias_uteis_org(_org uuid, _d date, _n integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_somar_dias_uteis_org(_org uuid, _d date, _n integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obra_somar_dias_uteis_org(_org uuid, _d date, _n integer) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_tarefa_baseline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.inicio_original IS NOT NULL OR OLD.fim_original IS NOT NULL THEN
    NEW.inicio_original := OLD.inicio_original;
    NEW.fim_original := OLD.fim_original;
  ELSIF NEW.inicio_original IS NULL AND NEW.fim_original IS NULL
    AND (NEW.inicio_planeado IS DISTINCT FROM OLD.inicio_planeado
         OR NEW.fim_planeado IS DISTINCT FROM OLD.fim_planeado)
    AND (OLD.inicio_planeado IS NOT NULL OR OLD.fim_planeado IS NOT NULL)
    AND EXISTS (SELECT 1 FROM public.ops_obra o WHERE o.id = NEW.obra_id AND o.estado = 'em_curso') THEN
    NEW.inicio_original := OLD.inicio_planeado;
    NEW.fim_original := OLD.fim_planeado;
  END IF;
  RETURN NEW;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_tarefa_baseline() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_tarefa_baseline() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_tarefa_dep_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.depende_de IS NOT NULL AND OLD.depende_de IS DISTINCT FROM NEW.depende_de THEN
      DELETE FROM public.ops_obra_tarefa_dependencia
       WHERE tarefa_id = NEW.id AND depende_de_id = OLD.depende_de;
    END IF;
  END IF;
  IF NEW.depende_de IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.ops_obra_tarefa_dependencia
        WHERE tarefa_id = NEW.id AND depende_de_id = NEW.depende_de) THEN
    INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
    VALUES (NEW.id, NEW.depende_de, NEW.organization_id, NEW.obra_id);
  END IF;
  RETURN NULL;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_tarefa_dep_sync() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_tarefa_dep_sync() TO service_role;

