CREATE OR REPLACE FUNCTION public.ops_obra_tg_avisar_atribuicao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v record;
BEGIN
  FOR v IN SELECT obra_id, array_agg(DISTINCT utilizador_id) AS pessoas FROM novas GROUP BY obra_id LOOP
    PERFORM public.ops_obra_avisar_atribuicao(v.obra_id, v.pessoas);
  END LOOP;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Avisos de atribuição: %', SQLERRM;
  RETURN NULL;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_tg_avisar_atribuicao() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_tg_avisar_atribuicao() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_tg_rever_bancada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v uuid;
BEGIN
  -- Só as obras onde mudou alguma tarefa de bancada (ou marmorista).
  FOR v IN
    SELECT DISTINCT n.obra_id FROM novas n
      LEFT JOIN public.ops_skill k ON k.id = n.skill_id
     WHERE n.nome ILIKE '%bancada%' OR k.nome ILIKE 'marmor%'
  LOOP
    PERFORM public.ops_obra_avisar_bancada(v);
  END LOOP;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'Aviso da bancada: %', SQLERRM;
  RETURN NULL;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_tg_rever_bancada() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_tg_rever_bancada() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obra_validar_tarefas(_org uuid, _orc uuid, _tarefas jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_n    integer;
  e      jsonb;
  i      integer := 0;
  v_nome text;
  v_num  numeric;
  v_dep  integer;
  v_u    text;
  v_lin  uuid;
  v_ok   boolean;
BEGIN
  IF jsonb_typeof(_tarefas) <> 'array' THEN
    RAISE EXCEPTION 'As tarefas têm de vir numa lista.';
  END IF;
  v_n := jsonb_array_length(_tarefas);
  IF v_n > 500 THEN
    RAISE EXCEPTION 'Demasiadas tarefas (%). O máximo é 500.', v_n;
  END IF;

  FOR e IN SELECT x FROM jsonb_array_elements(_tarefas) x LOOP
    i := i + 1;
    IF jsonb_typeof(e) <> 'object' THEN
      RAISE EXCEPTION 'A tarefa n.º % não é válida.', i;
    END IF;
    v_nome := nullif(btrim(e->>'nome'), '');
    IF v_nome IS NULL THEN
      RAISE EXCEPTION 'A tarefa n.º % não tem nome.', i;
    END IF;
    IF length(v_nome) > 300 OR length(COALESCE(e->>'procedimento', '')) > 4000
       OR length(COALESCE(e->>'materiais', '')) > 4000 OR length(COALESCE(e->>'ferramentas', '')) > 4000 THEN
      RAISE EXCEPTION '"%": texto demasiado comprido.', left(v_nome, 60);
    END IF;

    -- Números: a mensagem certa em vez de um erro de conversão.
    IF (CASE WHEN COALESCE(e->>'fase', '') ~ '^\d{1,2}$' THEN (e->>'fase')::integer END)
       NOT BETWEEN 1 AND 9 IS NOT FALSE THEN
      RAISE EXCEPTION '"%": a fase tem de ser de 1 a 9.', v_nome;
    END IF;
    IF (CASE WHEN COALESCE(e->>'minutos', '') ~ '^\d{1,6}$' THEN (e->>'minutos')::integer END)
       > 0 IS NOT TRUE THEN
      RAISE EXCEPTION '"%": os minutos previstos têm de ser um número inteiro maior que 0.', v_nome;
    END IF;
    IF nullif(e->>'pessoas_previstas', '') IS NOT NULL
       AND (CASE WHEN e->>'pessoas_previstas' ~ '^\d{1,2}$' THEN (e->>'pessoas_previstas')::integer END)
           BETWEEN 1 AND 20 IS NOT TRUE THEN
      RAISE EXCEPTION '"%": de 1 a 20 pessoas.', v_nome;
    END IF;
    -- Planeamento automático (2c).
    IF nullif(e->>'espera_antes_horas', '') IS NOT NULL
       AND (public.ops_num(e->>'espera_antes_horas') BETWEEN 0 AND 2000) IS NOT TRUE THEN
      RAISE EXCEPTION '"%": a espera tem de ser de 0 a 2000 horas.', v_nome;
    END IF;
    IF nullif(e->>'medida', '') IS NOT NULL AND e->>'medida' NOT IN
       ('qt','fixo','m2_pavimento','m2_parede','m2_total','pontos_agua','pontos_eletricos',
        'pecas_sanitarias','acessorios','modulos','eletrodomesticos','ml_bancada') THEN
      RAISE EXCEPTION '"%": medida desconhecida.', v_nome;
    END IF;
    IF nullif(e->>'medida_qt', '') IS NOT NULL AND (public.ops_num(e->>'medida_qt') >= 0) IS NOT TRUE THEN
      RAISE EXCEPTION '"%": a quantidade da medida tem de ser um número ≥ 0.', v_nome;
    END IF;
    IF nullif(e->>'minutos_origem', '') IS NOT NULL
       AND e->>'minutos_origem' NOT IN ('padrao','aprendido','ficha','manual') THEN
      RAISE EXCEPTION '"%": origem do tempo desconhecida.', v_nome;
    END IF;
    IF (nullif(e->>'ritmo_n', '') IS NOT NULL AND (public.ops_num(e->>'ritmo_n') >= 0) IS NOT TRUE)
       OR (nullif(e->>'minutos_juntos', '') IS NOT NULL AND (public.ops_num(e->>'minutos_juntos') >= 0) IS NOT TRUE) THEN
      RAISE EXCEPTION '"%": número inválido.', v_nome;
    END IF;
    IF e ? 'fatores' AND jsonb_typeof(e->'fatores') NOT IN ('object', 'null') THEN
      RAISE EXCEPTION '"%": os fatores têm de vir num objeto.', v_nome;
    END IF;
    IF length(COALESCE(e->>'fatores_chave', '')) > 500 OR length(COALESCE(e->>'chave_passo', '')) > 12 THEN
      RAISE EXCEPTION '"%": texto demasiado comprido.', v_nome;
    END IF;

    -- "Depois de": posição(ões) 1..n de OUTRAS tarefas da lista.
    IF jsonb_typeof(e->'depende') NOT IN ('array', 'number', 'string', 'null') THEN
      RAISE EXCEPTION '"%": "depois de" inválido.', v_nome;
    END IF;
    FOR v_u IN SELECT jsonb_array_elements_text(
                 CASE jsonb_typeof(e->'depende') WHEN 'array' THEN e->'depende'
                      WHEN 'number' THEN jsonb_build_array(e->'depende')
                      WHEN 'string' THEN jsonb_build_array(e->'depende')
                      ELSE '[]'::jsonb END) LOOP
      IF v_u !~ '^\d{1,4}$' THEN
        RAISE EXCEPTION '"%": "depois de" inválido.', v_nome;
      END IF;
      v_dep := v_u::integer;
      IF v_dep = i OR v_dep < 1 OR v_dep > v_n THEN
        RAISE EXCEPTION '"%": só pode depender de outra tarefa da lista.', v_nome;
      END IF;
    END LOOP;

    -- Pessoas: perfil ATIVO em Operações nesta organização.
    IF e ? 'pessoas' AND jsonb_typeof(e->'pessoas') NOT IN ('array', 'null') THEN
      RAISE EXCEPTION '"%": as pessoas têm de vir numa lista.', v_nome;
    END IF;
    IF jsonb_typeof(e->'pessoas') = 'array' THEN
      IF jsonb_array_length(e->'pessoas') > 20 THEN
        RAISE EXCEPTION '"%": no máximo 20 pessoas.', v_nome;
      END IF;
      FOR v_u IN SELECT jsonb_array_elements_text(e->'pessoas') LOOP
        IF NOT EXISTS (SELECT 1 FROM public.ops_utilizador_perfil p
                        WHERE p.organization_id = _org AND p.utilizador_id::text = lower(v_u) AND p.ativo) THEN
          RAISE EXCEPTION '"%": há uma pessoa que não está ativa em Operações nesta organização.', v_nome
            USING ERRCODE = 'insufficient_privilege';
        END IF;
      END LOOP;
    END IF;

    IF nullif(e->>'skill_id', '') IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.ops_skill k
          WHERE k.id::text = e->>'skill_id' AND k.organization_id = _org) THEN
      RAISE EXCEPTION '"%": essa especialidade não é desta organização.', v_nome;
    END IF;
    IF length(COALESCE(e->>'skill_nome', '')) > 80 THEN
      RAISE EXCEPTION '"%": nome de especialidade demasiado comprido.', v_nome;
    END IF;

    -- Linha do orçamento: tem de ser DESTE orçamento (só lê o CRM).
    IF nullif(e->>'orcamento_linha_id', '') IS NOT NULL THEN
      IF _orc IS NULL OR e->>'orcamento_linha_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION '"%": essa linha não é do orçamento desta obra.', v_nome;
      END IF;
      v_lin := (e->>'orcamento_linha_id')::uuid;
      EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.quote_lines WHERE id = $1 AND quote_id = $2)'
         INTO v_ok USING v_lin, _orc;
      IF NOT v_ok THEN
        RAISE EXCEPTION '"%": essa linha não é do orçamento desta obra.', v_nome;
      END IF;
    END IF;
    IF nullif(e->>'servico_id', '') IS NOT NULL THEN
      IF e->>'servico_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION '"%": esse serviço não é desta organização.', v_nome;
      END IF;
      IF NOT public.ops_obra_servico_da_org(_org, (e->>'servico_id')::uuid) THEN
        RAISE EXCEPTION '"%": esse serviço não é desta organização.', v_nome;
      END IF;
    END IF;
    IF nullif(e->>'servico_tarefa_id', '') IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.ops_obra_servico_tarefa st
          WHERE st.id::text = e->>'servico_tarefa_id' AND st.organization_id = _org) THEN
      RAISE EXCEPTION '"%": esse passo de modelo não é desta organização.', v_nome;
    END IF;

    -- Materiais do CRM: só a forma (é uma cópia, sem FK).
    IF e ? 'materiais_crm' AND jsonb_typeof(e->'materiais_crm') NOT IN ('array', 'null') THEN
      RAISE EXCEPTION '"%": os materiais ligados têm de vir numa lista.', v_nome;
    END IF;
    IF jsonb_typeof(e->'materiais_crm') = 'array' THEN
      IF jsonb_array_length(e->'materiais_crm') > 100 THEN
        RAISE EXCEPTION '"%": demasiados materiais ligados.', v_nome;
      END IF;
      IF EXISTS (SELECT 1 FROM jsonb_array_elements(e->'materiais_crm') m
                  WHERE jsonb_typeof(m) <> 'object'
                     OR nullif(btrim(m->>'nome'), '') IS NULL
                     OR (nullif(m->>'produto_id', '') IS NOT NULL
                         AND m->>'produto_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
                     OR (nullif(m->>'quantidade', '') IS NOT NULL
                         AND m->>'quantidade' !~ '^\d{1,9}(\.\d{1,4})?$')
                     OR (nullif(m->>'disponivel', '') IS NOT NULL
                         AND m->>'disponivel' !~ '^-?\d{1,9}(\.\d{1,4})?$')) THEN
        RAISE EXCEPTION '"%": há um material ligado inválido.', v_nome;
      END IF;
    END IF;
  END LOOP;

  -- Sem ciclos nas dependências da lista.
  SELECT x.e->>'nome' INTO v_nome
    FROM (
      WITH RECURSIVE arestas(a, b) AS (
        SELECT x.pos::integer, dp.v::integer
          FROM jsonb_array_elements(_tarefas) WITH ORDINALITY AS x(e, pos)
         CROSS JOIN LATERAL jsonb_array_elements_text(
                 CASE jsonb_typeof(x.e->'depende') WHEN 'array' THEN x.e->'depende'
                      WHEN 'number' THEN jsonb_build_array(x.e->'depende')
                      WHEN 'string' THEN jsonb_build_array(x.e->'depende')
                      ELSE '[]'::jsonb END) dp(v)
      ),
      r(ini, cur) AS (
        SELECT a, b FROM arestas
        UNION
        SELECT r.ini, ar.b FROM r JOIN arestas ar ON ar.a = r.cur
      )
      SELECT min(ini) AS pos FROM r WHERE r.ini = r.cur
    ) c
    JOIN jsonb_array_elements(_tarefas) WITH ORDINALITY AS x(e, pos) ON x.pos = c.pos;
  IF v_nome IS NOT NULL THEN
    RAISE EXCEPTION '"%": as dependências fecham um ciclo (nenhuma tarefa do ciclo poderia começar).', v_nome;
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obra_validar_tarefas(_org uuid, _orc uuid, _tarefas jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obra_validar_tarefas(_org uuid, _orc uuid, _tarefas jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obras_que_vejo()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH eu AS (SELECT public.current_business_user_id() AS id),
  orgs AS (
    SELECT g.organization_id,
           public.ops_pode(g.organization_id, 'operations.orders.view_all') AS todas,
           public.ops_pode(g.organization_id, 'operations.orders.view') AS ver
      FROM (SELECT DISTINCT organization_id FROM public.ops_obra) g
  )
  SELECT o.id
    FROM public.ops_obra o
    JOIN orgs ON orgs.organization_id = o.organization_id
   CROSS JOIN eu
   WHERE orgs.todas
      OR (orgs.ver AND (
            o.gestor_id = eu.id
         OR o.supervisor_id = eu.id
         OR EXISTS (SELECT 1 FROM public.ops_obra_tarefa_pessoa tp
                     WHERE tp.obra_id = o.id AND tp.utilizador_id = eu.id)))
$function$;
REVOKE ALL ON FUNCTION public.ops_obras_que_vejo() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obras_que_vejo() TO authenticated;
GRANT EXECUTE ON FUNCTION public.ops_obras_que_vejo() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_obras_visiveis(_org uuid)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_todas boolean := public.ops_pode(_org, 'operations.orders.view_all');
  v_ver   boolean;
  v_eu    uuid;
BEGIN
  IF v_todas THEN
    RETURN QUERY SELECT o.id FROM public.ops_obra o WHERE o.organization_id = _org;
    RETURN;
  END IF;
  v_ver := public.ops_pode(_org, 'operations.orders.view');
  IF NOT v_ver THEN
    RETURN;
  END IF;
  v_eu := public.current_business_user_id();
  RETURN QUERY
  SELECT o.id FROM public.ops_obra o
   WHERE o.organization_id = _org
     AND (o.gestor_id = v_eu OR o.supervisor_id = v_eu
          OR EXISTS (SELECT 1 FROM public.ops_obra_tarefa_pessoa tp
                      WHERE tp.obra_id = o.id AND tp.utilizador_id = v_eu));
END
$function$;
REVOKE ALL ON FUNCTION public.ops_obras_visiveis(_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_obras_visiveis(_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_stock_calcular(p_org uuid, p_produtos uuid[])
 RETURNS TABLE(produto_id uuid, nome text, sku text, unidade text, gere_stock boolean, fisico numeric, reservado numeric, a_chegar numeric, disponivel numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_unidade text := 'NULL::text';
  v_join    text := '';
  v_res     text := 'SELECT NULL::uuid AS product_id, 0::numeric AS q WHERE false';
  v_chega   text := 'SELECT NULL::uuid AS product_id, 0::numeric AS q WHERE false';
BEGIN
  IF p_org IS NULL OR p_produtos IS NULL OR cardinality(p_produtos) = 0
     OR NOT public.ops_stock_ha_inventario() THEN
    RETURN;
  END IF;

  IF public.ops_stock_tem('products', ARRAY['uom_id'])
     AND public.ops_stock_tem('uom', ARRAY['id','code']) THEN
    v_unidade := 'u.code::text';
    v_join    := 'LEFT JOIN public.uom u ON u.id = p.uom_id';
  END IF;

  -- Reservas das ECs: a função do CRM, tal e qual.
  IF to_regprocedure('public.fn_client_order_line_reservations(uuid,uuid[])') IS NOT NULL THEN
    v_res := 'SELECT r.product_id, SUM(COALESCE(r.qty_reserved, 0))::numeric AS q
                FROM public.fn_client_order_line_reservations($1, ARRAY(SELECT id FROM prod)) r
               WHERE r.product_id IS NOT NULL
               GROUP BY r.product_id';
  END IF;

  IF public.ops_stock_tem('purchase_orders', ARRAY['id','organization_id','status','deleted_at','source_type'])
     AND public.ops_stock_tem('purchase_order_items', ARRAY['purchase_order_id','product_id','quantity','received_quantity','units_per_uom']) THEN
    v_chega := 'SELECT poi.product_id,
                       SUM(GREATEST(0, poi.quantity - COALESCE(poi.received_quantity, 0))
                           * COALESCE(poi.units_per_uom, 1))::numeric AS q
                  FROM public.purchase_orders po
                  JOIN public.purchase_order_items poi ON poi.purchase_order_id = po.id
                 WHERE po.organization_id = $1
                   AND po.deleted_at IS NULL
                   AND po.status IN (''pending'', ''ordered'', ''partially_received'')
                   AND po.source_type IS DISTINCT FROM ''contract''
                   AND poi.product_id IN (SELECT id FROM prod)
                 GROUP BY poi.product_id';
  END IF;

  RETURN QUERY EXECUTE format($q$
    WITH prod AS (
      SELECT p.id, p.name::text AS nome, NULLIF(p.sku::text, '') AS sku,
             %1$s AS unidade, COALESCE(p.manages_stock, true) AS gere
        FROM public.products p
        %2$s
       WHERE p.id = ANY ($2)
         AND p.deleted_at IS NULL
         AND %3$s
    ),
    fis AS (
      SELECT s.product_id, SUM(s.quantity)::numeric AS q
        FROM public.stocks s
        JOIN public.warehouses w ON w.id = s.warehouse_id
       WHERE w.organization_id = $1
         AND w.deleted_at IS NULL
         AND s.deleted_at IS NULL
         AND s.product_id IN (SELECT id FROM prod)
       GROUP BY s.product_id
    ),
    res   AS (%4$s),
    chega AS (%5$s)
    SELECT pr.id, pr.nome, pr.sku, pr.unidade, pr.gere,
           COALESCE(f.q, 0), COALESCE(r.q, 0), COALESCE(c.q, 0),
           CASE WHEN pr.gere THEN COALESCE(f.q, 0) - COALESCE(r.q, 0) END
      FROM prod pr
      LEFT JOIN fis   f ON f.product_id = pr.id
      LEFT JOIN res   r ON r.product_id = pr.id
      LEFT JOIN chega c ON c.product_id = pr.id
  $q$, v_unidade, v_join, public.ops_stock_filtro_org(), v_res, v_chega)
  USING p_org, p_produtos;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_stock_calcular(p_org uuid, p_produtos uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_stock_calcular(p_org uuid, p_produtos uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_stock_filtro_org()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN public.ops_stock_tem('product_organizations', ARRAY['product_id','organization_id']) THEN
      '(p.organization_id = $1 OR EXISTS (SELECT 1 FROM public.product_organizations po_'
      || ' WHERE po_.product_id = p.id AND po_.organization_id = $1))'
    ELSE 'p.organization_id = $1'
  END
$function$;
REVOKE ALL ON FUNCTION public.ops_stock_filtro_org() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_stock_filtro_org() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_stock_ha_inventario()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.ops_stock_tem('products',   ARRAY['id','name','sku','organization_id','deleted_at','manages_stock'])
     AND public.ops_stock_tem('stocks',     ARRAY['product_id','warehouse_id','quantity','deleted_at'])
     AND public.ops_stock_tem('warehouses', ARRAY['id','organization_id','deleted_at'])
$function$;
REVOKE ALL ON FUNCTION public.ops_stock_ha_inventario() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_stock_ha_inventario() TO service_role;

CREATE OR REPLACE FUNCTION public.ops_stock_tem(p_tabela text, p_colunas text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT to_regclass('public.' || p_tabela) IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM unnest(p_colunas) c(nome)
        WHERE NOT EXISTS (
          SELECT 1 FROM pg_attribute a
           WHERE a.attrelid = to_regclass('public.' || p_tabela)
             AND a.attname = c.nome AND a.attnum > 0 AND NOT a.attisdropped))
$function$;
REVOKE ALL ON FUNCTION public.ops_stock_tem(p_tabela text, p_colunas text[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_stock_tem(p_tabela text, p_colunas text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.ops_stock_verificar(p_org uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_org IS NULL OR NOT public.ops_pode(p_org, 'operations.view') THEN
    RAISE EXCEPTION 'Sem acesso ao stock desta organização.' USING ERRCODE = 'insufficient_privilege';
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION public.ops_stock_verificar(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ops_stock_verificar(p_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.resolve_proposal_address(_proposal_id uuid)
 RETURNS TABLE(address_id uuid, address_type text, is_primary boolean, valid_from timestamp with time zone, valid_to timestamp with time zone, created_at timestamp with time zone, street text, number text, floor text, unit text, postal_code text, city text, district text, country text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH prop AS (
    SELECT p.entity_id, p.deal_id,
           COALESCE(
             p.organization_id,
             (SELECT d0.organization_id FROM public.deals d0 WHERE d0.id = p.deal_id)
           ) AS doc_org
    FROM public.proposals p
    WHERE p.id = _proposal_id
      AND public.has_anew_permission((SELECT auth.uid()), 'proposals.view')
      AND (
        (p.organization_id IN (SELECT public.get_user_crm_org_ids((SELECT auth.uid()))))
        OR (
          p.organization_id IS NULL
          AND EXISTS (
            SELECT 1 FROM public.deals d
            WHERE d.id = p.deal_id
              AND d.organization_id IN (SELECT public.get_user_crm_org_ids((SELECT auth.uid())))
          )
        )
        OR EXISTS (
          SELECT 1 FROM public.deals d
          WHERE d.id = p.deal_id
            AND (d.created_by = public.current_business_user_id()
                 OR d.assigned_to = public.current_business_user_id())
        )
        OR p.created_by = public.current_business_user_id()
      )
  ),
  resolved AS (
    SELECT COALESCE(
      prop.entity_id,
      (SELECT d.entity_id FROM public.deals d WHERE d.id = prop.deal_id)
    ) AS eid,
    prop.doc_org
    FROM prop
  )
  SELECT
    ea.address_id,
    ea.address_type,
    ea.is_primary,
    ea.valid_from,
    ea.valid_to,
    ea.created_at,
    a.street,
    a.number,
    a.floor,
    a.unit,
    a.postal_code,
    a.city,
    a.district,
    a.country
  FROM resolved r
  JOIN public.anew_entity_addresses ea ON ea.entity_id = r.eid
  JOIN public.anew_addresses a ON a.id = ea.address_id
  WHERE r.eid IS NOT NULL
    -- Pertenca: a entidade tem de ser da MESMA organizacao do documento
    -- (criterio de sync_entity_primary_address, 20261120110000, mais a
    -- ligacao em anew_entity_org_links que is_entity_in_user_scope aceita).
    AND EXISTS (
      SELECT 1 FROM public.anew_leads l
        WHERE l.entity_id = r.eid AND l.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_contacts c
        WHERE c.entity_id = r.eid AND c.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_clients cl
        WHERE cl.entity_id = r.eid AND cl.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_organizations o
        WHERE o.entity_id = r.eid AND o.id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_entity_org_links ol
        WHERE ol.entity_id = r.eid AND ol.organization_id = r.doc_org
    )
    AND (ea.valid_to IS NULL OR ea.valid_to > now())
    AND ea.address_type IS DISTINCT FROM 'delivery'
  ORDER BY COALESCE(ea.is_primary, false) DESC, ea.created_at DESC, ea.id DESC
$function$;
REVOKE ALL ON FUNCTION public.resolve_proposal_address(_proposal_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.resolve_proposal_address(_proposal_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_proposal_address(_proposal_id uuid) TO service_role;
COMMENT ON FUNCTION public.resolve_proposal_address(_proposal_id uuid) IS 'Moradas activas (nao de entrega) do cliente de uma proposta, resolvidas PELA leitura da propria proposta. SECURITY DEFINER: confirma primeiro que o chamador pode ler a proposta (mesmo predicado de resolve_proposal_contact), que a entidade pertence a organizacao da proposta (ou do negocio, se a da proposta for NULL) -- por lead, contacto, cliente, organizacao ou ligacao em anew_entity_org_links, com igualdade exacta de organizacao -- e so entao devolve as moradas, primaria primeiro e depois a mais recente (is_primary DESC, created_at DESC, id DESC). EXECUTE so a authenticated.';

CREATE OR REPLACE FUNCTION public.resolve_quote_address(_quote_id uuid)
 RETURNS TABLE(address_id uuid, address_type text, is_primary boolean, valid_from timestamp with time zone, valid_to timestamp with time zone, created_at timestamp with time zone, street text, number text, floor text, unit text, postal_code text, city text, district text, country text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH q AS (
    SELECT qt.entity_id, qt.cliente_id, qt.deal_id,
           qt.organization_id AS doc_org
    FROM public.quotes qt
    WHERE qt.id = _quote_id
      AND public.has_anew_permission((SELECT auth.uid()), 'quotes.view')
      AND qt.organization_id IN (SELECT public.get_user_crm_org_ids((SELECT auth.uid())))
  ),
  resolved AS (
    SELECT COALESCE(
      q.entity_id,
      (SELECT c.entity_id FROM public.anew_clients c WHERE c.id = q.cliente_id),
      (SELECT d.entity_id FROM public.deals d WHERE d.id = q.deal_id),
      (SELECT al.entity_id FROM public.anew_leads al
         WHERE al.id = (SELECT d2.lead_id FROM public.deals d2 WHERE d2.id = q.deal_id))
    ) AS eid,
    q.doc_org
    FROM q
  )
  SELECT
    ea.address_id,
    ea.address_type,
    ea.is_primary,
    ea.valid_from,
    ea.valid_to,
    ea.created_at,
    a.street,
    a.number,
    a.floor,
    a.unit,
    a.postal_code,
    a.city,
    a.district,
    a.country
  FROM resolved r
  JOIN public.anew_entity_addresses ea ON ea.entity_id = r.eid
  JOIN public.anew_addresses a ON a.id = ea.address_id
  WHERE r.eid IS NOT NULL
    -- Pertenca: a entidade tem de ser da MESMA organizacao do documento
    -- (criterio de sync_entity_primary_address, 20261120110000, mais a
    -- ligacao em anew_entity_org_links que is_entity_in_user_scope aceita).
    AND EXISTS (
      SELECT 1 FROM public.anew_leads l
        WHERE l.entity_id = r.eid AND l.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_contacts c
        WHERE c.entity_id = r.eid AND c.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_clients cl
        WHERE cl.entity_id = r.eid AND cl.organization_id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_organizations o
        WHERE o.entity_id = r.eid AND o.id = r.doc_org
      UNION ALL
      SELECT 1 FROM public.anew_entity_org_links ol
        WHERE ol.entity_id = r.eid AND ol.organization_id = r.doc_org
    )
    AND (ea.valid_to IS NULL OR ea.valid_to > now())
    AND ea.address_type IS DISTINCT FROM 'delivery'
  ORDER BY COALESCE(ea.is_primary, false) DESC, ea.created_at DESC, ea.id DESC
$function$;
REVOKE ALL ON FUNCTION public.resolve_quote_address(_quote_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.resolve_quote_address(_quote_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_quote_address(_quote_id uuid) TO service_role;
COMMENT ON FUNCTION public.resolve_quote_address(_quote_id uuid) IS 'Moradas activas (nao de entrega) do cliente de um orcamento, resolvidas PELA leitura do proprio orcamento. SECURITY DEFINER: confirma primeiro que o chamador pode ler o orcamento (mesmo predicado de resolve_quote_contact), que a entidade pertence a organizacao do orcamento (por lead, contacto, cliente, organizacao ou ligacao em anew_entity_org_links, com igualdade exacta de organizacao) e so entao devolve as moradas, primaria primeiro e depois a mais recente (is_primary DESC, created_at DESC, id DESC). EXECUTE so a authenticated.';

CREATE OR REPLACE FUNCTION public.resource_has_full_day_time_off_on(p_resource_id uuid, p_date date, p_tz text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_tz TEXT;
  v_day_start TIMESTAMPTZ;
  v_day_end TIMESTAMPTZ;
BEGIN
  IF p_resource_id IS NULL OR p_date IS NULL THEN
    RETURN false;
  END IF;

  SELECT r.user_id, r.organization_id
  INTO v_user_id, v_org_id
  FROM public.schedule_resources r
  WHERE r.id = p_resource_id;

  -- Recurso sem pessoa (sala, viatura) ou inexistente: nunca tem ferias.
  IF v_user_id IS NULL OR v_org_id IS NULL THEN
    RETURN false;
  END IF;

  -- Fuso ja validado por quem chama: usa-se tal como vem (sem bloco protegido,
  -- que custaria uma subtransacao por chamada no caminho quente).
  v_tz := NULLIF(btrim(p_tz), '');
  IF v_tz IS NULL THEN
    SELECT NULLIF(btrim(s.timezone), '') INTO v_tz
    FROM public.schedule_settings s
    WHERE s.organization_id = v_org_id
    LIMIT 1;
    IF v_tz IS NULL THEN
      v_tz := 'Europe/Lisbon';
    ELSE
      BEGIN
        PERFORM now() AT TIME ZONE v_tz;
      EXCEPTION WHEN invalid_parameter_value THEN
        v_tz := 'Europe/Lisbon';
      END;
    END IF;
  END IF;

  v_day_start := p_date::TIMESTAMP AT TIME ZONE v_tz;
  v_day_end := (p_date + 1)::TIMESTAMP AT TIME ZONE v_tz;

  -- So "Dia inteiro". Ferias com horas tratam-se horario a horario em quem chama.
  RETURN EXISTS (
    SELECT 1
    FROM public.schedule_items si
    JOIN public.schedule_boards b
      ON b.id = si.board_id
     AND b.board_type = 'time_off'
    WHERE si.user_id = v_user_id
      AND si.organization_id = v_org_id
      AND si.all_day = true
      AND si.status <> 'cancelled'
      AND si.approval_status IS DISTINCT FROM 'rejected'
      AND si.start_datetime < v_day_end
      AND si.end_datetime > v_day_start
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.resource_has_full_day_time_off_on(p_resource_id uuid, p_date date, p_tz text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.resource_has_full_day_time_off_on(p_resource_id uuid, p_date date, p_tz text) TO service_role;
COMMENT ON FUNCTION public.resource_has_full_day_time_off_on(p_resource_id uuid, p_date date, p_tz text) IS 'Verdadeiro se a pessoa (user_id) do recurso tem ferias de DIA INTEIRO (all_day = true), nao canceladas e nao rejeitadas, num quadro time_off da mesma organizacao, que sobreponham o dia local p_date (fuso da organizacao, ou p_tz). Ferias com horas (all_day false ou NULL) nao contam aqui: bloqueiam so a sua faixa, verificada horario a horario por quem chama.';

CREATE OR REPLACE FUNCTION public.rpc_catalog_dismiss(p_supplier_id uuid, p_catalog_item_ids uuid[], p_dismissed boolean DEFAULT true, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org   uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  v_actor uuid := public.current_business_user_id();
  l       public.supplier_account_links;
  v_n     integer;
  v_reason text := NULLIF(left(btrim(COALESCE(p_reason, '')), 500), '');
BEGIN
  IF NOT public.has_anew_permission(auth.uid(), 'products.edit') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.edit)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF p_catalog_item_ids IS NULL OR cardinality(p_catalog_item_ids) = 0 THEN
    RAISE EXCEPTION 'Indique os artigos' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF cardinality(p_catalog_item_ids) > 5000 THEN
    RAISE EXCEPTION 'Demasiados artigos (máx. 5000)' USING ERRCODE = 'check_violation', HINT = 'too_many_rows';
  END IF;
  SELECT * INTO l FROM public.supplier_account_links WHERE supplier_id = p_supplier_id AND status = 'active';
  IF l.id IS NULL THEN
    RAISE EXCEPTION 'Este fornecedor não está ligado ao portal' USING ERRCODE = 'no_data_found', HINT = 'not_linked';
  END IF;

  IF COALESCE(p_dismissed, true) THEN
    INSERT INTO public.supplier_catalog_dismissals (organization_id, link_id, catalog_item_id, dismissed_by, reason)
    SELECT v_org, l.id, ci.id, v_actor, v_reason
    FROM public.supplier_catalog_items ci
    WHERE ci.supplier_account_id = l.supplier_account_id AND ci.id = ANY (p_catalog_item_ids)
    ON CONFLICT (link_id, catalog_item_id) DO NOTHING;
  ELSE
    DELETE FROM public.supplier_catalog_dismissals
    WHERE link_id = l.id AND catalog_item_id = ANY (p_catalog_item_ids);
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  RETURN jsonb_build_object('changed', v_n);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_catalog_dismiss(p_supplier_id uuid, p_catalog_item_ids uuid[], p_dismissed boolean, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_dismiss(p_supplier_id uuid, p_catalog_item_ids uuid[], p_dismissed boolean, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_dismiss(p_supplier_id uuid, p_catalog_item_ids uuid[], p_dismissed boolean, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_catalog_link(p_supplier_id uuid, p_catalog_item_id uuid, p_product_id uuid, p_uom_id uuid DEFAULT NULL::uuid, p_apply_catalog_price boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org      uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  v_actor    uuid := public.current_business_user_id();
  l          public.supplier_account_links;
  ci         public.supplier_catalog_items;
  p          record;
  isup       public.item_suppliers;
  v_other    record;
  v_created  boolean := false;
  v_warn     jsonb := '[]'::jsonb;
  v_codes    jsonb := '[]'::jsonb;
  v_price    boolean := COALESCE(p_apply_catalog_price, true);
  v_pref     boolean;
  v_code_id  uuid;
  v_old_price numeric;
  v_old_ccy  text;
  v_price_upd boolean := false;
  v_cost     jsonb;
BEGIN
  IF NOT public.has_anew_permission(auth.uid(), 'products.edit') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.edit)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  SELECT * INTO l FROM public.supplier_account_links WHERE supplier_id = p_supplier_id AND status = 'active';
  IF l.id IS NULL THEN
    RAISE EXCEPTION 'Este fornecedor não está ligado ao portal' USING ERRCODE = 'no_data_found', HINT = 'not_linked';
  END IF;
  SELECT * INTO ci FROM public.supplier_catalog_items WHERE id = p_catalog_item_id AND supplier_account_id = l.supplier_account_id;
  IF ci.id IS NULL THEN
    RAISE EXCEPTION 'Artigo do catálogo não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  SELECT id, name, sku, barcode INTO p FROM public.products
  WHERE id = p_product_id AND organization_id = v_org AND deleted_at IS NULL AND NOT is_deleted
  FOR NO KEY UPDATE;
  IF p.id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  -- F3.4b: usar o preço do catálogo muda preços (ligação e custo do produto):
  -- a mesma permissão de aceitar um pedido de alteração de preço.
  IF v_price AND ci.base_price IS NOT NULL
     AND NOT public.has_anew_permission(auth.uid(), 'products.manage_prices') THEN
    RAISE EXCEPTION 'Sem permissão para alterar preços: liga sem usar o preço do catálogo'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_price_permission';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('catalog_link:' || p_supplier_id::text, 0));
  PERFORM set_config('app.audit_source', 'supplier_catalog', true);

  -- Este artigo já está ligado?
  SELECT * INTO isup FROM public.item_suppliers
  WHERE supplier_id = p_supplier_id AND catalog_item_id = ci.id AND deleted_at IS NULL;
  IF isup.id IS NOT NULL THEN
    IF isup.product_id = p.id THEN
      RETURN jsonb_build_object('item_supplier_id', isup.id, 'created', false, 'already_linked', true,
                                'codes', '[]'::jsonb, 'warnings', '[]'::jsonb,
                                'item_supplier_price_updated', false, 'product_cost_updated', false,
                                'product_cost_reason', 'already_linked', 'product_cost_message', NULL);
    END IF;
    SELECT name, sku INTO v_other FROM public.products WHERE id = isup.product_id;
    RAISE EXCEPTION 'A referência «%» já está ligada ao produto «%» (%)', ci.supplier_ref, v_other.name, v_other.sku
      USING ERRCODE = 'unique_violation', HINT = 'conflict';
  END IF;

  -- A referência já aponta para outro produto em product_codes?
  SELECT pr.name, pr.sku INTO v_other
  FROM public.product_codes pc JOIN public.products pr ON pr.id = pc.product_id
  WHERE pc.organization_id = v_org AND pc.supplier_id = p_supplier_id AND pc.kind = 'supplier_ref'
    AND pc.deleted_at IS NULL AND pc.code_key = ci.ref_key AND pc.product_id <> p.id
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'A referência «%» já está associada ao produto «%» (%) nos códigos do fornecedor', ci.supplier_ref, v_other.name, v_other.sku
      USING ERRCODE = 'unique_violation', HINT = 'conflict';
  END IF;

  -- Linha existente (produto, fornecedor, unidade)?
  SELECT * INTO isup FROM public.item_suppliers
  WHERE product_id = p.id AND supplier_id = p_supplier_id AND deleted_at IS NULL
    AND COALESCE(uom_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_uom_id, '00000000-0000-0000-0000-000000000000'::uuid)
  FOR UPDATE;

  IF isup.id IS NOT NULL THEN
    IF isup.catalog_item_id IS NOT NULL THEN
      SELECT supplier_ref INTO v_other FROM public.supplier_catalog_items WHERE id = isup.catalog_item_id;
      RAISE EXCEPTION 'Este produto já está ligado a outra referência do catálogo («%»)', v_other.supplier_ref
        USING ERRCODE = 'unique_violation', HINT = 'conflict';
    END IF;
    IF isup.supplier_sku IS NOT NULL AND public.fn_product_code_key(isup.supplier_sku) IS DISTINCT FROM ci.ref_key THEN
      v_warn := v_warn || jsonb_build_array(format('Referência do fornecedor alterada de «%s» para «%s»', isup.supplier_sku, ci.supplier_ref));
    END IF;
    v_old_price := isup.purchase_price;
    v_old_ccy := isup.currency;
    UPDATE public.item_suppliers SET
      catalog_item_id = ci.id,
      supplier_sku = ci.supplier_ref,
      purchase_price = CASE WHEN v_price AND ci.base_price IS NOT NULL THEN ci.base_price ELSE purchase_price END,
      currency = CASE WHEN v_price AND ci.base_price IS NOT NULL THEN ci.currency ELSE currency END,
      moq = COALESCE(moq, ci.moq),
      lead_time_days = COALESCE(lead_time_days, ci.lead_time_days),
      updated_at = now()
    WHERE id = isup.id
    RETURNING * INTO isup;
    v_price_upd := v_price AND ci.base_price IS NOT NULL
                   AND (isup.purchase_price IS DISTINCT FROM v_old_price OR isup.currency IS DISTINCT FROM v_old_ccy);
  ELSE
    v_pref := NOT EXISTS (SELECT 1 FROM public.item_suppliers WHERE product_id = p.id AND deleted_at IS NULL);
    INSERT INTO public.item_suppliers (
      organization_id, item_type, product_id, supplier_id, uom_id, supplier_sku, purchase_price,
      currency, moq, lead_time_days, is_preferred, is_active, created_by, catalog_item_id
    ) VALUES (
      v_org, 'product', p.id, p_supplier_id, p_uom_id, ci.supplier_ref,
      CASE WHEN v_price THEN ci.base_price END, ci.currency, ci.moq, ci.lead_time_days,
      v_pref, true, v_actor, ci.id
    ) RETURNING * INTO isup;
    v_created := true;
    v_price_upd := v_price AND ci.base_price IS NOT NULL;
  END IF;

  -- F3.4b: com o preço do catálogo, o custo do produto segue a mesma regra
  -- de aceitar um preço (ligação preferencial, empresa principal, unidade).
  IF v_price AND ci.base_price IS NOT NULL THEN
    v_cost := public.fn_apply_product_cost_from_supplier(isup.id, v_org, isup.purchase_price, isup.currency, v_actor);
  ELSE
    v_cost := jsonb_build_object(
      'product_cost_updated', false, 'product_cost_rows', 0,
      'product_cost_reason', CASE WHEN v_price THEN 'no_catalog_price' ELSE 'catalog_price_not_used' END,
      'product_cost_message', CASE WHEN v_price THEN 'O artigo não tem preço no catálogo: preços não mudaram'
                                   ELSE 'Preço do catálogo não usado: preços não mudaram' END,
      'new_unit_cost', NULL, 'units_per_purchase_uom', NULL);
  END IF;

  -- product_codes: referência do fornecedor
  IF NOT EXISTS (SELECT 1 FROM public.product_codes
                 WHERE organization_id = v_org AND supplier_id = p_supplier_id AND kind = 'supplier_ref'
                   AND deleted_at IS NULL AND code_key = ci.ref_key) THEN
    v_code_id := gen_random_uuid();
    INSERT INTO public.product_codes (id, organization_id, code, kind, product_id, uom_id, supplier_id, source, context, created_by)
    VALUES (v_code_id, v_org, ci.supplier_ref, 'supplier_ref', p.id, p_uom_id, p_supplier_id, 'catalog',
            jsonb_build_object('catalog_item_id', ci.id, 'link_id', l.id), v_actor);
    v_codes := v_codes || jsonb_build_array(jsonb_build_object('id', v_code_id, 'kind', 'supplier_ref', 'code', ci.supplier_ref));
  END IF;

  -- product_codes: código de barras do artigo, se faltar no produto e estiver livre
  IF ci.barcode_key IS NOT NULL
     AND public.fn_product_code_key(p.barcode) IS DISTINCT FROM ci.barcode_key
     AND NOT EXISTS (SELECT 1 FROM public.product_codes
                     WHERE organization_id = v_org AND kind = 'barcode' AND deleted_at IS NULL
                       AND code_key = ci.barcode_key AND product_id = p.id) THEN
    SELECT pr.name, pr.sku INTO v_other
    FROM public.products pr
    WHERE pr.organization_id = v_org AND pr.id <> p.id AND pr.deleted_at IS NULL AND NOT pr.is_deleted
      AND public.fn_product_code_key(pr.barcode) = ci.barcode_key
    UNION ALL
    SELECT pr.name, pr.sku
    FROM public.product_codes pc JOIN public.products pr ON pr.id = pc.product_id
    WHERE pc.organization_id = v_org AND pc.kind = 'barcode' AND pc.deleted_at IS NULL
      AND pc.code_key = ci.barcode_key AND pc.product_id <> p.id
    LIMIT 1;
    IF FOUND THEN
      v_warn := v_warn || jsonb_build_array(format('O código de barras %s já está no produto «%s» (%s); não foi associado', ci.barcode, v_other.name, v_other.sku));
    ELSE
      v_code_id := gen_random_uuid();
      INSERT INTO public.product_codes (id, organization_id, code, kind, product_id, uom_id, supplier_id, source, context, created_by)
      VALUES (v_code_id, v_org, ci.barcode, 'barcode', p.id, p_uom_id, p_supplier_id, 'catalog',
              jsonb_build_object('catalog_item_id', ci.id, 'link_id', l.id), v_actor);
      v_codes := v_codes || jsonb_build_array(jsonb_build_object('id', v_code_id, 'kind', 'barcode', 'code', ci.barcode));
    END IF;
  END IF;

  -- Ligado deixa de estar "dispensado".
  DELETE FROM public.supplier_catalog_dismissals WHERE link_id = l.id AND catalog_item_id = ci.id;

  RETURN jsonb_build_object(
    'item_supplier_id', isup.id,
    'created', v_created,
    'already_linked', false,
    'is_preferred', isup.is_preferred,
    'codes', v_codes,
    'warnings', v_warn,
    'item_supplier_price_updated', v_price_upd
  ) || v_cost;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_catalog_link(p_supplier_id uuid, p_catalog_item_id uuid, p_product_id uuid, p_uom_id uuid, p_apply_catalog_price boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_link(p_supplier_id uuid, p_catalog_item_id uuid, p_product_id uuid, p_uom_id uuid, p_apply_catalog_price boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_link(p_supplier_id uuid, p_catalog_item_id uuid, p_product_id uuid, p_uom_id uuid, p_apply_catalog_price boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_catalog_link_suggestions(p_supplier_id uuid, p_catalog_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  v_acc uuid;
  v_res jsonb;
BEGIN
  IF NOT public.has_anew_permission(auth.uid(), 'products.view') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.view)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF p_catalog_item_ids IS NULL OR cardinality(p_catalog_item_ids) = 0 THEN
    RETURN jsonb_build_object('items', '[]'::jsonb);
  END IF;
  IF cardinality(p_catalog_item_ids) > 200 THEN
    RAISE EXCEPTION 'Demasiados artigos (máx. 200 por pedido)' USING ERRCODE = 'check_violation', HINT = 'too_many_rows';
  END IF;

  SELECT supplier_account_id INTO v_acc FROM public.supplier_account_links
  WHERE supplier_id = p_supplier_id AND status = 'active';
  IF v_acc IS NULL THEN
    RAISE EXCEPTION 'Este fornecedor não está ligado ao portal' USING ERRCODE = 'no_data_found', HINT = 'not_linked';
  END IF;

  WITH ci AS (
    SELECT c.id, c.ref_key, c.barcode_key, c.name,
           lower(extensions.unaccent('extensions.unaccent'::regdictionary, c.name)) AS uname
    FROM public.supplier_catalog_items c
    WHERE c.supplier_account_id = v_acc AND c.id = ANY (p_catalog_item_ids)
  ),
  cand AS (
    SELECT ci.id AS catalog_item_id, isup.product_id, 'supplier_sku'::text AS reason, 1.00::numeric AS score, isup.id AS item_supplier_id
    FROM ci
    JOIN public.item_suppliers isup
      ON isup.supplier_id = p_supplier_id AND isup.deleted_at IS NULL AND isup.product_id IS NOT NULL
     AND isup.catalog_item_id IS NULL
     AND public.fn_product_code_key(isup.supplier_sku) = ci.ref_key
    UNION ALL
    SELECT ci.id, pc.product_id, 'supplier_ref_code', 0.98, NULL
    FROM ci
    JOIN public.product_codes pc
      ON pc.organization_id = v_org AND pc.supplier_id = p_supplier_id AND pc.kind = 'supplier_ref'
     AND pc.deleted_at IS NULL AND pc.code_key = ci.ref_key
    UNION ALL
    SELECT ci.id, p.id, 'barcode', 0.95, NULL
    FROM ci
    JOIN public.products p
      ON ci.barcode_key IS NOT NULL AND p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
     AND public.fn_product_code_key(p.barcode) = ci.barcode_key
    UNION ALL
    SELECT ci.id, pc.product_id, 'barcode', 0.95, NULL
    FROM ci
    JOIN public.product_codes pc
      ON ci.barcode_key IS NOT NULL AND pc.organization_id = v_org AND pc.kind = 'barcode'
     AND pc.deleted_at IS NULL AND pc.code_key = ci.barcode_key
    UNION ALL
    SELECT ci.id, n.id, 'name', n.score, NULL
    FROM ci
    CROSS JOIN LATERAL (
      SELECT p.id,
             round(extensions.similarity(lower(extensions.unaccent('extensions.unaccent'::regdictionary, p.name)), ci.uname)::numeric, 3) AS score
      FROM public.products p
      WHERE p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
        AND p.name OPERATOR(extensions.%) ci.name
      ORDER BY 2 DESC, p.id
      LIMIT 10
    ) n
    WHERE n.score >= 0.30
  ),
  best AS (
    SELECT DISTINCT ON (c.catalog_item_id, c.product_id)
           c.catalog_item_id, c.product_id, c.reason, c.score, c.item_supplier_id
    FROM cand c
    JOIN public.products p ON p.id = c.product_id AND p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
    WHERE NOT EXISTS (
      SELECT 1 FROM public.item_suppliers x
      WHERE x.supplier_id = p_supplier_id AND x.catalog_item_id = c.catalog_item_id
        AND x.product_id = c.product_id AND x.deleted_at IS NULL)
    ORDER BY c.catalog_item_id, c.product_id, c.score DESC, c.item_supplier_id NULLS LAST
  ),
  ranked AS (
    SELECT b.*, row_number() OVER (PARTITION BY b.catalog_item_id ORDER BY b.score DESC, b.product_id) AS rn
    FROM best b
  )
  SELECT jsonb_build_object('items', COALESCE(jsonb_agg(jsonb_build_object(
           'catalog_item_id', ci.id,
           'suggestions', COALESCE((
             SELECT jsonb_agg(jsonb_build_object(
                      'product_id', p.id,
                      'product_name', p.name,
                      'product_sku', p.sku,
                      'product_barcode', p.barcode,
                      'reason', r.reason,
                      'score', r.score,
                      'exact', r.reason <> 'name',
                      'item_supplier_id', r.item_supplier_id) ORDER BY r.rn)
             FROM ranked r JOIN public.products p ON p.id = r.product_id
             WHERE r.catalog_item_id = ci.id AND r.rn <= 5
           ), '[]'::jsonb)) ORDER BY ci.id), '[]'::jsonb))
  INTO v_res
  FROM ci;

  RETURN v_res;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_catalog_link_suggestions(p_supplier_id uuid, p_catalog_item_ids uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_link_suggestions(p_supplier_id uuid, p_catalog_item_ids uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_link_suggestions(p_supplier_id uuid, p_catalog_item_ids uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_catalog_unlink(p_supplier_id uuid, p_catalog_item_id uuid, p_remove_item_supplier boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org   uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  v_actor uuid := public.current_business_user_id();
  v_n     integer;
  v_codes integer;
BEGIN
  IF NOT public.has_anew_permission(auth.uid(), 'products.edit') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.edit)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  PERFORM set_config('app.audit_source', 'supplier_catalog', true);

  IF COALESCE(p_remove_item_supplier, false) THEN
    UPDATE public.item_suppliers
       SET catalog_item_id = NULL, deleted_at = now(), deleted_by = v_actor, is_preferred = false, updated_at = now()
     WHERE supplier_id = p_supplier_id AND organization_id = v_org
       AND catalog_item_id = p_catalog_item_id AND deleted_at IS NULL;
  ELSE
    UPDATE public.item_suppliers
       SET catalog_item_id = NULL, updated_at = now()
     WHERE supplier_id = p_supplier_id AND organization_id = v_org
       AND catalog_item_id = p_catalog_item_id AND deleted_at IS NULL;
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'Este artigo não está ligado a nenhum produto deste fornecedor' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  UPDATE public.product_codes
     SET deleted_at = now(), deleted_by = v_actor, delete_reason = 'Ligação ao catálogo do fornecedor removida'
   WHERE organization_id = v_org AND supplier_id = p_supplier_id AND source = 'catalog'
     AND deleted_at IS NULL AND context ->> 'catalog_item_id' = p_catalog_item_id::text;
  GET DIAGNOSTICS v_codes = ROW_COUNT;

  RETURN jsonb_build_object('unlinked', v_n, 'codes_removed', v_codes,
                            'item_supplier_removed', COALESCE(p_remove_item_supplier, false));
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_catalog_unlink(p_supplier_id uuid, p_catalog_item_id uuid, p_remove_item_supplier boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_unlink(p_supplier_id uuid, p_catalog_item_id uuid, p_remove_item_supplier boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_catalog_unlink(p_supplier_id uuid, p_catalog_item_id uuid, p_remove_item_supplier boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_client_order_list_readiness(p_organization_id uuid, p_contract_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(contract_id uuid, lines_ready integer, units_ready numeric, units_in_stock_reserved numeric, units_on_po numeric, units_missing numeric, units_served numeric, units_received numeric, units_needed numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Utilizador não autenticado' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id é obrigatório' USING ERRCODE = 'check_violation';
  END IF;

  -- Mesma verificação que rpc_list_client_order_documents.
  IF p_organization_id NOT IN (SELECT public.get_user_visible_org_ids(v_uid))
     OR NOT COALESCE(public.has_anew_permission(v_uid, 'client_orders.view'), false) THEN
    RAISE EXCEPTION 'Sem permissão para ver encomendas de clientes desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH r AS MATERIALIZED (
    -- Uma só passagem pela reserva FIFO da organização inteira.
    SELECT
      f.contract_id  AS r_contract_id,
      f.product_id   AS r_product_id,
      f.is_served    AS r_is_served,
      COALESCE(f.qty_needed,   0) AS r_needed,
      COALESCE(f.qty_served,   0) AS r_served,
      COALESCE(f.qty_ordered,  0) AS r_ordered,
      COALESCE(f.qty_received, 0) AS r_received,
      COALESCE(f.qty_reserved, 0) AS r_reserved,
      COALESCE(f.qty_missing,  0) AS r_missing
    FROM public.fn_client_order_line_reservations(p_organization_id, NULL) f
  ),
  rc AS (
    -- Contratos da lista (filtros de rpc_list_client_order_documents).
    SELECT cc.id AS rc_contract_id
    FROM public.client_contracts cc
    WHERE cc.organization_id = p_organization_id
      AND cc.deleted_at IS NULL
      AND cc.status = ANY (ARRAY['signed', 'assinado'])
      AND (p_contract_ids IS NULL OR cc.id = ANY (p_contract_ids))
  ),
  lx AS (
    SELECT
      r.*,
      -- Linha em aberto: negação da regra de concluída de rpc_inventory_today.
      NOT (
        r.r_is_served
        OR (r.r_reserved = 0
            AND r.r_served = 0
            AND r.r_missing = 0
            AND r.r_ordered > 0
            AND r.r_received >= r.r_ordered)
      ) AS r_open
    FROM r
    JOIN rc ON rc.rc_contract_id = r.r_contract_id
    WHERE r.r_product_id IS NOT NULL
  ),
  agg AS (
    SELECT
      lx.r_contract_id AS a_contract_id,
      count(*) FILTER (WHERE lx.r_open AND lx.r_reserved > 0)::integer           AS a_lines_ready,
      COALESCE(sum(lx.r_reserved) FILTER (WHERE lx.r_open AND lx.r_reserved > 0), 0) AS a_units_ready,
      COALESCE(sum(lx.r_reserved), 0)                                            AS a_units_reserved,
      COALESCE(sum(GREATEST(0, lx.r_ordered - lx.r_received)) FILTER (WHERE lx.r_open), 0) AS a_units_on_po,
      COALESCE(sum(lx.r_missing) FILTER (WHERE lx.r_open), 0)                    AS a_units_missing,
      COALESCE(sum(lx.r_served + lx.r_received), 0)                              AS a_units_served,
      COALESCE(sum(lx.r_received), 0)                                            AS a_units_received,
      COALESCE(sum(lx.r_needed), 0)                                              AS a_units_needed
    FROM lx
    GROUP BY lx.r_contract_id
  )
  SELECT
    rc.rc_contract_id,
    COALESCE(a.a_lines_ready, 0),
    COALESCE(a.a_units_ready, 0)::numeric,
    COALESCE(a.a_units_reserved, 0)::numeric,
    COALESCE(a.a_units_on_po, 0)::numeric,
    COALESCE(a.a_units_missing, 0)::numeric,
    COALESCE(a.a_units_served, 0)::numeric,
    COALESCE(a.a_units_received, 0)::numeric,
    COALESCE(a.a_units_needed, 0)::numeric
  FROM rc
  LEFT JOIN agg a ON a.a_contract_id = rc.rc_contract_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_client_order_list_readiness(p_organization_id uuid, p_contract_ids uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_client_order_list_readiness(p_organization_id uuid, p_contract_ids uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_client_order_list_readiness(p_organization_id uuid, p_contract_ids uuid[]) TO service_role;
COMMENT ON FUNCTION public.rpc_client_order_list_readiness(p_organization_id uuid, p_contract_ids uuid[]) IS 'Prontidão de expedição por Encomenda de Cliente (contratos assinados, não apagados, da organização; opcionalmente só p_contract_ids): linhas/unidades prontas a sair (reserva de stock em linhas em aberto, mesma regra de rpc_inventory_today.ready_to_ship), reservadas, em PO por receber, em falta, servidas, recebidas e necessárias (unidades base). Uma passagem por fn_client_order_line_reservations. Exige org visível e client_orders.view. Só leitura.';

CREATE OR REPLACE FUNCTION public.rpc_delivery_note_cancel(p_delivery_note_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid;
  v_note   public.supplier_delivery_notes%ROWTYPE;
  v_reason text := nullif(btrim(COALESCE(p_reason, '')), '');
  v_active integer;
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT * INTO v_note FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  IF NOT FOUND
     OR v_note.organization_id NOT IN (SELECT public.get_user_visible_org_ids(auth.uid())) THEN
    RAISE EXCEPTION 'Guia do fornecedor não encontrada' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT public.has_anew_permission(auth.uid(), 'receiving.manage_delivery_notes') THEN  -- NOVO (20261210130000)
    RAISE EXCEPTION 'Sem permissão para cancelar guias desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_note.status = 'cancelled' THEN
    RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', false);
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Indica o motivo para cancelar a guia' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_reason) > 1000 THEN
    RAISE EXCEPTION 'Motivo demasiado longo' USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO v_active
  FROM public.purchase_order_receipts
  WHERE delivery_note_id = p_delivery_note_id AND kind = 'receipt' AND reverted_at IS NULL;
  IF v_active > 0 THEN
    RAISE EXCEPTION 'A guia % tem % receção(ões) ativa(s) — reverte-as primeiro na encomenda', v_note.note_number, v_active
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.supplier_delivery_notes
  SET status        = 'cancelled',
      cancelled_at  = now(),
      cancelled_by  = v_actor,
      cancel_reason = v_reason,
      history       = history || jsonb_build_array(jsonb_build_object(
                        'action', 'cancel', 'at', now(), 'by', v_actor, 'reason', v_reason, 'previous_status', status)),
      updated_at    = clock_timestamp()
  WHERE id = p_delivery_note_id;

  RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_delivery_note_cancel(p_delivery_note_id uuid, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_cancel(p_delivery_note_id uuid, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_cancel(p_delivery_note_id uuid, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_delivery_note_close(p_delivery_note_id uuid, p_notes text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor   uuid;
  v_note    public.supplier_delivery_notes%ROWTYPE;
  v_notes   text := nullif(btrim(COALESCE(p_notes, '')), '');
  v_summary jsonb;
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT * INTO v_note FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  IF NOT FOUND
     OR v_note.organization_id NOT IN (SELECT public.get_user_visible_org_ids(auth.uid())) THEN
    RAISE EXCEPTION 'Guia do fornecedor não encontrada' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT public.has_anew_permission(auth.uid(), 'receiving.manage_delivery_notes') THEN  -- NOVO (20261210130000)
    RAISE EXCEPTION 'Sem permissão para fechar guias desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_note.status = 'closed' THEN
    RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', false);
  END IF;
  IF v_note.status = 'cancelled' THEN
    RAISE EXCEPTION 'A guia % está cancelada', v_note.note_number USING ERRCODE = 'check_violation';
  END IF;
  IF p_expected_updated_at IS NOT NULL AND p_expected_updated_at IS DISTINCT FROM v_note.updated_at THEN
    RAISE EXCEPTION 'A guia % foi alterada entretanto — abre-a de novo antes de fechar', v_note.note_number
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF char_length(v_notes) > 2000 THEN
    RAISE EXCEPTION 'Nota de fecho demasiado longa' USING ERRCODE = 'check_violation';
  END IF;

  v_summary := public.fn_delivery_note_summary(p_delivery_note_id);
  IF (v_summary ->> 'has_divergences')::boolean AND v_notes IS NULL THEN
    RAISE EXCEPTION 'A guia % tem divergências (% produto(s)) — indica uma nota para fechar',
      v_note.note_number, v_summary -> 'totals' ->> 'divergences'
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.supplier_delivery_notes
  SET status        = 'closed',
      closed_at     = now(),
      closed_by     = v_actor,
      close_notes   = v_notes,
      close_summary = v_summary,
      history       = history || jsonb_build_array(jsonb_build_object(
                        'action', 'close', 'at', now(), 'by', v_actor, 'notes', v_notes,
                        'divergences', v_summary -> 'totals' -> 'divergences')),
      updated_at    = clock_timestamp()
  WHERE id = p_delivery_note_id;

  RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_delivery_note_close(p_delivery_note_id uuid, p_notes text, p_expected_updated_at timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_close(p_delivery_note_id uuid, p_notes text, p_expected_updated_at timestamp with time zone) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_close(p_delivery_note_id uuid, p_notes text, p_expected_updated_at timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_delivery_note_get(p_delivery_note_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_note    public.supplier_delivery_notes%ROWTYPE;
  v_summary jsonb;
BEGIN
  SELECT * INTO v_note FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id;
  IF NOT FOUND
     OR v_note.organization_id NOT IN (SELECT public.get_user_visible_org_ids(auth.uid())) THEN
    RAISE EXCEPTION 'Guia do fornecedor não encontrada' USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT (public.has_anew_permission(auth.uid(), 'purchase_orders.view')
          OR public.has_anew_permission(auth.uid(), 'purchase_orders.receive')) THEN
    RAISE EXCEPTION 'Sem permissão para consultar guias desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_summary := public.fn_delivery_note_summary(p_delivery_note_id);

  RETURN jsonb_build_object(
    'id',              v_note.id,
    'organization_id', v_note.organization_id,
    'supplier_id',     v_note.supplier_id,
    'supplier_name',   (SELECT name FROM public.suppliers WHERE id = v_note.supplier_id),
    'note_number',     v_note.note_number,
    'document_date',   v_note.document_date,
    'notes',           v_note.notes,
    'status',          v_note.status,
    'created_by',      v_note.created_by,
    'created_at',      v_note.created_at,
    'updated_at',      v_note.updated_at,
    'closed_at',       v_note.closed_at,
    'closed_by',       v_note.closed_by,
    'close_notes',     v_note.close_notes,
    'close_summary',   v_note.close_summary,
    'cancelled_at',    v_note.cancelled_at,
    'cancelled_by',    v_note.cancelled_by,
    'cancel_reason',   v_note.cancel_reason,
    'history',         v_note.history,
    'purchase_orders', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'purchase_order_id', po.id,
               'order_number',      po.order_number,
               'status',            po.status,
               'deleted',           po.deleted_at IS NOT NULL,
               'expected_delivery', po.expected_delivery,
               'source_type',       po.source_type,
               'source_id',         po.source_id
             ) ORDER BY po.order_number, po.id), '[]'::jsonb)
      FROM public.supplier_delivery_note_orders o
      JOIN public.purchase_orders po ON po.id = o.purchase_order_id
      WHERE o.delivery_note_id = p_delivery_note_id),
    'lines', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id',                     l.id,
               'position',               l.position,
               'product_id',             l.product_id,
               'product_name',           p.name,
               'sku',                    p.sku,
               'uom_id',                 l.uom_id,
               'uom_code',               (SELECT code FROM public.uom WHERE id = COALESCE(l.uom_id, p.uom_id)),
               'units_per_uom',          l.units_per_uom,
               'quantity',               l.quantity,
               'units',                  l.quantity * l.units_per_uom,
               'purchase_order_item_id', l.purchase_order_item_id,
               'order_number',           po.order_number,
               'description',            l.description
             ) ORDER BY l.position, l.id), '[]'::jsonb)
      FROM public.supplier_delivery_note_lines l
      LEFT JOIN public.products p ON p.id = l.product_id
      LEFT JOIN public.purchase_order_items poi ON poi.id = l.purchase_order_item_id
      LEFT JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
      WHERE l.delivery_note_id = p_delivery_note_id),
    'summary',         v_summary,
    -- Fechada e o recebido mudou depois (p.ex. reversão de uma receção).
    'changed_since_close', (v_note.status = 'closed'
                            AND (v_note.close_summary -> 'products') IS DISTINCT FROM (v_summary -> 'products'))
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_delivery_note_get(p_delivery_note_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_get(p_delivery_note_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_get(p_delivery_note_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_delivery_note_reopen(p_delivery_note_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid;
  v_note   public.supplier_delivery_notes%ROWTYPE;
  v_reason text := nullif(btrim(COALESCE(p_reason, '')), '');
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT * INTO v_note FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  IF NOT FOUND
     OR v_note.organization_id NOT IN (SELECT public.get_user_visible_org_ids(auth.uid())) THEN
    RAISE EXCEPTION 'Guia do fornecedor não encontrada' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT public.has_anew_permission(auth.uid(), 'receiving.manage_delivery_notes') THEN  -- NOVO (20261210130000)
    RAISE EXCEPTION 'Sem permissão para reabrir guias desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_note.status = 'open' THEN
    RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', false);
  END IF;
  IF v_note.status = 'cancelled' THEN
    RAISE EXCEPTION 'A guia % está cancelada', v_note.note_number USING ERRCODE = 'check_violation';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Indica o motivo para reabrir a guia' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_reason) > 1000 THEN
    RAISE EXCEPTION 'Motivo demasiado longo' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.supplier_delivery_notes
  SET status        = 'open',
      history       = history || jsonb_build_array(jsonb_build_object(
                        'action', 'reopen', 'at', now(), 'by', v_actor, 'reason', v_reason,
                        'previous_close', jsonb_build_object(
                          'closed_at', closed_at, 'closed_by', closed_by,
                          'close_notes', close_notes, 'close_summary', close_summary))),
      closed_at     = NULL,
      closed_by     = NULL,
      close_notes   = NULL,
      close_summary = NULL,
      updated_at    = clock_timestamp()
  WHERE id = p_delivery_note_id;

  RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('changed', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_delivery_note_reopen(p_delivery_note_id uuid, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_reopen(p_delivery_note_id uuid, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_reopen(p_delivery_note_id uuid, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_delivery_note_save(p_delivery_note_id uuid, p_supplier_id uuid, p_note_number text, p_document_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_purchase_order_ids uuid[] DEFAULT NULL::uuid[], p_lines jsonb DEFAULT NULL::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor      uuid;
  v_org        uuid;
  v_number     text := btrim(COALESCE(p_note_number, ''));
  v_notes      text := nullif(btrim(COALESCE(p_notes, '')), '');
  v_cur        public.supplier_delivery_notes%ROWTYPE;
  v_exists     boolean;
  v_cur_pos    uuid[];
  v_new_pos    uuid[];
  v_final_pos  uuid[];
  v_po         record;
  v_el         jsonb;
  v_ord        bigint;
  v_prod       record;
  v_poi        record;
  v_uom        uuid;
  v_factor     integer;
  v_qty        numeric;
  v_poi_id     uuid;
  v_desc       text;
  v_lines      jsonb := '[]'::jsonb;
  v_cur_lines  jsonb;
  v_dup        uuid;
  v_removed    text;
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF p_delivery_note_id IS NULL THEN
    RAISE EXCEPTION 'Identificador da guia em falta' USING ERRCODE = 'check_violation';
  END IF;

  SELECT organization_id INTO v_org
  FROM public.suppliers
  WHERE id = p_supplier_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_org NOT IN (SELECT public.get_user_visible_org_ids(auth.uid()))
     OR NOT public.has_anew_permission(auth.uid(), 'receiving.manage_delivery_notes') THEN  -- NOVO (20261210130000)
    RAISE EXCEPTION 'Sem permissão para registar guias desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_number = '' THEN
    RAISE EXCEPTION 'Indica o número da guia' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_number) > 100 THEN
    RAISE EXCEPTION 'Número da guia demasiado longo' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_notes) > 2000 THEN
    RAISE EXCEPTION 'Notas da guia demasiado longas' USING ERRCODE = 'check_violation';
  END IF;

  -- Guia existente: trancada até ao fim (espera pelas leituras em curso).
  SELECT * INTO v_cur FROM public.supplier_delivery_notes WHERE id = p_delivery_note_id FOR UPDATE;
  v_exists := FOUND;

  IF v_exists THEN
    IF v_cur.organization_id IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'Esta guia pertence a outra organização' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_cur.supplier_id IS DISTINCT FROM p_supplier_id THEN
      RAISE EXCEPTION 'A guia % é de outro fornecedor (o fornecedor de uma guia não muda)', v_cur.note_number
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT COALESCE(array_agg(purchase_order_id ORDER BY purchase_order_id), ARRAY[]::uuid[]) INTO v_cur_pos
    FROM public.supplier_delivery_note_orders WHERE delivery_note_id = p_delivery_note_id;
  ELSE
    v_cur_pos := ARRAY[]::uuid[];
  END IF;

  -- POs pedidas: mesma organização e fornecedor; as que entram de novo não
  -- podem estar apagadas nem canceladas.
  IF p_purchase_order_ids IS NOT NULL THEN
    IF cardinality(p_purchase_order_ids) > 100 THEN
      RAISE EXCEPTION 'Demasiadas encomendas numa guia (máximo 100)' USING ERRCODE = 'check_violation';
    END IF;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_new_pos
    FROM unnest(p_purchase_order_ids) x WHERE x IS NOT NULL;

    FOR v_po IN
      SELECT x AS id, po.organization_id, po.supplier_id, po.order_number, po.status, po.deleted_at
      FROM unnest(v_new_pos) x
      LEFT JOIN public.purchase_orders po ON po.id = x
    LOOP
      IF v_po.organization_id IS DISTINCT FROM v_org THEN
        RAISE EXCEPTION 'Encomenda a fornecedor não encontrada nesta organização' USING ERRCODE = 'no_data_found';
      END IF;
      IF v_po.supplier_id IS DISTINCT FROM p_supplier_id THEN
        RAISE EXCEPTION '% é de outro fornecedor', v_po.order_number USING ERRCODE = 'check_violation';
      END IF;
      IF NOT (v_po.id = ANY (v_cur_pos)) AND (v_po.deleted_at IS NOT NULL OR v_po.status = 'cancelled') THEN
        RAISE EXCEPTION '% está apagada ou cancelada', v_po.order_number USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
    v_final_pos := v_new_pos;
  ELSE
    v_final_pos := v_cur_pos;
  END IF;

  -- Linhas anunciadas: normalizadas para comparar e gravar.
  IF p_lines IS NOT NULL THEN
    IF jsonb_typeof(p_lines) <> 'array' THEN
      RAISE EXCEPTION 'As linhas da guia têm de ser uma lista' USING ERRCODE = 'check_violation';
    END IF;
    IF jsonb_array_length(p_lines) > 500 THEN
      RAISE EXCEPTION 'Demasiadas linhas numa guia (máximo 500)' USING ERRCODE = 'check_violation';
    END IF;

    FOR v_el, v_ord IN SELECT e, o FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS t(e, o) LOOP
      IF jsonb_typeof(v_el) <> 'object' THEN
        RAISE EXCEPTION 'Linha % da guia inválida', v_ord USING ERRCODE = 'check_violation';
      END IF;
      BEGIN
        v_qty    := (v_el ->> 'quantity')::numeric;
        v_uom    := nullif(v_el ->> 'uom_id', '')::uuid;
        v_poi_id := nullif(v_el ->> 'purchase_order_item_id', '')::uuid;
        SELECT id, name, uom_id INTO v_prod
        FROM public.products
        WHERE id = nullif(v_el ->> 'product_id', '')::uuid
          AND organization_id = v_org AND deleted_at IS NULL AND NOT is_deleted;
      EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN
        RAISE EXCEPTION 'Linha % da guia com dados inválidos', v_ord USING ERRCODE = 'check_violation';
      END;
      IF v_prod.id IS NULL THEN
        RAISE EXCEPTION 'Linha % da guia: produto inválido para esta organização', v_ord USING ERRCODE = 'check_violation';
      END IF;
      IF v_qty IS NULL OR v_qty <= 0 OR v_qty > 1000000000 THEN
        RAISE EXCEPTION 'Linha % da guia: a quantidade tem de ser positiva', v_ord USING ERRCODE = 'check_violation';
      END IF;
      v_desc := nullif(btrim(COALESCE(v_el ->> 'description', '')), '');
      IF char_length(v_desc) > 500 THEN
        RAISE EXCEPTION 'Linha % da guia: descrição demasiado longa', v_ord USING ERRCODE = 'check_violation';
      END IF;

      -- Unidade da linha: a do produto se não indicada ou igual.
      IF v_uom IS NOT DISTINCT FROM v_prod.uom_id THEN
        v_uom := NULL;
      END IF;
      v_factor := public.fn_uom_units_per(v_uom, v_prod.id);

      IF v_poi_id IS NOT NULL THEN
        SELECT poi.id, poi.product_id, poi.item_type, COALESCE(poi.units_per_uom, 1) AS units_per_uom,
               poi.description, po.id AS po_id, po.supplier_id, po.order_number, po.organization_id
        INTO v_poi
        FROM public.purchase_order_items poi
        JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
        WHERE poi.id = v_poi_id AND po.deleted_at IS NULL;
        IF NOT FOUND OR v_poi.organization_id IS DISTINCT FROM v_org THEN
          RAISE EXCEPTION 'Linha % da guia: linha de encomenda não encontrada', v_ord USING ERRCODE = 'no_data_found';
        END IF;
        IF v_poi.supplier_id IS DISTINCT FROM p_supplier_id THEN
          RAISE EXCEPTION 'Linha % da guia: a linha "%" (%) é de outro fornecedor', v_ord, v_poi.description, v_poi.order_number
            USING ERRCODE = 'check_violation';
        END IF;
        IF v_poi.item_type <> 'product' OR v_poi.product_id IS DISTINCT FROM v_prod.id THEN
          RAISE EXCEPTION 'Linha % da guia: a linha "%" (%) não é deste produto', v_ord, v_poi.description, v_poi.order_number
            USING ERRCODE = 'check_violation';
        END IF;
        -- NOVO (códigos, decisão 7): a linha da guia pode estar noutra unidade
        -- da mesma base que a linha da PO (os dois fatores são sobre a unidade
        -- de stock do produto; fn_uom_units_per já recusou unidades de outra base).
        IF cardinality(v_final_pos) > 0 AND NOT (v_poi.po_id = ANY (v_final_pos)) THEN
          RAISE EXCEPTION 'Linha % da guia: % não está nas encomendas da guia', v_ord, v_poi.order_number
            USING ERRCODE = 'check_violation';
        END IF;
      END IF;

      v_lines := v_lines || jsonb_build_object(
        'position', v_ord::integer, 'product_id', v_prod.id, 'uom_id', v_uom, 'units_per_uom', v_factor,
        'quantity', v_qty, 'purchase_order_item_id', v_poi_id, 'description', v_desc);
    END LOOP;
  END IF;

  IF v_exists THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'position', l.position, 'product_id', l.product_id, 'uom_id', l.uom_id, 'units_per_uom', l.units_per_uom,
             'quantity', l.quantity, 'purchase_order_item_id', l.purchase_order_item_id, 'description', l.description)
             ORDER BY l.position, l.id), '[]'::jsonb)
    INTO v_cur_lines
    FROM public.supplier_delivery_note_lines l WHERE l.delivery_note_id = p_delivery_note_id;

    -- Pedido igual ao gravado (repetição da criação ou edição sem mudanças).
    IF v_cur.note_number = v_number
       AND v_cur.document_date IS NOT DISTINCT FROM p_document_date
       AND v_cur.notes IS NOT DISTINCT FROM v_notes
       AND v_final_pos = v_cur_pos
       AND (p_lines IS NULL OR v_lines = v_cur_lines) THEN
      RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('saved', false);
    END IF;

    IF p_expected_updated_at IS NULL OR p_expected_updated_at IS DISTINCT FROM v_cur.updated_at THEN
      RAISE EXCEPTION 'A guia % foi alterada entretanto — abre-a de novo antes de editar', v_cur.note_number
        USING ERRCODE = 'serialization_failure';
    END IF;
    IF v_cur.status <> 'open' THEN
      RAISE EXCEPTION 'A guia % está %; só uma guia aberta pode ser editada', v_cur.note_number,
        CASE v_cur.status WHEN 'closed' THEN 'fechada' ELSE 'cancelada' END
        USING ERRCODE = 'check_violation';
    END IF;

    -- Não retirar POs que já têm receções ativas por esta guia.
    SELECT string_agg(DISTINCT po.order_number, ', ') INTO v_removed
    FROM public.purchase_order_receipts pr
    JOIN public.purchase_orders po ON po.id = pr.purchase_order_id
    WHERE pr.delivery_note_id = p_delivery_note_id
      AND pr.kind = 'receipt' AND pr.reverted_at IS NULL
      AND pr.purchase_order_id = ANY (v_cur_pos)
      AND NOT (pr.purchase_order_id = ANY (v_final_pos));
    IF v_removed IS NOT NULL THEN
      RAISE EXCEPTION 'Não podes retirar % da guia: já tem receções por esta guia', v_removed
        USING ERRCODE = 'check_violation';
    END IF;
    -- Guia que passa a ter POs: as receções ativas têm de caber nelas.
    IF cardinality(v_final_pos) > 0 THEN
      SELECT string_agg(DISTINCT po.order_number, ', ') INTO v_removed
      FROM public.purchase_order_receipts pr
      JOIN public.purchase_orders po ON po.id = pr.purchase_order_id
      WHERE pr.delivery_note_id = p_delivery_note_id
        AND pr.kind = 'receipt' AND pr.reverted_at IS NULL
        AND NOT (pr.purchase_order_id = ANY (v_final_pos));
      IF v_removed IS NOT NULL THEN
        RAISE EXCEPTION 'A guia já tem receções em % — essas encomendas têm de ficar na guia', v_removed
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  -- Nº repetido no mesmo fornecedor (guias não canceladas).
  SELECT id INTO v_dup
  FROM public.supplier_delivery_notes
  WHERE organization_id = v_org AND supplier_id = p_supplier_id
    AND lower(btrim(note_number)) = lower(v_number)
    AND status <> 'cancelled' AND id <> p_delivery_note_id
  LIMIT 1;
  IF v_dup IS NOT NULL THEN
    RAISE EXCEPTION 'Já existe a guia % deste fornecedor', v_number
      USING ERRCODE = 'unique_violation', DETAIL = v_dup::text,
            HINT = 'Abre a guia existente (id em DETAIL).';
  END IF;

  BEGIN
    IF v_exists THEN
      UPDATE public.supplier_delivery_notes
      SET note_number   = v_number,
          document_date = p_document_date,
          notes         = v_notes,
          updated_at    = clock_timestamp()
      WHERE id = p_delivery_note_id;
    ELSE
      INSERT INTO public.supplier_delivery_notes (
        id, organization_id, supplier_id, note_number, document_date, notes, created_by, created_at, updated_at
      ) VALUES (
        p_delivery_note_id, v_org, p_supplier_id, v_number, p_document_date, v_notes, v_actor, now(), clock_timestamp()
      )
      ON CONFLICT (id) DO NOTHING;
      IF NOT FOUND THEN
        -- Mesmo id criado em paralelo: o cliente repete e cai na comparação.
        RAISE EXCEPTION 'Guia em conflito — tenta de novo' USING ERRCODE = 'serialization_failure';
      END IF;
    END IF;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_dup
    FROM public.supplier_delivery_notes
    WHERE organization_id = v_org AND supplier_id = p_supplier_id
      AND lower(btrim(note_number)) = lower(v_number)
      AND status <> 'cancelled' AND id <> p_delivery_note_id
    LIMIT 1;
    RAISE EXCEPTION 'Já existe a guia % deste fornecedor', v_number
      USING ERRCODE = 'unique_violation', DETAIL = COALESCE(v_dup::text, ''),
            HINT = 'Abre a guia existente (id em DETAIL).';
  END;

  IF v_final_pos IS DISTINCT FROM v_cur_pos THEN
    DELETE FROM public.supplier_delivery_note_orders
    WHERE delivery_note_id = p_delivery_note_id AND NOT (purchase_order_id = ANY (v_final_pos));
    INSERT INTO public.supplier_delivery_note_orders (delivery_note_id, purchase_order_id, organization_id, created_by)
    SELECT p_delivery_note_id, x, v_org, v_actor
    FROM unnest(v_final_pos) x
    WHERE NOT (x = ANY (v_cur_pos));
  END IF;

  IF p_lines IS NOT NULL AND (NOT v_exists OR v_lines IS DISTINCT FROM v_cur_lines) THEN
    DELETE FROM public.supplier_delivery_note_lines WHERE delivery_note_id = p_delivery_note_id;
    INSERT INTO public.supplier_delivery_note_lines (
      delivery_note_id, organization_id, position, product_id, uom_id, units_per_uom, quantity,
      purchase_order_item_id, description, created_by
    )
    SELECT p_delivery_note_id, v_org, l.position, l.product_id, l.uom_id, l.units_per_uom, l.quantity,
           l.purchase_order_item_id, l.description, v_actor
    FROM jsonb_to_recordset(v_lines) AS l(position integer, product_id uuid, uom_id uuid, units_per_uom integer,
                                          quantity numeric, purchase_order_item_id uuid, description text);
  END IF;

  RETURN public.rpc_delivery_note_get(p_delivery_note_id) || jsonb_build_object('saved', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_delivery_note_save(p_delivery_note_id uuid, p_supplier_id uuid, p_note_number text, p_document_date date, p_notes text, p_purchase_order_ids uuid[], p_lines jsonb, p_expected_updated_at timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_save(p_delivery_note_id uuid, p_supplier_id uuid, p_note_number text, p_document_date date, p_notes text, p_purchase_order_ids uuid[], p_lines jsonb, p_expected_updated_at timestamp with time zone) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_delivery_note_save(p_delivery_note_id uuid, p_supplier_id uuid, p_note_number text, p_document_date date, p_notes text, p_purchase_order_ids uuid[], p_lines jsonb, p_expected_updated_at timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_assign(p_vehicle_id uuid, p_driver_id uuid, p_kind text, p_starts_on date, p_ends_on date DEFAULT NULL::date, p_km integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text, p_ops_obra_id uuid DEFAULT NULL::uuid, p_ops_ordem_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v        public.fleet_vehicles;
  d        public.fleet_drivers;
  v_prob   text;
  v_clash  record;
  v_other  text;
  v_id     uuid;
  v_item   uuid;
  v_kmini  integer;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe a viatura.' USING ERRCODE = 'check_violation'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  SELECT * INTO d FROM public.fleet_drivers
  WHERE id = p_driver_id AND organization_id = v.organization_id AND deleted_at IS NULL AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe o condutor.' USING ERRCODE = 'check_violation'; END IF;

  IF p_kind NOT IN ('permanent', 'temporary') THEN RAISE EXCEPTION 'Tipo inválido.' USING ERRCODE = 'check_violation'; END IF;
  IF v.status <> 'active' THEN
    RAISE EXCEPTION 'A % não está ativa (%).', v.plate, v.status USING ERRCODE = 'check_violation';
  END IF;
  IF p_starts_on IS NULL THEN RAISE EXCEPTION 'Indica o início.' USING ERRCODE = 'check_violation'; END IF;
  IF p_kind = 'temporary' AND p_ends_on IS NULL THEN RAISE EXCEPTION 'Indica até quando.' USING ERRCODE = 'check_violation'; END IF;
  IF p_ends_on IS NOT NULL AND p_ends_on < p_starts_on THEN
    RAISE EXCEPTION 'O fim não pode ser antes do início.' USING ERRCODE = 'check_violation';
  END IF;

  -- a carta tem de servir no início e no último dia
  v_prob := COALESCE(public.fn_fleet_licence_problem(d.id, v.required_licence, p_starts_on),
                     public.fn_fleet_licence_problem(d.id, v.required_licence, COALESCE(p_ends_on, p_starts_on)));
  IF v_prob IS NOT NULL THEN RAISE EXCEPTION '%', v_prob USING ERRCODE = 'check_violation'; END IF;

  IF p_starts_on <= current_date AND p_km IS NOT NULL AND p_km < v.odometer_km THEN
    RAISE EXCEPTION 'Não pode ser menos do que a última leitura (% km).', v.odometer_km USING ERRCODE = 'check_violation';
  END IF;

  -- sobreposição com outra atribuição da viatura
  SELECT a.starts_on, a.ends_on, dr.full_name INTO v_clash
  FROM public.fleet_assignments a
  JOIN public.fleet_drivers dr ON dr.id = a.driver_id
  WHERE a.vehicle_id = v.id AND a.cancelled_at IS NULL
    AND a.starts_on <= COALESCE(p_ends_on, 'infinity'::date)
    AND (a.ends_on IS NULL OR a.ends_on > p_starts_on OR (a.ends_on = p_starts_on AND a.returned_on IS NULL))
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'A % já está com % de % a %.', v.plate, v_clash.full_name, to_char(v_clash.starts_on, 'DD/MM/YYYY'),
      COALESCE(to_char(v_clash.ends_on, 'DD/MM/YYYY'), 'sem fim') USING ERRCODE = 'check_violation';
  END IF;

  -- uma reserva pontual não pode cair em manutenção nem oficina
  IF p_kind = 'temporary' THEN
    SELECT b.kind, b.label, b.from_on INTO v_clash
    FROM public.fn_fleet_vehicle_blockers(v.id, p_starts_on, p_ends_on) b
    WHERE b.kind IN ('maintenance', 'workshop')
    ORDER BY b.from_on
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'A % tem % a %: está bloqueada na agenda.', v.plate, v_clash.label, to_char(v_clash.from_on, 'DD/MM/YYYY')
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF p_kind = 'permanent' THEN
    SELECT fv.plate INTO v_other
    FROM public.fleet_assignments a JOIN public.fleet_vehicles fv ON fv.id = a.vehicle_id
    WHERE a.driver_id = d.id AND a.kind = 'permanent' AND a.ends_on IS NULL AND a.cancelled_at IS NULL
    LIMIT 1;
    IF v_other IS NOT NULL THEN
      RAISE EXCEPTION '% já tem a %. Devolve-a primeiro.', d.full_name, v_other USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF p_ops_obra_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.ops_obra o WHERE o.id = p_ops_obra_id AND o.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Obra inválida.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_ops_ordem_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.ops_ordem o WHERE o.id = p_ops_ordem_id AND o.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Ordem inválida.' USING ERRCODE = 'check_violation';
  END IF;

  v_kmini := CASE WHEN p_starts_on <= current_date THEN COALESCE(p_km, v.odometer_km) END;

  INSERT INTO public.fleet_assignments (organization_id, vehicle_id, driver_id, kind, starts_on, ends_on, km_start, reason,
                                        ops_obra_id, ops_ordem_id, created_by)
  VALUES (v.organization_id, v.id, d.id, p_kind, p_starts_on, p_ends_on, v_kmini, NULLIF(btrim(COALESCE(p_reason, '')), ''),
          p_ops_obra_id, p_ops_ordem_id, public.current_business_user_id())
  RETURNING id INTO v_id;

  IF p_starts_on <= current_date AND p_km IS NOT NULL AND p_km > v.odometer_km THEN
    UPDATE public.fleet_vehicles SET odometer_km = p_km, odometer_read_on = current_date WHERE id = v.id;
    INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, source_id, recorded_by)
    VALUES (v.organization_id, v.id, current_date, p_km, 'handover', v_id, public.current_business_user_id());
  END IF;

  -- a reserva pontual bloqueia a viatura na Agenda
  IF p_kind = 'temporary' THEN
    v_item := public.fn_fleet_sync_schedule_item(v.id, NULL, format('Reserva · %s · %s', v.plate, d.full_name),
                                                 p_starts_on, p_ends_on, 'scheduled', d.user_id,
                                                 jsonb_build_object('fleet_kind', 'reservation', 'fleet_assignment_id', v_id));
    UPDATE public.fleet_assignments SET schedule_item_id = v_item WHERE id = v_id;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, CASE WHEN p_kind = 'temporary' THEN 'Reserva' ELSE 'Atribuição' END,
    format('%s atribuída a %s.', v.plate, d.full_name),
    concat_ws(' · ', CASE WHEN p_kind = 'temporary' THEN 'Reserva' ELSE 'Permanente' END || ' de ' || to_char(p_starts_on, 'DD/MM/YYYY')
              || COALESCE(' a ' || to_char(p_ends_on, 'DD/MM/YYYY'), ', sem fim'), NULLIF(btrim(COALESCE(p_reason, '')), '')),
    'fleet_assignment', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_assign(p_vehicle_id uuid, p_driver_id uuid, p_kind text, p_starts_on date, p_ends_on date, p_km integer, p_reason text, p_ops_obra_id uuid, p_ops_ordem_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_assign(p_vehicle_id uuid, p_driver_id uuid, p_kind text, p_starts_on date, p_ends_on date, p_km integer, p_reason text, p_ops_obra_id uuid, p_ops_ordem_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_assign(p_vehicle_id uuid, p_driver_id uuid, p_kind text, p_starts_on date, p_ends_on date, p_km integer, p_reason text, p_ops_obra_id uuid, p_ops_ordem_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_cancel_reservation(p_assignment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a public.fleet_assignments;
  v_org uuid;
BEGIN
  SELECT * INTO a FROM public.fleet_assignments WHERE id = p_assignment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reserva desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  v_org := a.organization_id;
  PERFORM public.fn_fleet_assert(v_org, ARRAY['fleet.manage']);
  IF a.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'Esta reserva já foi cancelada.' USING ERRCODE = 'check_violation'; END IF;
  IF a.starts_on <= current_date THEN
    RAISE EXCEPTION 'Só se cancelam reservas que ainda não começaram. Esta devolve-se.' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.fleet_assignments SET cancelled_at = now(), cancelled_by = public.current_business_user_id() WHERE id = a.id;
  IF a.schedule_item_id IS NOT NULL THEN
    UPDATE public.schedule_items SET status = 'cancelled' WHERE id = a.schedule_item_id;
  END IF;
  PERFORM public.fn_fleet_log(v_org, a.vehicle_id, 'Reserva cancelada', 'Reserva cancelada. A viatura ficou livre na Agenda.',
    to_char(a.starts_on, 'DD/MM/YYYY') || ' a ' || COALESCE(to_char(a.ends_on, 'DD/MM/YYYY'), 'sem fim'), 'fleet_assignment', a.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_cancel_reservation(p_assignment_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_cancel_reservation(p_assignment_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_cancel_reservation(p_assignment_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_cancel_restock(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  q public.fleet_restock_requests;
BEGIN
  SELECT * INTO q FROM public.fleet_restock_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido desconhecido.' USING ERRCODE = 'no_data_found'; END IF;
  IF q.requested_by IS DISTINCT FROM public.current_business_user_id() THEN
    PERFORM public.fn_fleet_assert(q.organization_id, ARRAY['fleet.manage', 'inventory.edit']);
  ELSE
    PERFORM public.fn_fleet_assert(q.organization_id, ARRAY['fleet.manage', 'inventory.edit'], q.vehicle_id);
  END IF;
  IF q.status <> 'requested' THEN RAISE EXCEPTION 'Pedido já tratado.' USING ERRCODE = 'check_violation'; END IF;
  UPDATE public.fleet_restock_requests SET status = 'cancelled', done_by = public.current_business_user_id(), done_at = now() WHERE id = q.id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_cancel_restock(p_request_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_cancel_restock(p_request_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_cancel_restock(p_request_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_complete_maintenance(p_event_id uuid, p_km integer, p_final_cost numeric, p_done_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  m        public.fleet_maintenance_events;
  v        public.fleet_vehicles;
  v_exp    uuid;
  v_left   boolean := false;
  v_ipo    date;
BEGIN
  SELECT * INTO m FROM public.fleet_maintenance_events WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Intervenção desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = m.vehicle_id FOR UPDATE;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  IF m.status IN ('done', 'cancelled') THEN RAISE EXCEPTION 'Esta intervenção já está fechada.' USING ERRCODE = 'check_violation'; END IF;
  IF p_km IS NULL OR p_km < v.odometer_km THEN
    RAISE EXCEPTION 'Não pode ser menos do que % km.', v.odometer_km USING ERRCODE = 'check_violation';
  END IF;
  IF p_final_cost IS NULL OR p_final_cost < 0 THEN
    RAISE EXCEPTION 'Indica o valor (0 se não teve custo).' USING ERRCODE = 'check_violation';
  END IF;
  IF p_done_on IS NULL OR p_done_on > current_date THEN RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation'; END IF;

  UPDATE public.fleet_maintenance_events
     SET status = 'done', km = p_km, final_cost = p_final_cost, done_on = p_done_on
   WHERE id = m.id;

  UPDATE public.fleet_vehicles SET odometer_km = p_km, odometer_read_on = p_done_on WHERE id = v.id;
  INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, source_id, recorded_by)
  VALUES (v.organization_id, v.id, p_done_on, p_km, 'maintenance', m.id, public.current_business_user_id());

  IF m.kind = 'service' THEN
    UPDATE public.fleet_maintenance_plans SET last_km = p_km, last_done_on = p_done_on
     WHERE vehicle_id = v.id AND kind = 'service' AND is_active;
  END IF;

  -- Decisão 10: próxima IPO pela regra legal (categoria + 1.ª matrícula).
  IF m.kind = 'inspection' THEN
    v_ipo := public.fn_fleet_next_inspection(v.vehicle_category, v.first_registration_on, p_done_on);
    UPDATE public.fleet_compliance SET is_current = false, replaced_at = now()
     WHERE vehicle_id = v.id AND kind = 'inspection' AND is_current;
    INSERT INTO public.fleet_compliance (organization_id, vehicle_id, kind, valid_from, valid_until, provider_supplier_id, created_by)
    VALUES (v.organization_id, v.id, 'inspection', p_done_on, v_ipo, m.supplier_id, public.current_business_user_id());
  END IF;

  IF v.status = 'workshop' THEN
    UPDATE public.fleet_vehicles SET status = 'active', status_reason = NULL, status_changed_at = now() WHERE id = v.id;
    v_left := true;
  END IF;

  IF p_final_cost > 0 THEN
    INSERT INTO public.fleet_expenses (organization_id, vehicle_id, spent_on, category, amount, odometer_km, supplier_id,
                                       supplier_label, cost_center_id, cost_center_label, source, maintenance_event_id, notes, created_by)
    VALUES (v.organization_id, v.id, p_done_on, CASE WHEN m.kind = 'inspection' THEN 'inspection' ELSE 'workshop' END,
            p_final_cost, p_km, m.supplier_id, m.supplier_label, v.cost_center_id, v.cost_center_label, 'maintenance', m.id,
            m.title, public.current_business_user_id())
    RETURNING id INTO v_exp;
  END IF;

  IF m.schedule_item_id IS NOT NULL THEN
    UPDATE public.schedule_items SET status = 'completed' WHERE id = m.schedule_item_id;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Manutenção concluída',
    m.title || ' concluída. ' || CASE WHEN v_left THEN v.plate || ' volta a estar ativa.' ELSE '' END,
    concat_ws(' · ', m.title, m.supplier_label, p_final_cost || ' €', p_km || ' km'), 'fleet_maintenance_event', m.id);
  RETURN jsonb_build_object('expense_id', v_exp, 'back_to_active', v_left, 'inspection_until', v_ipo);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_complete_maintenance(p_event_id uuid, p_km integer, p_final_cost numeric, p_done_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_complete_maintenance(p_event_id uuid, p_km integer, p_final_cost numeric, p_done_on date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_complete_maintenance(p_event_id uuid, p_km integer, p_final_cost numeric, p_done_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_create_vehicle(p_organization_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor        uuid := public.current_business_user_id();
  v_plate        text := upper(regexp_replace(COALESCE(p_data ->> 'plate', ''), '\s', '', 'g'));
  v_fuel         text := COALESCE(NULLIF(p_data ->> 'fuel_type', ''), 'diesel');
  v_km           integer := NULLIF(p_data ->> 'odometer_km', '')::integer;
  v_make         text := btrim(COALESCE(p_data ->> 'make', ''));
  v_model        text := btrim(COALESCE(p_data ->> 'model', ''));
  v_want_wh      boolean := COALESCE((p_data ->> 'create_warehouse')::boolean, false);
  v_exist_wh     uuid := NULLIF(p_data ->> 'existing_warehouse_id', '')::uuid;
  v_want_res     boolean := COALESCE((p_data ->> 'create_schedule_resource')::boolean, false);
  v_exist_res    uuid := NULLIF(p_data ->> 'existing_schedule_resource_id', '')::uuid;
  v_id           uuid;
  v_wh           uuid;
  v_res          uuid;
  v_wh_count     integer;
  v_only_wh      uuid;
  v_default_set  boolean := false;
  v_code         text;
  v_category     text := NULLIF(p_data ->> 'vehicle_category', '');
  v_first_reg    date := NULLIF(p_data ->> 'first_registration_on', '')::date;
  v_ipo_until    date := NULLIF(p_data ->> 'inspection_until', '')::date;
BEGIN
  PERFORM public.fn_fleet_assert(p_organization_id, ARRAY['fleet.manage']);

  IF v_plate !~ '^([A-Z]{2}-[0-9]{2}-[A-Z]{2}|[0-9]{2}-[A-Z]{2}-[0-9]{2}|[0-9]{2}-[0-9]{2}-[A-Z]{2}|[A-Z]{2}-[0-9]{2}-[0-9]{2})$' THEN
    RAISE EXCEPTION 'Usa o formato português, por exemplo AA-00-AA.' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fleet_vehicles
             WHERE organization_id = p_organization_id AND plate = v_plate AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Já existe uma viatura com esta matrícula.' USING ERRCODE = 'unique_violation';
  END IF;
  IF v_make = '' THEN RAISE EXCEPTION 'Indica a marca.' USING ERRCODE = 'check_violation'; END IF;
  IF v_model = '' THEN RAISE EXCEPTION 'Indica o modelo.' USING ERRCODE = 'check_violation'; END IF;
  IF v_km IS NULL OR v_km < 0 THEN RAISE EXCEPTION 'Indica os km.' USING ERRCODE = 'check_violation'; END IF;
  IF NULLIF(p_data ->> 'insurance_until', '') IS NULL THEN
    RAISE EXCEPTION 'Sem seguro válido não pode circular.' USING ERRCODE = 'check_violation';
  END IF;

  IF v_category IS NOT NULL AND v_category NOT IN ('light_passenger', 'light_goods', 'other') THEN
    RAISE EXCEPTION 'Categoria inválida.' USING ERRCODE = 'check_violation';
  END IF;
  IF v_first_reg IS NOT NULL AND v_first_reg > current_date THEN
    RAISE EXCEPTION 'A data da 1.ª matrícula não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;
  -- Sem data da próxima IPO, calcula-a pela regra legal (só com categoria e
  -- 1.ª matrícula conhecidas): o primeiro prazo legal a partir de hoje.
  IF v_ipo_until IS NULL AND v_first_reg IS NOT NULL AND v_category IN ('light_passenger', 'light_goods') THEN
    v_ipo_until := public.fn_fleet_next_inspection(v_category, v_first_reg, (current_date - interval '3 months')::date);
  END IF;

  INSERT INTO public.fleet_vehicles (organization_id, plate, make, model, vehicle_type, vehicle_category, first_registration_on,
                                     fuel_type, ownership,
                                     lessor_supplier_id, monthly_rent, model_year, vin, odometer_km, odometer_read_on,
                                     required_licence, cost_center_id, cost_center_label, personal_use, is_pool,
                                     asset_id, notes, created_by)
  VALUES (p_organization_id, v_plate, v_make, v_model, NULLIF(p_data ->> 'vehicle_type', ''), v_category, v_first_reg, v_fuel,
          COALESCE(NULLIF(p_data ->> 'ownership', ''), 'owned'),
          NULLIF(p_data ->> 'lessor_supplier_id', '')::uuid, NULLIF(p_data ->> 'monthly_rent', '')::numeric,
          NULLIF(p_data ->> 'model_year', '')::smallint, NULLIF(p_data ->> 'vin', ''), v_km, current_date,
          COALESCE(NULLIF(upper(p_data ->> 'required_licence'), ''), 'B'),
          NULLIF(p_data ->> 'cost_center_id', '')::uuid, NULLIF(p_data ->> 'cost_center_label', ''),
          COALESCE((p_data ->> 'personal_use')::boolean, false), COALESCE((p_data ->> 'is_pool')::boolean, false),
          NULLIF(p_data ->> 'asset_id', '')::uuid, NULLIF(p_data ->> 'notes', ''), v_actor)
  RETURNING id INTO v_id;

  -- Armazém móvel ------------------------------------------------------------
  IF v_want_wh OR v_exist_wh IS NOT NULL THEN
    PERFORM public.fn_fleet_assert(p_organization_id,
      CASE WHEN v_exist_wh IS NULL THEN ARRAY['warehouses.create'] ELSE ARRAY['warehouses.edit'] END);

    -- Proteger a baixa automática de stock dos contratos/propostas: sem
    -- default_warehouse_id, fn_contract_stock_deduction usa "o único armazém".
    SELECT count(*), (array_agg(w.id))[1] INTO v_wh_count, v_only_wh
    FROM public.warehouses w
    WHERE w.organization_id = p_organization_id AND w.deleted_at IS NULL;

    IF v_exist_wh IS NOT NULL AND v_wh_count = 1 AND v_only_wh = v_exist_wh THEN
      RAISE EXCEPTION 'Esse é o único armazém da organização: não pode passar a carrinha.' USING ERRCODE = 'check_violation';
    END IF;
    IF v_wh_count = 1 AND NOT EXISTS (SELECT 1 FROM public.organization_inventory_settings s
                                      WHERE s.organization_id = p_organization_id AND s.default_warehouse_id IS NOT NULL) THEN
      INSERT INTO public.organization_inventory_settings (organization_id, default_warehouse_id, created_by)
      VALUES (p_organization_id, v_only_wh, v_actor)
      ON CONFLICT (organization_id) DO UPDATE SET default_warehouse_id = EXCLUDED.default_warehouse_id, updated_at = now();
      v_default_set := true;
    END IF;

    IF v_exist_wh IS NOT NULL THEN
      UPDATE public.warehouses
         SET is_vehicle = true, serves_customers = false, updated_at = now()
       WHERE id = v_exist_wh AND organization_id = p_organization_id AND deleted_at IS NULL
      RETURNING id INTO v_wh;
      IF v_wh IS NULL THEN
        RAISE EXCEPTION 'Armazém inválido para esta organização.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      v_code := 'VIA-' || replace(v_plate, '-', '');
      SELECT w.id INTO v_wh FROM public.warehouses w
      WHERE w.organization_id = p_organization_id AND w.code = v_code;
      IF v_wh IS NOT NULL THEN
        -- Reaproveita um armazém móvel antigo da mesma matrícula, só se vazio e livre.
        IF EXISTS (SELECT 1 FROM public.stocks s WHERE s.warehouse_id = v_wh AND s.deleted_at IS NULL AND s.quantity > 0)
           OR EXISTS (SELECT 1 FROM public.fleet_vehicles fv WHERE fv.warehouse_id = v_wh) THEN
          RAISE EXCEPTION 'O armazém móvel % já existe e tem stock ou outra viatura: esvazia-o por transferência primeiro.', v_code
            USING ERRCODE = 'check_violation';
        END IF;
        UPDATE public.warehouses
           SET deleted_at = NULL, deleted_by = NULL, is_active = true, serves_customers = false, is_vehicle = true, updated_at = now()
         WHERE id = v_wh;
      ELSE
        INSERT INTO public.warehouses (organization_id, name, code, address, city, is_active, serves_customers, is_vehicle, created_by)
        VALUES (p_organization_id, 'Carrinha ' || v_plate, v_code, 'Armazém móvel (viatura)',
                NULLIF(p_data ->> 'warehouse_city', ''), true, false, true, v_actor)
        RETURNING id INTO v_wh;
      END IF;
    END IF;

    -- Decisão 6: a carrinha nunca fica com reorder_point > 0 (senão entrava no
    -- "stock baixo" do Inventário). Se o armazém já tinha pontos de
    -- encomenda, passam para o mínimo da carrinha (minimum_quantity).
    UPDATE public.stocks
       SET minimum_quantity = GREATEST(minimum_quantity, reorder_point),
           reorder_point = 0
     WHERE warehouse_id = v_wh AND reorder_point > 0;
  END IF;

  -- Recurso da Agenda --------------------------------------------------------
  -- Decisão 3: criar o recurso basta fleet.manage (já verificado acima).
  -- Reaproveitar um recurso que já existe: basta fleet.manage se já for um
  -- recurso de viatura (resource_type = 'vehicle'); um recurso de outro tipo
  -- passaria a viatura, por isso continua a pedir scheduling.resources.edit.
  IF v_exist_res IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.schedule_resources sr
                   WHERE sr.id = v_exist_res AND sr.organization_id = p_organization_id
                     AND sr.resource_type = 'vehicle') THEN
      PERFORM public.fn_fleet_assert(p_organization_id, ARRAY['scheduling.resources.edit']);
    END IF;
    UPDATE public.schedule_resources
       SET resource_type = 'vehicle',
           metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('fleet_vehicle_id', v_id)
     WHERE id = v_exist_res AND organization_id = p_organization_id AND user_id IS NULL
    RETURNING id INTO v_res;
    IF v_res IS NULL THEN
      RAISE EXCEPTION 'Recurso da Agenda inválido (tem de ser desta organização e não ser uma pessoa).' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF v_want_res THEN
    INSERT INTO public.schedule_resources (name, resource_type, is_active, organization_id, created_by, metadata, color)
    VALUES (v_make || ' ' || split_part(v_model, ' ', 1) || ' · ' || v_plate, 'vehicle', true, p_organization_id, v_actor,
            jsonb_build_object('fleet_vehicle_id', v_id), '#64748b')
    RETURNING id INTO v_res;
  END IF;

  UPDATE public.fleet_vehicles SET warehouse_id = v_wh, schedule_resource_id = v_res WHERE id = v_id;

  -- Km, plano de revisão e vencimentos -------------------------------------
  INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, recorded_by)
  VALUES (p_organization_id, v_id, current_date, v_km, 'creation', v_actor);

  INSERT INTO public.fleet_maintenance_plans (organization_id, vehicle_id, kind, title, every_km, every_months, last_km, last_done_on, created_by)
  VALUES (p_organization_id, v_id, 'service', 'Revisão',
          COALESCE(NULLIF(p_data ->> 'service_every_km', '')::integer, 30000),
          COALESCE(NULLIF(p_data ->> 'service_every_months', '')::integer, 12),
          COALESCE(NULLIF(p_data ->> 'service_last_km', '')::integer, v_km),
          COALESCE(NULLIF(p_data ->> 'service_last_on', '')::date, current_date), v_actor);

  INSERT INTO public.fleet_compliance (organization_id, vehicle_id, kind, valid_until, is_exempt, provider_supplier_id, reference, created_by)
  SELECT p_organization_id, v_id, k.kind, k.until, k.exempt, k.sup, k.ref, v_actor
  FROM (VALUES
    ('insurance', NULLIF(p_data ->> 'insurance_until', '')::date, false,
       NULLIF(p_data ->> 'insurer_supplier_id', '')::uuid, NULLIF(p_data ->> 'insurance_policy_no', '')),
    ('inspection', v_ipo_until, false, NULL::uuid, NULL::text),
    ('road_tax', CASE WHEN v_fuel = 'electric' THEN NULL ELSE NULLIF(p_data ->> 'road_tax_until', '')::date END,
       v_fuel = 'electric', NULL::uuid, NULL::text),
    ('lease_contract', NULLIF(p_data ->> 'contract_ends_on', '')::date, false,
       NULLIF(p_data ->> 'lessor_supplier_id', '')::uuid, NULL::text)
  ) AS k(kind, until, exempt, sup, ref)
  WHERE k.until IS NOT NULL OR k.exempt;

  PERFORM public.fn_fleet_log(p_organization_id, v_id, 'Nova viatura', format('Viatura %s criada.', v_plate),
    concat_ws(' · ', v_make || ' ' || v_model, v_km || ' km',
              CASE WHEN v_wh IS NOT NULL THEN 'armazém móvel' END,
              CASE WHEN v_res IS NOT NULL THEN 'recurso da agenda' END,
              CASE WHEN v_default_set THEN 'armazém por omissão do inventário fixado no armazém existente' END),
    'fleet_vehicle', v_id);

  RETURN jsonb_build_object('vehicle_id', v_id, 'warehouse_id', v_wh, 'schedule_resource_id', v_res,
                            'default_warehouse_set', v_default_set);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_create_vehicle(p_organization_id uuid, p_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_create_vehicle(p_organization_id uuid, p_data jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_create_vehicle(p_organization_id uuid, p_data jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_fulfil_restock(p_request_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r       record;
  v_res   jsonb;
  v_out   jsonb := '[]'::jsonb;
BEGIN
  FOR r IN SELECT q.*, fv.plate
           FROM public.fleet_restock_requests q
           JOIN public.fleet_vehicles fv ON fv.id = q.vehicle_id
           WHERE q.id = ANY (p_request_ids)
           ORDER BY q.product_id
           FOR UPDATE OF q LOOP
    PERFORM public.fn_fleet_assert(r.organization_id, ARRAY['inventory.edit']);
    IF r.status <> 'requested' THEN
      v_out := v_out || jsonb_build_object('id', r.id, 'ok', false, 'error', 'Pedido já tratado.');
      CONTINUE;
    END IF;
    BEGIN
      v_res := public.rpc_register_stock_transfer(r.product_id, r.from_warehouse_id, r.to_warehouse_id, r.quantity,
                                                  'Reposição da carrinha ' || r.plate);
      UPDATE public.fleet_restock_requests
         SET status = 'transferred', stock_document_number = v_res ->> 'document_number',
             transfer_group_id = (v_res ->> 'transfer_group_id')::uuid, last_error = NULL,
             done_by = public.current_business_user_id(), done_at = now()
       WHERE id = r.id;
      v_out := v_out || jsonb_build_object('id', r.id, 'ok', true, 'document_number', v_res ->> 'document_number');
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.fleet_restock_requests SET last_error = SQLERRM WHERE id = r.id;
      v_out := v_out || jsonb_build_object('id', r.id, 'ok', false, 'error', SQLERRM);
    END;
    PERFORM public.fn_fleet_log(r.organization_id, r.vehicle_id, 'Reposição', format('Reposição da carrinha %s tratada.', r.plate),
      NULL, 'fleet_restock_request', r.id);
  END LOOP;
  RETURN v_out;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_fulfil_restock(p_request_ids uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_fulfil_restock(p_request_ids uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_fulfil_restock(p_request_ids uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_identify_driver(p_incident_id uuid, p_driver_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  i       public.fleet_incidents;
  d       public.fleet_drivers;
  v_plate text;
  v_auth  uuid;
BEGIN
  SELECT * INTO i FROM public.fleet_incidents WHERE id = p_incident_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Ocorrência desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(i.organization_id, ARRAY['fleet.manage']);
  SELECT * INTO d FROM public.fleet_drivers WHERE id = p_driver_id AND organization_id = i.organization_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe o condutor.' USING ERRCODE = 'check_violation'; END IF;
  IF i.status = 'resolved' THEN RAISE EXCEPTION 'A ocorrência já está resolvida.' USING ERRCODE = 'check_violation'; END IF;

  SELECT plate INTO v_plate FROM public.fleet_vehicles WHERE id = i.vehicle_id;
  UPDATE public.fleet_incidents SET driver_id = d.id, status = 'identified', driver_notified_at = now() WHERE id = i.id;

  -- aviso ao condutor (se tiver conta)
  SELECT au.auth_user_id INTO v_auth FROM public.anew_users au WHERE au.id = d.user_id AND au.deleted_at IS NULL;
  IF v_auth IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, organization_id, kind, type, entity_type, entity_id, title, message, priority, link, data)
    VALUES (v_auth, i.organization_id, 'notification', 'fleet_fine_identified', 'fleet_incident', i.id,
            'Multa associada a ti',
            format('Foste identificado como condutor da %s a %s (%s).', v_plate,
                   to_char(i.occurred_at AT TIME ZONE 'Europe/Lisbon', 'DD/MM/YYYY HH24:MI'), i.description),
            'medium', '/frota/ocorrencias', jsonb_build_object('vehicle_id', i.vehicle_id));
  END IF;

  PERFORM public.fn_fleet_log(i.organization_id, i.vehicle_id, 'Condutor identificado',
    format('Condutor identificado: %s.%s', d.full_name, CASE WHEN v_auth IS NOT NULL THEN ' Notificação enviada.' ELSE '' END),
    concat_ws(' · ', i.kind || ' de ' || to_char(i.occurred_at AT TIME ZONE 'Europe/Lisbon', 'DD/MM/YYYY'), i.description),
    'fleet_incident', i.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_identify_driver(p_incident_id uuid, p_driver_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_identify_driver(p_incident_id uuid, p_driver_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_identify_driver(p_incident_id uuid, p_driver_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_import_statement(p_organization_id uuid, p_file_name text, p_file_sha256 text, p_supplier_id uuid, p_rows jsonb, p_document_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_imp     uuid;
  r         jsonb;
  v         public.fleet_vehicles;
  v_plate   text;
  v_km      integer;
  v_on      date;
  v_flag    boolean;
  v_drv     uuid;
  v_exp     uuid;
  n_total   integer := 0;
  n_ok      integer := 0;
  n_flag    integer := 0;
  n_skip    integer := 0;
BEGIN
  PERFORM public.fn_fleet_assert(p_organization_id, ARRAY['fleet.costs']);
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Extrato vazio ou inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fleet_expense_imports i WHERE i.organization_id = p_organization_id AND i.file_sha256 = p_file_sha256) THEN
    RAISE EXCEPTION 'O % já foi importado: importá-lo outra vez duplicava os custos.', p_file_name USING ERRCODE = 'unique_violation';
  END IF;
  IF p_supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers s WHERE s.id = p_supplier_id AND s.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Fornecedor inválido.' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.fleet_expense_imports (organization_id, file_name, file_sha256, supplier_id, document_id, imported_by)
  VALUES (p_organization_id, p_file_name, p_file_sha256, p_supplier_id, p_document_id, public.current_business_user_id())
  RETURNING id INTO v_imp;

  FOR r IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    n_total := n_total + 1;
    v_plate := upper(regexp_replace(COALESCE(r ->> 'plate', ''), '\s', '', 'g'));
    SELECT * INTO v FROM public.fleet_vehicles
    WHERE organization_id = p_organization_id AND plate = v_plate AND deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND OR NOT (COALESCE(NULLIF(r ->> 'amount', '')::numeric, 0) > 0) THEN
      n_skip := n_skip + 1;  -- matrícula desconhecida ou linha sem valor
      CONTINUE;
    END IF;
    v_km := NULLIF(r ->> 'km', '')::integer;
    v_on := (r ->> 'spent_on')::date;
    v_flag := v_km IS NOT NULL AND v_km < v.odometer_km;
    SELECT a.driver_id INTO v_drv FROM public.fleet_assignments a WHERE a.id = public.fn_fleet_assignment_at(v.id, v_on);

    v_exp := NULL;
    INSERT INTO public.fleet_expenses (organization_id, vehicle_id, spent_on, category, quantity, unit, amount, odometer_km,
                                       driver_id, supplier_id, supplier_label, cost_center_id, cost_center_label, source,
                                       import_id, external_ref, needs_review, review_reason, created_by)
    VALUES (p_organization_id, v.id, v_on,
            CASE WHEN COALESCE(r ->> 'unit', 'L') = 'kWh' THEN 'charging' ELSE 'fuel' END,
            NULLIF(r ->> 'quantity', '')::numeric, COALESCE(NULLIF(r ->> 'unit', ''), 'L'), (r ->> 'amount')::numeric, v_km,
            v_drv, p_supplier_id, 'Cartão frota · ' || COALESCE(r ->> 'station', ''), v.cost_center_id, v.cost_center_label,
            'statement', v_imp, COALESCE(NULLIF(r ->> 'external_ref', ''), md5(r::text)), v_flag,
            CASE WHEN v_flag THEN format('Km abaixo da última leitura (%s)', v.odometer_km) END,
            public.current_business_user_id())
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_exp;

    IF v_exp IS NULL THEN
      n_skip := n_skip + 1;  -- linha já importada noutro extrato
      CONTINUE;
    END IF;
    n_ok := n_ok + 1;
    IF v_flag THEN
      n_flag := n_flag + 1;
    ELSIF v_km IS NOT NULL AND v_km > v.odometer_km THEN
      UPDATE public.fleet_vehicles SET odometer_km = v_km, odometer_read_on = v_on WHERE id = v.id;
      INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, source_id, recorded_by)
      VALUES (p_organization_id, v.id, v_on, v_km, 'statement', v_exp, public.current_business_user_id());
    END IF;
  END LOOP;

  UPDATE public.fleet_expense_imports
     SET rows_total = n_total, rows_imported = n_ok, rows_flagged = n_flag, rows_skipped = n_skip
   WHERE id = v_imp;

  PERFORM public.fn_fleet_log(p_organization_id, NULL, 'Importação',
    format('%s abastecimentos importados.%s', n_ok, CASE WHEN n_flag > 0 THEN format(' %s ficou para rever.', n_flag) ELSE '' END),
    p_file_name, 'fleet_expense_import', v_imp);
  RETURN jsonb_build_object('import_id', v_imp, 'total', n_total, 'imported', n_ok, 'flagged', n_flag, 'skipped', n_skip);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_import_statement(p_organization_id uuid, p_file_name text, p_file_sha256 text, p_supplier_id uuid, p_rows jsonb, p_document_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_import_statement(p_organization_id uuid, p_file_name text, p_file_sha256 text, p_supplier_id uuid, p_rows jsonb, p_document_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_import_statement(p_organization_id uuid, p_file_name text, p_file_sha256 text, p_supplier_id uuid, p_rows jsonb, p_document_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_link_order(p_vehicle_id uuid, p_ops_ordem_id uuid, p_ops_obra_id uuid, p_used_on date, p_driver_id uuid DEFAULT NULL::uuid, p_km integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v        public.fleet_vehicles;
  v_id     uuid;
  v_cost   numeric;
  v_estado text;
  v_cid    uuid;
  v_why    text;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage'], v.id);
  IF p_ops_ordem_id IS NULL AND p_ops_obra_id IS NULL THEN
    RAISE EXCEPTION 'Indica a ordem ou a obra.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_ops_ordem_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.ops_ordem o WHERE o.id = p_ops_ordem_id AND o.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Ordem inválida.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_ops_obra_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.ops_obra o WHERE o.id = p_ops_obra_id AND o.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Obra inválida.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_driver_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fleet_drivers d WHERE d.id = p_driver_id AND d.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Condutor inválido.' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.fleet_ops_links (organization_id, vehicle_id, ops_ordem_id, ops_obra_id, used_on, driver_id, km, cost_per_km, notes, created_by)
  VALUES (v.organization_id, v.id, p_ops_ordem_id, p_ops_obra_id, COALESCE(p_used_on, current_date), p_driver_id, p_km,
          public.fn_fleet_cost_per_km(v.organization_id, v.id), NULLIF(p_notes, ''), public.current_business_user_id())
  RETURNING id, travel_cost INTO v_id, v_cost;
  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Ligação a Operações', format('%s ligada a uma ordem/obra.', v.plate), NULL, 'fleet_ops_link', v_id);

  IF p_ops_ordem_id IS NULL THEN
    v_why := 'Ligação só à obra: o custo de Operações pertence à ordem.';
  ELSIF COALESCE(v_cost, 0) <= 0 THEN
    v_why := 'Sem km: não há custo a lançar.';
  ELSIF NOT public.ops_pode(v.organization_id, 'operations.costs.view') THEN
    v_why := 'Sem permissão para lançar custos em Operações: fica pendente para um gestor.';
  ELSE
    SELECT o.estado INTO v_estado FROM public.ops_ordem o WHERE o.id = p_ops_ordem_id;
    IF v_estado IN ('confirmada', 'cancelada') THEN
      v_why := 'A ordem já está encerrada: o custo não foi lançado.';
    ELSE
      v_cid := public.rpc_fleet_post_travel_cost(v_id);
    END IF;
  END IF;

  RETURN jsonb_build_object('link_id', v_id, 'travel_cost', v_cost, 'ops_custo_id', v_cid, 'cost_not_posted_reason', v_why);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_link_order(p_vehicle_id uuid, p_ops_ordem_id uuid, p_ops_obra_id uuid, p_used_on date, p_driver_id uuid, p_km integer, p_notes text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_link_order(p_vehicle_id uuid, p_ops_ordem_id uuid, p_ops_obra_id uuid, p_used_on date, p_driver_id uuid, p_km integer, p_notes text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_link_order(p_vehicle_id uuid, p_ops_ordem_id uuid, p_ops_obra_id uuid, p_used_on date, p_driver_id uuid, p_km integer, p_notes text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_post_travel_cost(p_link_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  l       public.fleet_ops_links;
  v_plate text;
  v_res   jsonb;
  v_cid   uuid;
BEGIN
  SELECT * INTO l FROM public.fleet_ops_links WHERE id = p_link_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Ligação desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(l.organization_id, ARRAY['fleet.manage', 'fleet.costs'], l.vehicle_id);
  IF l.ops_custo_id IS NOT NULL THEN
    RAISE EXCEPTION 'O custo desta deslocação já foi lançado na ordem.' USING ERRCODE = 'check_violation';
  END IF;
  IF l.ops_ordem_id IS NULL THEN
    RAISE EXCEPTION 'Só se lança custo numa ordem (o custo de Operações pertence à ordem, não à obra).' USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(l.travel_cost, 0) <= 0 THEN
    RAISE EXCEPTION 'Indica os km da deslocação.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT fv.plate INTO v_plate FROM public.fleet_vehicles fv WHERE fv.id = l.vehicle_id;
  v_res := public.rpc_ops_lancar_custo(
    l.ops_ordem_id, 'outro',
    format('Deslocação %s · %s km × %s €/km', v_plate, l.km, replace(trim_scale(l.cost_per_km)::text, '.', ',')),
    1, l.travel_cost, NULL, NULL, NULL);
  v_cid := (v_res ->> 'id')::uuid;

  UPDATE public.fleet_ops_links SET ops_custo_id = v_cid WHERE id = l.id;
  PERFORM public.fn_fleet_log(l.organization_id, l.vehicle_id, 'Custo da deslocação',
    format('Deslocação de %s € lançada na ordem.', l.travel_cost), NULL, 'fleet_ops_link', l.id);
  RETURN v_cid;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_post_travel_cost(p_link_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_post_travel_cost(p_link_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_post_travel_cost(p_link_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_record_expense(p_vehicle_id uuid, p_category text, p_spent_on date, p_amount numeric, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_label text DEFAULT NULL::text, p_cost_center_id uuid DEFAULT NULL::uuid, p_cost_center_label text DEFAULT NULL::text, p_ops_obra_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v    public.fleet_vehicles;
  v_id uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe a viatura.' USING ERRCODE = 'check_violation'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.costs', 'fleet.manage']);

  IF p_category IS NULL OR p_category NOT IN ('fuel', 'charging', 'tolls', 'parking', 'washing', 'workshop', 'rent',
                                              'insurance', 'road_tax', 'inspection', 'fine', 'other') THEN
    RAISE EXCEPTION 'Tipo de despesa inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (p_amount > 0) THEN RAISE EXCEPTION 'Indica o valor.' USING ERRCODE = 'check_violation'; END IF;
  IF p_supplier_id IS NULL AND NULLIF(btrim(COALESCE(p_supplier_label, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Escolhe o fornecedor.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_spent_on IS NULL OR p_spent_on > current_date THEN
    RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers s WHERE s.id = p_supplier_id AND s.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Fornecedor inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_ops_obra_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.ops_obra o WHERE o.id = p_ops_obra_id AND o.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Obra inválida.' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.fleet_expenses (organization_id, vehicle_id, spent_on, category, amount, supplier_id, supplier_label,
                                     cost_center_id, cost_center_label, ops_obra_id, source, notes, created_by)
  VALUES (v.organization_id, v.id, p_spent_on, p_category, p_amount, p_supplier_id, NULLIF(btrim(COALESCE(p_supplier_label, '')), ''),
          COALESCE(p_cost_center_id, CASE WHEN p_cost_center_label IS NULL AND p_ops_obra_id IS NULL THEN v.cost_center_id END),
          COALESCE(NULLIF(p_cost_center_label, ''), CASE WHEN p_cost_center_id IS NULL AND p_ops_obra_id IS NULL THEN v.cost_center_label END),
          p_ops_obra_id, 'manual', NULLIF(p_notes, ''), public.current_business_user_id())
  RETURNING id INTO v_id;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Despesa', format('Despesa de %s € registada.', p_amount),
    concat_ws(' · ', p_category, p_amount || ' €', NULLIF(p_supplier_label, ''), NULLIF(p_cost_center_label, '')), 'fleet_expense', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_record_expense(p_vehicle_id uuid, p_category text, p_spent_on date, p_amount numeric, p_supplier_id uuid, p_supplier_label text, p_cost_center_id uuid, p_cost_center_label text, p_ops_obra_id uuid, p_notes text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_expense(p_vehicle_id uuid, p_category text, p_spent_on date, p_amount numeric, p_supplier_id uuid, p_supplier_label text, p_cost_center_id uuid, p_cost_center_label text, p_ops_obra_id uuid, p_notes text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_expense(p_vehicle_id uuid, p_category text, p_spent_on date, p_amount numeric, p_supplier_id uuid, p_supplier_label text, p_cost_center_id uuid, p_cost_center_label text, p_ops_obra_id uuid, p_notes text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_record_fuel(p_vehicle_id uuid, p_quantity numeric, p_amount numeric, p_km integer, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_label text DEFAULT NULL::text, p_spent_on date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v      public.fleet_vehicles;
  v_el   boolean;
  v_drv  uuid;
  v_id   uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe a viatura.' USING ERRCODE = 'check_violation'; END IF;
  -- como no protótipo: gestor ou o próprio condutor (o perfil Financeiro não abastece)
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage'], v.id);

  IF NOT (p_quantity > 0) THEN RAISE EXCEPTION 'Indica a quantidade.' USING ERRCODE = 'check_violation'; END IF;
  IF NOT (p_amount > 0) THEN RAISE EXCEPTION 'Indica o valor.' USING ERRCODE = 'check_violation'; END IF;
  IF p_km IS NULL OR p_km < v.odometer_km THEN
    RAISE EXCEPTION 'Indica os km (pelo menos % km).', v.odometer_km USING ERRCODE = 'check_violation';
  END IF;
  IF p_spent_on IS NULL OR p_spent_on > current_date THEN
    RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_supplier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers s WHERE s.id = p_supplier_id AND s.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Fornecedor inválido.' USING ERRCODE = 'check_violation';
  END IF;

  v_el := v.fuel_type = 'electric';
  SELECT a.driver_id INTO v_drv FROM public.fleet_assignments a WHERE a.id = public.fn_fleet_assignment_at(v.id, p_spent_on);

  INSERT INTO public.fleet_expenses (organization_id, vehicle_id, spent_on, category, quantity, unit, amount, odometer_km,
                                     driver_id, supplier_id, supplier_label, cost_center_id, cost_center_label, source, created_by)
  VALUES (v.organization_id, v.id, p_spent_on, CASE WHEN v_el THEN 'charging' ELSE 'fuel' END, p_quantity,
          CASE WHEN v_el THEN 'kWh' ELSE 'L' END, p_amount, p_km, v_drv, p_supplier_id, NULLIF(p_supplier_label, ''),
          v.cost_center_id, v.cost_center_label, 'fuel', public.current_business_user_id())
  RETURNING id INTO v_id;

  UPDATE public.fleet_vehicles SET odometer_km = p_km, odometer_read_on = p_spent_on WHERE id = v.id;
  INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, source_id, recorded_by)
  VALUES (v.organization_id, v.id, p_spent_on, p_km, 'fuel', v_id, public.current_business_user_id());

  PERFORM public.fn_fleet_log(v.organization_id, v.id, CASE WHEN v_el THEN 'Carregamento' ELSE 'Abastecimento' END,
    format('Abastecimento de %s € registado na %s.', p_amount, v.plate),
    concat_ws(' · ', p_quantity || CASE WHEN v_el THEN ' kWh' ELSE ' L' END, p_amount || ' €', p_km || ' km', NULLIF(p_supplier_label, '')),
    'fleet_expense', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_record_fuel(p_vehicle_id uuid, p_quantity numeric, p_amount numeric, p_km integer, p_supplier_id uuid, p_supplier_label text, p_spent_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_fuel(p_vehicle_id uuid, p_quantity numeric, p_amount numeric, p_km integer, p_supplier_id uuid, p_supplier_label text, p_spent_on date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_fuel(p_vehicle_id uuid, p_quantity numeric, p_amount numeric, p_km integer, p_supplier_id uuid, p_supplier_label text, p_spent_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_record_odometer(p_vehicle_id uuid, p_km integer, p_read_on date DEFAULT CURRENT_DATE, p_confirm_jump boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v    public.fleet_vehicles;
  v_id uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage'], v.id);

  IF p_km IS NULL THEN RAISE EXCEPTION 'Indica os km.' USING ERRCODE = 'check_violation'; END IF;
  IF p_km < v.odometer_km THEN
    RAISE EXCEPTION 'Os km não podem descer. Última leitura: % km.', v.odometer_km USING ERRCODE = 'check_violation';
  END IF;
  IF p_km - v.odometer_km > 5000 AND NOT p_confirm_jump THEN
    RAISE EXCEPTION 'São mais % km do que a última leitura. Confirma o valor.', p_km - v.odometer_km USING ERRCODE = 'check_violation';
  END IF;
  IF p_read_on IS NULL OR p_read_on > current_date THEN
    RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, recorded_by)
  VALUES (v.organization_id, v.id, p_read_on, p_km, 'manual', public.current_business_user_id())
  RETURNING id INTO v_id;
  UPDATE public.fleet_vehicles SET odometer_km = p_km, odometer_read_on = p_read_on WHERE id = v.id;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Km', 'Km registados.', p_km || ' km a ' || to_char(p_read_on, 'DD/MM/YYYY'), 'fleet_odometer_reading', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_record_odometer(p_vehicle_id uuid, p_km integer, p_read_on date, p_confirm_jump boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_odometer(p_vehicle_id uuid, p_km integer, p_read_on date, p_confirm_jump boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_record_odometer(p_vehicle_id uuid, p_km integer, p_read_on date, p_confirm_jump boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_renew_compliance(p_vehicle_id uuid, p_kind text, p_valid_until date, p_amount numeric DEFAULT NULL::numeric, p_supplier_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v      public.fleet_vehicles;
  old    public.fleet_compliance;
  v_id   uuid;
  v_sup  uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage', 'fleet.costs']);

  IF p_kind NOT IN ('insurance', 'inspection', 'road_tax', 'lease_contract', 'green_card', 'tachograph', 'other') THEN
    RAISE EXCEPTION 'Documento inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_valid_until IS NULL OR p_valid_until <= current_date THEN
    RAISE EXCEPTION 'A nova validade tem de ser depois de hoje.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.documents d WHERE d.id = p_document_id AND d.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Documento anexo inválido.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO old FROM public.fleet_compliance WHERE vehicle_id = v.id AND kind = p_kind AND is_current FOR UPDATE;
  v_sup := COALESCE(p_supplier_id, old.provider_supplier_id);
  IF old.id IS NOT NULL THEN
    UPDATE public.fleet_compliance SET is_current = false, replaced_at = now() WHERE id = old.id;
  END IF;
  INSERT INTO public.fleet_compliance (organization_id, vehicle_id, kind, valid_from, valid_until, provider_supplier_id,
                                       reference, amount, document_id, created_by)
  VALUES (v.organization_id, v.id, p_kind, current_date, p_valid_until, v_sup, COALESCE(NULLIF(p_reference, ''), old.reference),
          NULLIF(p_amount, 0), p_document_id, public.current_business_user_id())
  RETURNING id INTO v_id;

  IF p_amount > 0 THEN
    INSERT INTO public.fleet_expenses (organization_id, vehicle_id, spent_on, category, amount, supplier_id, supplier_label,
                                       cost_center_id, cost_center_label, source, compliance_id, created_by)
    VALUES (v.organization_id, v.id, current_date,
            CASE p_kind WHEN 'insurance' THEN 'insurance' WHEN 'road_tax' THEN 'road_tax' WHEN 'inspection' THEN 'inspection'
                        WHEN 'lease_contract' THEN 'rent' ELSE 'other' END,
            p_amount, v_sup, CASE WHEN p_kind = 'road_tax' AND v_sup IS NULL THEN 'Autoridade Tributária' END,
            v.cost_center_id, v.cost_center_label, 'renewal', v_id, public.current_business_user_id());
  END IF;

  UPDATE public.notifications SET is_resolved = true, resolved_at = now(), resolved_reason = 'fleet_compliance_renewed'
   WHERE entity_id = old.id AND type = 'fleet_document_due' AND is_resolved = false;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Documento renovado',
    format('%s da %s renovado até %s.', p_kind, v.plate, to_char(p_valid_until, 'DD/MM/YYYY')),
    CASE WHEN p_amount > 0 THEN p_amount || ' €' END, 'fleet_compliance', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_renew_compliance(p_vehicle_id uuid, p_kind text, p_valid_until date, p_amount numeric, p_supplier_id uuid, p_reference text, p_document_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_renew_compliance(p_vehicle_id uuid, p_kind text, p_valid_until date, p_amount numeric, p_supplier_id uuid, p_reference text, p_document_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_renew_compliance(p_vehicle_id uuid, p_kind text, p_valid_until date, p_amount numeric, p_supplier_id uuid, p_reference text, p_document_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_report_incident(p_vehicle_id uuid, p_kind text, p_occurred_at timestamp with time zone, p_location text, p_description text, p_amount numeric DEFAULT NULL::numeric, p_notified_on date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v       public.fleet_vehicles;
  v_drv   uuid;
  v_ntf   date;
  v_id    uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe a viatura.' USING ERRCODE = 'check_violation'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage'], v.id);

  IF p_kind NOT IN ('fine', 'accident', 'breakdown') THEN RAISE EXCEPTION 'Tipo inválido.' USING ERRCODE = 'check_violation'; END IF;
  IF p_occurred_at IS NULL THEN RAISE EXCEPTION 'Indica quando.' USING ERRCODE = 'check_violation'; END IF;
  IF (p_occurred_at AT TIME ZONE 'Europe/Lisbon')::date > current_date THEN
    RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;
  IF btrim(COALESCE(p_location, '')) = '' THEN RAISE EXCEPTION 'Indica o local.' USING ERRCODE = 'check_violation'; END IF;
  IF length(btrim(COALESCE(p_description, ''))) < 3 THEN RAISE EXCEPTION 'Descreve o que aconteceu.' USING ERRCODE = 'check_violation'; END IF;

  IF p_kind = 'fine' THEN
    v_ntf := COALESCE(p_notified_on, current_date);
    INSERT INTO public.fleet_incidents (organization_id, vehicle_id, kind, occurred_at, location, description, amount,
                                        notified_on, identify_by, status, created_by)
    VALUES (v.organization_id, v.id, 'fine', p_occurred_at, btrim(p_location), btrim(p_description), NULLIF(p_amount, 0),
            v_ntf, public.fn_fleet_add_working_days(v.organization_id, v_ntf, 15), 'to_identify', public.current_business_user_id())
    RETURNING id INTO v_id;
  ELSE
    SELECT a.driver_id INTO v_drv FROM public.fleet_assignments a
    WHERE a.id = public.fn_fleet_assignment_at(v.id, (p_occurred_at AT TIME ZONE 'Europe/Lisbon')::date);
    INSERT INTO public.fleet_incidents (organization_id, vehicle_id, kind, occurred_at, location, description, amount,
                                        driver_id, status, created_by)
    VALUES (v.organization_id, v.id, p_kind, p_occurred_at, btrim(p_location), btrim(p_description), NULLIF(p_amount, 0),
            v_drv, 'logged', public.current_business_user_id())
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Ocorrência', format('%s registada na %s.', p_kind, v.plate),
    concat_ws(' · ', p_kind, btrim(p_location), btrim(p_description)), 'fleet_incident', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_report_incident(p_vehicle_id uuid, p_kind text, p_occurred_at timestamp with time zone, p_location text, p_description text, p_amount numeric, p_notified_on date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_report_incident(p_vehicle_id uuid, p_kind text, p_occurred_at timestamp with time zone, p_location text, p_description text, p_amount numeric, p_notified_on date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_report_incident(p_vehicle_id uuid, p_kind text, p_occurred_at timestamp with time zone, p_location text, p_description text, p_amount numeric, p_notified_on date) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_request_restock(p_vehicle_id uuid, p_from_warehouse_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v       public.fleet_vehicles;
  v_below integer;
  v_ids   uuid[];
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage'], v.id);
  IF v.warehouse_id IS NULL THEN RAISE EXCEPTION 'A % não é um armazém móvel.', v.plate USING ERRCODE = 'check_violation'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.warehouses w
                 WHERE w.id = p_from_warehouse_id AND w.organization_id = v.organization_id
                   AND w.deleted_at IS NULL AND w.is_active AND NOT w.is_vehicle) THEN
    RAISE EXCEPTION 'Armazém de origem inválido.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO v_below
  FROM public.stocks s
  WHERE s.warehouse_id = v.warehouse_id AND s.deleted_at IS NULL
    AND s.minimum_quantity > 0 AND s.quantity < s.minimum_quantity;
  IF v_below = 0 THEN
    RAISE EXCEPTION 'Nenhum artigo da carrinha está abaixo do mínimo.' USING ERRCODE = 'check_violation';
  END IF;

  WITH ins AS (
    INSERT INTO public.fleet_restock_requests (organization_id, vehicle_id, from_warehouse_id, to_warehouse_id, product_id, quantity, requested_by)
    SELECT v.organization_id, v.id, p_from_warehouse_id, v.warehouse_id, s.product_id, s.minimum_quantity - s.quantity,
           public.current_business_user_id()
    FROM public.stocks s
    WHERE s.warehouse_id = v.warehouse_id AND s.deleted_at IS NULL
      AND s.minimum_quantity > 0 AND s.quantity < s.minimum_quantity
    ON CONFLICT DO NOTHING
    RETURNING id
  )
  SELECT array_agg(id) INTO v_ids FROM ins;

  IF v_ids IS NULL THEN
    RAISE EXCEPTION 'Já há pedidos de reposição pendentes para todos os artigos em falta.' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Pedido de reposição',
    format('Pedido de reposição: armazém central → carrinha %s (%s artigo(s)).', v.plate, cardinality(v_ids)), NULL,
    'fleet_restock_request', v_ids[1]);
  RETURN jsonb_build_object('request_ids', to_jsonb(v_ids));
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_request_restock(p_vehicle_id uuid, p_from_warehouse_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_request_restock(p_vehicle_id uuid, p_from_warehouse_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_request_restock(p_vehicle_id uuid, p_from_warehouse_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_resolve_incident(p_incident_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  i public.fleet_incidents;
BEGIN
  SELECT * INTO i FROM public.fleet_incidents WHERE id = p_incident_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Ocorrência desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(i.organization_id, ARRAY['fleet.manage']);
  IF i.status = 'resolved' THEN RAISE EXCEPTION 'A ocorrência já está resolvida.' USING ERRCODE = 'check_violation'; END IF;

  UPDATE public.fleet_incidents SET status = 'resolved', resolved_at = now(), resolved_by = public.current_business_user_id() WHERE id = i.id;
  -- os avisos pendentes desta ocorrência deixam de valer
  UPDATE public.notifications SET is_resolved = true, resolved_at = now(), resolved_reason = 'fleet_incident_resolved'
   WHERE entity_id = i.id AND type IN ('fleet_fine_deadline', 'fleet_fine_identified') AND is_resolved = false;

  PERFORM public.fn_fleet_log(i.organization_id, i.vehicle_id, 'Ocorrência resolvida', 'Ocorrência marcada como resolvida.',
    concat_ws(' · ', i.kind || ' de ' || to_char(i.occurred_at AT TIME ZONE 'Europe/Lisbon', 'DD/MM/YYYY'), i.description),
    'fleet_incident', i.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_resolve_incident(p_incident_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_resolve_incident(p_incident_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_resolve_incident(p_incident_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_return(p_assignment_id uuid, p_km integer, p_returned_on date, p_damage_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a     public.fleet_assignments;
  v     public.fleet_vehicles;
  v_inc uuid;
BEGIN
  SELECT * INTO a FROM public.fleet_assignments WHERE id = p_assignment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Atribuição desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = a.vehicle_id FOR UPDATE;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  IF a.returned_on IS NOT NULL OR a.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'Esta atribuição já foi devolvida.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_km IS NULL OR p_km < v.odometer_km THEN
    RAISE EXCEPTION 'Indica os km. Não pode ser menos do que % km.', v.odometer_km USING ERRCODE = 'check_violation';
  END IF;
  IF p_returned_on IS NULL OR p_returned_on < a.starts_on THEN
    RAISE EXCEPTION 'A data é anterior à entrega.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_returned_on > current_date THEN
    RAISE EXCEPTION 'Não pode ser no futuro.' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.fleet_assignments
     SET ends_on = p_returned_on, returned_on = p_returned_on, km_end = p_km,
         damage_notes = NULLIF(btrim(COALESCE(p_damage_notes, '')), '')
   WHERE id = a.id;
  UPDATE public.fleet_vehicles SET odometer_km = p_km, odometer_read_on = p_returned_on WHERE id = v.id;
  INSERT INTO public.fleet_odometer_readings (organization_id, vehicle_id, read_on, km, source, source_id, recorded_by)
  VALUES (v.organization_id, v.id, p_returned_on, p_km, 'return', a.id, public.current_business_user_id());

  IF a.schedule_item_id IS NOT NULL THEN
    -- liberta a Agenda a partir do dia seguinte à devolução
    PERFORM public.fn_fleet_sync_schedule_item(v.id, a.schedule_item_id, NULL, a.starts_on, p_returned_on, 'completed', NULL);
  END IF;

  IF NULLIF(btrim(COALESCE(p_damage_notes, '')), '') IS NOT NULL THEN
    INSERT INTO public.fleet_incidents (organization_id, vehicle_id, kind, occurred_at, location, description, driver_id,
                                        status, assignment_id, created_by)
    VALUES (v.organization_id, v.id, 'accident', (p_returned_on + time '18:00') AT TIME ZONE 'Europe/Lisbon',
            'Na devolução', 'Danos detetados na devolução: ' || btrim(p_damage_notes), a.driver_id, 'logged', a.id,
            public.current_business_user_id())
    RETURNING id INTO v_inc;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Devolução', format('%s devolvida com %s km.', v.plate, p_km),
    to_char(p_returned_on, 'DD/MM/YYYY') || CASE WHEN v_inc IS NOT NULL THEN ' · com danos (ocorrência aberta)' ELSE '' END,
    'fleet_assignment', a.id);
  RETURN jsonb_build_object('assignment_id', a.id, 'incident_id', v_inc);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_return(p_assignment_id uuid, p_km integer, p_returned_on date, p_damage_notes text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_return(p_assignment_id uuid, p_km integer, p_returned_on date, p_damage_notes text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_return(p_assignment_id uuid, p_km integer, p_returned_on date, p_damage_notes text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_schedule_maintenance(p_vehicle_id uuid, p_kind text, p_title text, p_scheduled_on date, p_expected_end_on date DEFAULT NULL::date, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_label text DEFAULT NULL::text, p_estimated_cost numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_incident_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v       public.fleet_vehicles;
  v_res   record;
  v_id    uuid;
  v_item  uuid;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Escolhe a viatura.' USING ERRCODE = 'check_violation'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  IF p_kind NOT IN ('service', 'inspection', 'repair', 'tyres', 'other') THEN
    RAISE EXCEPTION 'Tipo de intervenção inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF btrim(COALESCE(p_title, '')) = '' THEN RAISE EXCEPTION 'Indica a intervenção.' USING ERRCODE = 'check_violation'; END IF;
  IF p_scheduled_on IS NULL OR p_scheduled_on < current_date THEN
    RAISE EXCEPTION 'Escolhe uma data a partir de hoje.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_expected_end_on IS NOT NULL AND p_expected_end_on < p_scheduled_on THEN
    RAISE EXCEPTION 'A data prevista de fim não pode ser antes do início.' USING ERRCODE = 'check_violation';
  END IF;

  -- a manutenção bloqueia a viatura: não pode cair numa reserva pontual
  SELECT b.label, b.from_on, b.to_on INTO v_res
  FROM public.fn_fleet_vehicle_blockers(v.id, p_scheduled_on, COALESCE(p_expected_end_on, p_scheduled_on)) b
  WHERE b.kind = 'temporary'
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'A viatura está reservada a % nesse dia (% a %). Escolhe outro dia ou cancela a reserva.',
      v_res.label, to_char(v_res.from_on, 'DD/MM/YYYY'), to_char(v_res.to_on, 'DD/MM/YYYY') USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.fleet_maintenance_events (organization_id, vehicle_id, kind, title, scheduled_on, expected_end_on, status,
                                               supplier_id, supplier_label, estimated_cost, notes, incident_id, created_by)
  VALUES (v.organization_id, v.id, p_kind, btrim(p_title), p_scheduled_on, p_expected_end_on, 'scheduled',
          p_supplier_id, NULLIF(p_supplier_label, ''), p_estimated_cost, NULLIF(p_notes, ''), p_incident_id,
          public.current_business_user_id())
  RETURNING id INTO v_id;

  v_item := public.fn_fleet_sync_schedule_item(v.id, NULL, format('%s · %s', btrim(p_title), v.plate),
                                               p_scheduled_on, COALESCE(p_expected_end_on, p_scheduled_on), 'scheduled', NULL,
                                               jsonb_build_object('fleet_kind', 'maintenance', 'fleet_maintenance_event_id', v_id));
  UPDATE public.fleet_maintenance_events SET schedule_item_id = v_item WHERE id = v_id;
  IF p_incident_id IS NOT NULL THEN
    UPDATE public.fleet_incidents SET maintenance_event_id = v_id, status = 'in_progress'
     WHERE id = p_incident_id AND vehicle_id = v.id AND status NOT IN ('resolved');
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Manutenção agendada',
    format('%s da %s agendada para %s.', btrim(p_title), v.plate, to_char(p_scheduled_on, 'DD/MM/YYYY')),
    concat_ws(' · ', btrim(p_title), NULLIF(p_supplier_label, ''), to_char(p_scheduled_on, 'DD/MM/YYYY')), 'fleet_maintenance_event', v_id);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_schedule_maintenance(p_vehicle_id uuid, p_kind text, p_title text, p_scheduled_on date, p_expected_end_on date, p_supplier_id uuid, p_supplier_label text, p_estimated_cost numeric, p_notes text, p_incident_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_schedule_maintenance(p_vehicle_id uuid, p_kind text, p_title text, p_scheduled_on date, p_expected_end_on date, p_supplier_id uuid, p_supplier_label text, p_estimated_cost numeric, p_notes text, p_incident_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_schedule_maintenance(p_vehicle_id uuid, p_kind text, p_title text, p_scheduled_on date, p_expected_end_on date, p_supplier_id uuid, p_supplier_label text, p_estimated_cost numeric, p_notes text, p_incident_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_set_status(p_vehicle_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v     public.fleet_vehicles;
  v_a   public.fleet_assignments;
  r     record;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  IF p_status NOT IN ('active', 'workshop', 'stopped', 'inactive', 'sold') THEN
    RAISE EXCEPTION 'Estado inválido.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_status = v.status THEN
    RAISE EXCEPTION 'Escolhe um estado diferente.' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Escreve o motivo (pelo menos 3 letras).' USING ERRCODE = 'check_violation';
  END IF;
  -- Decisão 11: vender/abater só com a carrinha a zero (nem positivo nem
  -- negativo); o armazém da carrinha fica depois inativo (não é apagado).
  IF p_status IN ('inactive', 'sold') AND v.warehouse_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.stocks s WHERE s.warehouse_id = v.warehouse_id AND s.deleted_at IS NULL AND s.quantity <> 0) THEN
    RAISE EXCEPTION 'A carrinha da % ainda tem stock: transfere-o primeiro para outro armazém (Inventário › Transferências) e depois muda o estado.', v.plate
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.fleet_vehicles
     SET status = p_status, status_reason = btrim(p_reason), status_changed_at = now()
   WHERE id = v.id;

  -- Fora de "ativa", a atribuição de hoje fecha (como gravarEstado).
  IF p_status <> 'active' THEN
    SELECT * INTO v_a FROM public.fleet_assignments WHERE id = public.fn_fleet_assignment_at(v.id, current_date);
    IF FOUND THEN
      UPDATE public.fleet_assignments
         SET ends_on = current_date, returned_on = current_date, km_end = v.odometer_km
       WHERE id = v_a.id;
      IF v_a.schedule_item_id IS NOT NULL THEN
        PERFORM public.fn_fleet_sync_schedule_item(v.id, v_a.schedule_item_id, NULL, v_a.starts_on, current_date, 'completed', NULL);
      END IF;
    END IF;
  END IF;

  IF p_status IN ('inactive', 'sold') THEN
    -- Reservas futuras caem e a viatura sai da Agenda.
    FOR r IN SELECT * FROM public.fleet_assignments
             WHERE vehicle_id = v.id AND cancelled_at IS NULL AND starts_on > current_date LOOP
      UPDATE public.fleet_assignments SET cancelled_at = now(), cancelled_by = public.current_business_user_id() WHERE id = r.id;
      IF r.schedule_item_id IS NOT NULL THEN
        UPDATE public.schedule_items SET status = 'cancelled' WHERE id = r.schedule_item_id;
      END IF;
    END LOOP;
    UPDATE public.fleet_restock_requests SET status = 'cancelled', done_at = now(), done_by = public.current_business_user_id()
     WHERE vehicle_id = v.id AND status = 'requested';
    IF v.schedule_resource_id IS NOT NULL THEN
      UPDATE public.schedule_resources SET is_active = false WHERE id = v.schedule_resource_id;
    END IF;
    IF v.warehouse_id IS NOT NULL THEN
      UPDATE public.warehouses SET is_active = false, updated_at = now()
       WHERE id = v.warehouse_id AND is_vehicle;
    END IF;
  ELSIF p_status = 'active' THEN
    IF v.schedule_resource_id IS NOT NULL THEN
      UPDATE public.schedule_resources SET is_active = true WHERE id = v.schedule_resource_id;
    END IF;
    IF v.warehouse_id IS NOT NULL AND v.status IN ('inactive', 'sold') THEN
      UPDATE public.warehouses SET is_active = true, updated_at = now()
       WHERE id = v.warehouse_id AND is_vehicle AND deleted_at IS NULL;
    END IF;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Estado', format('%s passou a "%s".', v.plate, p_status), btrim(p_reason), 'fleet_vehicle', v.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_set_status(p_vehicle_id uuid, p_status text, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_set_status(p_vehicle_id uuid, p_status text, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_set_status(p_vehicle_id uuid, p_status text, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_set_van_minimum(p_vehicle_id uuid, p_product_id uuid, p_minimum integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.fleet_vehicles;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['inventory.edit']);
  IF v.warehouse_id IS NULL THEN RAISE EXCEPTION 'A % não é um armazém móvel.', v.plate USING ERRCODE = 'check_violation'; END IF;
  IF p_minimum IS NULL OR p_minimum < 0 THEN RAISE EXCEPTION 'Indica o mínimo.' USING ERRCODE = 'check_violation'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.products p WHERE p.id = p_product_id AND p.organization_id = v.organization_id) THEN
    RAISE EXCEPTION 'Artigo inválido.' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.stocks SET minimum_quantity = p_minimum, reorder_point = 0
   WHERE product_id = p_product_id AND warehouse_id = v.warehouse_id;
  IF NOT FOUND THEN
    INSERT INTO public.stocks (organization_id, product_id, warehouse_id, quantity, minimum_quantity, reorder_point, created_by)
    VALUES (v.organization_id, p_product_id, v.warehouse_id, 0, p_minimum, 0, public.current_business_user_id());
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_set_van_minimum(p_vehicle_id uuid, p_product_id uuid, p_minimum integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_set_van_minimum(p_vehicle_id uuid, p_product_id uuid, p_minimum integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_set_van_minimum(p_vehicle_id uuid, p_product_id uuid, p_minimum integer) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_update_vehicle(p_vehicle_id uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.fleet_vehicles;
BEGIN
  SELECT * INTO v FROM public.fleet_vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Viatura desconhecida.' USING ERRCODE = 'no_data_found'; END IF;
  PERFORM public.fn_fleet_assert(v.organization_id, ARRAY['fleet.manage']);

  UPDATE public.fleet_vehicles SET
    make               = CASE WHEN p_data ? 'make' THEN btrim(p_data ->> 'make') ELSE make END,
    model              = CASE WHEN p_data ? 'model' THEN btrim(p_data ->> 'model') ELSE model END,
    vehicle_type       = CASE WHEN p_data ? 'vehicle_type' THEN NULLIF(p_data ->> 'vehicle_type', '') ELSE vehicle_type END,
    vehicle_category   = CASE WHEN p_data ? 'vehicle_category' THEN NULLIF(p_data ->> 'vehicle_category', '') ELSE vehicle_category END,
    first_registration_on = CASE WHEN p_data ? 'first_registration_on' THEN NULLIF(p_data ->> 'first_registration_on', '')::date ELSE first_registration_on END,
    fuel_type          = CASE WHEN p_data ? 'fuel_type' THEN p_data ->> 'fuel_type' ELSE fuel_type END,
    ownership          = CASE WHEN p_data ? 'ownership' THEN p_data ->> 'ownership' ELSE ownership END,
    lessor_supplier_id = CASE WHEN p_data ? 'lessor_supplier_id' THEN NULLIF(p_data ->> 'lessor_supplier_id', '')::uuid ELSE lessor_supplier_id END,
    monthly_rent       = CASE WHEN p_data ? 'monthly_rent' THEN NULLIF(p_data ->> 'monthly_rent', '')::numeric ELSE monthly_rent END,
    model_year         = CASE WHEN p_data ? 'model_year' THEN NULLIF(p_data ->> 'model_year', '')::smallint ELSE model_year END,
    vin                = CASE WHEN p_data ? 'vin' THEN NULLIF(p_data ->> 'vin', '') ELSE vin END,
    required_licence   = CASE WHEN p_data ? 'required_licence' THEN upper(p_data ->> 'required_licence') ELSE required_licence END,
    cost_center_id     = CASE WHEN p_data ? 'cost_center_id' THEN NULLIF(p_data ->> 'cost_center_id', '')::uuid ELSE cost_center_id END,
    cost_center_label  = CASE WHEN p_data ? 'cost_center_label' THEN NULLIF(p_data ->> 'cost_center_label', '') ELSE cost_center_label END,
    personal_use       = CASE WHEN p_data ? 'personal_use' THEN (p_data ->> 'personal_use')::boolean ELSE personal_use END,
    is_pool            = CASE WHEN p_data ? 'is_pool' THEN (p_data ->> 'is_pool')::boolean ELSE is_pool END,
    asset_id           = CASE WHEN p_data ? 'asset_id' THEN NULLIF(p_data ->> 'asset_id', '')::uuid ELSE asset_id END,
    notes              = CASE WHEN p_data ? 'notes' THEN NULLIF(p_data ->> 'notes', '') ELSE notes END
  WHERE id = v.id;

  IF p_data ? 'service_every_km' OR p_data ? 'service_every_months' THEN
    UPDATE public.fleet_maintenance_plans SET
      every_km     = CASE WHEN p_data ? 'service_every_km' THEN NULLIF(p_data ->> 'service_every_km', '')::integer ELSE every_km END,
      every_months = CASE WHEN p_data ? 'service_every_months' THEN NULLIF(p_data ->> 'service_every_months', '')::integer ELSE every_months END
    WHERE vehicle_id = v.id AND kind = 'service' AND is_active;
  END IF;

  PERFORM public.fn_fleet_log(v.organization_id, v.id, 'Ficha alterada', format('Ficha da %s alterada.', v.plate), NULL, 'fleet_vehicle', v.id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_update_vehicle(p_vehicle_id uuid, p_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_update_vehicle(p_vehicle_id uuid, p_data jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_update_vehicle(p_vehicle_id uuid, p_data jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_fleet_upsert_driver(p_organization_id uuid, p_driver_id uuid, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id   uuid := p_driver_id;
  v_user uuid := NULLIF(p_data ->> 'user_id', '')::uuid;
  v_cats text[];
BEGIN
  PERFORM public.fn_fleet_assert(p_organization_id, ARRAY['fleet.manage']);
  IF btrim(COALESCE(p_data ->> 'full_name', '')) = '' THEN
    RAISE EXCEPTION 'Indica o nome do condutor.' USING ERRCODE = 'check_violation';
  END IF;
  IF v_user IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.anew_memberships m
       WHERE m.user_id = v_user AND m.organization_id = p_organization_id AND m.status = 'active') THEN
    RAISE EXCEPTION 'O utilizador não pertence a esta organização.' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(array_agg(upper(btrim(x))), '{}') INTO v_cats
  FROM jsonb_array_elements_text(COALESCE(p_data -> 'licence_categories', '[]'::jsonb)) AS t(x)
  WHERE btrim(x) <> '';

  IF v_id IS NULL THEN
    INSERT INTO public.fleet_drivers (organization_id, user_id, pessoa_id, full_name, job_title, team, licence_number,
                                      licence_categories, licence_expires_on, notes, created_by)
    VALUES (p_organization_id, v_user, NULLIF(p_data ->> 'pessoa_id', '')::uuid, btrim(p_data ->> 'full_name'),
            NULLIF(p_data ->> 'job_title', ''), NULLIF(p_data ->> 'team', ''), NULLIF(p_data ->> 'licence_number', ''),
            v_cats, NULLIF(p_data ->> 'licence_expires_on', '')::date, NULLIF(p_data ->> 'notes', ''),
            public.current_business_user_id())
    RETURNING id INTO v_id;
    PERFORM public.fn_fleet_log(p_organization_id, NULL, 'Novo condutor', format('Condutor %s criado.', btrim(p_data ->> 'full_name')), NULL, 'fleet_driver', v_id);
  ELSE
    UPDATE public.fleet_drivers
       SET user_id = v_user,
           pessoa_id = NULLIF(p_data ->> 'pessoa_id', '')::uuid,
           full_name = btrim(p_data ->> 'full_name'),
           job_title = NULLIF(p_data ->> 'job_title', ''),
           team = NULLIF(p_data ->> 'team', ''),
           licence_number = NULLIF(p_data ->> 'licence_number', ''),
           licence_categories = v_cats,
           licence_expires_on = NULLIF(p_data ->> 'licence_expires_on', '')::date,
           is_active = COALESCE((p_data ->> 'is_active')::boolean, is_active),
           notes = NULLIF(p_data ->> 'notes', '')
     WHERE id = v_id AND organization_id = p_organization_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Condutor desconhecido.' USING ERRCODE = 'no_data_found';
    END IF;
    PERFORM public.fn_fleet_log(p_organization_id, NULL, 'Condutor alterado', format('Condutor %s alterado.', btrim(p_data ->> 'full_name')), NULL, 'fleet_driver', v_id);
  END IF;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_fleet_upsert_driver(p_organization_id uuid, p_driver_id uuid, p_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_upsert_driver(p_organization_id uuid, p_driver_id uuid, p_data jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_fleet_upsert_driver(p_organization_id uuid, p_driver_id uuid, p_data jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_get_morada_fiscal(p_entity_id uuid DEFAULT NULL::uuid, p_quote_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(entity_id uuid, entity_address_id uuid, address_id uuid, street text, number text, floor text, unit text, postal_code text, city text, formatted text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_entity uuid;
BEGIN
  IF p_quote_id IS NOT NULL THEN
    SELECT COALESCE(
             qt.entity_id,
             (SELECT c.entity_id FROM public.anew_clients c WHERE c.id = qt.cliente_id),
             (SELECT d.entity_id FROM public.deals d WHERE d.id = qt.deal_id),
             (SELECT al.entity_id FROM public.anew_leads al
                WHERE al.id = (SELECT d2.lead_id FROM public.deals d2 WHERE d2.id = qt.deal_id))
           )
      INTO v_entity
    FROM public.quotes qt
    WHERE qt.id = p_quote_id
      AND public.has_anew_permission(v_uid, 'quotes.view')
      AND qt.organization_id IN (SELECT public.get_user_crm_org_ids(v_uid));

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sem permissão para ver este orçamento' USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSE
    IF p_entity_id IS NULL THEN
      RAISE EXCEPTION 'entity_id ou quote_id é obrigatório' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT public.fn_entity_delivery_address_access(p_entity_id, 'view') THEN
      RAISE EXCEPTION 'Sem permissão para ver as moradas deste cliente' USING ERRCODE = 'insufficient_privilege';
    END IF;
    v_entity := p_entity_id;
  END IF;

  IF v_entity IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    v_entity,
    ea.id,
    a.id,
    a.street,
    a.number,
    a.floor,
    a.unit,
    a.postal_code,
    a.city,
    public.fn_quote_morada_texto(a.id)
  FROM public.anew_entity_addresses ea
  JOIN public.anew_addresses a ON a.id = ea.address_id
  WHERE ea.entity_id = v_entity
    AND coalesce(ea.address_type, '') <> 'delivery'
    AND (ea.valid_to IS NULL OR ea.valid_to > now())
  ORDER BY ea.is_primary DESC NULLS LAST, ea.is_fiscal DESC NULLS LAST, ea.created_at, ea.id
  LIMIT 1;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_get_morada_fiscal(p_entity_id uuid, p_quote_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_get_morada_fiscal(p_entity_id uuid, p_quote_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_get_morada_fiscal(p_entity_id uuid, p_quote_id uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_get_morada_fiscal(p_entity_id uuid, p_quote_id uuid) IS 'Morada fiscal (principal) da entidade de um orçamento ou de uma lead/cliente. Com p_quote_id: permissão de ver o orçamento. Só com p_entity_id: permissão de ver a ficha (fn_entity_delivery_address_access view).';

CREATE OR REPLACE FUNCTION public.rpc_inventory_today(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid          uuid := auth.uid();
  v_can_po       boolean;
  v_can_rec      boolean;
  v_can_sup      boolean;
  v_can_pricing  boolean;
  v_can_ec       boolean;
  v_can_inv      boolean;
  v_can_cost     boolean;
  v_purchases    jsonb;
  v_suppliers    jsonb;
  v_client_ord   jsonb;
  v_stock        jsonb;
  v_counts       jsonb;
  v_settings     jsonb;
  v_reserved     numeric;
  v_open_dn      integer;
  v_div_dn       integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Utilizador não autenticado' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id é obrigatório' USING ERRCODE = 'check_violation';
  END IF;

  IF p_organization_id NOT IN (SELECT public.get_user_visible_org_ids(v_uid)) THEN
    RAISE EXCEPTION 'Sem permissão para ver o inventário desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_can_po  := COALESCE(public.has_anew_permission(v_uid, 'purchase_orders.view'), false);
  -- Guias do fornecedor: mesma regra da RLS de supplier_delivery_notes.
  v_can_rec := v_can_po OR COALESCE(public.has_anew_permission(v_uid, 'purchase_orders.receive'), false);
  v_can_sup := COALESCE(public.has_anew_permission(v_uid, 'suppliers.view'), false);
  v_can_ec  := COALESCE(public.has_anew_permission(v_uid, 'client_orders.view'), false);
  v_can_inv := COALESCE(public.has_anew_permission(v_uid, 'inventory.view'), false);

  -- Sem nenhuma permissão: tudo a null.
  IF NOT (v_can_po OR v_can_rec OR v_can_sup OR v_can_ec OR v_can_inv) THEN
    RETURN jsonb_build_object(
      'purchases', NULL, 'suppliers', NULL, 'client_orders', NULL,
      'stock', NULL, 'counts', NULL, 'settings', NULL
    );
  END IF;

  v_can_cost    := COALESCE(public.has_anew_permission(v_uid, 'products.view_cost'), false);
  v_can_pricing := v_can_cost OR COALESCE(public.has_anew_permission(v_uid, 'suppliers.view_pricing'), false);

  -- ── 1. Compras (purchase_orders.view; guias: .view OU .receive) ────────────
  IF v_can_po THEN
    SELECT jsonb_build_object(
             'pending_approval', count(*) FILTER (WHERE po.status = 'pending'),
             'late',             count(*) FILTER (WHERE po.status IN ('ordered', 'partially_received')
                                                    AND po.expected_delivery < current_date),
             'portal_unseen',    count(*) FILTER (WHERE po.status IN ('ordered', 'partially_received')
                                                    AND pub.status = 'sent'),
             'portal_confirmed', count(*) FILTER (WHERE po.status IN ('ordered', 'partially_received')
                                                    AND pub.status = 'confirmed')
           )
      INTO v_purchases
      FROM public.purchase_orders po
      LEFT JOIN public.supplier_po_publications pub ON pub.purchase_order_id = po.id
     WHERE po.organization_id = p_organization_id
       AND po.deleted_at IS NULL;
  ELSIF v_can_rec THEN
    -- Só purchase_orders.receive: campos de POs a null, guias abaixo.
    v_purchases := jsonb_build_object(
      'pending_approval', NULL, 'late', NULL,
      'portal_unseen',    NULL, 'portal_confirmed', NULL
    );
  END IF;

  IF v_can_rec THEN
    -- Guias do fornecedor em aberto e, dessas, as com divergências ao vivo.
    WITH dn AS (
      SELECT n.id
        FROM public.supplier_delivery_notes n
       WHERE n.organization_id = p_organization_id
         AND n.status = 'open'
    ), ann AS (
      SELECT l.delivery_note_id AS note_id, l.product_id,
             sum(l.quantity * l.units_per_uom) AS units
        FROM public.supplier_delivery_note_lines l
        JOIN dn ON dn.id = l.delivery_note_id
       GROUP BY 1, 2
    ), rcv AS (
      SELECT pr.delivery_note_id AS note_id,
             COALESCE(pr.product_id, poi.product_id) AS product_id,
             sum(pr.quantity * pr.units_per_uom) AS units
        FROM public.purchase_order_receipts pr
        JOIN dn ON dn.id = pr.delivery_note_id
        LEFT JOIN public.purchase_order_items poi ON poi.id = pr.purchase_order_item_id
       WHERE pr.kind = 'receipt'
         AND pr.reverted_at IS NULL
       GROUP BY 1, 2
    )
    SELECT (SELECT count(*) FROM dn)::int,
           (SELECT count(DISTINCT COALESCE(a.note_id, r.note_id))
              FROM ann a
              FULL JOIN rcv r ON r.note_id = a.note_id AND r.product_id = a.product_id
             WHERE COALESCE(a.note_id, r.note_id) IN (SELECT note_id FROM ann)  -- só guias com linhas
               AND COALESCE(a.units, 0) <> COALESCE(r.units, 0))::int
      INTO v_open_dn, v_div_dn;

    v_purchases := v_purchases || jsonb_build_object(
      'open_delivery_notes',             v_open_dn,
      'delivery_notes_with_divergences', v_div_dn
    );
  END IF;

  -- ── 2. Fornecedores (suppliers.view) ───────────────────────────────────────
  IF v_can_sup THEN
    v_suppliers := jsonb_build_object(
      -- Pedidos de preço por decidir (fornecedor não apagado). Só com
      -- permissão de preços, como a RLS da tabela.
      'price_changes_pending',
        CASE WHEN v_can_pricing THEN (
          SELECT count(*)::int
            FROM public.supplier_price_change_requests pcr
            JOIN public.suppliers s ON s.id = pcr.supplier_id AND s.deleted_at IS NULL
           WHERE pcr.organization_id = p_organization_id
             AND pcr.status = 'pending'
        ) END,
      -- Fornecedores com ligação ativa ao portal cujo owner ainda não
      -- confirmou os dados (supplier_portal_users.profile_confirmed_at).
      'awaiting_profile', (
        SELECT count(DISTINCT l.supplier_id)::int
          FROM public.supplier_account_links l
          JOIN public.supplier_accounts a ON a.id = l.supplier_account_id AND a.status = 'active'
          JOIN public.suppliers s ON s.id = l.supplier_id AND s.deleted_at IS NULL
         WHERE l.organization_id = p_organization_id
           AND l.status = 'active'
           AND NOT EXISTS (
             SELECT 1 FROM public.supplier_portal_users u
              WHERE u.supplier_account_id = l.supplier_account_id
                AND u.role = 'owner'
                AND u.status = 'active'
                AND u.profile_confirmed_at IS NOT NULL
           )
      ),
      -- Fila "por ligar" do catálogo do fornecedor: mesma regra de
      -- rpc_supplier_catalog_list(p_filter => 'unlinked') (definição de
      -- 20261211150000), somada por todos os fornecedores da organização.
      -- Como lá (fn_sp_crm_supplier_org), exige perfil do CRM; senão null.
      'catalog_unlinked',
        CASE WHEN public.current_business_user_id() IS NOT NULL THEN (
          SELECT count(*)::int
            FROM public.suppliers s
            JOIN public.supplier_account_links l
              ON l.supplier_id = s.id AND l.status = 'active'
            JOIN public.supplier_catalog_items ci
              ON ci.supplier_account_id = l.supplier_account_id AND ci.is_active
           WHERE s.organization_id = p_organization_id
             AND s.deleted_at IS NULL
             AND NOT EXISTS (SELECT 1 FROM public.item_suppliers isup
                              WHERE isup.supplier_id = s.id
                                AND isup.catalog_item_id = ci.id
                                AND isup.deleted_at IS NULL)
             AND NOT EXISTS (SELECT 1 FROM public.supplier_catalog_dismissals d
                              WHERE d.link_id = l.id
                                AND d.catalog_item_id = ci.id)
        ) END
    );
  END IF;

  -- ── 3. Encomendas de Cliente + unidades reservadas (uma só passagem) ───────
  IF v_can_ec OR v_can_inv THEN
    -- r é MATERIALIZED: a função corre uma só vez e o mesmo resultado serve
    -- reserved_units (bloco stock, via v_reserved) e o bloco client_orders.
    WITH r AS MATERIALIZED (
      SELECT * FROM public.fn_client_order_line_reservations(p_organization_id, NULL)
    ), per_contract AS (
      -- Linha concluída = 'stock'/'received' na lista; o resto (awaiting,
      -- partial, no_supplier) deixa a EC em aberto.
      SELECT r.contract_id,
             bool_or(COALESCE(r.qty_reserved, 0) > 0) AS has_ready,
             -- Em falta, nada pedido e produto sem fornecedor preferido:
             -- critério v_has_pref de rpc_get_client_order_document
             -- (20261206150000).
             bool_or(COALESCE(r.qty_missing, 0) > 0
                     AND COALESCE(r.qty_ordered, 0) = 0
                     AND NOT EXISTS (
                       SELECT 1
                         FROM public.item_suppliers isup
                        WHERE isup.product_id = r.product_id
                          AND isup.is_preferred = true
                          AND isup.deleted_at IS NULL
                          AND isup.is_active = true
                          AND isup.organization_id = p_organization_id
                     )) AS has_missing
        FROM r
       WHERE NOT (
               r.is_served
               OR (COALESCE(r.qty_reserved, 0) = 0
                   AND COALESCE(r.qty_served, 0) = 0
                   AND COALESCE(r.qty_missing, 0) = 0
                   AND COALESCE(r.qty_ordered, 0) > 0
                   AND COALESCE(r.qty_received, 0) >= r.qty_ordered)
             )
       GROUP BY r.contract_id
    ), open_ec AS (
      SELECT pc.has_ready, pc.has_missing,
             CASE
               WHEN EXISTS (SELECT 1 FROM public.direct_sales d WHERE d.client_contract_id = cc.id) THEN 'direct_sale'
               WHEN COALESCE(cc.is_manual_order, false) THEN 'manual'
               ELSE 'contract'
             END AS origin
        FROM per_contract pc
        JOIN public.client_contracts cc ON cc.id = pc.contract_id
    )
    SELECT
      (SELECT COALESCE(sum(COALESCE(r.qty_reserved, 0)), 0) FROM r WHERE r.product_id IS NOT NULL),
      (SELECT jsonb_build_object(
                'open',                       count(*),
                'ready_to_ship',              count(*) FILTER (WHERE e.has_ready),
                'without_preferred_supplier', count(*) FILTER (WHERE e.has_missing),
                'by_origin', jsonb_build_object(
                  'contract',    count(*) FILTER (WHERE e.origin = 'contract'),
                  'direct_sale', count(*) FILTER (WHERE e.origin = 'direct_sale'),
                  'manual',      count(*) FILTER (WHERE e.origin = 'manual')
                )
              )
         FROM open_ec e)
      INTO v_reserved, v_client_ord;

    IF NOT v_can_ec THEN
      v_client_ord := NULL;
    END IF;
  END IF;

  -- ── 4. Stock, contagens e definições (inventory.view) ──────────────────────
  IF v_can_inv THEN
    -- Mesmas linhas que a lista de Existências por omissão (Stocks.tsx):
    -- stocks não apagados da organização com produto existente
    -- (products!inner); o armazém é LEFT na lista, sem filtro de
    -- is_active/deleted_at, por isso aqui também não se filtra.
    -- reorder_point / maximum_quantity são NOT NULL DEFAULT 0: 0 = não
    -- definido. Estado como getStockStatusCode: low primeiro, depois
    -- overstock (quantity >= maximum_quantity).
    SELECT jsonb_build_object(
             'below_reorder_point', count(*) FILTER (WHERE s.reorder_point > 0 AND s.quantity <= s.reorder_point),
             'overstock',           count(*) FILTER (WHERE s.maximum_quantity > 0 AND s.quantity >= s.maximum_quantity
                                                       AND NOT (s.reorder_point > 0 AND s.quantity <= s.reorder_point)),
             'reserved_units',      COALESCE(v_reserved, 0),
             'value',               CASE WHEN v_can_cost THEN
                                      round(COALESCE(sum(s.quantity * s.average_cost)
                                                       FILTER (WHERE s.quantity > 0 AND s.average_cost IS NOT NULL), 0), 2)
                                    END
           )
      INTO v_stock
      FROM public.stocks s
      JOIN public.products p ON p.id = s.product_id
     WHERE s.organization_id = p_organization_id
       AND s.deleted_at IS NULL;

    -- Contagens em curso; parada = sem atividade (cabeçalho ou linhas) há
    -- mais de 7 dias.
    SELECT jsonb_build_object(
             'in_progress', count(*),
             'stalled',     count(*) FILTER (WHERE GREATEST(c.started_at, c.updated_at, la.last_at) < now() - interval '7 days')
           )
      INTO v_counts
      FROM public.inventory_counts c
      LEFT JOIN LATERAL (
        SELECT max(GREATEST(l.updated_at, l.counted_at)) AS last_at
          FROM public.inventory_count_lines l
         WHERE l.inventory_count_id = c.id
      ) la ON true
     WHERE c.organization_id = p_organization_id
       AND c.status = 'em_contagem';

    -- Sem linha de definições vale 'contract_signed' (como os gatilhos de stock).
    v_settings := jsonb_build_object(
      'stock_deduction_trigger',
      COALESCE(
        (SELECT ois.stock_deduction_trigger
           FROM public.organization_inventory_settings ois
          WHERE ois.organization_id = p_organization_id),
        'contract_signed'
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'purchases',     v_purchases,
    'suppliers',     v_suppliers,
    'client_orders', v_client_ord,
    'stock',         v_stock,
    'counts',        v_counts,
    'settings',      v_settings
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_inventory_today(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_inventory_today(p_organization_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_inventory_today(p_organization_id uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_inventory_today(p_organization_id uuid) IS 'Contadores do ecrã Hoje do Inventário (compras, fornecedores, encomendas de cliente, stock, contagens, definições) da organização ativa. Cada bloco exige a sua permissão (null sem ela). Exige org visível. Só leitura.';

CREATE OR REPLACE FUNCTION public.rpc_ops_entrar_como_terminar(p_log_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_n integer;
BEGIN
  UPDATE public.ops_entrar_como_log
     SET fim = now()
   WHERE id = p_log_id
     AND admin_id = public.current_business_user_id()
     AND fim IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_n > 0);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_entrar_como_terminar(p_log_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_entrar_como_terminar(p_log_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_entrar_como_terminar(p_log_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_equipa_crm(p_org uuid)
 RETURNS TABLE(utilizador_id uuid, nome text, email text, telefone text, avatar_url text, cargo_crm text, local_crm text, papel_crm text, papel_crm_codigo text, equipa_crm text, distritos text[], codigos_postais text[], em_operacoes boolean, funcao text, ativo boolean, zona_base text, skills uuid[], skills_nomes text[], custo_hora numeric, pode_ver_custos boolean, rh_disponivel boolean, rh_ligado boolean, numero_interno text, cargo text, local_trabalho text, tipo_contrato text, regime text, categoria_funcao text, estado_contrato text, data_admissao date, ausencia_tipo text, ausencia_inicio date, ausencia_fim date, ausencia_origem text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_custos  boolean;
  v_gerir   boolean;
  v_rh      boolean := to_regclass('public.pessoas_contas') IS NOT NULL
                       AND to_regclass('public.pessoas') IS NOT NULL;
  v_agenda  boolean := to_regclass('public.schedule_resources') IS NOT NULL;

  f_equipa  text := 'NULL::text';
  f_dist    text := 'NULL::text[]';
  f_cps     text := 'NULL::text[]';
  j_rh      text := 'LEFT JOIN LATERAL (SELECT NULL::uuid AS pessoa_id, NULL::jsonb AS j) pe ON true';
  f_cargo   text := 'NULL::text';
  j_vinc    text := 'LEFT JOIN LATERAL (SELECT NULL::jsonb AS vj) vi ON true';
  f_local   text := 'NULL::text';
  q_aus     text[] := '{}';
  j_aus     text;
  v_sql     text;
BEGIN
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'Falta a organização.';
  END IF;

  IF NOT public.ops_pode(p_org, 'operations.view') THEN
    RAISE EXCEPTION 'Sem acesso a Operações nesta organização.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_custos := public.ops_pode(p_org, 'operations.costs.view');
  v_gerir  := public.ops_pode(p_org, 'operations.settings.manage');

  -- ── CRM: equipa ─────────────────────────────────────────────────────────
  IF to_regclass('public.organization_teams') IS NOT NULL
     AND to_regclass('public.organization_team_members') IS NOT NULL THEN
    f_equipa := $q$(SELECT string_agg(t.name::text, ', ' ORDER BY t.name::text)
         FROM public.organization_team_members tm
         JOIN public.organization_teams t ON t.id = tm.team_id
        WHERE tm.user_id = u.id AND t.organization_id = $1
          AND COALESCE((to_jsonb(t)->>'is_active')::boolean, true))$q$;
  END IF;

  -- ── CRM: distritos e códigos postais da agenda ──────────────────────────
  IF v_agenda AND to_regclass('public.resource_districts') IS NOT NULL
     AND to_regclass('public.administrative_divisions') IS NOT NULL THEN
    f_dist := $q$ARRAY(
        SELECT x.nome FROM (
          SELECT ad.name::text AS nome, min(rd.priority) AS pr
            FROM public.schedule_resources sr
            JOIN public.resource_districts rd ON rd.resource_id = sr.id AND rd.is_active
            JOIN public.administrative_divisions ad ON ad.id = rd.district_id
           WHERE sr.user_id = u.id AND sr.organization_id = $1
             AND COALESCE(sr.is_active, true)
           GROUP BY ad.name) x
        ORDER BY x.pr, x.nome)$q$;
  END IF;

  IF v_agenda AND to_regclass('public.resource_service_areas') IS NOT NULL THEN
    f_cps := $q$ARRAY(
        SELECT DISTINCT sa.postal_code_prefix::text
          FROM public.schedule_resources sr
          JOIN public.resource_service_areas sa ON sa.resource_id = sr.id
                AND COALESCE(sa.is_active, true)
         WHERE sr.user_id = u.id AND sr.organization_id = $1
           AND COALESCE(sr.is_active, true)
         ORDER BY 1)$q$;
  END IF;

  -- ── CRM: ausências aprovadas na agenda (só o título — nunca o motivo) ──
  IF v_agenda AND to_regclass('public.resource_time_off') IS NOT NULL THEN
    q_aus := array_append(q_aus, $q$SELECT COALESCE(nullif(btrim(t.title), ''), 'Ausência')::text AS tipo,
             t.start_date::date AS inicio, t.end_date::date AS fim, 'crm'::text AS origem
        FROM public.schedule_resources sr
        JOIN public.resource_time_off t ON t.resource_id = sr.id
       WHERE sr.user_id = u.id AND sr.organization_id = $1
         AND t.approved IS TRUE
         AND t.end_date >= current_date
         AND t.start_date <= current_date + 60$q$);
  END IF;

  -- ── RH (só se o módulo existir nesta base) ──────────────────────────────
  IF v_rh THEN
    -- A ficha ligada à conta, nesta organização. `to_jsonb(pe)` lê colunas
    -- que podem ainda não existir sem rebentar; e do resultado só se tiram
    -- os campos listados abaixo.
    j_rh := $q$LEFT JOIN LATERAL (
        SELECT pe0.id AS pessoa_id, to_jsonb(pe0) AS j
          FROM public.pessoas_contas pc
          JOIN public.pessoas pe0 ON pe0.id = pc.pessoa_id
                                 AND pe0.organization_id = pc.organization_id
         WHERE pc.anew_user_id = u.id AND pc.organization_id = $1
           AND pc.estado = 'activa'
           AND pe0.deleted_at IS NULL
         ORDER BY pc.ligada_em DESC
         LIMIT 1) pe ON true$q$;

    f_cargo := $q$nullif(btrim(pe.j->>'cargo'), '')$q$;
    IF to_regclass('public.hr_cargos') IS NOT NULL THEN
      -- Só o nome. O salário-base vive na mesma linha e não sai daqui.
      f_cargo := $q$COALESCE(
          (SELECT c.nome FROM public.hr_cargos c
            WHERE c.id::text = pe.j->>'cargo_id' AND c.organization_id = $1
              AND c.deleted_at IS NULL),
          nullif(btrim(pe.j->>'cargo'), ''))$q$;
    END IF;

    f_local := $q$nullif(btrim(pe.j->>'local_trabalho'), '')$q$;
    IF to_regclass('public.hr_locais_trabalho') IS NOT NULL THEN
      f_local := $q$(SELECT l.nome FROM public.hr_locais_trabalho l
                      WHERE l.id::text = pe.j->>'local_id' AND l.organization_id = $1
                        AND l.deleted_at IS NULL)$q$;
      IF to_regclass('public.pessoas_afectacoes') IS NOT NULL THEN
        f_local := $q$(SELECT l.nome FROM public.pessoas_afectacoes a
                        JOIN public.hr_locais_trabalho l ON l.id = a.local_id
                       WHERE a.pessoa_id = pe.pessoa_id AND a.organization_id = $1
                         AND a.deleted_at IS NULL
                         AND a.valido_de <= current_date
                         AND (a.valido_ate IS NULL OR a.valido_ate >= current_date)
                       ORDER BY a.valido_de DESC LIMIT 1)$q$ || ', ' || f_local;
      END IF;
      f_local := 'COALESCE(' || f_local || $q$, nullif(btrim(pe.j->>'local_trabalho'), ''))$q$;
    END IF;

    IF to_regclass('public.pessoas_vinculos') IS NOT NULL THEN
      -- O vínculo ativo; se ainda não houver, o futuro mais próximo.
      j_vinc := $q$LEFT JOIN LATERAL (
          SELECT to_jsonb(v) AS vj FROM public.pessoas_vinculos v
           WHERE v.pessoa_id = pe.pessoa_id AND v.organization_id = $1
             AND v.deleted_at IS NULL AND v.estado IN ('activo','futuro')
           ORDER BY (v.estado = 'activo') DESC, v.data_inicio DESC
           LIMIT 1) vi ON true$q$;
    END IF;

    IF to_regclass('public.pessoas_ausencias_pedidos') IS NOT NULL
       AND to_regclass('public.hr_ausencias_tipos') IS NOT NULL THEN
      -- Doença e parentalidade são dados de saúde/família: só "Ausência".
      q_aus := array_append(q_aus, $q$SELECT (CASE WHEN ti.categoria IN ('doenca','parentalidade') THEN 'Ausência'
                    ELSE ti.nome END)::text AS tipo,
             ap.data_inicio::date AS inicio, ap.data_fim::date AS fim, 'rh'::text AS origem
        FROM public.pessoas_ausencias_pedidos ap
        JOIN public.hr_ausencias_tipos ti ON ti.id = ap.tipo_id
       WHERE ap.pessoa_id = pe.pessoa_id AND ap.organization_id = $1
         AND ap.estado = 'aprovado'
         AND ap.data_fim >= current_date
         AND ap.data_inicio <= current_date + 60$q$);
    END IF;
  END IF;

  IF cardinality(q_aus) = 0 THEN
    j_aus := 'LEFT JOIN LATERAL (SELECT NULL::text AS tipo, NULL::date AS inicio, '
          || 'NULL::date AS fim, NULL::text AS origem) au ON true';
  ELSE
    j_aus := 'LEFT JOIN LATERAL (SELECT x.* FROM ('
          || array_to_string(q_aus, ' UNION ALL ')
          || ') x ORDER BY x.inicio, x.fim LIMIT 1) au ON true';
  END IF;

  v_sql := $q$
    SELECT
      u.id,
      COALESCE(nullif(btrim(u.name), ''), u.email, '—')::text,
      u.email::text,
      nullif(btrim(u.phone), '')::text,
      nullif(btrim(u.avatar_url), '')::text,
      nullif(btrim(to_jsonb(u)->>'position'), ''),
      nullif(btrim(to_jsonb(u)->>'location'), ''),
      pap.nome,
      pap.codigo,
      $q$ || f_equipa || $q$,
      $q$ || f_dist || $q$,
      $q$ || f_cps || $q$,
      (p.utilizador_id IS NOT NULL),
      p.funcao::text,
      p.ativo,
      nullif(btrim(p.zona_base), '')::text,
      COALESCE(sk.ids, '{}'::uuid[]),
      COALESCE(sk.nomes, '{}'::text[]),
      CASE WHEN $2 THEN p.custo_hora::numeric END,
      $2,
      $4,
      (pe.pessoa_id IS NOT NULL),
      nullif(btrim(pe.j->>'numero_interno'), ''),
      $q$ || f_cargo || $q$,
      $q$ || f_local || $q$,
      CASE WHEN $3 THEN vi.vj->>'tipo_contrato' END,
      CASE WHEN $3 THEN vi.vj->>'regime' END,
      CASE WHEN $3 THEN vi.vj->>'categoria_funcao' END,
      CASE WHEN $3 THEN pe.j->>'estado_contrato' END,
      CASE WHEN $3 THEN (pe.j->>'data_admissao')::date END,
      au.tipo,
      au.inicio,
      au.fim,
      au.origem
    FROM (SELECT DISTINCT m.user_id
            FROM public.anew_memberships m
           WHERE m.organization_id = $1 AND m.status = 'active') mm
    JOIN public.anew_users u ON u.id = mm.user_id
    LEFT JOIN public.ops_utilizador_perfil p
           ON p.utilizador_id = u.id AND p.organization_id = $1
    LEFT JOIN LATERAL (
      SELECT string_agg(DISTINCT r.name::text, ', ') AS nome,
             string_agg(DISTINCT (to_jsonb(r)->>'code'), ', ') AS codigo
        FROM public.anew_memberships m2
        JOIN public.anew_roles r ON r.id = m2.role_id
       WHERE m2.user_id = u.id AND m2.organization_id = $1 AND m2.status = 'active'
    ) pap ON true
    LEFT JOIN LATERAL (
      SELECT array_agg(k.id ORDER BY k.nome) AS ids,
             array_agg(k.nome::text ORDER BY k.nome) AS nomes
        FROM public.ops_utilizador_skill us
        JOIN public.ops_skill k ON k.id = us.skill_id AND k.organization_id = $1
       WHERE us.utilizador_id = u.id
    ) sk ON true
    $q$ || j_rh || $q$
    $q$ || j_vinc || $q$
    $q$ || j_aus || $q$
    ORDER BY 2$q$;

  RETURN QUERY EXECUTE v_sql USING p_org, v_custos, v_gerir, v_rh;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_equipa_crm(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_equipa_crm(p_org uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_equipa_crm(p_org uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_ops_equipa_crm(p_org uuid) IS 'Operações: a equipa de uma organização lida do CRM (anew_users, papéis, equipas, agenda) e, se existir, do RH (ficha, cargo, vínculo, local, ausências), mais o perfil de Operações. Só leitura. custo_hora só com operations.costs.view; dados contratuais só com operations.settings.manage.';

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_alertas(p_org uuid)
 RETURNS TABLE(tipo text, gravidade smallint, tarefa_id uuid, obra_id uuid, obra_codigo text, obra_titulo text, tarefa_nome text, pessoas uuid[], pessoas_nomes text[], desde timestamp with time zone, minutos_atraso integer, detalhe text, atraso_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_eu     uuid;
  v_funcao text;
BEGIN
  -- Primeiro quem chama (recusa quem não é desta organização), depois o resto.
  SELECT q.utilizador_id, q.funcao INTO v_eu, v_funcao FROM public.ops_quem_sou(p_org) q;
  IF NOT public.ops_pode(p_org, 'operations.orders.view') THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT a.tipo, a.gravidade, a.tarefa_id, a.obra_id, a.obra_codigo, a.obra_titulo, a.tarefa_nome,
         a.pessoas,
         COALESCE((SELECT array_agg(COALESCE(u.name, 'Sem nome') ORDER BY p.k)
                     FROM unnest(a.pessoas) WITH ORDINALITY AS p(id, k)
                     LEFT JOIN public.anew_users u ON u.id = p.id), '{}'::text[]),
         a.desde, a.minutos_atraso, a.detalhe, a.atraso_id
    FROM public.ops_obra_alertas_lista(p_org, NULL) a
   WHERE v_funcao IN ('admin','gestor') OR a.supervisor_id = v_eu
   ORDER BY a.gravidade, a.minutos_atraso DESC NULLS LAST, a.obra_codigo, a.tarefa_nome;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_alertas(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_alertas(p_org uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_alertas(p_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_aviso_bancada(p_obra_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
BEGIN
  IF NOT public.ops_pode_ver_obra(p_obra_id) THEN
    RAISE EXCEPTION 'Obra não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT jsonb_build_object(
           'enviado_em', a.enviado_em,
           'sem_especialidade', a.sem_especialidade,
           'para', COALESCE((SELECT jsonb_agg(COALESCE(u.name, 'Sem nome') ORDER BY u.name)
                               FROM public.anew_users u WHERE u.id = ANY (a.destinatarios)), '[]'::jsonb),
           'primeira', a.detalhe->>'primeira',
           'datas', a.detalhe->>'datas',
           'medidas', a.detalhe->>'medidas',
           'local', a.detalhe->>'local')
    INTO v
    FROM public.ops_obra_aviso a
   WHERE a.obra_id = p_obra_id AND a.tipo = 'bancada';
  RETURN COALESCE(v, '{}'::jsonb);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_aviso_bancada(p_obra_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_aviso_bancada(p_obra_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_aviso_bancada(p_obra_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_cliente_avisado(p_atraso_id uuid, p_nota text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_a    record;
  v_quem record;
  v_nota text := nullif(btrim(coalesce(p_nota, '')), '');
BEGIN
  SELECT a.*, o.supervisor_id AS obra_supervisor, o.estado AS obra_estado, t.nome AS tarefa_nome
    INTO v_a
    FROM public.ops_obra_tarefa_atraso a
    JOIN public.ops_obra o ON o.id = a.obra_id
    JOIN public.ops_obra_tarefa t ON t.id = a.tarefa_id
   WHERE a.id = p_atraso_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Atraso não encontrado.' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT q.utilizador_id, q.funcao INTO v_quem FROM public.ops_quem_sou(v_a.organization_id) q;
  IF NOT (
       (v_quem.funcao IN ('admin','gestor') AND public.ops_pode(v_a.organization_id, 'operations.orders.edit'))
    OR (v_a.obra_supervisor = v_quem.utilizador_id
        AND public.ops_pode(v_a.organization_id, 'operations.orders.confirm'))
  ) THEN
    RAISE EXCEPTION 'Só o supervisor da obra ou o gestor marcam o cliente como avisado.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_a.cliente_avisado THEN
    RETURN jsonb_build_object('ok', true, 'ja_avisado', true, 'cliente_avisado_em', v_a.cliente_avisado_em);
  END IF;

  UPDATE public.ops_obra_tarefa_atraso
     SET cliente_avisado = true, cliente_avisado_em = now(),
         cliente_avisado_por = v_quem.utilizador_id, nota_cliente = v_nota
   WHERE id = p_atraso_id;

  PERFORM public.ops_obra_evento(v_a.organization_id, v_a.obra_id, 'cliente_avisado',
    v_a.tarefa_nome || COALESCE(': ' || v_nota, ''), v_quem.utilizador_id,
    jsonb_build_object('atraso_id', p_atraso_id, 'tarefa_id', v_a.tarefa_id, 'nota', v_nota));

  RETURN jsonb_build_object('ok', true, 'ja_avisado', false);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_cliente_avisado(p_atraso_id uuid, p_nota text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_cliente_avisado(p_atraso_id uuid, p_nota text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_cliente_avisado(p_atraso_id uuid, p_nota text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_ficha_local(p_obra_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_o   record;
  v_orc uuid;
  v_f   jsonb;
BEGIN
  SELECT id, organization_id, orcamento_id, contrato_id INTO v_o FROM public.ops_obra WHERE id = p_obra_id;
  IF NOT FOUND OR NOT public.ops_pode_ver_obra(p_obra_id) THEN
    RAISE EXCEPTION 'Obra não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;
  v_orc := v_o.orcamento_id;
  IF v_orc IS NULL AND v_o.contrato_id IS NOT NULL THEN
    v_orc := public.ops_contrato_orcamento(v_o.contrato_id);
  END IF;
  IF v_orc IS NULL
     OR NOT public.ops_obra_crm_tem('anew_address_building', ARRAY['address_id'])
     OR NOT public.ops_obra_crm_tem('anew_addresses', ARRAY['id','floor'])
     OR NOT public.ops_obra_crm_tem('quotes', ARRAY['id','site_address_id']) THEN
    RETURN '{}'::jsonb;
  END IF;

  EXECUTE 'SELECT (to_jsonb(b) - ''created_by'' - ''updated_by'' - ''created_at'')
                  || jsonb_build_object(''piso'', a.floor)
             FROM public.quotes q
             JOIN public.anew_address_building b ON b.address_id = q.site_address_id
             LEFT JOIN public.anew_addresses a ON a.id = q.site_address_id
            WHERE q.id = $1'
     INTO v_f USING v_orc;
  RETURN COALESCE(v_f, '{}'::jsonb);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_ficha_local(p_obra_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_ficha_local(p_obra_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_ficha_local(p_obra_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_gravar_dependencias(p_tarefa_id uuid, p_depende_de uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t     record;
  v_quem  record;
  v_lista uuid[];
  v_mau   uuid;
BEGIN
  SELECT t.*, o.estado AS obra_estado INTO v_t
    FROM public.ops_obra_tarefa t JOIN public.ops_obra o ON o.id = t.obra_id
   WHERE t.id = p_tarefa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tarefa não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT * INTO v_quem FROM public.ops_obra_exigir(
    v_t.organization_id, 'operations.orders.edit', ARRAY['gestor'],
    'Só quem planeia muda as dependências.');
  IF v_t.obra_estado IN ('concluida','cancelada') THEN
    RAISE EXCEPTION 'A obra está %; já não se planeia.', v_t.obra_estado;
  END IF;

  -- Sem repetidos, pela ordem dada.
  SELECT COALESCE(array_agg(u ORDER BY pos), '{}') INTO v_lista
    FROM (SELECT u, min(pos) AS pos
            FROM unnest(COALESCE(p_depende_de, '{}'::uuid[])) WITH ORDINALITY AS x(u, pos)
           WHERE u IS NOT NULL GROUP BY u) z;
  IF p_tarefa_id = ANY (v_lista) THEN
    RAISE EXCEPTION 'Uma tarefa não pode depender de si própria.';
  END IF;
  SELECT u INTO v_mau FROM unnest(v_lista) u
   WHERE NOT EXISTS (SELECT 1 FROM public.ops_obra_tarefa d WHERE d.id = u AND d.obra_id = v_t.obra_id)
   LIMIT 1;
  IF v_mau IS NOT NULL THEN
    RAISE EXCEPTION 'Uma tarefa só pode depender de outra da mesma obra.';
  END IF;

  -- Primeiro a coluna (o trigger tira a antiga e põe a nova), depois o resto.
  UPDATE public.ops_obra_tarefa SET depende_de = v_lista[1], atualizada_em = now()
   WHERE id = p_tarefa_id AND depende_de IS DISTINCT FROM v_lista[1];
  DELETE FROM public.ops_obra_tarefa_dependencia
   WHERE tarefa_id = p_tarefa_id AND NOT (depende_de_id = ANY (v_lista));
  INSERT INTO public.ops_obra_tarefa_dependencia (tarefa_id, depende_de_id, organization_id, obra_id)
  SELECT p_tarefa_id, u, v_t.organization_id, v_t.obra_id FROM unnest(v_lista) u
  ON CONFLICT DO NOTHING;

  PERFORM public.ops_obra_evento(v_t.organization_id, v_t.obra_id, 'dependencias', v_t.nome,
    v_quem.o_utilizador, jsonb_build_object('tarefa_id', p_tarefa_id, 'depende_de', to_jsonb(v_lista)));

  RETURN jsonb_build_object(
    'ok', true,
    'dependencias', to_jsonb(v_lista),
    'antes_de_acabar', COALESCE((
       SELECT jsonb_agg(d.id) FROM public.ops_obra_tarefa d
        WHERE d.id = ANY (v_lista) AND v_t.inicio_planeado IS NOT NULL
          AND COALESCE(d.fim_planeado, d.inicio_planeado) > v_t.inicio_planeado), '[]'::jsonb));
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_gravar_dependencias(p_tarefa_id uuid, p_depende_de uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_gravar_dependencias(p_tarefa_id uuid, p_depende_de uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_gravar_dependencias(p_tarefa_id uuid, p_depende_de uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_material_chega(p_tarefa_id uuid, p_data date, p_nota text DEFAULT NULL::text, p_simular boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t       record;
  v_quem    record;
  v_ini     date;
  v_fim     date;
  v_mexidas jsonb := '{}'::jsonb;
  v_obra_ant date;
  v_obra_novo date;
  v_res     jsonb;
  v_moveu   boolean := false;
BEGIN
  SELECT t.*, o.estado AS obra_estado, o.supervisor_id AS obra_supervisor
    INTO v_t
    FROM public.ops_obra_tarefa t JOIN public.ops_obra o ON o.id = t.obra_id
   WHERE t.id = p_tarefa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tarefa não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT q.utilizador_id, q.funcao INTO v_quem FROM public.ops_quem_sou(v_t.organization_id) q;
  IF NOT (
       (v_quem.funcao IN ('admin','gestor') AND public.ops_pode(v_t.organization_id, 'operations.orders.edit'))
    OR (v_t.obra_supervisor = v_quem.utilizador_id
        AND public.ops_pode(v_t.organization_id, 'operations.orders.confirm'))
  ) THEN
    RAISE EXCEPTION 'Só o gestor ou o supervisor da obra dizem quando chega o material.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_t.obra_estado IN ('concluida','cancelada') THEN
    RAISE EXCEPTION 'A obra está %.', v_t.obra_estado;
  END IF;

  SELECT max(COALESCE(fim_planeado, inicio_planeado)) INTO v_obra_ant
    FROM public.ops_obra_tarefa WHERE obra_id = v_t.obra_id;

  BEGIN
    UPDATE public.ops_obra_tarefa
       SET material_chega_em     = p_data,
           material_chega_origem = CASE WHEN p_data IS NULL THEN NULL ELSE 'manual' END,
           material_chega_nota   = CASE WHEN p_data IS NULL THEN NULL
                                        ELSE left(nullif(btrim(COALESCE(p_nota, '')), ''), 500) END,
           atualizada_em         = now()
     WHERE id = p_tarefa_id;

    IF p_data IS NOT NULL AND v_t.estado = 'por_fazer' AND v_t.inicio_planeado IS NOT NULL
       AND v_t.inicio_planeado < p_data
       AND NOT EXISTS (SELECT 1 FROM public.ops_obra_registo r WHERE r.tarefa_id = p_tarefa_id) THEN
      v_ini := public.ops_obra_somar_dias_uteis_org(v_t.organization_id, p_data, 0);
      v_fim := public.ops_obra_somar_dias_uteis_org(v_t.organization_id, v_ini,
                 public.ops_obra_dias_uteis_entre_org(v_t.organization_id, v_t.inicio_planeado,
                                                      COALESCE(v_t.fim_planeado, v_t.inicio_planeado)));
      UPDATE public.ops_obra_tarefa
         SET inicio_original = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                    THEN inicio_planeado ELSE inicio_original END,
             fim_original    = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                    THEN fim_planeado ELSE fim_original END,
             inicio_planeado = v_ini,
             fim_planeado    = v_fim
       WHERE id = p_tarefa_id;
      v_moveu := true;
      v_mexidas := public.ops_obra_empurrar_dependentes_impl(
                     p_tarefa_id, COALESCE(v_t.fim_planeado, v_t.inicio_planeado));
    END IF;

    SELECT max(COALESCE(fim_planeado, inicio_planeado)) INTO v_obra_novo
      FROM public.ops_obra_tarefa WHERE obra_id = v_t.obra_id;

    IF NOT COALESCE(p_simular, false) THEN
      PERFORM public.ops_obra_evento(v_t.organization_id, v_t.obra_id, 'material',
        v_t.nome || ': material ' || COALESCE('chega a ' || to_char(p_data, 'DD/MM/YYYY'), 'já não condiciona'),
        v_quem.utilizador_id,
        jsonb_build_object('tarefa_id', p_tarefa_id, 'data', p_data, 'moveu', v_moveu,
                           'empurradas', (SELECT count(*) FROM jsonb_object_keys(v_mexidas)),
                           'fim_obra_anterior', v_obra_ant, 'fim_obra_novo', v_obra_novo));
    END IF;

    v_res := jsonb_build_object(
      'ok', true,
      'simulado', COALESCE(p_simular, false),
      'moveu', v_moveu,
      'novo_inicio', CASE WHEN v_moveu THEN v_ini END,
      'novo_fim', CASE WHEN v_moveu THEN v_fim END,
      'empurradas', COALESCE((SELECT jsonb_agg(e.value ORDER BY e.value->>'novo_inicio', e.value->>'nome')
                                FROM jsonb_each(v_mexidas) e), '[]'::jsonb),
      'fim_obra_anterior', v_obra_ant,
      'fim_obra_novo', v_obra_novo);

    IF COALESCE(p_simular, false) THEN
      RAISE EXCEPTION 'simulação' USING ERRCODE = 'OB001';
    END IF;
  EXCEPTION WHEN SQLSTATE 'OB001' THEN
    NULL;
  END;

  RETURN v_res;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_material_chega(p_tarefa_id uuid, p_data date, p_nota text, p_simular boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_material_chega(p_tarefa_id uuid, p_data date, p_nota text, p_simular boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_material_chega(p_tarefa_id uuid, p_data date, p_nota text, p_simular boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_porque_inicio(p_obra_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_o      record;
  v_inicio date;
  v_desde  date;
  v_funcs  text[];
BEGIN
  SELECT id, organization_id, estado, inicio_auto, data_inicio_prevista,
         (criada_em AT TIME ZONE 'Europe/Lisbon')::date AS criada
    INTO v_o FROM public.ops_obra WHERE id = p_obra_id;
  IF NOT FOUND OR NOT public.ops_pode_ver_obra(p_obra_id) THEN
    RAISE EXCEPTION 'Obra não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT COALESCE(min(inicio_planeado), v_o.data_inicio_prevista) INTO v_inicio
    FROM public.ops_obra_tarefa WHERE obra_id = p_obra_id;
  -- Desde o último replaneamento, se houve; senão, desde a criação.
  SELECT COALESCE(max((e.criado_em AT TIME ZONE 'Europe/Lisbon')::date), v_o.criada) INTO v_desde
    FROM public.ops_evento e
   WHERE e.entidade = 'obra' AND e.entidade_id = p_obra_id AND e.tipo IN ('criada','replaneada');
  v_desde := GREATEST(v_desde, v_o.criada);
  v_funcs := CASE WHEN EXISTS (SELECT 1 FROM public.ops_utilizador_perfil
                                WHERE organization_id = v_o.organization_id AND ativo
                                  AND funcao IN ('tecnico','operador'))
                  THEN ARRAY['tecnico','operador']
                  ELSE ARRAY['admin','gestor','supervisor','tecnico','operador'] END;

  RETURN jsonb_build_object(
    'inicio', v_inicio,
    'desde', v_desde,
    'auto', v_o.inicio_auto,
    'equipa', (SELECT count(*) FROM public.ops_utilizador_perfil
                WHERE organization_id = v_o.organization_id AND ativo AND funcao = ANY (v_funcs)),
    'nesta_obra', COALESCE((
      SELECT jsonb_agg(DISTINCT COALESCE(u.name, 'Sem nome'))
        FROM public.ops_obra_tarefa_pessoa tp
        LEFT JOIN public.anew_users u ON u.id = tp.utilizador_id
       WHERE tp.obra_id = p_obra_id), '[]'::jsonb),
    'ocupacao', COALESCE((
      SELECT jsonb_agg(x ORDER BY x.inicio, x.codigo)
        FROM (
          SELECT o.id AS obra_id, o.codigo, o.titulo,
                 min(t.inicio_planeado) AS inicio,
                 max(COALESCE(t.fim_planeado, t.inicio_planeado)) AS fim,
                 jsonb_agg(DISTINCT COALESCE(u.name, 'Sem nome')) AS pessoas,
                 count(DISTINCT tp.utilizador_id)::integer AS n
            FROM public.ops_obra o
            JOIN public.ops_obra_tarefa t ON t.obra_id = o.id
            JOIN public.ops_obra_tarefa_pessoa tp ON tp.tarefa_id = t.id
            JOIN public.ops_utilizador_perfil p
              ON p.utilizador_id = tp.utilizador_id AND p.organization_id = o.organization_id
             AND p.ativo AND p.funcao = ANY (v_funcs)
            LEFT JOIN public.anew_users u ON u.id = tp.utilizador_id
           WHERE o.organization_id = v_o.organization_id
             AND o.id <> p_obra_id
             AND o.estado IN ('planeada','em_curso')
             AND t.estado IN ('por_fazer','em_curso','rejeitada')
             AND t.inicio_planeado IS NOT NULL
             AND v_inicio IS NOT NULL AND v_inicio > v_desde
             AND t.inicio_planeado < v_inicio
             AND COALESCE(t.fim_planeado, t.inicio_planeado) >= v_desde
           GROUP BY o.id, o.codigo, o.titulo
        ) x), '[]'::jsonb)
  );
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_porque_inicio(p_obra_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_porque_inicio(p_obra_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_porque_inicio(p_obra_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_registar_atraso(p_tarefa_id uuid, p_motivo text, p_contexto text, p_minutos_extra integer DEFAULT NULL::integer, p_novo_fim date DEFAULT NULL::date, p_empurrar boolean DEFAULT true, p_simular boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t         record;
  v_quem      record;
  v_motivo    text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_ctx       text := nullif(btrim(coalesce(p_contexto, '')), '');
  v_simular   boolean := COALESCE(p_simular, false);
  v_hoje      date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
  v_fim_ant   date;
  v_novo      date;
  v_dias      integer;
  v_obra_ant  date;
  v_obra_novo date;
  v_estim     integer;
  v_id        uuid;
  v_mexidas   jsonb := '{}'::jsonb;   -- tarefa → {nome, datas antes e depois}
  v_res       jsonb;
BEGIN
  SELECT t.*, o.estado AS obra_estado, o.supervisor_id AS obra_supervisor, o.minutos_por_dia AS mpd
    INTO v_t
    FROM public.ops_obra_tarefa t JOIN public.ops_obra o ON o.id = t.obra_id
   WHERE t.id = p_tarefa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tarefa não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT q.utilizador_id, q.funcao INTO v_quem FROM public.ops_quem_sou(v_t.organization_id) q;
  IF NOT (
       (v_quem.funcao IN ('admin','gestor') AND public.ops_pode(v_t.organization_id, 'operations.orders.edit'))
    OR (v_t.obra_supervisor = v_quem.utilizador_id
        AND public.ops_pode(v_t.organization_id, 'operations.orders.confirm'))
    OR (EXISTS (SELECT 1 FROM public.ops_obra_tarefa_pessoa
                 WHERE tarefa_id = p_tarefa_id AND utilizador_id = v_quem.utilizador_id)
        AND public.ops_pode(v_t.organization_id, 'operations.orders.execute'))
  ) THEN
    RAISE EXCEPTION 'Só quem está na tarefa, o supervisor da obra ou o gestor registam um atraso.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_t.obra_estado IN ('concluida','cancelada') THEN
    RAISE EXCEPTION 'A obra está %; já não se registam atrasos.', v_t.obra_estado;
  END IF;
  IF v_t.estado NOT IN ('por_fazer','em_curso','rejeitada') THEN
    RAISE EXCEPTION 'Esta tarefa já está %. Um atraso regista-se antes de acabar.', replace(v_t.estado, '_', ' ');
  END IF;

  -- Na pré-visualização ainda se está a escrever: só as contas importam.
  IF NOT v_simular THEN
    IF v_motivo IS NULL OR v_motivo NOT IN ('secagem','condicoes_edificio','material_em_falta',
         'trabalho_imprevisto','acesso_cliente','meteorologia','equipa','outro') THEN
      RAISE EXCEPTION 'Escolhe o motivo do atraso.' USING ERRCODE = 'check_violation';
    END IF;
    IF v_ctx IS NULL OR length(v_ctx) < 5 THEN
      RAISE EXCEPTION 'Escreve o contexto do atraso (pelo menos 5 letras): é o que o supervisor e o cliente vão ler.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF p_minutos_extra IS NOT NULL AND p_minutos_extra <= 0 THEN
    RAISE EXCEPTION 'O tempo a mais tem de ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_minutos_extra IS NULL AND p_novo_fim IS NULL THEN
    RAISE EXCEPTION 'Diz quanto tempo a mais (horas ou dias) ou a nova data de fim.' USING ERRCODE = 'check_violation';
  END IF;

  v_fim_ant := COALESCE(v_t.fim_planeado, v_t.inicio_planeado);
  IF p_novo_fim IS NOT NULL THEN
    IF v_fim_ant IS NOT NULL AND p_novo_fim < v_fim_ant THEN
      RAISE EXCEPTION 'A nova data de fim (%) é antes do fim previsto (%). Um atraso só empurra para a frente.',
        to_char(p_novo_fim, 'DD/MM/YYYY'), to_char(v_fim_ant, 'DD/MM/YYYY') USING ERRCODE = 'check_violation';
    END IF;
    IF p_novo_fim < v_hoje THEN
      RAISE EXCEPTION 'A nova data de fim já passou.' USING ERRCODE = 'check_violation';
    END IF;
    v_novo := p_novo_fim;
  ELSE
    v_dias := ceil(p_minutos_extra::numeric / GREATEST(v_t.pessoas_previstas, 1) / GREATEST(v_t.mpd, 1))::integer;
    IF v_fim_ant IS NULL OR v_fim_ant < v_hoje THEN
      v_novo := public.ops_obra_somar_dias_uteis_org(v_t.organization_id, v_hoje, GREATEST(v_dias - 1, 0));
    ELSE
      v_novo := public.ops_obra_somar_dias_uteis_org(v_t.organization_id, v_fim_ant, v_dias);
    END IF;
  END IF;

  SELECT max(COALESCE(fim_planeado, inicio_planeado)) INTO v_obra_ant
    FROM public.ops_obra_tarefa WHERE obra_id = v_t.obra_id;

  BEGIN
    -- A tarefa: plano original (uma vez), novo fim, nova estimativa.
    UPDATE public.ops_obra_tarefa
       SET inicio_original = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                  THEN inicio_planeado ELSE inicio_original END,
           fim_original    = CASE WHEN inicio_original IS NULL AND fim_original IS NULL
                                  THEN fim_planeado ELSE fim_original END,
           fim_planeado    = v_novo,
           minutos_estimativa = CASE WHEN p_minutos_extra IS NULL THEN minutos_estimativa
                                     ELSE COALESCE(minutos_estimativa, minutos_previstos) + p_minutos_extra END,
           atualizada_em   = now()
     WHERE id = p_tarefa_id
     RETURNING minutos_estimativa INTO v_estim;

    -- As dependentes, em cadeia (sem ciclos: o trigger das dependências não deixa).
    IF COALESCE(p_empurrar, true) THEN
      v_mexidas := public.ops_obra_empurrar_dependentes_impl(p_tarefa_id, v_fim_ant);
    END IF;

    SELECT max(COALESCE(fim_planeado, inicio_planeado)) INTO v_obra_novo
      FROM public.ops_obra_tarefa WHERE obra_id = v_t.obra_id;

    IF NOT v_simular THEN
      INSERT INTO public.ops_obra_tarefa_atraso
        (organization_id, obra_id, tarefa_id, motivo, contexto, minutos_extra, novo_fim, fim_anterior, registado_por)
      VALUES
        (v_t.organization_id, v_t.obra_id, p_tarefa_id, v_motivo, v_ctx, p_minutos_extra, v_novo,
         v_t.fim_planeado, v_quem.utilizador_id)
      RETURNING id INTO v_id;

      PERFORM public.ops_obra_evento(v_t.organization_id, v_t.obra_id, 'atraso',
        v_t.nome || ': ' || v_ctx, v_quem.utilizador_id,
        jsonb_build_object('tarefa_id', p_tarefa_id, 'atraso_id', v_id, 'motivo', v_motivo,
                           'minutos_extra', p_minutos_extra, 'fim_anterior', v_t.fim_planeado,
                           'novo_fim', v_novo, 'empurradas', (SELECT count(*) FROM jsonb_object_keys(v_mexidas)),
                           'fim_obra_anterior', v_obra_ant, 'fim_obra_novo', v_obra_novo));
    END IF;

    v_res := jsonb_build_object(
      'ok', true,
      'simulado', v_simular,
      'atraso_id', v_id,
      'fim_anterior', v_t.fim_planeado,
      'novo_fim', v_novo,
      'minutos_estimativa', v_estim,
      'empurradas', COALESCE((SELECT jsonb_agg(e.value ORDER BY e.value->>'novo_inicio', e.value->>'nome')
                                FROM jsonb_each(v_mexidas) e), '[]'::jsonb),
      'fim_obra_anterior', v_obra_ant,
      'fim_obra_novo', v_obra_novo);

    IF v_simular THEN
      -- Desfaz tudo o que este bloco mudou; as contas ficam em v_res.
      RAISE EXCEPTION 'simulação' USING ERRCODE = 'OB001';
    END IF;
  EXCEPTION WHEN SQLSTATE 'OB001' THEN
    NULL;
  END;

  RETURN v_res;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_registar_atraso(p_tarefa_id uuid, p_motivo text, p_contexto text, p_minutos_extra integer, p_novo_fim date, p_empurrar boolean, p_simular boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_registar_atraso(p_tarefa_id uuid, p_motivo text, p_contexto text, p_minutos_extra integer, p_novo_fim date, p_empurrar boolean, p_simular boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_registar_atraso(p_tarefa_id uuid, p_motivo text, p_contexto text, p_minutos_extra integer, p_novo_fim date, p_empurrar boolean, p_simular boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_registar_foto(p_tarefa_id uuid, p_caminho text, p_nome text, p_mime text DEFAULT NULL::text, p_tamanho integer DEFAULT NULL::integer, p_legenda text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t       record;
  v_user    uuid;
  v_funcao  text;
  v_prefixo text;
  v_id      uuid;
BEGIN
  SELECT t.id, t.obra_id, t.estado, o.organization_id, o.estado AS obra_estado, o.supervisor_id
    INTO v_t
    FROM public.ops_obra_tarefa t
    JOIN public.ops_obra o ON o.id = t.obra_id
   WHERE t.id = p_tarefa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tarefa não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT q.utilizador_id, q.funcao INTO v_user, v_funcao
    FROM public.ops_quem_sou(v_t.organization_id) q;

  IF NOT (
    public.ops_pode(v_t.organization_id, 'operations.orders.execute')
    OR public.ops_pode(v_t.organization_id, 'operations.orders.edit')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para tirar fotos.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT (
    v_funcao IN ('admin','gestor')
    OR v_t.supervisor_id = v_user
    OR EXISTS (SELECT 1 FROM public.ops_obra_tarefa_pessoa tp
                WHERE tp.tarefa_id = p_tarefa_id AND tp.utilizador_id = v_user)
  ) THEN
    RAISE EXCEPTION 'Só quem está na tarefa lhe junta fotos.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_t.estado = 'validada' THEN
    RAISE EXCEPTION 'A tarefa já está validada — não se juntam fotos.';
  END IF;
  IF v_t.obra_estado IN ('concluida','cancelada') THEN
    RAISE EXCEPTION 'A obra está % — não se juntam fotos.', replace(v_t.obra_estado, 'concluida', 'concluída');
  END IF;

  v_prefixo := v_t.organization_id::text || '/' || v_t.obra_id::text || '/' || v_t.id::text || '/';
  IF p_caminho IS NULL OR left(p_caminho, length(v_prefixo)) <> v_prefixo
     OR position('..' IN p_caminho) > 0 THEN
    RAISE EXCEPTION 'O caminho do ficheiro não pertence a esta tarefa.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO public.ops_obra_tarefa_foto
    (organization_id, obra_id, tarefa_id, caminho, nome, mime, tamanho, legenda, carregado_por)
  VALUES
    (v_t.organization_id, v_t.obra_id, v_t.id, p_caminho,
     COALESCE(nullif(btrim(p_nome), ''), 'foto'),
     p_mime, p_tamanho, nullif(btrim(coalesce(p_legenda, '')), ''), v_user)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'caminho', p_caminho);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_registar_foto(p_tarefa_id uuid, p_caminho text, p_nome text, p_mime text, p_tamanho integer, p_legenda text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_registar_foto(p_tarefa_id uuid, p_caminho text, p_nome text, p_mime text, p_tamanho integer, p_legenda text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_registar_foto(p_tarefa_id uuid, p_caminho text, p_nome text, p_mime text, p_tamanho integer, p_legenda text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_remover_foto(p_foto_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_f      record;
  v_user   uuid;
  v_funcao text;
BEGIN
  SELECT f.*, t.estado AS tarefa_estado
    INTO v_f
    FROM public.ops_obra_tarefa_foto f
    JOIN public.ops_obra_tarefa t ON t.id = f.tarefa_id
   WHERE f.id = p_foto_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Foto não encontrada.' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT q.utilizador_id, q.funcao INTO v_user, v_funcao
    FROM public.ops_quem_sou(v_f.organization_id) q;

  IF v_funcao NOT IN ('admin','gestor') THEN
    IF v_f.carregado_por IS DISTINCT FROM v_user THEN
      RAISE EXCEPTION 'Só quem tirou a foto a apaga.' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_f.tarefa_estado = 'validada' THEN
      RAISE EXCEPTION 'A tarefa já está validada — a foto fica.';
    END IF;
  END IF;

  DELETE FROM public.ops_obra_tarefa_foto WHERE id = p_foto_id;
  RETURN jsonb_build_object('ok', true, 'caminho', v_f.caminho);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_remover_foto(p_foto_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_remover_foto(p_foto_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_remover_foto(p_foto_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_semear_tempos_padrao(p_org uuid, p_substituir boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.ops_obra_pode_gerir_modelos(p_org) THEN
    RAISE EXCEPTION 'Sem permissão para gerir modelos nesta organização.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN public.ops_obra_semear_tempos_padrao_impl(p_org, public.current_business_user_id(), COALESCE(p_substituir, false));
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_semear_tempos_padrao(p_org uuid, p_substituir boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_semear_tempos_padrao(p_org uuid, p_substituir boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_semear_tempos_padrao(p_org uuid, p_substituir boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_sincronizar_avisos(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.ops_quem_sou(p_org);
  IF NOT public.ops_pode(p_org, 'operations.orders.view') THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  RETURN public.ops_obra_sincronizar_avisos(p_org, NULL) || jsonb_build_object('ok', true);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_sincronizar_avisos(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_sincronizar_avisos(p_org uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_sincronizar_avisos(p_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obra_stock(p_org uuid, p_produto_ids uuid[] DEFAULT NULL::uuid[], p_pesquisa text DEFAULT NULL::text, p_limite integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quem  record;
  v_ids   uuid[];
  v_inv   boolean;
  v_res   boolean;
  v_txt   text := nullif(btrim(COALESCE(p_pesquisa, '')), '');
  v_out   jsonb;
BEGIN
  SELECT q.utilizador_id, q.funcao INTO v_quem FROM public.ops_quem_sou(p_org) q;
  IF v_quem.funcao IS DISTINCT FROM 'admin' AND v_quem.funcao IS DISTINCT FROM 'gestor' THEN
    RAISE EXCEPTION 'Só quem planeia vê o stock para a obra.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (public.ops_pode(p_org, 'operations.orders.edit') OR public.ops_pode(p_org, 'operations.orders.create')) THEN
    RAISE EXCEPTION 'Sem permissão (operations.orders.edit) nesta organização.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF to_regclass('public.products') IS NULL THEN
    RETURN jsonb_build_object('com_inventario', false, 'produtos', '[]'::jsonb);
  END IF;
  IF COALESCE(array_length(p_produto_ids, 1), 0) > 500 THEN
    RAISE EXCEPTION 'Demasiados produtos de uma vez.';
  END IF;

  -- Que produtos (desta organização, ou das fichas/orçamentos dela).
  IF v_txt IS NOT NULL THEN
    EXECUTE $q$
      SELECT COALESCE(array_agg(p.id), '{}') FROM (
        SELECT p.id FROM public.products p
         WHERE (to_jsonb(p)->>'organization_id') = $1::text
           AND COALESCE((to_jsonb(p)->>'is_deleted')::boolean, false) = false
           AND (to_jsonb(p)->>'deleted_at') IS NULL
           AND (p.name ILIKE '%' || $2 || '%' OR COALESCE(to_jsonb(p)->>'sku', '') ILIKE '%' || $2 || '%')
         ORDER BY (lower(p.name) LIKE lower($2) || '%') DESC, p.name
         LIMIT $3) p
    $q$ INTO v_ids USING p_org, v_txt, LEAST(GREATEST(COALESCE(p_limite, 30), 1), 100);
  ELSE
    EXECUTE format($q$
      SELECT COALESCE(array_agg(p.id), '{}') FROM public.products p
       WHERE p.id = ANY ($2)
         AND ((to_jsonb(p)->>'organization_id') = $1::text
              %s
              OR EXISTS (SELECT 1 FROM public.quote_lines l JOIN public.quotes q ON q.id = l.quote_id
                          WHERE q.organization_id = $1 AND (to_jsonb(l)->>'product_id') = p.id::text))
    $q$,
      CASE WHEN to_regclass('public.service_materials') IS NOT NULL THEN
        'OR EXISTS (SELECT 1 FROM public.service_materials sm
                     WHERE sm.product_id = p.id AND sm.deleted_at IS NULL
                       AND ((to_jsonb(sm)->>''organization_id'') = $1::text
                            OR public.ops_obra_servico_da_org($1, sm.service_id)))'
      ELSE '' END)
    INTO v_ids USING p_org, COALESCE(p_produto_ids, '{}'::uuid[]);
  END IF;

  v_inv := to_regclass('public.stocks') IS NOT NULL AND to_regclass('public.warehouses') IS NOT NULL;
  v_res := to_regprocedure('public.fn_client_order_line_reservations(uuid,uuid[])') IS NOT NULL;

  EXECUTE format($q$
    WITH st AS (
      %2$s
    ), rs AS (
      %3$s
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'produto_id', p.id,
             'nome', p.name,
             'sku', to_jsonb(p)->>'sku',
             'unidade', %1$s,
             'gere_stock', (to_jsonb(p)->>'manages_stock')::boolean,
             'stock', st.qtd,
             'reservado', COALESCE(rs.qtd, 0),
             'disponivel', CASE WHEN $3 THEN COALESCE(st.qtd, 0) - COALESCE(rs.qtd, 0) END)
             ORDER BY (COALESCE(st.qtd, 0) - COALESCE(rs.qtd, 0)) > 0 DESC, p.name), '[]'::jsonb)
      FROM public.products p
      LEFT JOIN st ON st.product_id = p.id
      LEFT JOIN rs ON rs.product_id = p.id
     WHERE p.id = ANY ($2)
  $q$,
    CASE WHEN to_regclass('public.uom') IS NOT NULL
         THEN '(SELECT u.code FROM public.uom u WHERE u.id::text = to_jsonb(p)->>''uom_id'')'
         ELSE 'NULL::text' END,
    CASE WHEN v_inv THEN
      'SELECT s.product_id, sum(s.quantity)::numeric AS qtd
         FROM public.stocks s JOIN public.warehouses w ON w.id = s.warehouse_id
        WHERE s.organization_id = $1 AND s.product_id = ANY ($2)
          AND (to_jsonb(s)->>''deleted_at'') IS NULL
          AND COALESCE((to_jsonb(w)->>''is_active'')::boolean, true)
          AND (to_jsonb(w)->>''deleted_at'') IS NULL
        GROUP BY s.product_id'
    ELSE 'SELECT NULL::uuid AS product_id, NULL::numeric AS qtd WHERE false' END,
    CASE WHEN v_res THEN
      'SELECT r.product_id, sum(COALESCE(r.qty_reserved, 0))::numeric AS qtd
         FROM public.fn_client_order_line_reservations($1, $2) r
        WHERE r.product_id IS NOT NULL GROUP BY r.product_id'
    ELSE 'SELECT NULL::uuid AS product_id, NULL::numeric AS qtd WHERE false' END)
  INTO v_out USING p_org, v_ids, v_inv;

  RETURN jsonb_build_object('com_inventario', v_inv, 'com_reservas', v_res, 'produtos', v_out);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obra_stock(p_org uuid, p_produto_ids uuid[], p_pesquisa text, p_limite integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_stock(p_org uuid, p_produto_ids uuid[], p_pesquisa text, p_limite integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obra_stock(p_org uuid, p_produto_ids uuid[], p_pesquisa text, p_limite integer) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obras_alertas_tempo(p_org uuid)
 RETURNS TABLE(tarefa_id uuid, obra_id uuid, obra_codigo text, nome text, estado text, minutos_previstos integer, minutos_reais numeric, a_correr integer, nivel text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  WITH vis AS (SELECT public.ops_obras_visiveis(p_org) AS id),
  t AS (
    SELECT t.id, t.obra_id, o.codigo, t.nome, t.estado, t.minutos_previstos,
           COALESCE(r.minutos, 0)::numeric(12,1) AS minutos_reais,
           COALESCE(r.a_correr, 0)::integer AS a_correr
      FROM public.ops_obra_tarefa t
      JOIN public.ops_obra_fase f ON f.id = t.fase_id
      JOIN public.ops_obra o ON o.id = t.obra_id
      LEFT JOIN LATERAL (
        SELECT round(sum(EXTRACT(EPOCH FROM (COALESCE(x.fim, now()) - x.inicio))) / 60.0, 1) AS minutos,
               count(*) FILTER (WHERE x.fim IS NULL) AS a_correr
          FROM public.ops_obra_registo x WHERE x.tarefa_id = t.id
      ) r ON true
     WHERE t.obra_id IN (SELECT vis.id FROM vis)
       AND t.estado IN ('por_fazer','em_curso','rejeitada')
  )
  SELECT t.id, t.obra_id, t.codigo, t.nome, t.estado, t.minutos_previstos, t.minutos_reais, t.a_correr,
         CASE WHEN t.minutos_reais > t.minutos_previstos THEN 'excedido' ELSE 'aviso' END
    FROM t
   WHERE t.minutos_reais >= 0.8 * t.minutos_previstos
   LIMIT 200;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obras_alertas_tempo(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obras_alertas_tempo(p_org uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obras_alertas_tempo(p_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_obras_lista(p_org uuid)
 RETURNS TABLE(id uuid, organization_id uuid, codigo text, titulo text, estado text, cliente_id uuid, orcamento_id uuid, contrato_id uuid, modelo_id uuid, morada text, data_inicio_prevista date, gestor_id uuid, supervisor_id uuid, tolerancia_percent integer, criada_em timestamp with time zone, n_tarefas integer, n_feitas integer, n_validadas integer, n_por_validar integer, minutos_previstos integer, minutos_reais numeric, inicio_planeado date, fim_planeado date, n_extras integer, fim_original date, n_alertas integer, cliente_nome text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  WITH vis AS (SELECT public.ops_obras_visiveis(p_org) AS id),
  reg AS (
    SELECT x.tarefa_id,
           round(sum(EXTRACT(EPOCH FROM (COALESCE(x.fim, now()) - x.inicio))) / 60.0, 1) AS minutos
      FROM public.ops_obra_registo x
     WHERE x.obra_id IN (SELECT vis.id FROM vis)
     GROUP BY x.tarefa_id
  ),
  tar AS (
    SELECT t.obra_id,
           count(*) AS n_tarefas,
           max(COALESCE(t.fim_original, t.fim_planeado)) AS fim_original,
           count(*) FILTER (WHERE t.estado IN ('feita','validada')) AS n_feitas,
           count(*) FILTER (WHERE t.estado = 'validada') AS n_validadas,
           count(*) FILTER (WHERE t.estado = 'feita') AS n_por_validar,
           sum(t.minutos_previstos) AS minutos_previstos,
           sum(COALESCE(reg.minutos, 0)) AS minutos_reais,
           min(t.inicio_planeado) AS inicio_planeado,
           max(t.fim_planeado) AS fim_planeado
      FROM public.ops_obra_tarefa t
      JOIN public.ops_obra_fase f ON f.id = t.fase_id
      LEFT JOIN reg ON reg.tarefa_id = t.id
     WHERE t.obra_id IN (SELECT vis.id FROM vis)
     GROUP BY t.obra_id
  ),
  ext AS (
    SELECT e.obra_id, count(*) AS n
      FROM public.ops_obra_extra e
     WHERE e.obra_id IN (SELECT vis.id FROM vis) AND e.estado IN ('registado','aprovado')
     GROUP BY e.obra_id
  ),
  al AS (
    SELECT a.obra_id, count(*) AS n
      FROM public.ops_obra_alertas_lista(p_org, NULL) a
     GROUP BY a.obra_id
  )
  SELECT o.id, o.organization_id, o.codigo, o.titulo, o.estado, o.cliente_id,
         o.orcamento_id, o.contrato_id, o.modelo_id, o.morada,
         o.data_inicio_prevista, o.gestor_id, o.supervisor_id, o.tolerancia_percent,
         o.criada_em,
         COALESCE(tar.n_tarefas, 0)::integer, COALESCE(tar.n_feitas, 0)::integer,
         COALESCE(tar.n_validadas, 0)::integer, COALESCE(tar.n_por_validar, 0)::integer,
         COALESCE(tar.minutos_previstos, 0)::integer, COALESCE(tar.minutos_reais, 0)::numeric(12,1),
         tar.inicio_planeado, tar.fim_planeado,
         COALESCE(ext.n, 0)::integer, tar.fim_original, COALESCE(al.n, 0)::integer,
         c.nome
    FROM public.ops_obra o
    JOIN vis ON vis.id = o.id
    LEFT JOIN tar ON tar.obra_id = o.id
    LEFT JOIN ext ON ext.obra_id = o.id
    LEFT JOIN al  ON al.obra_id = o.id
    LEFT JOIN public.ops_v_cliente c ON c.id = o.cliente_id
   ORDER BY o.criada_em DESC
   LIMIT 200;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_obras_lista(p_org uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obras_lista(p_org uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_obras_lista(p_org uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_pessoas_livres(p_org uuid, p_inicio date, p_fim date DEFAULT NULL::date, p_excluir_tarefa uuid DEFAULT NULL::uuid)
 RETURNS TABLE(utilizador_id uuid, nome text, funcao text, skills uuid[], zona text, minutos_ocupados integer, dias_cheios integer, ordens integer, livre boolean, motivo text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_quem record;
BEGIN
  SELECT q.utilizador_id, q.funcao INTO v_quem FROM public.ops_quem_sou(p_org) q;
  IF v_quem.funcao IS DISTINCT FROM 'admin' AND v_quem.funcao IS DISTINCT FROM 'gestor' THEN
    RAISE EXCEPTION 'Só quem planeia vê a agenda da equipa.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (public.ops_pode(p_org, 'operations.orders.edit') OR public.ops_pode(p_org, 'operations.orders.create')) THEN
    RAISE EXCEPTION 'Sem permissão (operations.orders.edit) nesta organização.' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_inicio IS NULL THEN
    RAISE EXCEPTION 'Indica a data de início.';
  END IF;
  IF p_fim IS NOT NULL AND p_fim < p_inicio THEN
    RAISE EXCEPTION 'O fim não pode ser antes do início.';
  END IF;
  IF COALESCE(p_fim, p_inicio) - p_inicio > 366 THEN
    RAISE EXCEPTION 'No máximo um ano de cada vez.';
  END IF;
  IF p_excluir_tarefa IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.ops_obra_tarefa WHERE id = p_excluir_tarefa AND organization_id = p_org) THEN
    RAISE EXCEPTION 'Tarefa não encontrada nesta organização.' USING ERRCODE = 'no_data_found';
  END IF;

  RETURN QUERY
    SELECT * FROM public.ops_obra_pessoas_livres_impl(p_org, p_inicio, COALESCE(p_fim, p_inicio), p_excluir_tarefa);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_pessoas_livres(p_org uuid, p_inicio date, p_fim date, p_excluir_tarefa uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_pessoas_livres(p_org uuid, p_inicio date, p_fim date, p_excluir_tarefa uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_pessoas_livres(p_org uuid, p_inicio date, p_fim date, p_excluir_tarefa uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_stock_disponivel(p_org uuid, p_produtos uuid[])
 RETURNS TABLE(produto_id uuid, nome text, sku text, unidade text, gere_stock boolean, fisico numeric, reservado numeric, a_chegar numeric, disponivel numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.ops_stock_verificar(p_org);
  IF cardinality(p_produtos) > 500 THEN
    RAISE EXCEPTION 'Demasiados produtos de uma vez (máximo 500).' USING ERRCODE = 'check_violation';
  END IF;
  RETURN QUERY SELECT c.* FROM public.ops_stock_calcular(p_org, p_produtos) c ORDER BY c.nome;
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_stock_disponivel(p_org uuid, p_produtos uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_disponivel(p_org uuid, p_produtos uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_disponivel(p_org uuid, p_produtos uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_stock_pesquisar(p_org uuid, p_texto text, p_limite integer DEFAULT 20)
 RETURNS TABLE(produto_id uuid, nome text, sku text, unidade text, gere_stock boolean, fisico numeric, reservado numeric, a_chegar numeric, disponivel numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_texto  text := btrim(COALESCE(p_texto, ''));
  v_limite int  := LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
  v_padrao text;
  v_barras text := '';
  v_ids    uuid[];
BEGIN
  PERFORM public.ops_stock_verificar(p_org);
  IF NOT public.ops_stock_ha_inventario() THEN
    RETURN;
  END IF;

  -- %, _ e \ escritos pela pessoa são texto, não padrões.
  v_padrao := '%' || replace(replace(replace(v_texto, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  IF public.ops_stock_tem('products', ARRAY['barcode']) THEN
    v_barras := ' OR p.barcode = $2';
  END IF;

  EXECUTE format($q$
    SELECT COALESCE(array_agg(x.id ORDER BY x.ordem, x.nome), '{}')
      FROM (
        SELECT p.id, p.name AS nome,
               CASE WHEN $2 <> '' AND (lower(p.sku) = lower($2)%1$s) THEN 0 ELSE 1 END AS ordem
          FROM public.products p
         WHERE p.deleted_at IS NULL
           AND %2$s
           AND ($2 = '' OR p.name ILIKE $3 OR p.sku ILIKE $3%1$s)
         ORDER BY ordem, p.name
         LIMIT $4
      ) x
  $q$, v_barras, public.ops_stock_filtro_org())
  INTO v_ids
  USING p_org, v_texto, v_padrao, v_limite;

  RETURN QUERY
  SELECT c.* FROM public.ops_stock_calcular(p_org, v_ids) c
   ORDER BY array_position(v_ids, c.produto_id);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_stock_pesquisar(p_org uuid, p_texto text, p_limite integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_pesquisar(p_org uuid, p_texto text, p_limite integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_pesquisar(p_org uuid, p_texto text, p_limite integer) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_ops_stock_sugerir(p_org uuid, p_servico_id uuid, p_quantidade numeric)
 RETURNS TABLE(produto_id uuid, nome text, sku text, unidade text, quantidade numeric, gere_stock boolean, fisico numeric, reservado numeric, a_chegar numeric, disponivel numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_qt     numeric := COALESCE(p_quantidade, 1);
  v_regra  text := 'NULL::numeric';
  v_ordem  text := '0';
  v_fator  text := '1';
  v_join   text := '';
  v_ids    uuid[];
  v_qts    numeric[];
BEGIN
  PERFORM public.ops_stock_verificar(p_org);
  IF v_qt < 0 THEN
    RAISE EXCEPTION 'A quantidade do serviço não pode ser negativa.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_servico_id IS NULL
     OR NOT public.ops_stock_ha_inventario()
     OR NOT public.ops_stock_tem('service_materials',
              ARRAY['service_id','product_id','quantity','organization_id','deleted_at']) THEN
    RETURN;
  END IF;

  IF public.ops_stock_tem('service_materials', ARRAY['reference_area_m2','reference_quantity']) THEN
    v_regra := 'CASE WHEN sm.reference_area_m2 > 0 AND sm.reference_quantity IS NOT NULL
                     THEN ceil(sm.reference_quantity / sm.reference_area_m2 * $3) END';
  END IF;
  IF public.ops_stock_tem('service_materials', ARRAY['sort_order']) THEN
    v_ordem := 'COALESCE(sm.sort_order, 0)';
  END IF;
  IF public.ops_stock_tem('service_materials', ARRAY['uom_id'])
     AND public.ops_stock_tem('products', ARRAY['uom_id'])
     AND public.ops_stock_tem('uom', ARRAY['id','base_uom_id','conversion_factor']) THEN
    v_join  := 'LEFT JOIN public.products p ON p.id = sm.product_id
                LEFT JOIN public.uom mu ON mu.id = sm.uom_id';
    v_fator := 'CASE WHEN sm.uom_id IS NULL OR sm.uom_id = p.uom_id THEN 1
                     WHEN mu.base_uom_id = p.uom_id AND mu.conversion_factor >= 1 THEN mu.conversion_factor
                     ELSE 1 END';
  END IF;

  EXECUTE format($q$
    SELECT COALESCE(array_agg(x.product_id ORDER BY x.ordem), '{}'),
           COALESCE(array_agg(x.q          ORDER BY x.ordem), '{}')
      FROM (
        SELECT sm.product_id,
               MIN(%1$s) AS ordem,
               round(SUM(COALESCE(%2$s, COALESCE(sm.quantity, 0) * $3) * %3$s), 3) AS q
          FROM public.service_materials sm
          %4$s
         WHERE sm.service_id = $2
           AND sm.organization_id = $1
           AND sm.deleted_at IS NULL
           AND sm.product_id IS NOT NULL
         GROUP BY sm.product_id
      ) x
  $q$, v_ordem, v_regra, v_fator, v_join)
  INTO v_ids, v_qts
  USING p_org, p_servico_id, v_qt;

  RETURN QUERY
  SELECT c.produto_id, c.nome, c.sku, c.unidade,
         v_qts[array_position(v_ids, c.produto_id)],
         c.gere_stock, c.fisico, c.reservado, c.a_chegar, c.disponivel
    FROM public.ops_stock_calcular(p_org, v_ids) c
   ORDER BY array_position(v_ids, c.produto_id);
END
$function$;
REVOKE ALL ON FUNCTION public.rpc_ops_stock_sugerir(p_org uuid, p_servico_id uuid, p_quantidade numeric) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_sugerir(p_org uuid, p_servico_id uuid, p_quantidade numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_ops_stock_sugerir(p_org uuid, p_servico_id uuid, p_quantidade numeric) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_po_accept_promised_date(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid := public.current_business_user_id();
  v_po     public.purchase_orders := public.fn_po_crm_load(p_po_id, 'purchase_orders.edit', true);
  v_pub    public.supplier_po_publications;
  v_old    date := v_po.expected_delivery;
  v_bypass text := current_setting('app.audit_bypass', true);
BEGIN
  SELECT * INTO v_pub FROM public.supplier_po_publications
  WHERE purchase_order_id = v_po.id AND status <> 'withdrawn'
  FOR UPDATE;
  IF v_pub.purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'Esta encomenda não está no portal do fornecedor' USING ERRCODE = 'no_data_found', HINT = 'not_published';
  END IF;
  IF v_pub.status <> 'confirmed' OR v_pub.promised_date IS NULL THEN
    RAISE EXCEPTION 'O fornecedor ainda não indicou uma data de entrega' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  IF v_old IS NOT DISTINCT FROM v_pub.promised_date THEN
    IF v_pub.promised_date_accepted_at IS NULL THEN
      UPDATE public.supplier_po_publications
         SET promised_date_accepted_at = now(), promised_date_accepted_by = v_actor
       WHERE purchase_order_id = v_po.id;
    END IF;
    RETURN jsonb_build_object('purchase_order_id', v_po.id, 'expected_delivery', v_old, 'already_accepted', true);
  END IF;

  PERFORM set_config('app.audit_bypass', 'on', true);
  UPDATE public.purchase_orders SET expected_delivery = v_pub.promised_date, updated_at = now()
  WHERE id = v_po.id
  RETURNING * INTO v_po;
  UPDATE public.supplier_po_publications
     SET promised_date_accepted_at = now(), promised_date_accepted_by = v_actor
   WHERE purchase_order_id = v_po.id;
  PERFORM public.fn_manual_audit_log('purchase_orders', v_po.id, v_po.organization_id, 'UPDATE',
    jsonb_build_object('expected_delivery', jsonb_build_object('old', v_old, 'new', v_po.expected_delivery),
                       'source', 'supplier_promised_date'), 'web_app');
  PERFORM set_config('app.audit_bypass', COALESCE(v_bypass, ''), true);

  RETURN jsonb_build_object('purchase_order_id', v_po.id, 'expected_delivery', v_po.expected_delivery, 'already_accepted', false);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_po_accept_promised_date(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_po_accept_promised_date(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_po_accept_promised_date(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_po_send_to_supplier(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor    uuid := public.current_business_user_id();
  v_po       public.purchase_orders := public.fn_po_crm_load(p_po_id, 'purchase_orders.approve', true);
  v_old      text := v_po.status;
  v_link     public.supplier_account_links;
  v_pub      public.supplier_po_publications;
  v_prev     public.supplier_po_publications;
  v_changed  boolean := false;
  v_already  boolean := false;
  v_emails   integer := 0;
  v_warning  text;
  v_bypass   text := current_setting('app.audit_bypass', true);
  v_diff     jsonb := '{}'::jsonb;
BEGIN
  IF v_po.status NOT IN ('pending', 'ordered') THEN
    RAISE EXCEPTION 'Só se pode encomendar uma encomenda pendente (estado atual: %)', v_po.status
      USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF v_po.supplier_id IS NULL THEN
    RAISE EXCEPTION 'Escolha o fornecedor antes de encomendar' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.purchase_order_items WHERE purchase_order_id = v_po.id) THEN
    RAISE EXCEPTION 'A encomenda não tem linhas' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  PERFORM set_config('app.audit_bypass', 'on', true);

  IF v_po.status = 'pending' THEN
    UPDATE public.purchase_orders SET status = 'ordered', updated_at = now()
    WHERE id = v_po.id
    RETURNING * INTO v_po;
    v_changed := true;
    v_diff := v_diff || jsonb_build_object('status', jsonb_build_object('old', v_old, 'new', 'ordered'));
  END IF;

  SELECT * INTO v_prev FROM public.supplier_po_publications WHERE purchase_order_id = v_po.id FOR UPDATE;

  IF v_prev.purchase_order_id IS NOT NULL AND v_prev.status <> 'withdrawn' THEN
    v_already := true;
    v_pub := v_prev;
  ELSE
    SELECT l.* INTO v_link
    FROM public.supplier_account_links l
    JOIN public.supplier_accounts a ON a.id = l.supplier_account_id
    WHERE l.supplier_id = v_po.supplier_id
      AND l.organization_id = v_po.organization_id
      AND l.status = 'active'
      AND a.status = 'active'
    LIMIT 1;

    IF v_link.id IS NOT NULL THEN
      IF v_prev.purchase_order_id IS NULL THEN
        INSERT INTO public.supplier_po_publications
          (purchase_order_id, organization_id, link_id, revision, status, sent_at, sent_by)
        VALUES (v_po.id, v_po.organization_id, v_link.id, 1, 'sent', now(), v_actor)
        RETURNING * INTO v_pub;
      ELSE
        UPDATE public.supplier_po_publications
           SET link_id = v_link.id,
               organization_id = v_po.organization_id,
               revision = revision + 1,
               status = 'sent',
               sent_at = now(), sent_by = v_actor,
               viewed_at = NULL, viewed_by = NULL,
               confirmed_at = NULL, confirmed_by = NULL,
               promised_date = NULL, supplier_comment = NULL,
               promised_date_accepted_at = NULL, promised_date_accepted_by = NULL,
               withdrawn_at = NULL, withdrawn_by = NULL, withdraw_reason = NULL
         WHERE purchase_order_id = v_po.id
        RETURNING * INTO v_pub;
      END IF;

      v_diff := v_diff || jsonb_build_object('supplier_publication', jsonb_build_object(
        'old', CASE WHEN v_prev.purchase_order_id IS NULL THEN NULL
                    ELSE jsonb_build_object('status', v_prev.status, 'revision', v_prev.revision) END,
        'new', jsonb_build_object('status', v_pub.status, 'revision', v_pub.revision, 'link_id', v_pub.link_id)));

      v_emails := public.fn_sp_po_queue_email(v_po, v_pub);
      IF v_emails = 0 THEN
        v_warning := 'no_portal_users';
      ELSIF NOT EXISTS (SELECT 1 FROM public.organization_smtp_settings
                        WHERE organization_id = v_po.organization_id AND is_active)
            AND NOT EXISTS (SELECT 1 FROM public.user_smtp_settings
                            WHERE user_id IN (auth.uid(), v_actor) AND is_active) THEN
        v_warning := 'no_smtp';
      END IF;
    END IF;
  END IF;

  IF v_diff <> '{}'::jsonb THEN
    PERFORM public.fn_manual_audit_log('purchase_orders', v_po.id, v_po.organization_id, 'UPDATE', v_diff, 'web_app');
  END IF;
  PERFORM set_config('app.audit_bypass', COALESCE(v_bypass, ''), true);

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'order_status', v_po.status,
    'status_changed', v_changed,
    'published', v_pub.purchase_order_id IS NOT NULL,
    'already_published', v_already,
    'revision', v_pub.revision,
    'emails_queued', v_emails,
    'warning', v_warning
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_po_send_to_supplier(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_po_send_to_supplier(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_po_send_to_supplier(p_po_id uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_po_send_to_supplier(p_po_id uuid) IS 'Portal do fornecedor F3.2: "Encomendar" (purchase_orders.approve). pending→ordered; com ligação ativa ao portal publica (revision+1 após retirada) e põe na fila scheduled_emails um email por utilizador do portal com acesso a esta empresa.';

CREATE OR REPLACE FUNCTION public.rpc_po_supplier_status(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_po       public.purchase_orders := public.fn_po_crm_load(p_po_id, 'purchase_orders.view', false);
  v_link     public.supplier_account_links;
  v_pub      public.supplier_po_publications;
  v_users    integer := 0;
  v_rcv      boolean;
  v_active   boolean;
  v_approve  boolean := public.has_anew_permission(v_uid, 'purchase_orders.approve');
  v_edit     boolean := public.has_anew_permission(v_uid, 'purchase_orders.edit');
  v_emails   jsonb;
BEGIN
  SELECT l.* INTO v_link
  FROM public.supplier_account_links l
  JOIN public.supplier_accounts a ON a.id = l.supplier_account_id
  WHERE l.supplier_id = v_po.supplier_id AND l.organization_id = v_po.organization_id
    AND l.status = 'active' AND a.status = 'active'
  LIMIT 1;
  IF v_link.id IS NOT NULL THEN
    SELECT count(*) INTO v_users
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_portal_users u ON u.id = x.portal_user_id
    WHERE x.link_id = v_link.id AND x.revoked_at IS NULL AND u.status = 'active';
  END IF;

  SELECT * INTO v_pub FROM public.supplier_po_publications WHERE purchase_order_id = v_po.id;
  v_active := v_pub.purchase_order_id IS NOT NULL AND v_pub.status <> 'withdrawn';
  v_rcv := EXISTS (SELECT 1 FROM public.purchase_order_items WHERE purchase_order_id = v_po.id AND received_quantity > 0);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'to_email', e.to_email, 'status', e.status, 'scheduled_for', e.scheduled_for,
           'sent_at', e.sent_at, 'error_message', e.error_message) ORDER BY e.created_at DESC), '[]'::jsonb)
  INTO v_emails
  FROM (
    SELECT * FROM public.scheduled_emails
    WHERE entity_type = 'purchase_orders' AND entity_id = v_po.id
      AND organization_id = v_po.organization_id
    ORDER BY created_at DESC
    LIMIT 10
  ) e;

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'order_status', v_po.status,
    'supplier_id', v_po.supplier_id,
    'expected_delivery', v_po.expected_delivery,
    'portal', jsonb_build_object('linked', v_link.id IS NOT NULL, 'link_id', v_link.id, 'active_users', v_users),
    'publication', CASE WHEN v_pub.purchase_order_id IS NULL THEN NULL ELSE jsonb_build_object(
        'status', v_pub.status,
        'revision', v_pub.revision,
        'sent_at', v_pub.sent_at,
        'sent_by', jsonb_build_object('id', v_pub.sent_by, 'name', (SELECT name FROM public.anew_users WHERE id = v_pub.sent_by)),
        'viewed_at', v_pub.viewed_at,
        'confirmed_at', v_pub.confirmed_at,
        'confirmed_by_name', (SELECT COALESCE(name, email) FROM public.supplier_portal_users WHERE id = v_pub.confirmed_by),
        'promised_date', v_pub.promised_date,
        'supplier_comment', v_pub.supplier_comment,
        'promised_date_accepted_at', v_pub.promised_date_accepted_at,
        'promised_date_accepted_by_name', (SELECT name FROM public.anew_users WHERE id = v_pub.promised_date_accepted_by),
        'withdrawn_at', v_pub.withdrawn_at,
        'withdrawn_by_name', (SELECT name FROM public.anew_users WHERE id = v_pub.withdrawn_by),
        'withdraw_reason', v_pub.withdraw_reason) END,
    'emails', v_emails,
    'can_send', v_approve AND v_po.supplier_id IS NOT NULL
                AND (v_po.status = 'pending' OR (v_po.status = 'ordered' AND NOT v_active AND v_link.id IS NOT NULL)),
    'can_withdraw', v_approve AND v_active AND v_pub.status <> 'confirmed' AND NOT v_rcv,
    'can_accept_date', v_edit AND v_active AND v_pub.status = 'confirmed' AND v_pub.promised_date IS NOT NULL
                       AND v_pub.promised_date IS DISTINCT FROM v_po.expected_delivery,
    'can_edit_lines', NOT v_active AND NOT v_rcv
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_po_supplier_status(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_po_supplier_status(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_po_supplier_status(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_po_withdraw_from_supplier(p_po_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid := public.current_business_user_id();
  v_po     public.purchase_orders := public.fn_po_crm_load(p_po_id, 'purchase_orders.approve', true);
  v_pub    public.supplier_po_publications;
  v_reason text := NULLIF(btrim(regexp_replace(COALESCE(p_reason, ''), '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]', '', 'g')), '');
  v_old    text := v_po.status;
  v_bypass text := current_setting('app.audit_bypass', true);
  v_diff   jsonb;
  v_prev_status text;
BEGIN
  IF v_reason IS NOT NULL AND char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'Motivo demasiado longo (máx. 500 caracteres)' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  SELECT * INTO v_pub FROM public.supplier_po_publications
  WHERE purchase_order_id = v_po.id AND status <> 'withdrawn'
  FOR UPDATE;
  IF v_pub.purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'Esta encomenda não está no portal do fornecedor' USING ERRCODE = 'no_data_found', HINT = 'not_published';
  END IF;
  IF v_pub.status = 'confirmed' THEN
    RAISE EXCEPTION 'O fornecedor já confirmou esta encomenda: já não pode ser retirada do portal'
      USING ERRCODE = 'check_violation', HINT = 'already_confirmed';
  END IF;
  IF EXISTS (SELECT 1 FROM public.purchase_order_items WHERE purchase_order_id = v_po.id AND received_quantity > 0) THEN
    RAISE EXCEPTION 'Esta encomenda já tem receções: já não pode ser retirada do portal'
      USING ERRCODE = 'check_violation', HINT = 'has_receipts';
  END IF;

  v_prev_status := v_pub.status;
  PERFORM set_config('app.audit_bypass', 'on', true);

  UPDATE public.supplier_po_publications
     SET status = 'withdrawn', withdrawn_at = now(), withdrawn_by = v_actor, withdraw_reason = v_reason
   WHERE purchase_order_id = v_po.id
  RETURNING * INTO v_pub;

  IF v_po.status = 'ordered' THEN
    UPDATE public.purchase_orders SET status = 'pending', updated_at = now()
    WHERE id = v_po.id
    RETURNING * INTO v_po;
  END IF;

  v_diff := jsonb_build_object('supplier_publication', jsonb_build_object(
              'old', jsonb_build_object('status', v_prev_status, 'revision', v_pub.revision),
              'new', jsonb_build_object('status', 'withdrawn', 'revision', v_pub.revision, 'reason', v_reason)));
  IF v_po.status IS DISTINCT FROM v_old THEN
    v_diff := v_diff || jsonb_build_object('status', jsonb_build_object('old', v_old, 'new', v_po.status));
  END IF;
  PERFORM public.fn_manual_audit_log('purchase_orders', v_po.id, v_po.organization_id, 'UPDATE', v_diff, 'web_app');
  PERFORM set_config('app.audit_bypass', COALESCE(v_bypass, ''), true);

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'order_status', v_po.status,
    'withdrawn', true,
    'revision', v_pub.revision
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_po_withdraw_from_supplier(p_po_id uuid, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_po_withdraw_from_supplier(p_po_id uuid, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_po_withdraw_from_supplier(p_po_id uuid, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_price_changes_decide(p_ids uuid[], p_approve boolean, p_note text DEFAULT NULL::text, p_accept_unit_change boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_actor    uuid := public.current_business_user_id();
  v_ids      uuid[];
  v_orgs     uuid[];
  v_note     text;
  v_n        integer;
  r          public.supplier_price_change_requests;
  isup       public.item_suppliers;
  v_stale    boolean;
  v_is_upd   boolean;
  v_plan     jsonb;
  v_res      jsonb;
  v_results  jsonb := '[]'::jsonb;
  v_approved integer := 0;
  v_rejected integer := 0;
  v_skipped  integer := 0;
  v_items_upd integer := 0;
  v_costs_upd integer := 0;
BEGIN
  IF v_uid IS NULL OR v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF NOT public.has_anew_permission(v_uid, 'products.edit') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.edit)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF NOT public.has_anew_permission(v_uid, 'products.manage_prices') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (products.manage_prices)' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF p_approve IS NULL THEN
    RAISE EXCEPTION 'Indique se aceita ou recusa' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  v_ids := ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(p_ids, ARRAY[]::uuid[])) x WHERE x IS NOT NULL);
  IF cardinality(v_ids) = 0 THEN
    RAISE EXCEPTION 'Indique os pedidos' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF cardinality(v_ids) > 1000 THEN
    RAISE EXCEPTION 'Demasiados pedidos (máx. 1000)' USING ERRCODE = 'check_violation', HINT = 'too_many_rows';
  END IF;
  v_note := NULLIF(btrim(regexp_replace(COALESCE(p_note, ''), '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]', '', 'g')), '');
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'Nota demasiado longa (máx. 500 caracteres)' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  v_orgs := ARRAY(SELECT public.get_user_visible_org_ids(v_uid));
  SELECT count(*) INTO v_n
  FROM public.supplier_price_change_requests
  WHERE id = ANY (v_ids) AND organization_id = ANY (v_orgs);
  IF v_n <> cardinality(v_ids) THEN
    RAISE EXCEPTION 'Pedido de alteração de preço não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  PERFORM set_config('app.audit_source', 'supplier_price_approval', true);

  FOR r IN
    SELECT * FROM public.supplier_price_change_requests
    WHERE id = ANY (v_ids)
    ORDER BY id
    FOR UPDATE
  LOOP
    IF r.status <> 'pending' THEN
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'id', r.id, 'outcome', 'skipped', 'reason', 'not_pending', 'status', r.status,
        'message', 'Este pedido já não está por aprovar'));
      CONTINUE;
    END IF;

    SELECT * INTO isup FROM public.item_suppliers WHERE id = r.item_supplier_id FOR UPDATE;
    v_stale := isup.id IS NULL OR isup.deleted_at IS NOT NULL
               OR isup.catalog_item_id IS DISTINCT FROM r.catalog_item_id
               OR isup.supplier_id IS DISTINCT FROM r.supplier_id;

    IF NOT p_approve THEN
      UPDATE public.supplier_price_change_requests
         SET status = 'rejected', decided_at = now(), decided_by = v_actor, decision_note = v_note,
             result = jsonb_build_object('item_supplier_updated', false, 'product_cost_updated', false)
       WHERE id = r.id;
      v_rejected := v_rejected + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('id', r.id, 'outcome', 'rejected'));
      CONTINUE;
    END IF;

    IF v_stale THEN
      UPDATE public.supplier_price_change_requests
         SET status = 'superseded', superseded_at = now(),
             result = jsonb_build_object('reason', 'link_changed')
       WHERE id = r.id;
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'id', r.id, 'outcome', 'skipped', 'reason', 'stale',
        'message', 'A ligação deste artigo ao produto mudou ou foi removida: o pedido foi arquivado'));
      CONTINUE;
    END IF;

    IF r.unit_changed AND NOT COALESCE(p_accept_unit_change, false) THEN
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'id', r.id, 'outcome', 'skipped', 'reason', 'unit_changed',
        'message', 'O fornecedor mudou a unidade/embalagem deste artigo: confirme que a ligação continua certa antes de aceitar'));
      CONTINUE;
    END IF;

    -- Preço do fornecedor (histórico pelo gatilho existente).
    v_is_upd := isup.purchase_price IS DISTINCT FROM r.new_price OR isup.currency IS DISTINCT FROM r.currency;
    IF v_is_upd THEN
      UPDATE public.item_suppliers
         SET purchase_price = r.new_price, currency = r.currency, updated_at = now()
       WHERE id = isup.id;
      v_items_upd := v_items_upd + 1;
    END IF;

    -- Custo do produto (mesma regra que rpc_catalog_link com preço do catálogo).
    v_plan := public.fn_apply_product_cost_from_supplier(isup.id, r.organization_id, r.new_price, r.currency, v_actor);
    IF (v_plan ->> 'product_cost_rows')::integer > 0 THEN
      v_costs_upd := v_costs_upd + 1;
    END IF;

    v_res := jsonb_build_object(
      'item_supplier_updated', v_is_upd,
      'accepted_unit_change', r.unit_changed) || v_plan;

    UPDATE public.supplier_price_change_requests
       SET status = 'approved', decided_at = now(), decided_by = v_actor, decision_note = v_note, result = v_res
     WHERE id = r.id;
    v_approved := v_approved + 1;
    v_results := v_results || jsonb_build_array(jsonb_build_object('id', r.id, 'outcome', 'approved') || v_res);
  END LOOP;

  -- Sino: sem pendentes para o fornecedor nessa empresa → aviso resolvido.
  BEGIN
    UPDATE public.notifications n
       SET is_resolved = true, resolved_at = now(), resolved_reason = 'prices_decided'
      FROM (SELECT DISTINCT organization_id, supplier_id
              FROM public.supplier_price_change_requests WHERE id = ANY (v_ids)) s
     WHERE n.type = 'supplier_price_pending'
       AND n.entity_id = s.supplier_id
       AND n.organization_id = s.organization_id
       AND n.is_resolved = false
       AND NOT EXISTS (SELECT 1 FROM public.supplier_price_change_requests q
                       WHERE q.organization_id = s.organization_id AND q.supplier_id = s.supplier_id
                         AND q.status = 'pending');
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Aviso de preços não resolvido: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'approved', v_approved,
    'rejected', v_rejected,
    'skipped', v_skipped,
    'item_suppliers_updated', v_items_upd,
    'product_costs_updated', v_costs_upd,
    'results', v_results
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_price_changes_decide(p_ids uuid[], p_approve boolean, p_note text, p_accept_unit_change boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_price_changes_decide(p_ids uuid[], p_approve boolean, p_note text, p_accept_unit_change boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_price_changes_decide(p_ids uuid[], p_approve boolean, p_note text, p_accept_unit_change boolean) TO service_role;
COMMENT ON FUNCTION public.rpc_price_changes_decide(p_ids uuid[], p_approve boolean, p_note text, p_accept_unit_change boolean) IS 'Portal do fornecedor F3.4b: aceitar (item_suppliers.purchase_price e, se for a ligação preferencial na empresa principal, product_prices purchase = preço / fator) ou recusar pedidos de alteração de preço. products.edit + products.manage_prices. Encomendas existentes não mudam.';

CREATE OR REPLACE FUNCTION public.rpc_price_changes_list(p_supplier_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'pending'::text, p_product_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_status text := lower(COALESCE(NULLIF(btrim(p_status), ''), 'pending'));
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 100), 0), 500);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_orgs   uuid[];
  v_counts jsonb;
  v_total  integer;
  v_items  jsonb;
BEGIN
  IF v_uid IS NULL OR public.current_business_user_id() IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF v_status NOT IN ('pending', 'approved', 'rejected', 'superseded', 'decided', 'all') THEN
    RAISE EXCEPTION 'Estado inválido (pending, approved, rejected, superseded, decided, all)'
      USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  IF p_supplier_id IS NOT NULL THEN
    PERFORM public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  ELSIF NOT public.has_anew_permission(v_uid, 'suppliers.view') THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (suppliers.view)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;
  IF NOT (public.has_anew_permission(v_uid, 'suppliers.view_pricing')
          OR public.has_anew_permission(v_uid, 'products.view_cost')) THEN
    RAISE EXCEPTION 'Sem permissão para esta operação (suppliers.view_pricing)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  v_orgs := ARRAY(SELECT public.get_user_visible_org_ids(v_uid));
  IF p_organization_id IS NOT NULL AND NOT (p_organization_id = ANY (v_orgs)) THEN
    RAISE EXCEPTION 'Empresa não encontrada' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  IF p_product_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.products pr
       WHERE pr.id = p_product_id
         AND (pr.organization_id = ANY (v_orgs)
              OR EXISTS (SELECT 1 FROM public.product_organizations po
                         WHERE po.product_id = pr.id AND po.organization_id = ANY (v_orgs)))) THEN
    RAISE EXCEPTION 'Produto não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  WITH sc AS (
    SELECT r.*
    FROM public.supplier_price_change_requests r
    WHERE r.organization_id = ANY (v_orgs)
      AND (p_supplier_id IS NULL OR r.supplier_id = p_supplier_id)
      AND (p_product_id IS NULL OR r.product_id = p_product_id)
      AND (p_organization_id IS NULL OR r.organization_id = p_organization_id)
  ),
  f AS (
    SELECT sc.* FROM sc
    WHERE v_status = 'all' OR sc.status = v_status
       OR (v_status = 'decided' AND sc.status IN ('approved', 'rejected'))
  ),
  page AS (
    SELECT f.* FROM f
    ORDER BY f.requested_at DESC, f.id
    LIMIT v_limit OFFSET v_offset
  )
  SELECT
    (SELECT jsonb_build_object(
              'pending', count(*) FILTER (WHERE status = 'pending'),
              'approved', count(*) FILTER (WHERE status = 'approved'),
              'rejected', count(*) FILTER (WHERE status = 'rejected'),
              'superseded', count(*) FILTER (WHERE status = 'superseded'))
       FROM sc),
    (SELECT count(*) FROM f),
    (SELECT COALESCE(jsonb_agg(x.item ORDER BY x.requested_at DESC, x.id), '[]'::jsonb)
       FROM (
         SELECT pg.requested_at, pg.id,
                jsonb_build_object(
                  'id', pg.id,
                  'status', pg.status,
                  'organization_id', pg.organization_id,
                  'requested_at', pg.requested_at,
                  'batch_id', pg.batch_id,
                  'supplier', jsonb_build_object('id', s.id, 'name', s.name),
                  'catalog_item', jsonb_build_object(
                    'id', ci.id, 'supplier_ref', ci.supplier_ref, 'name', ci.name, 'is_active', ci.is_active),
                  'item_supplier_id', pg.item_supplier_id,
                  'product', CASE WHEN pr.id IS NULL THEN NULL
                                  ELSE jsonb_build_object('id', pr.id, 'name', pr.name, 'sku', pr.sku) END,
                  'purchase_uom', jsonb_build_object('id', isup.uom_id, 'code', um.code),
                  'is_preferred', COALESCE(isup.is_preferred AND isup.is_active, false),
                  'current_price', isup.purchase_price,
                  'current_currency', isup.currency,
                  'old_price', pg.old_price,
                  'new_price', pg.new_price,
                  'currency', pg.currency,
                  'catalog_old_price', pg.catalog_old_price,
                  'catalog_new_price', pg.catalog_new_price,
                  'diff', CASE WHEN isup.purchase_price IS NOT NULL THEN pg.new_price - isup.purchase_price END,
                  'diff_pct', CASE WHEN isup.purchase_price > 0
                                   THEN round((pg.new_price - isup.purchase_price) / isup.purchase_price * 100, 2) END,
                  'unit_changed', pg.unit_changed,
                  'old_unit_label', pg.old_unit_label,
                  'unit_label', pg.unit_label,
                  'old_units_per_pack', pg.old_units_per_pack,
                  'units_per_pack', pg.units_per_pack,
                  'stale', (isup.id IS NULL OR isup.deleted_at IS NOT NULL
                            OR isup.catalog_item_id IS DISTINCT FROM pg.catalog_item_id
                            OR isup.supplier_id IS DISTINCT FROM pg.supplier_id),
                  'already_applied', (isup.purchase_price IS NOT DISTINCT FROM pg.new_price
                                      AND isup.currency IS NOT DISTINCT FROM pg.currency),
                  'product_cost', CASE WHEN pg.status = 'pending'
                                       THEN public.fn_price_change_cost_plan(pg.item_supplier_id, pg.organization_id, pg.new_price, pg.currency) END,
                  'decided_at', pg.decided_at,
                  'decided_by', CASE WHEN du.id IS NULL THEN NULL
                                     ELSE jsonb_build_object('id', du.id, 'name', du.name) END,
                  'decision_note', pg.decision_note,
                  'superseded_at', pg.superseded_at,
                  'superseded_by', pg.superseded_by,
                  'result', pg.result
                ) AS item
         FROM page pg
         JOIN public.suppliers s ON s.id = pg.supplier_id
         JOIN public.supplier_catalog_items ci ON ci.id = pg.catalog_item_id
         LEFT JOIN public.item_suppliers isup ON isup.id = pg.item_supplier_id
         LEFT JOIN public.uom um ON um.id = isup.uom_id
         LEFT JOIN public.products pr ON pr.id = pg.product_id
         LEFT JOIN public.anew_users du ON du.id = pg.decided_by
       ) x)
  INTO v_counts, v_total, v_items;

  RETURN jsonb_build_object(
    'counts', v_counts,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'items', v_items,
    'can_decide', public.has_anew_permission(v_uid, 'products.edit')
                  AND public.has_anew_permission(v_uid, 'products.manage_prices')
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_price_changes_list(p_supplier_id uuid, p_status text, p_product_id uuid, p_organization_id uuid, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_price_changes_list(p_supplier_id uuid, p_status text, p_product_id uuid, p_organization_id uuid, p_limit integer, p_offset integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_price_changes_list(p_supplier_id uuid, p_status text, p_product_id uuid, p_organization_id uuid, p_limit integer, p_offset integer) TO service_role;
COMMENT ON FUNCTION public.rpc_price_changes_list(p_supplier_id uuid, p_status text, p_product_id uuid, p_organization_id uuid, p_limit integer, p_offset integer) IS 'Portal do fornecedor F3.4b: pedidos de alteração de preço (suppliers.view + suppliers.view_pricing ou products.view_cost). Por fornecedor, produto e/ou empresa; só empresas visíveis. product_cost = pré-visualização do efeito no custo do produto (só pendentes).';

CREATE OR REPLACE FUNCTION public.rpc_product_code_learn(p_id uuid, p_warehouse_id uuid, p_code text, p_kind text, p_product_id uuid, p_uom_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_set_product_uom boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_actor     uuid;
  v_org       uuid;
  v_code      text := btrim(COALESCE(p_code, ''));
  v_kind      text := lower(btrim(COALESCE(p_kind, '')));
  v_key       text;
  v_source    text;
  v_can_edit  boolean;
  v_can_wh    boolean;
  v_prod      record;
  v_uom       uuid;
  v_req_uom   uuid;
  v_factor    integer;
  v_un        uuid;
  v_conf      text;
  v_row       public.product_codes%ROWTYPE;
  v_other     record;
  v_already   text;
  v_existing  uuid;
  v_annulled  jsonb := '[]'::jsonb;
  v_warnings  jsonb := '[]'::jsonb;
  v_uom_set   boolean := false;
  v_prev_src  text;
  v_cn        text;
  v_txt       text;
  v_main_set  boolean := false;  -- products.barcode gravado nesta chamada
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'Identificador da associação em falta' USING ERRCODE = 'check_violation';
  END IF;
  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'Indica o produto' USING ERRCODE = 'check_violation';
  END IF;

  IF p_warehouse_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.warehouses WHERE id = p_warehouse_id AND deleted_at IS NULL;
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'Armazém não encontrado' USING ERRCODE = 'no_data_found';
    END IF;
    v_source := 'receiving';
  ELSE
    SELECT organization_id INTO v_org FROM public.products WHERE id = p_product_id;
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'Produto não encontrado' USING ERRCODE = 'no_data_found';
    END IF;
    v_source := 'product_form';
  END IF;

  v_can_edit := public.has_anew_permission(v_uid, 'products.edit');
  v_can_wh   := public.has_anew_permission(v_uid, 'receiving.learn_codes');  -- NOVO (20261210130000)
  IF v_org NOT IN (SELECT public.get_user_visible_org_ids(v_uid)) OR NOT (v_can_edit OR v_can_wh) THEN
    RAISE EXCEPTION 'Sem permissão para associar códigos a produtos desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Produto (trancado se a unidade do produto pode mudar ou, num código de
  -- barras, se o código principal pode ser preenchido — mesma ordem que a
  -- edição do produto: linha do produto antes do advisory da chave).
  IF COALESCE(p_set_product_uom, false) OR v_kind = 'barcode' THEN
    SELECT id, name, sku, barcode, uom_id, organization_id, deleted_at, is_deleted INTO v_prod
    FROM public.products WHERE id = p_product_id FOR NO KEY UPDATE;
  ELSE
    SELECT id, name, sku, barcode, uom_id, organization_id, deleted_at, is_deleted INTO v_prod
    FROM public.products WHERE id = p_product_id;
  END IF;
  IF v_prod.id IS NULL OR v_prod.organization_id IS DISTINCT FROM v_org
     OR v_prod.deleted_at IS NOT NULL OR v_prod.is_deleted THEN
    RAISE EXCEPTION 'Produto inválido para esta organização' USING ERRCODE = 'check_violation';
  END IF;

  -- Pedido já processado → devolve o gravado (tem de ser igual).
  SELECT * INTO v_row FROM public.product_codes WHERE id = p_id;
  IF FOUND THEN
    v_req_uom := CASE WHEN p_uom_id IS NOT DISTINCT FROM v_prod.uom_id THEN NULL ELSE p_uom_id END;
    IF v_row.organization_id IS DISTINCT FROM v_org OR v_row.created_by IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'Esta associação pertence a outro utilizador ou organização' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_row.product_id IS DISTINCT FROM p_product_id OR v_row.kind IS DISTINCT FROM v_kind
       OR v_row.code_key IS DISTINCT FROM public.fn_product_code_key(v_code)
       OR v_row.supplier_id IS DISTINCT FROM p_supplier_id OR v_row.uom_id IS DISTINCT FROM v_req_uom THEN
      RAISE EXCEPTION 'O identificador da associação já foi usado noutra associação (outro código, produto, unidade ou fornecedor)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN public.fn_product_code_json(p_id)
      || jsonb_build_object('replayed', true, 'learned', v_row.deleted_at IS NULL, 'already', NULL,
                            'product_uom_set', COALESCE((v_row.context ->> 'product_uom_set')::boolean, false),
                            'annulled', COALESCE(v_row.context -> 'annulled', '[]'::jsonb), 'warnings', '[]'::jsonb,
                            'main_barcode_set', false);
  END IF;

  IF v_code = '' THEN
    RAISE EXCEPTION 'Indica o código lido' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_code) > 200 THEN
    RAISE EXCEPTION 'Código demasiado longo' USING ERRCODE = 'check_violation';
  END IF;
  IF v_kind NOT IN ('barcode', 'supplier_ref') THEN
    RAISE EXCEPTION 'Tipo de código inválido (barcode ou supplier_ref)' USING ERRCODE = 'check_violation';
  END IF;
  v_key := public.fn_product_code_key(v_code);

  IF v_kind = 'supplier_ref' AND p_supplier_id IS NULL THEN
    RAISE EXCEPTION 'Indica o fornecedor da referência' USING ERRCODE = 'check_violation';
  END IF;
  IF p_supplier_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.suppliers WHERE id = p_supplier_id AND organization_id = v_org AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Fornecedor inválido para esta organização' USING ERRCODE = 'check_violation';
  END IF;

  v_prev_src := current_setting('app.audit_source', true);
  IF v_source = 'receiving' THEN
    PERFORM set_config('app.audit_source', 'receiving', true);
  END IF;

  -- Produto sem unidade: definir 'un' (opcional, sem conflitos).
  IF v_prod.uom_id IS NULL AND COALESCE(p_set_product_uom, false) THEN
    IF NOT v_can_edit THEN
      RAISE EXCEPTION 'Definir a unidade do produto exige permissão para editar produtos' USING ERRCODE = 'insufficient_privilege';
    END IF;
    SELECT id INTO v_un FROM public.uom
    WHERE organization_id IS NULL AND base_uom_id IS NULL AND lower(btrim(code)) = 'un'
    ORDER BY id LIMIT 1;
    IF v_un IS NULL THEN
      RAISE EXCEPTION 'Unidade "un" não encontrada' USING ERRCODE = 'no_data_found';
    END IF;
    SELECT string_agg(format('%s %s', z.n, z.t), ', ' ORDER BY z.t) INTO v_conf
    FROM (
      SELECT 'linha(s) de encomenda a fornecedor' AS t, count(*) AS n FROM public.purchase_order_items WHERE product_id = p_product_id AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'linha(s) de orçamento', count(*) FROM public.quote_lines WHERE product_id = p_product_id AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'linha(s) de venda direta', count(*) FROM public.direct_sale_lines WHERE product_id = p_product_id AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'ligação(ões) a fornecedores', count(*) FROM public.item_suppliers WHERE product_id = p_product_id AND deleted_at IS NULL AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'material(is) de serviços', count(*) FROM public.service_materials WHERE product_id = p_product_id AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'linha(s) de guias', count(*) FROM public.supplier_delivery_note_lines WHERE product_id = p_product_id AND uom_id IS NOT NULL AND uom_id <> v_un
      UNION ALL SELECT 'código(s) aprendido(s)', count(*) FROM public.product_codes WHERE product_id = p_product_id AND deleted_at IS NULL AND uom_id IS NOT NULL AND uom_id <> v_un
    ) z
    WHERE z.n > 0;
    IF v_conf IS NOT NULL THEN
      RAISE EXCEPTION 'Não é possível definir a unidade "un" em «%»: já há % noutra unidade', v_prod.name, v_conf
        USING ERRCODE = 'check_violation';
    END IF;
    UPDATE public.products SET uom_id = v_un WHERE id = p_product_id;
    v_prod.uom_id := v_un;
    v_uom_set := true;
  END IF;

  -- Unidade do código: NULL = a do produto.
  v_uom := CASE WHEN p_uom_id IS NOT DISTINCT FROM v_prod.uom_id THEN NULL ELSE p_uom_id END;
  IF v_uom IS NOT NULL AND v_prod.uom_id IS NULL
     AND EXISTS (SELECT 1 FROM public.uom WHERE id = v_uom AND base_uom_id IS NULL) THEN
    RAISE EXCEPTION 'O produto «%» não tem unidade definida — associa o código sem unidade ou define a unidade do produto', v_prod.name
      USING ERRCODE = 'check_violation';
  END IF;
  v_factor := public.fn_uom_units_per(v_uom, p_product_id);  -- erro claro se incompatível

  -- Conflitos (com o lock da chave detido).
  IF v_kind = 'barcode' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('product_code:' || v_org::text || ':' || v_key, 0));

    IF public.fn_product_code_key(v_prod.barcode) = v_key THEN
      IF v_uom IS NOT NULL THEN
        RAISE EXCEPTION 'O código «%» já é o código de barras principal de «%» (na unidade do produto)', v_code, v_prod.name
          USING ERRCODE = 'unique_violation', DETAIL = p_product_id::text;
      END IF;
      v_already := 'product_barcode';
    END IF;

    SELECT p.id, p.name, p.sku INTO v_other
    FROM public.products p
    WHERE p.organization_id = v_org AND p.id <> p_product_id
      AND p.deleted_at IS NULL AND NOT p.is_deleted
      AND public.fn_product_code_key(p.barcode) = v_key
    ORDER BY p.id LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'O código «%» já é o código de barras do produto «%» (%)', v_code, v_other.name, v_other.sku
        USING ERRCODE = 'unique_violation', DETAIL = v_other.id::text;
    END IF;
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended('product_code:' || v_org::text || ':' || p_supplier_id::text || ':' || v_key, 0));

    -- Referência na ficha do produto (item_suppliers) do mesmo fornecedor.
    FOR v_other IN
      SELECT i.product_id, p.name, p.sku,
             CASE WHEN i.uom_id IS NOT DISTINCT FROM p.uom_id THEN NULL ELSE i.uom_id END AS uom_id
      FROM public.item_suppliers i
      JOIN public.products p ON p.id = i.product_id
      WHERE i.organization_id = v_org AND i.supplier_id = p_supplier_id AND i.deleted_at IS NULL
        AND i.product_id IS NOT NULL AND p.deleted_at IS NULL AND NOT p.is_deleted
        AND public.fn_product_code_key(i.supplier_sku) = v_key
      ORDER BY (i.product_id = p_product_id) DESC, i.id
    LOOP
      IF v_other.product_id <> p_product_id THEN
        RAISE EXCEPTION 'A referência «%» deste fornecedor já está na ficha do produto «%» (%)', v_code, v_other.name, v_other.sku
          USING ERRCODE = 'unique_violation', DETAIL = v_other.product_id::text;
      ELSIF v_other.uom_id IS DISTINCT FROM v_uom THEN
        RAISE EXCEPTION 'A referência «%» deste fornecedor já está na ficha de «%» noutra unidade', v_code, v_prod.name
          USING ERRCODE = 'unique_violation', DETAIL = p_product_id::text;
      ELSE
        v_already := 'item_supplier';
      END IF;
    END LOOP;
  END IF;

  -- Códigos aprendidos ativos com a mesma chave (no máximo um: índices únicos).
  FOR v_other IN
    SELECT pc.id, pc.product_id, pc.uom_id, p.name, p.sku,
           (p.deleted_at IS NULL AND NOT p.is_deleted) AS active
    FROM public.product_codes pc
    JOIN public.products p ON p.id = pc.product_id
    WHERE pc.organization_id = v_org AND pc.kind = v_kind AND pc.deleted_at IS NULL AND pc.code_key = v_key
      AND (v_kind = 'barcode' OR pc.supplier_id = p_supplier_id)
    FOR UPDATE OF pc
  LOOP
    IF v_other.product_id = p_product_id THEN
      IF v_other.uom_id IS DISTINCT FROM v_uom THEN
        RAISE EXCEPTION 'O código «%» já está associado a «%» noutra unidade', v_code, v_prod.name
          USING ERRCODE = 'unique_violation', DETAIL = p_product_id::text;
      END IF;
      v_already := 'product_code';
      v_existing := v_other.id;
    ELSIF v_other.active THEN
      RAISE EXCEPTION 'O código «%» já está associado ao produto «%» (%)', v_code, v_other.name, v_other.sku
        USING ERRCODE = 'unique_violation', DETAIL = v_other.product_id::text;
    ELSE
      -- Produto apagado não bloqueia: o código antigo é anulado.
      UPDATE public.product_codes
      SET deleted_at = now(), deleted_by = v_actor,
          delete_reason = left(format('Produto «%s» apagado — código associado a «%s»', v_other.name, v_prod.name), 1000)
      WHERE id = v_other.id;
      v_annulled := v_annulled || to_jsonb(v_other.id);
    END IF;
  END LOOP;

  -- Avisos: o código também é o SKU de outro produto (a leitura passa a
  -- encontrar este primeiro — nível 1/2 antes do SKU).
  SELECT string_agg(DISTINCT format('«%s» (%s)', p.name, p.sku), ', ') INTO v_txt
  FROM public.products p
  WHERE p.organization_id = v_org AND p.id <> p_product_id AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND lower(btrim(p.sku)) = lower(v_code);
  IF v_txt IS NOT NULL THEN
    v_warnings := v_warnings || to_jsonb(format('O código «%s» também é o SKU de %s — a leitura passa a encontrar «%s» primeiro', v_code, v_txt, v_prod.name));
  END IF;

  IF v_already IS NOT NULL THEN
    PERFORM set_config('app.audit_source', COALESCE(v_prev_src, ''), true);
    RETURN COALESCE(public.fn_product_code_json(v_existing),
                    jsonb_build_object('id', NULL, 'code', v_code, 'code_key', v_key, 'kind', v_kind,
                                       'product_id', p_product_id, 'product_name', v_prod.name, 'sku', v_prod.sku,
                                       'uom_id', COALESCE(v_uom, v_prod.uom_id),
                                       'uom_code', (SELECT code FROM public.uom WHERE id = COALESCE(v_uom, v_prod.uom_id)),
                                       'is_pack', v_uom IS NOT NULL, 'units_per_uom', v_factor,
                                       'supplier_id', p_supplier_id))
      || jsonb_build_object('replayed', false, 'learned', false, 'already', v_already,
                            'product_uom_set', v_uom_set, 'annulled', v_annulled, 'warnings', v_warnings,
                            'main_barcode_set', false);
  END IF;

  BEGIN
    INSERT INTO public.product_codes (
      id, organization_id, code, kind, product_id, uom_id, supplier_id, source, context, created_by
    ) VALUES (
      p_id, v_org, v_code, v_kind, p_product_id, v_uom, p_supplier_id, v_source,
      jsonb_strip_nulls(jsonb_build_object(
        'warehouse_id', p_warehouse_id,
        'product_uom_set', CASE WHEN v_uom_set THEN true END,
        'annulled', CASE WHEN jsonb_array_length(v_annulled) > 0 THEN v_annulled END)),
      v_actor
    )
    ON CONFLICT (id) DO NOTHING;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Associação em conflito — tenta de novo' USING ERRCODE = 'serialization_failure';
    END IF;
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_cn = CONSTRAINT_NAME;
    IF COALESCE(v_cn, '') = '' THEN
      RAISE;  -- mensagem do gatilho (já com o nome do produto)
    END IF;
    RAISE EXCEPTION 'O código «%» acabou de ser associado a outro produto — lê de novo', v_code
      USING ERRCODE = 'unique_violation';
  END;

  -- Código de barras da unidade do produto num produto sem código principal:
  -- passa também a ser o products.barcode (a linha em product_codes fica).
  -- Códigos de embalagem (v_uom não nulo) nunca: o principal é o da unidade.
  -- Depois do INSERT, com o advisory da chave e a linha do produto detidos;
  -- auditado (fn_generic_entity_audit) com a mesma origem do código.
  IF v_kind = 'barcode' AND v_uom IS NULL AND public.fn_product_code_key(v_prod.barcode) IS NULL THEN
    UPDATE public.products SET barcode = v_code
    WHERE id = p_product_id AND public.fn_product_code_key(barcode) IS NULL;
    v_main_set := FOUND;
  END IF;

  PERFORM set_config('app.audit_source', COALESCE(v_prev_src, ''), true);

  RETURN public.fn_product_code_json(p_id)
    || jsonb_build_object('replayed', false, 'learned', true, 'already', NULL,
                          'product_uom_set', v_uom_set, 'annulled', v_annulled, 'warnings', v_warnings,
                          'main_barcode_set', v_main_set);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_product_code_learn(p_id uuid, p_warehouse_id uuid, p_code text, p_kind text, p_product_id uuid, p_uom_id uuid, p_supplier_id uuid, p_set_product_uom boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_product_code_learn(p_id uuid, p_warehouse_id uuid, p_code text, p_kind text, p_product_id uuid, p_uom_id uuid, p_supplier_id uuid, p_set_product_uom boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_product_code_learn(p_id uuid, p_warehouse_id uuid, p_code text, p_kind text, p_product_id uuid, p_uom_id uuid, p_supplier_id uuid, p_set_product_uom boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_product_code_remove(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_actor    uuid;
  v_reason   text := btrim(COALESCE(p_reason, ''));
  v_row      public.product_codes%ROWTYPE;
  v_can_edit boolean;
  v_can_wh   boolean;
  v_already  boolean := false;
  v_scans    integer;
  v_main_cleared boolean := false;  -- products.barcode limpo nesta chamada
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT * INTO v_row FROM public.product_codes WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Código não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  v_can_edit := public.has_anew_permission(v_uid, 'products.edit');
  v_can_wh   := public.has_anew_permission(v_uid, 'receiving.learn_codes');  -- NOVO (20261210130000)
  IF v_row.organization_id NOT IN (SELECT public.get_user_visible_org_ids(v_uid))
     OR NOT (v_can_edit
             OR (v_can_wh AND v_row.created_by = v_actor AND v_row.created_at > now() - interval '24 hours')) THEN
    RAISE EXCEPTION 'Só quem associou o código (nas primeiras 24 h) ou quem edita produtos o pode remover'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'Indica o motivo' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_reason) > 1000 THEN
    RAISE EXCEPTION 'Motivo demasiado longo' USING ERRCODE = 'check_violation';
  END IF;

  IF v_row.deleted_at IS NOT NULL THEN
    v_already := true;
  ELSE
    UPDATE public.product_codes
    SET deleted_at = now(), deleted_by = v_actor, delete_reason = v_reason
    WHERE id = p_id;
    -- O código removido era também o código principal (mesma chave): limpa-o.
    IF v_row.kind = 'barcode' THEN
      UPDATE public.products SET barcode = NULL
      WHERE id = v_row.product_id AND public.fn_product_code_key(barcode) = v_row.code_key;
      v_main_cleared := FOUND;
    END IF;
  END IF;

  SELECT count(*) INTO v_scans
  FROM public.receiving_scans s
  WHERE s.organization_id = v_row.organization_id
    AND s.product_id = v_row.product_id
    AND s.created_at >= v_row.created_at
    AND public.fn_product_code_key(s.code) = v_row.code_key;

  RETURN public.fn_product_code_json(p_id)
    || jsonb_build_object('removed', NOT v_already, 'already_removed', v_already, 'scans_using_code', v_scans,
                          'main_barcode_cleared', v_main_cleared);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_product_code_remove(p_id uuid, p_reason text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_product_code_remove(p_id uuid, p_reason text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_product_code_remove(p_id uuid, p_reason text) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_receive_by_code(p_request_id uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_purchase_order_item_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_dry_run boolean DEFAULT false, p_delivery_note_id uuid DEFAULT NULL::uuid, p_unit_conversion boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor       uuid;
  v_org         uuid;
  v_dry         boolean := COALESCE(p_dry_run, false);
  v_code        text := nullif(btrim(COALESCE(p_code, '')), '');
  v_lc          text;
  v_product     record;
  v_factor      integer;
  v_uom_code    text;
  v_units       numeric;
  v_matched_by  text;
  v_replay      jsonb;
  v_forced      record;
  v_locked      uuid[];
  v_cid         uuid;
  v_open_total  numeric;
  v_open_list   text;
  v_plan        jsonb;
  v_po          record;
  v_r           jsonb;
  v_allocs      jsonb := '[]'::jsonb;
  v_warnings    jsonb := '[]'::jsonb;
  v_to_order    numeric := 0;
  v_to_stock    numeric := 0;
  v_other       integer;
  v_result      jsonb;
  -- NOVO (guia)
  v_note_org       uuid;
  v_note_supplier  uuid;
  v_note_number    text;
  v_note_status    text;
  v_scope          uuid[];
  v_note_poi       uuid[];
  v_note_has_lines boolean := false;
  v_ann            numeric;
  v_rcv            numeric;
  v_checks         jsonb := '[]'::jsonb;
  -- NOVO (códigos)
  v_key            text;
  v_conv           boolean := COALESCE(p_unit_conversion, false);
  v_base_code      text;
  v_line           record;
  v_rest           numeric;
  v_take           numeric;
  v_open_units     numeric;
BEGIN
  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Identificador do pedido de receção em falta' USING ERRCODE = 'check_violation';
  END IF;

  SELECT organization_id INTO v_org
  FROM public.warehouses
  WHERE id = p_warehouse_id AND deleted_at IS NULL;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Armazém não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_org NOT IN (SELECT public.get_user_visible_org_ids(auth.uid()))
     OR NOT public.has_anew_permission(auth.uid(), 'receiving.receive')  -- NOVO (20261210130000)
     OR NOT public.has_anew_permission(auth.uid(), 'purchase_orders.receive')
     OR NOT public.has_anew_permission(auth.uid(), 'inventory.edit') THEN
    RAISE EXCEPTION 'Sem permissão para receber encomendas desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Pedido já processado → devolve o resultado gravado.
  v_replay := public.fn_receiving_scan_replay(p_request_id, v_org, v_actor, p_warehouse_id, p_product_id, p_quantity, p_uom_id);
  IF v_replay IS NOT NULL THEN
    -- NOVO (guia): o identificador gravado com outra guia (ou sem guia) é erro.
    IF (SELECT s.delivery_note_id FROM public.receiving_scans s WHERE s.id = p_request_id) IS DISTINCT FROM p_delivery_note_id THEN
      RAISE EXCEPTION 'O identificador do pedido de receção já foi usado noutra leitura (outra guia)'
        USING ERRCODE = 'check_violation';
    END IF;
    -- NOVO (códigos): gravado com outra opção de conversão de unidades → erro.
    IF COALESCE((v_replay ->> 'unit_conversion')::boolean, false) IS DISTINCT FROM v_conv THEN
      RAISE EXCEPTION 'O identificador do pedido de receção já foi usado noutra leitura (outra opção de conversão de unidades)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN v_replay;
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'A quantidade lida tem de ser positiva' USING ERRCODE = 'check_violation';
  END IF;
  IF p_quantity <> floor(p_quantity) THEN
    RAISE EXCEPTION 'A quantidade lida tem de ser um número inteiro (%)', p_quantity USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, name, sku, barcode, uom_id INTO v_product
  FROM public.products
  WHERE id = p_product_id AND organization_id = v_org AND deleted_at IS NULL AND NOT is_deleted;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto inválido para esta organização' USING ERRCODE = 'check_violation';
  END IF;

  IF p_supplier_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.suppliers
    WHERE id = p_supplier_id AND organization_id = v_org AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Fornecedor inválido para esta organização' USING ERRCODE = 'check_violation';
  END IF;

  -- NOVO (guia): 1.º lock da ordem global — a guia FOR SHARE (várias leituras
  -- da mesma guia em paralelo; fechar/editar/cancelar esperam). Fixa o
  -- fornecedor e o âmbito.
  IF p_delivery_note_id IS NOT NULL THEN
    SELECT organization_id, supplier_id, note_number, status
    INTO v_note_org, v_note_supplier, v_note_number, v_note_status
    FROM public.supplier_delivery_notes
    WHERE id = p_delivery_note_id
    FOR SHARE;
    IF v_note_org IS NULL OR v_note_org <> v_org THEN
      RAISE EXCEPTION 'Guia do fornecedor não encontrada nesta organização' USING ERRCODE = 'no_data_found';
    END IF;
    IF v_note_status <> 'open' THEN
      RAISE EXCEPTION 'A guia % está % — reabre-a para receber', v_note_number,
        CASE v_note_status WHEN 'closed' THEN 'fechada' ELSE 'cancelada' END
        USING ERRCODE = 'check_violation';
    END IF;
    IF p_supplier_id IS NOT NULL AND p_supplier_id <> v_note_supplier THEN
      RAISE EXCEPTION 'A guia % é de outro fornecedor', v_note_number USING ERRCODE = 'check_violation';
    END IF;
    p_supplier_id := v_note_supplier;
    v_scope := public.fn_delivery_note_scope(p_delivery_note_id);
    SELECT array_agg(DISTINCT l.purchase_order_item_id) FILTER (WHERE l.purchase_order_item_id IS NOT NULL),
           count(*) > 0
    INTO v_note_poi, v_note_has_lines
    FROM public.supplier_delivery_note_lines l
    WHERE l.delivery_note_id = p_delivery_note_id;
  END IF;

  -- Fator da unidade lida (erro claro se a unidade não for do produto).
  v_factor   := public.fn_uom_units_per(p_uom_id, p_product_id);
  v_uom_code := COALESCE((SELECT code FROM public.uom WHERE id = COALESCE(p_uom_id, v_product.uom_id)), 'un.');
  v_units    := p_quantity * v_factor;
  IF v_units > 2147483647 THEN
    RAISE EXCEPTION 'A leitura excede o limite de stock (% unidades)', v_units USING ERRCODE = 'numeric_value_out_of_range';
  END IF;

  -- Como o código lido corresponde a este produto (só registo/aviso).
  IF v_code IS NOT NULL THEN
    v_lc := lower(v_code);
    v_key := public.fn_product_code_key(v_code);  -- NOVO (códigos)
    v_matched_by := CASE
      -- NOVO (códigos): chave normalizada + códigos aprendidos
      WHEN public.fn_product_code_key(v_product.barcode) = v_key
        OR EXISTS (SELECT 1 FROM public.product_codes pc
                   WHERE pc.product_id = p_product_id AND pc.organization_id = v_org
                     AND pc.kind = 'barcode' AND pc.deleted_at IS NULL AND pc.code_key = v_key) THEN 'barcode'
      WHEN EXISTS (SELECT 1 FROM public.purchase_order_items poi
                   JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
                   WHERE po.organization_id = v_org AND poi.product_id = p_product_id
                     AND lower(btrim(poi.supplier_sku)) = v_lc)
        OR EXISTS (SELECT 1 FROM public.item_suppliers i
                   WHERE i.organization_id = v_org AND i.product_id = p_product_id
                     AND i.deleted_at IS NULL AND lower(btrim(i.supplier_sku)) = v_lc)
        OR EXISTS (SELECT 1 FROM public.product_codes pc  -- NOVO (códigos)
                   WHERE pc.product_id = p_product_id AND pc.organization_id = v_org
                     AND pc.kind = 'supplier_ref' AND pc.deleted_at IS NULL AND pc.code_key = v_key) THEN 'supplier_sku'
      WHEN lower(btrim(v_product.sku)) = v_lc THEN 'sku'
      WHEN EXISTS (SELECT 1 FROM public.purchase_order_items poi
                   JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
                   WHERE po.organization_id = v_org AND poi.product_id = p_product_id
                     AND lower(btrim(poi.sku)) = v_lc) THEN 'po_line_sku'
    END;
    IF v_matched_by IS NULL THEN
      v_warnings := v_warnings || to_jsonb(format('O código «%s» não corresponde a «%s»', v_code, v_product.name));
    END IF;
  END IF;

  -- Linha forçada: validações com mensagens claras.
  IF p_purchase_order_item_id IS NOT NULL THEN
    SELECT poi.id, poi.product_id, poi.item_type, poi.quantity, poi.received_quantity,
           COALESCE(poi.units_per_uom, 1) AS units_per_uom, poi.description,
           po.status, po.supplier_id, po.order_number
    INTO v_forced
    FROM public.purchase_order_items poi
    JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
    WHERE poi.id = p_purchase_order_item_id AND po.organization_id = v_org AND po.deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Linha de encomenda não encontrada' USING ERRCODE = 'no_data_found';
    END IF;
    IF v_forced.item_type <> 'product' OR v_forced.product_id IS DISTINCT FROM p_product_id THEN
      RAISE EXCEPTION 'A linha "%" (%) não é do produto lido', v_forced.description, v_forced.order_number
        USING ERRCODE = 'check_violation';
    END IF;
    IF p_supplier_id IS NOT NULL AND v_forced.supplier_id IS DISTINCT FROM p_supplier_id THEN
      RAISE EXCEPTION 'A linha "%" (%) é de outro fornecedor', v_forced.description, v_forced.order_number
        USING ERRCODE = 'check_violation';
    END IF;
    -- NOVO (guia): a linha forçada tem de estar no âmbito da guia.
    IF v_scope IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.purchase_order_items poi
      WHERE poi.id = p_purchase_order_item_id AND poi.purchase_order_id = ANY (v_scope)
    ) THEN
      RAISE EXCEPTION 'A linha "%" (%) não está nas encomendas da guia %', v_forced.description, v_forced.order_number, v_note_number
        USING ERRCODE = 'check_violation';
    END IF;
    -- NOVO (códigos): com conversão a linha pode estar noutra unidade (a
    -- divisibilidade é verificada no plano).
    IF NOT v_conv AND v_forced.units_per_uom <> v_factor THEN
      RAISE EXCEPTION 'A linha "%" (%) está noutra unidade (% un. por unidade; a leitura tem %)', v_forced.description, v_forced.order_number, v_forced.units_per_uom, v_factor
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_forced.status NOT IN ('pending', 'ordered', 'partially_received') OR v_forced.quantity <= v_forced.received_quantity THEN
      RAISE EXCEPTION 'A linha "%" (%) não está em aberto', v_forced.description, v_forced.order_number
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Reserva do identificador (fica com o resultado no fim). Um pedido igual
  -- em paralelo espera aqui pelo primeiro e, quando este confirma, devolve o
  -- resultado gravado. Em dry-run nada é gravado.
  IF NOT v_dry THEN
    INSERT INTO public.receiving_scans (
      id, organization_id, warehouse_id, supplier_id, code, matched_by,
      product_id, uom_id, quantity, units, result, created_by,
      delivery_note_id  -- NOVO (guia)
    ) VALUES (
      p_request_id, v_org, p_warehouse_id, p_supplier_id, v_code, v_matched_by,
      p_product_id, p_uom_id, p_quantity, v_units, '{}'::jsonb, v_actor,
      p_delivery_note_id
    )
    ON CONFLICT (id) DO NOTHING;

    IF NOT FOUND THEN
      v_replay := public.fn_receiving_scan_replay(p_request_id, v_org, v_actor, p_warehouse_id, p_product_id, p_quantity, p_uom_id);
      IF v_replay IS NULL THEN
        RAISE EXCEPTION 'Pedido de receção em conflito — tenta de novo' USING ERRCODE = 'serialization_failure';
      END IF;
      -- NOVO (guia)
      IF (SELECT s.delivery_note_id FROM public.receiving_scans s WHERE s.id = p_request_id) IS DISTINCT FROM p_delivery_note_id THEN
        RAISE EXCEPTION 'O identificador do pedido de receção já foi usado noutra leitura (outra guia)'
          USING ERRCODE = 'check_violation';
      END IF;
      -- NOVO (códigos)
      IF COALESCE((v_replay ->> 'unit_conversion')::boolean, false) IS DISTINCT FROM v_conv THEN
        RAISE EXCEPTION 'O identificador do pedido de receção já foi usado noutra leitura (outra opção de conversão de unidades)'
          USING ERRCODE = 'check_violation';
      END IF;
      RETURN v_replay;
    END IF;
  END IF;

  -- 1. Serializa leituras do mesmo produto.
  PERFORM pg_advisory_xact_lock(hashtextextended('receiving:' || v_org::text || ':' || p_product_id::text, 0));

  BEGIN
    -- 2. Tranca as POs candidatas (ordem fixa por id).
    SELECT COALESCE(array_agg(t.id ORDER BY t.id), ARRAY[]::uuid[]) INTO v_locked
    FROM (
      SELECT po.id
      FROM public.purchase_orders po
      WHERE po.id IN (
              SELECT o.purchase_order_id
              FROM public.fn_receiving_open_lines(v_org, ARRAY[p_product_id], p_supplier_id) o
              WHERE (v_conv OR o.units_per_uom = v_factor)  -- NOVO (códigos)
                AND (p_purchase_order_item_id IS NULL OR o.purchase_order_item_id = p_purchase_order_item_id)
                AND (v_scope IS NULL OR o.purchase_order_id = ANY (v_scope)))  -- NOVO (guia)
        AND po.deleted_at IS NULL
        AND po.status IN ('pending', 'ordered', 'partially_received')
      ORDER BY po.id
      FOR UPDATE
    ) t;

    -- 3. Locks das Encomendas Cliente (os da Fase 1), ordem fixa.
    FOR v_cid IN
      SELECT DISTINCT po.source_id
      FROM public.purchase_orders po
      WHERE po.id = ANY (v_locked) AND po.source_type = 'contract' AND po.source_id IS NOT NULL
      ORDER BY po.source_id
    LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended('po_receipt_contract:' || v_cid::text, 0));
    END LOOP;

    -- 4. Em aberto relido com tudo trancado (só POs trancadas). take = o que
    --    cada linha recebe, enchendo pela ordem D2 (NOVO (guia): primeiro as
    --    linhas indicadas na guia; sem guia a ordem é a mesma).
    IF NOT v_conv THEN  -- caminho da fatia 2 (sem conversão), intacto
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'rn', a.rn, 'purchase_order_id', a.purchase_order_id, 'order_number', a.order_number,
             'po_status', a.po_status, 'purchase_order_item_id', a.purchase_order_item_id,
             'open_quantity', a.open_quantity, 'take', a.take) ORDER BY a.rn), '[]'::jsonb),
           COALESCE(SUM(a.open_quantity), 0),
           string_agg(DISTINCT a.order_number, ', ')
    INTO v_plan, v_open_total, v_open_list
    FROM (
      SELECT c.rn, c.purchase_order_id, c.order_number, c.po_status, c.purchase_order_item_id, c.open_quantity,
             LEAST(c.open_quantity,
                   GREATEST(0, p_quantity - COALESCE(SUM(c.open_quantity) OVER (
                     ORDER BY c.rn ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0))) AS take
      FROM (
        SELECT o.*, row_number() OVER (
                 ORDER BY CASE WHEN o.purchase_order_item_id = ANY (v_note_poi) THEN 0 ELSE 1 END,  -- NOVO (guia)
                          o.allocation_rank) AS rn
        FROM public.fn_receiving_open_lines(v_org, ARRAY[p_product_id], p_supplier_id) o
        WHERE o.purchase_order_id = ANY (v_locked)
          AND o.units_per_uom = v_factor
          AND (p_purchase_order_item_id IS NULL OR o.purchase_order_item_id = p_purchase_order_item_id)
      ) c
    ) a;

    -- D3: acima do em aberto → recusa tudo.
    IF v_open_total < p_quantity THEN
      RAISE EXCEPTION '%', format('Leste %s %s; em aberto %s %s%s', p_quantity, v_uom_code, v_open_total, v_uom_code,
        CASE WHEN v_open_list IS NOT NULL THEN format(' (%s)', v_open_list)
             WHEN p_purchase_order_item_id IS NOT NULL THEN ' (a linha indicada já não está em aberto)'
             ELSE format(' — sem encomendas a fornecedor em aberto para «%s»%s', v_product.name,
                         CASE WHEN p_supplier_id IS NOT NULL THEN ' deste fornecedor nesta unidade' ELSE ' nesta unidade' END)
        END)
        -- NOVO (guia): âmbito da guia na mensagem ('' sem guia)
        || CASE WHEN p_delivery_note_id IS NOT NULL
                THEN format(' — âmbito da guia %s%s', v_note_number,
                            CASE WHEN v_scope IS NOT NULL THEN format(' (%s encomenda(s) da guia)', cardinality(v_scope))
                                 ELSE ' (encomendas do fornecedor)' END)
                ELSE '' END
        USING ERRCODE = 'check_violation';
    END IF;

    ELSE
      -- NOVO (códigos): conversão caixa↔unidades. Linhas elegíveis = todas as
      -- linhas em aberto trancadas (os fatores das linhas são todos sobre a
      -- unidade de stock do produto — mesma base); ordem = linhas da guia →
      -- D2, sem preferir a unidade lida. Cada linha só leva unidades inteiras
      -- suas: take = LEAST(em aberto, floor(resto / fator)). Resto ≠ 0 →
      -- recusa tudo (mensagens em unidades de stock).
      v_rest := v_units;
      v_open_units := 0;
      v_plan := '[]'::jsonb;
      v_base_code := COALESCE((SELECT code FROM public.uom WHERE id = v_product.uom_id), 'un.');
      FOR v_line IN
        SELECT o.*, row_number() OVER (
                 ORDER BY CASE WHEN o.purchase_order_item_id = ANY (v_note_poi) THEN 0 ELSE 1 END,
                          o.allocation_rank) AS rn
        FROM public.fn_receiving_open_lines(v_org, ARRAY[p_product_id], p_supplier_id) o
        WHERE o.purchase_order_id = ANY (v_locked)
          AND o.units_per_uom >= 1
          AND (p_purchase_order_item_id IS NULL OR o.purchase_order_item_id = p_purchase_order_item_id)
        ORDER BY rn
      LOOP
        v_take := LEAST(v_line.open_quantity, floor(v_rest / v_line.units_per_uom));
        v_rest := v_rest - v_take * v_line.units_per_uom;
        v_open_units := v_open_units + v_line.open_quantity * v_line.units_per_uom;
        v_plan := v_plan || jsonb_build_object(
          'rn', v_line.rn, 'purchase_order_id', v_line.purchase_order_id, 'order_number', v_line.order_number,
          'po_status', v_line.po_status, 'purchase_order_item_id', v_line.purchase_order_item_id,
          'open_quantity', v_line.open_quantity, 'take', v_take);
      END LOOP;
      SELECT string_agg(DISTINCT x ->> 'order_number', ', ') INTO v_open_list
      FROM jsonb_array_elements(v_plan) x;

      IF v_rest <> 0 THEN
        RAISE EXCEPTION '%', CASE
          WHEN v_open_units < v_units THEN
            format('Leste %s %s (%s %s); em aberto %s %s%s', p_quantity, v_uom_code, trim_scale(v_units), v_base_code,
                   trim_scale(v_open_units), v_base_code,
                   CASE WHEN v_open_list IS NOT NULL THEN format(' (%s)', v_open_list)
                        WHEN p_purchase_order_item_id IS NOT NULL THEN ' (a linha indicada já não está em aberto)'
                        ELSE format(' — sem encomendas a fornecedor em aberto para «%s»%s', v_product.name,
                                    CASE WHEN p_supplier_id IS NOT NULL THEN ' deste fornecedor' ELSE '' END)
                   END)
          ELSE
            format('Leste %s %s (%s %s); as linhas em aberto (%s) só recebem unidades inteiras da sua embalagem — ficam %s %s por distribuir',
                   p_quantity, v_uom_code, trim_scale(v_units), v_base_code, v_open_list, trim_scale(v_rest), v_base_code)
          END
          || CASE WHEN p_delivery_note_id IS NOT NULL
                  THEN format(' — âmbito da guia %s%s', v_note_number,
                              CASE WHEN v_scope IS NOT NULL THEN format(' (%s encomenda(s) da guia)', cardinality(v_scope))
                                   ELSE ' (encomendas do fornecedor)' END)
                  ELSE '' END
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- NOVO (guia): avisos de anunciado (decisão 1: aviso + confirmação no
    -- ecrã). Com o lock do produto detido, o recebido pela guia é estável.
    IF p_delivery_note_id IS NOT NULL AND v_note_has_lines THEN
      SELECT COALESCE(sum(l.quantity * l.units_per_uom), 0) INTO v_ann
      FROM public.supplier_delivery_note_lines l
      WHERE l.delivery_note_id = p_delivery_note_id AND l.product_id = p_product_id;
      IF v_ann = 0 THEN
        v_checks   := v_checks || to_jsonb('nao_consta_da_guia'::text);
        v_warnings := v_warnings || to_jsonb(format('«%s» não consta da guia %s', v_product.name, v_note_number));
      ELSE
        SELECT COALESCE(sum(pr.quantity * pr.units_per_uom), 0) INTO v_rcv
        FROM public.purchase_order_receipts pr
        WHERE pr.delivery_note_id = p_delivery_note_id AND pr.product_id = p_product_id
          AND pr.kind = 'receipt' AND pr.reverted_at IS NULL;
        IF v_rcv + v_units > v_ann THEN
          v_checks   := v_checks || to_jsonb('acima_do_anunciado'::text);
          v_warnings := v_warnings || to_jsonb(format('«%s»: com esta leitura ficam %s un. recebidas pela guia %s; anunciadas %s un.',
                          v_product.name, trim_scale(v_rcv + v_units), v_note_number, trim_scale(v_ann)));
        END IF;
      END IF;
    END IF;

    -- 5. Receção pela Fase 1, uma chamada por PO, pela ordem D2 (os locks já
    --    estão todos detidos, a ordem das chamadas não cria esperas novas).
    FOR v_po IN
      SELECT l.purchase_order_id, min(l.order_number) AS order_number,
             bool_or(l.po_status = 'pending') AS pending,
             jsonb_agg(jsonb_build_object('purchase_order_item_id', l.purchase_order_item_id, 'quantity', l.take) ORDER BY l.rn) AS lines,
             array_agg(l.purchase_order_item_id ORDER BY l.rn) AS ids
      FROM jsonb_to_recordset(v_plan) AS l(rn bigint, purchase_order_id uuid, order_number text, po_status text,
                                           purchase_order_item_id uuid, open_quantity numeric, take numeric)
      WHERE l.take > 0
      GROUP BY l.purchase_order_id
      ORDER BY min(l.rn)
    LOOP
      v_r := public.rpc_receive_purchase_order_lines(v_po.purchase_order_id, p_warehouse_id, v_po.lines, NULL);

      IF NOT v_dry THEN
        -- Liga as linhas de histórico acabadas de gravar pela Fase 1 a esta
        -- leitura (received_at = now() = início da transação; received_by =
        -- current_business_user_id(), como a Fase 1 grava).
        UPDATE public.purchase_order_receipts
        SET receiving_scan_id = p_request_id,
            delivery_note_id  = p_delivery_note_id  -- NOVO (guia); NULL sem guia (já era NULL)
        WHERE purchase_order_id = v_po.purchase_order_id
          AND purchase_order_item_id = ANY (v_po.ids)
          AND kind = 'receipt'
          AND receiving_scan_id IS NULL
          AND received_at = now()
          AND received_by = v_actor;
      END IF;

      IF v_po.pending THEN
        v_warnings := v_warnings || to_jsonb(format('%s ainda está pendente (não confirmada ao fornecedor)', v_po.order_number));
      END IF;

      v_allocs := v_allocs || jsonb_build_object(
        'purchase_order_id',    v_po.purchase_order_id,
        'order_number',         v_r -> 'order_number',
        'status',               v_r -> 'status',
        'stock_skipped',        v_r -> 'stock_skipped',
        'units_to_order_total', v_r -> 'units_to_order_total',
        'units_to_stock_total', v_r -> 'units_to_stock_total',
        'lines',                v_r -> 'lines'
      );
      v_to_order := v_to_order + COALESCE((v_r ->> 'units_to_order_total')::numeric, 0);
      v_to_stock := v_to_stock + COALESCE((v_r ->> 'units_to_stock_total')::numeric, 0);
    END LOOP;

    IF v_dry THEN
      RAISE EXCEPTION USING ERRCODE = 'OLPV2', MESSAGE = 'receive_by_code_dry_run_rollback';
    END IF;
  EXCEPTION WHEN SQLSTATE 'OLPV2' THEN
    NULL;  -- dry-run: tudo o que a receção escreveu foi desfeito com a subtransação
  END;

  SELECT count(*) INTO v_other
  FROM public.fn_receiving_open_lines(v_org, ARRAY[p_product_id], p_supplier_id) o
  WHERE NOT v_conv AND o.units_per_uom <> v_factor  -- NOVO (códigos): com conversão nenhuma fica de fora
    AND (v_scope IS NULL OR o.purchase_order_id = ANY (v_scope));  -- NOVO (guia)
  IF v_other > 0 THEN
    v_warnings := v_warnings || to_jsonb(format('%s linha(s) em aberto de «%s» noutra unidade não entraram nesta leitura', v_other, v_product.name));
  END IF;

  v_result := jsonb_build_object(
    'request_id',           p_request_id,
    'replayed',             false,
    'dry_run',              v_dry,
    'product_id',           p_product_id,
    'warehouse_id',         p_warehouse_id,
    'supplier_id',          p_supplier_id,
    'uom_id',               p_uom_id,
    'uom_code',             v_uom_code,
    'units_per_uom',        v_factor,
    'quantity',             p_quantity,
    'units',                v_units,
    'matched_by',           v_matched_by,
    'allocations',          v_allocs,
    'units_to_order_total', v_to_order,
    'units_to_stock_total', v_to_stock,
    'warnings',             v_warnings
  ) || CASE WHEN p_delivery_note_id IS NOT NULL  -- NOVO (guia): '{}' sem guia
            THEN jsonb_build_object('delivery_note_id', p_delivery_note_id,
                                    'delivery_note_number', v_note_number,
                                    'delivery_note_checks', v_checks)
            ELSE '{}'::jsonb END
    || CASE WHEN v_conv THEN jsonb_build_object('unit_conversion', true) ELSE '{}'::jsonb END;  -- NOVO (códigos)

  IF NOT v_dry THEN
    UPDATE public.receiving_scans SET result = v_result WHERE id = p_request_id;
  END IF;

  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_receive_by_code(p_request_id uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid, p_supplier_id uuid, p_purchase_order_item_id uuid, p_code text, p_dry_run boolean, p_delivery_note_id uuid, p_unit_conversion boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_receive_by_code(p_request_id uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid, p_supplier_id uuid, p_purchase_order_item_id uuid, p_code text, p_dry_run boolean, p_delivery_note_id uuid, p_unit_conversion boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_receive_by_code(p_request_id uuid, p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_uom_id uuid, p_supplier_id uuid, p_purchase_order_item_id uuid, p_code text, p_dry_run boolean, p_delivery_note_id uuid, p_unit_conversion boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_receiving_lookup(p_warehouse_id uuid, p_code text, p_supplier_id uuid DEFAULT NULL::uuid, p_delivery_note_id uuid DEFAULT NULL::uuid, p_unit_conversion boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org         uuid;
  v_code        text := btrim(COALESCE(p_code, ''));
  v_lc          text;
  v_can_receive boolean;
  v_level       integer;
  v_cand        record;
  v_factor      integer;
  v_lines       jsonb;
  v_candidates  jsonb := '[]'::jsonb;
  v_warnings    jsonb := '[]'::jsonb;
  v_other       integer;
  v_other_txt   text;
  v_matches     jsonb;
  -- NOVO (guia)
  v_note_org       uuid;
  v_note_supplier  uuid;
  v_note_number    text;
  v_note_status    text;
  v_scope          uuid[];
  v_note_poi       uuid[];
  v_note_has_lines boolean := false;
  v_ann            numeric;
  v_rcv            numeric;
  v_note_info      jsonb := '{}'::jsonb;
  -- NOVO (códigos)
  v_key            text;
  v_conv           boolean := COALESCE(p_unit_conversion, false);
BEGIN
  SELECT organization_id INTO v_org
  FROM public.warehouses
  WHERE id = p_warehouse_id AND deleted_at IS NULL;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Armazém não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_org NOT IN (SELECT public.get_user_visible_org_ids(auth.uid()))
     OR NOT public.has_anew_permission(auth.uid(), 'receiving.view')  -- NOVO (20261210130000)
     OR NOT (public.has_anew_permission(auth.uid(), 'purchase_orders.receive')
             OR public.has_anew_permission(auth.uid(), 'purchase_orders.view')) THEN
    RAISE EXCEPTION 'Sem permissão para consultar encomendas desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_can_receive := public.has_anew_permission(auth.uid(), 'receiving.receive')  -- NOVO (20261210130000)
               AND public.has_anew_permission(auth.uid(), 'purchase_orders.receive')
               AND public.has_anew_permission(auth.uid(), 'inventory.edit');

  IF v_code = '' THEN
    RAISE EXCEPTION 'Indica o código lido' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_code) > 200 THEN
    RAISE EXCEPTION 'Código lido demasiado longo' USING ERRCODE = 'check_violation';
  END IF;

  IF p_supplier_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.suppliers
    WHERE id = p_supplier_id AND organization_id = v_org AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Fornecedor inválido para esta organização' USING ERRCODE = 'check_violation';
  END IF;

  -- NOVO (guia): a guia fixa o fornecedor e o âmbito (POs da guia, ou todas
  -- as do fornecedor se não tiver POs).
  IF p_delivery_note_id IS NOT NULL THEN
    SELECT organization_id, supplier_id, note_number, status
    INTO v_note_org, v_note_supplier, v_note_number, v_note_status
    FROM public.supplier_delivery_notes
    WHERE id = p_delivery_note_id;
    IF v_note_org IS NULL OR v_note_org <> v_org THEN
      RAISE EXCEPTION 'Guia do fornecedor não encontrada nesta organização' USING ERRCODE = 'no_data_found';
    END IF;
    IF v_note_status <> 'open' THEN
      RAISE EXCEPTION 'A guia % está % — reabre-a para receber', v_note_number,
        CASE v_note_status WHEN 'closed' THEN 'fechada' ELSE 'cancelada' END
        USING ERRCODE = 'check_violation';
    END IF;
    IF p_supplier_id IS NOT NULL AND p_supplier_id <> v_note_supplier THEN
      RAISE EXCEPTION 'A guia % é de outro fornecedor', v_note_number USING ERRCODE = 'check_violation';
    END IF;
    p_supplier_id := v_note_supplier;
    v_scope := public.fn_delivery_note_scope(p_delivery_note_id);
    SELECT array_agg(DISTINCT l.purchase_order_item_id) FILTER (WHERE l.purchase_order_item_id IS NOT NULL),
           count(*) > 0
    INTO v_note_poi, v_note_has_lines
    FROM public.supplier_delivery_note_lines l
    WHERE l.delivery_note_id = p_delivery_note_id;
    v_note_info := jsonb_build_object('delivery_note', jsonb_build_object(
      'id', p_delivery_note_id, 'note_number', v_note_number, 'status', v_note_status,
      'supplier_id', v_note_supplier, 'purchase_order_ids', to_jsonb(v_scope), 'has_lines', v_note_has_lines));
  END IF;

  v_lc := lower(v_code);
  v_key := public.fn_product_code_key(v_code);  -- NOVO (códigos)

  -- Correspondências (produto, unidade, nível) num jsonb — sem tabelas
  -- temporárias (função STABLE).
  SELECT COALESCE(jsonb_agg(jsonb_build_object('product_id', mm.product_id, 'uom_id', mm.uom_id,
                                               'matched_by', mm.matched_by, 'lvl', mm.lvl,
                                               'code_id', mm.code_id)), '[]'::jsonb)  -- NOVO (códigos): code_id
  INTO v_matches
  FROM (
  -- 1 código de barras
  SELECT p.id AS product_id, NULL::uuid AS uom_id, 'barcode'::text AS matched_by, 1 AS lvl, NULL::uuid AS code_id
  FROM public.products p
  WHERE p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND public.fn_product_code_key(p.barcode) = v_key  -- NOVO (códigos): chave normalizada (GTIN)
  UNION
  -- 1b NOVO (códigos): código de barras aprendido (unidade do código)
  SELECT pc.product_id, pc.uom_id, 'barcode', 1, pc.id
  FROM public.product_codes pc
  JOIN public.products p ON p.id = pc.product_id
  WHERE pc.organization_id = v_org AND pc.kind = 'barcode' AND pc.deleted_at IS NULL
    AND pc.code_key = v_key
    AND p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
  UNION
  -- 2a referência do fornecedor nas linhas em aberto
  SELECT poi.product_id, poi.uom_id, 'supplier_sku', 2, NULL::uuid
  FROM public.purchase_order_items poi
  JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
  JOIN public.products p ON p.id = poi.product_id
  WHERE po.organization_id = v_org AND po.deleted_at IS NULL
    AND po.status IN ('pending', 'ordered', 'partially_received')
    AND poi.item_type = 'product' AND poi.quantity > poi.received_quantity
    AND (p_supplier_id IS NULL OR po.supplier_id = p_supplier_id)
    AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND lower(btrim(poi.supplier_sku)) = v_lc
  UNION
  -- 2b referência do fornecedor na ficha do produto (item_suppliers)
  SELECT i.product_id, i.uom_id, 'supplier_sku', 2, NULL::uuid
  FROM public.item_suppliers i
  JOIN public.products p ON p.id = i.product_id
  WHERE i.organization_id = v_org AND i.deleted_at IS NULL AND i.product_id IS NOT NULL
    AND (p_supplier_id IS NULL OR i.supplier_id = p_supplier_id)
    AND p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND lower(btrim(i.supplier_sku)) = v_lc
  UNION
  -- 2c NOVO (códigos): referência do fornecedor aprendida (filtrada pelo
  -- fornecedor quando há; unidade do código)
  SELECT pc.product_id, pc.uom_id, 'supplier_sku', 2, pc.id
  FROM public.product_codes pc
  JOIN public.products p ON p.id = pc.product_id
  WHERE pc.organization_id = v_org AND pc.kind = 'supplier_ref' AND pc.deleted_at IS NULL
    AND pc.code_key = v_key
    AND (p_supplier_id IS NULL OR pc.supplier_id = p_supplier_id)
    AND p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
  UNION
  -- 3 SKU do produto
  SELECT p.id, NULL::uuid, 'sku', 3, NULL::uuid
  FROM public.products p
  WHERE p.organization_id = v_org AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND lower(btrim(p.sku)) = v_lc
  UNION
  -- 4 SKU gravado nas linhas das POs da organização
  SELECT poi.product_id, NULL::uuid, 'po_line_sku', 4, NULL::uuid
  FROM public.purchase_order_items poi
  JOIN public.purchase_orders po ON po.id = poi.purchase_order_id
  JOIN public.products p ON p.id = poi.product_id
  WHERE po.organization_id = v_org AND po.deleted_at IS NULL
    AND poi.item_type = 'product'
    AND (p_supplier_id IS NULL OR po.supplier_id = p_supplier_id)
    AND p.deleted_at IS NULL AND NOT p.is_deleted
    AND lower(btrim(poi.sku)) = v_lc
  ) mm;

  SELECT min(m.lvl) INTO v_level
  FROM jsonb_to_recordset(v_matches) AS m(product_id uuid, uom_id uuid, matched_by text, lvl integer);

  IF v_level IS NULL THEN
    RETURN jsonb_build_object(
      'found', false, 'code', v_code, 'organization_id', v_org,
      'warehouse_id', p_warehouse_id, 'supplier_id', p_supplier_id,
      'can_receive', v_can_receive, 'candidates', '[]'::jsonb,
      'warnings', jsonb_build_array(format('Código «%s» não encontrado nesta organização', v_code))
    ) || v_note_info  -- NOVO (guia): '{}' sem guia
     || CASE WHEN v_conv THEN jsonb_build_object('unit_conversion', true) ELSE '{}'::jsonb END;  -- NOVO (códigos)
  END IF;

  -- Níveis inferiores com outros produtos: só aviso.
  SELECT count(DISTINCT m.product_id),
         string_agg(DISTINCT format('%s (%s)', p.name, m.matched_by), ', ')
  INTO v_other, v_other_txt
  FROM jsonb_to_recordset(v_matches) AS m(product_id uuid, uom_id uuid, matched_by text, lvl integer)
  JOIN public.products p ON p.id = m.product_id
  WHERE m.lvl > v_level
    AND m.product_id NOT IN (
      SELECT m2.product_id
      FROM jsonb_to_recordset(v_matches) AS m2(product_id uuid, uom_id uuid, matched_by text, lvl integer)
      WHERE m2.lvl = v_level);
  IF v_other > 0 THEN
    v_warnings := v_warnings || to_jsonb(format('O código também corresponde a: %s', v_other_txt));
  END IF;

  FOR v_cand IN
    SELECT DISTINCT ON (m.product_id, COALESCE(m.uom_id, p.uom_id))
           m.product_id, m.matched_by,
           -- unidade lida: a da ligação/linha; senão a do produto
           CASE WHEN m.uom_id IS NULL OR m.uom_id IS NOT DISTINCT FROM p.uom_id THEN p.uom_id ELSE m.uom_id END AS uom_id,
           (m.uom_id IS NOT NULL AND m.uom_id IS DISTINCT FROM p.uom_id) AS is_pack,
           p.name, p.sku, p.barcode, m.code_id  -- NOVO (códigos)
    FROM jsonb_to_recordset(v_matches) AS m(product_id uuid, uom_id uuid, matched_by text, lvl integer, code_id uuid)
    JOIN public.products p ON p.id = m.product_id
    WHERE m.lvl = v_level
    ORDER BY m.product_id, COALESCE(m.uom_id, p.uom_id), p.name, m.code_id NULLS FIRST  -- NOVO (códigos)
  LOOP
    v_factor := 1;
    IF v_cand.is_pack THEN
      BEGIN
        v_factor := public.fn_uom_units_per(v_cand.uom_id, v_cand.product_id);
      EXCEPTION WHEN OTHERS THEN
        v_warnings := v_warnings || to_jsonb(format('«%s»: a unidade da referência do fornecedor não é compatível com a do produto (%s)', v_cand.name, SQLERRM));
        CONTINUE;
      END;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'purchase_order_id',      o.purchase_order_id,
             'order_number',           o.order_number,
             'po_status',              o.po_status,
             'confirmed',              o.confirmed,
             'supplier_id',            o.supplier_id,
             'supplier_name',          o.supplier_name,
             'expected_delivery',      o.expected_delivery,
             'purchase_order_item_id', o.purchase_order_item_id,
             'description',            o.description,
             'quantity',               o.quantity,
             'received_quantity',      o.received_quantity,
             'open_quantity',          o.open_quantity,
             'uom_id',                 o.uom_id,
             'units_per_uom',          o.units_per_uom,
             'same_unit',              (o.units_per_uom = v_factor),
             'contract_id',            o.contract_id,
             'contract_order_number',  o.contract_order_number,
             'contract_active',        o.contract_active,
             -- Posição na ordem de enchimento (só linhas da mesma unidade).
             -- NOVO (códigos): com conversão todas as linhas entram na ordem.
             'allocation_rank',        CASE WHEN v_conv OR o.units_per_uom = v_factor THEN o.r END
           -- NOVO (guia): linha indicada na guia (só com guia)
           ) || CASE WHEN p_delivery_note_id IS NOT NULL
                     THEN jsonb_build_object('in_delivery_note', COALESCE(o.purchase_order_item_id = ANY (v_note_poi), false))
                     ELSE '{}'::jsonb END
           -- NOVO (códigos): em aberto em unidades de stock (só com conversão)
           || CASE WHEN v_conv THEN jsonb_build_object('open_units', o.open_quantity * o.units_per_uom)
                   ELSE '{}'::jsonb END
           ORDER BY (v_conv OR o.units_per_uom = v_factor) DESC, o.prio, o.allocation_rank), '[]'::jsonb),
           count(*) FILTER (WHERE NOT v_conv AND o.units_per_uom <> v_factor)
    INTO v_lines, v_other
    FROM (
      -- NOVO (guia): prio 0 = linha indicada na guia (sem guia é sempre 1);
      -- só POs do âmbito da guia.
      SELECT ol.*, pr.prio,
             row_number() OVER (PARTITION BY (v_conv OR ol.units_per_uom = v_factor) ORDER BY pr.prio, ol.allocation_rank) AS r
      FROM public.fn_receiving_open_lines(v_org, ARRAY[v_cand.product_id], p_supplier_id) ol
      CROSS JOIN LATERAL (SELECT CASE WHEN ol.purchase_order_item_id = ANY (v_note_poi) THEN 0 ELSE 1 END AS prio) pr
      WHERE v_scope IS NULL OR ol.purchase_order_id = ANY (v_scope)
    ) o;

    IF jsonb_array_length(v_lines) = 0 THEN
      v_warnings := v_warnings || to_jsonb(format('«%s» não tem encomendas a fornecedor em aberto%s', v_cand.name,
                      CASE WHEN p_supplier_id IS NOT NULL THEN ' deste fornecedor' ELSE '' END)
                      -- NOVO (guia)
                      || CASE WHEN v_scope IS NOT NULL THEN format(' nas encomendas da guia %s', v_note_number) ELSE '' END);
    ELSIF v_other > 0 THEN
      v_warnings := v_warnings || to_jsonb(format('«%s»: %s linha(s) em aberto noutra unidade — não entram numa leitura nesta unidade', v_cand.name, v_other));
    END IF;

    -- NOVO (guia): anunciado / recebido pela guia (unidades de stock).
    IF p_delivery_note_id IS NOT NULL THEN
      SELECT COALESCE(sum(l.quantity * l.units_per_uom), 0) INTO v_ann
      FROM public.supplier_delivery_note_lines l
      WHERE l.delivery_note_id = p_delivery_note_id AND l.product_id = v_cand.product_id;
      SELECT COALESCE(sum(pr.quantity * pr.units_per_uom), 0) INTO v_rcv
      FROM public.purchase_order_receipts pr
      WHERE pr.delivery_note_id = p_delivery_note_id AND pr.product_id = v_cand.product_id
        AND pr.kind = 'receipt' AND pr.reverted_at IS NULL;
      IF v_note_has_lines AND v_ann = 0 THEN
        v_warnings := v_warnings || to_jsonb(format('«%s» não consta da guia %s', v_cand.name, v_note_number));
      END IF;
    END IF;

    v_candidates := v_candidates || (jsonb_build_object(
      'product_id',    v_cand.product_id,
      'name',          v_cand.name,
      'sku',           v_cand.sku,
      'barcode',       v_cand.barcode,
      'matched_by',    v_cand.matched_by,
      'uom_id',        v_cand.uom_id,
      'uom_code',      (SELECT code FROM public.uom WHERE id = v_cand.uom_id),
      'units_per_uom', v_factor,
      'open_lines',    v_lines
    ) || CASE WHEN v_cand.code_id IS NOT NULL  -- NOVO (códigos)
              THEN jsonb_build_object('learned_code_id', v_cand.code_id) ELSE '{}'::jsonb END
      || CASE WHEN p_delivery_note_id IS NOT NULL  -- NOVO (guia)
              THEN jsonb_build_object('delivery_note', jsonb_build_object(
                     'announced', v_ann > 0, 'announced_units', trim_scale(v_ann), 'received_units', trim_scale(v_rcv)))
              ELSE '{}'::jsonb END);
  END LOOP;

  RETURN jsonb_build_object(
    'found',           jsonb_array_length(v_candidates) > 0,
    'code',            v_code,
    'organization_id', v_org,
    'warehouse_id',    p_warehouse_id,
    'supplier_id',     p_supplier_id,
    'can_receive',     v_can_receive,
    'candidates',      v_candidates,
    'warnings',        v_warnings
  ) || v_note_info  -- NOVO (guia): '{}' sem guia
     || CASE WHEN v_conv THEN jsonb_build_object('unit_conversion', true) ELSE '{}'::jsonb END;  -- NOVO (códigos)
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_receiving_lookup(p_warehouse_id uuid, p_code text, p_supplier_id uuid, p_delivery_note_id uuid, p_unit_conversion boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_receiving_lookup(p_warehouse_id uuid, p_code text, p_supplier_id uuid, p_delivery_note_id uuid, p_unit_conversion boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_receiving_lookup(p_warehouse_id uuid, p_code text, p_supplier_id uuid, p_delivery_note_id uuid, p_unit_conversion boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_set_quote_morada_entrega(p_quote_id uuid, p_address_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_quote  public.quotes;
  v_entity uuid;
  v_texto  text;
BEGIN
  IF p_quote_id IS NULL THEN
    RAISE EXCEPTION 'quote_id é obrigatório' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_quote FROM public.quotes q WHERE q.id = p_quote_id FOR UPDATE;
  IF NOT FOUND OR v_quote.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Orçamento não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_uid IS NULL
     OR v_quote.organization_id IS NULL
     OR v_quote.organization_id NOT IN (SELECT public.get_user_crm_org_ids(v_uid))
     OR NOT public.has_anew_permission(v_uid, 'quotes.edit')
     OR NOT EXISTS (
       SELECT 1 FROM unnest((SELECT public.crm_scope_keys('quotes.view'::text))) AS k(scope_key)
       WHERE k.scope_key = v_quote.organization_id::text || ':*'
          OR k.scope_key = v_quote.organization_id::text || ':' || v_quote.assigned_to::text
          OR k.scope_key = v_quote.organization_id::text || ':' || v_quote.created_by::text
     ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar este orçamento' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_address_id IS NULL THEN
    UPDATE public.quotes
       SET site_address_id = NULL,
           obra_endereco   = NULL
     WHERE id = p_quote_id;
    RETURN jsonb_build_object('quote_id', p_quote_id, 'site_address_id', NULL, 'obra_endereco', NULL);
  END IF;

  v_entity := COALESCE(
    v_quote.entity_id,
    (SELECT c.entity_id FROM public.anew_clients c WHERE c.id = v_quote.cliente_id),
    (SELECT d.entity_id FROM public.deals d WHERE d.id = v_quote.deal_id)
  );

  IF p_address_id IS DISTINCT FROM v_quote.site_address_id THEN
    IF v_entity IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.anew_entity_addresses ea
      WHERE ea.entity_id = v_entity
        AND ea.address_id = p_address_id
        AND ea.address_type = 'delivery'
        AND (ea.valid_to IS NULL OR ea.valid_to > now())
    ) THEN
      RAISE EXCEPTION 'A morada de entrega não pertence ao cliente deste orçamento' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  v_texto := left(public.fn_quote_morada_texto(p_address_id), 500);

  UPDATE public.quotes
     SET site_address_id = p_address_id,
         obra_endereco   = v_texto
   WHERE id = p_quote_id;

  RETURN jsonb_build_object('quote_id', p_quote_id, 'site_address_id', p_address_id, 'obra_endereco', v_texto);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_set_quote_morada_entrega(p_quote_id uuid, p_address_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_set_quote_morada_entrega(p_quote_id uuid, p_address_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_set_quote_morada_entrega(p_quote_id uuid, p_address_id uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_set_quote_morada_entrega(p_quote_id uuid, p_address_id uuid) IS 'Grava a morada de entrega de um orçamento: site_address_id (anew_addresses) e obra_endereco (texto formatado com andar e fração). A morada tem de ser uma morada de entrega ativa da entidade do orçamento. NULL limpa as duas.';

CREATE OR REPLACE FUNCTION public.rpc_supplier_catalog_list(p_supplier_id uuid, p_filter text DEFAULT 'all'::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_include_inactive boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org     uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  v_uid     uuid := auth.uid();
  v_pricing boolean;
  v_filter  text := lower(COALESCE(NULLIF(btrim(p_filter), ''), 'all'));
  v_limit   integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_offset  integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_q       text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_like    text;
  l         public.supplier_account_links;
  v_counts  jsonb;
  v_total   integer;
  v_items   jsonb;
BEGIN
  IF v_filter NOT IN ('all', 'linked', 'unlinked', 'dismissed') THEN
    RAISE EXCEPTION 'Filtro inválido (all, linked, unlinked, dismissed)' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  v_pricing := public.has_anew_permission(v_uid, 'suppliers.view_pricing')
            OR public.has_anew_permission(v_uid, 'products.view_cost');

  SELECT * INTO l FROM public.supplier_account_links WHERE supplier_id = p_supplier_id AND status = 'active';
  IF l.id IS NULL THEN
    RETURN jsonb_build_object('linked_account', false, 'counts', jsonb_build_object('all', 0, 'linked', 0, 'unlinked', 0, 'dismissed', 0),
                              'total', 0, 'limit', v_limit, 'offset', v_offset, 'items', '[]'::jsonb,
                              'can_link', false, 'can_view_pricing', v_pricing,
                              'can_manage_prices', public.has_anew_permission(v_uid, 'products.manage_prices'));
  END IF;

  IF v_q IS NOT NULL THEN
    v_like := '%' || replace(replace(replace(left(v_q, 100), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  WITH f AS (
    SELECT ci.id, ci.supplier_ref,
           EXISTS (SELECT 1 FROM public.item_suppliers isup
                   WHERE isup.supplier_id = p_supplier_id AND isup.catalog_item_id = ci.id AND isup.deleted_at IS NULL) AS is_linked,
           EXISTS (SELECT 1 FROM public.supplier_catalog_dismissals d WHERE d.link_id = l.id AND d.catalog_item_id = ci.id) AS is_dismissed
    FROM public.supplier_catalog_items ci
    WHERE ci.supplier_account_id = l.supplier_account_id
      AND (COALESCE(p_include_inactive, false) OR ci.is_active)
      AND (v_like IS NULL OR ci.supplier_ref ILIKE v_like OR ci.name ILIKE v_like
           OR ci.barcode ILIKE v_like OR ci.brand ILIKE v_like)
  ),
  fx AS (
    SELECT f.*,
           (v_filter = 'all'
            OR (v_filter = 'linked' AND f.is_linked)
            OR (v_filter = 'unlinked' AND NOT f.is_linked AND NOT f.is_dismissed)
            OR (v_filter = 'dismissed' AND f.is_dismissed AND NOT f.is_linked)) AS in_filter
    FROM f
  ),
  page AS (
    SELECT fx.id, fx.is_linked, fx.is_dismissed
    FROM fx WHERE fx.in_filter
    ORDER BY fx.supplier_ref, fx.id
    LIMIT v_limit OFFSET v_offset
  )
  SELECT
    (SELECT jsonb_build_object(
              'all', count(*),
              'linked', count(*) FILTER (WHERE is_linked),
              'unlinked', count(*) FILTER (WHERE NOT is_linked AND NOT is_dismissed),
              'dismissed', count(*) FILTER (WHERE is_dismissed AND NOT is_linked))
       FROM fx),
    (SELECT count(*) FROM fx WHERE in_filter),
    (SELECT COALESCE(jsonb_agg(
           public.fn_sp_catalog_item_json(ci, v_pricing)
           || jsonb_build_object(
                'is_linked', f.is_linked,
                'is_dismissed', f.is_dismissed,
                'links', COALESCE((
                  SELECT jsonb_agg(jsonb_build_object(
                           'item_supplier_id', isup.id,
                           'product_id', p.id,
                           'product_name', p.name,
                           'product_sku', p.sku,
                           'uom_id', isup.uom_id,
                           'supplier_sku', isup.supplier_sku,
                           'purchase_price', CASE WHEN v_pricing THEN isup.purchase_price END,
                           'currency', isup.currency,
                           'is_preferred', isup.is_preferred) ORDER BY p.name)
                  FROM public.item_suppliers isup
                  JOIN public.products p ON p.id = isup.product_id
                  WHERE isup.supplier_id = p_supplier_id AND isup.catalog_item_id = ci.id AND isup.deleted_at IS NULL
                ), '[]'::jsonb))
           ORDER BY ci.supplier_ref, ci.id), '[]'::jsonb)
       FROM page f
       JOIN public.supplier_catalog_items ci ON ci.id = f.id)
  INTO v_counts, v_total, v_items;

  RETURN jsonb_build_object(
    'linked_account', true,
    'counts', v_counts,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'items', v_items,
    'can_link', public.has_anew_permission(v_uid, 'products.edit'),
    'can_view_pricing', v_pricing,
    'can_manage_prices', public.has_anew_permission(v_uid, 'products.manage_prices')
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_catalog_list(p_supplier_id uuid, p_filter text, p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_catalog_list(p_supplier_id uuid, p_filter text, p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_catalog_list(p_supplier_id uuid, p_filter text, p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_supplier_portal_invite_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_email text, p_name text DEFAULT NULL::text, p_check_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller   uuid;
  v_email    text := lower(btrim(COALESCE(p_email, '')));
  v_name     text := NULLIF(left(btrim(regexp_replace(COALESCE(p_name, ''), '[\x01-\x1F\x7F]', '', 'g')), 200), '');
  s          record;
  v_key      text;
  v_auth     uuid;
  v_anew     public.anew_users;
  v_kind     text;
  a          public.supplier_accounts;
  l          public.supplier_account_links;
  pu         public.supplier_portal_users;
  v_new_user boolean := false;
  v_may_temp boolean := false;
  v_org_name text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Só disponível para o servidor' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  SELECT u.id INTO v_caller FROM public.anew_users u
  WHERE u.auth_user_id = p_caller_auth_uid AND u.status = 'active' AND u.deleted_at IS NULL;
  IF v_caller IS NULL
     OR p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.get_user_visible_org_ids(p_caller_auth_uid))
     OR NOT public.has_anew_permission(p_caller_auth_uid, 'suppliers.portal_manage') THEN
    RAISE EXCEPTION 'Sem permissão para gerir o acesso dos fornecedores ao portal'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  SELECT id, name, tax_id, vat_number, organization_id, primary_contact_name INTO s
  FROM public.suppliers
  WHERE id = p_supplier_id AND organization_id = p_organization_id AND deleted_at IS NULL
  FOR UPDATE;
  IF s.id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  v_key := public.fn_nif_key(COALESCE(NULLIF(btrim(s.tax_id), ''), NULLIF(btrim(s.vat_number), '')));
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'O NIF do fornecedor é inválido ou está vazio. Para fornecedores estrangeiros use o prefixo do país (ex.: ESB12345678).'
      USING ERRCODE = 'check_violation', HINT = 'invalid_nif';
  END IF;

  IF v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR char_length(v_email) > 320 THEN
    RAISE EXCEPTION 'Email inválido' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  SELECT id INTO v_auth FROM auth.users WHERE lower(email) = v_email ORDER BY created_at LIMIT 1;

  -- Perfil do CRM/portal do cliente com este email que não é desta conta Auth
  -- (ou não tem conta) → recusado.
  IF EXISTS (SELECT 1 FROM public.anew_users
             WHERE lower(email) = v_email AND auth_user_id IS DISTINCT FROM v_auth) THEN
    RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
      USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
  END IF;

  IF v_auth IS NOT NULL THEN
    SELECT * INTO v_anew FROM public.anew_users WHERE auth_user_id = v_auth;
    IF v_anew.id IS NOT NULL THEN
      -- (i) interna → recusada. (ii) só-cliente → aceite ('client_existing').
      -- Só-cliente: perfil ativo, ≥ 1 membership ativa e todas de cliente,
      -- acesso dado ao portal do cliente, email confirmado. Zero memberships
      -- ativas = registo próprio / onboarding do CRM → interna.
      IF v_anew.status <> 'active' OR v_anew.deleted_at IS NOT NULL
         OR EXISTS (SELECT 1 FROM public.anew_memberships m
                    WHERE m.user_id = v_anew.id AND m.status = 'active' AND m.role_is_client IS NOT TRUE)
         OR NOT EXISTS (SELECT 1 FROM public.anew_memberships m
                        WHERE m.user_id = v_anew.id AND m.status = 'active' AND m.role_is_client IS TRUE)
         OR NOT EXISTS (SELECT 1 FROM public.client_portal_users c WHERE c.auth_user_id = v_auth)
         OR NOT EXISTS (SELECT 1 FROM auth.users au WHERE au.id = v_auth AND au.email_confirmed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
          USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
      END IF;
      v_kind := 'client_existing';
    ELSE
      -- (iii) sem perfil: acesso ao portal do cliente sem perfil é um estado
      -- inválido (legado) → recusado, como antes.
      IF EXISTS (SELECT 1 FROM public.client_portal_users WHERE auth_user_id = v_auth) THEN
        RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
          USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
      END IF;
      v_kind := 'supplier';
    END IF;

    -- Já é utilizador do portal de OUTRO fornecedor (ou suspenso) → recusado.
    IF EXISTS (SELECT 1 FROM public.supplier_portal_users x
               JOIN public.supplier_accounts xa ON xa.id = x.supplier_account_id
               WHERE x.auth_user_id = v_auth AND (xa.nif_key <> v_key OR x.status <> 'active')) THEN
      RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
        USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
    END IF;
  END IF;

  -- F3.1 (convite seguro): uma conta Auth SEM perfil que ainda NÃO é
  -- utilizador do portal só é aproveitada se foi criada pelo servidor para o
  -- portal do fornecedor (app_metadata.supplier_portal = true — o utilizador
  -- não altera app_metadata) e nunca iniciou sessão. Fecha o caso de uma
  -- conta registada por terceiros com o mesmo email (e
  -- user_metadata.admin_created='true', que faz handle_new_user saltá-la)
  -- ser ligada ao fornecedor. Contas já ligadas (têm supplier_portal_users)
  -- não passam por aqui — podem já ter iniciado sessão com a password
  -- temporária. Contas 'client_existing' foram verificadas acima.
  IF v_kind = 'supplier'
     AND NOT EXISTS (SELECT 1 FROM public.supplier_portal_users x WHERE x.auth_user_id = v_auth)
     AND EXISTS (SELECT 1 FROM auth.users au
                 WHERE au.id = v_auth
                   AND (au.raw_app_meta_data->>'supplier_portal' IS DISTINCT FROM 'true'
                        OR au.last_sign_in_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'Este email não pode ser usado no portal do fornecedor. Indique outro email.'
      USING ERRCODE = 'check_violation', HINT = 'email_not_allowed';
  END IF;

  IF EXISTS (SELECT 1 FROM public.supplier_accounts WHERE nif_key = v_key AND status <> 'active') THEN
    RAISE EXCEPTION 'Não foi possível enviar o convite para este fornecedor. Contacte o suporte.'
      USING ERRCODE = 'check_violation', HINT = 'account_unavailable';
  END IF;

  -- Já ligado a outra conta (NIF mudou fora do gatilho)? Pede para desligar.
  IF EXISTS (SELECT 1 FROM public.supplier_account_links sl JOIN public.supplier_accounts sa ON sa.id = sl.supplier_account_id
             WHERE sl.supplier_id = s.id AND sl.status = 'active' AND sa.nif_key <> v_key) THEN
    RAISE EXCEPTION 'Este fornecedor está ligado ao portal com outro NIF. Desligue o portal e volte a convidar.'
      USING ERRCODE = 'check_violation', HINT = 'conflict';
  END IF;

  IF COALESCE(p_check_only, false) THEN
    RETURN jsonb_build_object('ok', true, 'auth_user_exists', v_auth IS NOT NULL, 'account_kind', v_kind);
  END IF;

  IF v_auth IS NULL THEN
    RAISE EXCEPTION 'A conta de acesso ainda não existe' USING ERRCODE = 'no_data_found', HINT = 'auth_user_missing';
  END IF;

  PERFORM set_config('app.audit_user_id', v_caller::text, true);
  PERFORM set_config('app.audit_source', 'supplier_portal_invite', true);
  PERFORM pg_advisory_xact_lock(hashtextextended('supplier_account:' || v_key, 0));

  -- Conta
  INSERT INTO public.supplier_accounts (nif_key, display_name, created_by_org_id)
  VALUES (v_key, left(btrim(s.name), 200), p_organization_id)
  ON CONFLICT (nif_key) DO NOTHING;
  SELECT * INTO a FROM public.supplier_accounts WHERE nif_key = v_key FOR UPDATE;

  -- Ligação
  SELECT * INTO l FROM public.supplier_account_links
  WHERE supplier_id = s.id AND supplier_account_id = a.id FOR UPDATE;
  IF l.id IS NULL THEN
    INSERT INTO public.supplier_account_links (supplier_account_id, organization_id, supplier_id, invited_by)
    VALUES (a.id, p_organization_id, s.id, v_caller)
    RETURNING * INTO l;
  ELSIF l.status <> 'active' THEN
    UPDATE public.supplier_account_links
       SET status = 'active', revoked_at = NULL, revoked_by = NULL, invited_by = v_caller,
           organization_id = p_organization_id, updated_at = now()
     WHERE id = l.id
    RETURNING * INTO l;
  END IF;

  -- Utilizador do portal
  SELECT * INTO pu FROM public.supplier_portal_users WHERE auth_user_id = v_auth FOR UPDATE;
  IF pu.id IS NULL THEN
    -- Cliente existente: já tem password própria (a do portal do cliente)
    -- → marcada como definida (sem modal de 1.º acesso no portal do
    -- fornecedor).
    -- O gatilho trg_supplier_portal_users_00_block_internal volta a verificar
    -- (sob lock) que a conta não é interna.
    INSERT INTO public.supplier_portal_users (supplier_account_id, auth_user_id, email, name, role, created_by_org_id, invited_by,
                                              first_login, password_changed_at)
    VALUES (a.id, v_auth, v_email, COALESCE(v_name, NULLIF(btrim(s.primary_contact_name), ''), left(btrim(s.name), 200)),
            CASE WHEN EXISTS (SELECT 1 FROM public.supplier_portal_users
                              WHERE supplier_account_id = a.id AND role = 'owner' AND status = 'active')
                 THEN 'member' ELSE 'owner' END,
            p_organization_id, v_caller,
            v_kind IS DISTINCT FROM 'client_existing',
            CASE WHEN v_kind = 'client_existing' THEN now() END)
    RETURNING * INTO pu;
    v_new_user := true;
  END IF;

  -- Password temporária só numa conta de fornecedor criada para o convite,
  -- ligada agora, que nunca iniciou sessão.
  v_may_temp := v_new_user AND v_kind = 'supplier'
                AND EXISTS (SELECT 1 FROM auth.users au
                            WHERE au.id = v_auth
                              AND au.raw_app_meta_data->>'supplier_portal' = 'true'
                              AND au.last_sign_in_at IS NULL);

  -- Acesso desta empresa
  INSERT INTO public.supplier_portal_user_access AS x (portal_user_id, link_id, organization_id, granted_by)
  VALUES (pu.id, l.id, p_organization_id, v_caller)
  ON CONFLICT (portal_user_id, link_id) DO UPDATE
    SET revoked_at = NULL, revoked_by = NULL, granted_by = EXCLUDED.granted_by, granted_at = now(),
        organization_id = EXCLUDED.organization_id
    WHERE x.revoked_at IS NOT NULL;

  SELECT name INTO v_org_name FROM public.anew_organizations WHERE id = p_organization_id;

  RETURN jsonb_build_object(
    'ok', true,
    'portal_user_id', pu.id,
    'link_id', l.id,
    'auth_user_id', v_auth,
    'email', pu.email,
    'user_name', pu.name,
    'is_new_user', v_new_user,
    'password_set', pu.password_changed_at IS NOT NULL,
    'account_kind', v_kind,
    'may_set_temp_password', v_may_temp,
    'organization_name', v_org_name,
    'supplier_name', s.name
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_portal_invite_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_email text, p_name text, p_check_only boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_invite_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_email text, p_name text, p_check_only boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_supplier_portal_profile_status(p_organization_id uuid)
 RETURNS TABLE(supplier_id uuid, portal_status text, awaiting_profile boolean, account_status text, catalog_unlinked integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid         uuid := auth.uid();
  v_can_catalog boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Utilizador não autenticado' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id é obrigatório' USING ERRCODE = 'check_violation';
  END IF;

  IF p_organization_id NOT IN (SELECT public.get_user_visible_org_ids(v_uid))
     OR NOT COALESCE(public.has_anew_permission(v_uid, 'suppliers.view'), false) THEN
    RAISE EXCEPTION 'Sem permissão para ver os fornecedores desta organização' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Mesma condição de rpc_inventory_today.catalog_unlinked
  -- (fn_sp_crm_supplier_org exige perfil do CRM).
  v_can_catalog := public.current_business_user_id() IS NOT NULL;

  RETURN QUERY
  WITH s AS (
    SELECT sp.id AS s_id
    FROM public.suppliers sp
    WHERE sp.organization_id = p_organization_id
      AND sp.deleted_at IS NULL
  ),
  al AS (
    -- Ligação ativa (no máximo uma por fornecedor).
    SELECT l.id                  AS al_link_id,
           l.supplier_id         AS al_supplier_id,
           l.supplier_account_id AS al_account_id,
           l.organization_id     AS al_org_id,
           a.status              AS al_account_status
    FROM public.supplier_account_links l
    JOIN s ON s.s_id = l.supplier_id
    LEFT JOIN public.supplier_accounts a ON a.id = l.supplier_account_id
    WHERE l.status = 'active'
  ),
  anyl AS (
    SELECT DISTINCT l.supplier_id AS any_supplier_id
    FROM public.supplier_account_links l
    JOIN s ON s.s_id = l.supplier_id
  ),
  aw AS (
    -- Regra de rpc_inventory_today.suppliers.awaiting_profile.
    SELECT al.al_supplier_id AS aw_supplier_id,
           (al.al_org_id = p_organization_id
            AND al.al_account_status = 'active'
            AND NOT EXISTS (
              SELECT 1 FROM public.supplier_portal_users u
               WHERE u.supplier_account_id = al.al_account_id
                 AND u.role = 'owner'
                 AND u.status = 'active'
                 AND u.profile_confirmed_at IS NOT NULL
            )) AS aw_awaiting
    FROM al
  ),
  cat AS (
    -- Fila "por ligar" de rpc_supplier_catalog_list (counts.unlinked).
    SELECT al.al_supplier_id AS cat_supplier_id, count(*)::integer AS cat_unlinked
    FROM al
    JOIN public.supplier_catalog_items ci
      ON ci.supplier_account_id = al.al_account_id AND ci.is_active
    WHERE v_can_catalog
      AND NOT EXISTS (SELECT 1 FROM public.item_suppliers isup
                       WHERE isup.supplier_id = al.al_supplier_id
                         AND isup.catalog_item_id = ci.id
                         AND isup.deleted_at IS NULL)
      AND NOT EXISTS (SELECT 1 FROM public.supplier_catalog_dismissals d
                       WHERE d.link_id = al.al_link_id
                         AND d.catalog_item_id = ci.id)
    GROUP BY al.al_supplier_id
  )
  SELECT
    s.s_id,
    CASE
      WHEN al.al_link_id IS NOT NULL AND COALESCE(aw.aw_awaiting, false) THEN 'invited_awaiting'
      WHEN al.al_link_id IS NOT NULL THEN 'active'
      WHEN anyl.any_supplier_id IS NOT NULL THEN 'revoked'
      ELSE 'none'
    END::text,
    COALESCE(aw.aw_awaiting, false),
    al.al_account_status::text,
    CASE WHEN v_can_catalog THEN COALESCE(cat.cat_unlinked, 0) END
  FROM s
  LEFT JOIN al   ON al.al_supplier_id = s.s_id
  LEFT JOIN aw   ON aw.aw_supplier_id = s.s_id
  LEFT JOIN anyl ON anyl.any_supplier_id = s.s_id
  LEFT JOIN cat  ON cat.cat_supplier_id = s.s_id;
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_portal_profile_status(p_organization_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_profile_status(p_organization_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_profile_status(p_organization_id uuid) TO service_role;
COMMENT ON FUNCTION public.rpc_supplier_portal_profile_status(p_organization_id uuid) IS 'Estado do Portal do Fornecedor por fornecedor (não apagado) da organização: portal_status (invited_awaiting|active|revoked|none), awaiting_profile (regra de rpc_inventory_today), account_status da conta ligada e catalog_unlinked (fila por ligar de rpc_supplier_catalog_list; null sem perfil do CRM). Exige org visível e suppliers.view. Só leitura.';

CREATE OR REPLACE FUNCTION public.rpc_supplier_portal_resend_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_portal_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller   uuid;
  r          record;
  v_org_name text;
  v_kind     text;
  v_may_temp boolean;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Só disponível para o servidor' USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  SELECT u.id INTO v_caller FROM public.anew_users u
  WHERE u.auth_user_id = p_caller_auth_uid AND u.status = 'active' AND u.deleted_at IS NULL;
  IF v_caller IS NULL
     OR p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.get_user_visible_org_ids(p_caller_auth_uid))
     OR NOT public.has_anew_permission(p_caller_auth_uid, 'suppliers.portal_manage') THEN
    RAISE EXCEPTION 'Sem permissão para gerir o acesso dos fornecedores ao portal'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_permission';
  END IF;

  SELECT pu.id, pu.email, pu.name, pu.auth_user_id, pu.password_changed_at, s.name AS supplier_name
  INTO r
  FROM public.supplier_portal_user_access x
  JOIN public.supplier_account_links l ON l.id = x.link_id
  JOIN public.supplier_portal_users pu ON pu.id = x.portal_user_id
  JOIN public.supplier_accounts a ON a.id = l.supplier_account_id
  JOIN public.suppliers s ON s.id = l.supplier_id
  WHERE l.supplier_id = p_supplier_id AND l.organization_id = p_organization_id
    AND l.status = 'active' AND x.revoked_at IS NULL AND x.portal_user_id = p_portal_user_id
    AND pu.status = 'active' AND a.status = 'active' AND s.deleted_at IS NULL;
  IF r.id IS NULL THEN
    RAISE EXCEPTION 'Utilizador do portal não encontrado neste fornecedor' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;

  -- Conta que também é cliente (tem perfil): a password é a do portal do
  -- cliente — nunca reposta daqui.
  v_kind := CASE WHEN EXISTS (SELECT 1 FROM public.anew_users WHERE auth_user_id = r.auth_user_id)
                 THEN 'client_existing' ELSE 'supplier' END;
  -- Nova password temporária só se ainda não definiu a sua e a conta foi
  -- criada pelo convite do portal do fornecedor.
  v_may_temp := v_kind = 'supplier' AND r.password_changed_at IS NULL
                AND EXISTS (SELECT 1 FROM auth.users au
                            WHERE au.id = r.auth_user_id
                              AND au.raw_app_meta_data->>'supplier_portal' = 'true');

  SELECT name INTO v_org_name FROM public.anew_organizations WHERE id = p_organization_id;

  RETURN jsonb_build_object(
    'ok', true,
    'portal_user_id', r.id,
    'auth_user_id', r.auth_user_id,
    'email', r.email,
    'user_name', r.name,
    'password_set', r.password_changed_at IS NOT NULL,
    'account_kind', v_kind,
    'may_set_temp_password', v_may_temp,
    'organization_name', v_org_name,
    'supplier_name', r.supplier_name
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_portal_resend_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_portal_user_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_resend_prepare(p_caller_auth_uid uuid, p_organization_id uuid, p_supplier_id uuid, p_portal_user_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_supplier_portal_revoke_access(p_supplier_id uuid, p_portal_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org   uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.portal_manage');
  v_actor uuid := public.current_business_user_id();
  l       public.supplier_account_links;
  v_n     integer := 0;
BEGIN
  SELECT * INTO l FROM public.supplier_account_links
  WHERE supplier_id = p_supplier_id AND status = 'active'
  FOR UPDATE;
  IF l.id IS NULL THEN
    RAISE EXCEPTION 'Este fornecedor não tem acesso ativo ao portal' USING ERRCODE = 'no_data_found', HINT = 'not_linked';
  END IF;

  IF p_portal_user_id IS NOT NULL THEN
    UPDATE public.supplier_portal_user_access
       SET revoked_at = now(), revoked_by = v_actor
     WHERE link_id = l.id AND portal_user_id = p_portal_user_id AND revoked_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
      RAISE EXCEPTION 'Utilizador do portal não encontrado neste fornecedor' USING ERRCODE = 'no_data_found', HINT = 'not_found';
    END IF;
    RETURN jsonb_build_object('revoked_users', v_n, 'link_revoked', false);
  END IF;

  UPDATE public.supplier_portal_user_access
     SET revoked_at = now(), revoked_by = v_actor
   WHERE link_id = l.id AND revoked_at IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  UPDATE public.supplier_account_links
     SET status = 'revoked', revoked_at = now(), revoked_by = v_actor, updated_at = now()
   WHERE id = l.id;

  RETURN jsonb_build_object('revoked_users', v_n, 'link_revoked', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_portal_revoke_access(p_supplier_id uuid, p_portal_user_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_revoke_access(p_supplier_id uuid, p_portal_user_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_revoke_access(p_supplier_id uuid, p_portal_user_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_supplier_portal_status(p_supplier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org   uuid := public.fn_sp_crm_supplier_org(p_supplier_id, 'suppliers.view');
  s       record;
  l       public.supplier_account_links;
  v_key   text;
  v_users jsonb := '[]'::jsonb;
  v_items integer;
BEGIN
  SELECT id, name, tax_id, vat_number, email INTO s FROM public.suppliers WHERE id = p_supplier_id;
  v_key := public.fn_nif_key(COALESCE(NULLIF(btrim(s.tax_id), ''), NULLIF(btrim(s.vat_number), '')));

  SELECT * INTO l FROM public.supplier_account_links
  WHERE supplier_id = p_supplier_id
  ORDER BY (status = 'active') DESC, created_at DESC
  LIMIT 1;

  IF l.id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'portal_user_id', pu.id,
             'email', pu.email,
             'name', pu.name,
             'access_status', CASE WHEN x.revoked_at IS NULL AND pu.status = 'active' THEN 'active' ELSE 'revoked' END,
             'granted_at', x.granted_at,
             'revoked_at', x.revoked_at,
             'password_set', pu.password_changed_at IS NOT NULL,
             'last_login_at', pu.last_login_at
           ) ORDER BY x.granted_at), '[]'::jsonb)
    INTO v_users
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_portal_users pu ON pu.id = x.portal_user_id
    WHERE x.link_id = l.id;
  END IF;

  IF l.status = 'active' THEN
    SELECT count(*) INTO v_items FROM public.supplier_catalog_items
    WHERE supplier_account_id = l.supplier_account_id AND is_active;
  END IF;

  RETURN jsonb_build_object(
    'supplier_id', p_supplier_id,
    'nif', COALESCE(NULLIF(btrim(s.tax_id), ''), NULLIF(btrim(s.vat_number), '')),
    'nif_valid', v_key IS NOT NULL,
    'nif_key', v_key,
    'supplier_email', s.email,
    'portal_status', CASE WHEN l.id IS NULL THEN 'not_invited' WHEN l.status = 'active' THEN 'active' ELSE 'revoked' END,
    'link_id', l.id,
    'linked_at', l.created_at,
    'revoked_at', l.revoked_at,
    'users', v_users,
    'catalog_active_items', v_items,
    'can_manage', public.has_anew_permission(auth.uid(), 'suppliers.portal_manage')
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_supplier_portal_status(p_supplier_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_status(p_supplier_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_supplier_portal_status(p_supplier_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.rpc_update_entity_delivery_address(p_entity_address_id uuid, p_street text, p_number text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_floor text DEFAULT NULL::text, p_unit text DEFAULT NULL::text, p_acesso text DEFAULT NULL::text, p_impacto_percent integer DEFAULT NULL::integer, p_estacionamento text DEFAULT NULL::text, p_zona_estacionamento text DEFAULT NULL::text, p_tem_elevador boolean DEFAULT NULL::boolean, p_n_elevadores integer DEFAULT NULL::integer, p_n_andares integer DEFAULT NULL::integer, p_n_fracoes_por_andar integer DEFAULT NULL::integer, p_tipologia text DEFAULT NULL::text, p_area_util_m2 numeric DEFAULT NULL::numeric, p_n_divisoes integer DEFAULT NULL::integer, p_n_casas_banho integer DEFAULT NULL::integer, p_ano_construcao integer DEFAULT NULL::integer, p_pavimento text DEFAULT NULL::text, p_eletrica text DEFAULT NULL::text, p_quadro_diferencial boolean DEFAULT NULL::boolean, p_canalizacao text DEFAULT NULL::text, p_gas text DEFAULT NULL::text, p_amianto text DEFAULT NULL::text, p_habitada_durante_obra boolean DEFAULT NULL::boolean, p_animais boolean DEFAULT NULL::boolean, p_notas_interior text DEFAULT NULL::text, p_com_interior boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor          uuid;
  v_street         text := btrim(coalesce(p_street, ''));
  v_number         text := btrim(coalesce(p_number, ''));
  v_floor          text := nullif(btrim(coalesce(p_floor, '')), '');
  v_unit           text := nullif(btrim(coalesce(p_unit, '')), '');
  v_postal         text := btrim(coalesce(p_postal_code, ''));
  v_city           text := btrim(coalesce(p_city, ''));
  v_notas          text := nullif(btrim(coalesce(p_notas_interior, '')), '');
  v_country        text := 'PT';
  v_key            text;
  v_entity_id      uuid;
  v_type           text;
  v_valid_to       timestamptz;
  v_old_address_id uuid;
  v_old_key        text;
  v_address_id     uuid;
  v_formatted      text;
  v_com_interior   boolean;
BEGIN
  IF p_entity_address_id IS NULL THEN
    RAISE EXCEPTION 'entity_address_id é obrigatório' USING ERRCODE = 'check_violation';
  END IF;

  SELECT ea.entity_id, ea.address_type, ea.valid_to, ea.address_id
    INTO v_entity_id, v_type, v_valid_to, v_old_address_id
  FROM public.anew_entity_addresses ea
  WHERE ea.id = p_entity_address_id
  FOR UPDATE;

  IF v_entity_id IS NULL THEN
    RAISE EXCEPTION 'Morada não encontrada' USING ERRCODE = 'no_data_found';
  END IF;

  -- Permissão antes de revelar o tipo/estado da linha.
  IF NOT public.fn_entity_delivery_address_access(v_entity_id, 'edit') THEN
    RAISE EXCEPTION 'Sem permissão para alterar as moradas deste cliente' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_type IS DISTINCT FROM 'delivery' THEN
    RAISE EXCEPTION 'Só é possível editar moradas de entrega' USING ERRCODE = 'check_violation';
  END IF;

  IF v_valid_to IS NOT NULL AND v_valid_to <= now() THEN
    RAISE EXCEPTION 'Esta morada de entrega foi removida' USING ERRCODE = 'check_violation';
  END IF;

  v_actor := public.current_business_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Perfil de utilizador não encontrado' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_street = '' THEN
    RAISE EXCEPTION 'A rua é obrigatória' USING ERRCODE = 'check_violation';
  END IF;
  IF v_postal = '' THEN
    RAISE EXCEPTION 'O código postal é obrigatório' USING ERRCODE = 'check_violation';
  END IF;
  IF v_postal !~ '^[0-9]{4}-[0-9]{3}$' OR v_postal = '0000-000' THEN
    RAISE EXCEPTION 'Código postal inválido (formato 0000-000)' USING ERRCODE = 'check_violation';
  END IF;
  IF v_city = '' THEN
    RAISE EXCEPTION 'A localidade é obrigatória' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM public.fn_validar_ficha_edificio(
    v_floor, p_acesso, p_impacto_percent, p_estacionamento, p_zona_estacionamento,
    p_tem_elevador, p_n_elevadores, p_n_andares, p_n_fracoes_por_andar,
    p_tipologia, p_area_util_m2, p_n_divisoes, p_n_casas_banho, p_ano_construcao,
    p_pavimento, p_eletrica, p_canalizacao, p_gas, p_amianto, v_notas);

  v_com_interior := COALESCE(p_com_interior, false)
    OR p_tipologia IS NOT NULL OR p_area_util_m2 IS NOT NULL OR p_n_divisoes IS NOT NULL
    OR p_n_casas_banho IS NOT NULL OR p_ano_construcao IS NOT NULL OR p_pavimento IS NOT NULL
    OR p_eletrica IS NOT NULL OR p_quadro_diferencial IS NOT NULL OR p_canalizacao IS NOT NULL
    OR p_gas IS NOT NULL OR p_amianto IS NOT NULL OR p_habitada_durante_obra IS NOT NULL
    OR p_animais IS NOT NULL OR v_notas IS NOT NULL;

  -- Mesmo cálculo de address_key que rpc_add_entity_delivery_address.
  v_key :=
    lower(v_street) || '|' ||
    lower(v_number) || '|' ||
    lower(coalesce(v_floor, '')) || '|' ||
    lower(coalesce(v_unit, '')) || '|' ||
    lower(v_postal) || '|' ||
    lower(v_city) || '|' ||
    lower(v_country);

  SELECT a.address_key INTO v_old_key FROM public.anew_addresses a WHERE a.id = v_old_address_id;

  IF v_old_key IS NOT DISTINCT FROM v_key THEN
    v_address_id := v_old_address_id;
  ELSE
    SELECT a.id INTO v_address_id
    FROM public.anew_addresses a
    WHERE a.address_key = v_key
    ORDER BY a.created_at
    LIMIT 1;

    IF v_address_id IS NULL THEN
      INSERT INTO public.anew_addresses (
        street, number, floor, unit, postal_code, city, country, address_key, created_by
      ) VALUES (
        v_street, v_number, v_floor, v_unit, v_postal, v_city, v_country, v_key, v_actor
      )
      RETURNING id INTO v_address_id;
    ELSIF EXISTS (
      SELECT 1
      FROM public.anew_entity_addresses ea
      WHERE ea.entity_id = v_entity_id
        AND ea.address_id = v_address_id
        AND ea.address_type = 'delivery'
        AND ea.id <> p_entity_address_id
        AND (ea.valid_to IS NULL OR ea.valid_to > now())
    ) THEN
      RAISE EXCEPTION 'Este cliente já tem esta morada de entrega' USING ERRCODE = 'unique_violation';
    END IF;

    IF v_address_id IS DISTINCT FROM v_old_address_id THEN
      UPDATE public.anew_entity_addresses
         SET address_id = v_address_id
       WHERE id = p_entity_address_id;
    END IF;
  END IF;

  PERFORM public.fn_gravar_ficha_edificio(
    v_address_id, v_actor,
    true, p_acesso, p_impacto_percent, p_estacionamento, p_zona_estacionamento,
    p_tem_elevador, p_n_elevadores, p_n_andares, p_n_fracoes_por_andar,
    v_com_interior, p_tipologia, p_area_util_m2, p_n_divisoes, p_n_casas_banho, p_ano_construcao,
    p_pavimento, p_eletrica, p_quadro_diferencial, p_canalizacao, p_gas, p_amianto,
    p_habitada_durante_obra, p_animais, v_notas);

  SELECT nullif(concat_ws(', ',
           nullif(btrim(a.street), ''),
           nullif(btrim(a.number), ''),
           nullif(btrim(a.postal_code), ''),
           nullif(btrim(a.city), '')
         ), '')
    INTO v_formatted
  FROM public.anew_addresses a
  WHERE a.id = v_address_id;

  RETURN jsonb_build_object(
    'entity_address_id', p_entity_address_id,
    'address_id',        v_address_id,
    'formatted',         v_formatted,
    'address_changed',   v_address_id IS DISTINCT FROM v_old_address_id
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.rpc_update_entity_delivery_address(p_entity_address_id uuid, p_street text, p_number text, p_postal_code text, p_city text, p_floor text, p_unit text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text, p_com_interior boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_update_entity_delivery_address(p_entity_address_id uuid, p_street text, p_number text, p_postal_code text, p_city text, p_floor text, p_unit text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text, p_com_interior boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_update_entity_delivery_address(p_entity_address_id uuid, p_street text, p_number text, p_postal_code text, p_city text, p_floor text, p_unit text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text, p_com_interior boolean) TO service_role;
COMMENT ON FUNCTION public.rpc_update_entity_delivery_address(p_entity_address_id uuid, p_street text, p_number text, p_postal_code text, p_city text, p_floor text, p_unit text, p_acesso text, p_impacto_percent integer, p_estacionamento text, p_zona_estacionamento text, p_tem_elevador boolean, p_n_elevadores integer, p_n_andares integer, p_n_fracoes_por_andar integer, p_tipologia text, p_area_util_m2 numeric, p_n_divisoes integer, p_n_casas_banho integer, p_ano_construcao integer, p_pavimento text, p_eletrica text, p_quadro_diferencial boolean, p_canalizacao text, p_gas text, p_amianto text, p_habitada_durante_obra boolean, p_animais boolean, p_notas_interior text, p_com_interior boolean) IS 'Edita uma morada de entrega (20261206160000). Nunca faz UPDATE a anew_addresses: se a morada mudou, reutiliza/cria pela address_key e repõe a ligação (mesmo entity_address_id). Ficha do local: o exterior é substituído (tudo NULL = apagar); o interior (20261207110000) só com p_com_interior = true ou com algum campo do interior — chamadas antigas não o apagam.';

CREATE OR REPLACE FUNCTION public.sp_catalog_import(p_rows jsonb, p_dry_run boolean DEFAULT true, p_file_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u         public.supplier_portal_users := public.fn_sp_actor();
  v_n       integer;
  v_dry     boolean := COALESCE(p_dry_run, true);
  v_file    text := NULLIF(left(btrim(regexp_replace(COALESCE(p_file_name, ''), '[\x01-\x1F\x7F]', '', 'g')), 255), '');
  v_new     integer;
  v_chg     integer;
  v_same    integer;
  v_err     integer;
  v_rows    jsonb;
  v_summary jsonb;
  v_import  uuid;
BEGIN
  IF u.role <> 'owner' THEN
    RAISE EXCEPTION 'Só o utilizador principal da conta pode alterar o catálogo'
      USING ERRCODE = 'insufficient_privilege', HINT = 'not_owner';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'Envie as linhas como uma lista' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  v_n := jsonb_array_length(p_rows);
  IF v_n = 0 THEN
    RAISE EXCEPTION 'O ficheiro não tem linhas' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF v_n > 5000 THEN
    RAISE EXCEPTION 'Demasiadas linhas (%); o máximo é 5000 por importação', v_n
      USING ERRCODE = 'check_violation', HINT = 'too_many_rows';
  END IF;

  -- Uma importação de cada vez por conta.
  PERFORM pg_advisory_xact_lock(hashtextextended('sp_catalog:' || u.supplier_account_id::text, 0));

  CREATE TEMP TABLE IF NOT EXISTS _sp_cat_import (
    idx         integer,
    rownum      integer,
    data        jsonb,
    errors      text[],
    ref_key     text,
    existing_id uuid,
    status      text,
    changes     jsonb
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._sp_cat_import;

  INSERT INTO pg_temp._sp_cat_import (idx, rownum, data, errors, ref_key)
  SELECT e.ord::integer,
         CASE WHEN jsonb_typeof(e.v) = 'object' AND (e.v ->> '_row') ~ '^[0-9]{1,7}$'
              THEN (e.v ->> '_row')::integer ELSE e.ord::integer END,
         c.data, c.errors,
         public.fn_product_code_key(c.data ->> 'supplier_ref')
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS e(v, ord)
  CROSS JOIN LATERAL public.fn_sp_catalog_clean(e.v) c;

  -- Referência repetida no próprio ficheiro: fica a primeira.
  UPDATE pg_temp._sp_cat_import t
     SET errors = t.errors || format('Referência repetida no ficheiro (já na linha %s)', d.first_row)
  FROM (
    SELECT idx, first_value(rownum) OVER (PARTITION BY ref_key ORDER BY idx) AS first_row,
           row_number() OVER (PARTITION BY ref_key ORDER BY idx) AS rn
    FROM pg_temp._sp_cat_import
    WHERE ref_key IS NOT NULL
  ) d
  WHERE d.idx = t.idx AND d.rn > 1;

  UPDATE pg_temp._sp_cat_import t
     SET existing_id = ci.id
  FROM public.supplier_catalog_items ci
  WHERE ci.supplier_account_id = u.supplier_account_id AND ci.ref_key = t.ref_key;

  -- Artigo novo precisa de nome.
  UPDATE pg_temp._sp_cat_import t
     SET errors = t.errors || 'Nome obrigatório'::text
  WHERE t.existing_id IS NULL AND NOT (t.data ? 'name')
    AND NOT ('Nome obrigatório' = ANY (t.errors));

  UPDATE pg_temp._sp_cat_import t
     SET status = 'error'
  WHERE cardinality(t.errors) > 0;

  UPDATE pg_temp._sp_cat_import t
     SET changes = public.fn_sp_catalog_diff(ci, t.data),
         status = CASE WHEN public.fn_sp_catalog_diff(ci, t.data) = '{}'::jsonb THEN 'unchanged' ELSE 'changed' END
  FROM public.supplier_catalog_items ci
  WHERE t.status IS NULL AND t.existing_id = ci.id;

  UPDATE pg_temp._sp_cat_import SET status = 'new' WHERE status IS NULL;

  SELECT count(*) FILTER (WHERE status = 'new'),
         count(*) FILTER (WHERE status = 'changed'),
         count(*) FILTER (WHERE status = 'unchanged'),
         count(*) FILTER (WHERE status = 'error')
  INTO v_new, v_chg, v_same, v_err
  FROM pg_temp._sp_cat_import;

  IF NOT v_dry THEN
    INSERT INTO public.supplier_catalog_items (
      supplier_account_id, supplier_ref, barcode, name, description, brand, unit_label,
      units_per_pack, base_price, currency, moq, lead_time_days, is_active,
      created_by_portal_user, updated_by_portal_user
    )
    SELECT u.supplier_account_id,
           t.data ->> 'supplier_ref', t.data ->> 'barcode', t.data ->> 'name', t.data ->> 'description',
           t.data ->> 'brand', t.data ->> 'unit_label',
           (t.data ->> 'units_per_pack')::numeric, (t.data ->> 'base_price')::numeric,
           COALESCE(t.data ->> 'currency', 'EUR'), (t.data ->> 'moq')::numeric,
           (t.data ->> 'lead_time_days')::integer, COALESCE((t.data ->> 'is_active')::boolean, true),
           u.id, u.id
    FROM pg_temp._sp_cat_import t
    WHERE t.status = 'new';

    UPDATE public.supplier_catalog_items ci SET
      supplier_ref   = CASE WHEN t.data ? 'supplier_ref'   THEN t.data ->> 'supplier_ref' ELSE ci.supplier_ref END,
      barcode        = CASE WHEN t.data ? 'barcode'        THEN t.data ->> 'barcode' ELSE ci.barcode END,
      name           = CASE WHEN t.data ? 'name'           THEN t.data ->> 'name' ELSE ci.name END,
      description    = CASE WHEN t.data ? 'description'    THEN t.data ->> 'description' ELSE ci.description END,
      brand          = CASE WHEN t.data ? 'brand'          THEN t.data ->> 'brand' ELSE ci.brand END,
      unit_label     = CASE WHEN t.data ? 'unit_label'     THEN t.data ->> 'unit_label' ELSE ci.unit_label END,
      units_per_pack = CASE WHEN t.data ? 'units_per_pack' THEN (t.data ->> 'units_per_pack')::numeric ELSE ci.units_per_pack END,
      base_price     = CASE WHEN t.data ? 'base_price'     THEN (t.data ->> 'base_price')::numeric ELSE ci.base_price END,
      currency       = CASE WHEN t.data ? 'currency'       THEN t.data ->> 'currency' ELSE ci.currency END,
      moq            = CASE WHEN t.data ? 'moq'            THEN (t.data ->> 'moq')::numeric ELSE ci.moq END,
      lead_time_days = CASE WHEN t.data ? 'lead_time_days' THEN (t.data ->> 'lead_time_days')::integer ELSE ci.lead_time_days END,
      is_active      = CASE WHEN t.data ? 'is_active'      THEN (t.data ->> 'is_active')::boolean ELSE ci.is_active END,
      updated_at = now(),
      updated_by_portal_user = u.id
    FROM pg_temp._sp_cat_import t
    WHERE t.status = 'changed' AND ci.id = t.existing_id;
  END IF;

  v_summary := jsonb_build_object('total', v_n, 'new', v_new, 'changed', v_chg, 'unchanged', v_same, 'errors', v_err);

  IF NOT v_dry THEN
    INSERT INTO public.supplier_catalog_imports (supplier_account_id, portal_user_id, file_name, total_rows, summary)
    VALUES (u.supplier_account_id, u.id, v_file, v_n, v_summary)
    RETURNING id INTO v_import;
  END IF;

  -- Detalhe só das linhas novas, alteradas ou com erro (as iguais só contam).
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'row', t.rownum,
           'status', t.status,
           'supplier_ref', t.data ->> 'supplier_ref',
           'name', COALESCE(t.data ->> 'name', ci.name),
           'changes', CASE WHEN t.status = 'changed' THEN t.changes END,
           'errors', CASE WHEN t.status = 'error' THEN to_jsonb(t.errors) END
         ) ORDER BY t.idx), '[]'::jsonb)
  INTO v_rows
  FROM pg_temp._sp_cat_import t
  LEFT JOIN public.supplier_catalog_items ci ON ci.id = t.existing_id
  WHERE t.status <> 'unchanged';

  TRUNCATE pg_temp._sp_cat_import;

  RETURN v_summary || jsonb_build_object('dry_run', v_dry, 'import_id', v_import, 'rows', v_rows);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_catalog_import(p_rows jsonb, p_dry_run boolean, p_file_name text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_catalog_import(p_rows jsonb, p_dry_run boolean, p_file_name text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_catalog_import(p_rows jsonb, p_dry_run boolean, p_file_name text) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_catalog_list(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_include_inactive boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u        public.supplier_portal_users := public.fn_sp_actor();
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_q      text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_like   text;
  v_total  integer;
  v_items  jsonb;
BEGIN
  IF v_q IS NOT NULL THEN
    v_like := '%' || replace(replace(replace(left(v_q, 100), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  SELECT count(*) INTO v_total
  FROM public.supplier_catalog_items ci
  WHERE ci.supplier_account_id = u.supplier_account_id
    AND (COALESCE(p_include_inactive, false) OR ci.is_active)
    AND (v_like IS NULL OR ci.supplier_ref ILIKE v_like OR ci.name ILIKE v_like
         OR ci.barcode ILIKE v_like OR ci.brand ILIKE v_like);

  SELECT COALESCE(jsonb_agg(public.fn_sp_catalog_item_json(ci, true) ORDER BY ci.supplier_ref, ci.id), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT c.id
    FROM public.supplier_catalog_items c
    WHERE c.supplier_account_id = u.supplier_account_id
      AND (COALESCE(p_include_inactive, false) OR c.is_active)
      AND (v_like IS NULL OR c.supplier_ref ILIKE v_like OR c.name ILIKE v_like
           OR c.barcode ILIKE v_like OR c.brand ILIKE v_like)
    ORDER BY c.supplier_ref, c.id
    LIMIT v_limit OFFSET v_offset
  ) z
  JOIN public.supplier_catalog_items ci ON ci.id = z.id;

  RETURN jsonb_build_object(
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'can_edit', u.role = 'owner',
    'items', v_items
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_catalog_list(p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_catalog_list(p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_catalog_list(p_search text, p_limit integer, p_offset integer, p_include_inactive boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_catalog_set_active(p_item_ids uuid[], p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u   public.supplier_portal_users := public.fn_sp_actor();
  v_n integer;
BEGIN
  IF u.role <> 'owner' THEN
    RAISE EXCEPTION 'Só o utilizador principal da conta pode alterar o catálogo'
      USING ERRCODE = 'insufficient_privilege', HINT = 'not_owner';
  END IF;
  IF p_active IS NULL OR p_item_ids IS NULL OR cardinality(p_item_ids) = 0 THEN
    RAISE EXCEPTION 'Indique os artigos e o estado' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF cardinality(p_item_ids) > 5000 THEN
    RAISE EXCEPTION 'Demasiados artigos (máx. 5000)' USING ERRCODE = 'check_violation', HINT = 'too_many_rows';
  END IF;

  UPDATE public.supplier_catalog_items
     SET is_active = p_active, updated_at = now(), updated_by_portal_user = u.id
   WHERE supplier_account_id = u.supplier_account_id
     AND id = ANY (p_item_ids)
     AND is_active IS DISTINCT FROM p_active;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  RETURN jsonb_build_object('updated', v_n);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_catalog_set_active(p_item_ids uuid[], p_active boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_catalog_set_active(p_item_ids uuid[], p_active boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_catalog_set_active(p_item_ids uuid[], p_active boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_catalog_upsert_item(p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u      public.supplier_portal_users := public.fn_sp_actor();
  v_id   uuid;
  v_errs text[];
  cur    public.supplier_catalog_items;
  v_key  text;
  v_data jsonb;
  v_row  jsonb;
BEGIN
  IF u.role <> 'owner' THEN
    RAISE EXCEPTION 'Só o utilizador principal da conta pode alterar o catálogo'
      USING ERRCODE = 'insufficient_privilege', HINT = 'not_owner';
  END IF;
  IF p_item IS NULL OR jsonb_typeof(p_item) <> 'object' THEN
    RAISE EXCEPTION 'Artigo inválido' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  IF NULLIF(p_item ->> 'id', '') IS NOT NULL THEN
    BEGIN
      v_id := (p_item ->> 'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Artigo não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
    END;
    SELECT * INTO cur FROM public.supplier_catalog_items
    WHERE id = v_id AND supplier_account_id = u.supplier_account_id FOR UPDATE;
    IF cur.id IS NULL THEN
      RAISE EXCEPTION 'Artigo não encontrado' USING ERRCODE = 'no_data_found', HINT = 'not_found';
    END IF;
    -- Na edição a referência é opcional: sem ela fica a atual.
    v_row := p_item - 'id';
    IF NOT (v_row ? 'supplier_ref') THEN
      v_row := v_row || jsonb_build_object('supplier_ref', cur.supplier_ref);
    END IF;
  ELSE
    v_row := p_item - 'id';
  END IF;

  SELECT x.data, x.errors INTO v_data, v_errs FROM public.fn_sp_catalog_clean(v_row) x;
  IF cur.id IS NULL AND NOT (v_data ? 'name') AND NOT ('Nome obrigatório' = ANY (v_errs)) THEN
    v_errs := v_errs || 'Nome obrigatório'::text;
  END IF;
  IF cardinality(v_errs) > 0 THEN
    RAISE EXCEPTION '%', array_to_string(v_errs, '; ')
      USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('sp_catalog:' || u.supplier_account_id::text, 0));
  v_key := public.fn_product_code_key(v_data ->> 'supplier_ref');
  IF EXISTS (SELECT 1 FROM public.supplier_catalog_items
             WHERE supplier_account_id = u.supplier_account_id AND ref_key = v_key
               AND id IS DISTINCT FROM cur.id) THEN
    RAISE EXCEPTION 'Já existe um artigo com a referência «%»', v_data ->> 'supplier_ref'
      USING ERRCODE = 'unique_violation', HINT = 'conflict';
  END IF;

  IF cur.id IS NULL THEN
    INSERT INTO public.supplier_catalog_items (
      supplier_account_id, supplier_ref, barcode, name, description, brand, unit_label,
      units_per_pack, base_price, currency, moq, lead_time_days, is_active,
      created_by_portal_user, updated_by_portal_user
    ) VALUES (
      u.supplier_account_id, v_data ->> 'supplier_ref', v_data ->> 'barcode', v_data ->> 'name',
      v_data ->> 'description', v_data ->> 'brand', v_data ->> 'unit_label',
      (v_data ->> 'units_per_pack')::numeric, (v_data ->> 'base_price')::numeric,
      COALESCE(v_data ->> 'currency', 'EUR'), (v_data ->> 'moq')::numeric,
      (v_data ->> 'lead_time_days')::integer, COALESCE((v_data ->> 'is_active')::boolean, true), u.id, u.id
    ) RETURNING * INTO cur;
    RETURN jsonb_build_object('created', true, 'item', public.fn_sp_catalog_item_json(cur, true));
  END IF;

  UPDATE public.supplier_catalog_items ci SET
    supplier_ref   = v_data ->> 'supplier_ref',
    barcode        = CASE WHEN v_data ? 'barcode'        THEN v_data ->> 'barcode' ELSE ci.barcode END,
    name           = CASE WHEN v_data ? 'name'           THEN v_data ->> 'name' ELSE ci.name END,
    description    = CASE WHEN v_data ? 'description'    THEN v_data ->> 'description' ELSE ci.description END,
    brand          = CASE WHEN v_data ? 'brand'          THEN v_data ->> 'brand' ELSE ci.brand END,
    unit_label     = CASE WHEN v_data ? 'unit_label'     THEN v_data ->> 'unit_label' ELSE ci.unit_label END,
    units_per_pack = CASE WHEN v_data ? 'units_per_pack' THEN (v_data ->> 'units_per_pack')::numeric ELSE ci.units_per_pack END,
    base_price     = CASE WHEN v_data ? 'base_price'     THEN (v_data ->> 'base_price')::numeric ELSE ci.base_price END,
    currency       = CASE WHEN v_data ? 'currency'       THEN v_data ->> 'currency' ELSE ci.currency END,
    moq            = CASE WHEN v_data ? 'moq'            THEN (v_data ->> 'moq')::numeric ELSE ci.moq END,
    lead_time_days = CASE WHEN v_data ? 'lead_time_days' THEN (v_data ->> 'lead_time_days')::integer ELSE ci.lead_time_days END,
    is_active      = CASE WHEN v_data ? 'is_active'      THEN (v_data ->> 'is_active')::boolean ELSE ci.is_active END,
    updated_at = now(),
    updated_by_portal_user = u.id
  WHERE ci.id = cur.id
  RETURNING ci.* INTO cur;

  RETURN jsonb_build_object('created', false, 'item', public.fn_sp_catalog_item_json(cur, true));
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_catalog_upsert_item(p_item jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_catalog_upsert_item(p_item jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_catalog_upsert_item(p_item jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_confirm_order(p_po_id uuid, p_revision integer, p_promised_date date DEFAULT NULL::date, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u         public.supplier_portal_users := public.fn_sp_actor();
  v_pub     public.supplier_po_publications;
  v_po      public.purchase_orders;
  v_comment text := NULLIF(btrim(regexp_replace(COALESCE(p_comment, ''), '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]', '', 'g')), '');
  v_today   date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
  v_n       integer;
BEGIN
  -- Bloqueia a publicação e volta a verificar o acesso com a linha bloqueada.
  PERFORM 1 FROM public.supplier_po_publications WHERE purchase_order_id = p_po_id FOR UPDATE;
  v_pub := public.fn_sp_po_publication(p_po_id, u.id);
  IF v_pub.purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'Encomenda não encontrada' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_po_id;

  IF p_revision IS DISTINCT FROM v_pub.revision THEN
    RAISE EXCEPTION 'A empresa atualizou esta encomenda: recarregue a página para ver a versão nova'
      USING ERRCODE = 'check_violation', HINT = 'stale_revision';
  END IF;

  IF v_pub.status = 'confirmed' THEN
    RETURN jsonb_build_object(
      'purchase_order_id', p_po_id, 'revision', v_pub.revision, 'publication_status', v_pub.status,
      'confirmed_at', v_pub.confirmed_at, 'promised_date', v_pub.promised_date,
      'supplier_comment', v_pub.supplier_comment, 'already_confirmed', true);
  END IF;

  IF v_po.status NOT IN ('ordered', 'partially_received') THEN
    RAISE EXCEPTION 'Esta encomenda já está fechada (%): não é possível confirmá-la', v_po.status
      USING ERRCODE = 'check_violation', HINT = 'order_closed';
  END IF;
  IF v_comment IS NOT NULL AND char_length(v_comment) > 1000 THEN
    RAISE EXCEPTION 'Comentário demasiado longo (máx. 1000 caracteres)' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF p_promised_date IS NOT NULL AND (p_promised_date < LEAST(v_po.order_date, v_today) OR p_promised_date > v_today + 730) THEN
    RAISE EXCEPTION 'Data de entrega inválida (entre a data da encomenda e daqui a 2 anos)'
      USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;

  UPDATE public.supplier_po_publications
     SET status = 'confirmed', confirmed_at = now(), confirmed_by = u.id,
         viewed_at = COALESCE(viewed_at, now()), viewed_by = COALESCE(viewed_by, u.id),
         promised_date = p_promised_date, supplier_comment = v_comment
   WHERE purchase_order_id = p_po_id
  RETURNING * INTO v_pub;

  PERFORM public.fn_manual_audit_log('purchase_orders', p_po_id, v_po.organization_id, 'UPDATE',
    jsonb_build_object('supplier_publication', jsonb_build_object(
      'old', jsonb_build_object('status', 'sent'),
      'new', jsonb_build_object('status', 'confirmed', 'revision', v_pub.revision, 'promised_date', v_pub.promised_date,
                                'confirmed_by_portal_user', u.id))), 'supplier_portal');

  v_n := public.fn_po_notify_supplier_confirmed(v_po, v_pub);

  RETURN jsonb_build_object(
    'purchase_order_id', p_po_id, 'revision', v_pub.revision, 'publication_status', v_pub.status,
    'confirmed_at', v_pub.confirmed_at, 'promised_date', v_pub.promised_date,
    'supplier_comment', v_pub.supplier_comment, 'already_confirmed', false);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_confirm_order(p_po_id uuid, p_revision integer, p_promised_date date, p_comment text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_confirm_order(p_po_id uuid, p_revision integer, p_promised_date date, p_comment text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_confirm_order(p_po_id uuid, p_revision integer, p_promised_date date, p_comment text) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_get_my_supplier_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u           public.supplier_portal_users := public.fn_sp_actor();
  s           public.suppliers;
  v_companies jsonb;
BEGIN
  SELECT sp.* INTO s
  FROM public.supplier_portal_user_access x
  JOIN public.supplier_account_links l ON l.id = x.link_id
  JOIN public.suppliers sp ON sp.id = l.supplier_id
  WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL
    AND l.status = 'active' AND sp.deleted_at IS NULL
  ORDER BY sp.updated_at DESC NULLS LAST, sp.id
  LIMIT 1;

  IF s.id IS NULL THEN
    RAISE EXCEPTION 'Sem acesso ao portal do fornecedor'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_supplier_access';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id', c.id, 'name', c.name) ORDER BY c.name), '[]'::jsonb)
  INTO v_companies
  FROM (
    SELECT DISTINCT o.id, o.name
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_account_links l ON l.id = x.link_id
    JOIN public.suppliers sp ON sp.id = l.supplier_id
    JOIN public.anew_organizations o ON o.id = l.organization_id
    WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL
      AND l.status = 'active' AND sp.deleted_at IS NULL
  ) c;

  RETURN jsonb_build_object(
    'can_edit', u.role = 'owner',
    'confirmed_at', u.profile_confirmed_at,
    'data', jsonb_build_object(
      'name', s.name,
      'contact_person', s.contact_person,
      'email', s.email,
      'phone', s.phone,
      'phone_country_code', s.phone_country_code,
      -- Só leitura no portal; recurso a vat_number quando tax_id está vazio.
      'tax_id', COALESCE(NULLIF(btrim(s.tax_id), ''), NULLIF(btrim(s.vat_number), '')),
      'address', s.address,
      'city', s.city,
      'postal_code', s.postal_code,
      'country', s.country,
      'website', s.website
    ),
    'companies', v_companies
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_get_my_supplier_data() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_get_my_supplier_data() TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_get_my_supplier_data() TO service_role;
COMMENT ON FUNCTION public.sp_get_my_supplier_data() IS 'Portal do fornecedor: dados da empresa (ficha suppliers ligada mais recente), empresas ligadas, can_edit (owner) e confirmed_at.';

CREATE OR REPLACE FUNCTION public.sp_get_order(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u        public.supplier_portal_users := public.fn_sp_actor();
  v_pub    public.supplier_po_publications := public.fn_sp_po_publication(p_po_id, u.id);
  v_po     public.purchase_orders;
  v_org    public.anew_organizations;
  v_sup    record;
  v_snd    record;
  v_nif    text;
  v_addr   text;
  v_lines  jsonb;
  v_tot    record;
BEGIN
  IF v_pub.purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'Encomenda não encontrada' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = v_pub.purchase_order_id;
  SELECT * INTO v_org FROM public.anew_organizations WHERE id = v_po.organization_id;
  SELECT name, tax_id, email, phone INTO v_sup FROM public.suppliers WHERE id = v_po.supplier_id;
  SELECT name, email, phone INTO v_snd FROM public.anew_users WHERE id = v_pub.sent_by;

  SELECT fe.nif INTO v_nif
  FROM public.anew_entity_fiscal_entities efe
  JOIN public.fiscal_entities fe ON fe.id = efe.fiscal_entity_id
  WHERE efe.entity_id = v_org.entity_id AND (efe.valid_to IS NULL OR efe.valid_to > now())
  ORDER BY efe.is_primary DESC NULLS LAST, efe.created_at DESC
  LIMIT 1;

  SELECT concat_ws(', ', NULLIF(concat_ws(' ', a.street, a.number), ''), NULLIF(concat_ws(' ', a.postal_code, a.city), ''), a.country)
  INTO v_addr
  FROM public.anew_entity_addresses ea
  JOIN public.anew_addresses a ON a.id = ea.address_id
  WHERE ea.entity_id = v_org.entity_id AND (ea.valid_to IS NULL OR ea.valid_to > now())
  ORDER BY ea.is_fiscal DESC NULLS LAST, ea.is_primary DESC NULLS LAST, ea.created_at DESC
  LIMIT 1;

  v_lines := public.fn_sp_po_lines_json(v_po.id);
  SELECT round(COALESCE(sum(i.unit_price * i.quantity), 0), 2) AS subtotal,
         round(COALESCE(sum(COALESCE(i.vat_amount, 0)), 0), 2) AS vat_total
  INTO v_tot
  FROM public.purchase_order_items i WHERE i.purchase_order_id = v_po.id;

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'order_number', v_po.order_number,
    'order_date', v_po.order_date,
    'expected_delivery', v_po.expected_delivery,
    'order_status', v_po.status,
    'supplier_notes', v_po.supplier_notes,
    'currency', 'EUR',
    'publication', jsonb_build_object(
      'status', v_pub.status,
      'revision', v_pub.revision,
      'sent_at', v_pub.sent_at,
      'viewed_at', v_pub.viewed_at,
      'confirmed_at', v_pub.confirmed_at,
      'confirmed_by_name', (SELECT COALESCE(name, email) FROM public.supplier_portal_users WHERE id = v_pub.confirmed_by),
      'promised_date', v_pub.promised_date,
      'supplier_comment', v_pub.supplier_comment,
      'promised_date_accepted', v_pub.promised_date_accepted_at IS NOT NULL),
    'can_confirm', v_pub.status IN ('sent', 'viewed') AND v_po.status IN ('ordered', 'partially_received'),
    'company', jsonb_build_object(
      'organization_id', v_org.id, 'name', v_org.name, 'nif', v_nif, 'address', NULLIF(v_addr, ''),
      'phone', v_org.phone, 'logo_url', v_org.logo_url),
    'supplier', jsonb_build_object('name', v_sup.name, 'tax_id', v_sup.tax_id, 'email', v_sup.email, 'phone', v_sup.phone),
    'sent_by', CASE WHEN v_pub.sent_by IS NULL THEN NULL
                    ELSE jsonb_build_object('name', v_snd.name, 'email', v_snd.email, 'phone', v_snd.phone) END,
    'lines', v_lines,
    'totals', jsonb_build_object('subtotal', v_tot.subtotal, 'vat_total', v_tot.vat_total,
                                 'total', v_tot.subtotal + v_tot.vat_total)
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_get_order(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_get_order(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_get_order(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_list_orders(p_org_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u        public.supplier_portal_users := public.fn_sp_actor();
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_status text := COALESCE(NULLIF(btrim(p_status), ''), 'all');
  v_q      text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_like   text;
  v_counts jsonb;
  v_total  integer;
  v_items  jsonb;
BEGIN
  IF v_status NOT IN ('all', 'to_confirm', 'confirmed', 'open', 'received', 'cancelled') THEN
    RAISE EXCEPTION 'Filtro de estado inválido' USING ERRCODE = 'check_violation', HINT = 'validation';
  END IF;
  IF v_q IS NOT NULL THEN
    v_like := '%' || replace(replace(replace(left(v_q, 100), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  SELECT jsonb_build_object(
           'all', count(*),
           'to_confirm', count(*) FILTER (WHERE pub_status IN ('sent', 'viewed') AND order_status IN ('ordered', 'partially_received')),
           'confirmed', count(*) FILTER (WHERE pub_status = 'confirmed'),
           'open', count(*) FILTER (WHERE order_status IN ('ordered', 'partially_received')),
           'received', count(*) FILTER (WHERE order_status = 'received'),
           'cancelled', count(*) FILTER (WHERE order_status = 'cancelled'))
  INTO v_counts
  FROM public.fn_sp_orders_visible(u.id, p_org_id, v_like);

  v_total := (v_counts ->> CASE WHEN v_status = 'all' THEN 'all' ELSE v_status END)::integer;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'purchase_order_id', v.purchase_order_id,
           'order_number', v.order_number,
           'organization', jsonb_build_object('id', v.organization_id, 'name', v.org_name, 'logo_url', v.org_logo),
           'order_date', v.order_date,
           'expected_delivery', v.expected_delivery,
           'order_status', v.order_status,
           'publication_status', v.pub_status,
           'revision', v.revision,
           'sent_at', v.sent_at,
           'viewed_at', v.viewed_at,
           'confirmed_at', v.confirmed_at,
           'promised_date', v.promised_date,
           'lines', t.n,
           'subtotal', t.subtotal,
           'vat_total', t.vat_total,
           'total', t.subtotal + t.vat_total,
           'currency', 'EUR',
           'can_confirm', v.pub_status IN ('sent', 'viewed') AND v.order_status IN ('ordered', 'partially_received')
         ) ORDER BY v.sent_at DESC, v.purchase_order_id), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT * FROM public.fn_sp_orders_visible(u.id, p_org_id, v_like) z
    WHERE v_status = 'all'
       OR (v_status = 'to_confirm' AND z.pub_status IN ('sent', 'viewed') AND z.order_status IN ('ordered', 'partially_received'))
       OR (v_status = 'confirmed' AND z.pub_status = 'confirmed')
       OR (v_status = 'open' AND z.order_status IN ('ordered', 'partially_received'))
       OR (v_status = 'received' AND z.order_status = 'received')
       OR (v_status = 'cancelled' AND z.order_status = 'cancelled')
    ORDER BY z.sent_at DESC, z.purchase_order_id
    LIMIT v_limit OFFSET v_offset
  ) v
  CROSS JOIN LATERAL (
    SELECT count(*) AS n,
           round(COALESCE(sum(i.unit_price * i.quantity), 0), 2) AS subtotal,
           round(COALESCE(sum(COALESCE(i.vat_amount, 0)), 0), 2) AS vat_total
    FROM public.purchase_order_items i
    WHERE i.purchase_order_id = v.purchase_order_id
  ) t;

  RETURN jsonb_build_object('total', v_total, 'limit', v_limit, 'offset', v_offset,
                            'counts', v_counts, 'items', v_items);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_list_orders(p_org_id uuid, p_status text, p_search text, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_list_orders(p_org_id uuid, p_status text, p_search text, p_limit integer, p_offset integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_list_orders(p_org_id uuid, p_status text, p_search text, p_limit integer, p_offset integer) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_mark_order_viewed(p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u      public.supplier_portal_users := public.fn_sp_actor();
  v_pub  public.supplier_po_publications := public.fn_sp_po_publication(p_po_id, u.id);
  v_at   timestamptz;
BEGIN
  IF v_pub.purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'Encomenda não encontrada' USING ERRCODE = 'no_data_found', HINT = 'not_found';
  END IF;
  IF v_pub.viewed_at IS NOT NULL THEN
    RETURN jsonb_build_object('purchase_order_id', p_po_id, 'viewed_at', v_pub.viewed_at, 'first_view', false);
  END IF;
  UPDATE public.supplier_po_publications
     SET viewed_at = now(), viewed_by = u.id,
         status = CASE WHEN status = 'sent' THEN 'viewed' ELSE status END
   WHERE purchase_order_id = p_po_id AND viewed_at IS NULL AND status <> 'withdrawn'
  RETURNING viewed_at INTO v_at;
  IF v_at IS NULL THEN
    SELECT viewed_at INTO v_at FROM public.supplier_po_publications WHERE purchase_order_id = p_po_id;
    RETURN jsonb_build_object('purchase_order_id', p_po_id, 'viewed_at', v_at, 'first_view', false);
  END IF;
  RETURN jsonb_build_object('purchase_order_id', p_po_id, 'viewed_at', v_at, 'first_view', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_mark_order_viewed(p_po_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_mark_order_viewed(p_po_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_mark_order_viewed(p_po_id uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.sp_mark_password_changed()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  UPDATE public.supplier_portal_users
     SET password_changed_at = now(), first_login = false, updated_at = now()
   WHERE auth_user_id = auth.uid() AND status = 'active'
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Sem acesso ao portal do fornecedor'
      USING ERRCODE = 'insufficient_privilege', HINT = 'no_supplier_access';
  END IF;
  RETURN jsonb_build_object('ok', true);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_mark_password_changed() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_mark_password_changed() TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_mark_password_changed() TO service_role;

CREATE OR REPLACE FUNCTION public.sp_my_companies()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u public.supplier_portal_users := public.fn_sp_actor();
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'organization_id', o.id,
             'name', o.name,
             'logo_url', o.logo_url,
             'granted_at', x.granted_at) ORDER BY o.name)
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_account_links l ON l.id = x.link_id
    JOIN public.suppliers s ON s.id = l.supplier_id
    JOIN public.anew_organizations o ON o.id = l.organization_id
    WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL
      AND l.status = 'active' AND s.deleted_at IS NULL
  ), '[]'::jsonb);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_my_companies() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_my_companies() TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_my_companies() TO service_role;

CREATE OR REPLACE FUNCTION public.sp_update_my_supplier_data(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u          public.supplier_portal_users := public.fn_sp_actor();
  v_fields   text[] := ARRAY['name', 'contact_person', 'email', 'phone', 'phone_country_code',
                             'address', 'city', 'postal_code', 'country', 'website'];
  v_labels   jsonb := jsonb_build_object(
                'name', 'Nome', 'contact_person', 'Pessoa de contacto', 'email', 'Email',
                'phone', 'Telefone', 'phone_country_code', 'Indicativo', 'address', 'Morada',
                'city', 'Localidade', 'postal_code', 'Código postal', 'country', 'País',
                'website', 'Website');
  v_maxlen   jsonb := jsonb_build_object(
                'name', 200, 'contact_person', 200, 'email', 255, 'phone', 20,
                'phone_country_code', 10, 'address', 255, 'city', 100, 'postal_code', 20,
                'country', 100, 'website', 255);
  v_clean    jsonb := '{}'::jsonb;
  k          text;
  v          text;
  v_type     text;
  v_pc_pt    text;     -- postal enviado normalizado 0000-000 (NULL = não é PT válido)
  v_eff_ctry text;     -- país efetivo da ficha (enviado ou o da ficha)
  v_row      jsonb;    -- v_clean com o postal normalizado para esta ficha
  r          record;
  v_changed  text[];
  v_count    integer := 0;
  v_conf     timestamptz;
BEGIN
  IF u.role IS DISTINCT FROM 'owner' THEN
    RAISE EXCEPTION 'Só o responsável da conta pode alterar os dados da empresa'
      USING ERRCODE = 'insufficient_privilege', HINT = 'not_owner';
  END IF;

  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN
    RAISE EXCEPTION 'Dados inválidos' USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
  END IF;

  -- 4.1 Limpar: só os campos aceites; trim (inclui tabs/quebras); '' → NULL.
  FOREACH k IN ARRAY v_fields LOOP
    CONTINUE WHEN NOT (p_data ? k);
    v_type := jsonb_typeof(p_data -> k);
    IF v_type NOT IN ('string', 'number', 'null') THEN
      RAISE EXCEPTION 'O campo «%» tem um valor inválido.', v_labels ->> k
        USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
    END IF;
    v := NULLIF(regexp_replace(p_data ->> k, '^[[:space:]]+|[[:space:]]+$', '', 'g'), '');
    v_clean := v_clean || jsonb_build_object(k, v);
  END LOOP;

  -- 4.2 Validar (só as chaves enviadas).
  IF v_clean ? 'name' AND (v_clean ->> 'name') IS NULL THEN
    RAISE EXCEPTION 'O campo «Nome» é obrigatório.'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
  END IF;

  v := v_clean ->> 'email';
  IF v IS NOT NULL AND v !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'O campo «Email» tem um formato inválido.'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
  END IF;

  v := v_clean ->> 'phone';
  IF v IS NOT NULL AND v !~ '^[0-9 ()+./-]+$' THEN
    RAISE EXCEPTION 'O campo «Telefone» só pode ter números, espaços e os sinais + ( ) - . /'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
  END IF;

  v := v_clean ->> 'phone_country_code';
  IF v IS NOT NULL THEN
    v := regexp_replace(v, '[[:space:]]', '', 'g');
    -- 00NNN (valores antigos do CRM) → +NNN; antes do caso só-dígitos ('0044').
    IF v ~ '^00[0-9]{1,4}$' THEN
      v := '+' || substr(v, 3);
    ELSIF v ~ '^[0-9]{1,4}$' THEN
      v := '+' || v;
    END IF;
    IF v !~ '^\+[0-9]{1,4}$' THEN
      RAISE EXCEPTION 'O campo «Indicativo» deve ter o formato +351.'
        USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
    END IF;
    v_clean := v_clean || jsonb_build_object('phone_country_code', v);
  END IF;

  v := v_clean ->> 'website';
  IF v IS NOT NULL THEN
    IF v !~* '^https?://' THEN
      v := 'https://' || v;
    END IF;
    IF v !~* '^https?://[^[:space:]/?#@]+\.[^[:space:]/?#@]+([/?#][^[:space:]]*)?$' THEN
      RAISE EXCEPTION 'O campo «Website» tem um formato inválido.'
        USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
    END IF;
    v_clean := v_clean || jsonb_build_object('website', v);
  END IF;

  -- Código postal: só a forma normalizada PT aqui; a validação é por ficha
  -- (4.3), contra o país efetivo de cada uma.
  v := v_clean ->> 'postal_code';
  IF v IS NOT NULL THEN
    v_pc_pt := regexp_replace(v, '[[:space:]]', '', 'g');
    IF v_pc_pt ~ '^[0-9]{7}$' THEN
      v_pc_pt := substr(v_pc_pt, 1, 4) || '-' || substr(v_pc_pt, 5, 3);
    END IF;
    IF v_pc_pt !~ '^[0-9]{4}-[0-9]{3}$' THEN
      v_pc_pt := NULL;
    END IF;
  END IF;

  -- Tamanhos máximos (alinhados com o zod de src/pages/Suppliers.tsx).
  FOREACH k IN ARRAY v_fields LOOP
    v := v_clean ->> k;
    IF v IS NOT NULL AND char_length(v) > (v_maxlen ->> k)::integer THEN
      RAISE EXCEPTION 'O campo «%» deve ter no máximo % caracteres.', v_labels ->> k, v_maxlen ->> k
        USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
    END IF;
  END LOOP;

  -- 4.3 Gravar em todas as fichas ligadas (uma gravação de cada vez por conta).
  PERFORM pg_advisory_xact_lock(hashtextextended('sp_supplier_data:' || u.supplier_account_id::text, 0));
  PERFORM set_config('app.audit_source', 'supplier_portal', true);

  FOR r IN
    SELECT sp.id AS supplier_id, to_jsonb(sp) AS sj, l.id AS link_id, l.organization_id
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_account_links l ON l.id = x.link_id
    JOIN public.suppliers sp ON sp.id = l.supplier_id
    WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL
      AND l.status = 'active' AND sp.deleted_at IS NULL
    ORDER BY sp.id
    FOR UPDATE OF sp
  LOOP
    -- Código postal por ficha (só se a chave vier e não for vazia): país
    -- efetivo = o enviado ou, sem a chave country, o desta ficha. PT ou vazio
    -- → tem de ser 0000-000 (grava-se normalizado). Erro = rollback de tudo.
    v_row := v_clean;
    IF (v_clean ->> 'postal_code') IS NOT NULL THEN
      v_eff_ctry := CASE WHEN v_clean ? 'country' THEN v_clean ->> 'country' ELSE r.sj ->> 'country' END;
      IF NULLIF(btrim(v_eff_ctry), '') IS NULL
         OR lower(btrim(v_eff_ctry)) IN ('portugal', 'pt', 'prt') THEN
        IF v_pc_pt IS NULL THEN
          RAISE EXCEPTION 'O campo «Código postal» deve ter o formato 0000-000.'
            USING ERRCODE = 'invalid_parameter_value', HINT = 'validation';
        END IF;
        v_row := v_row || jsonb_build_object('postal_code', v_pc_pt);
      END IF;
    END IF;

    v_changed := ARRAY[]::text[];
    FOREACH k IN ARRAY v_fields LOOP
      IF v_row ? k AND (r.sj ->> k) IS DISTINCT FROM (v_row ->> k) THEN
        v_changed := v_changed || k;
      END IF;
    END LOOP;
    CONTINUE WHEN cardinality(v_changed) = 0;

    -- tax_id / vat_number / organization_id nunca no SET
    -- (trg_suppliers_portal_nif_guard não dispara).
    UPDATE public.suppliers s SET
      name               = CASE WHEN v_row ? 'name'               THEN v_row ->> 'name'               ELSE s.name END,
      contact_person     = CASE WHEN v_row ? 'contact_person'     THEN v_row ->> 'contact_person'     ELSE s.contact_person END,
      email              = CASE WHEN v_row ? 'email'              THEN v_row ->> 'email'              ELSE s.email END,
      phone              = CASE WHEN v_row ? 'phone'              THEN v_row ->> 'phone'              ELSE s.phone END,
      phone_country_code = CASE WHEN v_row ? 'phone_country_code' THEN v_row ->> 'phone_country_code' ELSE s.phone_country_code END,
      address            = CASE WHEN v_row ? 'address'            THEN v_row ->> 'address'            ELSE s.address END,
      city               = CASE WHEN v_row ? 'city'               THEN v_row ->> 'city'               ELSE s.city END,
      postal_code        = CASE WHEN v_row ? 'postal_code'        THEN v_row ->> 'postal_code'        ELSE s.postal_code END,
      country            = CASE WHEN v_row ? 'country'            THEN v_row ->> 'country'            ELSE s.country END,
      website            = CASE WHEN v_row ? 'website'            THEN v_row ->> 'website'            ELSE s.website END
    WHERE s.id = r.supplier_id;

    UPDATE public.supplier_account_links
       SET supplier_data_updated_at = now()
     WHERE id = r.link_id;

    v_count := v_count + 1;

    -- Sino do CRM: um aviso por pessoa e ficha (atualizado a cada gravação).
    BEGIN
      INSERT INTO public.notifications
        (user_id, organization_id, kind, type, title, message, link, entity_type, entity_id, priority, data)
      SELECT au.auth_user_id, r.organization_id, 'notification', 'supplier_data_updated',
             'Dados do fornecedor atualizados',
             format('O fornecedor %s atualizou os seus dados no portal (%s).',
                    COALESCE(v_row ->> 'name', r.sj ->> 'name'),
                    (SELECT string_agg(lower(v_labels ->> c), ', ') FROM unnest(v_changed) AS c)),
             '/suppliers?open=' || r.supplier_id::text || '&tab=portal',
             'supplier', r.supplier_id, 'low',
             jsonb_build_object('modulo', 'compras', 'supplier_id', r.supplier_id,
                                'changed_fields', to_jsonb(v_changed),
                                'portal_user_id', u.id)
      FROM (
        SELECT DISTINCT au0.auth_user_id
        FROM public.anew_memberships m
        JOIN public.anew_users au0 ON au0.id = m.user_id
        WHERE m.organization_id = r.organization_id
          AND m.status = 'active' AND m.role_is_client IS NOT TRUE
          AND au0.deleted_at IS NULL AND au0.auth_user_id IS NOT NULL
          AND EXISTS (SELECT 1 FROM public.anew_role_permissions rp
                      WHERE rp.role_id = m.role_id AND rp.permission_code = 'suppliers.edit')
      ) au
      ON CONFLICT (type, entity_id, user_id) WHERE is_resolved = false DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        title = EXCLUDED.title,
        message = EXCLUDED.message,
        link = EXCLUDED.link,
        data = EXCLUDED.data,
        priority = EXCLUDED.priority,
        is_read = false,
        read_at = NULL,
        is_dismissed = false,
        created_at = now();
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Aviso de dados do fornecedor atualizados não enviado: %', SQLERRM;
    END;
  END LOOP;

  -- 4.4 Confirmar (mesmo sem mudanças); mantém a 1.ª data de confirmação.
  UPDATE public.supplier_portal_users
     SET profile_confirmed_at = now(), updated_at = now()
   WHERE id = u.id AND profile_confirmed_at IS NULL;
  SELECT profile_confirmed_at INTO v_conf FROM public.supplier_portal_users WHERE id = u.id;

  RETURN jsonb_build_object('ok', true, 'updated_count', v_count, 'confirmed_at', v_conf);
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_update_my_supplier_data(p_data jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_update_my_supplier_data(p_data jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_update_my_supplier_data(p_data jsonb) TO service_role;
COMMENT ON FUNCTION public.sp_update_my_supplier_data(p_data jsonb) IS 'Portal do fornecedor: o owner confirma/edita os dados da empresa; atualiza todas as fichas suppliers ligadas (links ativos com acesso), marca supplier_data_updated_at, avisa no sino do CRM e marca profile_confirmed_at.';

CREATE OR REPLACE FUNCTION public.sp_whoami()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  u        public.supplier_portal_users;
  a        public.supplier_accounts;
  v_active boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('is_supplier', false);
  END IF;
  SELECT * INTO u FROM public.supplier_portal_users WHERE auth_user_id = v_uid;
  IF u.id IS NULL THEN
    RETURN jsonb_build_object('is_supplier', false);
  END IF;
  SELECT * INTO a FROM public.supplier_accounts WHERE id = u.supplier_account_id;

  v_active := u.status = 'active' AND a.status = 'active' AND EXISTS (
    SELECT 1
    FROM public.supplier_portal_user_access x
    JOIN public.supplier_account_links l ON l.id = x.link_id
    JOIN public.suppliers s ON s.id = l.supplier_id
    WHERE x.portal_user_id = u.id AND x.revoked_at IS NULL AND l.status = 'active' AND s.deleted_at IS NULL
  );

  IF v_active AND (u.last_login_at IS NULL OR u.last_login_at < now() - interval '10 minutes') THEN
    UPDATE public.supplier_portal_users SET last_login_at = now() WHERE id = u.id;
  END IF;

  RETURN jsonb_build_object(
    'is_supplier', true,
    'active', v_active,
    'first_login', u.password_changed_at IS NULL,
    -- Dados da empresa confirmados no primeiro acesso (members nunca bloqueados).
    'profile_confirmed', (u.profile_confirmed_at IS NOT NULL OR u.role <> 'owner'),
    'can_manage_catalog', v_active AND u.role = 'owner',
    -- Também cliente do portal do cliente (membership cliente ativa).
    'also_client', EXISTS (
      SELECT 1 FROM public.anew_users au
      JOIN public.anew_memberships m ON m.user_id = au.id AND m.status = 'active' AND m.role_is_client IS TRUE
      WHERE au.auth_user_id = v_uid AND au.status = 'active' AND au.deleted_at IS NULL),
    'user', jsonb_build_object('id', u.id, 'email', u.email, 'name', u.name, 'role', u.role,
                               'password_changed_at', u.password_changed_at),
    'account', CASE WHEN v_active THEN jsonb_build_object('id', a.id, 'display_name', a.display_name, 'nif_key', a.nif_key) END
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.sp_whoami() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sp_whoami() TO authenticated;
GRANT EXECUTE ON FUNCTION public.sp_whoami() TO service_role;

