DO $guarda_barcode$
DECLARE
  v_n integer;
BEGIN
  SELECT count(*) INTO v_n
  FROM (
    SELECT 1
    FROM public.products
    WHERE public.fn_product_code_key(barcode) IS NOT NULL
      AND deleted_at IS NULL
      AND NOT is_deleted
    GROUP BY organization_id, public.fn_product_code_key(barcode)
    HAVING count(*) > 1
  ) d;
  IF v_n > 0 THEN
    RAISE EXCEPTION 'juntar_estrutura: products tem % codigo(s) de barras repetido(s) na mesma organizacao; corrigir antes de criar uq_products_barcode_key', v_n;
  END IF;
END $guarda_barcode$;
CREATE UNIQUE INDEX IF NOT EXISTS uq_products_barcode_key ON public.products USING btree (organization_id, fn_product_code_key(barcode)) WHERE ((fn_product_code_key(barcode) IS NOT NULL) AND (deleted_at IS NULL) AND (NOT is_deleted));
