-- 8. Vista nova ------------------------------------------------------------
CREATE OR REPLACE VIEW public.fleet_v_vehicles WITH (security_invoker=true) AS
 SELECT v.id,
    v.organization_id,
    v.plate,
    v.make,
    v.model,
    v.vehicle_type,
    v.vehicle_category,
    v.first_registration_on,
    v.fuel_type,
    v.ownership,
    v.lessor_supplier_id,
    v.monthly_rent,
    v.model_year,
    v.odometer_km,
    v.odometer_read_on,
    v.status,
    v.status_reason,
    v.required_licence,
    v.cost_center_id,
    v.cost_center_label,
    v.personal_use,
    v.is_pool,
    v.schedule_resource_id,
    v.warehouse_id,
    v.asset_id,
    a.id AS current_assignment_id,
    a.kind AS current_assignment_kind,
    a.driver_id AS current_driver_id,
    d.full_name AS current_driver_name,
    ins.valid_until AS insurance_until,
    ins.reference AS insurance_policy_no,
    ins.provider_supplier_id AS insurer_supplier_id,
    ipo.valid_until AS inspection_until,
    iuc.valid_until AS road_tax_until,
    COALESCE(iuc.is_exempt, false) AS road_tax_exempt,
    lc.valid_until AS contract_ends_on,
    p.every_km AS service_every_km,
    p.every_months AS service_every_months,
    p.last_km AS service_last_km,
    p.last_done_on AS service_last_on,
    (p.last_km + p.every_km) AS service_next_km,
    ((p.last_done_on + make_interval(months => p.every_months)))::date AS service_next_on
   FROM (((((((fleet_vehicles v
     LEFT JOIN fleet_assignments a ON ((a.id = fn_fleet_assignment_at(v.id, CURRENT_DATE))))
     LEFT JOIN fleet_drivers d ON ((d.id = a.driver_id)))
     LEFT JOIN fleet_compliance ins ON (((ins.vehicle_id = v.id) AND (ins.kind = 'insurance'::text) AND ins.is_current)))
     LEFT JOIN fleet_compliance ipo ON (((ipo.vehicle_id = v.id) AND (ipo.kind = 'inspection'::text) AND ipo.is_current)))
     LEFT JOIN fleet_compliance iuc ON (((iuc.vehicle_id = v.id) AND (iuc.kind = 'road_tax'::text) AND iuc.is_current)))
     LEFT JOIN fleet_compliance lc ON (((lc.vehicle_id = v.id) AND (lc.kind = 'lease_contract'::text) AND lc.is_current)))
     LEFT JOIN fleet_maintenance_plans p ON (((p.vehicle_id = v.id) AND (p.kind = 'service'::text) AND p.is_active)))
  WHERE (v.deleted_at IS NULL);
REVOKE ALL ON TABLE public.fleet_v_vehicles FROM PUBLIC, anon, authenticated, service_role;
GRANT INSERT, SELECT, UPDATE, DELETE ON TABLE public.fleet_v_vehicles TO authenticated;
GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.fleet_v_vehicles TO service_role;

