DO $do$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'levantamento_linhas' AND policyname = 'levantamento_linhas_delete') THEN
    EXECUTE 'CREATE POLICY levantamento_linhas_delete ON public.levantamento_linhas AS PERMISSIVE FOR DELETE TO authenticated USING ((( SELECT has_anew_permission(( SELECT auth.uid() AS uid), ''pessoas.edit''::text) AS has_anew_permission) AND (organization_id IN ( SELECT get_user_crm_org_ids(( SELECT auth.uid() AS uid)) AS get_user_crm_org_ids)) AND (EXISTS ( SELECT 1
   FROM levantamentos l
  WHERE ((l.id = levantamento_linhas.levantamento_id) AND (EXISTS ( SELECT 1
           FROM unnest(( SELECT crm_scope_keys(''pessoas.edit''::text) AS crm_scope_keys)) k(scope_key)
          WHERE ((k.scope_key = ((l.organization_id)::text || '':*''::text)) OR (k.scope_key = (((l.organization_id)::text || '':''::text) || (l.feito_por)::text)) OR (k.scope_key = (((l.organization_id)::text || '':''::text) || (l.created_by)::text))))))))))';
  END IF;
