DO $do$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'levantamentos' AND policyname = 'levantamentos_insert') THEN
    EXECUTE 'CREATE POLICY levantamentos_insert ON public.levantamentos AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((( SELECT has_anew_permission(( SELECT auth.uid() AS uid), ''pessoas.create''::text) AS has_anew_permission) AND (organization_id IN ( SELECT get_user_crm_org_ids(( SELECT auth.uid() AS uid)) AS get_user_crm_org_ids)) AND (EXISTS ( SELECT 1
   FROM unnest(( SELECT crm_scope_keys(''pessoas.create''::text) AS crm_scope_keys)) k(scope_key)
  WHERE starts_with(k.scope_key, ((levantamentos.organization_id)::text || '':''::text)))) AND ((created_by IS NULL) OR (created_by = ( SELECT COALESCE(( SELECT au.id
           FROM anew_users au
          WHERE (au.auth_user_id = ( SELECT auth.uid() AS uid))
         LIMIT 1), current_business_user_id()) AS "coalesce"))) AND (EXISTS ( SELECT 1
   FROM anew_entity_org_links l
  WHERE ((l.entity_id = levantamentos.entity_id) AND (l.organization_id = levantamentos.organization_id)))) AND ((feito_por IS NULL) OR (EXISTS ( SELECT 1
   FROM anew_memberships m
  WHERE ((m.user_id = levantamentos.feito_por) AND (m.organization_id = levantamentos.organization_id) AND (m.status = ''active''::text) AND (m.role_is_client IS NOT TRUE))))) AND (negocio_id IS NULL)))';
  END IF;
