-- 12. Conferir: falha se faltar alguma peca --------------------------------
DO $conferir$
DECLARE
  v_falta text[];
BEGIN
  -- tabelas: 46 esperados
  SELECT array_agg(e ORDER BY e) INTO v_falta FROM unnest(ARRAY[
    'anew_address_building',
    'fleet_activity_log',
    'fleet_assignments',
    'fleet_compliance',
    'fleet_drivers',
    'fleet_expense_imports',
    'fleet_expenses',
    'fleet_incidents',
    'fleet_maintenance_events',
    'fleet_maintenance_plans',
    'fleet_odometer_readings',
    'fleet_ops_links',
    'fleet_restock_requests',
    'fleet_vehicles',
    'levantamento_linhas',
    'levantamento_opcoes',
    'levantamento_perguntas',
    'levantamento_questionario',
    'levantamento_respostas',
    'levantamento_seccoes',
    'levantamentos',
    'negocio_eventos',
    'negocio_workflow_config',
    'negocios',
    'ops_entrar_como_log',
    'ops_obra_aviso',
    'ops_obra_ritmo',
    'ops_obra_ritmo_historico',
    'ops_obra_servico_perfil',
    'ops_obra_tarefa_atraso',
    'ops_obra_tarefa_dependencia',
    'ops_obra_tarefa_foto',
    'product_codes',
    'receiving_scans',
    'supplier_account_links',
    'supplier_accounts',
    'supplier_catalog_dismissals',
    'supplier_catalog_imports',
    'supplier_catalog_items',
    'supplier_delivery_note_lines',
    'supplier_delivery_note_orders',
    'supplier_delivery_notes',
    'supplier_po_publications',
    'supplier_portal_user_access',
    'supplier_portal_users',
    'supplier_price_change_requests'
  ]::text[]) AS e
  WHERE e NOT IN (SELECT c.relname::text FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind::text = 'r' AND c.relrowsecurity);
  IF v_falta IS NOT NULL THEN
    RAISE EXCEPTION 'juntar_estrutura: faltam tabelas (%): %', cardinality(v_falta), array_to_string(v_falta, ', ');
  END IF;

  -- vistas: 1 esperados
  SELECT array_agg(e ORDER BY e) INTO v_falta FROM unnest(ARRAY[
    'fleet_v_vehicles'
  ]::text[]) AS e
  WHERE e NOT IN (SELECT c.relname::text FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind::text = 'v' AND coalesce(c.reloptions::text, '') LIKE '%security_invoker=true%');
  IF v_falta IS NOT NULL THEN
    RAISE EXCEPTION 'juntar_estrutura: faltam vistas (%): %', cardinality(v_falta), array_to_string(v_falta, ', ');
  END IF;

  -- colunas: 57 esperados
  SELECT array_agg(e ORDER BY e) INTO v_falta FROM unnest(ARRAY[
    'anew_leads.closure_result',
    'client_contracts.negocio_id',
    'deal_needs.diag_tipo_area',
