  ]::text[]) AS e
  WHERE e NOT IN (SELECT (tablename || '.' || policyname)::text FROM pg_policies WHERE schemaname = 'public');
  IF v_falta IS NOT NULL THEN
    RAISE EXCEPTION 'juntar_estrutura: faltam politicas (%): %', cardinality(v_falta), array_to_string(v_falta, ', ');
  END IF;

  -- funcoes novas executaveis por anon/PUBLIC: so as 0 que a principal permite
  SELECT array_agg(f ORDER BY f) INTO v_falta FROM (
    SELECT (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')')::text AS f, p.oid
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'
